def _paper_cohort_scope(cfg: dict | None) -> dict:
    """Return the explicit policy scope for the current Paper cohort.

    Older recovery-trial configs only stored a label.  Infer their strategy
    scope so a recovery trial cannot accidentally claim unrelated trades.
    """
    cfg = cfg or {}
    started_at = str(cfg.get("current_cohort_started_at") or "").strip() or None
    label = str(cfg.get("current_cohort_label") or "Current cohort").strip()
    strategy_keys = sorted({
        str(key).strip()
        for key in (cfg.get("current_cohort_strategy_keys") or [])
        if str(key).strip()
    })
    inferred = False
    if not strategy_keys and label.startswith("recovery_trial_"):
        suffix = label[len("recovery_trial_"):]
        match = re.match(r"(.+)_\d{4}-\d{2}-\d{2}$", suffix)
        if match and match.group(1):
            strategy_keys = [match.group(1)]
            inferred = True
    fingerprints = sorted({
        str(value).strip()
        for value in (cfg.get("current_cohort_policy_fingerprints") or [])
        if str(value).strip()
    })
    return {
        "label": label,
        "started_at": started_at,
        "strategy_keys": strategy_keys,
        "policy_fingerprints": fingerprints,
        "assignment_basis": "filled_at",
        "scope_inferred_from_legacy_label": inferred,
        "target_count": int(cfg.get("current_cohort_target_count") or 20),
    }


def _paper_trade_in_cohort(trade: dict, scope: dict) -> bool:
    """True only when a trade was assigned after start and matches policy scope."""
    started_at = str(scope.get("started_at") or "")
    if not started_at:
        return True
    assigned_at = (
        trade.get("filled_at")
        or trade.get("opened_at")
        or trade.get("queued_at")
        or trade.get("closed_at")  # legacy rows only; current schema always has lifecycle timestamps
        or ""
    )
    if str(assigned_at) < started_at:
        return False
    strategy_keys = set(scope.get("strategy_keys") or [])
    if strategy_keys and str(trade.get("strategy_key") or "") not in strategy_keys:
        return False
    fingerprints = set(scope.get("policy_fingerprints") or [])
    if fingerprints and str(trade.get("learning_policy_fingerprint") or "") not in fingerprints:
        return False
    return True

HARD_NOTIONAL_CAPS_BY_LIQUIDITY_TIER = {
    # Account-balance fractions. These are intentionally hardwired safety
    # rails, not user-tunable strategy parameters.
    "unknown": 0.05,
    "micro":   0.05,
    "thin":    0.10,
    "deep":    0.25,
}
HARD_NOTIONAL_CAP_LOW_HISTORY_COUNT = 50
HARD_NOTIONAL_CAP_LOW_HISTORY_FRACTION = 0.10
HARD_NOTIONAL_CAP_LOW_HISTORY_DEEP_FRACTION = 0.15
HARD_NOTIONAL_CAP_DEEP_VOLUME_USD = 10_000_000


def compute_paper_position_size(
    account_balance: float,
    risk_pct: float,
    entry_px: float,
    stop_loss: float | None,
    atr_pct: float | None,
    conviction: int,
) -> float:
    """Return derived paper trade notional from account risk and stop distance."""
    risk_amount = account_balance * risk_pct / 100

    if stop_loss and entry_px and entry_px > 0:
        stop_pct = abs(entry_px - stop_loss) / entry_px
    elif atr_pct and atr_pct > 0:
        stop_pct = atr_pct / 100
    else:
        stop_pct = 0.02

    stop_pct = max(stop_pct, 0.005)
    size = risk_amount / stop_pct

    if conviction >= 80:
        modifier = 1.0
    elif conviction >= 65:
        modifier = 0.8
    else:
        modifier = 0.6

    cap = account_balance * 0.25
    return round(min(size * modifier, cap), 2)


def _paper_symbol_history_counts() -> dict[str, int]:
    """Closed live+paper outcome count per symbol for hard notional caps."""
    counts: dict[str, int] = {}
    try:
        con = sqlite3.connect(DB_PATH)
        for symbol, n in con.execute("""
            SELECT symbol, COUNT(*)
            FROM signals
            WHERE result IN ('WIN','LOSS','PARTIAL','TP3')
              AND pnl_pct IS NOT NULL
            GROUP BY symbol
        """).fetchall():
            if symbol:
                counts[str(symbol)] = int(n or 0)
        for symbol, n in con.execute("""
            SELECT symbol, COUNT(*)
            FROM paper_trades
            WHERE status='closed'
              AND result IN ('WIN','LOSS','PARTIAL','TP3')
              AND pnl_pct IS NOT NULL
            GROUP BY symbol
        """).fetchall():
            if symbol:
                counts[str(symbol)] = max(counts.get(str(symbol), 0), int(n or 0))
        con.close()
    except Exception as e:
        print(f"[paper_sizing] symbol history count error: {e}", file=sys.stderr)
    return counts


def _hard_notional_cap_for_signal(
    account_balance: float,
    sig: dict,
    symbol_history_count: int | None = None,
) -> dict:
    """
    Hard paper notional cap by liquidity tier and available outcome history.

    This addresses the EV/PF paradox: percent EV can look positive while
    dollar-weighted PF fails if large notionals cluster in fragile symbols.
    """
    acct = max(0.0, float(account_balance or 0.0))
    tier = str(sig.get("liquidity_tier") or "unknown").strip().lower()
    if tier not in HARD_NOTIONAL_CAPS_BY_LIQUIDITY_TIER:
        tier = "unknown"
    history_count = int(symbol_history_count or 0)
    volume = float(sig.get("volume_24h") or 0.0)
    risk_score = float(sig.get("liquidity_risk_score") or 0.0)

    fractions = [HARD_NOTIONAL_CAPS_BY_LIQUIDITY_TIER[tier]]
    reasons = [f"liquidity_tier:{tier}"]

    if history_count < HARD_NOTIONAL_CAP_LOW_HISTORY_COUNT:
        if tier == "deep" and volume >= HARD_NOTIONAL_CAP_DEEP_VOLUME_USD:
            fractions.append(HARD_NOTIONAL_CAP_LOW_HISTORY_DEEP_FRACTION)
            reasons.append(f"low_symbol_history_deep:{history_count}")
        else:
            fractions.append(HARD_NOTIONAL_CAP_LOW_HISTORY_FRACTION)
            reasons.append(f"low_symbol_history:{history_count}")

    if risk_score >= 70:
        fractions.append(0.05)
        reasons.append(f"liquidity_risk_score:{risk_score:.0f}")
    elif risk_score >= 40:
        fractions.append(0.10)
        reasons.append(f"liquidity_risk_score:{risk_score:.0f}")

    cap_fraction = min(fractions) if fractions else 0.25
    return {
        "cap_usd": round(acct * cap_fraction, 2),
        "cap_fraction": cap_fraction,
        "tier": tier,
        "history_count": history_count,
        "reason": ",".join(reasons),
        "hardwired": True,
    }


def _apply_hard_notional_cap(raw_size_usd: float, cap: dict) -> dict:
    raw = max(0.0, float(raw_size_usd or 0.0))
    cap_usd = max(0.0, float(cap.get("cap_usd") or 0.0))
    final = min(raw, cap_usd) if cap_usd > 0 else raw
    return {
        "raw_size_usd": round(raw, 2),
        "size_usd": round(final, 2),
        "notional_cap_usd": round(cap_usd, 2) if cap_usd > 0 else None,
        "notional_cap_applied": bool(cap_usd > 0 and final < raw),
        "notional_cap_reason": cap.get("reason"),
        "liquidity_tier": cap.get("tier"),
        "symbol_history_count": cap.get("history_count"),
    }


