PAPER_READINESS_TRIM_FRACTION = 0.10
PAPER_READINESS_MAX_COHORT_DRAWDOWN_PCT = 20.0
PAPER_SIZING_MODES = {"fixed", "compound_realized"}


def _paper_notional_pnl_usd(
    size_usd: float | None,
    pnl_pct: float | None,
    leverage: float | None,
) -> float:
    """Convert leveraged return-on-margin percent to notional-dollar P&L."""
    lev = max(1.0, float(leverage or 1.0))
    return float(size_usd or 0.0) * float(pnl_pct or 0.0) / 100.0 / lev


def _paper_trade_pnl_usd(trade: dict, pnl_field: str = "pnl_pct") -> float:
    return _paper_notional_pnl_usd(
        trade.get("size_usd"),
        trade.get(pnl_field),
        trade.get("leverage"),
    )


def _load_goals() -> dict:
    try:
        with open(GOALS_PATH, encoding="utf-8") as f:
            stored = json.load(f)
        merged = copy.deepcopy(DEFAULT_GOALS)
        if isinstance(stored, dict):
            merged.update(stored)
            if isinstance(stored.get("scale_up_trigger"), dict):
                merged["scale_up_trigger"] = {
                    **DEFAULT_GOALS["scale_up_trigger"],
                    **stored["scale_up_trigger"],
                }
        return merged
    except Exception:
        return copy.deepcopy(DEFAULT_GOALS)


def _save_goals(goals: dict) -> None:
    os.makedirs("data", exist_ok=True)
    tmp = GOALS_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(goals, f, indent=2)
    os.replace(tmp, GOALS_PATH)


def _paper_equity_metrics(rows, starting_balance: float) -> dict:
    """Return fixed-dollar paper equity and peak-to-trough drawdown metrics."""
    balance = float(starting_balance or 0.0)
    peak = balance
    max_drawdown_pct = 0.0
    max_drawdown_usd = 0.0
    peak_at = None
    trough_at = None
    current_peak_at = None

    for row in rows:
        size_usd = float(row[0] or 0.0)
        pnl_pct = float(row[1] or 0.0)
        closed_at = row[2] if len(row) > 2 else None
        leverage = row[3] if len(row) > 3 else 1.0
        balance += _paper_notional_pnl_usd(size_usd, pnl_pct, leverage)

        if balance > peak:
            peak = balance
            current_peak_at = closed_at

        drawdown_usd = max(0.0, peak - balance)
        drawdown_pct = (drawdown_usd / peak * 100.0) if peak > 0 else 0.0
        if drawdown_pct > max_drawdown_pct:
            max_drawdown_pct = drawdown_pct
            max_drawdown_usd = drawdown_usd
            peak_at = current_peak_at
            trough_at = closed_at

    total_pnl_usd = balance - float(starting_balance or 0.0)
    current_drawdown_usd = max(0.0, peak - balance)
    current_drawdown_pct = (
        current_drawdown_usd / peak * 100.0 if peak > 0 else 0.0
    )
    return {
        "current_value_usd": round(balance, 2),
        "total_pnl_usd": round(total_pnl_usd, 2),
        "return_pct": round((total_pnl_usd / starting_balance) * 100.0, 2) if starting_balance else 0.0,
        "peak_value_usd": round(peak, 2),
        "current_drawdown_usd": round(current_drawdown_usd, 2),
        "current_drawdown_pct": round(current_drawdown_pct, 2),
        "max_drawdown_usd": round(max_drawdown_usd, 2),
        "max_drawdown_pct": round(max_drawdown_pct, 2),
        "drawdown_peak_at": peak_at,
        "drawdown_trough_at": trough_at,
    }


def _paper_closed_equity_rows() -> list[tuple] | None:
    """Return closed realized Paper P&L rows in deterministic equity order."""
    con = None
    try:
        con = sqlite3.connect(DB_PATH)
        cols = {
            row[1] for row in con.execute(
                "PRAGMA table_info(paper_trades)"
            ).fetchall()
        }
        leverage_expr = "leverage" if "leverage" in cols else "1"
        return con.execute(
            f"SELECT size_usd, pnl_pct, closed_at, {leverage_expr} "
            "FROM paper_trades "
            "WHERE status='closed' AND pnl_pct IS NOT NULL "
            "ORDER BY closed_at ASC, id ASC"
        ).fetchall()
    except Exception as e:
        print(f"[paper_sizing] realized equity unavailable: {e}", file=sys.stderr)
        return None
    finally:
        if con is not None:
            con.close()


def _paper_sizing_policy(
    cfg: dict | None = None,
    equity_rows: list[tuple] | None = None,
) -> dict:
    """
    Resolve the single sizing base used by Paper risk sizing and notional caps.

    Compound mode uses only closed realized Paper P&L. Open/unrealized P&L is
    never included. A breached equity floor blocks new entries; a current
    drawdown breach falls back to no more than the configured fixed base.
    """
    cfg = cfg or _load_paper_config()
    fixed_base = max(0.0, float(cfg.get("account_balance_usd", 200.0) or 0.0))
    mode = str(cfg.get("paper_sizing_mode") or "fixed").strip().lower()
    if mode not in PAPER_SIZING_MODES:
        mode = "fixed"

    floor_usd = max(
        0.0,
        float(cfg.get("compound_equity_floor_usd", 50.0) or 0.0),
    )
    configured_cap = float(
        cfg.get("compound_equity_cap_usd")
        or max(fixed_base * 5.0, floor_usd)
    )
    cap_usd = max(floor_usd, configured_cap)
    fallback_pct = min(
        100.0,
        max(
            0.0,
            float(cfg.get("compound_drawdown_fallback_pct", 20.0) or 0.0),
        ),
    )
    rows = equity_rows if equity_rows is not None else _paper_closed_equity_rows()
    equity_available = rows is not None
    rows = rows or []
    equity = _paper_equity_metrics(rows, fixed_base)
    realized_equity = float(equity.get("current_value_usd") or 0.0)
    current_drawdown_pct = float(equity.get("current_drawdown_pct") or 0.0)

    effective_base = fixed_base
    entry_allowed = fixed_base > 0
    state = "fixed_base"
    reason = "Fixed Base mode uses the configured Paper account balance."
    cap_applied = False
    drawdown_fallback_active = False

    if mode == "compound_realized":
        if not equity_available:
            effective_base = 0.0
            entry_allowed = False
            state = "equity_unavailable_block"
            reason = (
                "Closed realized Paper equity is unavailable; Compound mode "
                "fails closed and blocks new entries."
            )
        elif realized_equity < floor_usd:
            effective_base = 0.0
            entry_allowed = False
            state = "equity_floor_block"
            reason = (
                f"Realized Paper equity ${realized_equity:.2f} is below the "
                f"${floor_usd:.2f} operating floor; new entries are blocked."
            )
        elif fallback_pct > 0 and current_drawdown_pct >= fallback_pct:
            effective_base = min(realized_equity, fixed_base, cap_usd)
            entry_allowed = effective_base > 0
            state = "drawdown_fixed_fallback"
            drawdown_fallback_active = True
            reason = (
                f"Current realized-equity drawdown {current_drawdown_pct:.2f}% "
                f"reached the {fallback_pct:.2f}% fallback; sizing is limited "
                f"to the fixed ${fixed_base:.2f} base."
            )
        else:
            effective_base = min(realized_equity, cap_usd)
            entry_allowed = effective_base > 0
            cap_applied = realized_equity > cap_usd
            state = "compound_capped" if cap_applied else "compound_active"
            reason = (
                f"Using closed realized Paper equity, capped at ${cap_usd:.2f}."
                if cap_applied
                else "Using closed realized Paper equity as the sizing base."
            )

    risk_pct = max(0.0, float(cfg.get("risk_pct_per_trade", 5.0) or 0.0))
    max_positions = max(0, int(cfg.get("max_open_positions", 0) or 0))
    maximum_single_notional = effective_base * 0.25
    return {
        "mode": mode,
        "mode_label": (
            "Compound Realized Equity"
            if mode == "compound_realized" else "Fixed Base"
        ),
        "state": state,
        "entry_allowed": entry_allowed,
        "reason": reason,
        "fixed_base_usd": round(fixed_base, 2),
        "realized_equity_usd": round(realized_equity, 2),
        "realized_equity_available": equity_available,
        "realized_pnl_usd": round(realized_equity - fixed_base, 2),
        "eligible_equity_definition": (
            "configured fixed base plus P&L from closed Paper trades only; "
            "open and unrealized P&L are excluded"
        ),
        "effective_sizing_base_usd": round(effective_base, 2),
        "compound_equity_cap_usd": round(cap_usd, 2),
        "compound_equity_floor_usd": round(floor_usd, 2),
        "cap_applied": cap_applied,
        "current_drawdown_pct": round(current_drawdown_pct, 2),
        "drawdown_fallback_pct": round(fallback_pct, 2),
        "drawdown_fallback_active": drawdown_fallback_active,
        "risk_pct_per_trade": round(risk_pct, 4),
        "target_risk_budget_usd": round(effective_base * risk_pct / 100.0, 2),
        "maximum_single_notional_usd": round(maximum_single_notional, 2),
        "maximum_concurrent_notional_usd": round(
            maximum_single_notional * max_positions,
            2,
        ),
        "max_open_positions": max_positions,
        "loss_warning": (
            "Compounding accelerates losses as well as gains. The risk budget "
            "is a sizing target, not a guaranteed maximum realized loss."
        ),
        "equity": equity,
    }


def _paper_profit_factor(values: list[float]) -> float | None:
    gains = sum(value for value in values if value > 0)
    losses = abs(sum(value for value in values if value < 0))
    if losses > 0:
        return round(gains / losses, 2)
    if gains > 0:
        return 999.0
    return None


def _paper_evidence_stats(
    trades: list[dict],
    starting_balance: float = 200.0,
) -> dict:
    """Return chronological, net, outlier-resistant paper evidence."""
    valid = [trade for trade in trades if trade.get("pnl_pct") is not None]
    pnls = [float(trade.get("pnl_pct") or 0.0) for trade in valid]
    pnl_usd = [_paper_trade_pnl_usd(trade) for trade in valid]
    wins = sum(
        1 for trade in valid
        if str(trade.get("result") or "").upper() in {"WIN", "TP3"}
    )
    partials = sum(
        1 for trade in valid
        if str(trade.get("result") or "").upper() == "PARTIAL"
    )
    losses = sum(
        1 for trade in valid
        if str(trade.get("result") or "").upper() == "LOSS"
    )

    balance = float(starting_balance or 0.0)
    peak = balance
    max_drawdown_usd = 0.0
    max_drawdown_pct = 0.0
    for value in pnl_usd:
        balance += value
        peak = max(peak, balance)
        drawdown_usd = max(0.0, peak - balance)
        drawdown_pct = drawdown_usd / peak * 100.0 if peak > 0 else 0.0
        max_drawdown_usd = max(max_drawdown_usd, drawdown_usd)
        max_drawdown_pct = max(max_drawdown_pct, drawdown_pct)

    trim_each_tail = (
        int(math.floor(len(valid) * PAPER_READINESS_TRIM_FRACTION))
        if len(valid) >= 10 else 0
    )
    ranked = sorted(range(len(valid)), key=lambda index: pnls[index])
    retained = (
        ranked[trim_each_tail:len(ranked) - trim_each_tail]
        if trim_each_tail and len(ranked) > trim_each_tail * 2
        else ranked
    )
    trimmed_pnls = [pnls[index] for index in retained]
    trimmed_pnl_usd = [pnl_usd[index] for index in retained]

    best_index = (
        max(range(len(valid)), key=lambda index: pnl_usd[index])
        if valid else None
    )
    leave_best_pnls = [
        value for index, value in enumerate(pnls) if index != best_index
    ]
    leave_best_usd = [
        value for index, value in enumerate(pnl_usd) if index != best_index
    ]
    gross_gains_usd = sum(value for value in pnl_usd if value > 0)
    best_gain_usd = max([value for value in pnl_usd if value > 0], default=0.0)

    def window_stats(window: int) -> dict:
        window_trades = valid[-window:]
        window_pnls = [
            float(trade.get("pnl_pct") or 0.0)
            for trade in window_trades
        ]
        window_usd = [_paper_trade_pnl_usd(trade) for trade in window_trades]
        window_wp = sum(
            1 for trade in window_trades
            if str(trade.get("result") or "").upper()
            in {"WIN", "TP3", "PARTIAL"}
        )
        return {
            "window": window,
            "count": len(window_trades),
            "avg_pnl": (
                round(sum(window_pnls) / len(window_pnls), 2)
                if window_pnls else None
            ),
            "avg_pnl_usd": (
                round(sum(window_usd) / len(window_usd), 2)
                if window_usd else None
            ),
            "win_partial_rate": (
                round(window_wp / len(window_trades) * 100.0, 1)
                if window_trades else None
            ),
            "profit_factor": _paper_profit_factor(window_usd),
        }

    return {
        "count": len(valid),
        "wins": wins,
        "partials": partials,
        "losses": losses,
        "win_partial_rate": (
            round((wins + partials) / len(valid) * 100.0, 1)
            if valid else None
        ),
        "avg_pnl": round(sum(pnls) / len(pnls), 2) if pnls else None,
        "total_pnl": round(sum(pnls), 2),
        "avg_pnl_usd": (
            round(sum(pnl_usd) / len(pnl_usd), 2)
            if pnl_usd else None
        ),
        "total_pnl_usd": round(sum(pnl_usd), 2),
        "profit_factor": _paper_profit_factor(pnl_usd),
        "max_drawdown_usd": round(max_drawdown_usd, 2),
        "max_drawdown_pct": round(max_drawdown_pct, 2),
        "trim_fraction": PAPER_READINESS_TRIM_FRACTION,
        "trim_each_tail": trim_each_tail,
        "trimmed_count": len(trimmed_pnls),
        "trimmed_avg_pnl": (
            round(sum(trimmed_pnls) / len(trimmed_pnls), 2)
            if trimmed_pnls else None
        ),
        "trimmed_avg_pnl_usd": (
            round(sum(trimmed_pnl_usd) / len(trimmed_pnl_usd), 2)
            if trimmed_pnl_usd else None
        ),
        "leave_best_out_total_pnl": round(sum(leave_best_pnls), 2),
        "leave_best_out_total_pnl_usd": round(sum(leave_best_usd), 2),
        "top_winner_share_pct": (
            round(best_gain_usd / gross_gains_usd * 100.0, 1)
            if gross_gains_usd else None
        ),
        "rolling_windows": {
            str(window): window_stats(window)
            for window in PAPER_READINESS_RECENT_WINDOWS
        },
    }


def _paper_scale_stats(rows, starting_balance: float = 200.0) -> dict:
    """Return robust paper cohort stats used as hard scale-up gates."""
    trades = [
        {
            "result": row[0],
            "size_usd": row[1],
            "pnl_pct": row[2],
            "closed_at": row[3] if len(row) > 3 else None,
            "leverage": row[4] if len(row) > 4 else 1.0,
        }
        for row in rows
    ]
    stats = _paper_evidence_stats(trades, starting_balance)
    return {
        **stats,
        # Goal actuals historically expose this field as a 0..1 fraction.
        "win_partial_rate_fraction": (
            round(float(stats["win_partial_rate"]) / 100.0, 4)
            if stats.get("win_partial_rate") is not None else None
        ),
    }
def _load_suggestions_data() -> dict:
    try:
        with open(LEARNER_PENDING_PATH, encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            data.setdefault("suggestions", [])
            return data
    except Exception:
        pass
    return {"suggestions": []}


def _load_suggestions() -> list[dict]:
    return _load_suggestions_data().get("suggestions", [])


def _write_suggestions_data(data: dict) -> None:
    os.makedirs(os.path.dirname(LEARNER_PENDING_PATH) or ".", exist_ok=True)
    tmp = LEARNER_PENDING_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
    os.replace(tmp, LEARNER_PENDING_PATH)


def _write_rejected(entry: dict) -> None:
    try:
        existing = []
        if os.path.exists(LEARNER_REJECTED_PATH):
            with open(LEARNER_REJECTED_PATH, encoding="utf-8") as f:
                existing = json.load(f)
        if not isinstance(existing, list):
            existing = []
        existing.append(entry)
        os.makedirs(os.path.dirname(LEARNER_REJECTED_PATH) or ".", exist_ok=True)
        tmp = LEARNER_REJECTED_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(existing, f, indent=2)
        os.replace(tmp, LEARNER_REJECTED_PATH)
    except Exception as e:
        print(f"[suggestions] write_rejected error: {e}", file=sys.stderr)


def _update_suggestion_status(sid: str, status: str, extra: dict | None = None) -> bool:
    try:
        data = _load_suggestions_data()
        for suggestion in data.get("suggestions", []):
            if suggestion.get("id") == sid:
                suggestion["status"] = status
                if extra:
                    suggestion.update(extra)
                _write_suggestions_data(data)
                return True
    except Exception as e:
        print(f"[suggestions] update_status error: {e}", file=sys.stderr)
    return False


def _learner_running() -> bool:
    if not os.path.exists(LEARNER_HEARTBEAT_PATH):
        return False
    try:
        mtime = os.path.getmtime(LEARNER_HEARTBEAT_PATH)
        return (datetime.utcnow().timestamp() - mtime) < 600
    except Exception:
        return False


def _file_age_seconds(path: str) -> int | None:
    try:
        if not path or not os.path.exists(path):
            return None
        return max(0, int(time.time() - os.path.getmtime(path)))
    except Exception:
        return None


def _file_mtime_iso(path: str) -> str | None:
    try:
        if not path or not os.path.exists(path):
            return None
        return datetime.fromtimestamp(os.path.getmtime(path), timezone.utc).isoformat()
    except Exception:
        return None


def _git_commit_short() -> str | None:
    env_commit = os.getenv("MT7_GIT_COMMIT") or os.getenv("APP_GIT_COMMIT")
    if env_commit:
        return str(env_commit)[:12]
    try:
        out = subprocess.check_output(
            ["git", "rev-parse", "--short=12", "HEAD"],
            cwd=os.path.dirname(os.path.abspath(__file__)) or ".",
            stderr=subprocess.DEVNULL,
            timeout=2,
        )
        return out.decode("utf-8", "ignore").strip() or None
    except Exception:
        return None


def _app_file_sha() -> str | None:
    try:
        with open(__file__, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()[:12]
    except Exception:
        return None


def _ops_check(name: str, status: str, detail: str, value=None, action: str = "") -> dict:
    color = {"pass": "green", "warn": "amber", "fail": "red", "info": "blue"}.get(status, "blue")
    return {"name": name, "status": status, "color": color, "detail": detail, "value": value, "action": action}


def _suggestion_baseline_snapshot() -> dict:
    goals = _load_goals()
    actuals = _compute_goal_actuals(goals)
    return {
        "ev_per_trade_pct":  actuals.get("ev_per_trade_pct"),
        "paper_ev_per_trade_pct": actuals.get("paper_ev_per_trade_pct"),
        "win_partial_rate":  actuals.get("win_partial_rate"),
        "ev_sample_n":       actuals.get("ev_sample_n"),
        "current_value_usd": actuals.get("current_value_usd"),
        "snapshot_at":       datetime.utcnow().isoformat(),
    }


def _compute_goal_actuals(goals: dict) -> dict:
    """Compute paper account and live-signal goal metrics from signals.db."""
    account_balance = float(goals.get("account_balance_usd", 200.0) or 200.0)
    now = datetime.utcnow()
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0).isoformat()
    thirty_days_ago = (now - timedelta(days=30)).isoformat()

    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row

        rows = con.execute(
            "SELECT size_usd, pnl_pct, closed_at, leverage FROM paper_trades "
            "WHERE status='closed' AND pnl_pct IS NOT NULL "
            "ORDER BY closed_at ASC, id ASC"
        ).fetchall()
        equity = _paper_equity_metrics(rows, account_balance)
        total_pnl_usd = float(equity.get("total_pnl_usd") or 0.0)
        current_value = float(equity.get("current_value_usd") or account_balance)
        return_pct = float(equity.get("return_pct") or 0.0)
        drawdown_pct = float(equity.get("max_drawdown_pct") or 0.0)

        month_rows = con.execute(
            "SELECT size_usd, pnl_pct, leverage FROM paper_trades "
            "WHERE status='closed' AND closed_at >= ? AND pnl_pct IS NOT NULL",
            (month_start,),
        ).fetchall()
        month_pnl_usd = sum(
            _paper_notional_pnl_usd(r[0], r[1], r[2])
            for r in month_rows
        )
        monthly_return_pct = round((month_pnl_usd / account_balance) * 100, 2) if account_balance else 0

        ev_rows = con.execute(
            "SELECT pnl_pct FROM signals WHERE COALESCE(source, 'live')='live' "
            "AND result IN ('WIN','LOSS','PARTIAL') "
            "AND pnl_pct IS NOT NULL AND logged_at >= ?",
            (thirty_days_ago,),
        ).fetchall()
        ev_values = [r[0] for r in ev_rows]
        ev_per_trade = round(sum(ev_values) / len(ev_values), 2) if ev_values else None
        ev_sample_n = len(ev_values)

        paper_ev_rows = con.execute(
            "SELECT pnl_pct FROM signals WHERE source='paper' "
            "AND result IN ('WIN','LOSS','PARTIAL') "
            "AND pnl_pct IS NOT NULL AND logged_at >= ?",
            (thirty_days_ago,),
        ).fetchall()
        paper_ev_values = [r[0] for r in paper_ev_rows]
        paper_ev_per_trade = round(sum(paper_ev_values) / len(paper_ev_values), 2) if paper_ev_values else None

        wr_rows = con.execute(
            "SELECT result FROM signals WHERE COALESCE(source, 'live')='live' "
            "AND result IN ('WIN','LOSS','PARTIAL') AND logged_at >= ?",
            (thirty_days_ago,),
        ).fetchall()
        wr_results = [r[0] for r in wr_rows]
        win_partial = sum(1 for r in wr_results if r in ("WIN", "PARTIAL"))
        win_partial_rate = round(win_partial / len(wr_results), 4) if wr_results else None

        streak_rows = con.execute(
            "SELECT result FROM signals WHERE COALESCE(source, 'live')='live' "
            "AND result IN ('WIN','LOSS','PARTIAL') "
            "ORDER BY logged_at DESC LIMIT 20"
        ).fetchall()
        streak = 0
        for r in streak_rows:
            if r[0] == "LOSS":
                streak += 1
            else:
                break

        cfg = _load_paper_config()
        cohort_scope = _paper_cohort_scope(cfg)
        cohort_candidates = [
            dict(row) for row in con.execute(
                "SELECT result, size_usd, pnl_pct, closed_at, strategy_key, "
                "queued_at, filled_at, opened_at, learning_policy_fingerprint "
                ", leverage "
                "FROM paper_trades WHERE status='closed' AND result IS NOT NULL "
                "AND pnl_pct IS NOT NULL ORDER BY closed_at ASC, id ASC"
            ).fetchall()
        ]
        cohort_rows = [
            (
                row.get("result"),
                row.get("size_usd"),
                row.get("pnl_pct"),
                row.get("closed_at"),
                row.get("leverage"),
            )
            for row in cohort_candidates
            if _paper_trade_in_cohort(row, cohort_scope)
        ]
        paper_scale = _paper_scale_stats(cohort_rows, account_balance)

        con.close()

        safety = _paper_safety_controls(cfg)
        active_safety_controls = list(safety.get("reasons") or [])

        scale_trigger = goals.get("scale_up_trigger", {})
        max_drawdown_pct = abs(float(goals.get("max_drawdown_pct", 40.0)))
        ev_threshold = float(scale_trigger.get("ev_threshold_pct", 8.0))
        min_trades = int(scale_trigger.get("min_trades", 50))
        cohort_min_trades = max(
            PAPER_READINESS_MIN_TRADES,
            int(goals.get("evaluation_window_trades", 20)),
        )
        cohort_wp_floor = PAPER_READINESS_WP_FLOOR_PCT
        cohort_pf_floor = PAPER_READINESS_PF_FLOOR
        cohort_drawdown_limit = min(
            max_drawdown_pct,
            PAPER_READINESS_MAX_COHORT_DRAWDOWN_PCT,
        )
        scale_blockers = []

        if ev_per_trade is None or ev_per_trade < ev_threshold:
            scale_blockers.append(f"live EV below {ev_threshold:.1f}%")
        if ev_sample_n < min_trades:
            scale_blockers.append(f"live EV sample below {min_trades} trades")
        if drawdown_pct >= max_drawdown_pct:
            scale_blockers.append(f"drawdown {drawdown_pct:.1f}% >= {max_drawdown_pct:.1f}% limit")
        if active_safety_controls:
            scale_blockers.append("active paper safety control")
        if paper_scale["count"] < cohort_min_trades:
            scale_blockers.append(f"paper cohort below {cohort_min_trades} trades")
        if (
            paper_scale["win_partial_rate"] is None
            or paper_scale["win_partial_rate"] < cohort_wp_floor
        ):
            scale_blockers.append(
                f"paper cohort W+P below {cohort_wp_floor:.0f}%"
            )
        if paper_scale["profit_factor"] is None or paper_scale["profit_factor"] < cohort_pf_floor:
            scale_blockers.append(f"paper cohort PF below {cohort_pf_floor:.2f}")
        if (
            paper_scale.get("avg_pnl") is None
            or float(paper_scale["avg_pnl"]) <= 0
            or paper_scale.get("avg_pnl_usd") is None
            or float(paper_scale["avg_pnl_usd"]) <= 0
        ):
            scale_blockers.append("paper cohort net EV is not positive")
        if (
            paper_scale.get("trimmed_avg_pnl") is None
            or float(paper_scale["trimmed_avg_pnl"]) <= 0
            or float(paper_scale.get("leave_best_out_total_pnl_usd") or 0) <= 0
        ):
            scale_blockers.append("paper cohort edge depends on outliers")
        if float(paper_scale.get("max_drawdown_pct") or 0) > cohort_drawdown_limit:
            scale_blockers.append(
                f"paper cohort drawdown above {cohort_drawdown_limit:.1f}%"
            )
        rolling_unstable = []
        for window in PAPER_READINESS_RECENT_WINDOWS:
            recent = (paper_scale.get("rolling_windows") or {}).get(str(window)) or {}
            if (
                int(recent.get("count") or 0) < window
                or float(recent.get("avg_pnl") or 0) <= 0
                or float(recent.get("profit_factor") or 0) < PAPER_READINESS_RECENT_PF_FLOOR
                or float(recent.get("win_partial_rate") or 0)
                < PAPER_READINESS_RECENT_WP_FLOOR_PCT
            ):
                rolling_unstable.append(window)
        if rolling_unstable:
            scale_blockers.append(
                "paper recent-window stability missing "
                + "/".join(str(window) for window in rolling_unstable)
            )

        scale_ready = not scale_blockers
        return {
            "current_value_usd":    current_value,
            "total_pnl_usd":        round(total_pnl_usd, 2),
            "return_pct":           return_pct,
            "monthly_return_pct":   monthly_return_pct,
            "month_pnl_usd":        round(month_pnl_usd, 2),
            "ev_per_trade_pct":     ev_per_trade,
            "ev_sample_n":          ev_sample_n,
            "paper_ev_per_trade_pct": paper_ev_per_trade,
            "paper_ev_sample_n":    len(paper_ev_values),
            "win_partial_rate":     win_partial_rate,
            "win_partial_sample_n": len(wr_results),
            "drawdown_pct":         drawdown_pct,
            "max_drawdown_pct":     drawdown_pct,
            "max_drawdown_usd":     equity.get("max_drawdown_usd"),
            "peak_value_usd":       equity.get("peak_value_usd"),
            "drawdown_peak_at":     equity.get("drawdown_peak_at"),
            "drawdown_trough_at":   equity.get("drawdown_trough_at"),
            "consecutive_losses":   streak,
            "scale_up_ready":       scale_ready,
            "scale_up_blockers":     scale_blockers,
            "active_safety_controls": active_safety_controls,
            "paper_cohort_sample_n": paper_scale["count"],
            "paper_cohort_win_partial_rate": paper_scale["win_partial_rate"],
            "paper_cohort_profit_factor": paper_scale["profit_factor"],
            "paper_cohort_avg_pnl": paper_scale.get("avg_pnl"),
            "paper_cohort_avg_pnl_usd": paper_scale.get("avg_pnl_usd"),
            "paper_cohort_trimmed_avg_pnl": paper_scale.get("trimmed_avg_pnl"),
            "paper_cohort_leave_best_out_total_pnl_usd": paper_scale.get(
                "leave_best_out_total_pnl_usd"
            ),
            "paper_cohort_max_drawdown_pct": paper_scale.get("max_drawdown_pct"),
            "paper_cohort_max_drawdown_usd": paper_scale.get("max_drawdown_usd"),
            "paper_cohort_top_winner_share_pct": paper_scale.get(
                "top_winner_share_pct"
            ),
            "paper_cohort_rolling_windows": paper_scale.get("rolling_windows") or {},
            "paper_cohort_readiness_target": cohort_min_trades,
            "paper_cohort_drawdown_limit_pct": cohort_drawdown_limit,
            "paper_cohort_scope": cohort_scope,
            "kill_switch_breached": drawdown_pct >= max_drawdown_pct,
        }
    except Exception as e:
        print(f"[goals] compute error: {e}", file=sys.stderr)
        return {}


def _version_payload() -> dict:
    return {
        "app": "Matrix Trader 7.0",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "git_commit": _git_commit_short(),
        "app_sha": _app_file_sha(),
        "score_version": SCORE_VERSION,
        "python": sys.version.split()[0],
        "host": socket.gethostname(),
        "paths": {
            "db": DB_PATH,
            "paper_config": PAPER_CONFIG_PATH,
            "learner_pending": LEARNER_PENDING_PATH,
            "learner_heartbeat": LEARNER_HEARTBEAT_PATH,
            "research_memo": HERMES_RESEARCH_MEMO_PATH,
            "edge_lab_db": EDGE_LAB_DB_PATH,
            "edge_lab_report": EDGE_LAB_REPORT_PATH,
        },
        "files": {
            "app_mtime": _file_mtime_iso(__file__),
            "db_mtime": _file_mtime_iso(DB_PATH),
            "paper_config_mtime": _file_mtime_iso(PAPER_CONFIG_PATH),
            "research_memo_mtime": _file_mtime_iso(HERMES_RESEARCH_MEMO_PATH),
        },
    }


def _edge_lab_cohort_coverage_fast() -> dict:
    try:
        cfg = _load_paper_config()
        scope = _paper_cohort_scope(cfg)
        since = scope.get("started_at")
        if not since:
            return {"available": os.path.exists(EDGE_LAB_DB_PATH), "coverage_pct": None, "matched": 0, "total": 0, "note": "No cohort start configured."}
        if not os.path.exists(EDGE_LAB_DB_PATH):
            return {"available": False, "coverage_pct": None, "matched": 0, "total": 0, "note": "edge_lab.db missing."}
        sig_con = sqlite3.connect(DB_PATH)
        sig_con.row_factory = sqlite3.Row
        candidates = [dict(r) for r in sig_con.execute("""
            SELECT symbol, strategy_key, filled_at, opened_at, queued_at, closed_at,
                   learning_policy_fingerprint
            FROM paper_trades
            WHERE status='closed'
            ORDER BY COALESCE(closed_at, opened_at, queued_at) DESC
            LIMIT 1000
        """).fetchall()]
        trades = [row for row in candidates if _paper_trade_in_cohort(row, scope)][:160]
        sig_con.close()
        edge_con = sqlite3.connect(EDGE_LAB_DB_PATH)
        edge_con.row_factory = sqlite3.Row
        _ensure_edge_lab_indexes(edge_con)
        matched = 0
        reasons = defaultdict(int)
        max_age_seconds = 30 * 60
        for trade in trades:
            trade_ts = _parse_iso_to_epoch(trade.get("filled_at") or trade.get("opened_at") or trade.get("queued_at") or trade.get("closed_at"))
            match = _edge_feature_match(
                edge_con,
                str(trade.get("symbol") or "").upper(),
                trade_ts,
                max_age_seconds,
            )
            reasons[match["coverage_reason"]] += 1
            if match["matched"]:
                matched += 1
        edge_con.close()
        total = len(trades)
        return {
            "available": True,
            "coverage_pct": round(matched / total * 100, 1) if total else None,
            "matched": matched,
            "total": total,
            "coverage_reasons": dict(sorted(reasons.items())),
            "feature_source": "candle_feature_snapshots",
            "measurement_state": "measured" if total else "collecting",
            "measurement_window_start": str(since),
            "cohort_scope": scope,
            "note": (
                "Share of closed trades in the current Paper cohort with a usable "
                "pre-entry Edge Lab snapshot."
                if total
                else "The current Paper cohort has no closed trades to measure yet."
            ),
        }
    except Exception as e:
        return {"available": os.path.exists(EDGE_LAB_DB_PATH), "coverage_pct": None, "matched": 0, "total": 0, "error": str(e)}


_ops_edge_coverage_cache_lock = threading.Lock()
_ops_edge_coverage_cache: dict = {
    "built_at": 0.0,
    "packet": None,
    "refreshing": False,
}
OPS_EDGE_COVERAGE_CACHE_SECONDS = 15 * 60


def _refresh_ops_edge_coverage() -> None:
    try:
        packet = _edge_lab_cohort_coverage_fast()
    except Exception as exc:
        packet = {
            "available": os.path.exists(EDGE_LAB_DB_PATH),
            "coverage_pct": None,
            "matched": 0,
            "total": 0,
            "error": str(exc),
        }
    with _ops_edge_coverage_cache_lock:
        _ops_edge_coverage_cache.update({
            "built_at": time.time(),
            "packet": packet,
            "refreshing": False,
        })


def _edge_lab_cohort_coverage_cached() -> dict:
    """Return Edge coverage without blocking the Watchdog first paint.

    The Edge Lab database is large enough that opening it and matching the
    current cohort can take several seconds under scan load. A daemon refresh
    keeps that work off the request thread; callers receive the last completed
    packet or an explicit warming state.
    """
    now = time.time()
    with _ops_edge_coverage_cache_lock:
        packet = _ops_edge_coverage_cache.get("packet")
        age = max(0.0, now - float(_ops_edge_coverage_cache.get("built_at") or 0.0))
        refreshing = bool(_ops_edge_coverage_cache.get("refreshing"))
        if packet is not None and age < OPS_EDGE_COVERAGE_CACHE_SECONDS:
            cached = copy.deepcopy(packet)
            cached["cache_age_seconds"] = round(age, 1)
            cached["refreshing"] = refreshing
            return cached
        if not refreshing:
            _ops_edge_coverage_cache["refreshing"] = True
            threading.Thread(
                target=_refresh_ops_edge_coverage,
                name="mt7-ops-edge-coverage",
                daemon=True,
            ).start()
        if packet is not None:
            stale = copy.deepcopy(packet)
            stale["cache_age_seconds"] = round(age, 1)
            stale["refreshing"] = True
            stale["stale"] = True
            return stale
    return {
        "available": os.path.exists(EDGE_LAB_DB_PATH),
        "coverage_pct": None,
        "matched": 0,
        "total": 0,
        "refreshing": True,
        "note": "Edge Lab cohort coverage is warming in the background.",
    }


def _ops_watchdog_payload() -> dict:
    version = _version_payload()
    actuals = _compute_goal_actuals(_load_goals())
    suggestions = _annotate_suggestion_authority(_load_suggestions())
    active_suggestions = [s for s in suggestions if s.get("status") in {"pending", "pending_review", "evaluating", "shadow_evaluating"}]
    applied_evaluating = [s for s in active_suggestions if s.get("status") == "evaluating"]
    parallel_shadow = [
        s for s in active_suggestions
        if s.get("status") in {"pending", "pending_review", "shadow_evaluating"}
        and not s.get("state_conflict")
    ]
    authority_conflicts = [s for s in suggestions if s.get("state_conflict")]
    learner_age = _file_age_seconds(LEARNER_HEARTBEAT_PATH)
    memo_age = _file_age_seconds(HERMES_RESEARCH_MEMO_PATH)
    db_age = _file_age_seconds(DB_PATH)
    edge_coverage = _edge_lab_cohort_coverage_cached()
    checks: list[dict] = []

    checks.append(_ops_check(
        "App Fingerprint",
        "pass" if version.get("app_sha") else "warn",
        "Running app exposes a stable file hash and optional git commit.",
        version.get("git_commit") or version.get("app_sha"),
        "Set MT7_GIT_COMMIT during deploy for stronger commit verification." if not version.get("git_commit") else "",
    ))
    checks.append(_ops_check(
        "Account Schema",
        "pass" if actuals.get("max_drawdown_usd") is not None and actuals.get("return_pct") is not None and actuals.get("scale_up_blockers") is not None else "fail",
        "Paper account includes true drawdown, return, and scale-up blocker fields.",
        f"DD {actuals.get('drawdown_pct')}%",
        "Redeploy app.py if this fails.",
    ))
    if learner_age is None:
        checks.append(_ops_check("mt-learner Heartbeat", "fail", "Learner heartbeat file is missing.", "missing", "Restart mt-learner and verify paths."))
    else:
        checks.append(_ops_check(
            "mt-learner Heartbeat",
            "pass" if learner_age < 600 else "fail" if learner_age > 1800 else "warn",
            "Fresh heartbeat means the suggestion loop is alive.",
            f"{round(learner_age / 60, 1)}m old",
            "Restart mt-learner if stale.",
        ))
    applied_by_strategy: dict[str, list[dict]] = defaultdict(list)
    for suggestion in applied_evaluating:
        applied_by_strategy[str(suggestion.get("strategy") or "unknown")].append(
            suggestion
        )
    duplicate_applied_strategies = sorted(
        strategy for strategy, items in applied_by_strategy.items()
        if len(items) > 1
    )
    experiment_meta: dict[str, dict] = {}
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        experiment_ids = [
            str(s.get("learning_experiment_id") or "")
            for s in applied_evaluating
            if s.get("learning_experiment_id")
        ]
        for experiment_id in experiment_ids:
            row = con.execute(
                """SELECT activated_at, evidence_rules_json, result_json,
                          blocked_reason
                   FROM learning_experiments WHERE experiment_id=?""",
                (experiment_id,),
            ).fetchone()
            if row:
                experiment_meta[experiment_id] = dict(row)
        con.close()
    except (sqlite3.Error, OSError):
        experiment_meta = {}

    stuck = []
    for s in active_suggestions:
        if s.get("status") != "evaluating":
            continue
        meta = experiment_meta.get(str(s.get("learning_experiment_id") or "")) or {}
        rules = _learning_json(meta.get("evidence_rules_json"), {})
        result = _learning_json(meta.get("result_json"), {})
        treatment = result.get("treatment") or {}
        closed = int(treatment.get("count") or 0)
        minimum_days = max(1, int(rules.get("minimum_elapsed_days") or 7))
        activated_epoch = _parse_iso_to_epoch(meta.get("activated_at"))
        age_days = (
            (time.time() - activated_epoch) / 86400.0
            if activated_epoch else 0.0
        )
        # Immature collection is normal. Flag only an explicit blockage or a
        # lane that has produced no exact-policy close after twice its minimum
        # duration.
        if meta.get("blocked_reason") or (
            age_days >= minimum_days * 2 and closed == 0
        ):
            stuck.append(s.get("id") or "unknown")
    checks.append(_ops_check(
        "Learner Queue",
        "fail" if authority_conflicts or duplicate_applied_strategies
        else "warn" if stuck else "pass",
        "Shadow studies run concurrently; applied trials are serial within a strategy and parallel across independent strategies.",
        (
            f"{len(parallel_shadow)} shadow / "
            f"{len(applied_by_strategy)} applied strategy lanes"
            + (f" / {len(authority_conflicts)} authority conflict" if authority_conflicts else "")
            + (
                f" / duplicate {', '.join(duplicate_applied_strategies)}"
                if duplicate_applied_strategies else ""
            )
        ),
        (
            "Reconcile suggestion status with active strategy overrides."
            if authority_conflicts
            else "Keep only one applied evaluator per affected strategy."
            if duplicate_applied_strategies
            else "Review the applied evaluator: it has no exact-policy closes after its grace period."
            if stuck else ""
        ),
    ))
    checks.append(_ops_check(
        "Research Memo",
        "fail" if memo_age is None else "warn" if memo_age > 7 * 86400 else "pass",
        "Hermes research memo should be recent enough to reflect current sources.",
        "missing" if memo_age is None else f"{round(memo_age / 3600, 1)}h old",
        "Generate a Research Memo from Intelligence > Hermes." if memo_age is None or memo_age > 7 * 86400 else "",
    ))
    checks.append(_ops_check(
        "Signals DB Freshness",
        "warn" if db_age is None or db_age > 3600 else "pass",
        "signals.db should update as scanners, paper trades, or evaluations run.",
        "missing" if db_age is None else f"{round(db_age / 60, 1)}m old",
    ))
    edge_total = int(edge_coverage.get("total") or 0)
    edge_matched = int(edge_coverage.get("matched") or 0)
    edge_status = "pass" if edge_coverage.get("coverage_pct") is not None and edge_coverage.get("coverage_pct") >= 60 else "warn"
    if edge_total == 0 and edge_coverage.get("available"):
        edge_status = "info"
    elif edge_coverage.get("refreshing") and edge_coverage.get("coverage_pct") is None:
        edge_status = "info"
    elif not edge_coverage.get("available"):
        edge_status = "fail"
    checks.append(_ops_check(
        "Current Paper Cohort Edge Coverage",
        edge_status,
        "Share of current-cohort closed trades with a usable pre-entry Edge Lab snapshot.",
        (
            f"{edge_coverage.get('coverage_pct')}% · {edge_matched}/{edge_total}"
            if edge_coverage.get("coverage_pct") is not None
            else f"collecting · {edge_matched}/{edge_total}"
            if edge_total == 0 and edge_coverage.get("available")
            else "unavailable"
        ),
        (
            "Let the current Paper cohort close trades before judging forward coverage."
            if edge_status == "info" and edge_total == 0
            else "Coverage is warming in the background; refresh shortly."
            if edge_status == "info"
            else "Add cohort symbols to Edge Lab ingestion before using attribution."
            if edge_status != "pass"
            else ""
        ),
    ))
    checks.append(_ops_check(
        "Assisted-Live Readiness",
        "pass" if actuals.get("scale_up_ready") and not actuals.get("active_safety_controls") else "warn",
        "Readiness for design review only; silent live trading remains disabled by safety rules.",
        "ready" if actuals.get("scale_up_ready") else "blocked",
        "; ".join(actuals.get("scale_up_blockers") or [])[:180],
    ))

    fail_count = len([c for c in checks if c["status"] == "fail"])
    warn_count = len([c for c in checks if c["status"] == "warn"])
    posture = "blocked" if fail_count else "review" if warn_count else "healthy"
    return {
        "success": True,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "posture": posture,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "version": version,
        "checks": checks,
        "learner": {
            "running": _learner_running(),
            "heartbeat_age_seconds": learner_age,
            "active_count": len(active_suggestions),
            "active_ids": [str(s.get("id") or "unknown") for s in active_suggestions[:6]],
            "stuck_ids": stuck[:6],
        },
        "research": {
            "memo_path": HERMES_RESEARCH_MEMO_PATH,
            "memo_age_seconds": memo_age,
            "source_count": ((_hermes_research_pipeline_summary().get("library") or {}).get("source_count") or 0),
        },
        "edge_lab": edge_coverage,
        "paper": {
            "scale_up_ready": actuals.get("scale_up_ready"),
            "scale_up_blockers": actuals.get("scale_up_blockers") or [],
            "drawdown_pct": actuals.get("drawdown_pct"),
            "max_drawdown_usd": actuals.get("max_drawdown_usd"),
            "return_pct": actuals.get("return_pct"),
        },
    }


@app.route("/api/version")
def api_version():
    return jsonify({"success": True, **_version_payload()})


@app.route("/api/ops/watchdog")
def api_ops_watchdog():
    try:
        return jsonify(_ops_watchdog_payload())
    except Exception as e:
        print(f"[api/ops/watchdog] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


