    if not con.execute("SELECT 1 FROM ticker_daily_snapshots LIMIT 1").fetchone():
        # One-time migration: preserve the final hourly observation for each
        # available day without carrying the full hourly table for months.
        con.execute("""
            INSERT OR REPLACE INTO ticker_daily_snapshots
                (day,ts,symbol,exchange,price,volume_24h,funding_rate,change_24h_pct,open_interest)
            SELECT latest.day, snap.ts, snap.symbol, snap.exchange, snap.price,
                   snap.volume_24h, snap.funding_rate, snap.change_24h_pct, snap.open_interest
            FROM ticker_snapshots AS snap
            JOIN (
                SELECT substr(ts,1,10) AS day, exchange, symbol, MAX(ts) AS ts
                FROM ticker_snapshots
                GROUP BY substr(ts,1,10), exchange, symbol
            ) AS latest
              ON latest.ts=snap.ts
             AND latest.exchange=snap.exchange
             AND latest.symbol=snap.symbol
        """)
