def _snapshot_tickers() -> int:
    """Persist hourly MEXC state plus an efficient 90-day daily close."""
    try:
        tickers = fetch_mexc("/contract/ticker")
        if not tickers or not isinstance(tickers, list):
            return 0
        ts = datetime.utcnow().isoformat()
        rows = []
        for t in tickers:
            symbol = t.get("symbol", "")
            if not symbol:
                continue
            price  = float(t.get("lastPrice") or t.get("fairPrice") or 0)
            volume = float(t.get("volume24") or t.get("vol24h") or t.get("amount24") or 0)
            funding = float(t.get("fundingRate") or 0)
            change  = float(t.get("riseFallRate") or 0) * 100
            oi      = float(t.get("holdVol") or 0)
            rows.append((ts, symbol, "MEXC", price, volume, funding, change, oi))
        con = sqlite3.connect(DB_PATH)
        con.executemany(
            "INSERT INTO ticker_snapshots (ts,symbol,exchange,price,volume_24h,funding_rate,change_24h_pct,open_interest) VALUES (?,?,?,?,?,?,?,?)",
            rows,
        )
        day = ts[:10]
        con.executemany(
            """
            INSERT INTO ticker_daily_snapshots
                (day,ts,symbol,exchange,price,volume_24h,funding_rate,change_24h_pct,open_interest)
            VALUES (?,?,?,?,?,?,?,?,?)
            ON CONFLICT(day,exchange,symbol) DO UPDATE SET
                ts=excluded.ts,
                price=excluded.price,
                volume_24h=excluded.volume_24h,
                funding_rate=excluded.funding_rate,
                change_24h_pct=excluded.change_24h_pct,
                open_interest=excluded.open_interest
            """,
            [(day, *row) for row in rows],
        )
        cutoff = (datetime.utcnow() - timedelta(days=7)).isoformat()
        con.execute("DELETE FROM ticker_snapshots WHERE ts < ?", (cutoff,))
        daily_cutoff = (datetime.utcnow() - timedelta(days=90)).strftime("%Y-%m-%d")
        con.execute("DELETE FROM ticker_daily_snapshots WHERE day < ?", (daily_cutoff,))
        con.commit()
        con.close()
        return len(rows)
    except Exception as e:
        print(f"[snapshot_tickers] {e}", file=sys.stderr)
        return 0


def _cross_venue_number(value, default=None):
    """Parse a public-feed number without turning missing data into false zeroes."""
    try:
        if value is None or value == "":
            return default
        number = float(value)
        return number if math.isfinite(number) else default
    except (TypeError, ValueError):
        return default


def _cross_venue_spread_bps(bid, ask) -> float | None:
    bid_value = _cross_venue_number(bid)
    ask_value = _cross_venue_number(ask)
    if not bid_value or not ask_value or bid_value <= 0 or ask_value <= 0:
        return None
    midpoint = (bid_value + ask_value) / 2
    return ((ask_value - bid_value) / midpoint) * 10000 if midpoint else None


def _normalize_cross_venue_mexc(tickers: list[dict]) -> dict[str, dict]:
    normalized = {}
    for ticker in tickers or []:
        native_symbol = str(ticker.get("symbol") or "").upper()
        if not native_symbol.endswith("_USDT"):
            continue
        base_asset = native_symbol[:-5]
        price = _cross_venue_number(ticker.get("lastPrice") or ticker.get("fairPrice"))
        if not base_asset or not price or price <= 0:
            continue
        funding = _cross_venue_number(ticker.get("fundingRate"))
        normalized[base_asset] = {
            "base_asset": base_asset,
            "exchange": "MEXC",
            "native_symbol": native_symbol,
            "quote_asset": "USDT",
            "price": price,
            "mark_price": _cross_venue_number(ticker.get("fairPrice")),
            "index_price": _cross_venue_number(ticker.get("indexPrice")),
            "bid_price": _cross_venue_number(ticker.get("bid1")),
            "ask_price": _cross_venue_number(ticker.get("ask1")),
            "spread_bps": _cross_venue_spread_bps(ticker.get("bid1"), ticker.get("ask1")),
            "volume_24h_usd": _cross_venue_number(ticker.get("amount24")),
            # MEXC's ticker-level holdVol is retained in native contract units.
            # It is intentionally not mislabeled as USD or compared to venue USD OI.
            "open_interest_native": _cross_venue_number(ticker.get("holdVol")),
            "open_interest_usd": None,
            "funding_rate": funding,
            "funding_interval_hours": 8.0,
            "funding_interval_assumed": 1,
            "funding_8h_equiv": funding,
            "change_24h_pct": (
                _cross_venue_number(ticker.get("riseFallRate"), 0.0) * 100
            ),
            "source_timestamp_ms": int(_cross_venue_number(ticker.get("timestamp"), 0) or 0) or None,
            "data_quality": "mexc_funding_interval_assumed;oi_native_contract_units",
        }
    return normalized


def _normalize_cross_venue_hyperliquid(tickers: list[dict]) -> dict[str, dict]:
    normalized = {}
    for ticker in tickers or []:
        native_symbol = str(ticker.get("symbol") or "").upper()
        if not native_symbol.endswith("_USDC"):
            continue
        base_asset = native_symbol[:-5]
        price = _cross_venue_number(ticker.get("lastPrice") or ticker.get("fairPrice"))
        if not base_asset or not price or price <= 0:
            continue
        funding = _cross_venue_number(ticker.get("fundingRate"))
        normalized[base_asset] = {
            "base_asset": base_asset,
            "exchange": "HYPERLIQUID",
            "native_symbol": native_symbol,
            "quote_asset": "USDC",
            "price": price,
            "mark_price": _cross_venue_number(ticker.get("lastPrice")),
            "index_price": _cross_venue_number(ticker.get("fairPrice")),
            "bid_price": None,
            "ask_price": None,
            "spread_bps": None,
            "volume_24h_usd": _cross_venue_number(ticker.get("vol24h")),
            "open_interest_native": None,
            "open_interest_usd": _cross_venue_number(ticker.get("holdVol")),
            "funding_rate": funding,
            "funding_interval_hours": 1.0,
            "funding_interval_assumed": 0,
            "funding_8h_equiv": funding * 8 if funding is not None else None,
            "change_24h_pct": (
                _cross_venue_number(ticker.get("riseFallRate"), 0.0) * 100
            ),
            "source_timestamp_ms": None,
            "data_quality": "mark_price_only;usdc_quote",
        }
    return normalized


def _normalize_cross_venue_bybit(tickers: list[dict]) -> dict[str, dict]:
    normalized = {}
    for ticker in tickers or []:
        native_symbol = str(ticker.get("symbol") or "").upper()
        # Bybit's linear response also contains USDC and dated contracts.
        # Keep perpetual USDT names so base matching stays deterministic.
        if not native_symbol.endswith("USDT"):
            continue
        base_asset = native_symbol[:-4]
        price = _cross_venue_number(ticker.get("lastPrice") or ticker.get("markPrice"))
        if not base_asset or not price or price <= 0:
            continue
        funding = _cross_venue_number(ticker.get("fundingRate"))
        interval = _cross_venue_number(ticker.get("fundingIntervalHour"), 8.0) or 8.0
        normalized[base_asset] = {
            "base_asset": base_asset,
            "exchange": "BYBIT",
            "native_symbol": native_symbol,
            "quote_asset": "USDT",
            "price": price,
            "mark_price": _cross_venue_number(ticker.get("markPrice")),
            "index_price": _cross_venue_number(ticker.get("indexPrice")),
            "bid_price": _cross_venue_number(ticker.get("bid1Price")),
            "ask_price": _cross_venue_number(ticker.get("ask1Price")),
            "spread_bps": _cross_venue_spread_bps(
                ticker.get("bid1Price"),
                ticker.get("ask1Price"),
            ),
            "volume_24h_usd": _cross_venue_number(ticker.get("turnover24h")),
            "open_interest_native": _cross_venue_number(ticker.get("openInterest")),
            "open_interest_usd": _cross_venue_number(ticker.get("openInterestValue")),
            "funding_rate": funding,
            "funding_interval_hours": interval,
            "funding_interval_assumed": int(not ticker.get("fundingIntervalHour")),
            "funding_8h_equiv": (
                funding * (8 / interval) if funding is not None and interval > 0 else None
            ),
            "change_24h_pct": (
                _cross_venue_number(ticker.get("price24hPcnt"), 0.0) * 100
            ),
            "source_timestamp_ms": None,
            "data_quality": (
                "bybit_funding_interval_assumed"
                if not ticker.get("fundingIntervalHour")
                else "complete_ticker"
            ),
        }
    return normalized


def _collect_cross_venue_snapshot() -> dict:
    """Fetch three public venue universes once and persist synchronized report evidence."""
    started = time.perf_counter()
    captured_at = datetime.utcnow().isoformat()
    errors = {}

    def fetch_hyperliquid():
        universe, contexts = fetch_hl_meta_and_ctxs()
        return normalize_hl_tickers(universe, contexts)

    fetchers = {
        "MEXC": lambda: fetch_mexc("/contract/ticker") or [],
        "HYPERLIQUID": fetch_hyperliquid,
        "BYBIT": fetch_bybit_tickers,
    }
    raw = {}
    with ThreadPoolExecutor(max_workers=3) as pool:
        futures = {name: pool.submit(fetcher) for name, fetcher in fetchers.items()}
        for name, future in futures.items():
            try:
                rows = future.result()
                raw[name] = rows if isinstance(rows, list) else []
                if not raw[name]:
                    errors[name] = "empty response"
            except Exception as exc:
                raw[name] = []
                errors[name] = str(exc)[:240]

    venue_maps = {
        "MEXC": _normalize_cross_venue_mexc(raw.get("MEXC") or []),
        "HYPERLIQUID": _normalize_cross_venue_hyperliquid(raw.get("HYPERLIQUID") or []),
        "BYBIT": _normalize_cross_venue_bybit(raw.get("BYBIT") or []),
    }
    mexc_bases = set(venue_maps["MEXC"])
    matched_bases = sorted(
        base for base in mexc_bases
        if base in venue_maps["HYPERLIQUID"] or base in venue_maps["BYBIT"]
    )
    matched_three = sum(
        1 for base in matched_bases
        if base in venue_maps["HYPERLIQUID"] and base in venue_maps["BYBIT"]
    )
    stored = []
    columns = (
        "captured_at", "base_asset", "exchange", "native_symbol", "quote_asset",
        "price", "mark_price", "index_price", "bid_price", "ask_price", "spread_bps",
        "volume_24h_usd", "open_interest_native", "open_interest_usd", "funding_rate",
        "funding_interval_hours", "funding_interval_assumed", "funding_8h_equiv",
        "change_24h_pct", "source_timestamp_ms", "data_quality",
    )
    for base in matched_bases:
        for venue in ("MEXC", "HYPERLIQUID", "BYBIT"):
            packet = venue_maps[venue].get(base)
            if packet:
                stored.append(tuple([captured_at] + [packet.get(key) for key in columns[1:]]))

    latency_ms = round((time.perf_counter() - started) * 1000)
    con = sqlite3.connect(DB_PATH, timeout=20)
    try:
        con.executemany(
            f"""
            INSERT OR IGNORE INTO cross_venue_snapshots ({",".join(columns)})
            VALUES ({",".join("?" for _ in columns)})
            """,
            stored,
        )
        con.execute(
            """
            INSERT OR REPLACE INTO cross_venue_collection_runs
                (captured_at,latency_ms,mexc_count,hyperliquid_count,bybit_count,
                 matched_two_venue,matched_three_venue,stored_rows,errors_json)
            VALUES (?,?,?,?,?,?,?,?,?)
            """,
            (
                captured_at,
                latency_ms,
                len(venue_maps["MEXC"]),
                len(venue_maps["HYPERLIQUID"]),
                len(venue_maps["BYBIT"]),
                len(matched_bases),
                matched_three,
                len(stored),
                json.dumps(errors, sort_keys=True),
            ),
        )
        cutoff = (datetime.utcnow() - timedelta(days=CROSS_VENUE_RETENTION_DAYS)).isoformat()
        con.execute("DELETE FROM cross_venue_snapshots WHERE captured_at < ?", (cutoff,))
        con.execute(
            "DELETE FROM cross_venue_collection_runs WHERE captured_at < ?",
            ((datetime.utcnow() - timedelta(days=30)).isoformat(),),
        )
        con.commit()
    finally:
        con.close()
    return {
        "captured_at": captured_at,
        "latency_ms": latency_ms,
        "mexc_count": len(venue_maps["MEXC"]),
        "hyperliquid_count": len(venue_maps["HYPERLIQUID"]),
        "bybit_count": len(venue_maps["BYBIT"]),
        "matched_two_venue": len(matched_bases),
        "matched_three_venue": matched_three,
        "stored_rows": len(stored),
        "errors": errors,
    }


_CATALYST_HEADERS = {
    "User-Agent": "MatrixTrader/7.0 catalyst-monitor",
    "Accept": "application/json,text/html,application/xml,text/xml;q=0.9,*/*;q=0.8",
}
_CATALYST_ASSET_STOPWORDS = {
    "API", "APR", "CEO", "CPI", "ETF", "FED", "FOMC", "GDP", "MEXC", "NEW",
    "PERP", "SPOT", "SEC", "THE", "USD", "USDC", "USDT", "UTC",
}


def _catalyst_clean_text(value, limit: int = 900) -> str:
    """Normalize source text without asking an LLM to interpret it."""
    text = html_lib.unescape(str(value or ""))
    text = re.sub(r"<br\s*/?>", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:limit]


def _catalyst_iso(value) -> str | None:
    """Return a UTC-naive ISO timestamp so SQLite lexical ranges remain stable."""
    if value is None or value == "":
        return None
    try:
        if isinstance(value, (int, float)) or str(value).strip().isdigit():
            raw = float(value)
            if raw > 10_000_000_000:
                raw /= 1000
            parsed = datetime.fromtimestamp(raw, tz=timezone.utc)
        elif isinstance(value, datetime):
            parsed = value
        else:
            raw = str(value).strip()
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
        return parsed.replace(microsecond=0).isoformat()
    except Exception:
        return None


def _catalyst_assets(text: str, known_assets: set[str] | None = None) -> list[str]:
    """Extract canonical perp bases conservatively; unknown prose acronyms are ignored."""
    haystack = str(text or "").upper()
    known = {
        str(asset or "").upper().replace("_USDT", "").replace("USDT", "")
        for asset in (known_assets or set())
        if str(asset or "").strip()
    }
    known.update({"BTC", "ETH", "SOL", "HYPE", "MX", "XRP", "DOGE", "BNB"})
    candidates = set(re.findall(r"\b([A-Z0-9]{2,20})_?USDT\b", haystack))
    candidates.update(re.findall(r"\b([A-Z0-9]{2,15})/(?:USDT|USD|USDC)\b", haystack))
    candidates.update(
        token for token in re.findall(r"\(([A-Z0-9]{2,15})\)", haystack)
        if token in known
    )
    aliases = {
        "BITCOIN": "BTC",
        "ETHEREUM": "ETH",
        "SOLANA": "SOL",
        "HYPERLIQUID": "HYPE",
    }
    for word, base in aliases.items():
        if word in haystack:
            candidates.add(base)
    return [
        f"{base}_USDT"
        for base in sorted(candidates)
        if base in known and base not in _CATALYST_ASSET_STOPWORDS
    ][:12]


def _catalyst_classify(title: str, summary: str = "", forced_type: str | None = None) -> tuple[str, str, str]:
    """Classify the operational meaning of a primary-source item, never its price direction."""
    text = f"{title} {summary}".lower()
    event_type = forced_type or "announcement"
    horizon = "hours-7d"
    if any(word in text for word in ("exploit", "hack", "security incident", "breach")):
        event_type, horizon = "security", "minutes-24h"
    elif any(word in text for word in ("outage", "degraded", "incident")):
        event_type, horizon = "venue_incident", "minutes-24h"
    elif any(word in text for word in ("delist", "remove the following", "cease trading")):
        event_type, horizon = "delisting", "hours-7d"
    elif "leverage" in text:
        event_type, horizon = "leverage_change", "hours-7d"
    elif any(word in text for word in ("funding rate", "funding interval", "settlement frequency")):
        event_type, horizon = "funding_change", "hours-7d"
    elif any(word in text for word in ("maintenance", "network upgrade", "system upgrade")):
        event_type, horizon = "maintenance", "minutes-7d"
    elif any(word in text for word in ("governance", "proposal", "temperature check", "snapshot vote", "onchain vote", "on-chain vote")):
        event_type, horizon = "governance", "days-6w"
    elif any(word in text for word in ("enforcement", "settlement", "charges", "regulation", "rulemaking", "digital asset")):
        event_type, horizon = "regulatory", "hours-6w"
    elif any(word in text for word in ("listing", "now live", "launchpool", "pre-market")):
        event_type, horizon = "listing", "hours-7d"
    elif any(word in text for word in ("fomc", "monetary policy", "federal funds rate")):
        event_type, horizon = "monetary_policy", "hours-6w"
    severity = "low"
    if event_type in {"security", "venue_incident"}:
        severity = "critical" if any(word in text for word in ("critical", "exploit", "hack", "outage")) else "high"
    elif event_type in {"delisting", "leverage_change", "funding_change", "monetary_policy"}:
        severity = "high"
    elif event_type in {"maintenance", "listing", "governance", "regulatory"}:
        severity = "medium"
    return event_type, severity, horizon


def _catalyst_event(
    *,
    source_key: str,
    source_name: str,
    source_kind: str,
    source_url: str,
    external_id: str,
    title: str,
    summary: str = "",
    published_at=None,
    event_at=None,
    status: str = "published",
    event_type: str | None = None,
    severity: str | None = None,
    horizon: str | None = None,
    assets: list[str] | None = None,
    venues: list[str] | None = None,
    scheduled: bool = False,
    source_time_quality: str = "published",
    raw_meta: dict | None = None,
) -> dict:
    clean_title = _catalyst_clean_text(title, 320)
    clean_summary = _catalyst_clean_text(summary, 900)
    classified_type, classified_severity, classified_horizon = _catalyst_classify(
        clean_title,
        clean_summary,
        forced_type=event_type,
    )
    content_hash = hashlib.sha256(
        f"{source_key}|{external_id}|{clean_title}|{clean_summary}|{event_at}".encode("utf-8")
    ).hexdigest()
    return {
        "source_key": source_key,
        "source_name": source_name,
        "source_kind": source_kind,
        "source_url": str(source_url or ""),
        "external_id": str(external_id),
        "title": clean_title,
        "summary": clean_summary,
        "published_at": _catalyst_iso(published_at),
        "event_at": _catalyst_iso(event_at) or _catalyst_iso(published_at),
        "status": str(status or "published"),
        "severity": severity or classified_severity,
        "event_type": classified_type,
        "affected_assets": list(dict.fromkeys(assets or []))[:12],
        "affected_venues": list(dict.fromkeys(venues or []))[:6],
        "horizon": horizon or classified_horizon,
        "scheduled": bool(scheduled),
        "primary_source": True,
        "source_time_quality": source_time_quality,
        "content_hash": content_hash,
        "raw_meta": raw_meta or {},
    }


def _parse_mexc_announcements(page_html: str, known_assets: set[str] | None = None) -> list[dict]:
    """Parse official MEXC announcement cards and preserve publication/effective time."""
    pattern = re.compile(
        r'<a\s+[^>]*title="(?P<title>[^"]+)"[^>]*href="(?P<href>/announcements/article/[^"]+)"'
        r'[^>]*>.*?</a>.*?<time[^>]*dateTime="(?P<published>[^"]+)"',
        re.IGNORECASE | re.DOTALL,
    )
    rows = []
    seen = set()
    for match in pattern.finditer(page_html or ""):
        title = html_lib.unescape(match.group("title"))
        href = html_lib.unescape(match.group("href"))
        external_id = href.rstrip("/").split("-")[-1]
        if external_id in seen:
            continue
        seen.add(external_id)
        effective_at = None
        effective = re.search(
            r"\[([A-Z][a-z]{2}\s+\d{1,2},\s+\d{4},\s+\d{1,2}:\d{2}\s+\(UTC\))\]",
            title,
        )
        if effective:
            try:
                effective_at = datetime.strptime(
                    effective.group(1),
                    "%b %d, %Y, %H:%M (UTC)",
                )
            except Exception:
                pass
        assets = _catalyst_assets(title, known_assets)
        rows.append(_catalyst_event(
            source_key="mexc_announcements",
            source_name="MEXC Announcements",
            source_kind="exchange_announcement",
            source_url=f"https://www.mexc.com{href}",
            external_id=external_id,
            title=title,
            published_at=match.group("published"),
            event_at=effective_at or match.group("published"),
            assets=assets,
            venues=["MEXC"],
            scheduled=bool(effective_at and _catalyst_iso(effective_at) != _catalyst_iso(match.group("published"))),
            source_time_quality="published_and_effective" if effective_at else "published",
        ))
    return rows


def _parse_mexc_telegram(page_html: str, known_assets: set[str] | None = None) -> list[dict]:
    """Fallback for MEXC's official public announcement channel."""
    pattern = re.compile(
        r'<div[^>]+data-post="MEXC_OfficialAnnouncements/(?P<id>\d+)"[^>]*>'
        r'(?P<body>.*?)</article>',
        re.IGNORECASE | re.DOTALL,
    )
    rows = []
    for match in pattern.finditer(page_html or ""):
        body = match.group("body")
        text_match = re.search(
            r'tgme_widget_message_text[^>]*>(?P<text>.*?)</div>',
            body,
            re.IGNORECASE | re.DOTALL,
        )
        time_match = re.search(r'<time[^>]+datetime="(?P<time>[^"]+)"', body, re.IGNORECASE)
        if not text_match or not time_match:
            continue
        text = _catalyst_clean_text(text_match.group("text"))
        title = text.split(". ")[0][:240] or "MEXC official announcement"
        post_id = match.group("id")
        rows.append(_catalyst_event(
            source_key="mexc_official_channel",
            source_name="MEXC Official Announcements",
            source_kind="official_channel_mirror",
            source_url=f"https://t.me/MEXC_OfficialAnnouncements/{post_id}",
            external_id=post_id,
            title=title,
            summary=text,
            published_at=time_match.group("time"),
            assets=_catalyst_assets(text, known_assets),
            venues=["MEXC"],
            source_time_quality="published",
        ))
    return rows


def _parse_bybit_announcements(payload: dict, known_assets: set[str] | None = None) -> list[dict]:
    rows = []
    for item in ((payload or {}).get("result") or {}).get("list") or []:
        title = item.get("title") or "Bybit announcement"
        summary = item.get("description") or ""
        url = item.get("url") or "https://announcements.bybit.com/"
        external_id = str(item.get("id") or hashlib.sha256(str(url).encode()).hexdigest()[:24])
        start_at = item.get("startDateTimestamp")
        rows.append(_catalyst_event(
            source_key="bybit_announcements",
            source_name="Bybit Announcements API",
            source_kind="exchange_announcement",
            source_url=url,
            external_id=external_id,
            title=title,
            summary=summary,
            published_at=item.get("dateTimestamp"),
            event_at=start_at or item.get("dateTimestamp"),
            assets=_catalyst_assets(f"{title} {summary}", known_assets),
            venues=["BYBIT"],
            scheduled=bool(start_at),
            source_time_quality="published_and_effective" if start_at else "published",
            raw_meta={
                "type": (item.get("type") or {}).get("key"),
                "tags": item.get("tags") or [],
            },
        ))
    return rows


def _parse_hyperliquid_status(payload: dict, *, scheduled: bool = False) -> list[dict]:
    key = "scheduled_maintenances" if scheduled else "incidents"
    rows = []
    for item in (payload or {}).get(key) or []:
        updates = item.get("incident_updates") or []
        latest_update = updates[0] if updates else {}
        event_at = (
            item.get("scheduled_for") or item.get("started_at")
            if scheduled else item.get("created_at")
        )
        status = str(item.get("status") or "unknown")
        impact = str(item.get("impact") or "none").lower()
        severity = {
            "critical": "critical",
            "major": "high",
            "minor": "medium",
            "none": "low",
        }.get(impact, "medium")
        rows.append(_catalyst_event(
            source_key="hyperliquid_status",
            source_name="Hyperliquid Status",
            source_kind="exchange_maintenance" if scheduled else "exchange_incident",
            source_url=item.get("shortlink") or "https://hyperliquid.statuspage.io/",
            external_id=item.get("id") or hashlib.sha256(str(item).encode()).hexdigest()[:24],
            title=item.get("name") or "Hyperliquid status update",
            summary=latest_update.get("body") or "",
            published_at=item.get("created_at"),
            event_at=event_at,
            status=status,
            event_type="maintenance" if scheduled else "venue_incident",
            severity=severity,
            horizon="minutes-7d" if scheduled else "minutes-24h",
            assets=["MARKET"],
            venues=["HYPERLIQUID"],
            scheduled=scheduled,
            source_time_quality="scheduled" if scheduled else "published",
            raw_meta={
                "impact": impact,
                "updated_at": item.get("updated_at"),
                "scheduled_until": item.get("scheduled_until"),
            },
        ))
    return rows


def _parse_fed_monetary_rss(xml_text: str) -> list[dict]:
    rows = []
    try:
        # The feed declares UTF-8 but can arrive decoded as a visible BOM
        # ("ï»¿") when the response omits a charset.
        clean_xml = (xml_text or "").lstrip("\ufeff")
        if clean_xml.startswith("ï»¿"):
            clean_xml = clean_xml[3:]
        root = ET.fromstring(clean_xml)
    except Exception:
        return rows
    for item in root.findall(".//item"):
        def node_text(name):
            node = item.find(name)
            return node.text.strip() if node is not None and node.text else ""
        title = node_text("title")
        url = node_text("link")
        guid = node_text("guid") or url or title
        published_raw = node_text("pubDate")
        try:
            published_at = parsedate_to_datetime(published_raw)
        except Exception:
            published_at = published_raw
        rows.append(_catalyst_event(
            source_key="federal_reserve_monetary",
            source_name="Federal Reserve Monetary Policy",
            source_kind="macro_release",
            source_url=url or "https://www.federalreserve.gov/newsevents.htm",
            external_id=hashlib.sha256(guid.encode("utf-8")).hexdigest()[:32],
            title=title,
            summary=node_text("description"),
            published_at=published_at,
            event_type="monetary_policy",
            severity="high",
            horizon="hours-6w",
            assets=["MARKET"],
            venues=["MEXC", "HYPERLIQUID", "BYBIT"],
            source_time_quality="published",
        ))
    return rows


_CRYPTO_REGULATORY_TERMS = {
    "bitcoin", "blockchain", "crypto", "cryptocurrency", "digital asset",
    "ether", "stablecoin", "token", "virtual currency", "decentralized finance",
}


def _parse_official_rss(
    xml_text: str,
    *,
    source_key: str,
    source_name: str,
    source_kind: str,
    fallback_url: str,
    fixed_assets: list[str] | None = None,
    event_type: str | None = None,
    require_terms: set[str] | None = None,
    authority_scope: str,
    limit: int = 40,
) -> list[dict]:
    """Normalize official regulator/protocol RSS with explicit authority scope."""
    try:
        clean_xml = (xml_text or "").lstrip("\ufeff")
        if clean_xml.startswith("ï»¿"):
            clean_xml = clean_xml[3:]
        root = ET.fromstring(clean_xml)
    except Exception:
        return []
    rows = []
    for item in root.findall(".//item")[: max(1, limit)]:
        def node_text(name):
            node = item.find(name)
            return node.text.strip() if node is not None and node.text else ""

        title = node_text("title")
        summary = node_text("description")
        haystack = f"{title} {_catalyst_clean_text(summary)}".lower()
        if require_terms and not any(term in haystack for term in require_terms):
            continue
        url = node_text("link") or fallback_url
        guid = node_text("guid") or url or title
        published_raw = node_text("pubDate")
        try:
            published_at = parsedate_to_datetime(published_raw)
        except Exception:
            published_at = published_raw
        rows.append(_catalyst_event(
            source_key=source_key,
            source_name=source_name,
            source_kind=source_kind,
            source_url=url,
            external_id=hashlib.sha256(guid.encode("utf-8")).hexdigest()[:32],
            title=title or f"{source_name} update",
            summary=summary,
            published_at=published_at,
            event_type=event_type,
            severity="medium",
            horizon="hours-6w" if event_type == "regulatory" else "days-6w",
            assets=fixed_assets or ["MARKET"],
            venues=["MEXC", "HYPERLIQUID", "BYBIT"],
            source_time_quality="published",
            raw_meta={
                "authority_scope": authority_scope,
                "symbol_resolution": (
                    "reviewed_protocol_mapping" if fixed_assets else "market_wide"
                ),
            },
        ))
    return rows


def _parse_protocol_status(
    payload: dict,
    *,
    source_key: str,
    source_name: str,
    fallback_url: str,
    asset: str,
) -> list[dict]:
    """Normalize official protocol Statuspage incidents without price inference."""
    rows = []
    for item in (payload or {}).get("incidents") or []:
        updates = item.get("incident_updates") or []
        latest_update = updates[0] if updates else {}
        impact = str(item.get("impact") or "none").lower()
        severity = {
            "critical": "critical",
            "major": "high",
            "minor": "medium",
            "none": "low",
        }.get(impact, "medium")
        rows.append(_catalyst_event(
            source_key=source_key,
            source_name=source_name,
            source_kind="protocol_security_status",
            source_url=item.get("shortlink") or fallback_url,
            external_id=item.get("id") or hashlib.sha256(str(item).encode()).hexdigest()[:24],
            title=item.get("name") or f"{source_name} incident",
            summary=latest_update.get("body") or "",
            published_at=item.get("created_at"),
            event_at=item.get("started_at") or item.get("created_at"),
            status=str(item.get("status") or "unknown"),
            event_type="security" if "security" in str(item.get("name") or "").lower() else "protocol_incident",
            severity=severity,
            horizon="minutes-7d",
            assets=[asset],
            venues=["MEXC", "HYPERLIQUID", "BYBIT"],
            source_time_quality="published",
            raw_meta={
                "authority_scope": "official_protocol_status",
                "symbol_resolution": "reviewed_protocol_mapping",
                "impact": impact,
                "updated_at": item.get("updated_at"),
            },
        ))
    return rows


def _parse_fomc_calendar(page_html: str) -> list[dict]:
    """Extract official FOMC meeting windows and model the statement time as 2pm ET."""
    rows = []
    sections = re.finditer(
        r'<a[^>]*>\s*(?P<year>\d{4})\s+FOMC Meetings\s*</a>'
        r'(?P<body>.*?)(?=<a[^>]*>\s*\d{4}\s+FOMC Meetings\s*</a>|$)',
        page_html or "",
        re.IGNORECASE | re.DOTALL,
    )
    now_year = datetime.utcnow().year
    for section in sections:
        year = int(section.group("year"))
        if year < now_year - 1 or year > now_year + 3:
            continue
        body = section.group("body")
        meeting_pattern = re.compile(
            r'fomc-meeting__month[^>]*>.*?<strong>(?P<month>.*?)</strong>.*?'
            r'fomc-meeting__date[^>]*>(?P<date>.*?)</div>',
            re.IGNORECASE | re.DOTALL,
        )
        for meeting in meeting_pattern.finditer(body):
            month_text = _catalyst_clean_text(meeting.group("month"), 30).split("/")[0]
            date_text = _catalyst_clean_text(meeting.group("date"), 80)
            days = [int(value) for value in re.findall(r"\d{1,2}", date_text)]
            if not days:
                continue
            try:
                month_num = datetime.strptime(month_text[:3], "%b").month
                start_day, end_day = days[0], days[-1]
                start_date = datetime(year, month_num, start_day)
                event_local = datetime(
                    year, month_num, end_day, 14, 0,
                    tzinfo=ZoneInfo("America/New_York"),
                )
                event_at = event_local.astimezone(timezone.utc)
            except Exception:
                continue
            projections = "*" in date_text
            title = (
                f"FOMC monetary-policy decision window: "
                f"{start_date.strftime('%b')} {start_day}"
                f"{f'–{end_day}' if end_day != start_day else ''}, {year}"
            )
            rows.append(_catalyst_event(
                source_key="fomc_calendar",
                source_name="Federal Reserve FOMC Calendar",
                source_kind="scheduled_macro",
                source_url="https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm",
                external_id=f"fomc-{year}-{month_num:02d}-{end_day:02d}",
                title=title,
                summary=(
                    "Scheduled FOMC decision; Summary of Economic Projections is indicated."
                    if projections else
                    "Scheduled FOMC monetary-policy decision."
                ),
                published_at=None,
                event_at=event_at,
                event_type="monetary_policy",
                severity="high",
                horizon="hours-6w",
                assets=["MARKET"],
                venues=["MEXC", "HYPERLIQUID", "BYBIT"],
                scheduled=True,
                source_time_quality="official_schedule",
                raw_meta={
                    "meeting_start": start_date.date().isoformat(),
                    "projections": projections,
                },
            ))
    return rows


def _catalyst_known_assets() -> set[str]:
    assets = {"BTC", "ETH", "SOL", "HYPE", "MX", "XRP", "DOGE", "BNB"}
    try:
        con = sqlite3.connect(DB_PATH, timeout=2)
        tables = {
            str(row[0]) for row in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        }
        if "ticker_snapshots" in tables:
            rows = con.execute(
                "SELECT DISTINCT symbol FROM ticker_snapshots ORDER BY ts DESC LIMIT 2000"
            ).fetchall()
            assets.update(
                str(row[0] or "").upper().replace("_USDT", "").replace("USDT", "")
                for row in rows
            )
        con.close()
    except Exception:
        pass
    return {asset for asset in assets if asset}


def _fetch_catalyst_sources() -> tuple[dict[str, list[dict]], dict[str, str]]:
    """Fetch official sources concurrently; report generation never calls this."""
    known_assets = _catalyst_known_assets()

    def fetch_mexc_source():
        response = requests.get(
            "https://www.mexc.com/announcements",
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        rows = _parse_mexc_announcements(response.text, known_assets)
        if rows:
            return rows
        fallback = requests.get(
            "https://t.me/s/MEXC_OfficialAnnouncements",
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        fallback.raise_for_status()
        return _parse_mexc_telegram(fallback.text, known_assets)

    def fetch_bybit_source():
        response = requests.get(
            f"{BYBIT_BASE}/v5/announcements/index",
            params={"locale": "en-US", "limit": 50},
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        payload = response.json()
        if int(payload.get("retCode") or 0) != 0:
            raise RuntimeError(str(payload.get("retMsg") or "Bybit announcement API error"))
        return _parse_bybit_announcements(payload, known_assets)

    def fetch_hyperliquid_source():
        rows = []
        for suffix, scheduled in (
            ("incidents.json", False),
            ("scheduled-maintenances.json", True),
        ):
            response = requests.get(
                f"https://hyperliquid.statuspage.io/api/v2/{suffix}",
                headers=_CATALYST_HEADERS,
                timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
            )
            response.raise_for_status()
            rows.extend(_parse_hyperliquid_status(response.json(), scheduled=scheduled))
        return rows

    def fetch_fed_rss_source():
        response = requests.get(
            "https://www.federalreserve.gov/feeds/press_monetary.xml",
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        return _parse_fed_monetary_rss(response.text)

    def fetch_fomc_source():
        response = requests.get(
            "https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm",
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        return _parse_fomc_calendar(response.text)

    def fetch_rss_source(
        url,
        *,
        source_key,
        source_name,
        source_kind,
        fixed_assets=None,
        event_type=None,
        require_terms=None,
        authority_scope,
    ):
        response = requests.get(
            url,
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        return _parse_official_rss(
            response.text,
            source_key=source_key,
            source_name=source_name,
            source_kind=source_kind,
            fallback_url=url,
            fixed_assets=fixed_assets,
            event_type=event_type,
            require_terms=require_terms,
            authority_scope=authority_scope,
        )

    def fetch_solana_status_source():
        url = "https://status.solana.com/api/v2/incidents.json"
        response = requests.get(
            url,
            headers=_CATALYST_HEADERS,
            timeout=CATALYST_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        return _parse_protocol_status(
            response.json(),
            source_key="solana_protocol_status",
            source_name="Solana Status",
            fallback_url="https://status.solana.com/",
            asset="SOL_USDT",
        )

    fetchers = {
        "mexc_announcements": fetch_mexc_source,
        "bybit_announcements": fetch_bybit_source,
        "hyperliquid_status": fetch_hyperliquid_source,
        "federal_reserve_monetary": fetch_fed_rss_source,
        "fomc_calendar": fetch_fomc_source,
        "sec_crypto_releases": lambda: fetch_rss_source(
            "https://www.sec.gov/news/pressreleases.rss",
            source_key="sec_crypto_releases",
            source_name="U.S. SEC Press Releases",
            source_kind="official_regulator",
            event_type="regulatory",
            require_terms=_CRYPTO_REGULATORY_TERMS,
            authority_scope="official_regulator_release",
        ),
        "cftc_crypto_releases": lambda: fetch_rss_source(
            "https://www.cftc.gov/RSS/RSSGP/rssgp.xml",
            source_key="cftc_crypto_releases",
            source_name="U.S. CFTC Press Releases",
            source_kind="official_regulator",
            event_type="regulatory",
            require_terms=_CRYPTO_REGULATORY_TERMS,
            authority_scope="official_regulator_release",
        ),
        "ethereum_foundation": lambda: fetch_rss_source(
            "https://blog.ethereum.org/feed.xml",
            source_key="ethereum_foundation",
            source_name="Ethereum Foundation Blog",
            source_kind="official_protocol_publication",
            fixed_assets=["ETH_USDT"],
            require_terms={
                "security", "protocol", "upgrade", "hard fork", "governance",
                "consensus", "execution layer",
            },
            authority_scope="official_protocol_publication",
        ),
        "aave_governance": lambda: fetch_rss_source(
            "https://governance.aave.com/latest.rss",
            source_key="aave_governance",
            source_name="Aave Governance Forum",
            source_kind="official_governance_forum",
            fixed_assets=["AAVE_USDT"],
            event_type="governance",
            authority_scope="official_protocol_governance_forum",
        ),
        "arbitrum_governance": lambda: fetch_rss_source(
            "https://forum.arbitrum.foundation/latest.rss",
            source_key="arbitrum_governance",
            source_name="Arbitrum Governance Forum",
            source_kind="official_governance_forum",
            fixed_assets=["ARB_USDT"],
            event_type="governance",
            authority_scope="official_protocol_governance_forum",
        ),
        "optimism_governance": lambda: fetch_rss_source(
            "https://gov.optimism.io/latest.rss",
            source_key="optimism_governance",
            source_name="Optimism Governance Forum",
            source_kind="official_governance_forum",
            fixed_assets=["OP_USDT"],
            event_type="governance",
            authority_scope="official_protocol_governance_forum",
        ),
        "solana_protocol_status": fetch_solana_status_source,
    }
    results, errors = {}, {}
    empty_is_valid = {"sec_crypto_releases", "cftc_crypto_releases", "ethereum_foundation"}
    with ThreadPoolExecutor(max_workers=len(fetchers)) as pool:
        futures = {name: pool.submit(fetcher) for name, fetcher in fetchers.items()}
        for name, future in futures.items():
            try:
                rows = future.result()
                results[name] = rows if isinstance(rows, list) else []
                if not results[name] and name not in empty_is_valid:
                    errors[name] = "no parseable official-source items"
            except Exception as exc:
                results[name] = []
                errors[name] = str(exc)[:300]
    return results, errors


def _collect_catalyst_events() -> dict:
    """Refresh the advisory catalyst cache with a single bounded SQLite write."""
    started = time.perf_counter()
    collected_at = datetime.utcnow().replace(microsecond=0).isoformat()
    source_rows, errors = _fetch_catalyst_sources()
    cutoff = datetime.utcnow() - timedelta(days=CATALYST_RETENTION_DAYS)
    future_limit = datetime.utcnow() + timedelta(days=730)
    events = []
    for rows in source_rows.values():
        for event in rows:
            reference = _catalyst_iso(event.get("event_at") or event.get("published_at"))
            try:
                reference_dt = datetime.fromisoformat(reference) if reference else datetime.utcnow()
            except Exception:
                reference_dt = datetime.utcnow()
            status = str(event.get("status") or "").lower()
            if reference_dt < cutoff and status not in {"investigating", "identified", "monitoring"}:
                continue
            if reference_dt > future_limit:
                continue
            event["observed_at"] = collected_at
            events.append(event)
    deduped = {
        (event["source_key"], event["external_id"]): event
        for event in events
        if event.get("external_id") and event.get("title")
    }
    events = list(deduped.values())
    con = sqlite3.connect(DB_PATH, timeout=20)
    try:
        existing = {
            (str(row[0]), str(row[1]))
            for row in con.execute(
                "SELECT source_key, external_id FROM catalyst_events"
            ).fetchall()
        }
        columns = (
            "source_key", "source_name", "source_kind", "source_url", "external_id",
            "title", "summary", "published_at", "event_at", "observed_at", "status",
            "severity", "event_type", "affected_assets_json", "affected_venues_json",
            "horizon", "scheduled", "primary_source", "source_time_quality",
            "content_hash", "raw_meta_json",
        )
        values = []
        for event in events:
            packet = dict(event)
            packet["affected_assets_json"] = json.dumps(event.get("affected_assets") or [])
            packet["affected_venues_json"] = json.dumps(event.get("affected_venues") or [])
            packet["raw_meta_json"] = json.dumps(event.get("raw_meta") or {}, sort_keys=True)
            packet["scheduled"] = int(bool(event.get("scheduled")))
            packet["primary_source"] = int(bool(event.get("primary_source", True)))
            values.append(tuple(packet.get(column) for column in columns))
        if values:
            updates = ",".join(
                f"{column}=excluded.{column}"
                for column in columns
                if column not in {"source_key", "external_id"}
            )
            con.executemany(
                f"""
                INSERT INTO catalyst_events ({",".join(columns)})
                VALUES ({",".join("?" for _ in columns)})
                ON CONFLICT(source_key, external_id) DO UPDATE SET {updates}
                """,
                values,
            )
        latency_ms = round((time.perf_counter() - started) * 1000)
        new_events = sum(
            1 for event in events
            if (event["source_key"], event["external_id"]) not in existing
        )
        counts = {name: len(rows) for name, rows in source_rows.items()}
        con.execute(
            """
            INSERT OR REPLACE INTO catalyst_collection_runs
                (collected_at,latency_ms,stored_events,new_events,source_counts_json,source_errors_json)
            VALUES (?,?,?,?,?,?)
            """,
            (
                collected_at,
                latency_ms,
                len(events),
                new_events,
                json.dumps(counts, sort_keys=True),
                json.dumps(errors, sort_keys=True),
            ),
        )
        cutoff_iso = cutoff.isoformat()
        con.execute(
            """
            DELETE FROM catalyst_events
            WHERE COALESCE(event_at,published_at,observed_at)<?
              AND status NOT IN ('investigating','identified','monitoring')
            """,
            (cutoff_iso,),
        )
        con.execute(
            "DELETE FROM catalyst_collection_runs WHERE collected_at<?",
            ((datetime.utcnow() - timedelta(days=30)).isoformat(),),
        )
        con.commit()
    finally:
        con.close()
    return {
        "collected_at": collected_at,
        "latency_ms": latency_ms,
        "stored_events": len(events),
        "new_events": new_events,
        "source_counts": counts,
        "errors": errors,
    }


