def _tokenomics_base_symbol(value) -> str:
    """Convert a perp or token symbol to a conservative uppercase base."""
    raw = str(value or "").strip().upper()
    if raw in {"", "-", "N/A", "NONE"}:
        return ""
    for suffix in ("_USDT", "-USDT", "/USDT", "USDT"):
        if raw.endswith(suffix) and len(raw) > len(suffix):
            raw = raw[:-len(suffix)]
            break
    return raw if re.fullmatch(r"[A-Z0-9]{2,20}", raw) else ""


def _tokenomics_priority_symbols(limit: int = 30) -> list[str]:
    """Select a bounded set of report-relevant assets without any network work."""
    bases = ["BTC", "ETH", "SOL", "HYPE"]
    try:
        con = sqlite3.connect(DB_PATH, timeout=2)
        tables = {
            str(row[0]) for row in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        }
        if "ticker_snapshots" in tables:
            latest = con.execute("SELECT MAX(ts) FROM ticker_snapshots").fetchone()[0]
            if latest:
                rows = con.execute(
                    """
                    SELECT symbol
                    FROM ticker_snapshots
                    WHERE ts=?
                    ORDER BY ABS(COALESCE(change_24h_pct,0)) DESC,
                             COALESCE(volume_24h,0) DESC
                    LIMIT 20
                    """,
                    (latest,),
                ).fetchall()
                bases.extend(_tokenomics_base_symbol(row[0]) for row in rows)
        if "paper_trades" in tables:
            columns = {
                str(row[1]) for row in con.execute(
                    "PRAGMA table_info(paper_trades)"
                ).fetchall()
            }
            if {"symbol", "status"} <= columns:
                rows = con.execute(
                    """
                    SELECT DISTINCT symbol FROM paper_trades
                    WHERE LOWER(status) IN ('open','pending')
                    ORDER BY id DESC LIMIT 12
                    """
                ).fetchall()
                bases.extend(_tokenomics_base_symbol(row[0]) for row in rows)
        con.close()
    except Exception:
        pass
    return list(dict.fromkeys(base for base in bases if base))[:max(4, limit)]


def _parse_defillama_page_data(page_html: str) -> list[dict]:
    """Read the structured payload already rendered on a public DefiLlama page."""
    match = re.search(
        r'<script[^>]+id="__NEXT_DATA__"[^>]*>(.*?)</script>',
        page_html or "",
        re.IGNORECASE | re.DOTALL,
    )
    if not match:
        raise ValueError("DefiLlama page did not contain structured page data")
    payload = json.loads(html_lib.unescape(match.group(1)))
    rows = (((payload or {}).get("props") or {}).get("pageProps") or {}).get("data")
    if not isinstance(rows, list):
        raise ValueError("DefiLlama structured page data has no row list")
    return [row for row in rows if isinstance(row, dict)]


def _tokenomics_symbol_map(*row_sets: list[dict]) -> tuple[dict[str, str], dict[str, str]]:
    """Return reviewed mappings only; token tickers are not globally unique."""
    mapping = dict(_TOKENOMICS_CURATED_IDS)
    quality = {symbol: "curated_exact" for symbol in mapping}
    return mapping, quality


def _tokenomics_unlock_rows(rows: list[dict], observed_at: str) -> list[dict]:
    """Normalize only the next disclosed unlock group; do not replay full histories."""
    normalized = []
    for protocol in rows:
        protocol_id = str(protocol.get("protocolId") or "")
        project_name = str(protocol.get("name") or "Unknown token")
        symbol = _tokenomics_base_symbol(protocol.get("tSymbol"))
        coin_id = str(protocol.get("gecko_id") or "").strip() or None
        mapping_quality = (
            "curated_exact"
            if symbol and coin_id and _TOKENOMICS_CURATED_IDS.get(symbol) == coin_id
            else "unverified_symbol" if symbol else "project_only"
        )
        circ = _report_float(protocol.get("circSupply"), None)
        maximum = _report_float(protocol.get("maxSupply"), None)
        price = _report_float(protocol.get("tPrice"), None)
        unlocked_pct = (
            round(circ / maximum * 100, 2)
            if circ is not None and maximum not in (None, 0) else None
        )
        for event in protocol.get("upcomingEvent") or []:
            unlock_at = _catalyst_iso(event.get("timestamp"))
            if not unlock_at:
                continue
            unlock_type = str(event.get("unlockType") or "unknown").lower()
            category = str(event.get("category") or "unspecified")
            amounts = [
                _report_float(value, None)
                for value in (event.get("noOfTokens") or [])
            ]
            amounts = [value for value in amounts if value is not None]
            # A linear row describes a change in emission rate, not a discrete
            # transfer at the timestamp. Keep the schedule but do not present
            # that rate as a cliff-sized dollar unlock.
            token_amount = sum(amounts) if unlock_type == "cliff" else None
            unlock_value = (
                token_amount * price
                if token_amount is not None and price is not None else None
            )
            pct_float = (
                token_amount / circ * 100
                if token_amount is not None and circ not in (None, 0) else None
            )
            external_seed = (
                f"{protocol_id}|{project_name}|{unlock_at}|{category}|{unlock_type}"
            )
            normalized.append({
                "source_key": "defillama_unlocks_public",
                "source_name": "DefiLlama Unlocks",
                "source_url": "https://defillama.com/unlocks",
                "external_id": hashlib.sha256(
                    external_seed.encode("utf-8")
                ).hexdigest()[:32],
                "protocol_id": protocol_id or None,
                "project_name": project_name,
                "symbol": symbol or None,
                "coin_id": coin_id,
                "unlock_at": unlock_at,
                "observed_at": observed_at,
                "unlock_type": unlock_type,
                "category": category,
                "token_amount": token_amount,
                "unlock_value_usd": unlock_value,
                "unlock_pct_float": pct_float,
                "circulating_supply": circ,
                "max_supply": maximum,
                "unlocked_pct": unlocked_pct,
                "mapping_quality": mapping_quality,
                "data_quality": "third_party_aggregated_public_page",
                "raw_meta": {
                    "description_template": event.get("description"),
                    "reported_token_values": amounts,
                    "rate_duration_days": event.get("rateDurationDays"),
                    "linear_amount_is_rate": unlock_type == "linear",
                },
            })
    return normalized


def _tokenomics_treasury_rows(rows: list[dict], captured_at: str) -> list[dict]:
    """Normalize public treasury observations without implying wallet-level proof."""
    normalized = []
    snapshot_day = captured_at[:10]
    for row in rows:
        external_id = str(row.get("id") or "").strip()
        if not external_id:
            continue
        total = _report_float(row.get("tvl"), None)
        own = _report_float(row.get("ownTokens"), 0)
        stable = _report_float(row.get("stablecoins"), 0)
        majors = _report_float(row.get("majors"), 0)
        others = _report_float(row.get("others"), 0)
        symbol = _tokenomics_base_symbol(row.get("symbol"))
        coin_id = str(row.get("gecko_id") or "").strip() or None
        mapping_quality = (
            "curated_exact"
            if symbol and coin_id and _TOKENOMICS_CURATED_IDS.get(symbol) == coin_id
            else "unverified_symbol" if symbol else "project_only"
        )
        normalized.append({
            "snapshot_day": snapshot_day,
            "captured_at": captured_at,
            "source_key": "defillama_treasuries_public",
            "source_name": "DefiLlama Treasuries",
            "source_url": "https://defillama.com/treasuries",
            "external_id": external_id,
            "project_name": str(row.get("name") or "Unknown treasury"),
            "symbol": symbol or None,
            "coin_id": coin_id,
            "treasury_value_usd": total,
            "stablecoins_usd": stable,
            "majors_usd": majors,
            "own_tokens_usd": own,
            "other_tokens_usd": others,
            "liquid_ex_own_usd": max(0, total - own) if total is not None else None,
            "own_token_share_pct": (
                own / total * 100 if total not in (None, 0) else None
            ),
            "market_cap": _report_float(row.get("mcap"), None),
            "mapping_quality": mapping_quality,
            "data_quality": "third_party_aggregated_public_page",
        })
    return normalized


def _fetch_tokenomics_sources() -> tuple[dict[str, list[dict]], dict[str, str]]:
    """Fetch low-frequency public tokenomics sources outside report requests."""
    errors: dict[str, str] = {}
    source_rows: dict[str, list[dict]] = {
        "coin_gecko_markets": [],
        "defillama_unlocks": [],
        "defillama_treasuries": [],
    }

    def fetch_page(url):
        response = requests.get(
            url,
            headers=_TOKENOMICS_HEADERS,
            timeout=TOKENOMICS_HTTP_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        return _parse_defillama_page_data(response.text)

    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = {
            "defillama_unlocks": pool.submit(fetch_page, "https://defillama.com/unlocks"),
            "defillama_treasuries": pool.submit(fetch_page, "https://defillama.com/treasuries"),
        }
        for name, future in futures.items():
            try:
                source_rows[name] = future.result()
            except Exception as exc:
                errors[name] = str(exc)[:300]

    symbol_map, map_quality = _tokenomics_symbol_map(
        source_rows["defillama_unlocks"],
        source_rows["defillama_treasuries"],
    )
    requested = list(dict.fromkeys([
        *_tokenomics_priority_symbols(),
        *_TOKENOMICS_CURATED_IDS.keys(),
    ]))
    selected = [
        (symbol, symbol_map[symbol], map_quality.get(symbol, "unknown"))
        for symbol in requested if symbol in symbol_map
    ][:30]
    if selected:
        try:
            headers = dict(_TOKENOMICS_HEADERS)
            api_key = str(os.getenv("COINGECKO_API_KEY") or "").strip()
            if api_key:
                headers["x-cg-demo-api-key"] = api_key
            response = requests.get(
                "https://api.coingecko.com/api/v3/coins/markets",
                params={
                    "vs_currency": "usd",
                    "ids": ",".join(coin_id for _, coin_id, _ in selected),
                    "sparkline": "false",
                    "precision": "full",
                },
                headers=headers,
                timeout=TOKENOMICS_HTTP_TIMEOUT_SECONDS,
            )
            response.raise_for_status()
            payload = response.json()
            if not isinstance(payload, list):
                raise ValueError("CoinGecko markets response was not a list")
            reverse = {
                coin_id: (symbol, quality)
                for symbol, coin_id, quality in selected
            }
            source_rows["coin_gecko_markets"] = [
                {
                    **row,
                    "_mt7_symbol": reverse[str(row.get("id"))][0],
                    "_mapping_quality": reverse[str(row.get("id"))][1],
                }
                for row in payload
                if str(row.get("id")) in reverse
            ]
        except Exception as exc:
            errors["coin_gecko_markets"] = str(exc)[:300]
    else:
        errors["coin_gecko_markets"] = "no unambiguous report-relevant symbol mappings"
    return source_rows, errors


def _collect_tokenomics_evidence() -> dict:
    """Refresh supply, next-unlock, and treasury caches in one bounded write."""
    started = time.perf_counter()
    collected_at = datetime.utcnow().replace(microsecond=0).isoformat()
    source_rows, errors = _fetch_tokenomics_sources()
    asset_rows = []
    for row in source_rows.get("coin_gecko_markets") or []:
        market_cap = _report_float(row.get("market_cap"), None)
        fdv = _report_float(row.get("fully_diluted_valuation"), None)
        circulating = _report_float(row.get("circulating_supply"), None)
        total = _report_float(row.get("total_supply"), None)
        maximum = _report_float(row.get("max_supply"), None)
        denominator = maximum or total
        asset_rows.append({
            "captured_at": collected_at,
            "symbol": f"{row.get('_mt7_symbol')}_USDT",
            "coin_id": str(row.get("id") or ""),
            "name": row.get("name"),
            "source_key": "coingecko_markets",
            "source_name": "CoinGecko Markets",
            "source_url": f"https://www.coingecko.com/en/coins/{row.get('id')}",
            "mapping_quality": row.get("_mapping_quality") or "unknown",
            "current_price": _report_float(row.get("current_price"), None),
            "market_cap": market_cap,
            "fully_diluted_value": fdv,
            "circulating_supply": circulating,
            "total_supply": total,
            "max_supply": maximum,
            "float_pct": (
                circulating / denominator * 100
                if circulating is not None and denominator not in (None, 0) else None
            ),
            "fdv_market_cap_ratio": (
                fdv / market_cap
                if fdv is not None and market_cap not in (None, 0) else None
            ),
            "volume_24h": _report_float(row.get("total_volume"), None),
            "source_updated_at": _catalyst_iso(row.get("last_updated")),
            "observed_at": collected_at,
            "data_quality": "third_party_aggregated_api",
        })
    unlock_rows = _tokenomics_unlock_rows(
        source_rows.get("defillama_unlocks") or [],
        collected_at,
    )
    unlock_rows = list({
        row["external_id"]: row
        for row in unlock_rows if row.get("external_id")
    }.values())
    treasury_rows = _tokenomics_treasury_rows(
        source_rows.get("defillama_treasuries") or [],
        collected_at,
    )
    con = sqlite3.connect(DB_PATH, timeout=30)
    try:
        asset_columns = (
            "captured_at", "symbol", "coin_id", "name", "source_key", "source_name",
            "source_url", "mapping_quality", "current_price", "market_cap",
            "fully_diluted_value", "circulating_supply", "total_supply", "max_supply",
            "float_pct", "fdv_market_cap_ratio", "volume_24h", "source_updated_at",
            "observed_at", "data_quality",
        )
        if asset_rows:
            con.executemany(
                f"""
                INSERT OR REPLACE INTO tokenomics_asset_snapshots
                    ({",".join(asset_columns)})
                VALUES ({",".join("?" for _ in asset_columns)})
                """,
                [tuple(row.get(column) for column in asset_columns) for row in asset_rows],
            )
        unlock_columns = (
            "source_key", "source_name", "source_url", "external_id", "protocol_id",
            "project_name", "symbol", "coin_id", "unlock_at", "observed_at",
            "unlock_type", "category", "token_amount", "unlock_value_usd",
            "unlock_pct_float", "circulating_supply", "max_supply", "unlocked_pct",
            "mapping_quality", "data_quality", "raw_meta_json",
        )
        if unlock_rows:
            values = []
            for row in unlock_rows:
                packet = dict(row)
                packet["raw_meta_json"] = json.dumps(
                    row.get("raw_meta") or {},
                    sort_keys=True,
                )
                values.append(tuple(packet.get(column) for column in unlock_columns))
            updates = ",".join(
                f"{column}=excluded.{column}"
                for column in unlock_columns
                if column not in {"source_key", "external_id"}
            )
            con.executemany(
                f"""
                INSERT INTO token_unlock_events ({",".join(unlock_columns)})
                VALUES ({",".join("?" for _ in unlock_columns)})
                ON CONFLICT(source_key, external_id) DO UPDATE SET {updates}
                """,
                values,
            )
        treasury_columns = (
            "snapshot_day", "captured_at", "source_key", "source_name", "source_url",
            "external_id", "project_name", "symbol", "coin_id", "treasury_value_usd",
            "stablecoins_usd", "majors_usd", "own_tokens_usd", "other_tokens_usd",
            "liquid_ex_own_usd", "own_token_share_pct", "market_cap",
            "mapping_quality", "data_quality",
        )
        if treasury_rows:
            con.executemany(
                f"""
                INSERT OR REPLACE INTO token_treasury_snapshots
                    ({",".join(treasury_columns)})
                VALUES ({",".join("?" for _ in treasury_columns)})
                """,
                [
                    tuple(row.get(column) for column in treasury_columns)
                    for row in treasury_rows
                ],
            )
        latency_ms = round((time.perf_counter() - started) * 1000)
        counts = {
            "coin_gecko_markets": len(source_rows.get("coin_gecko_markets") or []),
            "defillama_unlocks": len(source_rows.get("defillama_unlocks") or []),
            "defillama_treasuries": len(source_rows.get("defillama_treasuries") or []),
        }
        con.execute(
            """
            INSERT OR REPLACE INTO tokenomics_collection_runs
                (collected_at,latency_ms,asset_snapshots,unlock_events,
                 treasury_snapshots,mapped_symbols,source_counts_json,source_errors_json)
            VALUES (?,?,?,?,?,?,?,?)
            """,
            (
                collected_at,
                latency_ms,
                len(asset_rows),
                len(unlock_rows),
                len(treasury_rows),
                len({row.get("symbol") for row in asset_rows if row.get("symbol")}),
                json.dumps(counts, sort_keys=True),
                json.dumps(errors, sort_keys=True),
            ),
        )
        cutoff = (datetime.utcnow() - timedelta(days=TOKENOMICS_RETENTION_DAYS)).isoformat()
        con.execute(
            "DELETE FROM tokenomics_asset_snapshots WHERE captured_at<?",
            (cutoff,),
        )
        con.execute(
            "DELETE FROM token_treasury_snapshots WHERE captured_at<?",
            (cutoff,),
        )
        con.execute(
            """
            DELETE FROM token_unlock_events
            WHERE unlock_at<? AND observed_at<?
            """,
            (cutoff, cutoff),
        )
        con.execute(
            "DELETE FROM tokenomics_collection_runs WHERE collected_at<?",
            ((datetime.utcnow() - timedelta(days=30)).isoformat(),),
        )
        con.commit()
    finally:
        con.close()
    return {
        "collected_at": collected_at,
        "latency_ms": latency_ms,
        "asset_snapshots": len(asset_rows),
        "unlock_events": len(unlock_rows),
        "treasury_snapshots": len(treasury_rows),
        "mapped_symbols": len({
            row.get("symbol") for row in asset_rows if row.get("symbol")
        }),
        "source_counts": counts,
        "errors": errors,
    }


