def _social_post_url(uri: str, handle: str) -> str:
    parts = str(uri or "").split("/")
    rkey = parts[-1] if parts else ""
    return (
        f"https://bsky.app/profile/{quote_plus(str(handle or ''))}/post/{quote_plus(rkey)}"
        if handle and rkey else "https://bsky.app/"
    )


def _parse_bluesky_search(
    payload: dict,
    *,
    topic_key: str,
    query_text: str,
    symbol: str | None,
    captured_at: str,
) -> dict:
    """Aggregate public posts without assigning a bullish/bearish trading score."""
    try:
        captured_dt = datetime.fromisoformat(captured_at)
    except Exception:
        captured_dt = datetime.utcnow()
    lower = captured_dt - timedelta(hours=6)
    posts = []
    for item in (payload or {}).get("posts") or []:
        record = item.get("record") or {}
        author = item.get("author") or {}
        indexed_at = _catalyst_iso(item.get("indexedAt") or record.get("createdAt"))
        try:
            published_dt = datetime.fromisoformat(indexed_at) if indexed_at else None
        except Exception:
            published_dt = None
        if published_dt and published_dt < lower:
            continue
        text = _catalyst_clean_text(record.get("text"), 320)
        if not text:
            continue
        handle = str(author.get("handle") or "")
        posts.append({
            "uri": str(item.get("uri") or ""),
            "url": _social_post_url(item.get("uri"), handle),
            "author_handle": handle,
            "published_at": indexed_at,
            "text": text,
            "like_count": int(item.get("likeCount") or 0),
            "repost_count": int(item.get("repostCount") or 0),
            "reply_count": int(item.get("replyCount") or 0),
        })
    authors = defaultdict(int)
    text_counts = defaultdict(int)
    for post in posts:
        authors[post["author_handle"] or "unknown"] += 1
        normalized = re.sub(r"\W+", " ", post["text"].lower()).strip()
        if normalized:
            text_counts[hashlib.sha256(normalized.encode("utf-8")).hexdigest()] += 1
    post_count = len(posts)
    top_author_share = (
        max(authors.values(), default=0) / post_count * 100 if post_count else None
    )
    duplicate_posts = sum(max(0, count - 1) for count in text_counts.values())
    duplicate_share = duplicate_posts / post_count * 100 if post_count else None
    engagement = sum(
        post["like_count"] + post["repost_count"] + post["reply_count"]
        for post in posts
    )
    ranked = sorted(
        posts,
        key=lambda post: (
            post["like_count"] + post["repost_count"] + post["reply_count"],
            post["published_at"] or "",
        ),
        reverse=True,
    )
    return {
        "captured_at": captured_at,
        "source_key": "bluesky_public_search",
        "source_name": "Bluesky Public AppView",
        "source_url": "https://docs.bsky.app/docs/api/app-bsky-feed-search-posts",
        "topic_key": topic_key,
        "query_text": query_text,
        "symbol": symbol,
        "post_count": post_count,
        "unique_authors": len(authors),
        "total_likes": sum(post["like_count"] for post in posts),
        "total_reposts": sum(post["repost_count"] for post in posts),
        "total_replies": sum(post["reply_count"] for post in posts),
        "top_author_share_pct": round(top_author_share, 1) if top_author_share is not None else None,
        "duplicate_text_share_pct": round(duplicate_share, 1) if duplicate_share is not None else None,
        "posts_per_hour": round(post_count / 6, 2),
        "engagement_per_post": round(engagement / post_count, 2) if post_count else 0,
        "examples": [
            {
                "url": post["url"],
                "author_handle": post["author_handle"],
                "published_at": post["published_at"],
                "text": post["text"],
                "engagement": (
                    post["like_count"] + post["repost_count"] + post["reply_count"]
                ),
            }
            for post in ranked[:3]
        ],
    }


def _fetch_social_sources() -> tuple[dict[str, dict], dict[str, str]]:
    """Fetch a bounded public social sample outside scan and report paths."""
    topics = dict(_SOCIAL_TOPIC_QUERIES)
    for base in _tokenomics_priority_symbols(limit=8):
        if base in {"BTC", "ETH", "SOL", "HYPE"}:
            continue
        if base not in _TOKENOMICS_CURATED_IDS:
            continue
        topics[base.lower()] = (base, f"{base}_USDT")
        if len(topics) >= 8:
            break

    def fetch_topic(topic_key, query_text, symbol):
        params = {
            "q": query_text,
            "limit": 50,
            "sort": "latest",
            "lang": "en",
        }
        # Bluesky documents direct public AppView access. The cached public
        # host can stall or return 403 on some VPS networks, so use the proven
        # non-authenticated AppView first and keep the cached host as fallback.
        last_error = None
        for host in ("https://api.bsky.app", "https://public.api.bsky.app"):
            try:
                response = requests.get(
                    f"{host}/xrpc/app.bsky.feed.searchPosts",
                    params=params,
                    headers=_SOCIAL_HEADERS,
                    timeout=SOCIAL_HTTP_TIMEOUT_SECONDS,
                )
                response.raise_for_status()
                return response.json()
            except Exception as exc:
                last_error = exc
        raise RuntimeError(str(last_error or "Bluesky public search unavailable"))

    results, errors = {}, {}
    with ThreadPoolExecutor(max_workers=min(4, len(topics))) as pool:
        futures = {
            key: pool.submit(fetch_topic, key, query, symbol)
            for key, (query, symbol) in topics.items()
        }
        for key, future in futures.items():
            try:
                results[key] = future.result()
            except Exception as exc:
                errors[key] = str(exc)[:300]
    return results, errors


def _collect_social_evidence() -> dict:
    """Persist aggregate activity, diversity, and manipulation-risk evidence."""
    started = time.perf_counter()
    captured_at = datetime.utcnow().replace(microsecond=0).isoformat()
    payloads, errors = _fetch_social_sources()
    rows = []
    for topic_key, payload in payloads.items():
        query, symbol = _SOCIAL_TOPIC_QUERIES.get(
            topic_key,
            (topic_key.upper(), f"{topic_key.upper()}_USDT"),
        )
        rows.append(_parse_bluesky_search(
            payload,
            topic_key=topic_key,
            query_text=query,
            symbol=symbol,
            captured_at=captured_at,
        ))
    con = sqlite3.connect(DB_PATH, timeout=20)
    try:
        for row in rows:
            baseline = [
                float(item[0])
                for item in con.execute(
                    """
                    SELECT posts_per_hour
                    FROM social_activity_snapshots
                    WHERE source_key=? AND topic_key=? AND captured_at<?
                      AND captured_at>=?
                    ORDER BY captured_at DESC
                    LIMIT 336
                    """,
                    (
                        row["source_key"],
                        row["topic_key"],
                        captured_at,
                        (datetime.utcnow() - timedelta(days=7)).isoformat(),
                    ),
                ).fetchall()
                if item[0] is not None
            ]
            baseline.sort()
            baseline_median = None
            if baseline:
                middle = len(baseline) // 2
                baseline_median = (
                    baseline[middle]
                    if len(baseline) % 2
                    else (baseline[middle - 1] + baseline[middle]) / 2
                )
            activity_delta = (
                (row["posts_per_hour"] / baseline_median - 1) * 100
                if baseline_median not in (None, 0) else None
            )
            flags = ["single_social_source"]
            if row["post_count"] < 15:
                flags.append("thin_sample")
            if row["unique_authors"] < 8:
                flags.append("low_author_diversity")
            if (
                row["top_author_share_pct"] is not None
                and row["top_author_share_pct"] > 35
            ):
                flags.append("author_concentration")
            if (
                row["duplicate_text_share_pct"] is not None
                and row["duplicate_text_share_pct"] > 20
            ):
                flags.append("duplicate_language")
            if len(baseline) < 4:
                flags.append("baseline_collecting")
            quality = (
                "concentrated"
                if "author_concentration" in flags or "duplicate_language" in flags
                else "thin"
                if "thin_sample" in flags or "low_author_diversity" in flags
                else "usable_single_source"
            )
            row.update({
                "activity_vs_baseline_pct": (
                    round(activity_delta, 1) if activity_delta is not None else None
                ),
                "baseline_observations": len(baseline),
                "evidence_quality": quality,
                "quality_flags": flags,
            })
        columns = (
            "captured_at", "source_key", "source_name", "source_url", "topic_key",
            "query_text", "symbol", "post_count", "unique_authors", "total_likes",
            "total_reposts", "total_replies", "top_author_share_pct",
            "duplicate_text_share_pct", "posts_per_hour", "engagement_per_post",
            "activity_vs_baseline_pct", "baseline_observations", "evidence_quality",
            "quality_flags_json", "examples_json", "source_time_quality",
        )
        values = []
        for row in rows:
            packet = dict(row)
            packet["quality_flags_json"] = json.dumps(
                row.get("quality_flags") or [],
                sort_keys=True,
            )
            packet["examples_json"] = json.dumps(
                row.get("examples") or [],
                sort_keys=True,
            )
            packet["source_time_quality"] = "post_timestamp"
            values.append(tuple(packet.get(column) for column in columns))
        if values:
            con.executemany(
                f"""
                INSERT OR REPLACE INTO social_activity_snapshots
                    ({",".join(columns)})
                VALUES ({",".join("?" for _ in columns)})
                """,
                values,
            )
        latency_ms = round((time.perf_counter() - started) * 1000)
        con.execute(
            """
            INSERT OR REPLACE INTO social_collection_runs
                (collected_at,latency_ms,stored_topics,total_posts,unique_authors,
                 source_counts_json,source_errors_json)
            VALUES (?,?,?,?,?,?,?)
            """,
            (
                captured_at,
                latency_ms,
                len(rows),
                sum(row["post_count"] for row in rows),
                len({
                    example.get("author_handle")
                    for row in rows for example in row.get("examples") or []
                    if example.get("author_handle")
                }),
                json.dumps({"bluesky_public_search": len(rows)}, sort_keys=True),
                json.dumps(errors, sort_keys=True),
            ),
        )
        cutoff = (datetime.utcnow() - timedelta(days=SOCIAL_RETENTION_DAYS)).isoformat()
        con.execute(
            "DELETE FROM social_activity_snapshots WHERE captured_at<?",
            (cutoff,),
        )
        con.execute(
            "DELETE FROM social_collection_runs WHERE collected_at<?",
            (cutoff,),
        )
        con.commit()
    finally:
        con.close()
    return {
        "collected_at": captured_at,
        "latency_ms": latency_ms,
        "stored_topics": len(rows),
        "total_posts": sum(row["post_count"] for row in rows),
        "source_counts": {"bluesky_public_search": len(rows)},
        "errors": errors,
    }


def _snapshot_market_context() -> bool:
    """Fetch BTC+ETH 1h RSI/trend and store in market_context_snapshots. Prunes rows older than 30 days."""
    try:
        def _coin_ctx(symbol):
            data = fetch_mexc(f"/contract/kline/{symbol}", params={"interval": "Min60", "limit": 100})
            if not data or not isinstance(data, dict):
                return None, None, None, None
            df = pd.DataFrame({
                "open":   data.get("open", []),
                "high":   data.get("high", []),
                "low":    data.get("low", []),
                "close":  data.get("close", []),
                "volume": data.get("vol", []),
            }).astype(float)
            if len(df) < 16:
                return None, None, None, None
            price = float(df["close"].iloc[-1])
            rsi_s = calc_rsi(df, 14).dropna()
            rsi   = float(rsi_s.iloc[-1]) if not rsi_s.empty else None
            try:
                ema20 = float(calc_ema(df, 20).dropna().iloc[-1])
                ema50 = float(calc_ema(df, 50).dropna().iloc[-1])
                trend = "BULLISH" if ema20 > ema50 else "BEARISH"
            except Exception:
                trend = "NEUTRAL"
            change_24h = None
            if len(df) >= 25:
                old = float(df["close"].iloc[-25])
                if old > 0:
                    change_24h = round((price - old) / old * 100, 4)
            return price, rsi, trend, change_24h

        ts = datetime.utcnow().isoformat()
        btc_price, btc_rsi, btc_trend, btc_change = _coin_ctx("BTC_USDT")
        eth_price, eth_rsi, eth_trend, _           = _coin_ctx("ETH_USDT")

        con = sqlite3.connect(DB_PATH)
        con.execute(
            "INSERT INTO market_context_snapshots (ts,btc_price,btc_rsi_1h,btc_trend,btc_change_24h,eth_price,eth_rsi_1h,eth_trend) VALUES (?,?,?,?,?,?,?,?)",
            (ts, btc_price, btc_rsi, btc_trend, btc_change, eth_price, eth_rsi, eth_trend),
        )
        cutoff = (datetime.utcnow() - timedelta(days=30)).isoformat()
        con.execute("DELETE FROM market_context_snapshots WHERE ts < ?", (cutoff,))
        con.commit()
        con.close()
        return True
    except Exception as e:
        print(f"[snapshot_market_context] {e}", file=sys.stderr)
        return False


def get_latest_market_context() -> dict | None:
    """Return the most recent market_context_snapshots row as a dict, or None."""
    try:
        con = sqlite3.connect(DB_PATH)
        row = con.execute(
            "SELECT ts,btc_price,btc_rsi_1h,btc_trend,btc_change_24h,eth_price,eth_rsi_1h,eth_trend FROM market_context_snapshots ORDER BY ts DESC LIMIT 1"
        ).fetchone()
        con.close()
        if not row:
            return None
        return {
            "ts": row[0], "btc_price": row[1], "btc_rsi_1h": row[2],
            "btc_trend": row[3], "btc_change_24h": row[4],
            "eth_price": row[5], "eth_rsi_1h": row[6], "eth_trend": row[7],
        }
    except Exception:
        return None


def log_signals(
    signals: list[dict],
    source: str = "live",
    allow_duplicate_open: bool = False,
) -> list[int | None]:
    """
    Append enriched signals to the history DB after every scan.
    Failures are swallowed — logging must never crash the scan.
    Duplicate guard: skip if an open (result IS NULL) signal already exists
    for the same symbol + direction + strategy_key. Different strategies may
    each hold the same symbol simultaneously — that is intentional.
    """
    inserted_ids: list[int | None] = []
    try:
        con = sqlite3.connect(DB_PATH)
        for sig in signals:
            entries = sig.get("entries") or [None, None, None]
            exits   = sig.get("exits")   or [None, None, None]
            skey = sig.get("strategy_key") or strategy_name_to_key(sig.get("strategy", ""))
            if not allow_duplicate_open:
                exists = con.execute("""
                    SELECT 1 FROM signals
                    WHERE symbol=? AND direction=? AND strategy_key=? AND source=? AND result IS NULL
                    LIMIT 1
                """, (sig["symbol"], sig["direction"], skey, source)).fetchone()
                if exists:
                    inserted_ids.append(None)
                    continue
            leverage_val = sig.get("leverage_cap") or sig.get("max_leverage") or None
            cur = con.execute("""
                INSERT INTO signals
                (logged_at, symbol, exchange, direction, strategy, strategy_key, conviction,
                 price, entry1, entry2, entry3, tp1, tp2, tp3, stop_loss,
                 atr_pct, volatility, funding_rate, rsi_1h, trend_score,
                 tags, signal_why, signal_json, data_quality, leverage,
                 flow_score, flow_confirmed, source)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                datetime.utcnow().isoformat(),
                sig["symbol"],
                sig.get("exchange", "MEXC"),
                sig["direction"],
                sig.get("strategy", ""),
                skey,
                sig.get("conviction", 0),
                sig.get("price", 0),
                entries[0], entries[1], entries[2],
                exits[0],   exits[1],   exits[2],
                sig.get("stop_loss"),
                sig.get("atr_pct"),
                sig.get("volatility"),
                sig.get("funding_rate"),
                sig.get("rsi_1h"),
                sig.get("trend_score"),
                ",".join(sig.get("tags", [])),
                sig.get("signal_why", ""),
                json.dumps(sig, default=str),
                sig.get("data_quality") or "current",
                leverage_val,
                sig.get("flow_score"),
                1 if sig.get("flow_confirmed") else (0 if sig.get("flow_confirmed") is False else None),
                source,
            ))
            inserted_ids.append(cur.lastrowid)
        con.commit()
        con.close()
    except Exception as e:
        print(f"log_signals error: {e}", file=sys.stderr)
    return inserted_ids


def load_risk_gates() -> dict:
    """Load local risk-gate configuration from data/risk_gates.json."""
    gates = copy.deepcopy(DEFAULT_RISK_GATES)
    try:
        if os.path.exists(RISK_GATES_PATH):
            with open(RISK_GATES_PATH, "r", encoding="utf-8") as f:
                raw = json.load(f)
            for key, cfg in (raw or {}).items():
                if key in gates and isinstance(cfg, dict):
                    gates[key].update(cfg)
    except Exception as e:
        print(f"load_risk_gates error: {e}", file=sys.stderr)

    for key, cfg in gates.items():
        cfg["key"] = key
        if cfg.get("mode") not in {"block", "shadow", "off"}:
            cfg["mode"] = DEFAULT_RISK_GATES[key]["mode"]
        vols = cfg.get("volatility") or DEFAULT_RISK_GATES[key]["volatility"]
        cfg["volatility"] = [str(v) for v in vols if str(v) in {"low", "medium", "high", "extreme"}]
        if not cfg["volatility"]:
            cfg["volatility"] = list(DEFAULT_RISK_GATES[key]["volatility"])
    return gates


def save_risk_gates(gates: dict) -> None:
    os.makedirs("data", exist_ok=True)
    # Preserve non-gate keys (e.g. disabled_builtins) already in the file.
    try:
        if os.path.exists(RISK_GATES_PATH):
            with open(RISK_GATES_PATH, "r", encoding="utf-8") as f:
                existing = json.load(f)
        else:
            existing = {}
    except Exception:
        existing = {}
    merged = {k: v for k, v in existing.items() if k not in DEFAULT_RISK_GATES}
    merged.update(gates)
    with open(RISK_GATES_PATH, "w", encoding="utf-8") as f:
        json.dump(merged, f, indent=2, sort_keys=True)


def get_risk_gate(gate_key: str) -> dict:
    return load_risk_gates()[gate_key]


def get_long_vol_gate() -> dict:
    return get_risk_gate("long_vol_long")


def _load_extreme_vol_firebreak() -> bool:
    """
    Read extreme_vol_firebreak from risk_gates.json.
    Returns True (gate ON) if the file is missing, malformed, or the key is absent.
    Never raises — scan must never fail due to a missing settings file.
    """
    try:
        if os.path.exists(RISK_GATES_PATH):
            with open(RISK_GATES_PATH, "r", encoding="utf-8") as f:
                raw = json.load(f)
            return bool(raw.get("extreme_vol_firebreak", True))
    except Exception:
        pass
    return True


def _save_extreme_vol_firebreak(val: bool) -> None:
    """Persist extreme_vol_firebreak to risk_gates.json, preserving all existing keys."""
    os.makedirs("data", exist_ok=True)
    try:
        with open(RISK_GATES_PATH, "r", encoding="utf-8") as f:
            existing = json.load(f)
    except Exception:
        existing = {}
    existing["extreme_vol_firebreak"] = bool(val)
    tmp = RISK_GATES_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(existing, f, indent=2, sort_keys=True)
    os.replace(tmp, RISK_GATES_PATH)


def _load_strategy_overrides() -> dict:
    """
    Read data/strategy_overrides.json.
    Returns {} if missing or malformed. Never raises.
    Structure: {"balanced": {"min_conviction": 65, "blocked_agent_regimes": [...]}, ...}
    """
    try:
        if os.path.exists(STRATEGY_OVERRIDES_PATH):
            with open(STRATEGY_OVERRIDES_PATH, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return {}


def _write_strategy_overrides(overrides: dict) -> None:
    """Atomically persist the complete built-in strategy override map."""
    os.makedirs(os.path.dirname(STRATEGY_OVERRIDES_PATH) or ".", exist_ok=True)
    cleaned = {
        str(key): value
        for key, value in (overrides or {}).items()
        if isinstance(value, dict) and value
    }
    tmp = STRATEGY_OVERRIDES_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(cleaned, f, indent=2, sort_keys=True)
    os.replace(tmp, STRATEGY_OVERRIDES_PATH)


def _save_strategy_override(strategy_key: str, field: str, value) -> None:
    """
    Persist a single field override for a built-in strategy.
    Preserves all existing overrides. Atomic write.
    Only permitted fields: ["min_conviction", "allowed_volatility", "blocked_agent_regimes"]
    """
    PERMITTED = {"min_conviction", "allowed_volatility", "blocked_agent_regimes"}
    if field not in PERMITTED:
        return
    os.makedirs("data", exist_ok=True)
    try:
        with open(STRATEGY_OVERRIDES_PATH, "r", encoding="utf-8") as f:
            existing = json.load(f)
    except Exception:
        existing = {}
    if strategy_key not in existing:
        existing[strategy_key] = {}
    existing[strategy_key][field] = value
    _write_strategy_overrides(existing)


def _normalize_agent_regime_list(raw) -> list[str]:
    """Return clean agent-regime labels without hard-coding the current taxonomy."""
    if not isinstance(raw, list):
        return []
    cleaned: list[str] = []
    for item in raw:
        label = str(item or "").strip().lower()
        if not label or not re.match(r"^[a-z][a-z0-9_]{1,48}$", label):
            continue
        if label not in cleaned:
            cleaned.append(label)
    return cleaned


def _suggestion_control_target(suggestion: dict) -> dict | None:
    """Return the built-in override controlled by a learner suggestion."""
    strategy = str(suggestion.get("strategy") or "").strip()
    if not strategy or strategy not in STRATEGIES:
        return None
    stype = suggestion.get("type")
    payload = suggestion.get("api_payload") or {}
    if stype == "threshold":
        value = payload.get("min_conviction")
        if value is None:
            value = suggestion.get("suggested_value")
        try:
            return {"strategy": strategy, "field": "min_conviction", "value": int(value)}
        except (TypeError, ValueError):
            return None
    if stype != "regime_suppress":
        return None
    blocked = _normalize_agent_regime_list(payload.get("blocked_agent_regimes"))
    regime = str(suggestion.get("regime") or "").strip().lower()
    if not blocked and regime and regime not in {"low", "medium", "high", "extreme"}:
        blocked = _normalize_agent_regime_list([regime])
    if blocked:
        return {"strategy": strategy, "field": "blocked_agent_regimes", "value": blocked}
    allowed = payload.get("allowed_volatility")
    if isinstance(allowed, list) and allowed:
        normalized = [str(item).strip().lower() for item in allowed if str(item).strip()]
        return {"strategy": strategy, "field": "allowed_volatility", "value": normalized}
    return None


def _suggestion_effective_control(
    suggestion: dict,
    overrides: dict | None = None,
) -> dict:
    """Describe whether a suggestion currently changes built-in scan behavior."""
    target = _suggestion_control_target(suggestion)
    if not target:
        return {
            "managed": False,
            "active": False,
            "strategy": suggestion.get("strategy"),
            "field": None,
            "expected": None,
            "actual": None,
            "runtime_actual": None,
            "proposal_baseline": suggestion.get("current_value"),
            "proposal_baseline_consistent": None,
        }
    current = (overrides if overrides is not None else _load_strategy_overrides()).get(
        target["strategy"], {}
    )
    actual = current.get(target["field"])
    runtime_actual = actual
    if target["field"] == "min_conviction" and runtime_actual is None:
        try:
            runtime_actual = get_strategy_config(
                target["strategy"],
                include_disabled=True,
            ).get("min_conviction")
        except Exception:
            runtime_actual = None
    expected = target["value"]
    if target["field"] == "blocked_agent_regimes":
        actual_normalized = _normalize_agent_regime_list(actual)
        active = bool(expected) and all(item in actual_normalized for item in expected)
        actual = actual_normalized
    elif target["field"] == "allowed_volatility":
        actual_normalized = [
            str(item).strip().lower()
            for item in (actual if isinstance(actual, list) else [])
            if str(item).strip()
        ]
        active = actual_normalized == expected
        actual = actual_normalized
    else:
        try:
            active = int(actual) == int(expected)
        except (TypeError, ValueError):
            active = False
    proposal_baseline = suggestion.get("current_value")
    proposal_baseline_consistent = None
    if (
        target["field"] == "min_conviction"
        and proposal_baseline is not None
        and runtime_actual is not None
    ):
        try:
            proposal_baseline_consistent = (
                int(proposal_baseline) == int(runtime_actual)
            )
        except (TypeError, ValueError):
            proposal_baseline_consistent = False
    return {
        "managed": True,
        "active": bool(active),
        "strategy": target["strategy"],
        "field": target["field"],
        "expected": expected,
        "actual": actual,
        "runtime_actual": runtime_actual,
        "proposal_baseline": proposal_baseline,
        "proposal_baseline_consistent": proposal_baseline_consistent,
    }


SUGGESTION_CONTRACT_VERSION = "mt7_suggestion_v1"
_SUGGESTION_CAPITAL_FIELDS = {
    "leverage",
    "leverage_cap",
    "max_leverage",
    "risk_pct",
    "risk_pct_per_trade",
    "position_size",
    "position_size_usd",
    "size_usd",
    "max_position_size_usd",
    "max_standard_position_usd",
    "max_open_positions",
    "max_positions",
    "margin_mode",
    "paper_margin_mode",
}
_SUGGESTION_EXECUTION_FIELDS = {
    "live_trading_enabled",
    "execution_mode",
    "auto_execute",
    "silent_automation",
}
_SUGGESTION_FIELD_META = {
    "min_conviction": ("Minimum conviction", "score points"),
    "blocked_agent_regimes": ("Blocked agent regimes", "regime labels"),
    "allowed_volatility": ("Allowed volatility", "volatility regimes"),
    "leverage": ("Leverage", "×"),
    "leverage_cap": ("Maximum leverage", "×"),
    "max_leverage": ("Maximum leverage", "×"),
    "risk_pct": ("Risk sizing input", "% of sizing balance"),
    "risk_pct_per_trade": ("Risk sizing input", "% of sizing balance"),
    "position_size": ("Position notional", "USD"),
    "position_size_usd": ("Position notional", "USD"),
    "size_usd": ("Position notional", "USD"),
    "max_position_size_usd": ("Maximum position notional", "USD"),
    "max_standard_position_usd": ("Maximum standard position", "USD"),
    "max_open_positions": ("Maximum open positions", "positions"),
    "max_positions": ("Maximum open positions", "positions"),
    "margin_mode": ("Margin mode", "mode"),
    "paper_margin_mode": ("Paper margin mode", "mode"),
    "live_trading_enabled": ("Live trading master gate", "boolean"),
    "execution_mode": ("Execution mode", "mode"),
    "auto_execute": ("Automatic execution", "boolean"),
    "silent_automation": ("Silent automation", "boolean"),
}


def _suggestion_current_value(
    field: str,
    suggestion: dict,
    control: dict,
    strategy_cfg: dict,
    paper_cfg: dict,
    goals: dict,
):
    """Resolve the current value from the owning runtime config, not prose."""
    if field == control.get("field"):
        runtime_actual = control.get("runtime_actual")
        if runtime_actual is not None:
            return runtime_actual
    aliases = {
        "leverage": "max_leverage",
        "leverage_cap": "max_leverage",
        "risk_pct": "risk_pct_per_trade",
        "position_size": "max_standard_position_usd",
        "position_size_usd": "max_standard_position_usd",
        "size_usd": "max_standard_position_usd",
        "max_position_size_usd": "max_standard_position_usd",
        "margin_mode": "paper_margin_mode",
        "max_positions": "max_open_positions",
    }
    canonical = aliases.get(field, field)
    if canonical in strategy_cfg:
        return strategy_cfg.get(canonical)
    if canonical in paper_cfg:
        return paper_cfg.get(canonical)
    if canonical in goals:
        return goals.get(canonical)
    if field == "live_trading_enabled":
        return bool(LIVE_TRADING_ENABLED)
    if field in {"auto_execute", "silent_automation"}:
        return False
    return suggestion.get("current_value")


def _suggestion_change_set(suggestion: dict, control: dict) -> list[dict]:
    """Normalize legacy and future suggestion payloads into explicit field changes."""
    strategy = str(suggestion.get("strategy") or "").strip()
    try:
        strategy_cfg = (
            get_strategy_config(strategy, include_disabled=True)
            if strategy else {}
        )
    except Exception:
        strategy_cfg = {}
    try:
        paper_cfg = _load_paper_config()
    except Exception:
        paper_cfg = dict(_PAPER_CONFIG_DEFAULT)
    goals = _load_goals()
    supplied = suggestion.get("change_set")
    changes: list[dict] = []
    if isinstance(supplied, list):
        for item in supplied:
            if not isinstance(item, dict) or not item.get("field"):
                continue
            field = str(item["field"]).strip()
            proposed = item.get("proposed")
            if proposed is None:
                continue
            label, unit = _SUGGESTION_FIELD_META.get(
                field,
                (field.replace("_", " ").title(), "value"),
            )
            current = _suggestion_current_value(
                field, suggestion, control, strategy_cfg, paper_cfg, goals
            )
            changes.append({
                **item,
                "field": field,
                "label": item.get("label") or label,
                "unit": item.get("unit") or unit,
                "current": current if current is not None else item.get("current"),
                "proposed": proposed,
            })
    if changes:
        return changes

    stype = str(suggestion.get("type") or "")
    payload = suggestion.get("api_payload") or {}
    if stype == "new_strategy":
        proposed = payload.get("name") or suggestion.get("proposed_name") or strategy
        changes.append({
            "field": "strategy_definition",
            "label": "Strategy definition",
            "current": "not present",
            "proposed": proposed or "new custom strategy",
            "unit": "strategy",
        })
    for field, proposed in payload.items():
        if field in {"name", "key", "base_key", "description"}:
            continue
        label, unit = _SUGGESTION_FIELD_META.get(
            field,
            (field.replace("_", " ").title(), "value"),
        )
        current_value = _suggestion_current_value(
            field, suggestion, control, strategy_cfg, paper_cfg, goals
        )
        if current_value is None and stype == "new_strategy":
            current_value = "not applicable (new strategy)"
        changes.append({
            "field": field,
            "label": label,
            "current": current_value,
            "proposed": proposed,
            "unit": unit,
        })
    if not changes and control.get("field"):
        field = str(control["field"])
        label, unit = _SUGGESTION_FIELD_META.get(
            field,
            (field.replace("_", " ").title(), "value"),
        )
        changes.append({
            "field": field,
            "label": label,
            "current": control.get("runtime_actual"),
            "proposed": control.get("expected"),
            "unit": unit,
        })
    return changes


def _suggestion_capital_impact(changes: list[dict]) -> dict | None:
    fields = {str(change.get("field") or "") for change in changes}
    if not fields.intersection(_SUGGESTION_CAPITAL_FIELDS):
        return None
    paper_cfg = _load_paper_config()
    balance = float(paper_cfg.get("account_balance_usd") or 0.0)
    current = {str(c.get("field")): c.get("current") for c in changes}
    proposed = {str(c.get("field")): c.get("proposed") for c in changes}

    def first(mapping: dict, names: tuple[str, ...], fallback=None):
        for name in names:
            if mapping.get(name) is not None:
                return mapping.get(name)
        return fallback

    current_risk = first(
        current,
        ("risk_pct_per_trade", "risk_pct"),
        paper_cfg.get("risk_pct_per_trade"),
    )
    proposed_risk = first(
        proposed,
        ("risk_pct_per_trade", "risk_pct"),
        current_risk,
    )
    current_notional = first(
        current,
        (
            "position_size_usd",
            "position_size",
            "size_usd",
            "max_position_size_usd",
            "max_standard_position_usd",
        ),
    )
    proposed_notional = first(
        proposed,
        (
            "position_size_usd",
            "position_size",
            "size_usd",
            "max_position_size_usd",
            "max_standard_position_usd",
        ),
        current_notional,
    )
    current_leverage = first(
        current,
        ("leverage", "leverage_cap", "max_leverage"),
    )
    proposed_leverage = first(
        proposed,
        ("leverage", "leverage_cap", "max_leverage"),
        current_leverage,
    )
    current_max_positions = first(
        current,
        ("max_open_positions", "max_positions"),
        paper_cfg.get("max_open_positions"),
    )
    proposed_max_positions = first(
        proposed,
        ("max_open_positions", "max_positions"),
        current_max_positions,
    )

    def numeric(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    risk_now = numeric(current_risk)
    risk_next = numeric(proposed_risk)
    notional_now = numeric(current_notional)
    notional_next = numeric(proposed_notional)
    lev_now = numeric(current_leverage)
    lev_next = numeric(proposed_leverage)
    pos_now = numeric(current_max_positions)
    pos_next = numeric(proposed_max_positions)
    return {
        "sizing_balance_usd": round(balance, 2),
        "target_risk_budget_current_usd": (
            round(balance * risk_now / 100.0, 2) if risk_now is not None else None
        ),
        "target_risk_budget_proposed_usd": (
            round(balance * risk_next / 100.0, 2) if risk_next is not None else None
        ),
        "position_notional_current_usd": notional_now,
        "position_notional_proposed_usd": notional_next,
        "estimated_margin_current_usd": (
            round(notional_now / lev_now, 2)
            if notional_now is not None and lev_now and lev_now > 0 else None
        ),
        "estimated_margin_proposed_usd": (
            round(notional_next / lev_next, 2)
            if notional_next is not None and lev_next and lev_next > 0 else None
        ),
        "max_concurrent_notional_current_usd": (
            round(notional_now * pos_now, 2)
            if notional_now is not None and pos_now is not None else None
        ),
        "max_concurrent_notional_proposed_usd": (
            round(notional_next * pos_next, 2)
            if notional_next is not None and pos_next is not None else None
        ),
        "loss_semantics": (
            "Risk percentage is a sizing input, not a guaranteed maximum loss. "
            "Stops, leverage, fees, slippage, gaps, funding, and liquidation can "
            "produce a different realized result."
        ),
        "liquidation_semantics": (
            "Liquidation distance must be calculated from the target exchange, "
            "symbol risk tier, margin mode, collateral, and current positions. "
            "MT7 must not infer one universal leverage-only liquidation price."
        ),
    }


def _suggestion_explainability_contract(
    suggestion: dict,
    control: dict | None = None,
) -> dict:
    """Build the authoritative human-readable contract for any suggestion type."""
    control = control or _suggestion_effective_control(suggestion)
    changes = _suggestion_change_set(suggestion, control)
    fields = {str(change.get("field") or "") for change in changes}
    capital_fields = sorted(fields.intersection(_SUGGESTION_CAPITAL_FIELDS))
    execution_fields = sorted(fields.intersection(_SUGGESTION_EXECUTION_FIELDS))
    restricted = bool(capital_fields or execution_fields)
    if execution_fields:
        classification = "restricted_execution_change"
    elif capital_fields:
        classification = "restricted_capital_change"
    else:
        classification = "strategy_configuration_change"

    change_phrases = []
    missing: list[str] = []
    for change in changes:
        current = change.get("current")
        proposed = change.get("proposed")
        if current is None:
            missing.append(f"current value for {change.get('field')}")
        change_phrases.append(
            f"{change.get('label')}: {current if current is not None else 'unknown'} "
            f"→ {proposed} {change.get('unit') or ''}".strip()
        )
    if not changes:
        missing.append("explicit change set")
    strategy_factory = None
    if suggestion.get("type") == "new_strategy":
        strategy_factory = _validate_strategy_factory_contract({
            **suggestion,
            **(suggestion.get("strategy_factory_contract") or {}),
        })
        missing.extend(
            f"strategy factory: {field}"
            for field in strategy_factory.get("missing", [])
        )
        missing.extend(
            f"restricted strategy field: {field}"
            for field in strategy_factory.get("restricted_fields", [])
        )

    evidence = dict(suggestion.get("evidence") or {})
    evidence.setdefault("source", suggestion.get("objective") or suggestion.get("type"))
    evidence.setdefault("sample_size", suggestion.get("sample_size"))
    evidence.setdefault("confidence", suggestion.get("confidence") or "unknown")
    evidence.setdefault("forward_tested", suggestion.get("status") in {"evaluated", "applied"})
    if evidence.get("sample_size") is None:
        missing.append("evidence sample size")

    expected = dict(suggestion.get("expected_impact") or {})
    expected.setdefault(
        "benefit",
        suggestion.get("expected_net_ev_delta")
        or suggestion.get("expected_ev_label")
        or suggestion.get("expected_win_rate_delta")
        or "No quantified benefit supplied.",
    )
    expected.setdefault(
        "trade_count_effect",
        suggestion.get("expected_trade_count_delta") or "Not quantified.",
    )
    expected.setdefault(
        "uncertainty",
        "Historical or shadow evidence does not guarantee future profitability.",
    )
    downside = suggestion.get("downside") or (
        "May reduce opportunity count or underperform when market conditions change."
    )
    rollback = dict(suggestion.get("rollback_plan") or {})
    rollback.setdefault(
        "condition",
        "Roll back if the forward Paper cohort underperforms its pre-trial baseline "
        "or breaches its declared risk gate.",
    )
    rollback.setdefault(
        "action",
        "Restore the exact pre-trial values and park the suggestion.",
    )

    suggestion_id = str(suggestion.get("id") or "SUGGESTION")
    application_supported = str(suggestion.get("type") or "") in {
        "threshold",
        "regime_suppress",
        "new_strategy",
    }
    confirmation_phrase = f"APPROVE {suggestion_id}" if restricted else None
    application_policy = {
        "auto_apply_allowed": False,
        "explicit_user_approval_required": True,
        "acknowledgement_required": True,
        "restricted": restricted,
        "restricted_fields": capital_fields + execution_fields,
        "confirmation_phrase": confirmation_phrase,
        "application_supported": application_supported,
        "target_lane": "serial_paper_config_trial",
        "live_behavior_change_allowed": False,
    }
    scope = dict(suggestion.get("scope") or {})
    scope.setdefault("strategy", suggestion.get("strategy") or "system")
    scope.setdefault("target_mode", "paper_trial_after_review")
    scope.setdefault("exchange", "all_configured")
    scope.setdefault("direction", suggestion.get("direction") or "both")
    scope.setdefault("regime", suggestion.get("regime") or "all")
    fingerprint_payload = {
        "id": suggestion_id,
        "scope": scope,
        "changes": changes,
        "baseline": {
            "field": control.get("field"),
            "runtime_actual": control.get("runtime_actual"),
        },
    }
    fingerprint = hashlib.sha256(
        json.dumps(fingerprint_payload, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()[:16]
    return {
        "version": SUGGESTION_CONTRACT_VERSION,
        "classification": classification,
        "title": suggestion.get("title") or suggestion.get("evidence_summary") or suggestion_id,
        "scope": scope,
        "change_set": changes,
        "plain_language": {
            "what_changes": "; ".join(change_phrases) or "No explicit change supplied.",
            "why": suggestion.get("reasoning") or suggestion.get("evidence_summary") or "No rationale supplied.",
            "expected_benefit": expected.get("benefit"),
            "downside": downside,
            "rollback": f"{rollback.get('condition')} {rollback.get('action')}",
        },
        "evidence": evidence,
        "expected_impact": expected,
        "downside": downside,
        "capital_impact": _suggestion_capital_impact(changes),
        "authority": {
            "current_mode": control.get("mode"),
            "managed_field": control.get("field"),
            "runtime_actual": control.get("runtime_actual"),
            "proposal_baseline": control.get("proposal_baseline"),
            "proposal_baseline_consistent": control.get("proposal_baseline_consistent"),
        },
        "application_policy": application_policy,
        "rollback_plan": rollback,
        "strategy_factory": strategy_factory,
        "audit": {
            "baseline_fingerprint": fingerprint,
            "generated_at": datetime.now(timezone.utc).isoformat(),
        },
        "completeness": {
            "complete": not missing,
            "missing": missing,
        },
    }


def _suggestion_application_gate(
    suggestion: dict,
    body: dict | None,
) -> tuple[bool, str | None, dict]:
    """Require an acknowledged, current, understandable contract before mutation."""
    body = body if isinstance(body, dict) else {}
    control = _suggestion_effective_control(suggestion)
    contract = _suggestion_explainability_contract(suggestion, control)
    if control.get("proposal_baseline_consistent") is False:
        return False, (
            "Suggestion baseline is stale. Recompute it from runtime_actual before "
            "starting any applied trial."
        ), contract
    if not contract["completeness"]["complete"]:
        return False, (
            "Suggestion explanation is incomplete: "
            + ", ".join(contract["completeness"]["missing"])
        ), contract
    if body.get("suggestion_contract_version") != SUGGESTION_CONTRACT_VERSION:
        return False, "Current suggestion contract version was not acknowledged.", contract
    if body.get("acknowledge_explainability") is not True:
        return False, "Explicit acknowledgement of the suggestion explanation is required.", contract
    if body.get("baseline_fingerprint") != contract["audit"]["baseline_fingerprint"]:
        return False, (
            "Suggestion baseline changed after review. Refresh the suggestion and "
            "approve the current contract."
        ), contract
    policy = contract["application_policy"]
    if not policy.get("application_supported"):
        return False, "This suggestion type is advisory only and has no safe application handler.", contract
    expected_phrase = policy.get("confirmation_phrase")
    if expected_phrase and str(body.get("confirmation") or "").strip() != expected_phrase:
        return False, (
            f"Restricted change requires the exact confirmation phrase: {expected_phrase}"
        ), contract
    return True, None, contract


def _annotate_suggestion_authority(suggestions: list[dict]) -> list[dict]:
    """Expose config authority separately from research workflow status."""
    overrides = _load_strategy_overrides()
    annotated: list[dict] = []
    applied_statuses = {"evaluating", "applied"}
    shadow_statuses = {"pending", "pending_review", "shadow_evaluating", "parked"}
    for original in suggestions:
        suggestion = dict(original)
        control = _suggestion_effective_control(suggestion, overrides)
        status = str(suggestion.get("status") or "")
        conflict = bool(
            control["managed"]
            and (
                (control["active"] and status in shadow_statuses)
                or (not control["active"] and status in applied_statuses)
            )
        )
        if status == "superseded":
            mode = "superseded"
            conflict = False
        elif control["active"] and status in applied_statuses:
            mode = "applied_config"
        elif status in {"pending", "pending_review"}:
            mode = "proposed_read_only"
        elif status == "shadow_evaluating" and not control["active"]:
            mode = "shadow_read_only"
        elif status == "parked" and not control["active"]:
            mode = "parked_read_only"
        elif conflict:
            mode = "state_conflict"
        else:
            mode = "none"
        suggestion["control_authority"] = {
            **control,
            "mode": mode,
            "state_consistent": not conflict,
        }
        suggestion["state_conflict"] = conflict
        suggestion["baseline_conflict"] = (
            control.get("proposal_baseline_consistent") is False
        )
        suggestion["explainability"] = _suggestion_explainability_contract(
            suggestion,
            suggestion["control_authority"],
        )
        suggestion["restricted_change"] = bool(
            suggestion["explainability"]["application_policy"]["restricted"]
        )
        annotated.append(suggestion)
    return annotated


def _suggestion_evaluation_conflicts(
    suggestions: list[dict],
    candidate: dict,
) -> list[dict]:
    """Keep applied trials serial per strategy, not globally serial."""
    candidate_id = str(candidate.get("id") or "")
    candidate_strategy = str(candidate.get("strategy") or "").strip()
    return [
        suggestion for suggestion in suggestions
        if suggestion.get("status") == "evaluating"
        and str(suggestion.get("id") or "") != candidate_id
        and (
            not candidate_strategy
            or not str(suggestion.get("strategy") or "").strip()
            or str(suggestion.get("strategy") or "").strip()
            == candidate_strategy
        )
    ]


def _revert_suggestion_config(suggestion: dict) -> tuple[bool, str | None, dict]:
    """Remove only the built-in override owned by one suggestion."""
    target = _suggestion_control_target(suggestion)
    if not target:
        return False, "this suggestion does not map to a reversible built-in override", {}
    overrides = _load_strategy_overrides()
    strategy_values = dict(overrides.get(target["strategy"]) or {})
    field = target["field"]
    if field not in strategy_values:
        return True, None, {"changed": False, **target}
    changed = False
    if field == "blocked_agent_regimes":
        current = _normalize_agent_regime_list(strategy_values.get(field))
        remaining = [item for item in current if item not in set(target["value"])]
        changed = remaining != current
        if remaining:
            strategy_values[field] = remaining
        else:
            strategy_values.pop(field, None)
    elif field == "allowed_volatility":
        current = [
            str(item).strip().lower()
            for item in (strategy_values.get(field) or [])
            if str(item).strip()
        ]
        if current == target["value"]:
            strategy_values.pop(field, None)
            changed = True
    else:
        try:
            matches = int(strategy_values.get(field)) == int(target["value"])
        except (TypeError, ValueError):
            matches = False
        if matches:
            strategy_values.pop(field, None)
            changed = True
    if strategy_values:
        overrides[target["strategy"]] = strategy_values
    else:
        overrides.pop(target["strategy"], None)
    if changed:
        _write_strategy_overrides(overrides)
    return True, None, {"changed": changed, **target}


def _reconcile_legacy_suggestion_authority() -> dict:
    """Repair legacy shadow labels for controls that are already active.

    The earliest applied suggestion becomes the owner. Later suggestions for the
    exact same active control become superseded. Scan behavior is never changed.
    """
    data = _load_suggestions_data()
    suggestions = data.get("suggestions", [])
    overrides = _load_strategy_overrides()
    groups: dict[tuple, list[dict]] = defaultdict(list)
    eligible = {"pending", "pending_review", "shadow_evaluating", "parked", "evaluating", "applied"}
    for suggestion in suggestions:
        status = str(suggestion.get("status") or "")
        control = _suggestion_effective_control(suggestion, overrides)
        target = _suggestion_control_target(suggestion)
        if not target or not control["active"] or not suggestion.get("applied_at") or status not in eligible:
            continue
        value = target["value"]
        canonical_value = tuple(value) if isinstance(value, list) else value
        groups[(target["strategy"], target["field"], canonical_value)].append(suggestion)

    changed: list[dict] = []
    now = datetime.utcnow().isoformat()
    for members in groups.values():
        members.sort(
            key=lambda item: (
                0 if item.get("status") == "applied" else 1,
                0 if item.get("status") == "evaluating" else 1,
                str(item.get("applied_at") or "9999"),
                str(item.get("id") or ""),
            )
        )
        owner = members[0]
        if owner.get("status") in {"pending", "pending_review", "shadow_evaluating", "parked"}:
            previous = owner.get("status")
            owner["status"] = "applied"
            owner["previous_status"] = previous
            owner["authority_reconciled_at"] = now
            owner["authority_reconcile_reason"] = "active override predates explicit authority states"
            owner["shadow_mode"] = False
            changed.append({"id": owner.get("id"), "from": previous, "to": "applied"})
        for duplicate in members[1:]:
            previous = duplicate.get("status")
            if previous == "superseded":
                continue
            duplicate["status"] = "superseded"
            duplicate["previous_status"] = previous
            duplicate["superseded_by"] = owner.get("id")
            duplicate["authority_reconciled_at"] = now
            duplicate["authority_reconcile_reason"] = "duplicate of an earlier active control"
            duplicate["shadow_mode"] = False
            changed.append({"id": duplicate.get("id"), "from": previous, "to": "superseded"})
    if changed:
        _write_suggestions_data(data)
        _append_experiment_record({
            "id": f"authority_reconcile_{now}",
            "type": "suggestion_authority_reconciled",
            "reconciled_at": now,
            "changes": changed,
            "active_override_strategies": sorted(overrides),
            "scan_behavior_changed": False,
        })
    return {
        "changed_count": len(changed),
        "changes": changed,
        "active_override_strategies": sorted(overrides),
    }


def _append_experiment_record(record: dict) -> None:
    """Append a reversible learner experiment record to data/experiment_ledger.json."""
    os.makedirs("data", exist_ok=True)
    try:
        with open(EXPERIMENT_LEDGER_PATH, "r", encoding="utf-8") as f:
            ledger = json.load(f)
        if not isinstance(ledger, list):
            ledger = []
    except Exception:
        ledger = []
    ledger.append(record)
    tmp = EXPERIMENT_LEDGER_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(ledger, f, indent=2, sort_keys=True)
    os.replace(tmp, EXPERIMENT_LEDGER_PATH)


def _read_experiment_ledger() -> list[dict]:
    try:
        if os.path.exists(EXPERIMENT_LEDGER_PATH):
            with open(EXPERIMENT_LEDGER_PATH, encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, list) else []
    except Exception as e:
        print(f"[experiment ledger] read error: {e}", file=sys.stderr)
    return []


def _append_experiment_record_once(record: dict, key: str = "id") -> bool:
    """Append a research experiment if its stable id is not already present."""
    os.makedirs("data", exist_ok=True)
    ledger = _read_experiment_ledger()
    rid = record.get(key)
    if rid and any(item.get(key) == rid for item in ledger if isinstance(item, dict)):
        return False
    ledger.append(record)
    tmp = EXPERIMENT_LEDGER_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(ledger, f, indent=2, sort_keys=True)
    os.replace(tmp, EXPERIMENT_LEDGER_PATH)
    return True


def _learning_json(raw, default):
    if isinstance(raw, (dict, list)):
        return raw
    try:
        value = json.loads(raw or "")
        return value if isinstance(value, type(default)) else default
    except Exception:
        return default


RESEARCH_EXPERIMENT_ACTIVE_STATUSES = {"active", "collecting", "review"}
RESEARCH_EXPERIMENT_TERMINAL_STATUSES = {
    "falsified",
    "inconclusive",
    "promotion_candidate",
    "completed",
    "rolled_back",
    "parked",
    "cancelled",
}
RESEARCH_MAX_BEHAVIORAL_EXPERIMENTS = 2
RESEARCH_MAX_SHADOW_EXPERIMENTS = 10


def _ensure_research_orchestrator_schema() -> None:
    """Idempotent lazy migration for app imports and existing deployments."""
    con = sqlite3.connect(DB_PATH)
    try:
        tables = {
            str(row[0]) for row in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        }
        if "learning_experiments" not in tables:
            return
        for col, sql_type in [
            ("idea_type", "TEXT NOT NULL DEFAULT 'new_strategy'"),
            ("decision_surface", "TEXT NOT NULL DEFAULT 'signal_generation'"),
            ("lifecycle_state", "TEXT NOT NULL DEFAULT 'collecting'"),
            ("hypothesis_family", "TEXT"),
            ("conflict_keys_json", "TEXT NOT NULL DEFAULT '[]'"),
            ("evaluator", "TEXT NOT NULL DEFAULT 'isolated_strategy_cohort'"),
            ("treatment_pct", "INTEGER NOT NULL DEFAULT 100"),
            ("authority_ceiling", "TEXT NOT NULL DEFAULT 'paper'"),
            ("scheduler_managed", "INTEGER NOT NULL DEFAULT 0"),
            ("last_progress_at", "TEXT"),
            ("blocked_reason", "TEXT"),
            ("extension_count", "INTEGER NOT NULL DEFAULT 0"),
            ("champion_experiment_id", "TEXT"),
            ("probation_stage", "TEXT NOT NULL DEFAULT 'initial'"),
        ]:
            try:
                con.execute(
                    f"ALTER TABLE learning_experiments ADD COLUMN {col} {sql_type}"
                )
            except sqlite3.OperationalError:
                pass
        con.execute("""
            CREATE TABLE IF NOT EXISTS learning_experiment_assignments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                experiment_id TEXT NOT NULL,
                assignment_key TEXT NOT NULL,
                paper_trade_id INTEGER,
                signal_id INTEGER,
                assigned_at TEXT NOT NULL,
                symbol TEXT NOT NULL,
                strategy_key TEXT NOT NULL,
                arm TEXT NOT NULL,
                bucket INTEGER NOT NULL,
                decision TEXT NOT NULL DEFAULT 'observed',
                eligible INTEGER NOT NULL DEFAULT 1,
                policy_fingerprint TEXT,
                outcome_source TEXT,
                result TEXT,
                pnl_pct REAL,
                closed_at TEXT,
                metadata_json TEXT NOT NULL DEFAULT '{}',
                UNIQUE(experiment_id, assignment_key)
            )
        """)
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_learning_assignments_experiment
            ON learning_experiment_assignments
               (experiment_id, arm, result, closed_at)
        """)
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_learning_assignments_trade
            ON learning_experiment_assignments (paper_trade_id, signal_id)
        """)
        con.commit()
    finally:
        con.close()


def _research_experiment_contract_from_row(row: dict) -> dict:
    """Rehydrate an orchestrator contract from a learning-ledger row."""
    scope = _learning_json(row.get("scope_json"), {})
    contract = scope.get("orchestrator_contract")
    if isinstance(contract, dict):
        return contract
    return _research_normalize_contract({
        "idea_type": row.get("idea_type") or row.get("family"),
        "target_strategy": row.get("strategy_key"),
        "hypothesis_family": row.get("hypothesis_family") or row.get("family"),
        "hypothesis": row.get("hypothesis"),
        "minimum_closed_trades": (
            _learning_json(row.get("evidence_rules_json"), {}).get(
                "minimum_closed_trades"
            )
        ),
        "minimum_elapsed_days": (
            _learning_json(row.get("evidence_rules_json"), {}).get(
                "minimum_elapsed_days"
            )
        ),
        "treatment_pct": row.get("treatment_pct"),
        "authority_ceiling": row.get("authority_ceiling"),
    })


def _research_contract_for_item(item: dict) -> dict:
    """Translate a research-ledger item into the canonical experiment shape."""
    control = item.get("rule_control") if isinstance(item.get("rule_control"), dict) else {}
    rule_type = (
        control.get("rule_type")
        or item.get("rule_type")
        or item.get("candidate_type")
        or "annotation"
    )
    executable = (
        (control.get("executable") or {})
        if isinstance(control.get("executable"), dict)
        else {}
    )
    return _research_normalize_contract({
        **item,
        "idea_type": rule_type,
        "hypothesis_family": (
            item.get("hypothesis_family")
            or item.get("research_shadow_tag")
            or item.get("shadow_tag")
        ),
        "target_strategy": (
            control.get("scope")
            or item.get("target_strategy")
            or "portfolio"
        ),
        "behavior_changed": (
            item.get("thesis")
            or item.get("candidate_title")
            or item.get("title")
        ),
        "minimum_closed_trades": (
            (item.get("promotion_progress") or {}).get("target")
            or 50
        ),
        "minimum_elapsed_days": 7,
        "authority_ceiling": "paper",
        "runtime_wired": bool(executable.get("can_paper_apply")),
        "variant_policy": item.get("variant_policy") or {},
        "strategy_contract": item.get("strategy_contract") or {},
    })


def _research_learning_experiment_rows(
    statuses: set[str] | None = None,
) -> list[dict]:
    _ensure_research_orchestrator_schema()
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        if statuses:
            marks = ",".join("?" for _ in statuses)
            rows = con.execute(
                f"""SELECT * FROM learning_experiments
                    WHERE source_type='research_candidate'
                      AND status IN ({marks})
                    ORDER BY created_at ASC""",
                tuple(sorted(statuses)),
            ).fetchall()
        else:
            rows = con.execute(
                """SELECT * FROM learning_experiments
                   WHERE source_type='research_candidate'
                   ORDER BY created_at DESC"""
            ).fetchall()
        return [dict(row) for row in rows]
    finally:
        con.close()


def _research_experiment_conflicts(
    contract: dict,
    *,
    exclude_experiment_id: str | None = None,
) -> list[dict]:
    conflicts = []
    marks = ",".join("?" for _ in RESEARCH_EXPERIMENT_ACTIVE_STATUSES)
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        rows = [
            dict(row) for row in con.execute(
                f"""SELECT * FROM learning_experiments
                    WHERE status IN ({marks})
                    ORDER BY created_at ASC""",
                tuple(sorted(RESEARCH_EXPERIMENT_ACTIVE_STATUSES)),
            ).fetchall()
        ]
    finally:
        con.close()
    for row in rows:
        if row.get("experiment_id") == exclude_experiment_id:
            continue
        existing_contract = _research_experiment_contract_from_row(row)
        if (
            str(row.get("source_type") or "") != "research_candidate"
            and str(existing_contract.get("target_strategy") or "")
            == str(contract.get("target_strategy") or "")
        ):
            conflicts.append({
                "experiment_id": row.get("experiment_id"),
                "strategy_key": row.get("strategy_key"),
                "idea_type": row.get("idea_type") or row.get("family"),
                "conflicts": True,
                "reason": "An active learner policy experiment already shares this strategy.",
                "shared_keys": [f"strategy:{contract.get('target_strategy')}"],
            })
            continue
        report = _research_conflict_report(
            contract,
            existing_contract,
        )
        if report.get("conflicts"):
            conflicts.append({
                "experiment_id": row.get("experiment_id"),
                "strategy_key": row.get("strategy_key"),
                "idea_type": row.get("idea_type"),
                **report,
            })
    return conflicts


def _research_context_snapshot(item: dict) -> dict:
    """Persist trader-facing provenance without granting it policy authority."""
    keys = (
        "title",
        "thesis",
        "expected_edge",
        "strategy_shape",
        "entry_filter_rule",
        "reject_filter_rule",
        "cohort_definition",
        "expected_failure_mode",
        "known_caveats",
        "gate_impact",
        "overfitting_risk",
        "next_action",
        "promotion_criteria",
        "rollback_condition",
        "source_count",
        "source_titles",
        "avg_source_quality",
        "avg_source_relevance",
        "evidence_stats",
        "partial_fields",
        "missing_fields",
    )
    snapshot = {
        key: item.get(key)
        for key in keys
        if item.get(key) not in (None, "", [], {})
    }
    snapshot["captured_at"] = datetime.now(timezone.utc).isoformat()
    return snapshot


def _research_refresh_experiment_context(
    experiment: dict,
    item: dict,
) -> dict:
    """Refresh explanatory metadata while preserving the frozen experiment contract."""
    scope = _learning_json(experiment.get("scope_json"), {})
    context = _research_context_snapshot(item)
    previous = scope.get("research_context")
    previous_core = {
        key: value for key, value in (previous or {}).items()
        if key != "captured_at"
    } if isinstance(previous, dict) else {}
    context_core = {
        key: value for key, value in context.items()
        if key != "captured_at"
    }
    if previous_core == context_core:
        return experiment
    scope["research_context"] = context
    con = sqlite3.connect(DB_PATH)
    try:
        con.execute(
            """UPDATE learning_experiments
               SET scope_json=?
               WHERE experiment_id=?""",
            (
                json.dumps(scope, sort_keys=True, default=str),
                experiment["experiment_id"],
            ),
        )
        con.commit()
    finally:
        con.close()
    return {**experiment, "scope_json": json.dumps(scope, sort_keys=True, default=str)}


RESEARCH_APPROVAL_STATUSES = {
    "awaiting_approval",
    "queued",
    "ready_for_experiment",
}

RESEARCH_APPROVAL_STATE_LABELS = {
    "ready_for_approval": "Ready for approval",
    "redundant_with_champion": "Redundant with champion",
    "target_disabled": "Target strategy disabled",
    "target_unavailable": "Target strategy unavailable",
    "missing_data": "Missing required data",
    "conflicts_with_active_experiment": "Conflicts with active experiment",
    "capacity_full": "Behavioral capacity full",
    "not_executable": "No runnable Paper behavior",
    "not_applicable": "Approval not applicable",
}


def _research_approval_preflight(
    experiment: dict,
    contract: dict | None = None,
    *,
    validation: dict | None = None,
    conflicts: list[dict] | None = None,
    paper_cfg: dict | None = None,
    active_behavioral_count: int | None = None,
) -> dict:
    """Prove a pending challenger is reachable and behaviorally distinct."""
    contract = contract or _research_experiment_contract_from_row(experiment)
    validation = validation or _research_validate_contract(contract)
    paper_cfg = paper_cfg or _load_paper_config()
    status = str(experiment.get("status") or "")
    behavioral = bool(contract.get("behavioral"))
    target = str(
        contract.get("target_strategy")
        or experiment.get("strategy_key")
        or ""
    ).strip()
    source_id = str(experiment.get("source_id") or "").strip()
    issues: list[dict] = []

    def add_issue(code: str, message: str, redesign: str = "") -> None:
        if any(item.get("code") == code and item.get("message") == message for item in issues):
            return
        issues.append({
            "code": code,
            "message": message,
            "redesign": redesign,
        })

    if status not in RESEARCH_APPROVAL_STATUSES or not behavioral:
        return {
            "can_approve": False,
            "state": "not_applicable",
            "label": RESEARCH_APPROVAL_STATE_LABELS["not_applicable"],
            "summary": "This lifecycle state does not accept a Paper challenger approval.",
            "issues": [],
            "next_step": "Continue the governed lifecycle shown on the experiment card.",
            "target_strategy": target,
            "target_reachable": None,
            "decision_delta": "not_applicable",
            "prepared_policy_fingerprint": experiment.get("policy_fingerprint"),
            "current_policy_fingerprint": None,
            "champion_policy_changed": False,
        }

    for problem in validation.get("problems") or []:
        add_issue(
            "missing_data",
            str(problem),
            "Supply the missing pre-entry field or runnable policy, then reconcile.",
        )
    if not contract.get("executable"):
        add_issue(
            "not_executable",
            "The contract has no executable Paper treatment.",
            "Define and wire an exact Paper-only treatment before requesting approval.",
        )

    disabled = {
        str(value).strip()
        for value in (paper_cfg.get("disabled_strategies") or [])
        if str(value).strip()
    }
    target_is_strategy = bool(target and target not in {"portfolio", "market", "global"})
    if target_is_strategy:
        registry = get_strategy_registry(include_disabled=True)
        if target not in registry:
            add_issue(
                "target_unavailable",
                f"The target strategy '{target}' is not registered in the Paper strategy registry.",
                "Retarget the contract to a registered strategy or register it through the strategy governance workflow.",
            )
        elif target in disabled:
            add_issue(
                "target_disabled",
                f"The target strategy '{target}' is disabled, so this experiment cannot receive eligible Paper assignments.",
                "Retarget the experiment to an enabled strategy or make strategy enablement a separate governed decision.",
            )

    current_controls = _research_rule_controls_by_tag()
    current_control = current_controls.get(source_id) or {}
    current_control_mode = str(current_control.get("mode") or "")
    current_policy = _learning_policy_snapshot(target, paper_cfg)
    variant_policy = contract.get("variant_policy")
    variant_policy = variant_policy if isinstance(variant_policy, dict) else {}
    matched_variant_fields: list[str] = []
    unresolved_variant_fields: list[str] = []
    changed_variant_fields: list[str] = []
    missing = object()

    def champion_value(key: str):
        parts = [part for part in str(key).split(".") if part]
        for source in (
            paper_cfg,
            current_policy.get("strategy_overrides") or {},
            current_policy.get("strategy") or {},
        ):
            value = source
            for part in parts:
                if not isinstance(value, dict) or part not in value:
                    value = missing
                    break
                value = value[part]
            if value is not missing:
                return value
        return missing

    for key, proposed in variant_policy.items():
        champion = champion_value(str(key))
        if champion is missing:
            unresolved_variant_fields.append(str(key))
        elif champion == proposed:
            matched_variant_fields.append(str(key))
        else:
            changed_variant_fields.append(str(key))
    if (
        variant_policy
        and matched_variant_fields
        and len(matched_variant_fields) == len(variant_policy)
    ):
        add_issue(
            "redundant_with_champion",
            "Every declared treatment setting already matches the Paper champion "
            f"({', '.join(sorted(matched_variant_fields))}), so the expected behavioral delta is zero.",
            "Change at least one predeclared treatment setting or convert the proposal into a non-behavioral policy audit.",
        )
    if current_control_mode == "paper_applied":
        add_issue(
            "redundant_with_champion",
            "The same research rule is already applied by the Paper champion, so treatment and control would make the same decision.",
            "Convert the proposal into a non-behavioral policy audit or declare a genuinely different threshold or rule.",
        )
    if (
        source_id == "research_order_flow_confirmation"
        and bool(paper_cfg.get("flow_required"))
    ):
        add_issue(
            "redundant_with_champion",
            "Order-flow confirmation is already required by the Paper champion, so the proposed add-flow treatment has zero behavioral delta.",
            "Audit the existing gate with forward blocked-opportunity outcomes, or test an explicit Paper-only threshold/ablation variant.",
        )

    conflicts = (
        conflicts
        if conflicts is not None
        else _research_experiment_conflicts(
            contract,
            exclude_experiment_id=experiment.get("experiment_id"),
        )
    )
    if conflicts:
        conflict_ids = ", ".join(
            str(item.get("experiment_id") or "active experiment")
            for item in conflicts
        )
        add_issue(
            "conflicts_with_active_experiment",
            f"The experiment conflicts with active policy surface: {conflict_ids}.",
            "Wait for the conflicting experiment to finish or redesign this contract onto an orthogonal decision surface.",
        )

    if active_behavioral_count is None:
        active_behavioral_count = len([
            row for row in _research_learning_experiment_rows(
                RESEARCH_EXPERIMENT_ACTIVE_STATUSES
            )
            if _research_experiment_contract_from_row(row).get("behavioral")
        ])
    if behavioral and active_behavioral_count >= RESEARCH_MAX_BEHAVIORAL_EXPERIMENTS:
        add_issue(
            "capacity_full",
            "All behavioral Paper experiment slots are occupied.",
            "Wait for an active behavioral challenger to complete or stop.",
        )

    priority = {
        "redundant_with_champion": 0,
        "target_disabled": 1,
        "target_unavailable": 2,
        "missing_data": 3,
        "not_executable": 4,
        "conflicts_with_active_experiment": 5,
        "capacity_full": 6,
    }
    primary = min(
        (str(item.get("code") or "") for item in issues),
        key=lambda code: priority.get(code, 99),
        default="ready_for_approval",
    )
    can_approve = not issues
    current_fingerprint = _learning_fingerprint(current_policy)
    if can_approve:
        summary = (
            "Preflight passed: the target is reachable and the challenger "
            "introduces a distinct Paper decision rule."
        )
        next_step = "Review the contract and explicitly approve the Paper challenger."
    else:
        summary = "Approval blocked: " + " ".join(
            str(item.get("message") or "") for item in issues
        )
        redesigns = [
            str(item.get("redesign") or "")
            for item in issues
            if item.get("redesign")
        ]
        next_step = (
            " ".join(dict.fromkeys(redesigns))
            if redesigns
            else "Redesign the contract, then reconcile."
        )
    issue_codes = {str(item.get("code") or "") for item in issues}
    decision_delta = (
        "zero"
        if "redundant_with_champion" in issue_codes
        else "unreachable"
        if {"target_disabled", "target_unavailable"} & issue_codes
        else "blocked"
        if issues
        else "expected"
    )
    return {
        "can_approve": can_approve,
        "state": primary,
        "label": RESEARCH_APPROVAL_STATE_LABELS.get(
            primary, primary.replace("_", " ").title()
        ),
        "summary": summary,
        "issues": issues,
        "next_step": next_step,
        "target_strategy": target,
        "target_reachable": not bool(
            {"target_disabled", "target_unavailable"} & issue_codes
        ),
        "decision_delta": decision_delta,
        "prepared_policy_fingerprint": experiment.get("policy_fingerprint"),
        "current_policy_fingerprint": current_fingerprint,
        "champion_policy_changed": bool(
            experiment.get("policy_fingerprint")
            and experiment.get("policy_fingerprint") != current_fingerprint
        ),
        "champion_facts": {
            "flow_required": bool(paper_cfg.get("flow_required")),
            "min_flow_score": paper_cfg.get("min_flow_score"),
            "target_disabled": target in disabled,
            "existing_rule_mode": current_control_mode or None,
            "matched_variant_fields": sorted(matched_variant_fields),
            "changed_variant_fields": sorted(changed_variant_fields),
            "unresolved_variant_fields": sorted(unresolved_variant_fields),
        },
    }


def _research_prepare_experiment(
    item: dict,
    *,
    actor: str = "research_orchestrator",
) -> dict:
    """Create an immutable awaiting-approval contract without changing behavior."""
    tag = str(
        item.get("research_shadow_tag")
        or item.get("shadow_tag")
        or item.get("id")
        or ""
    ).strip()
    if not tag:
        raise ValueError("research candidate requires a stable source tag")
    existing = [
        row for row in _research_learning_experiment_rows()
        if str(row.get("source_id") or "") == tag
        and row.get("status") not in RESEARCH_EXPERIMENT_TERMINAL_STATUSES
    ]
    if existing:
        refreshed = _research_refresh_experiment_context(existing[0], item)
        return {
            "created": False,
            "experiment": refreshed,
            "contract": _research_experiment_contract_from_row(refreshed),
        }

    contract = _research_contract_for_item(item)
    validation = _research_validate_contract(contract)
    now = datetime.now(timezone.utc).isoformat()
    lifecycle = validation.get("next_state") or "needs_data"
    status = (
        "awaiting_approval"
        if lifecycle == "ready_for_experiment" and contract.get("behavioral")
        else "collecting"
        if lifecycle == "ready_for_experiment"
        else lifecycle
    )
    policy = _learning_policy_snapshot(contract["target_strategy"])
    fingerprint = _learning_fingerprint(policy)
    digest = hashlib.sha256(
        f"{tag}|{now}|{json.dumps(contract, sort_keys=True)}".encode()
    ).hexdigest()[:12]
    experiment_id = f"research:{tag}:{digest}"
    evidence_rules = _learning_default_evidence_rules()
    evidence_rules.update(contract.get("evidence_rules") or {})
    baseline = {
        "prepared_at": now,
        "legacy_rows_excluded": True,
        "historical_shadow_is_causal": False,
        "research_shadow_result": {
            "matched": item.get("matched"),
            "comparison": item.get("comparison"),
            "status": item.get("outcome_status") or item.get("stage"),
        },
    }
    rollback = {
        "action": "restore_previous_paper_champion",
        "automatic_paper_stop_allowed": True,
        "live_change_allowed": False,
        "source_condition": item.get("rollback_condition"),
    }
    scope = {
        "strategy": contract["target_strategy"],
        "target_mode": "paper_challenger_after_approval",
        "orchestrator_contract": contract,
        "research_context": _research_context_snapshot(item),
    }
    change_set = [{
        "research_shadow_tag": tag,
        "idea_type": contract["idea_type"],
        "decision_surface": contract["decision_surface"],
        "behavior_changed": contract["behavior_changed"],
    }]

    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("BEGIN IMMEDIATE")
        con.execute(
            """INSERT INTO learning_experiments
               (experiment_id, contract_version, source_type, source_id, family,
                strategy_key, status, hypothesis, mechanism, scope_json,
                change_set_json, baseline_json, evidence_rules_json,
                rollback_json, policy_json, policy_fingerprint, authority_mode,
                user_approved, capital_change, execution_change, activated_at,
                created_at, updated_at, idea_type, decision_surface,
                lifecycle_state, hypothesis_family, conflict_keys_json,
                evaluator, treatment_pct, authority_ceiling, scheduler_managed,
                last_progress_at, probation_stage)
               VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                experiment_id,
                RESEARCH_ORCHESTRATOR_VERSION,
                "research_candidate",
                tag,
                contract["hypothesis_family"],
                contract["target_strategy"],
                status,
                contract["behavior_changed"],
                str(item.get("mechanism") or item.get("expected_edge") or contract["behavior_changed"]),
                json.dumps(scope, sort_keys=True, default=str),
                json.dumps(change_set, sort_keys=True, default=str),
                json.dumps(baseline, sort_keys=True, default=str),
                json.dumps(evidence_rules, sort_keys=True, default=str),
                json.dumps(rollback, sort_keys=True, default=str),
                json.dumps(policy, sort_keys=True, default=str),
                fingerprint,
                "shadow_only",
                0,
                1 if contract["idea_type"] in {"sizing_rule", "portfolio_rule"} else 0,
                1 if contract["idea_type"] in {"stop_rule", "exit_rule", "execution_rule"} else 0,
                now,
                now,
                now,
                contract["idea_type"],
                contract["decision_surface"],
                status,
                contract["hypothesis_family"],
                json.dumps(contract["conflict_keys"], sort_keys=True),
                contract["evaluator"],
                contract["treatment_pct"],
                contract["authority_ceiling"],
                1,
                now,
                "initial",
            ),
        )
        _learning_append_event(
            con,
            experiment_id,
            "contract_prepared",
            {
                "actor": actor,
                "contract": contract,
                "validation": validation,
                "behavior_changed": False,
                "requires_user_approval": bool(contract.get("behavioral")),
                "live_behavior_change_allowed": False,
            },
            now,
        )
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {
        "created": True,
        "experiment": {
            "experiment_id": experiment_id,
            "source_id": tag,
            "status": status,
            "lifecycle_state": status,
        },
        "contract": contract,
        "validation": validation,
    }


def _research_activate_experiment(
    experiment_id: str,
    *,
    actor: str,
    reason: str,
) -> dict:
    """Activate one approved Paper challenger after conflict/capacity checks."""
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    row = con.execute(
        "SELECT * FROM learning_experiments WHERE experiment_id=?",
        (experiment_id,),
    ).fetchone()
    con.close()
    if not row:
        raise ValueError("research experiment not found")
    experiment = dict(row)
    if experiment.get("source_type") != "research_candidate":
        raise ValueError("only research candidates use this activation path")
    if (
        experiment.get("status") in RESEARCH_EXPERIMENT_ACTIVE_STATUSES
        and bool(experiment.get("user_approved"))
    ):
        return {
            "experiment_id": experiment_id,
            "status": experiment.get("status"),
            "lifecycle_state": experiment.get("lifecycle_state") or "paper_challenger",
            "policy_fingerprint": experiment.get("policy_fingerprint"),
            "contract": _research_experiment_contract_from_row(experiment),
            "already_active": True,
        }
    if experiment.get("status") not in {
        "awaiting_approval",
        "queued",
        "ready_for_experiment",
        "review",
    }:
        raise ValueError(f"experiment cannot activate from {experiment.get('status')}")
    contract = _research_experiment_contract_from_row(experiment)
    validation = _research_validate_contract(contract)
    if not validation.get("valid") or not contract.get("executable"):
        raise ValueError("; ".join(validation.get("problems") or ["contract is not executable"]))
    conflicts = _research_experiment_conflicts(
        contract,
        exclude_experiment_id=experiment_id,
    )
    approval_preflight = _research_approval_preflight(
        experiment,
        contract,
        validation=validation,
        conflicts=conflicts,
    )
    if not approval_preflight.get("can_approve"):
        raise ValueError(str(approval_preflight.get("summary") or "experiment is not approval-ready"))
    marks = ",".join("?" for _ in RESEARCH_EXPERIMENT_ACTIVE_STATUSES)
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        active = [
            dict(row) for row in con.execute(
                f"""SELECT * FROM learning_experiments
                    WHERE status IN ({marks})
                    ORDER BY created_at ASC""",
                tuple(sorted(RESEARCH_EXPERIMENT_ACTIVE_STATUSES)),
            ).fetchall()
        ]
    finally:
        con.close()
    active_behavioral = len([
        row for row in active
        if _research_experiment_contract_from_row(row).get("behavioral")
    ])
    if contract.get("behavioral") and active_behavioral >= RESEARCH_MAX_BEHAVIORAL_EXPERIMENTS:
        raise ValueError("behavioral experiment capacity is full")

    now = datetime.now(timezone.utc).isoformat()
    policy = _learning_policy_snapshot(experiment["strategy_key"])
    fingerprint = _learning_fingerprint(policy)
    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("BEGIN IMMEDIATE")
        con.execute(
            """UPDATE learning_experiments
               SET status='collecting', lifecycle_state='paper_challenger',
                   policy_json=?, policy_fingerprint=?, authority_mode='paper_only',
                   user_approved=1, activated_at=?, updated_at=?,
                   last_progress_at=?, blocked_reason=NULL,
                   probation_stage='paper_challenger'
               WHERE experiment_id=?""",
            (
                json.dumps(policy, sort_keys=True, default=str),
                fingerprint,
                now,
                now,
                now,
                experiment_id,
            ),
        )
        _learning_append_event(
            con,
            experiment_id,
            "paper_challenger_activated",
            {
                "actor": actor,
                "reason": reason,
                "policy_fingerprint": fingerprint,
                "treatment_pct": contract.get("treatment_pct"),
                "automatic_promotion": False,
                "automatic_live_change": False,
            },
            now,
        )
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {
        "experiment_id": experiment_id,
        "status": "collecting",
        "lifecycle_state": "paper_challenger",
        "policy_fingerprint": fingerprint,
        "contract": contract,
    }


def _research_stop_source_experiments(
    source_id: str,
    *,
    status: str,
    actor: str,
    reason: str,
    automatic: bool = False,
) -> list[str]:
    """Stop Paper research challengers while preserving every ledger event."""
    if status not in {"falsified", "rolled_back", "parked", "cancelled"}:
        raise ValueError("invalid research experiment stop status")
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    stopped: list[str] = []
    now = datetime.now(timezone.utc).isoformat()
    try:
        con.execute("BEGIN IMMEDIATE")
        rows = con.execute(
            """SELECT experiment_id, status
               FROM learning_experiments
               WHERE source_type='research_candidate' AND source_id=?
                 AND status IN ('active','collecting','review',
                                'awaiting_approval','queued','ready_for_experiment')""",
            (source_id,),
        ).fetchall()
        for row in rows:
            lifecycle = "rolled_back" if status == "rolled_back" else status
            con.execute(
                """UPDATE learning_experiments
                   SET status=?, lifecycle_state=?, authority_mode='shadow_only',
                       updated_at=?, rollback_required=0,
                       blocked_reason=?, probation_stage='stopped'
                   WHERE experiment_id=?""",
                (status, lifecycle, now, reason, row["experiment_id"]),
            )
            _learning_append_event(
                con,
                row["experiment_id"],
                "paper_challenger_stopped",
                {
                    "from": row["status"],
                    "to": status,
                    "actor": actor,
                    "reason": reason,
                    "automatic": automatic,
                    "live_behavior_changed": False,
                    "risk_increased": False,
                },
                now,
            )
            stopped.append(row["experiment_id"])
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return stopped


def _research_auto_stop_falsified(item: dict) -> dict:
    """Disarm an unsafe or stalled Paper hook; never promote or touch live."""
    source_id = str(item.get("source_id") or "")
    experiment_id = str(item.get("experiment_id") or "")
    target_lifecycle = str(item.get("status") or "falsified")
    if not source_id or not experiment_id:
        return {"changed": False, "reason": "missing identity"}
    controls = _research_rule_controls_by_tag()
    current = controls.get(source_id) or {}
    if current.get("mode") != "paper_applied":
        return {"changed": False, "reason": "paper hook already inactive"}
    now = datetime.now(timezone.utc).isoformat()
    record = {
        "id": f"research_rule_control_{source_id}_{now}",
        "type": "research_rule_control",
        "source": "research_orchestrator",
        "research_shadow_tag": source_id,
        "shadow_tag": source_id,
        "mode": "shadow",
        "rule_type": current.get("rule_type") or "entry_gate",
        "scope": current.get("scope") or "portfolio",
        "reason": str(item.get("reason") or "Experiment falsified"),
        "actor": "research_orchestrator",
        "created_at": now,
        "updated_at": now,
        "updated_by": "research_orchestrator",
        "changed_scoring": False,
        "changed_paper_behavior": True,
        "changed_live_behavior": False,
        "automatic": True,
        "automatic_action": "paper_stop_only",
        "notes": [
            "Automatic Paper challenger stop after a falsification or stale-capacity boundary.",
            "The previous champion remains the active Paper behavior.",
            "No live, leverage, sizing, or execution authority was increased.",
        ],
    }
    ledger = _read_experiment_ledger()
    ledger.append(record)
    _research_write_experiment_ledger(ledger)
    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("BEGIN IMMEDIATE")
        con.execute(
            """UPDATE learning_experiments
               SET authority_mode='shadow_only', rollback_required=0,
                   lifecycle_state=?, probation_stage='stopped',
                   updated_at=?
               WHERE experiment_id=?""",
            (target_lifecycle, now, experiment_id),
        )
        _learning_append_event(
            con,
            experiment_id,
            "automatic_paper_stop",
            {
                "reason": record["reason"],
                "rule_mode": "shadow",
                "paper_behavior_stopped": True,
                "live_behavior_changed": False,
                "risk_increased": False,
            },
            now,
        )
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {"changed": True, "control": record}


def _research_promote_experiment(
    experiment_id: str,
    *,
    actor: str,
    reason: str,
) -> dict:
    """Promote evidence one Paper stage; live authority is never granted."""
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    row = con.execute(
        "SELECT * FROM learning_experiments WHERE experiment_id=?",
        (experiment_id,),
    ).fetchone()
    con.close()
    if not row:
        raise ValueError("research experiment not found")
    experiment = dict(row)
    if experiment.get("source_type") != "research_candidate":
        raise ValueError("only research candidates use this promotion path")
    if experiment.get("status") != "promotion_candidate":
        raise ValueError("experiment must be a promotion candidate")
    if not bool(experiment.get("user_approved")):
        raise ValueError("Paper challenger was not user approved")
    contract = _research_experiment_contract_from_row(experiment)
    now = datetime.now(timezone.utc).isoformat()
    if str(experiment.get("probation_stage") or "initial") == "confirmation":
        con = sqlite3.connect(DB_PATH)
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute(
                """UPDATE learning_experiments
                   SET status='completed', lifecycle_state='confirmed',
                       probation_stage='confirmed', updated_at=?,
                       authority_mode='paper_only'
                   WHERE experiment_id=?""",
                (now, experiment_id),
            )
            _learning_append_event(
                con,
                experiment_id,
                "paper_champion_confirmed",
                {
                    "actor": actor,
                    "reason": reason,
                    "live_authority_granted": False,
                    "separate_live_review_required": True,
                },
                now,
            )
            con.commit()
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()
        return {
            "experiment_id": experiment_id,
            "status": "completed",
            "lifecycle_state": "confirmed",
            "live_authority_granted": False,
        }

    confirmation_contract = {
        **contract,
        "treatment_pct": 80,
        "evidence_rules": {
            **(contract.get("evidence_rules") or {}),
            "minimum_closed_trades": max(
                50,
                int(
                    (contract.get("evidence_rules") or {}).get(
                        "minimum_closed_trades"
                    )
                    or 50
                ),
            ),
            "minimum_elapsed_days": max(
                7.0,
                float(
                    (contract.get("evidence_rules") or {}).get(
                        "minimum_elapsed_days"
                    )
                    or 7
                ),
            ),
        },
    }
    scope = _learning_json(experiment.get("scope_json"), {})
    scope["orchestrator_contract"] = confirmation_contract
    policy = _learning_policy_snapshot(experiment["strategy_key"])
    policy["research_confirmation_parent"] = experiment_id
    fingerprint = _learning_fingerprint(policy)
    child_id = (
        f"research-confirmation:{experiment.get('source_id')}:"
        f"{hashlib.sha256((experiment_id + now).encode()).hexdigest()[:12]}"
    )
    evidence_rules = _learning_default_evidence_rules()
    evidence_rules.update(confirmation_contract.get("evidence_rules") or {})
    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("BEGIN IMMEDIATE")
        con.execute(
            """UPDATE learning_experiments
               SET status='completed', lifecycle_state='paper_champion',
                   probation_stage='initial_passed', updated_at=?
               WHERE experiment_id=?""",
            (now, experiment_id),
        )
        _learning_append_event(
            con,
            experiment_id,
            "promoted_to_paper_champion",
            {
                "actor": actor,
                "reason": reason,
                "confirmation_experiment_id": child_id,
                "live_authority_granted": False,
            },
            now,
        )
        con.execute(
            """INSERT INTO learning_experiments
               (experiment_id, contract_version, source_type, source_id, family,
                strategy_key, status, hypothesis, mechanism, scope_json,
                change_set_json, baseline_json, evidence_rules_json,
                rollback_json, policy_json, policy_fingerprint, authority_mode,
                user_approved, capital_change, execution_change, activated_at,
                created_at, updated_at, idea_type, decision_surface,
                lifecycle_state, hypothesis_family, conflict_keys_json,
                evaluator, treatment_pct, authority_ceiling, scheduler_managed,
                last_progress_at, champion_experiment_id, probation_stage)
               VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                child_id,
                RESEARCH_ORCHESTRATOR_VERSION,
                "research_candidate",
                experiment.get("source_id"),
                experiment.get("family"),
                experiment.get("strategy_key"),
                "collecting",
                experiment.get("hypothesis"),
                experiment.get("mechanism"),
                json.dumps(scope, sort_keys=True, default=str),
                experiment.get("change_set_json"),
                json.dumps(
                    {
                        "parent_experiment_id": experiment_id,
                        "parent_result": _learning_json(
                            experiment.get("result_json"), {}
                        ),
                        "forward_boundary_at": now,
                    },
                    sort_keys=True,
                    default=str,
                ),
                json.dumps(evidence_rules, sort_keys=True, default=str),
                experiment.get("rollback_json"),
                json.dumps(policy, sort_keys=True, default=str),
                fingerprint,
                "paper_only",
                1,
                int(experiment.get("capital_change") or 0),
                int(experiment.get("execution_change") or 0),
                now,
                now,
                now,
                confirmation_contract.get("idea_type"),
                confirmation_contract.get("decision_surface"),
                "paper_champion",
                confirmation_contract.get("hypothesis_family"),
                json.dumps(
                    confirmation_contract.get("conflict_keys") or [],
                    sort_keys=True,
                ),
                confirmation_contract.get("evaluator"),
                80,
                confirmation_contract.get("authority_ceiling") or "paper",
                1,
                now,
                experiment_id,
                "confirmation",
            ),
        )
        _learning_append_event(
            con,
            child_id,
            "paper_champion_confirmation_started",
            {
                "actor": actor,
                "reason": reason,
                "parent_experiment_id": experiment_id,
                "treatment_pct": 80,
                "control_holdout_pct": 20,
                "historical_rows_attributed": False,
                "live_authority_granted": False,
            },
            now,
        )
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {
        "experiment_id": experiment_id,
        "status": "completed",
        "lifecycle_state": "paper_champion",
        "confirmation_experiment_id": child_id,
        "confirmation_treatment_pct": 80,
        "live_authority_granted": False,
    }


def _research_assignments_for_signal(sig: dict, assigned_at: str | None = None) -> list[dict]:
    """Assign every compatible active research experiment to one Paper candidate."""
    existing = sig.get("_research_assignments")
    if isinstance(existing, list):
        return existing
    strategy_key = str(
        sig.get("_strategy_key") or sig.get("strategy_key") or "balanced"
    )
    symbol = str(sig.get("symbol") or "")
    assigned_at = assigned_at or datetime.now(timezone.utc).isoformat()
    assignments = []
    for row in _research_learning_experiment_rows(
        RESEARCH_EXPERIMENT_ACTIVE_STATUSES
    ):
        contract = _research_experiment_contract_from_row(row)
        target = str(contract.get("target_strategy") or "")
        if target not in {
            strategy_key,
            "portfolio",
            "all",
            "all_strategies",
        }:
            continue
        assignment = _research_deterministic_arm(
            row["experiment_id"],
            symbol,
            str(sig.get("logged_at") or sig.get("timestamp") or assigned_at),
            int(contract.get("treatment_pct") or 30),
        )
        assignments.append({
            "experiment_id": row["experiment_id"],
            "source_id": row.get("source_id"),
            "idea_type": contract.get("idea_type"),
            "decision_surface": contract.get("decision_surface"),
            "evaluator": contract.get("evaluator"),
            "strategy_key": strategy_key,
            "symbol": symbol,
            "assigned_at": assigned_at,
            "policy_fingerprint": row.get("policy_fingerprint"),
            **assignment,
        })
    return assignments


def _research_record_assignments(
    assignments: list[dict],
    *,
    paper_trade_id: int | None,
    signal_id: int | None,
    decision: str,
    metadata: dict | None = None,
) -> None:
    if not assignments:
        return
    con = sqlite3.connect(DB_PATH)
    try:
        for item in assignments:
            item_decision = str(item.get("decision") or decision)
            con.execute(
                """INSERT OR IGNORE INTO learning_experiment_assignments
                   (experiment_id, assignment_key, paper_trade_id, signal_id,
                    assigned_at, symbol, strategy_key, arm, bucket, decision,
                    eligible, policy_fingerprint, outcome_source, metadata_json)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    item["experiment_id"],
                    item["assignment_key"],
                    paper_trade_id,
                    signal_id,
                    item["assigned_at"],
                    item["symbol"],
                    item["strategy_key"],
                    item["arm"],
                    int(item["bucket"]),
                    item_decision,
                    1,
                    item.get("policy_fingerprint"),
                    "signals" if signal_id and item_decision == "blocked" else "paper_trades",
                    json.dumps(metadata or {}, sort_keys=True, default=str),
                ),
            )
        con.commit()
    finally:
        con.close()


def _research_sync_assignment_outcomes(con: sqlite3.Connection) -> int:
    """Copy immutable closed outcomes into the many-to-many assignment ledger."""
    changed = con.execute(
        """UPDATE learning_experiment_assignments
           SET result=(
                 SELECT p.result FROM paper_trades p
                 WHERE p.id=learning_experiment_assignments.paper_trade_id
               ),
               pnl_pct=(
                 SELECT p.pnl_pct FROM paper_trades p
                 WHERE p.id=learning_experiment_assignments.paper_trade_id
               ),
               closed_at=(
                 SELECT p.closed_at FROM paper_trades p
                 WHERE p.id=learning_experiment_assignments.paper_trade_id
               ),
               outcome_source='paper_trades'
           WHERE paper_trade_id IS NOT NULL
             AND EXISTS (
                 SELECT 1 FROM paper_trades p
                 WHERE p.id=learning_experiment_assignments.paper_trade_id
                   AND p.status='closed'
                   AND p.result IN ('WIN','LOSS','PARTIAL')
                   AND p.pnl_pct IS NOT NULL
             )
             AND (result IS NULL OR pnl_pct IS NULL)"""
    ).rowcount
    changed += con.execute(
        """UPDATE learning_experiment_assignments
           SET result=(
                 SELECT s.result FROM signals s
                 WHERE s.id=learning_experiment_assignments.signal_id
               ),
               pnl_pct=(
                 SELECT s.pnl_pct FROM signals s
                 WHERE s.id=learning_experiment_assignments.signal_id
               ),
               closed_at=(
                 SELECT s.result_at FROM signals s
                 WHERE s.id=learning_experiment_assignments.signal_id
               ),
               outcome_source='signals'
           WHERE signal_id IS NOT NULL
             AND decision='blocked'
             AND EXISTS (
                 SELECT 1 FROM signals s
                 WHERE s.id=learning_experiment_assignments.signal_id
                   AND s.result IN ('WIN','LOSS','PARTIAL','TP3')
                   AND s.pnl_pct IS NOT NULL
             )
             AND (result IS NULL OR pnl_pct IS NULL)"""
    ).rowcount
    cfg = _load_paper_config()
    cost_rows = con.execute(
        """SELECT a.id, a.result, a.pnl_pct, a.metadata_json,
                  COALESCE(s.leverage, 1.0) AS leverage
           FROM learning_experiment_assignments a
           JOIN signals s ON s.id=a.signal_id
           WHERE a.decision='blocked'
             AND a.outcome_source='signals'
             AND a.result IN ('WIN','LOSS','PARTIAL','TP3')
             AND a.pnl_pct IS NOT NULL
             AND a.metadata_json NOT LIKE '%counterfactual_cost_adjusted%'"""
    ).fetchall()
    for row in cost_rows:
        result = "WIN" if str(row[1]) == "TP3" else str(row[1])
        fee_pct, slippage_pct, total_cost_pct = _paper_cost_adjustment(
            cfg,
            result,
            float(row[4] or 1.0),
        )
        metadata = _learning_json(row[3], {})
        metadata.update({
            "counterfactual_cost_adjusted": True,
            "gross_pnl_pct": float(row[2] or 0.0),
            "fee_cost_pct": fee_pct,
            "slippage_cost_pct": slippage_pct,
        })
        con.execute(
            """UPDATE learning_experiment_assignments
               SET pnl_pct=?, metadata_json=?
               WHERE id=?""",
            (
                round(float(row[2] or 0.0) - total_cost_pct, 4),
                json.dumps(metadata, sort_keys=True, default=str),
                int(row[0]),
            ),
        )
    return changed


def _research_experiment_assignment_rows(
    con: sqlite3.Connection,
    experiment: dict,
) -> dict:
    rows = [
        dict(row) for row in con.execute(
            """SELECT a.*, COALESCE(p.size_usd, 100.0) AS size_usd,
                      COALESCE(p.leverage, s.leverage, 1.0) AS leverage,
                      COALESCE(p.funding_complete, 0) AS funding_complete,
                      COALESCE(p.execution_cost_complete, 0) AS execution_cost_complete
               FROM learning_experiment_assignments a
               LEFT JOIN paper_trades p ON p.id=a.paper_trade_id
               LEFT JOIN signals s ON s.id=a.signal_id
               WHERE a.experiment_id=?
               ORDER BY a.assigned_at ASC, a.id ASC""",
            (experiment["experiment_id"],),
        ).fetchall()
    ]
    treatment_closed = [
        row for row in rows
        if row.get("arm") == "treatment"
        and row.get("decision") != "blocked"
        and row.get("result") in {"WIN", "LOSS", "PARTIAL"}
        and row.get("pnl_pct") is not None
    ]
    control_closed = [
        row for row in rows
        if row.get("arm") == "control"
        and row.get("result") in {"WIN", "LOSS", "PARTIAL"}
        and row.get("pnl_pct") is not None
    ]
    blocked_shadow = [
        row for row in rows
        if row.get("arm") == "treatment"
        and row.get("decision") == "blocked"
        and row.get("result") in {"WIN", "LOSS", "PARTIAL", "TP3"}
        and row.get("pnl_pct") is not None
    ]
    # Gate policy expectancy is measured per eligible opportunity.  A blocked
    # opportunity contributes zero realized Paper return, while its shadow
    # outcome remains separate as opportunity cost.
    treatment_policy = list(treatment_closed) + [
        {**row, "result": "PARTIAL", "pnl_pct": 0.0, "size_usd": 0.0}
        for row in blocked_shadow
    ]
    return {
        "all": rows,
        "treatment": treatment_policy,
        "control": control_closed,
        "accepted_treatment": treatment_closed,
        "blocked_shadow": blocked_shadow,
    }


def _research_experiment_orchestrator_payload(
    *,
    reconcile: bool = False,
) -> dict:
    """Return concurrency, blockage, and lifecycle truth for the Research UI."""
    if reconcile:
        _research_reconcile_experiments()
    rows = _research_learning_experiment_rows()
    active = [
        row for row in rows
        if row.get("status") in RESEARCH_EXPERIMENT_ACTIVE_STATUSES
    ]
    active_behavioral = len([
        row for row in active
        if _research_experiment_contract_from_row(row).get("behavioral")
    ])
    pending = [
        row for row in rows
        if row.get("status") in {
            "awaiting_approval",
            "queued",
            "needs_data",
            "ready_for_experiment",
        }
    ]
    cards = []
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        _research_sync_assignment_outcomes(con)
        con.commit()
        for row in rows[:100]:
            contract = _research_experiment_contract_from_row(row)
            scope = _learning_json(row.get("scope_json"), {})
            context = scope.get("research_context")
            context = context if isinstance(context, dict) else {}
            validation = _research_validate_contract(contract)
            assignment_rows = [
                dict(item) for item in con.execute(
                    """SELECT arm, decision, result, symbol, closed_at
                       FROM learning_experiment_assignments
                       WHERE experiment_id=?
                       ORDER BY assigned_at ASC, id ASC""",
                    (row["experiment_id"],),
                ).fetchall()
            ]
            counts = {
                arm: len([
                    item for item in assignment_rows
                    if str(item.get("arm") or "") == arm
                ])
                for arm in ("treatment", "control")
            }
            closed_rows = [
                item for item in assignment_rows
                if item.get("result") is not None
            ]
            closed = len(closed_rows)
            effective = _research_effective_sample(closed_rows)
            assignments = {
                "total": len(assignment_rows),
                "treatment": counts.get("treatment", 0),
                "control": counts.get("control", 0),
                "closed": closed,
                "treatment_closed": len([
                    item for item in closed_rows
                    if item.get("arm") == "treatment"
                ]),
                "control_closed": len([
                    item for item in closed_rows
                    if item.get("arm") == "control"
                ]),
                "blocked": len([
                    item for item in assignment_rows
                    if item.get("decision") == "blocked"
                ]),
                "contaminated": len([
                    item for item in assignment_rows
                    if item.get("decision") == "contaminated"
                ]),
                "effective_symbol_days": int(
                    effective.get("symbol_day_count") or 0
                ),
                "effective_market_days": int(
                    effective.get("market_day_count") or 0
                ),
            }
            elapsed_days = 0.0
            if bool(row.get("user_approved")):
                activated_at = _parse_iso_datetime(row.get("activated_at"))
                if activated_at:
                    elapsed_days = max(
                        0.0,
                        (
                            datetime.now(timezone.utc).replace(tzinfo=None)
                            - activated_at
                        ).total_seconds() / 86400.0,
                    )
            experiment_conflicts = _research_experiment_conflicts(
                contract,
                exclude_experiment_id=row.get("experiment_id"),
            )
            approval_preflight = _research_approval_preflight(
                row,
                contract,
                validation=validation,
                conflicts=experiment_conflicts,
                active_behavioral_count=active_behavioral,
            )
            blocker_messages = []
            if row.get("blocked_reason"):
                blocker_messages.append(str(row.get("blocked_reason")))
            for problem in validation.get("problems") or []:
                if problem not in blocker_messages:
                    blocker_messages.append(problem)
            for issue in approval_preflight.get("issues") or []:
                message = str(issue.get("message") or "").strip()
                if message and message not in blocker_messages:
                    blocker_messages.append(message)
            display_status = (
                approval_preflight.get("state")
                if row.get("status") in RESEARCH_APPROVAL_STATUSES
                and not approval_preflight.get("can_approve")
                else row.get("lifecycle_state") or row.get("status")
            )
            card = {
                "experiment_id": row["experiment_id"],
                "source_id": row.get("source_id"),
                "status": row.get("status"),
                "lifecycle_state": row.get("lifecycle_state") or row.get("status"),
                "display_status": display_status,
                "strategy_key": row.get("strategy_key"),
                "hypothesis": row.get("hypothesis"),
                "idea_type": contract.get("idea_type"),
                "decision_surface": contract.get("decision_surface"),
                "evaluator": contract.get("evaluator"),
                "treatment_pct": contract.get("treatment_pct"),
                "conflict_keys": contract.get("conflict_keys"),
                "behavioral": contract.get("behavioral"),
                "virtual_first": contract.get("virtual_first"),
                "user_approved": bool(row.get("user_approved")),
                "authority_mode": row.get("authority_mode"),
                "authority_ceiling": row.get("authority_ceiling"),
                "blocked_reason": row.get("blocked_reason"),
                "last_progress_at": row.get("last_progress_at"),
                "probation_stage": row.get("probation_stage"),
                "assignments": assignments,
                "evaluation": _learning_json(row.get("result_json"), {}),
                "approval_readiness": approval_preflight,
            }
            card["brief"] = _research_trader_experiment_brief(
                contract,
                context=context,
                state={
                    **card,
                    "elapsed_days": elapsed_days,
                    "validation": validation,
                    "blockers": blocker_messages,
                    "approval_readiness": approval_preflight,
                    "conflicts": [
                        str(item.get("reason") or "Overlapping active policy")
                        + (
                            f" ({item.get('strategy_key')})"
                            if item.get("strategy_key")
                            else ""
                        )
                        for item in experiment_conflicts
                    ],
                },
            )
            cards.append(card)
    finally:
        con.close()
    active_shadow = len(active) - active_behavioral
    source_ids = {
        str(row.get("source_id") or "") for row in rows if row.get("source_id")
    }
    marker_tags = set(_research_paper_trials_by_tag().keys())
    marker_only = sorted(marker_tags - source_ids)
    controls = _research_rule_controls_by_tag()
    active_control_tags = {
        tag for tag, control in controls.items()
        if str((control or {}).get("mode") or "") == "paper_applied"
    }
    active_experiment_tags = {
        str(row.get("source_id") or "") for row in active if row.get("source_id")
    }
    orphan_controls = sorted(active_control_tags - active_experiment_tags)
    status_counts: dict[str, int] = defaultdict(int)
    for row in rows:
        status_counts[str(row.get("status") or "unknown")] += 1
    initial_promotions = len([
        row for row in rows
        if str(row.get("probation_stage") or "") in {
            "initial_passed",
            "confirmation",
            "confirmed",
        }
    ])
    confirmed_count = len([
        row for row in rows
        if str(row.get("lifecycle_state") or "") == "confirmed"
    ])
    forward_lifts = []
    for row in rows:
        evaluation = _learning_json(row.get("result_json"), {})
        delta = (evaluation.get("deltas") or {}).get("avg_pnl_pct")
        if delta is not None and row.get("status") in {
            "promotion_candidate",
            "completed",
        }:
            try:
                forward_lifts.append(float(delta))
            except Exception:
                pass
    family_counts: dict[str, int] = defaultdict(int)
    for row in rows:
        family_counts[str(
            row.get("hypothesis_family") or row.get("family") or "unknown"
        )] += 1
    scheduling = _research_scheduler_plan(
        [
            {
                "id": row.get("experiment_id"),
                "created_at": row.get("created_at"),
                "priority_score": float(
                    (
                        (_learning_json(row.get("baseline_json"), {}).get(
                            "research_shadow_result"
                        ) or {}).get("matched") or {}
                    ).get("count")
                    or 0
                ),
                "contract": _research_experiment_contract_from_row(row),
            }
            for row in pending
        ],
        [
            {
                "experiment_id": row.get("experiment_id"),
                "contract": _research_experiment_contract_from_row(row),
            }
            for row in active
        ],
        max_behavioral=RESEARCH_MAX_BEHAVIORAL_EXPERIMENTS,
        max_shadow=RESEARCH_MAX_SHADOW_EXPERIMENTS,
    )
    scheduler_blocked = {
        str(item.get("id") or ""): str(item.get("reason") or "")
        for item in scheduling.get("blocked") or []
        if item.get("id") and item.get("reason")
    }
    for card in cards:
        reason = scheduler_blocked.get(str(card.get("experiment_id") or ""))
        if not reason:
            continue
        brief = card.get("brief") or {}
        blockers = list(brief.get("blockers") or [])
        if reason not in blockers:
            blockers.append(reason)
        brief["blockers"] = blockers
        if card.get("status") in {"queued", "awaiting_approval"}:
            brief["next_step"] = (
                "Resolve the scheduler conflict or wait for capacity before approval."
            )
    readiness_counts: dict[str, int] = defaultdict(int)
    for card in cards:
        readiness = card.get("approval_readiness") or {}
        state = str(readiness.get("state") or "")
        if state and state != "not_applicable":
            readiness_counts[state] += 1
    return {
        "success": True,
        "version": RESEARCH_ORCHESTRATOR_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "total": len(rows),
            "active": len(active),
            "active_behavioral": active_behavioral,
            "active_shadow": active_shadow,
            "awaiting_or_blocked": len(pending),
            "approval_ready": readiness_counts.get("ready_for_approval", 0),
            "approval_blocked": sum(
                count for state, count in readiness_counts.items()
                if state != "ready_for_approval"
            ),
            "behavioral_slots_available": max(
                0, RESEARCH_MAX_BEHAVIORAL_EXPERIMENTS - active_behavioral
            ),
            "shadow_slots_available": max(
                0, RESEARCH_MAX_SHADOW_EXPERIMENTS - active_shadow
            ),
            "marker_only_trials": len(marker_only),
            "orphan_paper_controls": len(orphan_controls),
            "live_behavior_active": 0,
        },
        "effectiveness": {
            "status_counts": dict(status_counts),
            "hypothesis_family_count": len(family_counts),
            "variant_count_by_family": dict(sorted(family_counts.items())),
            "falsified_count": status_counts.get("falsified", 0),
            "initial_promotion_count": initial_promotions,
            "confirmed_count": confirmed_count,
            "forward_replication_rate": (
                round(confirmed_count / initial_promotions, 4)
                if initial_promotions else None
            ),
            "confirmed_or_promotable_avg_lift_pct": (
                round(sum(forward_lifts) / len(forward_lifts), 4)
                if forward_lifts else None
            ),
            "historical_results_count_as_forward": False,
        },
        "blockages": {
            "marker_only_trial_tags": marker_only,
            "orphan_paper_control_tags": orphan_controls,
            "experiments_with_blocked_reason": [
                {
                    "experiment_id": row.get("experiment_id"),
                    "reason": row.get("blocked_reason"),
                }
                for row in rows if row.get("blocked_reason")
            ],
            "approval_readiness_counts": dict(sorted(readiness_counts.items())),
        },
        "scheduler": scheduling,
        "experiments": cards,
        "safety": {
            "automatic_preflight": True,
            "behavioral_delta_preflight": True,
            "target_reachability_preflight": True,
            "automatic_assignment": True,
            "automatic_evaluation": True,
            "automatic_paper_stop": True,
            "automatic_promotion": False,
            "automatic_live_change": False,
            "automatic_risk_increase": False,
        },
    }


def _research_reconcile_experiments() -> dict:
    """Prepare missing contracts and surface stalled experiments.

    Reconciliation never starts a behavioral experiment and never changes live
    or risk authority.
    """
    prepared = []
    errors = []
    try:
        ledger = _research_evidence_ledger_payload()
        for item in ledger.get("items") or []:
            control = item.get("rule_control") or {}
            mode = str(control.get("mode") or "")
            if mode not in {"paper_trial", "paper_applied"}:
                continue
            try:
                prepared_item = _research_prepare_experiment(item)
                activation = None
                experiment_id = str(
                    (prepared_item.get("experiment") or {}).get("experiment_id")
                    or ""
                )
                if mode == "paper_applied" and experiment_id:
                    activation = _research_activate_experiment(
                        experiment_id,
                        actor="research_orchestrator_reconciler",
                        reason=(
                            "Adopt existing user-approved Paper Applied control "
                            "into the forward causal ledger"
                        ),
                    )
                prepared.append({
                    "source_id": item.get("research_shadow_tag"),
                    "created": bool(prepared_item.get("created")),
                    "experiment_id": experiment_id,
                    "activated": bool(activation),
                })
            except Exception as exc:
                errors.append({
                    "source_id": item.get("research_shadow_tag"),
                    "error": str(exc),
                })
    except Exception as exc:
        errors.append({"source_id": "research_ledger", "error": str(exc)})

    now = datetime.now(timezone.utc)
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    stalled = []
    auto_disarm = []
    try:
        _research_sync_assignment_outcomes(con)
        active = [
            dict(row) for row in con.execute(
                """SELECT * FROM learning_experiments
                   WHERE source_type='research_candidate'
                     AND status IN ('active','collecting','review')"""
            ).fetchall()
        ]
        for row in active:
            last = _parse_utc_iso(
                row.get("last_progress_at")
                or row.get("activated_at")
                or row.get("created_at")
            )
            count = int(con.execute(
                """SELECT COUNT(*) FROM learning_experiment_assignments
                   WHERE experiment_id=?""",
                (row["experiment_id"],),
            ).fetchone()[0])
            if count:
                latest = con.execute(
                    """SELECT MAX(assigned_at)
                       FROM learning_experiment_assignments
                       WHERE experiment_id=?""",
                    (row["experiment_id"],),
                ).fetchone()[0]
                con.execute(
                    """UPDATE learning_experiments
                       SET last_progress_at=?, blocked_reason=NULL
                       WHERE experiment_id=?""",
                    (latest, row["experiment_id"]),
                )
                continue
            if last and (now - last.astimezone(timezone.utc)).total_seconds() >= 72 * 3600:
                elapsed_hours = (
                    now - last.astimezone(timezone.utc)
                ).total_seconds() / 3600.0
                if elapsed_hours >= 168:
                    reason = (
                        "No eligible assignments for 7 days; automatically "
                        "parked so the experiment cannot block scheduler capacity."
                    )
                    con.execute(
                        """UPDATE learning_experiments
                           SET status='parked', lifecycle_state='parked',
                               authority_mode='shadow_only', blocked_reason=?,
                               updated_at=?, probation_stage='stopped'
                           WHERE experiment_id=?""",
                        (reason, now.isoformat(), row["experiment_id"]),
                    )
                    _learning_append_event(
                        con,
                        row["experiment_id"],
                        "automatically_parked_stale",
                        {
                            "reason": reason,
                            "elapsed_hours": round(elapsed_hours, 1),
                            "behavior_promoted": False,
                            "live_behavior_changed": False,
                        },
                        now.isoformat(),
                    )
                    auto_disarm.append({
                        "experiment_id": row["experiment_id"],
                        "source_id": row.get("source_id"),
                        "status": "parked",
                        "reason": reason,
                    })
                else:
                    reason = "No eligible assignments for 72h; scheduler is monitoring until the 7-day auto-park boundary."
                    con.execute(
                        """UPDATE learning_experiments
                           SET blocked_reason=?, updated_at=?
                           WHERE experiment_id=?""",
                        (reason, now.isoformat(), row["experiment_id"]),
                    )
                stalled.append({
                    "experiment_id": row["experiment_id"],
                    "reason": reason,
                })
        con.commit()
    finally:
        con.close()
    for item in auto_disarm:
        try:
            _research_auto_stop_falsified(item)
        except Exception as exc:
            errors.append({
                "source_id": item.get("source_id"),
                "error": f"stale Paper disarm failed: {exc}",
            })
    return {
        "success": not errors,
        "prepared": prepared,
        "stalled": stalled,
        "errors": errors,
        "behavior_changed": False,
        "live_changed": False,
    }


def _learning_policy_snapshot(strategy_key: str, paper_cfg: dict | None = None) -> dict:
    """Capture the effective Paper policy whose outcomes must stay attributable."""
    paper_cfg = paper_cfg or _load_paper_config()
    try:
        strategy = get_strategy_config(strategy_key, include_disabled=True)
    except Exception:
        strategy = {"key": strategy_key, "unavailable": True}
    paper_fields = (
        "min_conviction",
        "flow_required",
        "min_flow_score",
        "max_atr_pct",
        "max_trend_score_abs",
        "max_open_positions",
        "max_holding_hours",
        "paper_maker_fee_bps",
        "paper_taker_fee_bps",
        "paper_slippage_bps",
        "paper_stop_mode",
        "paper_breakeven_buffer_bps",
        "paper_trailing_atr_mult",
        "paper_margin_mode",
        "paper_sizing_mode",
        "risk_pct_per_trade",
        "disabled_strategies",
    )
    return {
        "contract_version": LEARNING_CONTRACT_VERSION,
        "strategy_key": strategy_key,
        "strategy": strategy,
        "strategy_overrides": _load_strategy_overrides().get(strategy_key, {}),
        "paper": {key: paper_cfg.get(key) for key in paper_fields},
        "research_paper_rules": _research_rule_controls_by_tag(),
        "scoring_version": SCORE_VERSION,
        "evaluation_version": "paper_min1_chunked_v1",
    }


def _learning_append_event(
    con: sqlite3.Connection,
    experiment_id: str,
    event_type: str,
    payload: dict,
    event_at: str | None = None,
) -> dict:
    """Append one hash-chained event inside the caller's transaction."""
    previous = con.execute(
        """SELECT sequence, event_hash
           FROM learning_experiment_events
           WHERE experiment_id=?
           ORDER BY sequence DESC LIMIT 1""",
        (experiment_id,),
    ).fetchone()
    sequence = int(previous[0]) + 1 if previous else 1
    previous_hash = previous[1] if previous else None
    event_at = event_at or datetime.now(timezone.utc).isoformat()
    digest = _learning_event_hash(
        experiment_id,
        sequence,
        event_type,
        event_at,
        payload,
        previous_hash,
    )
    con.execute(
        """INSERT INTO learning_experiment_events
           (experiment_id, sequence, event_type, event_at, payload_json,
            previous_hash, event_hash)
           VALUES (?,?,?,?,?,?,?)""",
        (
            experiment_id,
            sequence,
            event_type,
            event_at,
            json.dumps(payload, sort_keys=True, default=str),
            previous_hash,
            digest,
        ),
    )
    return {
        "sequence": sequence,
        "event_hash": digest,
        "previous_hash": previous_hash,
    }


def _learning_verify_event_chain(
    con: sqlite3.Connection,
    experiment_id: str,
) -> dict:
    rows = con.execute(
        """SELECT sequence, event_type, event_at, payload_json,
                  previous_hash, event_hash
           FROM learning_experiment_events
           WHERE experiment_id=?
           ORDER BY sequence ASC""",
        (experiment_id,),
    ).fetchall()
    expected_previous = None
    problems: list[str] = []
    for expected_sequence, row in enumerate(rows, 1):
        sequence, event_type, event_at, payload_json, previous_hash, digest = row
        payload = _learning_json(payload_json, {})
        expected = _learning_event_hash(
            experiment_id,
            sequence,
            event_type,
            event_at,
            payload,
            previous_hash,
        )
        if sequence != expected_sequence:
            problems.append(f"sequence {sequence} expected {expected_sequence}")
        if previous_hash != expected_previous:
            problems.append(f"sequence {sequence} previous hash mismatch")
        if digest != expected:
            problems.append(f"sequence {sequence} event hash mismatch")
        expected_previous = digest
    return {
        "valid": not problems and bool(rows),
        "event_count": len(rows),
        "problems": problems,
        "head_hash": expected_previous,
    }


def _learning_register_suggestion_experiment(
    suggestion: dict,
    contract: dict,
    baseline: dict,
    activated_at: str,
) -> dict:
    """Register one immutable, forward-only Paper experiment."""
    strategy_key = str(suggestion.get("strategy") or "").strip()
    if not strategy_key:
        raise ValueError("learning experiment requires a strategy")
    policy = _learning_policy_snapshot(strategy_key)
    policy_fingerprint = _learning_fingerprint(policy)
    source_id = str(suggestion.get("id") or "").strip()
    experiment_id = (
        f"suggestion:{source_id}:"
        f"{hashlib.sha256((activated_at + policy_fingerprint).encode()).hexdigest()[:12]}"
    )
    scope = contract.get("scope") or {
        "strategy": strategy_key,
        "target_mode": "paper_trial_after_review",
    }
    change_set = contract.get("change_set") or []
    evidence_rules = (
        suggestion.get("evidence_rules")
        or suggestion.get("evaluation_contract")
        or _learning_default_evidence_rules()
    )
    rollback = contract.get("rollback_plan") or {}
    hypothesis = str(
        suggestion.get("hypothesis")
        or suggestion.get("reasoning")
        or suggestion.get("evidence_summary")
        or "Applied strategy change should improve risk-adjusted Paper outcomes."
    ).strip()
    mechanism = str(
        suggestion.get("mechanism")
        or contract.get("plain_language", {}).get("why")
        or "The declared control change should remove or isolate a historically weaker cohort."
    ).strip()
    restricted = bool(contract.get("application_policy", {}).get("restricted"))

    con = sqlite3.connect(DB_PATH)
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS learning_experiments (
                experiment_id TEXT PRIMARY KEY, contract_version TEXT NOT NULL,
                source_type TEXT NOT NULL, source_id TEXT, family TEXT NOT NULL,
                strategy_key TEXT NOT NULL, status TEXT NOT NULL,
                hypothesis TEXT NOT NULL, mechanism TEXT NOT NULL,
                scope_json TEXT NOT NULL, change_set_json TEXT NOT NULL,
                baseline_json TEXT NOT NULL, evidence_rules_json TEXT NOT NULL,
                rollback_json TEXT NOT NULL, policy_json TEXT NOT NULL,
                policy_fingerprint TEXT NOT NULL, authority_mode TEXT NOT NULL,
                user_approved INTEGER NOT NULL, capital_change INTEGER NOT NULL,
                execution_change INTEGER NOT NULL, activated_at TEXT NOT NULL,
                created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
                evaluated_at TEXT, result_json TEXT,
                rollback_required INTEGER NOT NULL DEFAULT 0,
                UNIQUE(source_type, source_id, policy_fingerprint)
            )
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS learning_experiment_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                experiment_id TEXT NOT NULL, sequence INTEGER NOT NULL,
                event_type TEXT NOT NULL, event_at TEXT NOT NULL,
                payload_json TEXT NOT NULL, previous_hash TEXT,
                event_hash TEXT NOT NULL,
                UNIQUE(experiment_id, sequence), UNIQUE(event_hash)
            )
        """)
        conflict = con.execute(
            """SELECT experiment_id
               FROM learning_experiments
               WHERE strategy_key=?
                 AND status IN ('active','collecting','review')
               LIMIT 1""",
            (strategy_key,),
        ).fetchone()
        if conflict:
            raise ValueError(
                f"strategy already has an active learning experiment: {conflict[0]}"
            )
        con.execute("BEGIN IMMEDIATE")
        con.execute(
            """INSERT INTO learning_experiments
               (experiment_id, contract_version, source_type, source_id, family,
                strategy_key, status, hypothesis, mechanism, scope_json,
                change_set_json, baseline_json, evidence_rules_json,
                rollback_json, policy_json, policy_fingerprint, authority_mode,
                user_approved, capital_change, execution_change, activated_at,
                created_at, updated_at)
               VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                experiment_id,
                LEARNING_CONTRACT_VERSION,
                "learner_suggestion",
                source_id,
                str(suggestion.get("type") or "strategy_change"),
                strategy_key,
                "collecting",
                hypothesis,
                mechanism,
                json.dumps(scope, sort_keys=True, default=str),
                json.dumps(change_set, sort_keys=True, default=str),
                json.dumps(baseline, sort_keys=True, default=str),
                json.dumps(evidence_rules, sort_keys=True, default=str),
                json.dumps(rollback, sort_keys=True, default=str),
                json.dumps(policy, sort_keys=True, default=str),
                policy_fingerprint,
                "paper_only",
                1,
                1 if restricted else 0,
                0,
                activated_at,
                activated_at,
                activated_at,
            ),
        )
        _learning_append_event(
            con,
            experiment_id,
            "activated",
            {
                "source_id": source_id,
                "strategy_key": strategy_key,
                "policy_fingerprint": policy_fingerprint,
                "authority_mode": "paper_only",
                "user_approved": True,
                "auto_apply_allowed": False,
                "live_behavior_change_allowed": False,
            },
            activated_at,
        )
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {
        "experiment_id": experiment_id,
        "policy_fingerprint": policy_fingerprint,
        "status": "collecting",
    }


def _learning_bootstrap_applied_suggestions() -> list[dict]:
    """Start forward attribution for previously approved active controls.

    Historical outcomes remain excluded.  This only establishes a new
    deployment-time boundary around a control that is already active.
    """
    registered: list[dict] = []
    for suggestion in _annotate_suggestion_authority(_load_suggestions()):
        if suggestion.get("status") not in {"evaluating", "applied"}:
            continue
        if suggestion.get("learning_experiment_id"):
            continue
        control = suggestion.get("control_authority") or {}
        if not control.get("active"):
            continue
        source_id = str(suggestion.get("id") or "")
        con = sqlite3.connect(DB_PATH)
        existing = con.execute(
            """SELECT experiment_id
               FROM learning_experiments
               WHERE source_type='learner_suggestion' AND source_id=?
                 AND status IN ('active','collecting','review')
               LIMIT 1""",
            (source_id,),
        ).fetchone()
        con.close()
        if existing:
            continue
        activated_at = datetime.now(timezone.utc).isoformat()
        baseline = _suggestion_baseline_snapshot()
        baseline.update({
            "applied_at": activated_at,
            "forward_boundary_reason": (
                "Existing approved control adopted into the exact-policy ledger; "
                "all earlier rows remain legacy-unattributed."
            ),
            "legacy_rows_excluded": True,
        })
        contract = suggestion.get("explainability") or _suggestion_explainability_contract(
            suggestion
        )
        experiment = _learning_register_suggestion_experiment(
            suggestion,
            contract,
            baseline,
            activated_at,
        )
        _update_suggestion_status(
            source_id,
            "evaluating",
            {
                "learning_experiment_id": experiment["experiment_id"],
                "learning_policy_fingerprint": experiment["policy_fingerprint"],
                "learning_contract_version": LEARNING_CONTRACT_VERSION,
                "learning_forward_boundary_at": activated_at,
                "learning_legacy_rows_excluded": True,
            },
        )
        con = sqlite3.connect(DB_PATH)
        _learning_append_event(
            con,
            experiment["experiment_id"],
            "legacy_authority_reconciled",
            {
                "scan_behavior_changed": False,
                "historical_rows_attributed": False,
                "forward_boundary_at": activated_at,
            },
            activated_at,
        )
        con.commit()
        con.close()
        registered.append(experiment)
    return registered


def _learning_attribution_for_trade(
    strategy_key: str,
    paper_cfg: dict,
) -> dict:
    """Return the experiment and exact effective policy for a new Paper trade."""
    policy = _learning_policy_snapshot(strategy_key, paper_cfg)
    fingerprint = _learning_fingerprint(policy)
    experiment_id = None
    try:
        con = sqlite3.connect(DB_PATH)
        row = con.execute(
            """SELECT experiment_id, policy_fingerprint
               FROM learning_experiments
               WHERE strategy_key=?
                 AND status IN ('active','collecting','review')
               ORDER BY activated_at DESC LIMIT 1""",
            (strategy_key,),
        ).fetchone()
        con.close()
        if row and row[1] == fingerprint:
            experiment_id = row[0]
    except Exception as e:
        print(f"[learning] attribution lookup error: {e}", file=sys.stderr)
    return {
        "experiment_id": experiment_id,
        "policy_fingerprint": fingerprint,
        "policy": policy,
    }


def _learning_experiment_rows(
    con: sqlite3.Connection,
    experiment: dict,
) -> tuple[list[dict], list[dict]]:
    treatment = [
        dict(row) for row in con.execute(
            """SELECT result, pnl_pct, size_usd, leverage, closed_at,
                      funding_complete, execution_cost_complete
               FROM paper_trades
               WHERE learning_experiment_id=?
                 AND learning_policy_fingerprint=?
                 AND status='closed'
                 AND result IN ('WIN','LOSS','PARTIAL')
                 AND pnl_pct IS NOT NULL
               ORDER BY closed_at ASC, id ASC""",
            (
                experiment["experiment_id"],
                experiment["policy_fingerprint"],
            ),
        ).fetchall()
    ]
    rules = _learning_json(experiment.get("evidence_rules_json"), {})
    control_n = max(
        int(rules.get("minimum_closed_trades") or 50),
        len(treatment),
    )
    control = [
        dict(row) for row in con.execute(
            """SELECT result, pnl_pct, size_usd, leverage, closed_at,
                      funding_complete, execution_cost_complete
               FROM paper_trades
               WHERE strategy_key=?
                 AND status='closed'
                 AND result IN ('WIN','LOSS','PARTIAL')
                 AND pnl_pct IS NOT NULL
                 AND closed_at < ?
               ORDER BY closed_at DESC, id DESC
               LIMIT ?""",
            (
                experiment["strategy_key"],
                experiment["activated_at"],
                min(control_n, 250),
            ),
        ).fetchall()
    ]
    control.reverse()
    return treatment, control


def _learning_reconcile_suggestion_states() -> dict:
    """Close stale applied lanes without applying or restoring any control."""
    data = _load_suggestions_data()
    suggestions = data.get("suggestions") or []
    annotated = {
        item.get("id"): item
        for item in _annotate_suggestion_authority(suggestions)
    }
    changes: list[dict] = []
    now = datetime.now(timezone.utc).isoformat()
    con = sqlite3.connect(DB_PATH)
    try:
        for suggestion in suggestions:
            if suggestion.get("status") != "evaluating":
                continue
            sid = str(suggestion.get("id") or "")
            authority = (annotated.get(sid) or {}).get("control_authority") or {}
            experiment_id = suggestion.get("learning_experiment_id")
            experiment = (
                con.execute(
                    "SELECT status FROM learning_experiments WHERE experiment_id=?",
                    (experiment_id,),
                ).fetchone()
                if experiment_id else None
            )
            experiment_active = bool(
                experiment and experiment[0] in {"active", "collecting", "review"}
            )
            note = str(suggestion.get("evaluation_note") or "").lower()
            next_status = None
            reason = None
            if authority.get("active") and "cleared" in note:
                next_status = "applied"
                reason = "Explicit legacy evaluation note says cleared; active control retained."
            elif not authority.get("active") and (
                authority.get("managed") or experiment_active
            ):
                next_status = "parked"
                reason = "Applied evaluator no longer owns an active runtime control."
            elif not experiment_active and authority.get("active"):
                next_status = "applied"
                reason = "Active control has no open exact-policy experiment."
            if not next_status:
                continue
            suggestion["status"] = next_status
            suggestion["reconciled_at"] = now
            suggestion["reconciliation_reason"] = reason
            if experiment_active and experiment_id:
                con.execute(
                    """UPDATE learning_experiments
                       SET status='inconclusive', lifecycle_state='reconciled',
                           evaluated_at=?, updated_at=?
                       WHERE experiment_id=?""",
                    (now, now, experiment_id),
                )
                _learning_append_event(
                    con,
                    experiment_id,
                    "suggestion_state_reconciled",
                    {
                        "suggestion_status": next_status,
                        "reason": reason,
                        "automatic_config_change": False,
                        "control_active": bool(authority.get("active")),
                    },
                    now,
                )
            changes.append({
                "id": sid,
                "from": "evaluating",
                "to": next_status,
                "reason": reason,
                "control_active": bool(authority.get("active")),
            })
        if changes:
            _write_suggestions_data(data)
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    return {
        "success": True,
        "changes": changes,
        "changed_count": len(changes),
        "automatic_config_change": False,
        "live_changed": False,
    }


def _learning_evaluate_active_experiments() -> list[dict]:
    """Update evidence verdicts only; never mutate strategy or execution config."""
    results: list[dict] = []
    auto_stop: list[dict] = []
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        _research_sync_assignment_outcomes(con)
        experiments = [
            dict(row) for row in con.execute(
                """SELECT * FROM learning_experiments
                   WHERE status IN ('active','collecting','review')
                   ORDER BY activated_at ASC"""
            ).fetchall()
        ]
        for experiment in experiments:
            assignment_cohorts = None
            if experiment.get("source_type") == "research_candidate":
                assignment_cohorts = _research_experiment_assignment_rows(
                    con, experiment
                )
            if assignment_cohorts and assignment_cohorts.get("all"):
                treatment = assignment_cohorts["treatment"]
                control = assignment_cohorts["control"]
            else:
                treatment, control = _learning_experiment_rows(con, experiment)
            evaluation = _evaluate_learning_experiment(
                treatment,
                control,
                experiment["activated_at"],
                rules=_learning_json(experiment.get("evidence_rules_json"), {}),
            )
            treatment_effective = _research_effective_sample(treatment)
            control_effective = _research_effective_sample(control)
            rules = _learning_json(experiment.get("evidence_rules_json"), {})
            min_effective_days = int(
                rules.get("minimum_effective_days")
                or min(20, int(rules.get("minimum_closed_trades") or 50))
            )
            evaluation["effective_sample"] = {
                "treatment": treatment_effective,
                "control": control_effective,
                "minimum_effective_days": min_effective_days,
            }
            family_key = str(
                experiment.get("hypothesis_family")
                or experiment.get("family")
                or "unknown"
            )
            family_test_count = int(con.execute(
                """SELECT COUNT(*) FROM learning_experiments
                   WHERE source_type='research_candidate'
                     AND COALESCE(hypothesis_family, family)=?""",
                (family_key,),
            ).fetchone()[0]) if experiment.get("source_type") == "research_candidate" else 1
            adjusted_alpha = 0.05 / max(1, family_test_count)
            placebo = _research_permutation_delta_test(
                treatment,
                control,
                iterations=1000,
            )
            evaluation["multiplicity_and_placebo"] = {
                "hypothesis_family": family_key,
                "family_test_count": family_test_count,
                "family_adjusted_alpha": round(adjusted_alpha, 6),
                "permutation_test": placebo,
            }
            cost_evidence_rows = list(treatment) + list(control)
            funding_complete_count = len([
                row for row in cost_evidence_rows
                if int(row.get("funding_complete") or 0) == 1
            ])
            funding_cashflows_complete = bool(cost_evidence_rows) and (
                funding_complete_count == len(cost_evidence_rows)
            )
            execution_complete_count = len([
                row for row in cost_evidence_rows
                if int(row.get("execution_cost_complete") or 0) == 1
            ])
            evaluation["cost_scope"] = {
                "paper_fee_and_slippage": True,
                "blocked_counterfactual_fee_and_slippage": True,
                "funding_cashflows": funding_cashflows_complete,
                "funding_complete_count": funding_complete_count,
                "funding_evidence_count": len(cost_evidence_rows),
                "funding_coverage_pct": (
                    round(funding_complete_count / len(cost_evidence_rows) * 100.0, 1)
                    if cost_evidence_rows else None
                ),
                "execution_cost_complete_count": execution_complete_count,
                "execution_cost_coverage_pct": (
                    round(execution_complete_count / len(cost_evidence_rows) * 100.0, 1)
                    if cost_evidence_rows else None
                ),
                "warning": (
                    None
                    if funding_cashflows_complete
                    else "Funding settlement coverage is incomplete; funding-sensitive effects cannot promote."
                ),
            }
            if assignment_cohorts is not None:
                blocked_shadow = assignment_cohorts.get("blocked_shadow") or []
                blocked_pnls = [
                    float(row.get("pnl_pct") or 0.0) for row in blocked_shadow
                ]
                evaluation["gate_counterfactual"] = {
                    "blocked_closed": len(blocked_shadow),
                    "blocked_avg_pnl_pct": (
                        round(sum(blocked_pnls) / len(blocked_pnls), 4)
                        if blocked_pnls else None
                    ),
                    "profitable_block_rate": (
                        round(
                            len([p for p in blocked_pnls if p > 0])
                            / len(blocked_pnls)
                            * 100.0,
                            2,
                        )
                        if blocked_pnls else None
                    ),
                    "accepted_treatment_closed": len(
                        assignment_cohorts.get("accepted_treatment") or []
                    ),
                    "contaminated_assignments": len([
                        row for row in assignment_cohorts.get("all") or []
                        if row.get("decision") == "contaminated"
                    ]),
                }
            if (
                evaluation.get("verdict") in {
                    "promotion_candidate",
                    "falsified",
                }
                and treatment_effective.get("market_day_count", 0)
                < min_effective_days
            ):
                evaluation["raw_verdict_before_effective_sample_gate"] = (
                    evaluation["verdict"]
                )
                evaluation["verdict"] = "review"
                evaluation["sufficient"] = False
                evaluation.setdefault("reasons", []).append(
                    f"Only {treatment_effective.get('market_day_count', 0)}/"
                    f"{min_effective_days} independent market days."
                )
            if (
                evaluation.get("verdict") == "promotion_candidate"
                and placebo.get("available")
                and float(placebo.get("one_sided_p_value") or 1.0)
                > adjusted_alpha
            ):
                evaluation["raw_verdict_before_placebo_gate"] = (
                    "promotion_candidate"
                )
                evaluation["verdict"] = "review"
                evaluation.setdefault("reasons", []).append(
                    "Treatment separation did not beat the hypothesis-family "
                    "adjusted permutation placebo gate."
                )
            contract_for_cost = _research_experiment_contract_from_row(
                experiment
            )
            funding_sensitive = (
                "funding" in family_key.lower()
                or any(
                    "funding" in str(field).lower()
                    for field in (
                        contract_for_cost.get("required_pre_entry_fields") or []
                    )
                )
            )
            if (
                evaluation.get("verdict") == "promotion_candidate"
                and funding_sensitive
                and not evaluation["cost_scope"]["funding_cashflows"]
            ):
                evaluation["raw_verdict_before_cost_completeness_gate"] = (
                    "promotion_candidate"
                )
                evaluation["verdict"] = "review"
                evaluation.setdefault("reasons", []).append(
                    "Funding-sensitive research cannot promote until realized "
                    "funding cashflows are included in Paper outcomes."
                )
            previous_status = experiment["status"]
            next_status = evaluation["verdict"]
            updated_rules_json = experiment.get("evidence_rules_json")
            extension_count = int(experiment.get("extension_count") or 0)
            if next_status == "review" and evaluation.get("sufficient"):
                max_extensions = max(
                    0, min(1, int(rules.get("maximum_extensions") or 1))
                )
                if extension_count < max_extensions:
                    extended_rules = dict(rules)
                    extended_rules["minimum_closed_trades"] = max(
                        int(rules.get("minimum_closed_trades") or 50) + 1,
                        int(rules.get("minimum_closed_trades") or 50) * 2,
                    )
                    extended_rules["minimum_elapsed_days"] = max(
                        float(rules.get("minimum_elapsed_days") or 7) + 7,
                        14.0,
                    )
                    updated_rules_json = json.dumps(
                        extended_rules, sort_keys=True, default=str
                    )
                    extension_count += 1
                    next_status = "collecting"
                    evaluation["verdict"] = "collecting"
                    evaluation["extension"] = {
                        "automatic": True,
                        "extension_number": extension_count,
                        "new_minimum_closed_trades": extended_rules[
                            "minimum_closed_trades"
                        ],
                        "new_minimum_elapsed_days": extended_rules[
                            "minimum_elapsed_days"
                        ],
                        "maximum_extensions": max_extensions,
                    }
                    evaluation.setdefault("reasons", []).append(
                        "One predeclared extension started; no policy changed."
                    )
                else:
                    next_status = "inconclusive"
                    evaluation["verdict"] = "inconclusive"
                    evaluation.setdefault("reasons", []).append(
                        "The single predeclared extension was exhausted."
                    )
            lifecycle = (
                "promotion_candidate"
                if next_status == "promotion_candidate"
                else "falsified"
                if next_status == "falsified"
                else "inconclusive"
                if next_status == "inconclusive"
                else "review"
                if next_status == "review"
                else "paper_challenger"
            )
            result_json = json.dumps(evaluation, sort_keys=True, default=str)
            now = datetime.now(timezone.utc).isoformat()
            con.execute(
                """UPDATE learning_experiments
                   SET status=?, result_json=?, evaluated_at=?, updated_at=?,
                       rollback_required=?, lifecycle_state=?,
                       last_progress_at=COALESCE(last_progress_at, ?),
                       evidence_rules_json=?, extension_count=?
                   WHERE experiment_id=?""",
                (
                    next_status,
                    result_json,
                    now,
                    now,
                    1 if next_status == "falsified" else 0,
                    lifecycle,
                    now,
                    updated_rules_json,
                    extension_count,
                    experiment["experiment_id"],
                ),
            )
            if next_status != previous_status:
                _learning_append_event(
                    con,
                    experiment["experiment_id"],
                    "verdict_changed",
                    {
                        "from": previous_status,
                        "to": next_status,
                        "evaluation": evaluation,
                        "automatic_config_change": False,
                    },
                    now,
                )
            results.append({
                "experiment_id": experiment["experiment_id"],
                "strategy_key": experiment["strategy_key"],
                **evaluation,
            })
            if (
                experiment.get("source_type") == "research_candidate"
                and next_status == "falsified"
            ):
                auto_stop.append({
                    "experiment_id": experiment["experiment_id"],
                    "source_id": experiment.get("source_id"),
                    "reason": "; ".join(evaluation.get("reasons") or [])
                    or "Predeclared falsification gate failed.",
                })
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()
    for item in auto_stop:
        try:
            _research_auto_stop_falsified(item)
        except Exception as e:
            print(
                f"[research_orchestrator] automatic Paper stop failed "
                f"{item.get('experiment_id')}: {e}",
                file=sys.stderr,
            )
    try:
        _learning_reconcile_suggestion_states()
    except Exception as e:
        print(f"[learning] suggestion reconciliation error: {e}", file=sys.stderr)
    return results


def _learning_strategy_factory_candidates() -> list[dict]:
    paths = (
        "/opt/mt-learner/research/briefs.json",
        os.path.join(os.getcwd(), "mt-learner", "research", "briefs.json"),
    )
    data = {}
    for path in paths:
        if os.path.exists(path):
            data = _hermes_read_json(path, {}) or {}
            break
    candidates: list[dict] = []
    for brief in data.get("briefs", []):
        proposed = brief.get("proposed_strategy")
        if not proposed:
            continue
        payload = proposed.get("api_payload") or {}
        if not (
            proposed.get("base_key")
            or payload.get("base_key")
        ):
            # Entry/risk filter proposals belong in research governance, not
            # the new-strategy factory.
            continue
        candidate = {
            **proposed,
            "hypothesis": brief.get("thesis"),
            "novelty_claim": brief.get("what_is_novel"),
            "source_brief_id": brief.get("id"),
        }
        candidates.append({
            "source_brief_id": brief.get("id"),
            "title": brief.get("title"),
            "confidence": brief.get("confidence"),
            "validation": _validate_strategy_factory_contract(candidate),
        })
    return candidates


def _learning_effectiveness_snapshot(update_evaluations: bool = False) -> dict:
    _ensure_research_orchestrator_schema()
    if update_evaluations:
        _learning_evaluate_active_experiments()
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        experiments = [
            dict(row) for row in con.execute(
                "SELECT * FROM learning_experiments ORDER BY activated_at DESC LIMIT 100"
            ).fetchall()
        ]
        total_paper, attributed_paper = con.execute(
            """SELECT COUNT(*),
                      SUM(CASE WHEN learning_policy_fingerprint IS NOT NULL THEN 1 ELSE 0 END)
               FROM paper_trades"""
        ).fetchone()
        chains = {
            item["experiment_id"]: _learning_verify_event_chain(
                con, item["experiment_id"]
            )
            for item in experiments
        }
        experiment_cards = []
        for item in experiments:
            result = _learning_json(item.get("result_json"), {})
            assignment_counts = con.execute(
                """SELECT COUNT(*),
                          SUM(CASE WHEN arm='treatment' THEN 1 ELSE 0 END),
                          SUM(CASE WHEN arm='control' THEN 1 ELSE 0 END),
                          SUM(CASE WHEN result IS NOT NULL THEN 1 ELSE 0 END)
                   FROM learning_experiment_assignments
                   WHERE experiment_id=?""",
                (item["experiment_id"],),
            ).fetchone()
            experiment_cards.append({
                "experiment_id": item["experiment_id"],
                "source_id": item.get("source_id"),
                "family": item["family"],
                "strategy_key": item["strategy_key"],
                "status": item["status"],
                "hypothesis": item["hypothesis"],
                "mechanism": item["mechanism"],
                "activated_at": item["activated_at"],
                "policy_fingerprint": item["policy_fingerprint"],
                "rollback_required": bool(item["rollback_required"]),
                "idea_type": item.get("idea_type"),
                "decision_surface": item.get("decision_surface"),
                "lifecycle_state": item.get("lifecycle_state") or item["status"],
                "evaluator": item.get("evaluator"),
                "hypothesis_family": item.get("hypothesis_family"),
                "treatment_pct": item.get("treatment_pct"),
                "probation_stage": item.get("probation_stage"),
                "blocked_reason": item.get("blocked_reason"),
                "assignment": {
                    "total": int(assignment_counts[0] or 0),
                    "treatment": int(assignment_counts[1] or 0),
                    "control": int(assignment_counts[2] or 0),
                    "closed": int(assignment_counts[3] or 0),
                },
                "evaluation": result,
                "integrity": chains[item["experiment_id"]],
                "authority": {
                    "mode": item["authority_mode"],
                    "user_approved": bool(item["user_approved"]),
                    "auto_apply_allowed": False,
                    "live_behavior_change_allowed": False,
                },
            })
    finally:
        con.close()
    factory = _learning_strategy_factory_candidates()
    status_counts: dict[str, int] = defaultdict(int)
    for item in experiments:
        status_counts[item["status"]] += 1
    attribution_rate = (
        float(attributed_paper or 0) / float(total_paper or 1)
        if total_paper else 0.0
    )
    mature = sum(
        status_counts.get(status, 0)
        for status in ("review", "falsified", "promotion_candidate", "completed")
    )
    valid_factory = sum(item["validation"]["valid"] for item in factory)
    scores = _learning_maturity_score(
        exact_attribution_rate=attribution_rate,
        experiment_integrity_ok=all(
            chain["valid"] for chain in chains.values()
        ) if chains else True,
        active_experiments=sum(
            status_counts.get(status, 0)
            for status in ACTIVE_EXPERIMENT_STATUSES
        ),
        mature_experiments=mature,
        promoted_experiments=status_counts.get("promotion_candidate", 0)
        + status_counts.get("completed", 0),
        falsified_experiments=status_counts.get("falsified", 0),
        strategy_candidates_valid=valid_factory,
        strategy_candidates_total=len(factory),
    )
    bottlenecks = []
    if attribution_rate < 0.95:
        bottlenecks.append(
            "Legacy Paper rows lack exact policy attribution; only newly created "
            "trades count as causal evidence."
        )
    if mature == 0:
        bottlenecks.append(
            "No exact-policy forward experiment has reached its minimum sample and duration."
        )
    if factory and valid_factory < len(factory):
        bottlenecks.append(
            "Existing research strategy ideas are variants with incomplete entry, "
            "exit, cost, control, or falsification contracts."
        )
    return {
        "success": True,
        "contract_version": LEARNING_CONTRACT_VERSION,
        "scores": scores,
        "attribution": {
            "paper_rows": int(total_paper or 0),
            "exact_policy_rows": int(attributed_paper or 0),
            "exact_policy_rate": round(attribution_rate, 4),
            "legacy_rows_are_causal_evidence": False,
        },
        "experiments": {
            "total": len(experiments),
            "status_counts": dict(status_counts),
            "active_count": sum(
                status_counts.get(status, 0)
                for status in ACTIVE_EXPERIMENT_STATUSES
            ),
            "integrity_ok": all(
                chain["valid"] for chain in chains.values()
            ) if chains else True,
            "items": experiment_cards[:20],
        },
        "strategy_factory": {
            "candidate_count": len(factory),
            "valid_count": valid_factory,
            "authority": "shadow_only",
            "items": factory[:20],
        },
        "adaptive_loop_registry": {
            "serial_applied_strategy_experiments": True,
            "parallel_applied_across_independent_strategies": True,
            "parallel_read_only_research": True,
            "overlapping_policy_windows_allowed": False,
            "legacy_unattributed_rows_excluded": True,
        },
        "safety": {
            "auto_apply_suggestions": False,
            "auto_promote_strategies": False,
            "auto_raise_leverage": False,
            "auto_raise_position_size": False,
            "live_behavior_change": False,
            "falsification_changes_config": False,
        },
        "bottlenecks": bottlenecks,
    }


def _get_custom_strategy_keys() -> set:
    """Return the set of keys in the custom_strategies table."""
    try:
        con = sqlite3.connect(DB_PATH)
        rows = con.execute("SELECT key FROM custom_strategies WHERE enabled=1").fetchall()
        con.close()
        return {r[0] for r in rows}
    except Exception:
        return set()


def log_filtered_candidate(candidate: dict) -> None:
    """Shadow-log a candidate blocked by a risk gate. Never crash scanning."""
    try:
        con = sqlite3.connect(DB_PATH, timeout=1)
        con.execute("""
            INSERT INTO filtered_candidates
            (logged_at, gate_key, gate_mode, symbol, exchange, direction, strategy, strategy_key, conviction,
             price, atr_pct, volatility, funding_rate, tags, reason, signal_json)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            datetime.utcnow().isoformat(),
            candidate.get("gate_key", "long_vol_long"),
            candidate.get("gate_mode", "block"),
            candidate.get("symbol", ""),
            candidate.get("exchange", "MEXC"),
            candidate.get("direction", ""),
            candidate.get("strategy", ""),
            candidate.get("strategy_key", ""),
            candidate.get("conviction"),
            candidate.get("price"),
            candidate.get("atr_pct"),
            candidate.get("volatility"),
            candidate.get("funding_rate"),
            ",".join(candidate.get("tags", [])),
            candidate.get("reason", "risk_gate"),
            json.dumps(candidate, default=str),
        ))
        con.commit()
        con.close()
    except Exception as e:
        print(f"log_filtered_candidate error: {e}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Strategy registry
# ---------------------------------------------------------------------------
# Each strategy is a self-contained scoring profile. Weights scale the raw
# points awarded in score_ticker(); filters gate which tickers even enter
# stage 2; leverage_cap and min_conviction are applied at run_scan() time.
#
# Weight proportions are preserved from the Balanced defaults:
#   momentum strong : weak  = 1 : 0.5
#   funding  strong : weak  = 1 : 0.4
#   basis           = full weight or nothing (no weak tier)

