@app.route("/")
def index():
    return render_template("index.html")


@app.route("/api/scan")
def api_scan():
    try:
        threshold    = request.args.get("threshold", CONVICTION_THRESHOLD, type=int)
        strategy_key = request.args.get("strategy", "balanced")
        registry = get_strategy_registry(include_disabled=True)
        strat = registry.get(strategy_key)
        if strat and not strat.get("enabled", True) and strategy_key != "balanced":
            return jsonify({"success": False, "error": f"Strategy '{strategy_key}' is disabled"}), 400
        if strategy_key not in registry:
            strategy_key = "balanced"
        signals, total_pairs = run_scan(threshold=threshold, strategy_key=strategy_key)
        strat = registry.get(strategy_key, registry["balanced"])
        log_signals(signals)
        return jsonify({
            "success":       True,
            "signals":       signals,
            "count":         len(signals),
            "total_pairs":   total_pairs,
            "strategy":      strategy_key,
            "strategy_name": strat["name"],
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/scan/all", methods=["POST"])
def api_scan_all():
    """Fetch tickers once, score and enrich for every enabled strategy sequentially,
    log results, and return all signals grouped by strategy key.
    Strategies run one-at-a-time to avoid overwhelming the MEXC public API with
    concurrent kline requests (each strategy enriches 30 signals × 3 API calls).
    The frontend caches the results so strategy switching is instant."""
    try:
        t0 = time.time()
        expire_stale_signals()

        tickers = fetch_mexc("/contract/ticker")
        if not tickers or not isinstance(tickers, list):
            return jsonify({"success": False, "error": "MEXC ticker feed unavailable"}), 502

        total_pairs = len(tickers)
        registry = get_strategy_registry()
        results: dict = {}

        for key in registry:
            sigs, _ = run_scan(strategy_key=key, tickers=tickers)
            log_signals(sigs)
            results[key] = {
                "signals":     sigs,
                "total_pairs": total_pairs,
                "strategy":    key,
            }

        scan_time = round(time.time() - t0, 2)
        return jsonify({
            "success":     True,
            "results":     results,
            "total_pairs": total_pairs,
            "scan_time":   scan_time,
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/scan/strategy", methods=["POST"])
def api_scan_strategy():
    """Scan one selected strategy across one exchange.

    The dashboard's primary Scan action uses this bounded route. Scanning every
    enabled strategy sequentially grew past normal browser request lifetimes as
    the strategy library expanded; the explicit multi-scan route remains
    available for deliberate broad scans.
    """
    try:
        payload = request.get_json(silent=True) or {}
        exchange = str(payload.get("exchange") or "MEXC").strip().upper()
        strategy_key = str(payload.get("strategy") or "balanced").strip()
        registry = get_strategy_registry(include_disabled=True)
        strategy = registry.get(strategy_key)
        if strategy is None:
            return jsonify({"success": False, "error": f"Unknown strategy '{strategy_key}'"}), 400
        if not strategy.get("enabled", True) and strategy_key != "balanced":
            return jsonify({"success": False, "error": f"Strategy '{strategy_key}' is disabled"}), 400

        expire_stale_signals()
        if exchange == "MEXC":
            tickers = fetch_mexc("/contract/ticker")
        elif exchange == "HYPERLIQUID":
            universe, asset_ctxs = fetch_hl_meta_and_ctxs()
            tickers = normalize_hl_tickers(universe, asset_ctxs)
        elif exchange == "BYBIT":
            tickers = _fetch_exchange_tickers("BYBIT")
        else:
            return jsonify({"success": False, "error": f"Unsupported exchange '{exchange}'"}), 400
        if not tickers or not isinstance(tickers, list):
            return jsonify({
                "success": False,
                "error": f"{exchange.title()} ticker feed unavailable",
            }), 502

        t0 = time.time()
        signals, _ = run_scan(
            strategy_key=strategy_key,
            tickers=tickers,
            exchange=exchange,
        )
        log_signals(signals)
        total_pairs = len(tickers)
        return jsonify({
            "success": True,
            "results": {
                strategy_key: {
                    "signals": signals,
                    "total_pairs": total_pairs,
                    "strategy": strategy_key,
                },
            },
            "total_pairs": total_pairs,
            "strategy": strategy_key,
            "exchange": exchange,
            "scan_time": round(time.time() - t0, 2),
            "scope": "selected_strategy",
        })
    except Exception as e:
        print(f"[api/scan/strategy] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


