# ---------------------------------------------------------------------------
# Exchange configuration
# ---------------------------------------------------------------------------

EXCHANGE_CONFIG_PATH = "data/exchange_config.json"
_DEFAULT_EXCHANGE_CONFIG = {"enabled": ["MEXC", "HYPERLIQUID"]}


def _load_exchange_config() -> dict:
    try:
        with open(EXCHANGE_CONFIG_PATH) as f:
            cfg = json.load(f)
        # Validate enabled list — only keep known exchanges
        known = set(SUPPORTED_EXCHANGES.keys())
        cfg["enabled"] = [e for e in cfg.get("enabled", []) if e in known]
        if not cfg["enabled"]:
            cfg["enabled"] = list(_DEFAULT_EXCHANGE_CONFIG["enabled"])
        return cfg
    except (FileNotFoundError, json.JSONDecodeError):
        return dict(_DEFAULT_EXCHANGE_CONFIG)


def _save_exchange_config(cfg: dict) -> None:
    os.makedirs("data", exist_ok=True)
    with open(EXCHANGE_CONFIG_PATH, "w") as f:
        json.dump(cfg, f, indent=2)


@app.route("/api/exchanges")
def api_exchanges():
    """Return SUPPORTED_EXCHANGES registry + current enable/disable config."""
    cfg = _load_exchange_config()
    enabled_set = set(cfg["enabled"])
    exchanges = []
    for key, meta in SUPPORTED_EXCHANGES.items():
        exchanges.append({
            "key":       key,
            "name":      meta["name"],
            "enabled":   key in enabled_set,
            "quote":     meta.get("quote", "USDT"),
            "geo_free":  meta.get("geo_free", True),
            "funding_interval_h": meta.get("funding_interval_h", 8),
        })
    return jsonify({"success": True, "exchanges": exchanges, "enabled": cfg["enabled"]})


@app.route("/api/exchanges/config", methods=["PATCH"])
def api_exchanges_config():
    """Toggle an exchange on/off. Body: {"exchange": "BYBIT", "enabled": true}"""
    try:
        body = request.get_json(force=True) or {}
        exch = str(body.get("exchange", "")).upper()
        if exch not in SUPPORTED_EXCHANGES:
            return jsonify({"success": False, "error": f"Unknown exchange: {exch}"}), 400
        enable = bool(body.get("enabled", True))
        cfg = _load_exchange_config()
        enabled = list(cfg.get("enabled", []))
        if enable and exch not in enabled:
            enabled.append(exch)
        elif not enable and exch in enabled:
            enabled.remove(exch)
            if not enabled:
                return jsonify({"success": False, "error": "Cannot disable all exchanges"}), 400
        cfg["enabled"] = enabled
        _save_exchange_config(cfg)
        return jsonify({"success": True, "enabled": enabled})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/scan/multi", methods=["POST"])
def api_scan_multi():
    """Scan all enabled exchanges simultaneously using parallel threads.
    Returns {exchange_key: {results, total_pairs, scan_time}} per exchange."""
    try:
        t0 = time.time()
        expire_stale_signals()

        cfg = _load_exchange_config()
        enabled = cfg.get("enabled", ["MEXC"])

        def _scan_exchange(exch: str) -> tuple[str, dict]:
            try:
                if exch == "MEXC":
                    raw = fetch_mexc("/contract/ticker")
                elif exch == "HYPERLIQUID":
                    universe, asset_ctxs = fetch_hl_meta_and_ctxs()
                    raw = normalize_hl_tickers(universe, asset_ctxs)
                else:
                    raw = _fetch_exchange_tickers(exch)

                if not raw:
                    return exch, {"error": f"{exch} ticker feed unavailable", "results": {}}

                total_pairs = len(raw)
                registry = get_strategy_registry()
                results: dict = {}
                for key in registry:
                    sigs, _ = run_scan(strategy_key=key, tickers=raw, exchange=exch)
                    log_signals(sigs)
                    results[key] = {
                        "signals":     sigs,
                        "total_pairs": total_pairs,
                        "strategy":    key,
                    }
                return exch, {"results": results, "total_pairs": total_pairs}
            except Exception as exc:
                return exch, {"error": str(exc), "results": {}}

        per_exchange: dict = {}
        with ThreadPoolExecutor(max_workers=len(enabled)) as pool:
            for exch, data in pool.map(_scan_exchange, enabled):
                per_exchange[exch] = data

        scan_time = round(time.time() - t0, 2)
        return jsonify({
            "success":      True,
            "per_exchange": per_exchange,
            "enabled":      enabled,
            "scan_time":    scan_time,
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/market")
def api_market():
    try:
        exchange = request.args.get("exchange", "mexc").strip().lower()
        if exchange == "hyperliquid":
            universe, asset_ctxs = fetch_hl_meta_and_ctxs()
            raw_tickers = normalize_hl_tickers(universe, asset_ctxs)
            exchange_key = "HYPERLIQUID"
            unavailable = "Hyperliquid unavailable"
        elif exchange == "bybit":
            raw_tickers = _fetch_exchange_tickers("BYBIT")
            exchange_key = "BYBIT"
            unavailable = "Bybit unavailable"
        else:
            raw_tickers = fetch_mexc("/contract/ticker")
            exchange_key = "MEXC"
            unavailable = "MEXC unavailable"

        if not raw_tickers or not isinstance(raw_tickers, list):
            return jsonify({"success": False, "error": unavailable}), 502

        coinglass_snapshot = get_coin_market_snapshot()
        pairs = []
        for t in raw_tickers:
            canonical = normalize_ticker_for_scoring(t, exchange_key)
            if not canonical:
                continue
            scored = score_ticker(canonical, coinglass_snapshot=coinglass_snapshot)
            if scored:
                pairs.append(scored)

        pairs.sort(key=lambda p: p["conviction_base"], reverse=True)
        return jsonify({
            "success": True,
            "pairs": pairs,
            "count": len(pairs),
            "exchange": exchange_key,
            "coinglass_enabled": coinglass_enabled(),
            "coinglass_pairs": len(coinglass_snapshot),
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/market/summary")
def api_market_summary():
    """
    Live market summary: top movers, losers, volume, extreme funding, volatility watch,
    volume spikes (requires snapshot history), and latest BTC/ETH market context.
    """
    try:
        exchange_param = request.args.get("exchange", "mexc").strip().lower()

        if exchange_param == "hyperliquid":
            universe, asset_ctxs = fetch_hl_meta_and_ctxs()
            raw_tickers = normalize_hl_tickers(universe, asset_ctxs)
            exchange_label = "HYPERLIQUID"
        elif exchange_param == "bybit":
            raw_tickers = _fetch_exchange_tickers("BYBIT")
            exchange_label = "BYBIT"
        else:
            raw_tickers = fetch_mexc("/contract/ticker")
            exchange_label = "MEXC"

        if not raw_tickers or not isinstance(raw_tickers, list):
            return jsonify({"success": False, "error": "no ticker data"}), 502

        coinglass_snapshot = get_coin_market_snapshot()
        scored = []
        for t in raw_tickers:
            canonical = normalize_ticker_for_scoring(t, exchange_label)
            if canonical:
                s = score_ticker(canonical, coinglass_snapshot=coinglass_snapshot)
                if s:
                    scored.append(s)

        # 7-day avg volume from snapshots for spike detection
        vol_avgs: dict[str, float] = {}
        try:
            cutoff_7d = (datetime.utcnow() - timedelta(days=7)).isoformat()
            con = sqlite3.connect(DB_PATH)
            rows = con.execute("""
                SELECT symbol, AVG(volume_24h), COUNT(*)
                FROM ticker_snapshots
                WHERE ts > ? AND exchange = ?
                GROUP BY symbol HAVING COUNT(*) >= 3
            """, (cutoff_7d, exchange_label)).fetchall()
            con.close()
            vol_avgs = {r[0]: r[1] for r in rows}
        except Exception:
            pass

        def _change(s):  return s.get("change_24h_pct") or 0
        def _vol(s):     return s.get("volume_24h") or 0
        def _funding(s): return s.get("funding_rate") or 0

        # Volume spikes: current vol > 1.5× 7-day avg (only once history exists)
        volume_spikes = []
        for s in scored:
            avg = vol_avgs.get(s["symbol"])
            cur = _vol(s)
            if avg and avg > 0 and cur > avg * 1.5:
                volume_spikes.append({**s, "vol_spike_ratio": round(cur / avg, 2)})
        volume_spikes.sort(key=lambda x: x["vol_spike_ratio"], reverse=True)

        # Volatility watch: combined score from |change| + |funding| magnitude
        def _vwatch(s):
            return abs(_change(s)) * 10 + abs(_funding(s)) * 5000

        return jsonify({
            "success":                  True,
            "exchange":                 exchange_label,
            "top_movers":               sorted(scored, key=_change, reverse=True)[:6],
            "top_losers":               sorted(scored, key=_change)[:6],
            "top_volume":               sorted(scored, key=_vol, reverse=True)[:6],
            "extreme_funding_positive": sorted(scored, key=_funding, reverse=True)[:5],
            "extreme_funding_negative": sorted(scored, key=_funding)[:5],
            "volatility_watch":         sorted(scored, key=_vwatch, reverse=True)[:8],
            "volume_spikes":            volume_spikes[:6],
            "market_context":           get_latest_market_context(),
            "has_history":              len(vol_avgs) > 0,
            "snapshot_symbols":         len(vol_avgs),
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/signal/<symbol>")
def api_signal(symbol: str):
    """
    Return a fully-enriched signal for a single symbol. Used by the signal
    detail modal to refresh or display a specific ticker on demand.
    Fetches all tickers and finds the matching one — MEXC's public ticker
    endpoint doesn't support single-symbol filtering reliably.

    Strategy resolution order:
      1. ?strategy=<key> query param (explicit override)
      2. Most recent logged signal's strategy_key for this symbol (from DB)
      3. 'balanced' fallback
    """
    try:
        exchange = request.args.get("exchange", "mexc").strip().lower()
        # Resolve which strategy to use for enrichment
        strategy_key = request.args.get("strategy", "").strip().lower()
        registry = get_strategy_registry(include_disabled=True)
        if not strategy_key or strategy_key not in registry:
            try:
                con = sqlite3.connect(DB_PATH)
                row = con.execute(
                    "SELECT strategy_key FROM signals WHERE symbol=? ORDER BY logged_at DESC LIMIT 1",
                    (symbol.upper(),),
                ).fetchone()
                con.close()
                if row and row[0] and row[0] in registry:
                    strategy_key = row[0]
                else:
                    strategy_key = "balanced"
            except Exception:
                strategy_key = "balanced"

        strat = registry.get(strategy_key, registry["balanced"])

        if exchange == "hyperliquid":
            raw_tickers = normalize_hl_tickers(*fetch_hl_meta_and_ctxs())
            exchange_key = "HYPERLIQUID"
            unavailable = "Hyperliquid unavailable"
        elif exchange == "bybit":
            raw_tickers = _fetch_exchange_tickers("BYBIT")
            exchange_key = "BYBIT"
            unavailable = "Bybit unavailable"
        else:
            raw_tickers = fetch_mexc("/contract/ticker")
            exchange_key = "MEXC"
            unavailable = "MEXC unavailable"
        if not raw_tickers:
            return jsonify({"success": False, "error": unavailable}), 502

        requested_symbol = symbol.upper()
        # For Bybit, canonical symbols have underscore ("BTC_USDT") but raw tickers
        # use no separator ("BTCUSDT"). Normalize each raw ticker on the fly to match.
        def _sym_matches(raw_t: dict) -> bool:
            raw_sym = str(raw_t.get("symbol", "")).upper()
            if raw_sym == requested_symbol:
                return True
            if exchange_key == "BYBIT":
                from lib.bybit_client import normalize_bybit_symbol
                return normalize_bybit_symbol(raw_sym).upper() == requested_symbol
            return False

        raw_ticker = next((t for t in raw_tickers if _sym_matches(t)), None)
        if not raw_ticker:
            return jsonify({"success": False, "error": f"Symbol {symbol!r} not found"}), 404

        ticker = normalize_ticker_for_scoring(raw_ticker, exchange_key)
        if not ticker:
            return jsonify({"success": False, "error": f"Could not normalize {symbol!r}"}), 404

        coinglass_snapshot = get_coin_market_snapshot()
        base = score_ticker(ticker, strategy=strat, coinglass_snapshot=coinglass_snapshot)
        if not base:
            return jsonify({"success": False, "error": "Unable to score ticker"}), 422

        signal = enrich_signal(
            base,
            strategy=strat,
            strict_kline_gate=False,
            strict_trade_gates=False,
        )
        if not signal:
            return jsonify({"success": False, "error": "Insufficient kline data"}), 422
        _apply_liquidation_to_signal(signal)

        return jsonify({"success": True, "signal": signal})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


_CHART_INTERVALS = {
    "1m": {"mexc": "Min1",  "hl": "1m"},
    "5m": {"mexc": "Min5",  "hl": "5m"},
    "15m": {"mexc": "Min15", "hl": "15m"},
    "30m": {"mexc": "Min30", "hl": "30m"},
    "1h": {"mexc": "Min60", "hl": "1h"},
    "4h": {"mexc": "Hour4", "hl": "4h"},
    "8h": {"mexc": "Hour8", "hl": "8h"},
    "1d": {"mexc": "Day1",  "hl": "1d"},
}


def _chart_limit(raw: str | None) -> int:
    try:
        return max(50, min(int(raw or 300), 1000))
    except Exception:
        return 300


def _hl_chart_lookback_hours(interval: str, limit: int) -> int:
    minutes = {
        "1m": 1,
        "5m": 5,
        "15m": 15,
        "30m": 30,
        "1h": 60,
        "4h": 240,
        "8h": 480,
        "1d": 1440,
    }.get(interval, 60)
    return max(24, int(math.ceil(limit * minutes / 60 * 1.2)))


def _mexc_chart_candles(symbol: str, interval: str, limit: int) -> list[dict]:
    mexc_interval = _CHART_INTERVALS[interval]["mexc"]
    raw = fetch_mexc(f"/contract/kline/{symbol}", params={"interval": mexc_interval, "limit": limit})
    if not raw or not isinstance(raw, dict):
        return []
    times = raw.get("time") or []
    opens = raw.get("open") or []
    highs = raw.get("high") or []
    lows = raw.get("low") or []
    closes = raw.get("close") or []
    vols = raw.get("vol") or []
    candles = []
    for i in range(min(len(times), len(opens), len(highs), len(lows), len(closes))):
        try:
            candles.append({
                "time": int(float(times[i])),
                "open": float(opens[i]),
                "high": float(highs[i]),
                "low": float(lows[i]),
                "close": float(closes[i]),
                "volume": float(vols[i]) if i < len(vols) else 0.0,
            })
        except Exception:
            continue
    return candles[-limit:]


def _hyperliquid_chart_candles(symbol: str, interval: str, limit: int) -> list[dict]:
    coin = symbol.upper().replace("_USDT", "").replace("_USDC", "")
    rows = fetch_hl_klines(
        coin,
        _CHART_INTERVALS[interval]["hl"],
        lookback_hours=_hl_chart_lookback_hours(interval, limit),
    )
    candles = []
    for row in rows or []:
        try:
            candles.append({
                "time": int(float(row.get("t")) / 1000),
                "open": float(row.get("o")),
                "high": float(row.get("h")),
                "low": float(row.get("l")),
                "close": float(row.get("c")),
                "volume": float(row.get("v") or 0),
            })
        except Exception:
            continue
    candles.sort(key=lambda x: x["time"])
    return candles[-limit:]


def _canonical_usdt_symbol(symbol: str) -> str:
    s = (symbol or "").strip().upper().replace("-", "_").replace("/", "_")
    if "_" not in s and s.endswith("USDT"):
        s = s[:-4] + "_USDT"
    if "_" not in s:
        s = s + "_USDT"
    return s


def _binance_symbol_to_raw(symbol: str) -> str:
    return _canonical_usdt_symbol(symbol).replace("_", "")


def _binance_chart_candles(symbol: str, interval: str, limit: int) -> list[dict]:
    """Fetch Binance USDT-M futures candles as market-wide structure context."""
    candles, _reason = _binance_chart_candles_with_reason(symbol, interval, limit)
    return candles


def _binance_chart_candles_with_reason(symbol: str, interval: str, limit: int) -> tuple[list[dict], str | None]:
    """Fetch Binance USDT-M futures candles and preserve useful unavailable reasons."""
    raw_symbol = _binance_symbol_to_raw(symbol)
    try:
        resp = requests.get(
            f"{BINANCE_FAPI}/fapi/v1/klines",
            params={"symbol": raw_symbol, "interval": interval, "limit": max(50, min(limit, 1000))},
            timeout=10,
        )
        if resp.status_code == 400:
            try:
                err = resp.json()
                if err.get("code") == -1121:
                    return [], f"{raw_symbol} is not listed on Binance USDT-M futures"
                return [], str(err.get("msg") or "Binance rejected symbol/interval")
            except Exception:
                return [], "Binance rejected symbol/interval"
        resp.raise_for_status()
        rows = resp.json()
    except Exception as e:
        print(f"[binance_chart] {raw_symbol}: {e}", file=sys.stderr)
        return [], f"Binance request failed: {e}"
    candles = []
    for row in rows if isinstance(rows, list) else []:
        try:
            candles.append({
                "time": int(float(row[0]) / 1000),
                "open": float(row[1]),
                "high": float(row[2]),
                "low": float(row[3]),
                "close": float(row[4]),
                "volume": float(row[5] or 0),
            })
        except Exception:
            continue
    candles = candles[-limit:]
    return candles, None if candles else "Binance returned no candles"


def _ema_values(values: list[float], period: int) -> list[float]:
    if not values:
        return []
    alpha = 2 / (period + 1)
    out = [float(values[0])]
    for v in values[1:]:
        out.append(float(v) * alpha + out[-1] * (1 - alpha))
    return out


def _cluster_price_levels(points: list[tuple[int, float]], current: float, side: str, limit: int = 3) -> list[dict]:
    if current <= 0:
        return []
    tolerance = max(current * 0.0035, 1e-12)
    clusters: list[dict] = []
    for idx, price in sorted(points, key=lambda x: x[1]):
        if price <= 0:
            continue
        match = None
        for c in clusters:
            if abs(price - c["level"]) <= tolerance:
                match = c
                break
        recency = idx / max(1, len(points))
        if match:
            n = match["touches"] + 1
            match["level"] = (match["level"] * match["touches"] + price) / n
            match["touches"] = n
            match["score"] += 1 + recency
        else:
            clusters.append({"level": price, "touches": 1, "score": 1 + recency})
    if side == "support":
        clusters = [c for c in clusters if c["level"] < current]
        clusters.sort(key=lambda c: (c["score"], -abs(current - c["level"])), reverse=True)
    else:
        clusters = [c for c in clusters if c["level"] > current]
        clusters.sort(key=lambda c: (c["score"], -abs(current - c["level"])), reverse=True)
    out = []
    for c in clusters[:limit]:
        distance = (c["level"] - current) / current * 100
        out.append({
            "level": round(c["level"], 8),
            "touches": int(c["touches"]),
            "distance_pct": round(distance, 3),
            "score": round(c["score"], 2),
        })
    out.sort(key=lambda c: abs(c["distance_pct"]))
    return out


def _venue_structure(candles: list[dict], venue: str, interval: str = "15m") -> dict:
    if not candles or len(candles) < 20:
        return {"venue": venue, "available": False, "reason": "insufficient candles"}
    closes = [float(c["close"]) for c in candles]
    highs = [float(c["high"]) for c in candles]
    lows = [float(c["low"]) for c in candles]
    vols = [float(c.get("volume") or 0) for c in candles]
    current = closes[-1]
    prev_4 = closes[-5] if len(closes) >= 5 else closes[0]
    prev_16 = closes[-17] if len(closes) >= 17 else closes[0]
    prev_96 = closes[-97] if len(closes) >= 97 else closes[0]
    ema20 = _ema_values(closes, 20)[-1]
    ema50 = _ema_values(closes, 50)[-1] if len(closes) >= 50 else _ema_values(closes, min(20, len(closes)))[-1]
    trend = "bullish" if ema20 > ema50 and current > ema20 else "bearish" if ema20 < ema50 and current < ema20 else "mixed"
    lookback_high = max(highs[-21:-1]) if len(highs) >= 22 else max(highs[:-1])
    lookback_low = min(lows[-21:-1]) if len(lows) >= 22 else min(lows[:-1])
    breakout = current > lookback_high
    breakdown = current < lookback_low
    base_vols = vols[-33:-3] if len(vols) >= 33 else vols[:-3]
    recent_vol = sum(vols[-3:]) / 3 if len(vols) >= 3 else vols[-1]
    base_vol = sum(base_vols) / len(base_vols) if base_vols else None
    volume_expansion = recent_vol / base_vol if base_vol and base_vol > 0 else None
    ranges = [max(0, highs[i] - lows[i]) for i in range(len(candles))]
    avg_range = sum(ranges[-20:]) / min(20, len(ranges))
    support_points = [(i, lows[i]) for i in range(max(0, len(lows) - 120), len(lows))]
    resistance_points = [(i, highs[i]) for i in range(max(0, len(highs) - 120), len(highs))]
    return {
        "venue": venue,
        "available": True,
        "interval": interval,
        "price": round(current, 8),
        "change_1h_pct": round(_pct_change(current, prev_4) or 0, 3),
        "change_4h_pct": round(_pct_change(current, prev_16) or 0, 3),
        "change_24h_pct": round(_pct_change(current, prev_96) or 0, 3),
        "trend": trend,
        "ema20": round(ema20, 8),
        "ema50": round(ema50, 8),
        "breakout_20": breakout,
        "breakdown_20": breakdown,
        "volume_expansion": round(volume_expansion, 3) if volume_expansion is not None else None,
        "avg_range_pct": round(avg_range / current * 100, 3) if current > 0 else None,
        "supports": _cluster_price_levels(support_points, current, "support"),
        "resistances": _cluster_price_levels(resistance_points, current, "resistance"),
    }


def _build_cross_venue_structure(symbol: str, interval: str = "15m", limit: int = 160) -> dict:
    symbol = _canonical_usdt_symbol(symbol)
    interval = interval if interval in _CHART_INTERVALS else "15m"
    limit = max(80, min(int(limit or 160), 500))
    mexc = _venue_structure(_mexc_chart_candles(symbol, interval, limit), "MEXC", interval)
    binance_candles, binance_reason = _binance_chart_candles_with_reason(symbol, interval, limit)
    binance = _venue_structure(binance_candles, "BINANCE", interval)
    if not binance.get("available") and binance_reason:
        binance["reason"] = binance_reason
    hl = _venue_structure(_hyperliquid_chart_candles(symbol, interval, min(limit, 240)), "HYPERLIQUID", interval)
    venues = {"mexc": mexc, "binance": binance, "hyperliquid": hl}

    tags = []
    notes = []
    if binance.get("available") and mexc.get("available"):
        if binance["trend"] == mexc["trend"] and binance["trend"] in {"bullish", "bearish"}:
            tags.append(f"cross_venue_{binance['trend']}_alignment")
            notes.append(f"Binance and MEXC are both {binance['trend']} on {interval}.")
        if mexc.get("breakout_20") and binance.get("breakout_20"):
            tags.append("binance_confirmed_breakout")
            notes.append("Both venues are breaking above recent structure.")
        elif mexc.get("breakout_20") and not binance.get("breakout_20"):
            tags.append("mexc_local_pump_no_confirm")
            notes.append("MEXC is breaking out without Binance confirmation; avoid chasing local-only moves.")
        if mexc.get("breakdown_20") and binance.get("breakdown_20"):
            tags.append("binance_confirmed_breakdown")
            notes.append("Both venues are breaking below recent structure.")
        elif mexc.get("breakdown_20") and not binance.get("breakdown_20"):
            tags.append("mexc_local_flush_no_confirm")
            notes.append("MEXC is breaking down without Binance confirmation; wick/fakeout risk is higher.")
        lead_gap = abs(float(binance.get("change_1h_pct") or 0)) - abs(float(mexc.get("change_1h_pct") or 0))
        if lead_gap > 1.5:
            tags.append("binance_leads_mexc")
            notes.append("Binance has a stronger 1h impulse than MEXC, so MEXC may be lagging market-wide flow.")
        price_gap = None
        if mexc.get("price") and binance.get("price"):
            price_gap = (mexc["price"] - binance["price"]) / binance["price"] * 100
            if abs(price_gap) > 0.35:
                tags.append("venue_price_divergence")
                notes.append(f"MEXC trades {price_gap:+.2f}% versus Binance; use MEXC levels for execution.")
    else:
        tags.append("binance_unavailable" if not binance.get("available") else "mexc_unavailable")
        notes.append("Cross-venue confirmation is incomplete.")
    if not notes and binance.get("available") and mexc.get("available"):
        tags.append("cross_venue_mixed")
        notes.append("Binance and MEXC are both available, but structure is mixed; wait for a cleaner confirm/reject branch.")

    bias = "neutral"
    if any(t in tags for t in ("binance_confirmed_breakout", "cross_venue_bullish_alignment")):
        bias = "bullish"
    if any(t in tags for t in ("binance_confirmed_breakdown", "cross_venue_bearish_alignment")):
        bias = "bearish"
    if any(t.endswith("_no_confirm") for t in tags):
        bias = "caution"
    return {
        "symbol": symbol,
        "interval": interval,
        "generated_at": datetime.utcnow().isoformat(),
        "bias": bias,
        "tags": sorted(set(tags)),
        "notes": notes,
        "venues": venues,
    }


def _nearest_level(levels: list[dict]) -> dict | None:
    if not levels:
        return None
    return sorted(levels, key=lambda x: abs(float(x.get("distance_pct") or 0)))[0]


def _build_trade_buddy_brief(symbol: str, interval: str = "15m") -> dict:
    cv = _build_cross_venue_structure(symbol, interval=interval, limit=180)
    venue_listing = _venue_symbol_lookup(symbol)
    mexc = cv.get("venues", {}).get("mexc", {})
    binance = cv.get("venues", {}).get("binance", {})
    price = float(mexc.get("price") or binance.get("price") or 0)
    support = _nearest_level(mexc.get("supports") or [])
    resistance = _nearest_level(mexc.get("resistances") or [])
    atr_proxy_pct = float(mexc.get("avg_range_pct") or 1.0)
    atr_value = max(price * atr_proxy_pct / 100, price * 0.005) if price else 0
    direction = "LONG" if cv["bias"] == "bullish" else "SHORT" if cv["bias"] == "bearish" else "NEUTRAL"

    long_trigger = resistance["level"] if resistance else round(price + atr_value, 8)
    long_pullback = support["level"] if support else round(price - atr_value, 8)
    short_trigger = support["level"] if support else round(price - atr_value, 8)
    short_retest = resistance["level"] if resistance else round(price + atr_value, 8)

    if direction == "LONG":
        entries, exits, stop = generate_ladders(price, atr_value, tiers=3, direction="LONG")
        primary = (
            f"Bullish while MEXC holds above {long_pullback:.8g}. Best long is either a pullback/reclaim "
            f"near support or a clean 15m close through {long_trigger:.8g} with Binance confirmation."
        )
        invalidation = f"Bias weakens if price loses {long_pullback:.8g}; abandon the long plan below {stop:.8g}."
    elif direction == "SHORT":
        entries, exits, stop = generate_ladders(price, atr_value, tiers=3, direction="SHORT")
        primary = (
            f"Bearish while MEXC remains capped below {short_retest:.8g}. Best short is a weak bounce into "
            f"resistance or a clean 15m loss of {short_trigger:.8g} with Binance confirmation."
        )
        invalidation = f"Bias weakens if price reclaims {short_retest:.8g}; abandon the short plan above {stop:.8g}."
    else:
        entries, exits, stop = [], [], None
        primary = (
            "No clean directional trade yet. Wait for Binance and MEXC to agree on a reclaim, breakdown, "
            "or confirmed retest before treating this as actionable."
        )
        invalidation = "Neutral plan: no trade until a branch triggers with cross-venue confirmation."

    risk_flags = []
    if "mexc_local_pump_no_confirm" in cv["tags"] or "mexc_local_flush_no_confirm" in cv["tags"]:
        risk_flags.append("local_move_no_binance_confirmation")
    if "venue_price_divergence" in cv["tags"]:
        risk_flags.append("venue_price_divergence")
    if mexc.get("volume_expansion") and float(mexc["volume_expansion"]) >= 2:
        risk_flags.append("mexc_volume_expansion")
    if binance.get("volume_expansion") and float(binance["volume_expansion"]) >= 2:
        risk_flags.append("binance_volume_expansion")
    research_context = _research_retrieve_context(
        query=f"{symbol} cryptocurrency perpetual futures {cv['bias']} funding liquidity order book volatility momentum risk execution",
        tags=["funding", "liquidity", "order_flow", "volatility", "risk", "execution", "momentum"],
        limit=3,
    )

    scenarios = {
        "base_case": primary,
        "bullish_branch": (
            f"Long branch triggers on a hold/reclaim above {long_trigger:.8g}; targets are next resistance zones "
            f"or ladder exits {', '.join(f'{x:.8g}' for x in exits[:3]) if exits else 'after structure expands'}."
        ),
        "bearish_branch": (
            f"Short branch triggers on rejection below {short_retest:.8g} or loss of {short_trigger:.8g}; targets are "
            f"next support zones or ladder exits {', '.join(f'{x:.8g}' for x in exits[:3]) if exits else 'after structure expands'}."
        ),
        "invalidation": invalidation,
        "no_trade": "No trade if MEXC and Binance disagree, if price is mid-range, or if the trigger candle is already overextended.",
    }
    return {
        "symbol": cv["symbol"],
        "exchange_reference": "MEXC",
        "market_confirmation": "BINANCE",
        "interval": interval,
        "generated_at": cv["generated_at"],
        "bias": cv["bias"],
        "direction": direction,
        "price": round(price, 8) if price else None,
        "cross_venue": cv,
        "venue_listing": venue_listing,
        "levels": {
            "nearest_support": support,
            "nearest_resistance": resistance,
            "mexc_supports": mexc.get("supports") or [],
            "mexc_resistances": mexc.get("resistances") or [],
        },
        "trade_plan": {
            "entries": [round(x, 8) for x in entries],
            "targets": [round(x, 8) for x in exits],
            "stop_loss": round(stop, 8) if stop else None,
            "risk_flags": risk_flags,
            "scenarios": scenarios,
        },
        "research_context": research_context,
        "narrative": [
            f"Bias: {cv['bias'].upper()} on {interval}. " + (" ".join(cv["notes"][:2]) if cv["notes"] else "Venue context is limited."),
            primary,
            invalidation,
            "This is a read-only Cipher brief. It is not a live entry unless MT7 emits a fresh risk-gated signal.",
        ],
        "audit": {
            "logged": False,
            "affects_scoring": False,
            "affects_execution": False,
        },
    }


def _base_from_symbol(symbol: str) -> str:
    s = _canonical_usdt_symbol(symbol)
    return s.replace("_USDT", "").replace("_USDC", "").upper()


def _symbol_record(canonical: str, venue: str, market_type: str, native_symbol: str, status: str = "listed") -> dict:
    return {
        "symbol": canonical,
        "base": _base_from_symbol(canonical),
        "venue": venue,
        "market_type": market_type,
        "native_symbol": native_symbol,
        "status": status,
    }


def _fetch_mexc_listed_symbols() -> tuple[list[dict], str | None]:
    try:
        resp = requests.get(f"{MEXC_BASE}/contract/detail", timeout=15)
        data = resp.json()
        rows = data.get("data") if data.get("success") else []
        out = []
        for row in rows if isinstance(rows, list) else []:
            sym = str(row.get("symbol") or "").upper()
            if not sym:
                continue
            out.append(_symbol_record(_canonical_usdt_symbol(sym), "MEXC", "perp", sym, str(row.get("state") or "listed")))
        return out, None
    except Exception as e:
        return [], str(e)


