def _venue_symbol_directory(force: bool = False) -> dict:
    now = time.time()
    cached = _VENUE_SYMBOL_CACHE.get("data")
    if cached and not force and now - float(_VENUE_SYMBOL_CACHE.get("ts") or 0) < _VENUE_SYMBOL_TTL:
        return cached
    fetchers = {
        "mexc_perp": _fetch_mexc_listed_symbols,
        "binance_usdt_perp": _fetch_binance_futures_symbols,
        "binance_spot": _fetch_binance_spot_symbols,
        "hyperliquid_perp": _fetch_hyperliquid_symbols,
    }
    venues = {}
    symbols: dict[str, dict] = {}
    errors = {}
    for key, fn in fetchers.items():
        rows, err = fn()
        venues[key] = {"count": len(rows), "ok": err is None}
        if err:
            errors[key] = err
        for rec in rows:
            canonical_usdt = _canonical_usdt_symbol(rec["symbol"])
            item = symbols.setdefault(canonical_usdt, {
                "symbol": canonical_usdt,
                "base": _base_from_symbol(canonical_usdt),
                "venues": [],
                "market_types": [],
            })
            item["venues"].append(rec)
            item["market_types"].append(f"{rec['venue']}:{rec['market_type']}")
    for item in symbols.values():
        item["venues"].sort(key=lambda x: (x["venue"], x["market_type"]))
        item["market_types"] = sorted(set(item["market_types"]))
        item["venue_count"] = len(item["venues"])
    data = {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "ttl_seconds": _VENUE_SYMBOL_TTL,
        "summary": {
            "symbols": len(symbols),
            "venues": venues,
            "errors": errors,
        },
        "symbols": symbols,
    }
    _VENUE_SYMBOL_CACHE["ts"] = now
    _VENUE_SYMBOL_CACHE["data"] = data
    return data


def _venue_symbol_lookup(symbol: str) -> dict:
    directory = _venue_symbol_directory()
    canonical = _canonical_usdt_symbol(symbol)
    base = _base_from_symbol(canonical)
    venues = []
    seen = set()
    for key in (canonical, f"{base}_USDT", f"{base}_USDC"):
        item = directory.get("symbols", {}).get(key)
        if not item:
            continue
        for venue in item.get("venues", []) or []:
            sig = (venue.get("venue"), venue.get("market_type"), venue.get("native_symbol"))
            if sig in seen:
                continue
            seen.add(sig)
            venues.append(venue)
    venues.sort(key=lambda x: (str(x.get("venue") or ""), str(x.get("market_type") or ""), str(x.get("native_symbol") or "")))
    venue_keys = {f"{v.get('venue')}:{v.get('market_type')}" for v in venues}
    return {
        "success": True,
        "symbol": canonical,
        "base": base,
        "listed": bool(venues),
        "venues": venues,
        "availability": {
            "mexc_perp": "MEXC:perp" in venue_keys,
            "binance_usdt_perp": "BINANCE:usdt_perp" in venue_keys,
            "binance_spot": "BINANCE:spot" in venue_keys,
            "hyperliquid_perp": "HYPERLIQUID:perp" in venue_keys,
        },
        "directory_summary": directory.get("summary"),
    }


@app.route("/api/chart/<exchange>/<symbol>")
def api_chart(exchange: str, symbol: str):
    """Return normalized OHLCV candles for the in-app MT7 chart."""
    try:
        exchange_key = (exchange or "mexc").strip().upper()
        symbol_key = (symbol or "").strip().upper()
        interval = request.args.get("interval", "15m").strip().lower()
        limit = _chart_limit(request.args.get("limit"))

        if interval not in _CHART_INTERVALS:
            return jsonify({
                "success": False,
                "error": f"Unsupported interval {interval!r}",
                "supported_intervals": list(_CHART_INTERVALS.keys()),
            }), 400

        if exchange_key == "MEXC":
            candles = _mexc_chart_candles(symbol_key, interval, limit)
        elif exchange_key == "HYPERLIQUID":
            candles = _hyperliquid_chart_candles(symbol_key, interval, limit)
        elif exchange_key == "BYBIT":
            candles = fetch_bybit_candles(bybit_symbol_to_raw(symbol_key), interval, limit)
        elif exchange_key == "BINANCE":
            candles, unavailable_reason = _binance_chart_candles_with_reason(symbol_key, interval, limit)
        else:
            return jsonify({"success": False, "error": f"Unsupported exchange {exchange_key!r}"}), 400

        if not candles:
            return jsonify({
                "success": False,
                "error": unavailable_reason if exchange_key == "BINANCE" and unavailable_reason else f"No chart candles returned for {symbol_key} on {exchange_key}",
            }), 404

        return jsonify({
            "success": True,
            "exchange": exchange_key,
            "symbol": symbol_key,
            "interval": interval,
            "candles": candles,
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


