@app.route("/api/risk-gates/symbol-override", methods=["POST"])
def api_symbol_override_add():
    """
    Body: {symbol, action, reason}
    action: "exempt" | "force_mild" | "force_moderate" | "force_severe" | "blocked"
    """
    try:
        body = request.get_json(force=True) or {}
        symbol = (body.get('symbol') or '').strip().upper()
        action = body.get('action', '')
        reason = body.get('reason', '')
        valid_actions = {'exempt', 'force_mild', 'force_moderate', 'force_severe', 'blocked'}
        if not symbol or action not in valid_actions:
            return jsonify({'success': False, 'error': 'symbol and valid action required'}), 400
        raw = _load_risk_gates_raw()
        overrides = raw.get('symbol_overrides', {})
        if not isinstance(overrides, dict):
            overrides = {}
        overrides[symbol] = {'action': action, 'reason': reason or 'manual'}
        raw['symbol_overrides'] = overrides
        _save_risk_gates_raw(raw)
        return jsonify({'success': True, 'symbol': symbol, 'action': action})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route("/api/risk-gates/symbol-override/<symbol>", methods=["DELETE"])
def api_symbol_override_remove(symbol):
    """Removes a symbol from symbol_overrides in risk_gates.json."""
    try:
        symbol = symbol.strip().upper()
        raw = _load_risk_gates_raw()
        overrides = raw.get('symbol_overrides', {})
        if not isinstance(overrides, dict):
            overrides = {}
        if symbol not in overrides:
            return jsonify({'success': False, 'error': f'{symbol} not in overrides'}), 404
        del overrides[symbol]
        raw['symbol_overrides'] = overrides
        _save_risk_gates_raw(raw)
        return jsonify({'success': True, 'removed': symbol})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


def _symbol_hazard_register(limit: int = 30) -> dict:
    """Rank symbols that deserve extra skepticism before any live scale-up."""
    limit = max(5, min(int(limit or 30), 75))
    raw = _load_risk_gates_raw()
    overrides = raw.get('symbol_overrides', {})
    if not isinstance(overrides, dict):
        overrides = {}
    cfg = _symbol_loss_gate_config(raw)
    recent_live = _compute_symbol_loss_stats(
        min_trades=1,
        lookback_days=cfg["lookback_days"],
    )

    live_rows: dict[str, dict] = {}
    paper_rows: dict[str, dict] = {}
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        live_rows = {
            r["symbol"]: dict(r)
            for r in con.execute("""
                SELECT symbol,
                       COUNT(*) AS trade_count,
                       ROUND(SUM(pnl_pct), 4) AS sum_pnl,
                       ROUND(AVG(pnl_pct), 4) AS avg_pnl,
                       ROUND(MIN(pnl_pct), 4) AS worst_pnl,
                       MAX(result_at) AS last_seen
                FROM signals
                WHERE result IS NOT NULL
                  AND pnl_pct IS NOT NULL
                  AND result NOT IN ('EXPIRED', 'SKIPPED')
                  AND COALESCE(source, 'live') != 'paper'
                GROUP BY symbol
            """).fetchall()
        }
        paper_rows = {
            r["symbol"]: dict(r)
            for r in con.execute("""
                SELECT symbol,
                       COUNT(*) AS trade_count,
                       ROUND(SUM(pnl_pct), 4) AS sum_pnl,
                       ROUND(AVG(pnl_pct), 4) AS avg_pnl,
                       ROUND(MIN(pnl_pct), 4) AS worst_pnl,
                       MAX(closed_at) AS last_seen
                FROM paper_trades
                WHERE status='closed'
                  AND pnl_pct IS NOT NULL
                GROUP BY symbol
            """).fetchall()
        }
        con.close()
    except Exception as e:
        print(f"[symbol_hazard_register] {e}", file=sys.stderr)

    symbols = sorted(set(live_rows) | set(paper_rows) | set(recent_live) | set(overrides))
    hazards = []
    for sym in symbols:
        live = live_rows.get(sym, {})
        paper = paper_rows.get(sym, {})
        recent = recent_live.get(sym, {})
        override = overrides.get(sym, {}) if isinstance(overrides.get(sym, {}), dict) else {}
        live_sum = float(live.get("sum_pnl") or 0)
        paper_sum = float(paper.get("sum_pnl") or 0)
        live_worst = float(live.get("worst_pnl") or 0)
        paper_worst = float(paper.get("worst_pnl") or 0)
        recent_sum = float(recent.get("sum_pnl") or 0)
        live_n = int(live.get("trade_count") or 0)
        paper_n = int(paper.get("trade_count") or 0)
        active_action = override.get("action")

        hazard_score = 0.0
        hazard_score += max(0.0, -live_sum) * 1.4
        hazard_score += max(0.0, -paper_sum) * 0.8
        hazard_score += max(0.0, -recent_sum) * 1.8
        hazard_score += max(0.0, -min(live_worst, paper_worst)) * 0.6
        if live_n >= cfg["min_trades"] and recent_sum < cfg["threshold"]:
            hazard_score += 35
        if active_action == "blocked":
            hazard_score += 30
        elif active_action:
            hazard_score += 8

        if active_action == "blocked":
            recommendation = "blocked"
            reason = "Active symbol override is blocking this market."
        elif live_n >= cfg["min_trades"] and recent_sum < cfg["threshold"]:
            recommendation = "block_candidate"
            reason = f"Recent live P&L breaches the {cfg['lookback_days']}d symbol loss gate."
        elif live_sum <= -40 or paper_sum <= -60 or min(live_worst, paper_worst) <= -45:
            recommendation = "reduce_size"
            reason = "Historical outcomes show repeat or severe symbol-specific damage."
        elif hazard_score >= 20:
            recommendation = "watch"
            reason = "Mixed losses are not enough to block, but deserve manual review."
        else:
            recommendation = "ok"
            reason = "No current hazard threshold is breached."

        hazards.append({
            "symbol": sym,
            "hazard_score": round(hazard_score, 2),
            "recommendation": recommendation,
            "reason": reason,
            "live": {
                "trade_count": live_n,
                "sum_pnl": round(live_sum, 2),
                "avg_pnl": live.get("avg_pnl"),
                "worst_pnl": live.get("worst_pnl"),
                "last_seen": live.get("last_seen"),
                "recent_sum_pnl": round(recent_sum, 2),
                "recent_trade_count": int(recent.get("trade_count") or 0),
            },
            "paper": {
                "trade_count": paper_n,
                "sum_pnl": round(paper_sum, 2),
                "avg_pnl": paper.get("avg_pnl"),
                "worst_pnl": paper.get("worst_pnl"),
                "last_seen": paper.get("last_seen"),
            },
            "override": override or None,
        })

    hazards.sort(key=lambda h: (h["recommendation"] != "ok", h["hazard_score"]), reverse=True)
    return {
        "generated_at": datetime.utcnow().isoformat(),
        "threshold": cfg["threshold"],
        "min_trades": cfg["min_trades"],
        "lookback_days": cfg["lookback_days"],
        "summary": {
            "symbols": len(hazards),
            "blocked": sum(1 for h in hazards if h["recommendation"] == "blocked"),
            "block_candidates": sum(1 for h in hazards if h["recommendation"] == "block_candidate"),
            "reduce_size": sum(1 for h in hazards if h["recommendation"] == "reduce_size"),
            "watch": sum(1 for h in hazards if h["recommendation"] == "watch"),
        },
        "symbols": hazards[:limit],
    }


@app.route("/api/risk-gates/symbol-loss-stats", methods=["GET"])
def api_symbol_loss_stats():
    """Per-symbol cumulative P&L stats plus current auto-block status."""
    try:
        raw = _load_risk_gates_raw()
        cfg = _symbol_loss_gate_config(raw)
        threshold = cfg["threshold"]
        stats = _compute_symbol_loss_stats(
            min_trades=cfg["min_trades"],
            lookback_days=cfg["lookback_days"],
        )
        overrides = raw.get('symbol_overrides', {})
        if not isinstance(overrides, dict):
            overrides = {}
        unblocks = raw.get('symbol_loss_gate_unblocks', {})
        if not isinstance(unblocks, dict):
            unblocks = {}
        now = datetime.utcnow()
        result = []
        for sym, s in sorted(stats.items(), key=lambda x: x[1]['sum_pnl']):
            override = overrides.get(sym, {})
            auto_blocked = (override.get('action') == 'blocked'
                            and override.get('reason') == 'auto_loss_gate')
            manual_unblocked = _active_symbol_loss_unblock(unblocks.get(sym, {}), now)
            result.append({
                'symbol': sym,
                'sum_pnl': s['sum_pnl'],
                'avg_pnl': s['avg_pnl'],
                'worst_pnl': s['worst_pnl'],
                'trade_count': s['trade_count'],
                'auto_blocked': auto_blocked,
                'manual_unblocked': manual_unblocked,
                'at_risk': s['sum_pnl'] < threshold and not auto_blocked and not manual_unblocked,
                'blocked_at': override.get('blocked_at') if auto_blocked else None,
                'unblock_expires_at': unblocks.get(sym, {}).get('expires_at') if manual_unblocked else None,
            })
        return jsonify({
            'success': True,
            'threshold': threshold,
            'min_trades': cfg["min_trades"],
            'lookback_days': cfg["lookback_days"],
            'unblock_cooldown_hours': cfg["unblock_cooldown_hours"],
            'symbols': result,
            'blocked_count': sum(1 for r in result if r['auto_blocked']),
            'at_risk_count': sum(1 for r in result if r['at_risk']),
            'manual_unblocked_count': sum(1 for r in result if r['manual_unblocked']),
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


