def _hermes_latest_memo() -> dict | None:
    candidates = [
        os.path.join(HERMES_DIR, "latest_memo.json"),
        os.path.join(HERMES_DIR, "hermes_memo.json"),
    ]
    for path in candidates:
        data = _hermes_read_json(path, None)
        if isinstance(data, dict):
            data.setdefault("source_path", path)
            return data
    md_path = os.path.join(HERMES_DIR, "latest_memo.md")
    try:
        if os.path.exists(md_path):
            with open(md_path, encoding="utf-8") as f:
                return {
                    "generated_at": datetime.utcfromtimestamp(os.path.getmtime(md_path)).isoformat(),
                    "format": "markdown",
                    "source_path": md_path,
                    "body": f.read()[:12000],
                }
    except Exception as e:
        print(f"[hermes] latest_memo markdown: {e}", file=sys.stderr)
    return None


def _hermes_memo_archive(limit: int = 8) -> list[dict]:
    archive_dir = os.path.join(HERMES_DIR, "archive")
    if not os.path.isdir(archive_dir):
        return []
    memos: list[dict] = []
    try:
        files = [
            os.path.join(archive_dir, name)
            for name in os.listdir(archive_dir)
            if name.endswith(".json")
        ]
        for path in sorted(files, key=os.path.getmtime, reverse=True)[:limit]:
            data = _hermes_read_json(path, None)
            if not isinstance(data, dict):
                continue
            body = data.get("body") or ""
            title = "Hermes memo"
            match = re.search(r"^#\s+(.+)$", body, re.MULTILINE)
            if match:
                title = match.group(1).strip()
            memos.append({
                "archive_id": os.path.splitext(os.path.basename(path))[0],
                "generated_at": data.get("generated_at") or datetime.utcfromtimestamp(os.path.getmtime(path)).isoformat(),
                "source": data.get("source"),
                "source_path": path,
                "title": title,
                "body_preview": body[:700],
            })
    except Exception as e:
        print(f"[hermes] memo_archive: {e}", file=sys.stderr)
    return memos


def _hermes_archived_memo(archive_id: str) -> dict | None:
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", archive_id or ""):
        return None
    archive_dir = os.path.join(HERMES_DIR, "archive")
    json_path = os.path.join(archive_dir, f"{archive_id}.json")
    md_path = os.path.join(archive_dir, f"{archive_id}.md")
    data = _hermes_read_json(json_path, None)
    if isinstance(data, dict):
        body = data.get("body") or ""
        title = data.get("title") or "Hermes memo"
        match = re.search(r"^#\s+(.+)$", body, re.MULTILINE)
        if match:
            title = match.group(1).strip()
        if not body and os.path.exists(md_path):
            try:
                with open(md_path, encoding="utf-8") as f:
                    body = f.read()
            except Exception as e:
                print(f"[hermes] archived markdown {md_path}: {e}", file=sys.stderr)
        return {
            "archive_id": archive_id,
            "generated_at": data.get("generated_at") or (
                datetime.utcfromtimestamp(os.path.getmtime(json_path)).isoformat()
                if os.path.exists(json_path) else None
            ),
            "source": data.get("source"),
            "source_path": json_path,
            "title": title,
            "sections": data.get("sections") if isinstance(data.get("sections"), dict) else {},
            "body": body,
        }
    if os.path.exists(md_path):
        try:
            with open(md_path, encoding="utf-8") as f:
                body = f.read()
            title = "Hermes memo"
            match = re.search(r"^#\s+(.+)$", body, re.MULTILINE)
            if match:
                title = match.group(1).strip()
            return {
                "archive_id": archive_id,
                "generated_at": datetime.utcfromtimestamp(os.path.getmtime(md_path)).isoformat(),
                "source_path": md_path,
                "title": title,
                "sections": {},
                "body": body,
            }
        except Exception as e:
            print(f"[hermes] archived markdown {md_path}: {e}", file=sys.stderr)
    return None


def _hermes_latest_report_meta() -> dict:
    meta = {"daily": None, "weekly": None}
    try:
        if not os.path.isdir(REPORTS_DIR):
            return meta
        files = os.listdir(REPORTS_DIR)
        for kind in ("daily", "weekly"):
            prefix = f"{kind}_"
            candidates = [f for f in files if f.startswith(prefix) and f.endswith(".json")]
            if not candidates:
                continue
            candidates.sort(key=lambda f: os.path.getmtime(os.path.join(REPORTS_DIR, f)), reverse=True)
            fname = candidates[0]
            path = os.path.join(REPORTS_DIR, fname)
            data = _hermes_read_json(path, {})
            meta[kind] = {
                "file": fname,
                "modified_at": datetime.utcfromtimestamp(os.path.getmtime(path)).isoformat(),
                "generated_at": data.get("generated_at"),
                "narrative_source": data.get("narrative_source"),
                "ai_available": data.get("ai_available"),
            }
    except Exception as e:
        print(f"[hermes] latest_report_meta: {e}", file=sys.stderr)
    return meta


def _hermes_edge_lab_meta() -> dict:
    report_path = os.path.join("data", "factor_report.json")
    db_path = os.path.join("data", "edge_lab.db")
    report = _hermes_read_json(report_path, {})
    top_long = report.get("top_long_states") or []
    top_short = report.get("top_short_states") or []
    return {
        "available": bool(report),
        "report_path": report_path,
        "report_modified_at": (
            datetime.utcfromtimestamp(os.path.getmtime(report_path)).isoformat()
            if os.path.exists(report_path) else None
        ),
        "db_mb": round(os.path.getsize(db_path) / (1024 * 1024), 1) if os.path.exists(db_path) else None,
        "meta": report.get("meta") or {},
        "top_long": top_long[:3],
        "top_short": top_short[:3],
    }


def _hermes_research_queue() -> dict:
    queue_path = os.path.join(HERMES_DIR, "research_queue.json")
    data = _hermes_read_json(queue_path, {"items": []})
    items = data.get("items", []) if isinstance(data, dict) else []
    pipeline = _hermes_research_pipeline_summary()
    out = {
        "status": "manual_queue" if items else "empty",
        "items": items[:10],
        "count": len(items),
        "path": queue_path,
        "note": "Research arm is scaffolded as a review queue. External research should become shadow experiments, never direct config changes.",
    }
    out.update(pipeline)
    return out


def _research_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _research_write_json(path: str, data) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, sort_keys=True, default=str)
    os.replace(tmp, path)


def _research_slug_id(*parts: str) -> str:
    import hashlib
    raw = "|".join(str(p or "") for p in parts)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:14]


def _research_norm_identity(value: str) -> str:
    return re.sub(r"\s+", " ", unicodedata.normalize("NFC", str(value or "")).strip().lower())


def _research_load_sources() -> list[dict]:
    data = _hermes_read_json(HERMES_RESEARCH_SOURCES_PATH, {"sources": []})
    if isinstance(data, dict):
        sources = data.get("sources", [])
    elif isinstance(data, list):
        sources = data
    else:
        sources = []
    return [s for s in sources if isinstance(s, dict)]


def _research_find_source(source_id: str) -> dict | None:
    """Resolve current and legacy source identifiers used by cached scholar artifacts."""
    target = _research_norm_identity(source_id)
    if not target:
        return None
    sources = _research_load_sources()
    for source in sources:
        identities = [
            source.get("id"),
            source.get("source_id"),
            source.get("url"),
            source.get("full_text_url"),
            source.get("relative_path"),
            source.get("original_filename"),
            source.get("title"),
        ]
        if target in {_research_norm_identity(value) for value in identities if value}:
            return source
    return None


def _research_save_sources(sources: list[dict]) -> None:
    _research_write_json(HERMES_RESEARCH_SOURCES_PATH, {
        "updated_at": _research_now(),
        "sources": sources,
    })


def _research_source_is_online_sync_candidate(source: dict) -> bool:
    status = str(source.get("full_text_status") or "")
    return (
        status in {"full_text", "full_text_unverified", "partial_text"}
        and float(source.get("relevance_score") or 0) >= 0.72
        and float(source.get("quality_score") or 0) >= 0.5
        and bool(str(source.get("raw_excerpt") or source.get("summary") or "").strip())
    )


def _research_public_source_payload(source: dict) -> dict:
    """Return the research knowledge MT7 needs online, without local filesystem paths."""
    allowed = [
        "id", "title", "url", "full_text_url", "original_filename", "file_ext", "file_size_bytes",
        "file_sha256", "source_type", "author", "published_at", "added_at", "updated_at",
        "discovered_at", "discovery_provider", "discovery_query", "tags", "mt7_fields_needed",
        "summary", "raw_excerpt", "full_text_status", "full_text_word_count",
        "full_text_confidence", "quality_score", "relevance_score", "status", "hypotheses",
        "text_storage_note", "online_sync_approved", "online_sync_approved_at",
        "online_sync_approved_by",
    ]
    out = {k: source.get(k) for k in allowed if k in source}
    for key in ("title", "summary", "raw_excerpt", "text_storage_note"):
        if isinstance(out.get(key), str):
            out[key] = re.sub(r"/Users/[^\s'\"),;]+", "[local_path]", out[key])
            out[key] = re.sub(r"/home/[^\s'\"),;]+", "[local_path]", out[key])
    if source.get("relative_path"):
        out["relative_path"] = source.get("relative_path")
    out["synced_from"] = "local_indexed_package"
    return out


def _research_set_online_sync_approval(source_id: str, approved: bool, note: str = "") -> dict:
    sources = _research_load_sources()
    for source in sources:
        if str(source.get("id")) == str(source_id):
            source["online_sync_approved"] = bool(approved)
            source["online_sync_approved_at"] = _research_now()
            source["online_sync_approved_by"] = "local_user"
            if note:
                source["online_sync_note"] = note[:500]
            _research_save_sources(sources)
            return source
    raise KeyError("Research source not found")


def _research_bulk_approve_online_sync(mode: str = "safe") -> dict:
    sources = _research_load_sources()
    changed = 0
    approved = 0
    for source in sources:
        should_approve = _research_source_is_online_sync_candidate(source) if mode == "safe" else True
        if should_approve:
            approved += 1
            if not source.get("online_sync_approved"):
                source["online_sync_approved"] = True
                source["online_sync_approved_at"] = _research_now()
                source["online_sync_approved_by"] = f"bulk_{mode}"
                changed += 1
    if changed:
        _research_save_sources(sources)
    return {"changed": changed, "approved_count": approved, "mode": mode}


def _research_dedupe_sources_by_id(sources: list[dict]) -> list[dict]:
    order: list[str] = []
    merged: dict[str, dict] = {}
    for source in sources:
        if not isinstance(source, dict):
            continue
        sid = str(source.get("id") or "").strip()
        if not sid:
            continue
        if sid not in merged:
            order.append(sid)
            merged[sid] = source
        else:
            merged[sid] = {**merged[sid], **source}
    return [merged[sid] for sid in order]


def _research_export_online_sync_package() -> dict:
    sources = _research_load_sources()
    approved_sources = [
        _research_public_source_payload(s)
        for s in sources
        if s.get("online_sync_approved")
    ]
    status_counts: dict[str, int] = defaultdict(int)
    for source in approved_sources:
        status_counts[str(source.get("full_text_status") or "unknown")] += 1
    package = {
        "generated_at": _research_now(),
        "artifact_type": "mt7_research_online_sync_package",
        "source_count": len(approved_sources),
        "status_counts": dict(status_counts),
        "privacy_note": "Local absolute paths and corpus roots are omitted. Package contains approved indexed excerpts/summaries, metadata, tags, and shadow hypotheses.",
        "sources": approved_sources,
    }
    _research_write_json(HERMES_RESEARCH_ONLINE_SYNC_PATH, package)
    return {
        "export_path": HERMES_RESEARCH_ONLINE_SYNC_PATH,
        "source_count": len(approved_sources),
        "status_counts": dict(status_counts),
        "generated_at": package["generated_at"],
    }


def _research_import_online_sync_package(path: str = HERMES_RESEARCH_ONLINE_SYNC_PATH) -> dict:
    package = _hermes_read_json(path, None)
    if not isinstance(package, dict) or not isinstance(package.get("sources"), list):
        raise ValueError("Approved online sync package not found or invalid.")
    existing = _research_load_sources()
    by_id = {str(s.get("id")): idx for idx, s in enumerate(existing) if s.get("id")}
    imported = 0
    updated = 0
    skipped = 0
    for source in package.get("sources") or []:
        if not isinstance(source, dict) or not source.get("id"):
            skipped += 1
            continue
        clean = dict(source)
        clean.pop("path", None)
        clean.pop("corpus_root", None)
        clean["online_synced_at"] = _research_now()
        clean["online_sync_imported"] = True
        sid = str(clean.get("id"))
        if sid in by_id:
            idx = by_id[sid]
            existing[idx] = {**existing[idx], **clean}
            updated += 1
        else:
            existing.append(clean)
            by_id[sid] = len(existing) - 1
            imported += 1
    if imported or updated:
        existing = _research_dedupe_sources_by_id(existing)
        _research_save_sources(existing)
    return {
        "imported": imported,
        "updated": updated,
        "skipped": skipped,
        "total": len(existing),
        "package_source_count": len(package.get("sources") or []),
    }


def _research_extract_tags(text: str) -> list[str]:
    low = (text or "").lower()
    vocab = {
        "funding": ["funding", "perpetual", "perp", "basis"],
        "momentum": ["momentum", "breakout", "trend following", "trend-following"],
        "mean_reversion": ["mean reversion", "reversal", "overbought", "oversold"],
        "volatility": ["volatility", "realized vol", "atr", "variance"],
        "liquidity": ["liquidity", "order book", "market depth", "spread", "slippage"],
        "order_flow": ["order flow", "footprint", "delta", "volume profile", "vwap"],
        "sentiment": ["sentiment", "social", "news", "narrative"],
        "macro": ["macro", "rates", "dollar", "liquidity cycle", "cpi", "fed"],
        "risk": ["drawdown", "risk", "position sizing", "leverage"],
        "execution": ["execution", "fill", "fees", "maker", "taker"],
    }
    tags = [tag for tag, words in vocab.items() if any(w in low for w in words)]
    return tags[:8] or ["general"]


def _research_relevance_score(title: str, text: str, tags: list[str] | None = None) -> float:
    title_low = (title or "").lower()
    low = f"{title or ''} {text or ''}".lower()
    crypto_terms = [
        "cryptocurrency", "crypto", "bitcoin", "ethereum", "btc", "eth", "altcoin",
        "digital asset", "token", "defi", "stablecoin", "perpetual", "perp",
        "funding rate", "liquidation", "mexc", "binance", "hyperliquid",
    ]
    trading_terms = [
        "trading", "trade", "market microstructure", "order book", "liquidity",
        "volatility", "momentum", "mean reversion", "arbitrage", "futures",
        "derivatives", "portfolio", "risk management", "execution", "slippage",
        "exchange", "price discovery", "alpha", "strategy", "backtest",
    ]
    crypto_hits = sum(1 for term in crypto_terms if term in low)
    trading_hits = sum(1 for term in trading_terms if term in low)
    if any(term in title_low for term in ["cryptocurrency", "crypto", "bitcoin", "ethereum", "defi", "perpetual"]):
        crypto_hits = max(crypto_hits, 1)
    if any(term in title_low for term in ["trading", "arbitrage", "high frequency", "finance", "financial", "market microstructure", "portfolio"]):
        trading_hits = max(trading_hits, 2)
    tag_hits = len([t for t in (tags or []) if t and t != "general"])
    if crypto_hits >= 2:
        return 0.88
    if crypto_hits >= 1 and trading_hits >= 1:
        return 0.84
    if trading_hits >= 4:
        return 0.72
    if trading_hits >= 2:
        return 0.58
    if tag_hits >= 3:
        return 0.42
    return 0.24


def _research_sentence_is_boilerplate(sentence: str) -> bool:
    low = re.sub(r"\s+", " ", (sentence or "").lower()).strip()
    if not low:
        return True
    boilerplate_patterns = [
        "available online", "open access article", "creative commons", "creativecommons",
        "copyright", "©", "the author(s)", "license", "issn", "isbn", "doi:",
        "corresponding author", "received:", "accepted:", "revised:", "published:",
        "all rights reserved", "journal homepage", "downloaded from", "sciencedirect",
        "springer nature", "elsevier", "mdpi", "wiley", "expert systems with applications",
        "international journal", "proceedings of", "table of contents", "references",
        "orders are submitted based on an asset", "well suited for high-volatility markets",
        "this paper is organized as follows", "the remainder of this paper",
        "in section 2", "section 2 we review", "section 3", "section 4",
    ]
    if any(p in low for p in boilerplate_patterns):
        return True
    if re.search(r"\b\d{4}\s+\d{3,6}\b", low) and len(low) < 180:
        return True
    if len(re.findall(r"https?://|www\.", low)) >= 1:
        return True
    return False


def _research_sentence_score(sentence: str, tags: list[str] | None = None) -> int:
    if _research_sentence_is_boilerplate(sentence):
        return -100
    low = sentence.lower()
    tag_terms = {
        "funding": ["funding", "basis", "perpetual", "liquidation", "crowding"],
        "liquidity": ["liquidity", "market depth", "spread", "order book", "slippage"],
        "order_flow": ["order flow", "volume", "depth", "imbalance", "vwap"],
        "momentum": ["momentum", "trend", "breakout", "continuation"],
        "mean_reversion": ["reversal", "mean reversion", "overbought", "oversold"],
        "volatility": ["volatility", "variance", "atr", "regime"],
        "risk": ["risk", "drawdown", "position sizing", "stop loss", "leverage"],
        "execution": ["execution", "fill", "fees", "maker", "taker", "transaction cost"],
        "sentiment": ["sentiment", "news", "social", "narrative"],
        "macro": ["macro", "rates", "fed", "liquidity cycle"],
    }
    general_terms = [
        "cryptocurrency", "crypto", "bitcoin", "ethereum", "digital asset", "trading",
        "market", "futures", "perpetual", "price", "return", "volatility", "liquidity",
        "strategy", "algorithm", "model", "prediction", "forecast", "portfolio",
        "risk", "result", "finding", "evidence", "performance", "profit",
    ]
    wanted = list(general_terms)
    for tag in tags or []:
        wanted.extend(tag_terms.get(str(tag), []))
    score = sum(2 for term in wanted if term and term in low)
    if any(term in low for term in ["we propose", "we find", "results show", "findings", "this paper", "this study", "our model", "our results"]):
        score += 5
    if any(term in low for term in ["abstract", "conclusion", "experimental results", "empirical"]):
        score += 2
    if len(sentence) < 55 or len(sentence) > 360:
        score -= 2
    return score


def _research_summarize_text(text: str) -> str:
    clean = re.sub(r"\s+", " ", (text or "")).strip()
    if not clean:
        return ""
    sentences = re.split(r"(?<=[.!?])\s+", clean)
    candidates = []
    for idx, sentence in enumerate(sentences[:180]):
        sentence = sentence.strip()
        if not (45 <= len(sentence) <= 360):
            continue
        score = _research_sentence_score(sentence)
        if score <= 0:
            continue
        candidates.append((score, idx, sentence))
    candidates.sort(key=lambda x: (x[0], -x[1]), reverse=True)
    picked = sorted(candidates[:4], key=lambda x: x[1])
    if picked:
        return " ".join(s for _, __, s in picked)[:1000]
    fallback = [s.strip() for s in sentences if 45 <= len(s.strip()) <= 260 and not _research_sentence_is_boilerplate(s)]
    return " ".join(fallback[:3])[:900] if fallback else clean[:700]


def _research_display_summary(source: dict) -> str:
    text = _research_source_text(source, max_chars=60000)
    summary = _research_summarize_text(text) if text else ""
    return summary or str(source.get("summary") or "").strip()


def _research_text_profile(text: str, source_type: str = "", status_hint: str | None = None) -> dict:
    clean = re.sub(r"\s+", " ", (text or "")).strip()
    words = re.findall(r"\b[\w'-]+\b", clean)
    word_count = len(words)
    source_type = str(source_type or "").lower()
    if status_hint:
        status = status_hint
    elif not clean:
        status = "metadata_only"
    elif word_count >= 1200:
        status = "full_text_unverified" if source_type in {"url", "article", "webpage"} else "full_text"
    elif word_count >= 300:
        status = "partial_text"
    elif word_count >= 120:
        status = "abstract_only"
    else:
        status = "metadata_only"
    confidence = {
        "full_text": 0.95,
        "full_text_unverified": 0.72,
        "partial_text": 0.55,
        "abstract_only": 0.38,
        "metadata_only": 0.12,
        "low_quality_extract": 0.28,
        "scanned_needs_ocr": 0.08,
    }.get(status, 0.2)
    return {
        "full_text_status": status,
        "full_text_word_count": word_count,
        "full_text_confidence": confidence,
    }


def _research_fetch_readable_web_text(url: str, timeout: int = 10) -> str:
    if not url:
        return ""
    try:
        resp = requests.get(url, timeout=timeout, headers={"User-Agent": "MatrixTrader7-HermesResearch/1.0"})
        resp.raise_for_status()
        text = resp.text or ""
        text = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>|<nav[\s\S]*?</nav>|<footer[\s\S]*?</footer>", " ", text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        return text[:24000]
    except Exception:
        return ""


def _research_arxiv_html_url(arxiv_id_url: str) -> str:
    raw = str(arxiv_id_url or "").rstrip("/")
    arxiv_id = raw.split("/")[-1]
    return f"https://ar5iv.labs.arxiv.org/html/{arxiv_id}" if arxiv_id else ""


def _research_extract_pdf_text(path: str, max_pages: int = 90) -> tuple[str, dict]:
    meta = {
        "parser_available": False,
        "parser": None,
        "page_count": 0,
        "pages_extracted": 0,
        "error": None,
    }
    reader_cls = None
    try:
        from pypdf import PdfReader  # type: ignore
        reader_cls = PdfReader
        meta["parser"] = "pypdf"
    except Exception:
        try:
            from PyPDF2 import PdfReader  # type: ignore
            reader_cls = PdfReader
            meta["parser"] = "PyPDF2"
        except Exception:
            meta["error"] = "Install pypdf to extract local PDF text."
            return "", meta
    try:
        meta["parser_available"] = True
        reader = reader_cls(path)
        pages = getattr(reader, "pages", []) or []
        meta["page_count"] = len(pages)
        chunks = []
        for page in pages[:max_pages]:
            try:
                chunk = page.extract_text() or ""
            except Exception:
                chunk = ""
            chunk = re.sub(r"[ \t]+", " ", chunk).strip()
            if chunk:
                chunks.append(chunk)
            meta["pages_extracted"] += 1
        text = "\n\n".join(chunks)
        text = re.sub(r"\n{3,}", "\n\n", text).strip()
        return text[:60000], meta
    except Exception as exc:
        meta["error"] = str(exc)
        return "", meta


def _research_pdf_extract_worker(path: str, max_pages: int, queue) -> None:
    try:
        queue.put(_research_extract_pdf_text(path, max_pages=max_pages))
    except BaseException as exc:
        queue.put(("", {
            "parser_available": False,
            "parser": "pypdf",
            "page_count": 0,
            "pages_extracted": 0,
            "error": str(exc),
        }))


def _research_extract_pdf_text_bounded(path: str, max_pages: int | None = None, timeout_sec: int | None = None) -> tuple[str, dict]:
    max_pages = int(max_pages or HERMES_RESEARCH_PDF_MAX_PAGES)
    timeout_sec = int(timeout_sec if timeout_sec is not None else HERMES_RESEARCH_PDF_TIMEOUT_SEC)
    if timeout_sec <= 0:
        return _research_extract_pdf_text(path, max_pages=max_pages)
    try:
        method = "fork" if "fork" in mp.get_all_start_methods() else mp.get_start_method()
        ctx = mp.get_context(method)
        queue = ctx.Queue(maxsize=1)
        proc = ctx.Process(target=_research_pdf_extract_worker, args=(path, max_pages, queue))
        proc.daemon = True
        proc.start()
        proc.join(timeout_sec)
        if proc.is_alive():
            proc.terminate()
            proc.join(2)
            return "", {
                "parser_available": True,
                "parser": "pypdf",
                "page_count": 0,
                "pages_extracted": 0,
                "error": f"PDF extraction timed out after {timeout_sec}s; index this file with OCR or a smaller page limit.",
                "timed_out": True,
            }
        if not queue.empty():
            text, meta = queue.get()
            meta = dict(meta or {})
            meta["bounded_timeout_sec"] = timeout_sec
            meta["bounded_max_pages"] = max_pages
            return text, meta
        return "", {
            "parser_available": True,
            "parser": "pypdf",
            "page_count": 0,
            "pages_extracted": 0,
            "error": "PDF extraction worker exited without returning text.",
        }
    except Exception as exc:
        text, meta = _research_extract_pdf_text(path, max_pages=max_pages)
        meta = dict(meta or {})
        meta["bounded_error"] = str(exc)
        return text, meta


def _research_corpus_roots() -> list[str]:
    roots = []
    for raw in HERMES_RESEARCH_CORPUS_DIRS:
        path = os.path.abspath(os.path.expanduser(raw))
        if os.path.isdir(path) and path not in roots:
            roots.append(path)
    return roots


def _research_file_sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def _research_normalize_extracted_text(text: str, max_chars: int = 60000) -> str:
    text = html_lib.unescape(text or "")
    text = re.sub(r"\r", "\n", text)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()[:max_chars]


def _research_extract_epub_text(path: str, max_chars: int = 60000) -> tuple[str, dict]:
    meta = {
        "parser_available": True,
        "parser": "zipfile_epub",
        "file_count": 0,
        "files_extracted": 0,
        "error": None,
    }
    try:
        chunks = []
        with zipfile.ZipFile(path) as zf:
            names = [
                n for n in zf.namelist()
                if n.lower().endswith((".xhtml", ".html", ".htm"))
                and "__macosx" not in n.lower()
            ]
            meta["file_count"] = len(names)
            for name in names[:120]:
                try:
                    raw = zf.read(name)
                    html_text = raw.decode("utf-8", errors="ignore")
                except Exception:
                    continue
                html_text = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", html_text, flags=re.I)
                html_text = re.sub(r"<[^>]+>", " ", html_text)
                text = _research_normalize_extracted_text(html_text, max_chars=max_chars)
                if text:
                    chunks.append(text)
                meta["files_extracted"] += 1
                if sum(len(c) for c in chunks) >= max_chars:
                    break
        return _research_normalize_extracted_text("\n\n".join(chunks), max_chars=max_chars), meta
    except Exception as exc:
        meta["error"] = str(exc)
        return "", meta


def _research_extract_plain_text(path: str, max_chars: int = 60000) -> tuple[str, dict]:
    meta = {
        "parser_available": True,
        "parser": "plain_text",
        "error": None,
    }
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            return _research_normalize_extracted_text(f.read(max_chars + 2000), max_chars=max_chars), meta
    except Exception as exc:
        meta["error"] = str(exc)
        return "", meta


def _research_status_for_local_text(text: str, ext: str, extraction: dict) -> str | None:
    word_count = len(re.findall(r"\b[\w'-]+\b", text or ""))
    ext = ext.lower()
    if extraction.get("timed_out"):
        return "low_quality_extract"
    if ext == ".pdf":
        page_count = int(extraction.get("page_count") or 0)
        if word_count < 120 and extraction.get("parser_available") and page_count:
            return "scanned_needs_ocr"
        if word_count < 300 and page_count >= 5:
            return "low_quality_extract"
        if page_count and int(extraction.get("pages_extracted") or 0) < page_count:
            return "partial_text"
    if ext == ".epub" and word_count < 300 and int(extraction.get("file_count") or 0) > 5:
        return "low_quality_extract"
    return None


def _research_source_type_for_ext(ext: str) -> str:
    ext = ext.lower()
    if ext == ".pdf":
        return "local_pdf"
    if ext == ".epub":
        return "local_epub"
    if ext == ".md":
        return "local_markdown"
    return "local_text"


def _research_local_file_to_source(path: str, root: str) -> dict | None:
    ext = os.path.splitext(path)[1].lower()
    source_type = _research_source_type_for_ext(ext)
    try:
        stat = os.stat(path)
        sha = _research_file_sha256(path)
    except Exception:
        return None

    if ext == ".pdf":
        text, extraction = _research_extract_pdf_text_bounded(path)
    elif ext == ".epub":
        text, extraction = _research_extract_epub_text(path)
    else:
        text, extraction = _research_extract_plain_text(path)

    rel_to_root = os.path.relpath(path, root)
    try:
        rel_to_project = os.path.relpath(path, os.getcwd())
        stable_seed = rel_to_project if not rel_to_project.startswith("..") else f"{os.path.basename(path)}_{sha[:12]}"
    except Exception:
        stable_seed = f"{os.path.basename(path)}_{sha[:12]}"
    title = os.path.splitext(os.path.basename(path))[0].replace("_", " ").replace("-", " ").strip()
    status_hint = _research_status_for_local_text(text, ext, extraction)
    profile = _research_text_profile(text, source_type, status_hint)
    tags = _research_extract_tags(title + " " + text[:16000])
    confidence = float(profile.get("full_text_confidence") or 0)
    relevance = _research_relevance_score(title, text[:24000], tags)
    quality = round(min(0.96, max(0.12, confidence * 0.78 + relevance * 0.18)), 2)
    text_status = profile.get("full_text_status") or "metadata_only"
    status = "local_corpus_full_text" if text_status in {"full_text", "full_text_unverified"} else "local_corpus_partial"
    if text_status in {"metadata_only", "low_quality_extract", "scanned_needs_ocr"}:
        status = "local_corpus_needs_review"

    source = {
        "id": "local_" + _research_slug_id(stable_seed),
        "title": title[:220] or os.path.basename(path),
        "url": None,
        "full_text_url": None,
        "path": path,
        "corpus_root": root,
        "relative_path": rel_to_root,
        "original_filename": os.path.basename(path),
        "file_ext": ext.lstrip("."),
        "file_size_bytes": stat.st_size,
        "file_sha256": sha,
        "source_type": source_type,
        "author": None,
        "published_at": None,
        "added_at": _research_now(),
        "tags": tags,
        "mt7_fields_needed": [],
        "summary": _research_summarize_text(text) or "Local research document indexed, but extractable text was limited. Inspect extraction metadata before using it as evidence.",
        "raw_excerpt": text[:12000],
        **profile,
        "quality_score": quality,
        "relevance_score": relevance,
        "status": status,
        "extraction": extraction,
        "text_storage_note": "Indexed text is capped for UI display; MT7 keeps the original local path and file fingerprint for reprocessing.",
    }
    source["hypotheses"] = _research_hypotheses_from_source(source)
    return source


def _research_parse_csv_field(value) -> list[str]:
    if isinstance(value, list):
        return [str(x).strip() for x in value if str(x).strip()]
    return [x.strip() for x in str(value or "").split(",") if x.strip()]


def _research_ingest_pdf_upload(file_storage, title: str = "", tags=None, fields=None) -> dict:
    original_name = secure_filename(file_storage.filename or "")
    if not original_name:
        raise ValueError("Choose a PDF file to upload.")
    if not original_name.lower().endswith(".pdf"):
        raise ValueError("Only PDF files are supported for research uploads.")
    os.makedirs(HERMES_RESEARCH_UPLOAD_DIR, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    saved_name = f"{stamp}_{original_name}"
    saved_path = os.path.join(HERMES_RESEARCH_UPLOAD_DIR, saved_name)
    file_storage.save(saved_path)

    text, extraction = _research_extract_pdf_text(saved_path)
    provided_tags = _research_parse_csv_field(tags)
    provided_fields = _research_parse_csv_field(fields)
    doc_title = (title or "").strip() or re.sub(r"\.pdf$", "", original_name, flags=re.I).replace("_", " ").replace("-", " ").strip()
    profile = _research_text_profile(text, "uploaded_pdf") if text else _research_text_profile("", "uploaded_pdf", "metadata_only")
    status = "uploaded_pdf_extracted" if profile["full_text_status"] in {"full_text", "full_text_unverified"} else "uploaded_pdf_needs_review"
    if extraction.get("error"):
        status = "uploaded_pdf_extraction_warning"
    if profile["full_text_status"] == "metadata_only" and extraction.get("parser_available") and not extraction.get("error"):
        extraction["error"] = "No selectable text found. This may be a scanned/image PDF and will need OCR."

    source = {
        "id": "pdf_" + _research_slug_id(original_name, doc_title, str(os.path.getmtime(saved_path))),
        "title": doc_title[:220] or original_name,
        "url": None,
        "full_text_url": None,
        "path": saved_path,
        "original_filename": original_name,
        "source_type": "uploaded_pdf",
        "author": None,
        "published_at": None,
        "added_at": _research_now(),
        "tags": provided_tags or _research_extract_tags(doc_title + " " + text),
        "mt7_fields_needed": provided_fields,
        "summary": _research_summarize_text(text) or "Uploaded PDF. Text extraction was incomplete; inspect extraction metadata before using it as research evidence.",
        "raw_excerpt": text[:12000],
        **profile,
        "quality_score": 0.78 if profile["full_text_status"] == "full_text" else 0.58,
        "relevance_score": 0.74,
        "status": status,
        "extraction": extraction,
        "text_storage_note": "Indexed text is capped for UI display; the uploaded PDF file is retained locally for reprocessing.",
    }
    source["hypotheses"] = _research_hypotheses_from_source(source)
    sources = _research_load_sources()
    sources = [s for s in sources if s.get("id") != source["id"]]
    sources.insert(0, source)
    _research_save_sources(sources)
    return source


def _research_hypotheses_from_source(source: dict) -> list[dict]:
    if float(source.get("relevance_score") or 0.7) < 0.45:
        return []
    tags = set(source.get("tags") or [])
    title = source.get("title") or "Research source"
    sid = source.get("id") or _research_slug_id(title)
    source_fields = [
        str(x).strip()
        for x in (source.get("mt7_fields_needed") or [])
        if str(x).strip()
    ]
    candidates: list[dict] = []
    def add(kind: str, thesis: str, strategy: str, fields: list[str], gate: str, overfit: str):
        hid = "research_" + _research_slug_id(sid, kind, thesis)
        merged_fields = []
        for f in list(fields or []) + source_fields:
            if f and f not in merged_fields:
                merged_fields.append(f)
        candidates.append({
            "id": hid,
            "source_id": sid,
            "title": f"{title} — {kind.replace('_', ' ').title()}",
            "thesis": thesis,
            "target_strategy": strategy,
            "mt7_fields_needed": merged_fields,
            "shadow_tag": f"research_{kind}",
            "expected_edge": "Improve selectivity by filtering weak regimes or confirming tradeability before strategy promotion.",
            "gate_impact": gate,
            "overfitting_risk": overfit,
            "status": "shadow_proposed",
            "promotion_criteria": "At least 50 closed forward-tested signals with this shadow tag; positive cohort EV beats baseline and negative/absent cohort does not.",
            "rollback_condition": "Reject if the tagged cohort underperforms baseline EV or cuts trade count without improving drawdown.",
        })
    if {"order_flow", "liquidity"} & tags:
        add(
            "order_flow_confirmation",
            "Require recent tape delta, book imbalance, or volume-profile acceptance to confirm breakouts and avoid thin-liquidity traps.",
            "momentum_breakout",
            ["flow_score", "flow_delta_pct", "depth_imbalance", "profile_poc", "order_flow_vwap"],
            "Could tighten entry gates for momentum and high-volatility setups; should remain shadow until cohort data proves incremental EV.",
            "Medium: order-flow features can overfit recent microstructure and exchange-specific noise.",
        )
    if "funding" in tags:
        add(
            "funding_crowding_filter",
            "Separate funding extremes that create squeeze opportunity from crowded trend-continuation traps.",
            "funding_arb",
            ["funding_rate", "basis", "change_1h_pct", "trend_score", "agent_regime"],
            "May block some Funding Arb candidates when trend and funding crowding align against the entry.",
            "Medium-high: funding regimes shift quickly; needs rolling validation and no symbol-specific rules.",
        )
    if {"sentiment", "macro"} & tags:
        add(
            "sentiment_macro_regime",
            "Use external sentiment and macro stress as a risk regime annotation, not a direct entry signal.",
            "balanced",
            ["agent_regime", "btc_beta", "market_context", "news_sentiment"],
            "Should annotate risk-on/risk-off bias and possibly raise conviction thresholds during macro stress after validation.",
            "High: narrative data is noisy, delayed, and easy to rationalize after the fact.",
        )
    if {"volatility", "risk"} & tags:
        add(
            "volatility_stop_quality",
            "Test whether ATR stop distance and TP laddering need regime-specific treatment in high and extreme volatility.",
            "balanced",
            ["atr_pct", "vol_regime", "journey_mae_pct", "journey_mfe_pct", "stop_pressure"],
            "Could affect stop/target design, but must start as journey analytics only.",
            "Medium: stop tuning can curve-fit losses unless validated across regimes and strategies.",
        )
    if source_fields and not candidates:
        add(
            "field_mapped_prior",
            "Evaluate whether the source's mapped MT7 fields identify a repeatable shadow cohort with better EV than baseline.",
            "balanced",
            source_fields,
            "Should remain an annotation-only research cohort until forward-tested results prove it improves selectivity.",
            "Medium-high: manually mapped fields can encode hindsight unless the experiment is pre-registered and forward-tested.",
        )
    return candidates[:4]


def _research_local_metadata_candidate(path: str, root: str) -> dict:
    ext = os.path.splitext(path)[1].lower()
    title = os.path.splitext(os.path.basename(path))[0].replace("_", " ").replace("-", " ").strip()
    return {
        "id": "local_" + _research_slug_id(os.path.relpath(path, root), os.path.getmtime(path) if os.path.exists(path) else ""),
        "title": title[:220] or os.path.basename(path),
        "source_type": _research_source_type_for_ext(ext),
        "path": path,
        "corpus_root": root,
        "relative_path": os.path.relpath(path, root),
        "file_ext": ext.lstrip("."),
        "tags": _research_extract_tags(title),
        **_research_text_profile("", _research_source_type_for_ext(ext), "metadata_only"),
        "status": "local_corpus_candidate",
    }


def _research_local_corpus_candidates(limit: int = 40, extract_text: bool = True) -> list[dict]:
    out: list[dict] = []
    for root in _research_corpus_roots():
        for base, _, files in os.walk(root):
            for name in files:
                if name.startswith(".") or not name.lower().endswith((".txt", ".md", ".pdf", ".epub")):
                    continue
                path = os.path.join(base, name)
                source = _research_local_file_to_source(path, root) if extract_text else _research_local_metadata_candidate(path, root)
                if source:
                    out.append(source)
                if limit and len(out) >= limit:
                    out.sort(key=lambda x: (x.get("source_type", ""), x.get("title", "")))
                    return out[:limit]
    out.sort(key=lambda x: (x.get("source_type", ""), x.get("title", "")))
    return out[:limit] if limit else out


def _research_seed_local_corpus(limit: int = 250, force: bool = False) -> dict:
    existing = _research_load_sources()
    by_id = {str(s.get("id")): idx for idx, s in enumerate(existing) if s.get("id")}
    by_sha = {str(s.get("file_sha256")): idx for idx, s in enumerate(existing) if s.get("file_sha256")}
    added = 0
    updated = 0
    skipped = 0
    status_counts: dict[str, int] = defaultdict(int)
    roots = _research_corpus_roots()
    for item in _research_local_corpus_candidates(limit=limit):
        sid = str(item.get("id") or "")
        sha = str(item.get("file_sha256") or "")
        idx = by_sha.get(sha) if sha else None
        if idx is None:
            idx = by_id.get(sid)
        item_words = int(item.get("full_text_word_count") or 0)
        if idx is not None:
            current = existing[idx] if 0 <= idx < len(existing) else {}
            current_words = int(current.get("full_text_word_count") or 0)
            current_status = str(current.get("full_text_status") or "")
            should_update = force or item_words > current_words or current_status in {"", "metadata_only", "abstract_only", "low_quality_extract"}
            if should_update:
                merged = {**current, **item, "added_at": current.get("added_at") or item.get("added_at"), "updated_at": _research_now()}
                merged["hypotheses"] = _research_hypotheses_from_source(merged)
                existing[idx] = merged
                updated += 1
            else:
                skipped += 1
        else:
            existing.append(item)
            idx = len(existing) - 1
            by_id[sid] = idx
            if sha:
                by_sha[sha] = idx
            added += 1
        status_counts[str(item.get("full_text_status") or "unknown")] += 1
    if added or updated:
        existing.sort(key=lambda x: str(x.get("added_at") or ""), reverse=True)
        _research_save_sources(existing)
    return {
        "added": added,
        "updated": updated,
        "skipped": skipped,
        "total": len(existing),
        "roots": roots,
        "status_counts": dict(status_counts),
    }


