def _research_source_exists(sources: list[dict], candidate: dict) -> bool:
    url = str(candidate.get("url") or "").strip().lower()
    title = str(candidate.get("title") or "").strip().lower()
    cid = candidate.get("id")
    for source in sources:
        if cid and source.get("id") == cid:
            return True
        if url and str(source.get("url") or "").strip().lower() == url:
            return True
        if title and str(source.get("title") or "").strip().lower() == title:
            return True
    return False


def _research_web_relevance(query: str, title: str, summary: str, tags: list[str]) -> float | None:
    text = f"{query} {title} {summary}".lower()
    source_text = f"{title} {summary}".lower()
    domain_terms = [
        "crypto", "cryptocurrency", "bitcoin", "btc", "ethereum", "digital asset",
        "perpetual", "perpetual swap", "funding rate", "liquidation", "liquidations",
        "order book", "limit order", "market depth", "market microstructure",
        "trading", "exchange", "futures market", "derivatives", "volatility",
        "momentum", "mean reversion", "overbought", "oversold",
    ]
    tag_terms = [str(t).replace("_", " ").lower() for t in tags or []]
    domain_hits = sum(1 for term in domain_terms if term in source_text)
    tag_hits = sum(1 for term in tag_terms if term and term in text)

    # Require actual source text to mention the trading/crypto domain. Query
    # terms alone do not count, which avoids generic "futures" false positives.
    if domain_hits < 2 and not any(term in source_text for term in ("crypto", "cryptocurrency", "bitcoin", "ethereum", "perpetual swap", "funding rate", "order book")):
        return None
    return round(min(0.94, 0.55 + domain_hits * 0.045 + tag_hits * 0.025), 2)


def _research_fetch_arxiv(query: str, tags: list[str], limit: int) -> list[dict]:
    url = (
        "https://export.arxiv.org/api/query"
        f"?search_query=all:{quote_plus(query)}&start=0&max_results={max(1, min(limit, 8))}"
        "&sortBy=submittedDate&sortOrder=descending"
    )
    resp = requests.get(url, timeout=8, headers={"User-Agent": "MatrixTrader7-HermesResearch/1.0"})
    resp.raise_for_status()
    root = ET.fromstring(resp.text)
    ns = {"a": "http://www.w3.org/2005/Atom"}
    out: list[dict] = []
    for entry in root.findall("a:entry", ns):
        title = re.sub(r"\s+", " ", (entry.findtext("a:title", "", ns) or "")).strip()
        summary = re.sub(r"\s+", " ", (entry.findtext("a:summary", "", ns) or "")).strip()
        link = entry.findtext("a:id", "", ns) or ""
        published = entry.findtext("a:published", "", ns) or None
        authors = [
            re.sub(r"\s+", " ", a.findtext("a:name", "", ns) or "").strip()
            for a in entry.findall("a:author", ns)
        ]
        if not title:
            continue
        relevance = _research_web_relevance(query, title, summary, tags)
        if relevance is None:
            continue
        html_url = _research_arxiv_html_url(link)
        full_text = _research_fetch_readable_web_text(html_url, timeout=5) if html_url else ""
        full_profile = _research_text_profile(full_text, "web_academic_arxiv") if full_text else _research_text_profile(summary, "web_academic_arxiv", "abstract_only")
        use_text = full_text if full_profile["full_text_status"] in {"full_text", "full_text_unverified"} else summary
        payload = {
            "id": "web_" + _research_slug_id("arxiv", link, title),
            "title": title[:180],
            "url": link,
            "full_text_url": html_url or None,
            "source_type": "web_academic_arxiv",
            "author": ", ".join([a for a in authors if a][:3]) or None,
            "published_at": published,
            "added_at": _research_now(),
            "discovered_at": _research_now(),
            "discovery_provider": "arxiv",
            "discovery_query": query,
            "discovery_reason": "",
            "tags": sorted(set((tags or []) + _research_extract_tags(title + " " + summary)))[:8],
            "summary": _research_summarize_text(use_text),
            "raw_excerpt": use_text[:12000],
            **full_profile,
            "quality_score": 0.82,
            "relevance_score": relevance,
            "status": "web_discovered",
        }
        payload["hypotheses"] = _research_hypotheses_from_source(payload)
        out.append(payload)
    return out


def _research_fetch_crossref(query: str, tags: list[str], limit: int) -> list[dict]:
    url = (
        "https://api.crossref.org/works"
        f"?query.bibliographic={quote_plus(query)}&rows={max(1, min(limit, 8))}"
        "&sort=published&order=desc"
    )
    resp = requests.get(url, timeout=8, headers={"User-Agent": "MatrixTrader7-HermesResearch/1.0 (mailto:research@example.invalid)"})
    resp.raise_for_status()
    items = (((resp.json() or {}).get("message") or {}).get("items") or [])
    out: list[dict] = []
    for item in items:
        titles = item.get("title") or []
        title = re.sub(r"\s+", " ", str(titles[0] if titles else "")).strip()
        if not title:
            continue
        abstract = re.sub(r"<[^>]+>", " ", str(item.get("abstract") or ""))
        abstract = re.sub(r"\s+", " ", abstract).strip()
        doi = item.get("DOI")
        link = item.get("URL") or (f"https://doi.org/{doi}" if doi else "")
        date_parts = (((item.get("published-print") or item.get("published-online") or item.get("issued") or {}).get("date-parts") or [[]])[0])
        published = "-".join(str(x) for x in date_parts[:3]) if date_parts else None
        authors = item.get("author") or []
        author_names = [
            " ".join(x for x in [a.get("given"), a.get("family")] if x)
            for a in authors[:3] if isinstance(a, dict)
        ]
        container = item.get("container-title", [""])[0] if item.get("container-title") else ""
        summary = abstract or f"{container or 'Crossref indexed source'}."
        relevance = _research_web_relevance(query, title, summary, tags)
        if relevance is None:
            continue
        page_text = _research_fetch_readable_web_text(link, timeout=4) if link else ""
        page_profile = _research_text_profile(page_text, "web_academic_crossref") if page_text else _research_text_profile(summary, "web_academic_crossref", "abstract_only")
        use_text = page_text if page_profile["full_text_status"] in {"full_text", "full_text_unverified"} else summary
        payload = {
            "id": "web_" + _research_slug_id("crossref", link, title),
            "title": title[:180],
            "url": link or None,
            "source_type": "web_academic_crossref",
            "author": ", ".join(author_names) or None,
            "published_at": published,
            "added_at": _research_now(),
            "discovered_at": _research_now(),
            "discovery_provider": "crossref",
            "discovery_query": query,
            "discovery_reason": "",
            "tags": sorted(set((tags or []) + _research_extract_tags(title + " " + summary)))[:8],
            "summary": _research_summarize_text(use_text),
            "raw_excerpt": use_text[:12000],
            **page_profile,
            "quality_score": 0.78,
            "relevance_score": relevance,
            "status": "web_discovered",
        }
        payload["hypotheses"] = _research_hypotheses_from_source(payload)
        out.append(payload)
    return out


def _research_discover_web_sources(payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    raw_queries = payload.get("queries")
    if isinstance(raw_queries, list) and raw_queries:
        query_specs = []
        for q in raw_queries[:8]:
            if isinstance(q, dict):
                query_specs.append({
                    "query": str(q.get("query") or "").strip(),
                    "tags": q.get("tags") if isinstance(q.get("tags"), list) else [],
                    "reason": str(q.get("reason") or "User requested Hermes external research discovery.").strip(),
                })
            else:
                query_specs.append({"query": str(q).strip(), "tags": [], "reason": "User requested Hermes external research discovery."})
        query_specs = [q for q in query_specs if q["query"]]
    else:
        query_specs = _research_default_web_queries()

    providers = payload.get("providers") if isinstance(payload.get("providers"), list) else ["arxiv", "crossref"]
    providers = [str(p).lower() for p in providers if str(p).lower() in {"arxiv", "crossref"}] or ["arxiv", "crossref"]
    per_query = max(1, min(int(payload.get("per_query") or 3), 6))
    sources = _research_load_sources()
    added_sources: list[dict] = []
    errors: list[dict] = []
    provider_stats = {
        provider: {"queries": 0, "accepted": 0, "duplicates": 0, "added": 0, "errors": 0}
        for provider in providers
    }

    for spec in query_specs:
        query = spec["query"]
        tags = [str(t).strip() for t in spec.get("tags") or [] if str(t).strip()]
        for provider in providers:
            provider_candidates: list[dict] = []
            provider_stats.setdefault(provider, {"queries": 0, "accepted": 0, "duplicates": 0, "added": 0, "errors": 0})
            provider_stats[provider]["queries"] += 1
            try:
                if provider == "arxiv":
                    provider_candidates = _research_fetch_arxiv(query, tags, per_query)
                elif provider == "crossref":
                    provider_candidates = _research_fetch_crossref(query, tags, per_query)
            except Exception as e:
                provider_stats[provider]["errors"] += 1
                errors.append({"query": query, "provider": provider, "error": str(e)[:300]})
                continue
            provider_stats[provider]["accepted"] += len(provider_candidates)
            for candidate in provider_candidates:
                candidate["discovery_reason"] = spec.get("reason") or ""
                if _research_source_exists(sources, candidate) or _research_source_exists(added_sources, candidate):
                    provider_stats[provider]["duplicates"] += 1
                    continue
                sources.insert(0, candidate)
                added_sources.append(candidate)
                provider_stats[provider]["added"] += 1

    if added_sources:
        _research_save_sources(sources)
    accepted = sum(v.get("accepted", 0) for v in provider_stats.values())
    duplicates = sum(v.get("duplicates", 0) for v in provider_stats.values())
    status_note = "Discovery completed."
    if not added_sources and errors and not accepted:
        status_note = "No sources were added because research providers timed out or returned no relevant accepted candidates."
    elif not added_sources and duplicates:
        status_note = "No new sources were added because accepted candidates were already indexed."
    elif not added_sources:
        status_note = "No sources were added because provider results did not pass MT7 relevance filters."
    return {
        "queries": query_specs,
        "providers": providers,
        "provider_stats": provider_stats,
        "accepted": accepted,
        "duplicates": duplicates,
        "added": len(added_sources),
        "added_sources": added_sources[:12],
        "errors": errors,
        "status_note": status_note,
        "total": len(sources),
    }


def _research_ingest_source(payload: dict) -> dict:
    title = str(payload.get("title") or "").strip()
    url = str(payload.get("url") or "").strip()
    text = str(payload.get("text") or payload.get("summary") or "").strip()
    source_type = str(payload.get("source_type") or ("url" if url else "note")).strip().lower()
    fetched = False
    if url and not text:
        resp = requests.get(url, timeout=8, headers={"User-Agent": "MatrixTrader7-HermesResearch/1.0"})
        resp.raise_for_status()
        text = re.sub(r"<script[\s\S]*?</script>|<style[\s\S]*?</style>", " ", resp.text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        text = re.sub(r"\s+", " ", text).strip()[:12000]
        fetched = True
    if not title:
        title = (url or text[:90] or "Untitled research note").strip()[:180]
    tags = payload.get("tags") if isinstance(payload.get("tags"), list) else _research_extract_tags(title + " " + text)
    source = {
        "id": "src_" + _research_slug_id(url, title, text[:300]),
        "title": title,
        "url": url or None,
        "source_type": source_type,
        "author": payload.get("author"),
        "published_at": payload.get("published_at"),
        "added_at": _research_now(),
        "tags": tags,
        "mt7_fields_needed": payload.get("mt7_fields_needed") if isinstance(payload.get("mt7_fields_needed"), list) else [],
        "summary": _research_summarize_text(text) or str(payload.get("summary") or "").strip(),
        "raw_excerpt": text[:3000],
        **_research_text_profile(text, source_type),
        "quality_score": float(payload.get("quality_score") or (0.7 if source_type in {"paper", "academic", "url"} else 0.55)),
        "relevance_score": float(payload.get("relevance_score") or 0.7),
        "status": "fetched" if fetched else "manual",
    }
    source["hypotheses"] = _research_hypotheses_from_source(source)
    sources = _research_load_sources()
    sources = [s for s in sources if s.get("id") != source["id"]]
    sources.insert(0, source)
    _research_save_sources(sources)
    return source


def _research_source_text(source: dict, max_chars: int = 60000) -> str:
    """Return best available text for analysis, re-reading retained local files when possible."""
    if not isinstance(source, dict):
        return ""
    path = str(source.get("path") or "")
    source_type = str(source.get("source_type") or "")
    if path and os.path.exists(path):
        if source_type in {"uploaded_pdf", "local_pdf"}:
            text, _meta = _research_extract_pdf_text_bounded(path) if source_type == "local_pdf" else _research_extract_pdf_text(path)
            if text:
                return text[:max_chars]
        if source_type == "local_epub":
            text, _meta = _research_extract_epub_text(path, max_chars=max_chars)
            if text:
                return text[:max_chars]
        if source_type in {"local_text", "local_markdown"}:
            text, _meta = _research_extract_plain_text(path, max_chars=max_chars)
            if text:
                return text[:max_chars]
    return str(source.get("raw_excerpt") or source.get("summary") or "")[:max_chars]


def _research_retrieve_context(query: str = "", tags: list[str] | None = None, limit: int = 5, min_relevance: float = 0.45) -> list[dict]:
    """Retrieve stored research snippets for analysis prompts without re-reading large local files."""
    terms = set(re.findall(r"[a-z0-9_]{4,}", (query or "").lower()))
    for tag in tags or []:
        terms.update(re.findall(r"[a-z0-9_]{4,}", str(tag).lower()))
    scored = []
    for source in _research_load_sources():
        if not isinstance(source, dict):
            continue
        relevance = float(source.get("relevance_score") or 0)
        if relevance < min_relevance:
            continue
        status = str(source.get("full_text_status") or "")
        if status in {"metadata_only", "scanned_needs_ocr"}:
            continue
        text = " ".join([
            str(source.get("title") or ""),
            str(source.get("summary") or ""),
            str(source.get("raw_excerpt") or "")[:8000],
            " ".join(str(t) for t in source.get("tags") or []),
        ]).lower()
        term_hits = sum(1 for term in terms if term in text)
        source_tags = set(str(t).lower() for t in source.get("tags") or [])
        tag_hits = len(source_tags & set(str(t).lower() for t in tags or []))
        word_score = min(1.0, int(source.get("full_text_word_count") or 0) / 9000)
        quality = float(source.get("quality_score") or 0)
        score = relevance * 2.0 + quality + word_score + min(1.5, term_hits * 0.12) + tag_hits * 0.25
        scored.append((score, source))
    scored.sort(key=lambda x: x[0], reverse=True)
    hits = []
    for score, source in scored[:limit]:
        source_tags = [str(t) for t in (source.get("tags") or []) if str(t)]
        stored_text = str(source.get("raw_excerpt") or source.get("summary") or "")
        hypotheses = source.get("hypotheses") or []
        hits.append({
            "source_id": source.get("id"),
            "title": source.get("title"),
            "source_type": source.get("source_type"),
            "full_text_status": source.get("full_text_status"),
            "word_count": source.get("full_text_word_count"),
            "relevance_score": source.get("relevance_score"),
            "quality_score": source.get("quality_score"),
            "tags": source_tags,
            "retrieval_score": round(score, 3),
            "takeaways": _research_key_sentences(stored_text, source_tags, limit=2),
            "shadow_tags": [h.get("shadow_tag") for h in hypotheses[:3] if isinstance(h, dict) and h.get("shadow_tag")],
        })
    return hits


def _cipher_review_research_hypotheses(sources: list[dict]) -> list[dict]:
    reviews: list[dict] = []
    for source in sources:
        for hyp in source.get("hypotheses") or []:
            if not isinstance(hyp, dict):
                continue
            quality = float(source.get("quality_score") or 0)
            relevance = float(source.get("relevance_score") or 0)
            score = round((quality * 0.45 + relevance * 0.35 + (0.2 if hyp.get("mt7_fields_needed") else 0)) * 100)
            verdict = "shadow_only"
            if score >= 78:
                verdict = "shadow_priority"
            elif score < 55:
                verdict = "weak_prior"
            reviews.append({
                **hyp,
                "source_title": source.get("title"),
                "source_tags": source.get("tags") or [],
                "cipher_score": score,
                "cipher_verdict": verdict,
                "cipher_notes": [
                    "Advisory only: no live scoring, sizing, or gate changes.",
                    "Prefer broad regime features over symbol-specific rules.",
                    "Promotion requires out-of-sample forward results and a rollback condition.",
                ],
            })
    reviews.sort(key=lambda x: x.get("cipher_score", 0), reverse=True)
    return reviews


def _research_evidence_type(sentence: str) -> str:
    low = (sentence or "").lower()
    if any(x in low for x in ["backtest", "simulation", "out-of-sample", "paper trading", "live trading"]):
        return "backtest_or_simulation"
    if any(x in low for x in ["we find", "results show", "evidence", "sample", "dataset", "regression", "statistically", "outperform", "performance"]):
        return "empirical"
    if any(x in low for x in ["survey", "review", "literature", "meta-analysis", "systematic"]):
        return "review"
    if any(x in low for x in ["model", "framework", "propose", "derive", "theorem", "equilibrium"]):
        return "theoretical"
    if any(x in low for x in ["i ", "my ", "experience", "journey", "roadmap", "lesson"]):
        return "anecdotal"
    return "claim"


def _research_market_scope(text: str) -> str:
    low = (text or "").lower()
    if any(x in low for x in ["perpetual", "perp", "funding rate", "liquidation", "futures contract"]):
        return "crypto_perps"
    if any(x in low for x in ["cryptocurrency", "crypto", "bitcoin", "ethereum", "digital asset", "token"]):
        return "crypto"
    if any(x in low for x in ["stock", "equity", "equities", "s&p", "nasdaq"]):
        return "equities"
    if any(x in low for x in ["forex", "currency", "fx"]):
        return "fx"
    if any(x in low for x in ["market", "trading", "liquidity", "volatility"]):
        return "general_markets"
    return "unknown"


def _research_claim_confidence(source: dict, sentence: str, evidence_type: str, market_scope: str) -> int:
    status = str(source.get("full_text_status") or "")
    score = 35
    score += {"full_text": 24, "full_text_unverified": 16, "partial_text": 10}.get(status, 0)
    score += {
        "empirical": 22,
        "backtest_or_simulation": 18,
        "review": 13,
        "theoretical": 8,
        "claim": 5,
        "anecdotal": -3,
    }.get(evidence_type, 0)
    score += {"crypto_perps": 18, "crypto": 13, "general_markets": 6, "equities": 2, "fx": 2}.get(market_scope, 0)
    if any(x in sentence.lower() for x in ["significant", "outperform", "profitable", "predict", "improve", "reduce risk"]):
        score += 5
    if any(x in sentence.lower() for x in ["might", "may", "could", "limited", "however", "but "]):
        score -= 4
    return max(0, min(100, score))


def _research_claim_stance(sentence: str) -> str:
    """Classify whether a claim supports, cautions, or contradicts a hypothesis."""
    low = (sentence or "").lower()
    contradiction_terms = [
        "fails", "failed", "poorly", "underperform", "not profitable", "no evidence",
        "does not", "cannot", "unreliable", "worse", "negative return", "loss",
        "large drawdown", "doesn't guarantee",
    ]
    caution_terms = [
        "however", "but ", "may", "might", "could", "limited", "depends",
        "risk", "overfit", "transaction cost", "slippage", "fees", "caution",
        "not guarantee", "sensitive to",
    ]
    if any(term in low for term in contradiction_terms):
        return "contradiction"
    if any(term in low for term in caution_terms):
        return "caution"
    return "support"


def _research_claim_stats(claims: list[dict]) -> dict:
    """Summarize claim quality without letting one strong quote dominate."""
    valid = [c for c in (claims or []) if isinstance(c, dict)]
    confidences = sorted(int(c.get("confidence") or 0) for c in valid)
    if not confidences:
        return {
            "count": 0,
            "best_confidence": 0,
            "median_confidence": 0,
            "avg_confidence": 0,
            "high_confidence_count": 0,
            "weak_count": 0,
            "direct_crypto_perp_count": 0,
            "crypto_claim_count": 0,
            "support_count": 0,
            "caution_count": 0,
            "contradiction_count": 0,
            "mixed_evidence": False,
            "evidence_grade": "none",
        }
    mid = len(confidences) // 2
    median = confidences[mid] if len(confidences) % 2 else round((confidences[mid - 1] + confidences[mid]) / 2)
    support_count = sum(1 for c in valid if c.get("stance") == "support")
    caution_count = sum(1 for c in valid if c.get("stance") == "caution")
    contradiction_count = sum(1 for c in valid if c.get("stance") == "contradiction")
    direct_count = sum(1 for c in valid if c.get("market_scope") == "crypto_perps")
    crypto_count = sum(1 for c in valid if c.get("market_scope") in {"crypto_perps", "crypto"})
    weak_count = sum(1 for v in confidences if v < 55)
    mixed = contradiction_count > 0 or (caution_count >= support_count and support_count > 0)
    grade = "weak"
    if median >= 78 and direct_count:
        grade = "strong_direct"
    elif median >= 70:
        grade = "strong_indirect"
    elif median >= 58:
        grade = "moderate"
    if mixed:
        grade = "mixed_" + grade
    return {
        "count": len(valid),
        "best_confidence": max(confidences),
        "median_confidence": int(median),
        "avg_confidence": round(sum(confidences) / len(confidences)),
        "high_confidence_count": sum(1 for v in confidences if v >= 75),
        "weak_count": weak_count,
        "direct_crypto_perp_count": direct_count,
        "crypto_claim_count": crypto_count,
        "support_count": support_count,
        "caution_count": caution_count,
        "contradiction_count": contradiction_count,
        "mixed_evidence": mixed,
        "evidence_grade": grade,
    }


def _research_claims_from_source(source: dict, text: str | None = None, limit: int = 4) -> list[dict]:
    """Extract conservative, structured claims from indexed text for research triage."""
    if not isinstance(source, dict):
        return []
    raw = text if text is not None else str(source.get("raw_excerpt") or source.get("summary") or "")
    clean = re.sub(r"\s+", " ", raw or "").strip()
    if not clean:
        return []
    tags = [str(t) for t in (source.get("tags") or []) if str(t)]
    sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", clean) if 55 <= len(s.strip()) <= 360]
    scored = []
    for idx, sentence in enumerate(sentences[:220]):
        score = _research_sentence_score(sentence, tags)
        evidence_type = _research_evidence_type(sentence)
        if evidence_type in {"empirical", "backtest_or_simulation", "review"}:
            score += 10
        if score <= 0:
            continue
        market_scope = _research_market_scope(sentence + " " + str(source.get("title") or ""))
        confidence = _research_claim_confidence(source, sentence, evidence_type, market_scope)
        scored.append((score + confidence * 0.15, -idx, sentence, evidence_type, market_scope, confidence))
    scored.sort(reverse=True)
    claims = []
    seen = set()
    for _, __, sentence, evidence_type, market_scope, confidence in scored:
        key = sentence.lower()[:140]
        if key in seen:
            continue
        seen.add(key)
        applicability = "direct" if market_scope == "crypto_perps" else "moderate" if market_scope == "crypto" else "indirect"
        caveat = "Requires MT7 forward validation before scoring/gate impact."
        if evidence_type in {"anecdotal", "claim"}:
            caveat = "Low evidence type; use as ideation only."
        elif market_scope not in {"crypto_perps", "crypto"}:
            caveat = "Market scope is not crypto-perp specific; translate cautiously."
        claims.append({
            "claim": sentence[:420],
            "evidence_type": evidence_type,
            "market_scope": market_scope,
            "mt7_applicability": applicability,
            "confidence": confidence,
            "stance": _research_claim_stance(sentence),
            "caveat": caveat,
        })
        if len(claims) >= limit:
            break
    return claims


def _research_priority_queue(reviews: list[dict], ledger: list[dict] | None = None, sources: list[dict] | None = None) -> list[dict]:
    """Rank research hypotheses by testability and likely MT7 usefulness.

    Research ideas must stay advisory. This queue only tells us what deserves a
    shadow experiment first; it never changes signal scoring, gates, or sizing.
    """
    ledger = ledger or []
    registered_tags = {
        str(x.get("shadow_tag") or "")
        for x in ledger
        if isinstance(x, dict) and x.get("source") in {"hermes_research_pipeline", "hermes_research_strategy_candidate"}
    }
    known_fields = {
        "agent_regime", "atr_pct", "basis", "change_1h_pct", "depth_imbalance",
        "flow_delta_pct", "flow_score", "funding_rate", "journey_mae_pct",
        "journey_mfe_pct", "order_flow_vwap", "profile_poc", "stop_pressure",
        "trend_score", "vol_regime",
    }
    partial_fields = {"btc_beta", "market_context"}
    experimental_fields = {"news_sentiment"}
    source_by_id = {str(s.get("id") or ""): s for s in (sources or []) if isinstance(s, dict)}
    claims_by_source = {
        sid: _research_claims_from_source(source, limit=3)
        for sid, source in source_by_id.items()
        if sid
    }

    queue_by_concept: dict[tuple[str, str, str], dict] = {}
    for hyp in reviews:
        fields = [str(x) for x in (hyp.get("mt7_fields_needed") or []) if str(x)]
        available = [f for f in fields if f in known_fields]
        partial = [f for f in fields if f in partial_fields]
        missing = [f for f in fields if f not in known_fields and f not in partial_fields]
        testability = 100
        if fields:
            testability = round((len(available) + len(partial) * 0.5) / len(fields) * 100)
        if any(f in experimental_fields for f in fields):
            testability = min(testability, 55)

        risk = str(hyp.get("overfitting_risk") or "").lower()
        risk_penalty = 18 if "high" in risk else 10 if "medium-high" in risk else 5 if "medium" in risk else 0
        registered = str(hyp.get("shadow_tag") or "") in registered_tags
        registered_bonus = 4 if registered else 0
        source_claims = claims_by_source.get(str(hyp.get("source_id") or ""), [])
        evidence_stats = _research_claim_stats(source_claims)
        evidence_quality = int(evidence_stats.get("median_confidence") or 0)
        evidence_bonus = min(8, round(evidence_quality / 16)) if evidence_quality else 0
        if evidence_stats.get("direct_crypto_perp_count"):
            evidence_bonus += 1
        if evidence_stats.get("mixed_evidence"):
            evidence_bonus -= 2
        priority_score = round(
            float(hyp.get("cipher_score") or 0) * 0.62
            + testability * 0.28
            + registered_bonus
            + evidence_bonus
            - risk_penalty
        )

        blockers = []
        if missing:
            blockers.append("missing_fields: " + ", ".join(missing[:4]))
        if "high" in risk:
            blockers.append("high_overfit_risk")
        if not fields:
            blockers.append("no_mt7_field_map")
        next_action = "Run as shadow tag only"
        if registered:
            next_action = "Monitor registered shadow experiment"
        elif testability >= 75 and priority_score >= 70:
            next_action = "Register in next Hermes memo"
        elif missing:
            next_action = "Map missing data before experiment"
        elif priority_score < 55:
            next_action = "Keep as weak prior"

        item = {
            "id": hyp.get("id"),
            "shadow_tag": hyp.get("shadow_tag"),
            "source_title": hyp.get("source_title"),
            "source_ids": [str(hyp.get("source_id"))] if hyp.get("source_id") else [],
            "evidence_sources": [hyp.get("source_title")] if hyp.get("source_title") else [],
            "evidence_count": 1,
            "evidence_quality_score": evidence_quality,
            "evidence_best_score": int(evidence_stats.get("best_confidence") or 0),
            "evidence_median_score": int(evidence_stats.get("median_confidence") or 0),
            "evidence_avg_score": int(evidence_stats.get("avg_confidence") or 0),
            "evidence_stats": evidence_stats,
            "evidence_claims_all": source_claims,
            "evidence_claims": sorted(source_claims, key=lambda c: int(c.get("confidence") or 0), reverse=True)[:2],
            "evidence_types": sorted({c.get("evidence_type") for c in source_claims if c.get("evidence_type")}),
            "market_scopes": sorted({c.get("market_scope") for c in source_claims if c.get("market_scope")}),
            "direct_crypto_perp_claims": int(evidence_stats.get("direct_crypto_perp_count") or 0),
            "support_claims": int(evidence_stats.get("support_count") or 0),
            "caution_claims": int(evidence_stats.get("caution_count") or 0),
            "contradiction_claims": int(evidence_stats.get("contradiction_count") or 0),
            "mixed_evidence": bool(evidence_stats.get("mixed_evidence")),
            "evidence_grade": evidence_stats.get("evidence_grade"),
            "target_strategy": hyp.get("target_strategy"),
            "thesis": hyp.get("thesis"),
            "expected_edge": hyp.get("expected_edge"),
            "priority_score": max(0, min(100, priority_score)),
            "testability_score": testability,
            "cipher_score": hyp.get("cipher_score"),
            "cipher_verdict": hyp.get("cipher_verdict"),
            "registered": registered,
            "available_fields": available,
            "partial_fields": partial,
            "missing_fields": missing,
            "blockers": blockers,
            "next_action": next_action,
            "promotion_criteria": hyp.get("promotion_criteria"),
            "rollback_condition": hyp.get("rollback_condition"),
            "overfitting_risk": hyp.get("overfitting_risk"),
            "gate_impact": hyp.get("gate_impact"),
        }
        concept_key = (
            str(item.get("shadow_tag") or ""),
            str(item.get("target_strategy") or ""),
            str(item.get("thesis") or ""),
        )
        existing = queue_by_concept.get(concept_key)
        if not existing:
            queue_by_concept[concept_key] = item
            continue
        sources = existing.setdefault("evidence_sources", [])
        for title in item.get("evidence_sources") or []:
            if title and title not in sources:
                sources.append(title)
        source_ids = existing.setdefault("source_ids", [])
        for source_id in item.get("source_ids") or []:
            if source_id and source_id not in source_ids:
                source_ids.append(source_id)
        existing["evidence_count"] = len(sources)
        existing["priority_score"] = max(int(existing.get("priority_score") or 0), int(item.get("priority_score") or 0))
        existing["testability_score"] = max(int(existing.get("testability_score") or 0), int(item.get("testability_score") or 0))
        existing["cipher_score"] = max(int(existing.get("cipher_score") or 0), int(item.get("cipher_score") or 0))
        evidence_claims_all = list(existing.get("evidence_claims_all") or [])
        for claim in item.get("evidence_claims_all") or []:
            if claim and claim not in evidence_claims_all:
                evidence_claims_all.append(claim)
        evidence_stats = _research_claim_stats(evidence_claims_all)
        existing["evidence_claims_all"] = evidence_claims_all
        existing["evidence_claims"] = sorted(evidence_claims_all, key=lambda c: int(c.get("confidence") or 0), reverse=True)[:4]
        existing["evidence_stats"] = evidence_stats
        existing["evidence_quality_score"] = int(evidence_stats.get("median_confidence") or 0)
        existing["evidence_best_score"] = int(evidence_stats.get("best_confidence") or 0)
        existing["evidence_median_score"] = int(evidence_stats.get("median_confidence") or 0)
        existing["evidence_avg_score"] = int(evidence_stats.get("avg_confidence") or 0)
        existing["direct_crypto_perp_claims"] = int(evidence_stats.get("direct_crypto_perp_count") or 0)
        existing["support_claims"] = int(evidence_stats.get("support_count") or 0)
        existing["caution_claims"] = int(evidence_stats.get("caution_count") or 0)
        existing["contradiction_claims"] = int(evidence_stats.get("contradiction_count") or 0)
        existing["mixed_evidence"] = bool(evidence_stats.get("mixed_evidence"))
        existing["evidence_grade"] = evidence_stats.get("evidence_grade")
        for field_key in ("available_fields", "partial_fields", "missing_fields", "blockers"):
            merged = list(existing.get(field_key) or [])
            for value in item.get(field_key) or []:
                if value not in merged:
                    merged.append(value)
            existing[field_key] = merged
        for field_key in ("evidence_types", "market_scopes"):
            merged = list(existing.get(field_key) or [])
            for value in item.get(field_key) or []:
                if value not in merged:
                    merged.append(value)
            existing[field_key] = merged
        if not existing.get("registered") and item.get("registered"):
            existing["registered"] = True
            existing["next_action"] = item.get("next_action")
    queue = list(queue_by_concept.values())
    for item in queue:
        item.pop("evidence_claims_all", None)
    queue.sort(key=lambda x: (x.get("priority_score") or 0, x.get("testability_score") or 0), reverse=True)
    return queue


def _research_strategy_candidate_blueprint(item: dict) -> dict:
    tag = str(item.get("shadow_tag") or item.get("id") or "")
    thesis = str(item.get("thesis") or "")
    target = str(item.get("target_strategy") or "all_strategies")
    fields = [str(x) for x in (item.get("available_fields") or []) if str(x)]
    partial_fields = [str(x) for x in (item.get("partial_fields") or []) if str(x)]
    missing_fields = [str(x) for x in (item.get("missing_fields") or []) if str(x)]
    stats = item.get("evidence_stats") or {}
    evidence_median = int(item.get("evidence_median_score") or stats.get("median_confidence") or item.get("evidence_quality_score") or 0)
    evidence_best = int(item.get("evidence_best_score") or stats.get("best_confidence") or 0)
    mixed = bool(item.get("mixed_evidence") or stats.get("mixed_evidence"))
    base = {
        "research_shadow_tag": tag,
        "target_strategy": target,
        "title": tag.replace("research_", "").replace("_", " ").title(),
        "candidate_type": "shadow_filter",
        "status": "ready_for_shadow_design" if evidence_median >= 65 and len(fields) >= 2 else "needs_mapping",
        "registered": bool(item.get("registered")),
        "registration_id": f"research_candidate_{tag}" if tag else None,
        "confidence_summary": {
            "priority_score": item.get("priority_score"),
            "evidence_median": evidence_median,
            "evidence_best": evidence_best,
            "evidence_grade": item.get("evidence_grade"),
            "mixed_evidence": mixed,
            "source_count": item.get("evidence_count"),
            "direct_crypto_perp_claims": item.get("direct_crypto_perp_claims"),
            "support_claims": item.get("support_claims"),
            "caution_claims": item.get("caution_claims"),
            "contradiction_claims": item.get("contradiction_claims"),
        },
        "thesis": thesis,
        "expected_edge": item.get("expected_edge"),
        "fields_needed": fields,
        "partial_fields": partial_fields,
        "missing_fields": missing_fields,
        "evidence_basis": [c.get("claim") for c in (item.get("evidence_claims") or [])[:3] if isinstance(c, dict) and c.get("claim")],
        "source_trace": item.get("evidence_sources") or [],
        "known_caveats": [],
        "promotion_criteria": item.get("promotion_criteria") or "50+ forward shadow observations, positive net EV after estimated fees/slippage, and stable regime-split performance.",
        "rollback_criteria": item.get("rollback_condition") or "Retire if forward EV is negative, W+P falls below baseline, or the edge only appears in one noisy symbol/regime cluster.",
        "next_action": item.get("next_action") or "Design shadow experiment only.",
        "can_change_live_behavior": False,
    }
    if mixed:
        base["known_caveats"].append("Evidence is mixed; supporting claims must be checked against cautionary and contradictory claims before promotion.")
    if missing_fields:
        base["known_caveats"].append("Some fields are not available in MT7 telemetry yet: " + ", ".join(missing_fields[:5]) + ".")
    if tag == "research_order_flow_confirmation":
        base.update({
            "title": "Flow-Confirmed Momentum Filter",
            "candidate_type": "entry_quality_filter",
            "strategy_shape": "Keep breakout/breakdown candidates only when recent tape flow confirms the intended direction.",
            "entry_filter_rule": "The challenger asks MT7's existing order-flow confirmation check to approve the same momentum_breakout opportunity.",
            "reject_filter_rule": "If that confirmation check returns false, the challenger does not open a Paper position; the unchanged control arm still follows the current strategy.",
            "cohort_definition": "Attach shadow tag to all momentum_breakout, balanced, and funding_arb candidates with flow telemetry; compare flow-confirmed vs flow-divergent forward outcomes by direction and BTC regime.",
            "expected_failure_mode": "Thin-orderbook spoofing can make depth imbalance look supportive immediately before reversal; require forward outcome validation by venue/liquidity bucket.",
        })
    elif tag == "research_volatility_stop_quality":
        base.update({
            "title": "Volatility-Adjusted Stop Quality",
            "candidate_type": "risk_model_shadow_policy",
            "strategy_shape": "Score whether stop distance and TP laddering are appropriate for the current ATR/volatility regime before a trade is considered high quality.",
            "entry_filter_rule": "Annotate candidates where atr_pct and vol_regime imply stop distance is too tight, TP1 is too far, or expected MAE pressure is higher than the planned stop buffer.",
            "reject_filter_rule": "Shadow-reject high/extreme volatility candidates whose stop distance is inside recent regime-normal noise or whose first target does not compensate for expected MAE.",
            "cohort_definition": "Shadow-tag every candidate with atr_pct, vol_regime, journey_mae_pct, journey_mfe_pct, and stop_pressure; evaluate whether stop-quality pass/fail separates net EV.",
            "expected_failure_mode": "Overfitting to recent ATR can suppress legitimate volatility expansion trades; require regime-split validation.",
        })
    elif tag == "research_funding_crowding_filter":
        base.update({
            "title": "Funding Crowding Filter",
            "candidate_type": "crowding_risk_filter",
            "strategy_shape": "Separate funding extremes that imply squeeze opportunity from funding extremes that imply informed crowding against the entry.",
            "entry_filter_rule": "The challenger classifies the same funding_arb opportunity using direction, funding_rate, trend_score, and whether order flow confirmed it.",
            "reject_filter_rule": "It blocks a LONG when funding is below -0.10% and flow is unconfirmed, or a SHORT when funding is above +0.10% and flow is unconfirmed. Other buckets retain the current Paper decision.",
            "cohort_definition": "Tag all funding_arb and balanced candidates by funding_rate bucket, trend_score, direction, and flow confirmation; compare net EV across crowding regimes.",
            "expected_failure_mode": "Funding can stay extreme for long periods; premature reversal assumptions can be expensive without tape confirmation.",
        })
    elif tag == "research_sentiment_macro_regime":
        base.update({
            "title": "Sentiment/Macro Risk Regime Annotation",
            "candidate_type": "regime_annotation",
            "strategy_shape": "Use external sentiment/macro stress as an advisory risk annotation, not an entry signal.",
            "entry_filter_rule": "When news_sentiment or market_context indicates stress, annotate candidates and compare whether higher conviction thresholds or reduced trade frequency improve EV.",
            "reject_filter_rule": "Do not block in v1 unless telemetry proves negative forward EV; start as shadow-only risk-on/risk-off labeling.",
            "cohort_definition": "Collect all candidates with market_context/news_sentiment labels and evaluate EV by sentiment regime, strategy, direction, and BTC trend.",
            "expected_failure_mode": "External sentiment feeds can lag price and may double-count information already reflected in volatility and trend.",
        })
    else:
        base.update({
            "strategy_shape": "Convert the research hypothesis into a shadow tag using mapped MT7 telemetry only.",
            "entry_filter_rule": "Annotate candidates when the mapped fields support the research thesis.",
            "reject_filter_rule": "Shadow-reject only in analysis; do not block live or paper candidates until the cohort validates.",
            "cohort_definition": "Collect 50+ forward observations split by strategy, direction, volatility regime, and BTC regime.",
            "expected_failure_mode": "Research may not transfer to MT7's exchange universe, leverage assumptions, or fee/slippage environment.",
        })
    return base


def _research_strategy_candidates(priority_queue: list[dict], limit: int = 6) -> list[dict]:
    candidates = [_research_strategy_candidate_blueprint(item) for item in (priority_queue or [])[:limit]]
    candidates.sort(
        key=lambda c: (
            c.get("status") == "ready_for_shadow_design",
            int((c.get("confidence_summary") or {}).get("evidence_median") or 0),
            int((c.get("confidence_summary") or {}).get("priority_score") or 0),
        ),
        reverse=True,
    )
    return candidates


def _research_risk_label(score: int) -> str:
    if score >= 70:
        return "high"
    if score >= 42:
        return "medium"
    return "low"


def _research_transfer_risk(
    *,
    claim_stats: dict | None = None,
    status: str = "",
    missing_fields: list[str] | None = None,
    partial_fields: list[str] | None = None,
    overfitting_risk: str = "",
    source_count: int = 1,
) -> dict:
    """Score how likely a research idea fails when transferred into MT7."""
    stats = claim_stats or {}
    missing_fields = [str(x) for x in (missing_fields or []) if str(x)]
    partial_fields = [str(x) for x in (partial_fields or []) if str(x)]
    risk = 10
    reasons: list[str] = []

    status = str(status or "").lower()
    if status in {"metadata_only", "abstract_only", "scanned_needs_ocr", "low_quality_extract"}:
        risk += 22
        reasons.append("weak_or_incomplete_source_text")
    elif status in {"partial_text", "full_text_unverified"}:
        risk += 10
        reasons.append("text_requires_review")

    if int(stats.get("direct_crypto_perp_count") or 0) <= 0:
        risk += 18
        reasons.append("no_direct_crypto_perp_claims")
    if int(stats.get("crypto_claim_count") or 0) <= 0:
        risk += 8
        reasons.append("market_scope_may_not_transfer")
    if bool(stats.get("mixed_evidence")):
        risk += 16
        reasons.append("mixed_or_contradictory_evidence")
    if int(stats.get("contradiction_count") or 0) > 0:
        risk += min(18, int(stats.get("contradiction_count") or 0) * 6)
        reasons.append("explicit_contradictory_claims")
    median = int(stats.get("median_confidence") or 0)
    if median and median < 55:
        risk += 12
        reasons.append("low_median_claim_confidence")
    if not median:
        risk += 10
        reasons.append("no_extractable_claims")
    if source_count < 2:
        risk += 6
        reasons.append("single_source_prior")
    if missing_fields:
        risk += min(20, len(missing_fields) * 6)
        reasons.append("missing_mt7_fields")
    if partial_fields:
        risk += min(8, len(partial_fields) * 3)
        reasons.append("partial_mt7_field_mapping")
    overfit = str(overfitting_risk or "").lower()
    if "high" in overfit:
        risk += 15
        reasons.append("high_overfitting_risk")
    elif "medium" in overfit:
        risk += 7
        reasons.append("medium_overfitting_risk")

    score = max(0, min(100, int(risk)))
    return {
        "score": score,
        "label": _research_risk_label(score),
        "reasons": reasons[:6] or ["directly_mapped_low_transfer_risk"],
    }


def _research_source_dossier(source: dict, claims: list[dict]) -> dict:
    text = str(source.get("raw_excerpt") or source.get("summary") or "")[:60000]
    profile = _research_text_profile(text, str(source.get("source_type") or ""), source.get("full_text_status"))
    status = str(source.get("full_text_status") or profile.get("full_text_status") or "unknown")
    stats = _research_claim_stats(claims)
    hypotheses = [h for h in (source.get("hypotheses") or []) if isinstance(h, dict)]
    fields = []
    for hyp in hypotheses:
        for field in hyp.get("mt7_fields_needed") or []:
            field_s = str(field or "")
            if field_s and field_s not in fields:
                fields.append(field_s)
    transfer = _research_transfer_risk(
        claim_stats=stats,
        status=status,
        missing_fields=[],
        partial_fields=[],
        overfitting_risk="",
        source_count=1,
    )
    role = "primary"
    if status in {"metadata_only", "abstract_only", "scanned_needs_ocr", "low_quality_extract"}:
        role = "discovery_lead"
    elif bool(stats.get("mixed_evidence")) or transfer.get("label") == "high":
        role = "critique_required"
    return {
        "source_id": source.get("id"),
        "title": source.get("title") or source.get("original_filename") or "Research source",
        "source_type": source.get("source_type"),
        "author": source.get("author"),
        "published_at": source.get("published_at"),
        "tags": source.get("tags") or [],
        "summary": str(source.get("summary") or "").strip() or _research_summarize_text(text),
        "full_text_status": status,
        "full_text_word_count": int(source.get("full_text_word_count") or profile.get("full_text_word_count") or 0),
        "quality_score": source.get("quality_score"),
        "relevance_score": source.get("relevance_score"),
        "hypothesis_count": len(hypotheses),
        "mapped_fields": fields[:8],
        "claim_stats": stats,
        "strongest_claims": sorted(claims, key=lambda c: int(c.get("confidence") or 0), reverse=True)[:3],
        "key_takeaways": _research_key_sentences(text, [str(t) for t in (source.get("tags") or [])], limit=3),
        "transfer_risk": transfer,
        "role": role,
        "can_change_behavior": False,
    }


def _research_concept_relationships(nodes: list[dict]) -> list[dict]:
    edges = []
    for idx, left in enumerate(nodes):
        left_fields = set(left.get("fields") or [])
        left_sources = set(left.get("source_ids") or [])
        left_target = str(left.get("target_strategy") or "")
        for right in nodes[idx + 1:]:
            reasons = []
            strength = 0
            shared_fields = sorted(left_fields.intersection(set(right.get("fields") or [])))
            shared_sources = sorted(left_sources.intersection(set(right.get("source_ids") or [])))
            if shared_fields:
                strength += min(40, len(shared_fields) * 12)
                reasons.append("shared_fields: " + ", ".join(shared_fields[:4]))
            if shared_sources:
                strength += min(35, len(shared_sources) * 12)
                reasons.append("shared_sources")
            if left_target and left_target == str(right.get("target_strategy") or ""):
                strength += 18
                reasons.append("same_target_strategy")
            if strength <= 0:
                continue
            edges.append({
                "from": left.get("shadow_tag"),
                "to": right.get("shadow_tag"),
                "strength": min(100, strength),
                "reasons": reasons[:3],
            })
    edges.sort(key=lambda e: int(e.get("strength") or 0), reverse=True)
    return edges[:30]


def _research_claim_matches_concept(claim: dict, concept: dict) -> bool:
    """Keep source-level claims from being copied onto every concept card."""
    claim_text = " ".join([
        str(claim.get("claim") or ""),
        str(claim.get("caveat") or ""),
        str(claim.get("market_scope") or ""),
    ]).lower()
    raw_terms = [
        str(concept.get("shadow_tag") or "").replace("research_", "").replace("_", " "),
        str(concept.get("target_strategy") or "").replace("_", " "),
        *((str(x).replace("_", " ") for x in (concept.get("available_fields") or []))),
        *((str(x).replace("_", " ") for x in (concept.get("missing_fields") or []))),
    ]
    stop = {"research", "strategy", "balanced", "signal", "filter", "quality", "score"}
    tokens = {
        token
        for term in raw_terms
        for token in re.findall(r"[a-z][a-z0-9-]{3,}", term.lower())
        if token not in stop
    }
    return any(token in claim_text for token in tokens)


def _research_corpus_scholar_payload(
    sources: list[dict] | None = None,
    priority_queue: list[dict] | None = None,
    reviews: list[dict] | None = None,
    persist: bool = False,
) -> dict:
    """Build deterministic Corpus Scholar dossiers and maps without trading side effects."""
    sources = [s for s in (sources if sources is not None else _research_load_sources()) if isinstance(s, dict)]
    reviews = reviews if reviews is not None else _cipher_review_research_hypotheses(sources)
    if priority_queue is None:
        priority_queue = _research_priority_queue(reviews or [], _read_experiment_ledger(), sources)

    source_by_id = {str(s.get("id") or ""): s for s in sources if str(s.get("id") or "")}
    claims_by_source: dict[str, list[dict]] = {}
    dossiers = []
    for source in sources:
        sid = str(source.get("id") or "")
        text = str(source.get("raw_excerpt") or source.get("summary") or "")[:60000]
        claims = _research_claims_from_source(source, text=text, limit=6)
        claims_by_source[sid] = claims
        dossiers.append(_research_source_dossier(source, claims))
    dossiers.sort(
        key=lambda d: (
            float(d.get("relevance_score") or 0),
            float(d.get("quality_score") or 0),
            int((d.get("claim_stats") or {}).get("median_confidence") or 0),
            int(d.get("full_text_word_count") or 0),
        ),
        reverse=True,
    )

    nodes = []
    contradiction_items = []
    for item in priority_queue or []:
        source_ids = [str(x) for x in (item.get("source_ids") or []) if str(x)]
        raw_item_claims = [c for c in (item.get("evidence_claims") or []) if isinstance(c, dict)]
        concept_claims = [
            claim for claim in raw_item_claims
            if _research_claim_matches_concept(claim, item)
        ]
        source_claims = []
        source_titles = []
        weak_sources = 0
        coverage_only = False
        for sid in source_ids:
            source = source_by_id.get(sid)
            if source:
                source_titles.append(source.get("title") or sid)
                status = str(source.get("full_text_status") or "").lower()
                if status in {"metadata_only", "abstract_only", "scanned_needs_ocr", "low_quality_extract"}:
                    weak_sources += 1
            source_claims.extend(claims_by_source.get(sid) or [])
        if not concept_claims:
            concept_claims = [
                claim for claim in source_claims
                if _research_claim_matches_concept(claim, item)
            ]
        if not concept_claims:
            coverage_only = True
            concept_name = str(item.get("shadow_tag") or item.get("id") or "this concept")
            concept_claims = [{
                "claim": (
                    f"No concept-specific evidence was extracted for {concept_name}. "
                    "The linked sources require manual review before this idea can enter shadow measurement."
                ),
                "stance": "caution",
                "confidence": 20,
                "market_scope": "coverage_gap",
                "caveat": "Source linkage is not evidence that the source supports this specific concept.",
            }]
        stats = _research_claim_stats(concept_claims)
        missing_fields = [str(x) for x in (item.get("missing_fields") or []) if str(x)]
        partial_fields = [str(x) for x in (item.get("partial_fields") or []) if str(x)]
        transfer = _research_transfer_risk(
            claim_stats=stats,
            status="partial_text" if weak_sources else "full_text",
            missing_fields=missing_fields,
            partial_fields=partial_fields,
            overfitting_risk=str(item.get("overfitting_risk") or ""),
            source_count=max(1, len(source_ids)),
        )
        available_fields = [str(x) for x in (item.get("available_fields") or []) if str(x)]
        node = {
            "shadow_tag": item.get("shadow_tag") or item.get("id"),
            "target_strategy": item.get("target_strategy"),
            "thesis": item.get("thesis"),
            "priority_score": item.get("priority_score"),
            "testability_score": item.get("testability_score"),
            "registered": bool(item.get("registered")),
            "source_ids": source_ids,
            "source_titles": source_titles[:6],
            "source_count": len(source_ids),
            "fields": available_fields,
            "partial_fields": partial_fields,
            "missing_fields": missing_fields,
            "evidence_grade": stats.get("evidence_grade") or item.get("evidence_grade"),
            "claim_stats": stats,
            "support_claims": [c for c in concept_claims if c.get("stance") == "support"][:3],
            "caution_claims": [c for c in concept_claims if c.get("stance") == "caution"][:3],
            "contradiction_claims": [c for c in concept_claims if c.get("stance") == "contradiction"][:3],
            "next_action": item.get("next_action"),
            "transfer_risk": transfer,
            "can_change_behavior": False,
        }
        nodes.append(node)
        support_count = int(stats.get("support_count") or 0)
        caution_count = int(stats.get("caution_count") or 0)
        contradiction_count = int(stats.get("contradiction_count") or 0)
        total_claims = max(1, support_count + caution_count + contradiction_count)
        tension_score = (
            10 if coverage_only and weak_sources else
            5 if coverage_only else
            round(
                contradiction_count / total_claims * 70
                + caution_count / total_claims * 30
                + (10 if stats.get("mixed_evidence") else 0)
                + (5 if weak_sources else 0)
            )
        )
        if tension_score > 0:
            if coverage_only:
                tension_label = "coverage"
                why_flagged = "No claim in the linked evidence could be matched to this specific concept."
            elif contradiction_count:
                tension_label = "contradicted"
                why_flagged = "At least one extracted claim directly conflicts with the concept."
            elif caution_count:
                tension_label = "caution"
                why_flagged = "Evidence contains caveats or transfer warnings, but no direct contradiction."
            else:
                tension_label = "coverage"
                why_flagged = "Evidence coverage is incomplete or weak."
            contradiction_items.append({
                "shadow_tag": node.get("shadow_tag"),
                "target_strategy": node.get("target_strategy"),
                "tension_score": min(100, tension_score),
                "tension_label": tension_label,
                "why_flagged": why_flagged,
                "summary": "This map shows evidence tension, not a trading signal. Resolve it through source review and shadow measurement.",
                "trader_interpretation": (
                    "Do not promote or rely on this concept until its cautions are understood; "
                    "a high score means more unresolved tension, not stronger alpha."
                ),
                "support_count": support_count,
                "caution_count": caution_count,
                "contradiction_count": contradiction_count,
                "mixed_evidence": bool(stats.get("mixed_evidence")),
                "support_claims": node.get("support_claims") or [],
                "caution_claims": node.get("caution_claims") or [],
                "contradiction_claims": node.get("contradiction_claims") or [],
                "transfer_risk": transfer,
            })
    nodes.sort(
        key=lambda n: (
            int(n.get("priority_score") or 0),
            -int((n.get("transfer_risk") or {}).get("score") or 0),
            int((n.get("claim_stats") or {}).get("median_confidence") or 0),
        ),
        reverse=True,
    )
    contradiction_items.sort(key=lambda x: int(x.get("tension_score") or 0), reverse=True)
    edges = _research_concept_relationships(nodes)
    high_risk_concepts = [n for n in nodes if (n.get("transfer_risk") or {}).get("label") == "high"]
    medium_risk_concepts = [n for n in nodes if (n.get("transfer_risk") or {}).get("label") == "medium"]
    high_risk_sources = [d for d in dossiers if (d.get("transfer_risk") or {}).get("label") == "high"]
    payload = {
        "success": True,
        "generated_at": _research_now(),
        "snapshot_path": HERMES_RESEARCH_SCHOLAR_PATH,
        "summary": {
            "source_dossier_count": len(dossiers),
            "concept_count": len(nodes),
            "concept_edge_count": len(edges),
            "contradiction_item_count": len(contradiction_items),
            "high_transfer_risk_concepts": len(high_risk_concepts),
            "medium_transfer_risk_concepts": len(medium_risk_concepts),
            "high_transfer_risk_sources": len(high_risk_sources),
            "can_change_behavior": False,
        },
        "source_dossiers": dossiers,
        "concept_map": {
            "nodes": nodes,
            "edges": edges,
        },
        "contradiction_map": {
            "items": contradiction_items,
            "summary": {
                "items": len(contradiction_items),
                "highest_tension": int(contradiction_items[0].get("tension_score") or 0) if contradiction_items else 0,
                "note": "Contradictions are critique inputs only; they cannot alter paper/live behavior without validation.",
            },
        },
        "transfer_risk": {
            "highest_risk_concepts": high_risk_concepts[:8],
            "highest_risk_sources": high_risk_sources[:8],
            "summary": "Transfer risk scores whether a source/concept is likely to fail when moved into MT7's crypto-perp, leveraged, fee/slippage, and telemetry environment.",
        },
    }
    if persist:
        _research_write_json(HERMES_RESEARCH_SCHOLAR_PATH, payload)
    return payload


_research_scheduler_lock = threading.Lock()


def _research_scheduler_default_config() -> dict:
    return {
        "enabled": False,
        "interval_hours": 24,
        "memo_interval_hours": 168,
        "per_query": 2,
        "providers": ["arxiv", "crossref"],
        "run_local_index": True,
        "run_web_discovery": True,
        "run_scholar": True,
        "run_memo": True,
        "max_queries": 5,
        "last_run_at": None,
        "next_run_at": None,
        "last_status": "idle",
        "last_error": None,
        "last_result": None,
        "last_memo_at": None,
        "drift_alerts": [],
        "history": [],
    }


def _research_parse_dt(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        text = str(value).strip().replace("Z", "+00:00")
        dt = datetime.fromisoformat(text)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _research_scheduler_config() -> dict:
    cfg = _hermes_read_json(HERMES_RESEARCH_SCHEDULER_PATH, {}) or {}
    if not isinstance(cfg, dict):
        cfg = {}
    merged = {**_research_scheduler_default_config(), **cfg}
    merged["interval_hours"] = max(1, min(int(merged.get("interval_hours") or 24), 24 * 14))
    merged["memo_interval_hours"] = max(24, min(int(merged.get("memo_interval_hours") or 168), 24 * 30))
    merged["per_query"] = max(1, min(int(merged.get("per_query") or 2), 6))
    merged["max_queries"] = max(1, min(int(merged.get("max_queries") or 5), 10))
    providers = merged.get("providers") if isinstance(merged.get("providers"), list) else ["arxiv", "crossref"]
    merged["providers"] = [p for p in [str(x).lower() for x in providers] if p in {"arxiv", "crossref"}] or ["arxiv", "crossref"]
    merged["drift_alerts"] = [a for a in (merged.get("drift_alerts") or []) if isinstance(a, dict)][:30]
    merged["history"] = [h for h in (merged.get("history") or []) if isinstance(h, dict)][:20]
    return merged


def _research_scheduler_save(cfg: dict) -> dict:
    _research_write_json(HERMES_RESEARCH_SCHEDULER_PATH, cfg)
    return cfg


def _research_scheduler_next_run(cfg: dict, now: datetime | None = None) -> str:
    now = now or datetime.now(timezone.utc)
    interval = max(1, int(cfg.get("interval_hours") or 24))
    last = _research_parse_dt(cfg.get("last_run_at"))
    base = last or now
    return (base + timedelta(hours=interval)).isoformat()


def _research_scheduler_query_plan(
    scholar: dict | None = None,
    cfg: dict | None = None,
    limit: int | None = None,
) -> list[dict]:
    cfg = cfg or _research_scheduler_config()
    scholar = scholar or _research_corpus_scholar_payload(persist=False)
    limit = int(limit or cfg.get("max_queries") or 5)
    nodes = ((scholar.get("concept_map") or {}).get("nodes") or []) if isinstance(scholar, dict) else []
    risk_nodes = ((scholar.get("transfer_risk") or {}).get("highest_risk_concepts") or []) if isinstance(scholar, dict) else []
    contradiction_items = ((scholar.get("contradiction_map") or {}).get("items") or []) if isinstance(scholar, dict) else []
    by_tag = {}
    for node in [*nodes, *risk_nodes]:
        if isinstance(node, dict) and node.get("shadow_tag"):
            by_tag[str(node.get("shadow_tag"))] = node
    for item in contradiction_items:
        if isinstance(item, dict) and item.get("shadow_tag"):
            by_tag.setdefault(str(item.get("shadow_tag")), item)

    plans: list[dict] = []
    seen_queries: set[str] = set()
    def add(query: str, tags: list[str], reason: str, source: str) -> None:
        clean = re.sub(r"\s+", " ", query).strip()
        key = clean.lower()
        if not clean or key in seen_queries:
            return
        seen_queries.add(key)
        plans.append({
            "query": clean,
            "tags": sorted({str(t).strip() for t in tags if str(t).strip()})[:8],
            "reason": reason[:280],
            "source": source,
        })

    for tag, node in sorted(
        by_tag.items(),
        key=lambda kv: (
            int(((kv[1].get("transfer_risk") or {}).get("score") or 0)),
            int(kv[1].get("priority_score") or 0),
        ),
        reverse=True,
    ):
        fields = [str(x).replace("_", " ") for x in (node.get("fields") or node.get("missing_fields") or [])[:3]]
        thesis_terms = " ".join(re.findall(r"[A-Za-z][A-Za-z -]{3,}", str(node.get("thesis") or ""))[:2])
        tag_terms = tag.replace("research_", "").replace("_", " ")
        query = " ".join(["cryptocurrency perpetual futures", tag_terms, *fields])[:180]
        reason = (
            f"Corpus Scholar follow-up for {tag}: verify transfer risk, contradictions, and current evidence before this concept influences MT7."
        )
        add(query, [tag_terms, *(fields or []), str(node.get("target_strategy") or "")], reason, tag)
        if thesis_terms and len(plans) < limit:
            add(
                f"crypto derivatives {thesis_terms}",
                [tag_terms, "crypto", "derivatives"],
                f"Secondary concept search for {tag}; source must pass MT7 relevance gates.",
                tag,
            )
        if len(plans) >= limit:
            break

    for spec in _research_default_web_queries():
        if len(plans) >= limit:
            break
        add(spec.get("query") or "", spec.get("tags") or [], spec.get("reason") or "Default controlled research discovery.", "default")
    return plans[:limit]


def _research_rulebook_modes_by_tag() -> dict[str, dict]:
    try:
        items = (_research_rulebook_payload().get("items") or [])
    except Exception:
        items = []
    out = {}
    for item in items:
        tag = str(item.get("research_shadow_tag") or "")
        if tag:
            out[tag] = item
    return out


def _research_drift_alerts_from_sources(
    sources: list[dict],
    *,
    existing_alerts: list[dict] | None = None,
) -> list[dict]:
    existing_ids = {str(a.get("id") or "") for a in (existing_alerts or []) if isinstance(a, dict)}
    rulebook = _research_rulebook_modes_by_tag()
    alerts = []
    for source in sources:
        if not isinstance(source, dict):
            continue
        source_id = str(source.get("id") or "")
        text = str(source.get("raw_excerpt") or source.get("summary") or "")[:60000]
        claims = _research_claims_from_source(source, text=text, limit=8)
        caution_claims = [c for c in claims if c.get("stance") in {"contradiction", "caution"}]
        if not caution_claims:
            continue
        hypotheses = [h for h in (source.get("hypotheses") or []) if isinstance(h, dict)]
        tags = [str(h.get("shadow_tag") or "") for h in hypotheses if h.get("shadow_tag")]
        if not tags:
            tags = [str(t) for t in (source.get("tags") or []) if str(t)]
        for tag in tags[:5]:
            rule = rulebook.get(tag) or {}
            mode = ((rule.get("rule_control") or {}).get("mode") or "shadow")
            for claim in caution_claims[:3]:
                severity = "high" if claim.get("stance") == "contradiction" and mode in {"paper_trial", "paper_applied", "live_candidate"} else "medium" if claim.get("stance") == "contradiction" else "low"
                alert_id = _research_slug_id("drift", source_id, tag, claim.get("claim"), claim.get("stance"))
                if alert_id in existing_ids:
                    continue
                alerts.append({
                    "id": alert_id,
                    "created_at": _research_now(),
                    "severity": severity,
                    "shadow_tag": tag,
                    "source_id": source_id,
                    "source_title": source.get("title"),
                    "rule_mode": mode,
                    "stance": claim.get("stance"),
                    "claim": claim.get("claim"),
                    "confidence": claim.get("confidence"),
                    "evidence_type": claim.get("evidence_type"),
                    "market_scope": claim.get("market_scope"),
                    "action": "Review contradiction before promotion; keep behavior unchanged until source-level audit resolves it.",
                    "can_change_behavior": False,
                })
    alerts.sort(key=lambda a: ({"high": 3, "medium": 2, "low": 1}.get(a.get("severity"), 0), int(a.get("confidence") or 0)), reverse=True)
    return alerts


def _research_scheduler_due(cfg: dict | None = None, now: datetime | None = None) -> bool:
    cfg = cfg or _research_scheduler_config()
    if not bool(cfg.get("enabled")):
        return False
    now = now or datetime.now(timezone.utc)
    next_run = _research_parse_dt(cfg.get("next_run_at"))
    if next_run is None:
        last = _research_parse_dt(cfg.get("last_run_at"))
        if last is None:
            return True
        next_run = last + timedelta(hours=int(cfg.get("interval_hours") or 24))
    return now >= next_run


def _research_scheduler_payload() -> dict:
    cfg = _research_scheduler_config()
    scholar = _research_corpus_scholar_payload(persist=False)
    query_plan = _research_scheduler_query_plan(scholar=scholar, cfg=cfg)
    now = datetime.now(timezone.utc)
    effective_next_run_at = cfg.get("next_run_at") or _research_scheduler_next_run(cfg, now=now)
    cfg_view = {k: v for k, v in cfg.items() if k not in {"history", "drift_alerts", "last_result"}}
    cfg_view["next_run_at"] = effective_next_run_at
    return {
        "success": True,
        "generated_at": _research_now(),
        "config": cfg_view,
        "enabled": bool(cfg.get("enabled")),
        "due": _research_scheduler_due(cfg, now=now),
        "query_plan": query_plan,
        "drift_alerts": cfg.get("drift_alerts") or [],
        "history": cfg.get("history") or [],
        "last_result": cfg.get("last_result"),
        "scope": {
            "authority": "Scheduler may index research, run controlled discovery, rebuild scholar maps, and generate memos only.",
            "forbidden": "No scheduler cycle can alter scoring, paper config, sizing, or live execution.",
            "review_path": "New evidence -> drift alert/source audit -> shadow measurement -> paper evidence -> user approval.",
        },
    }


def _research_scheduler_update(payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    cfg = _research_scheduler_config()
    for key in ("enabled", "run_local_index", "run_web_discovery", "run_scholar", "run_memo"):
        if key in payload:
            cfg[key] = bool(payload.get(key))
    for key, lo, hi in (("interval_hours", 1, 24 * 14), ("memo_interval_hours", 24, 24 * 30), ("per_query", 1, 6), ("max_queries", 1, 10)):
        if key in payload:
            cfg[key] = max(lo, min(int(payload.get(key) or cfg.get(key) or lo), hi))
    if isinstance(payload.get("providers"), list):
        providers = [str(p).lower() for p in payload.get("providers") if str(p).lower() in {"arxiv", "crossref"}]
        cfg["providers"] = providers or cfg.get("providers") or ["arxiv", "crossref"]
    if payload.get("enabled") is True and not cfg.get("next_run_at"):
        cfg["next_run_at"] = _research_scheduler_next_run(cfg)
    if payload.get("reset_alerts"):
        cfg["drift_alerts"] = []
    cfg["updated_at"] = _research_now()
    cfg["updated_by"] = str(payload.get("actor") or "local_user")[:80]
    _research_scheduler_save(cfg)
    return _research_scheduler_payload()


def _research_scheduler_run_once(reason: str = "manual", force_memo: bool = False) -> dict:
    if not _research_scheduler_lock.acquire(blocking=False):
        return {"success": False, "error": "Research scheduler is already running."}
    cfg = _research_scheduler_config()
    started_at = _research_now()
    result = {
        "success": True,
        "started_at": started_at,
        "finished_at": None,
        "reason": reason,
        "steps": [],
        "added_sources": 0,
        "drift_alert_count": 0,
        "new_drift_alert_count": 0,
        "can_change_behavior": False,
    }
    try:
        before_sources = {str(s.get("id") or "") for s in _research_load_sources() if isinstance(s, dict)}
        if cfg.get("run_local_index"):
            index_result = _research_seed_local_corpus(limit=250, force=False)
            result["steps"].append({"step": "local_index", **index_result})
        scholar_pre = _research_corpus_scholar_payload(persist=False)
        query_plan = _research_scheduler_query_plan(scholar=scholar_pre, cfg=cfg)
        if cfg.get("run_web_discovery"):
            discovery = _research_discover_web_sources({
                "queries": query_plan,
                "providers": cfg.get("providers") or ["arxiv", "crossref"],
                "per_query": int(cfg.get("per_query") or 2),
            })
            result["steps"].append({"step": "web_discovery", **discovery})
            result["added_sources"] = int(discovery.get("added") or 0)
        sources_after = _research_load_sources()
        new_sources = [s for s in sources_after if str(s.get("id") or "") not in before_sources]
        existing_alerts = cfg.get("drift_alerts") or []
        new_alerts = _research_drift_alerts_from_sources(new_sources, existing_alerts=existing_alerts)
        combined_alerts = (new_alerts + existing_alerts)[:30]
        cfg["drift_alerts"] = combined_alerts
        result["drift_alert_count"] = len(combined_alerts)
        result["new_drift_alert_count"] = len(new_alerts)
        result["drift_alerts"] = new_alerts[:10]
        if cfg.get("run_scholar"):
            scholar = _research_corpus_scholar_payload(sources=sources_after, persist=True)
            summary = scholar.get("summary") or {}
            result["steps"].append({"step": "corpus_scholar", "summary": summary})
        memo_due = force_memo
        last_memo_at = _research_parse_dt(cfg.get("last_memo_at")) or _research_parse_dt(cfg.get("last_run_at"))
        if last_memo_at is None:
            memo_due = True
        elif datetime.now(timezone.utc) >= last_memo_at + timedelta(hours=int(cfg.get("memo_interval_hours") or 168)):
            memo_due = True
        if cfg.get("run_memo") and memo_due:
            memo = _research_generate_memo(register_experiments=True)
            cfg["last_memo_at"] = memo.get("generated_at") or _research_now()
            result["steps"].append({
                "step": "research_memo",
                "source_count": memo.get("source_count"),
                "registered_shadow_experiments": memo.get("registered_shadow_experiments"),
            })
        elif cfg.get("run_memo"):
            result["steps"].append({"step": "research_memo", "skipped": True, "reason": "memo interval not due"})
        finished_at = _research_now()
        cfg["last_run_at"] = finished_at
        cfg["next_run_at"] = _research_scheduler_next_run(cfg, now=_research_parse_dt(finished_at) or datetime.now(timezone.utc))
        cfg["last_status"] = "ok"
        cfg["last_error"] = None
        result["finished_at"] = finished_at
        result["query_plan"] = query_plan
        cfg["last_result"] = {k: v for k, v in result.items() if k != "drift_alerts"}
        history = [cfg["last_result"], *(cfg.get("history") or [])]
        cfg["history"] = history[:20]
        _research_scheduler_save(cfg)
        return {"success": True, **result, "scheduler": _research_scheduler_payload()}
    except Exception as e:
        finished_at = _research_now()
        cfg["last_run_at"] = finished_at
        cfg["next_run_at"] = _research_scheduler_next_run(cfg, now=_research_parse_dt(finished_at) or datetime.now(timezone.utc))
        cfg["last_status"] = "error"
        cfg["last_error"] = str(e)
        result.update({"success": False, "finished_at": finished_at, "error": str(e)})
        cfg["last_result"] = result
        cfg["history"] = [result, *(cfg.get("history") or [])][:20]
        _research_scheduler_save(cfg)
        print(f"[research_scheduler] run error: {e}", file=sys.stderr)
        return result
    finally:
        _research_scheduler_lock.release()


def _research_register_strategy_candidate(shadow_tag: str) -> dict:
    audit = _research_priority_audit_payload(shadow_tag)
    if not audit.get("success"):
        return audit
    candidate = audit.get("strategy_candidate") or {}
    concept = audit.get("concept") or {}
    tag = str(candidate.get("research_shadow_tag") or concept.get("shadow_tag") or shadow_tag or "").strip()
    if not tag:
        return {"success": False, "error": "Missing candidate shadow tag"}
    record = {
        "id": f"research_candidate_{tag}",
        "created_at": _research_now(),
        "source": "hermes_research_strategy_candidate",
        "status": "shadow_proposed",
        "candidate_title": candidate.get("title"),
        "candidate_type": candidate.get("candidate_type"),
        "research_shadow_tag": tag,
        "shadow_tag": tag,
        "target_strategy": candidate.get("target_strategy"),
        "hypothesis": candidate.get("thesis") or concept.get("thesis"),
        "strategy_shape": candidate.get("strategy_shape"),
        "entry_filter_rule": candidate.get("entry_filter_rule"),
        "reject_filter_rule": candidate.get("reject_filter_rule"),
        "cohort_definition": candidate.get("cohort_definition"),
        "expected_failure_mode": candidate.get("expected_failure_mode"),
        "mt7_fields_needed": candidate.get("fields_needed") or [],
        "partial_fields": candidate.get("partial_fields") or [],
        "missing_fields": candidate.get("missing_fields") or [],
        "promotion_criteria": candidate.get("promotion_criteria"),
        "rollback_condition": candidate.get("rollback_criteria"),
        "confidence_summary": candidate.get("confidence_summary") or {},
        "source_trace": candidate.get("source_trace") or [],
        "evidence_basis": candidate.get("evidence_basis") or [],
        "known_caveats": candidate.get("known_caveats") or [],
        "can_change_live_behavior": False,
        "notes": [
            "Measurement-only registration. Does not change scanner scoring, risk gates, paper config, sizing, or execution.",
            "Promotion requires forward evidence and explicit human review.",
        ],
    }
    created = _append_experiment_record_once(record, key="id")
    existing = record
    if not created:
        existing = next(
            (x for x in _read_experiment_ledger() if isinstance(x, dict) and x.get("id") == record["id"]),
            record,
        )
    return {
        "success": True,
        "created": created,
        "record": existing,
        "candidate": candidate,
        "pipeline": _hermes_research_pipeline_summary(),
    }


def _research_eval_stats(rows: list[dict]) -> dict:
    closed = [
        r for r in rows
        if str(r.get("result") or "").upper() in {"WIN", "LOSS", "PARTIAL", "TP3"}
        and r.get("pnl_pct") is not None
    ]
    pnls = [float(r.get("pnl_pct") or 0.0) for r in closed]
    wins = [r for r in closed if str(r.get("result") or "").upper() in {"WIN", "TP3"}]
    partials = [r for r in closed if str(r.get("result") or "").upper() == "PARTIAL"]
    losses = [r for r in closed if str(r.get("result") or "").upper() == "LOSS"]
    gains = [p for p in pnls if p > 0]
    loss_vals = [abs(p) for p in pnls if p < 0]
    return {
        "count": len(closed),
        "wins": len(wins),
        "partials": len(partials),
        "losses": len(losses),
        "win_partial_rate": round((len(wins) + len(partials)) / len(closed) * 100, 1) if closed else None,
        "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
        "total_pnl_pct": round(sum(pnls), 2) if pnls else 0,
        "best_pnl_pct": round(max(pnls), 2) if pnls else None,
        "worst_pnl_pct": round(min(pnls), 2) if pnls else None,
        "profit_factor": round(sum(gains) / sum(loss_vals), 2) if loss_vals else (round(sum(gains), 2) if gains else None),
    }


def _research_group_stats(rows: list[dict], key: str, limit: int = 8) -> list[dict]:
    groups: dict[str, list[dict]] = defaultdict(list)
    for row in rows:
        groups[str(row.get(key) or "unknown")].append(row)
    out = []
    for label, items in groups.items():
        stats = _research_eval_stats(items)
        if stats.get("count"):
            out.append({"key": label, **stats})
    out.sort(key=lambda x: (x.get("count") or 0, x.get("avg_pnl_pct") or -999), reverse=True)
    return out[:limit]


def _research_load_closed_signal_outcomes(limit: int = 2400) -> list[dict]:
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute("""
            SELECT id, logged_at, result_at, symbol, direction, strategy_key, result, pnl_pct,
                   flow_score, flow_confirmed, trend_score, atr_pct, volatility, funding_rate, signal_json, source
            FROM signals
            WHERE result IN ('WIN','LOSS','PARTIAL','TP3')
              AND pnl_pct IS NOT NULL
            ORDER BY COALESCE(result_at, logged_at, '') DESC
            LIMIT ?
        """, (int(limit),)).fetchall()
        con.close()
    except Exception as e:
        print(f"[research_shadow_results] load error: {e}", file=sys.stderr)
        return []
    out = []
    for row in rows:
        item = dict(row)
        try:
            sj = json.loads(item.get("signal_json") or "{}")
        except Exception:
            sj = {}
        item["agent_regime"] = sj.get("agent_regime") or sj.get("market_regime") or "unknown"
        item["btc_trend"] = ((sj.get("btc_context") or {}).get("btc_trend") or sj.get("daily_trend") or "unknown")
        item["vol_regime"] = sj.get("vol_regime") or sj.get("volatility_regime") or item.get("volatility") or "unknown"
        item["flow_delta_pct"] = sj.get("flow_delta_pct")
        item["depth_imbalance"] = sj.get("depth_imbalance")
        item["profile_poc"] = sj.get("profile_poc")
        item["journey_mae_pct"] = sj.get("journey_mae_pct")
        item["journey_mfe_pct"] = sj.get("journey_mfe_pct")
        item["journey_stop_pressure"] = sj.get("journey_stop_pressure") or sj.get("stop_pressure")
        item["journey_available"] = bool(sj.get("journey_available"))
        item["source_json"] = sj
        out.append(item)
    return out


def _research_float(value, default=None):
    try:
        if value is None or value == "":
            return default
        return float(value)
    except Exception:
        return default


def _research_flow_bucket(row: dict) -> str:
    direction = str(row.get("direction") or "").upper()
    score = row.get("flow_score")
    confirmed = row.get("flow_confirmed")
    delta = row.get("flow_delta_pct")
    depth = row.get("depth_imbalance")
    try:
        score_f = float(score) if score is not None else None
    except Exception:
        score_f = None
    try:
        delta_f = float(delta) if delta is not None else None
    except Exception:
        delta_f = None
    try:
        depth_f = float(depth) if depth is not None else None
    except Exception:
        depth_f = None
    if confirmed in {1, True, "1", "true", "True"}:
        return "flow_confirmed"
    if score_f is not None and score_f >= 60:
        return "flow_confirmed"
    if direction == "LONG":
        if (delta_f is not None and delta_f < 0) or (depth_f is not None and depth_f < -0.12) or (score_f is not None and score_f < 40):
            return "flow_divergent"
    elif direction == "SHORT":
        if (delta_f is not None and delta_f > 0) or (depth_f is not None and depth_f > 0.12) or (score_f is not None and score_f < 40):
            return "flow_divergent"
    if score_f is not None or delta_f is not None or depth_f is not None:
        return "flow_neutral"
    return "flow_unknown"


def _research_stop_quality_bucket(row: dict) -> str:
    """Retrospective stop-quality label using journey fields when available."""
    atr = _research_float(row.get("atr_pct"))
    mae = _research_float(row.get("journey_mae_pct"))
    mfe = _research_float(row.get("journey_mfe_pct"))
    pressure = _research_float(row.get("journey_stop_pressure"))
    vol = str(row.get("vol_regime") or row.get("volatility") or "").lower()
    if mae is None and mfe is None and pressure is None:
        return "stop_quality_unknown"
    if pressure is not None and pressure >= 95:
        return "stop_pressure_danger"
    if atr is not None and mae is not None and atr > 0 and mae > atr * 1.35:
        return "mae_exceeds_regime_noise"
    if vol in {"high", "extreme", "extreme_vol"} and pressure is not None and pressure >= 75:
        return "volatile_stop_stressed"
    if pressure is not None and pressure <= 65 and (mfe is None or mae is None or mfe >= mae * 0.8):
        return "stop_quality_healthy"
    if pressure is not None and pressure <= 80:
        return "stop_quality_acceptable"
    return "stop_quality_neutral"


def _research_funding_bucket(row: dict) -> str:
    direction = str(row.get("direction") or "").upper()
    funding = _research_float(row.get("funding_rate"), 0.0)
    trend = _research_float(row.get("trend_score"), 0.0)
    flow_confirmed = row.get("flow_confirmed") in {1, True, "1", "true", "True"}
    if funding is None:
        return "funding_unknown"
    abs_funding = abs(funding)
    if abs_funding < 0.0003:
        return "funding_neutral"
    if direction == "LONG" and funding < -0.001 and not flow_confirmed:
        return "negative_funding_long_trap"
    if direction == "SHORT" and funding > 0.001 and not flow_confirmed:
        return "positive_funding_short_trap"
    if flow_confirmed and abs_funding >= 0.0008:
        return "funding_extreme_flow_confirmed"
    if direction == "LONG" and funding < 0 and trend is not None and trend >= 25:
        return "squeeze_candidate"
    if direction == "SHORT" and funding > 0 and trend is not None and trend <= -25:
        return "long_flush_candidate"
    return "funding_crowded_unclear"


def _research_macro_bucket(row: dict) -> str:
    regime = str(row.get("agent_regime") or "unknown").lower()
    btc = str(row.get("btc_trend") or "unknown").lower()
    direction = str(row.get("direction") or "").upper()
    stress_regimes = {"choppy", "low_liquidity", "news_catalyst", "volatile_squeeze", "macro_stress"}
    if regime in stress_regimes or "bear" in btc:
        if direction == "LONG":
            return "macro_stress_long"
        if direction == "SHORT":
            return "macro_stress_short"
        return "macro_stress"
    if "bull" in btc or regime in {"trending", "risk_on", "momentum"}:
        return "macro_supportive"
    if regime == "unknown" and btc == "unknown":
        return "macro_unknown"
    return "macro_neutral"


def _research_shadow_verdict(pass_stats: dict, compare_stats: dict, target_n: int = 50) -> dict:
    n = int(pass_stats.get("count") or 0)
    pass_ev = pass_stats.get("avg_pnl_pct")
    compare_ev = compare_stats.get("avg_pnl_pct")
    pass_wp = pass_stats.get("win_partial_rate")
    verdict = "collecting"
    reason = f"Historical association sample is {n}/{target_n}; this is not forward causal evidence."
    if n >= target_n and pass_ev is not None and compare_ev is not None:
        if pass_ev > 0 and pass_ev > compare_ev and (pass_wp or 0) >= 50:
            verdict = "historical_candidate"
            reason = "Historical matched bucket is positive and separated; register a forward experiment before any promotion."
        elif pass_ev < 0 and pass_ev <= compare_ev:
            verdict = "historical_reject"
            reason = "Historical matched bucket is negative and does not beat comparison."
        else:
            verdict = "needs_more_data"
            reason = "Sample is large enough, but separation is not decisive."
    elif n >= target_n:
        verdict = "needs_more_data"
        reason = "Sample exists, but comparison data is incomplete."
    return {
        "status": verdict,
        "reason": reason,
        "progress": {"closed": n, "target": target_n, "pct": round(min(1.0, n / target_n) * 100, 1)},
    }


def _research_result_payload(
    record: dict,
    candidate: dict,
    scoped: list[dict],
    passed: list[dict],
    comparison: list[dict],
    evaluator: str,
    matched_bucket: str,
    comparison_bucket: str,
    verdict_target: int = 50,
    notes: list[str] | None = None,
) -> dict:
    pass_stats = _research_eval_stats(passed)
    compare_stats = _research_eval_stats(comparison)
    verdict = _research_shadow_verdict(pass_stats, compare_stats, target_n=verdict_target)
    if "stop_quality" in evaluator:
        verdict = {
            **verdict,
            "status": "diagnostic_only",
            "reason": (
                "Retrospective MAE/MFE/stop-pressure can diagnose stop design "
                "but cannot promote a pre-entry rule."
            ),
        }
    return {
        "evaluator": evaluator,
        "candidate_id": record.get("id"),
        "research_shadow_tag": record.get("research_shadow_tag") or record.get("shadow_tag"),
        "candidate_title": record.get("candidate_title") or candidate.get("title"),
        "candidate_type": record.get("candidate_type") or candidate.get("candidate_type"),
        "target_strategy": record.get("target_strategy") or candidate.get("target_strategy"),
        "status": verdict["status"],
        "verdict_reason": verdict["reason"],
        "promotion_progress": verdict["progress"],
        "matched_bucket": matched_bucket,
        "comparison_bucket": comparison_bucket,
        "matched": pass_stats,
        "comparison": compare_stats,
        "all_scoped": _research_eval_stats(scoped),
        "direction_split": _research_group_stats(passed, "direction", limit=4),
        "strategy_split": _research_group_stats(passed, "strategy_key", limit=6),
        "regime_split": _research_group_stats(passed, "agent_regime", limit=6),
        "btc_trend_split": _research_group_stats(passed, "btc_trend", limit=6),
        "bucket_split": _research_group_stats(scoped, "research_bucket", limit=8),
        "notes": notes or [],
        "evidence_scope": "historical_mixed_policy_association",
        "forward_causal_evidence": False,
        "recent_examples": [
            {
                "id": r.get("id"),
                "symbol": r.get("symbol"),
                "direction": r.get("direction"),
                "strategy_key": r.get("strategy_key"),
                "result": r.get("result"),
                "pnl_pct": r.get("pnl_pct"),
                "flow_score": r.get("flow_score"),
                "funding_rate": r.get("funding_rate"),
                "atr_pct": r.get("atr_pct"),
                "bucket": r.get("research_bucket"),
                "result_at": r.get("result_at"),
            }
            for r in passed[:8]
        ],
        "measurement_only": True,
    }


def _research_evaluate_flow_candidate(record: dict, candidate: dict, rows: list[dict]) -> dict:
    target_strategy = record.get("target_strategy") or candidate.get("target_strategy")
    scoped = []
    for row in rows:
        if target_strategy and target_strategy not in {"all", "all_strategies"} and str(row.get("strategy_key") or "") != str(target_strategy):
            continue
        bucket = _research_flow_bucket(row)
        item = dict(row)
        item["research_bucket"] = bucket
        scoped.append(item)
    passed = [r for r in scoped if r.get("research_bucket") == "flow_confirmed"]
    divergent = [r for r in scoped if r.get("research_bucket") == "flow_divergent"]
    comparison = [r for r in scoped if r.get("research_bucket") in {"flow_divergent", "flow_neutral"}]
    payload = _research_result_payload(
        record, candidate, scoped, passed, comparison,
        evaluator="flow_confirmation_v1",
        matched_bucket="flow_confirmed",
        comparison_bucket="flow_divergent_or_neutral",
    )
    payload.update({
        "divergent": _research_eval_stats(divergent),
    })
    return payload


def _research_evaluate_stop_quality_candidate(record: dict, candidate: dict, rows: list[dict]) -> dict:
    scoped = []
    for row in rows:
        bucket = _research_stop_quality_bucket(row)
        item = dict(row)
        item["research_bucket"] = bucket
        scoped.append(item)
    passed = [r for r in scoped if r.get("research_bucket") in {"stop_quality_healthy", "stop_quality_acceptable"}]
    comparison = [r for r in scoped if r.get("research_bucket") in {"stop_pressure_danger", "mae_exceeds_regime_noise", "volatile_stop_stressed"}]
    return _research_result_payload(
        record, candidate, scoped, passed, comparison,
        evaluator="volatility_stop_quality_v1",
        matched_bucket="healthy_or_acceptable_stop_quality",
        comparison_bucket="stop_pressure_or_regime_noise_danger",
        notes=["Retrospective evaluator: journey MAE/MFE/stop-pressure are known after outcome, so this validates stop design quality rather than making a pre-entry live gate."],
    )


def _research_evaluate_funding_candidate(record: dict, candidate: dict, rows: list[dict]) -> dict:
    scoped = []
    for row in rows:
        if str(row.get("strategy_key") or "") not in {"funding_arb", "balanced", "balanced_focus_short", "funding_arb_focus_short"}:
            continue
        bucket = _research_funding_bucket(row)
        item = dict(row)
        item["research_bucket"] = bucket
        scoped.append(item)
    passed = [r for r in scoped if r.get("research_bucket") in {"funding_extreme_flow_confirmed", "squeeze_candidate", "long_flush_candidate"}]
    comparison = [r for r in scoped if r.get("research_bucket") in {"negative_funding_long_trap", "positive_funding_short_trap", "funding_crowded_unclear"}]
    return _research_result_payload(
        record, candidate, scoped, passed, comparison,
        evaluator="funding_crowding_v1",
        matched_bucket="funding_extreme_confirmed_or_aligned",
        comparison_bucket="funding_crowded_trap_or_unclear",
    )


def _research_evaluate_macro_candidate(record: dict, candidate: dict, rows: list[dict]) -> dict:
    scoped = []
    for row in rows:
        bucket = _research_macro_bucket(row)
        item = dict(row)
        item["research_bucket"] = bucket
        scoped.append(item)
    passed = [r for r in scoped if r.get("research_bucket") in {"macro_supportive", "macro_stress_short"}]
    comparison = [r for r in scoped if r.get("research_bucket") in {"macro_stress_long", "macro_stress", "macro_neutral"}]
    return _research_result_payload(
        record, candidate, scoped, passed, comparison,
        evaluator="sentiment_macro_regime_v1",
        matched_bucket="macro_supportive_or_stress_short",
        comparison_bucket="macro_stress_long_or_neutral",
        notes=["Uses available BTC trend and agent_regime fields as current proxy; external news_sentiment can be added later when coverage is stable."],
    )


def _research_shadow_results_payload() -> dict:
    ledger = _read_experiment_ledger()
    registered_by_tag: dict[str, dict] = {}
    for item in ledger:
        if not isinstance(item, dict) or item.get("source") not in {"hermes_research_pipeline", "hermes_research_strategy_candidate"}:
            continue
        tag = str(item.get("research_shadow_tag") or item.get("shadow_tag") or "")
        if not tag:
            continue
        if tag not in registered_by_tag or item.get("source") == "hermes_research_strategy_candidate":
            registered_by_tag[tag] = item
    registered = list(registered_by_tag.values())
    rows = _research_load_closed_signal_outcomes()
    results = []
    for record in registered:
        tag = str(record.get("research_shadow_tag") or record.get("shadow_tag") or "")
        candidate = {
            "title": record.get("candidate_title"),
            "candidate_type": record.get("candidate_type"),
            "target_strategy": record.get("target_strategy"),
        }
        if tag == "research_order_flow_confirmation":
            results.append(_research_evaluate_flow_candidate(record, candidate, rows))
        elif tag == "research_volatility_stop_quality":
            results.append(_research_evaluate_stop_quality_candidate(record, candidate, rows))
        elif tag == "research_funding_crowding_filter":
            results.append(_research_evaluate_funding_candidate(record, candidate, rows))
        elif tag == "research_sentiment_macro_regime":
            results.append(_research_evaluate_macro_candidate(record, candidate, rows))
        else:
            results.append({
                "candidate_id": record.get("id"),
                "research_shadow_tag": tag,
                "candidate_title": record.get("candidate_title"),
                "candidate_type": record.get("candidate_type"),
                "target_strategy": record.get("target_strategy"),
                "status": "evaluator_pending",
                "verdict_reason": "Registered, but deterministic evaluator logic is not implemented for this candidate yet.",
                "promotion_progress": {"closed": 0, "target": 50, "pct": 0},
                "matched": _research_eval_stats([]),
                "comparison": _research_eval_stats([]),
                "measurement_only": True,
            })
    summary = {
        "registered": len(registered),
        "evaluated": len([r for r in results if r.get("status") != "evaluator_pending"]),
        "promote_candidate": len([r for r in results if r.get("status") == "promote_candidate"]),
        "reject_candidate": len([r for r in results if r.get("status") == "reject_candidate"]),
        "collecting": len([r for r in results if r.get("status") == "collecting"]),
        "needs_more_data": len([r for r in results if r.get("status") == "needs_more_data"]),
        "evaluator_pending": len([r for r in results if r.get("status") == "evaluator_pending"]),
        "closed_outcome_rows": len(rows),
    }
    return {
        "success": True,
        "generated_at": _research_now(),
        "summary": summary,
        "results": results,
        "measurement_only": True,
    }


def _research_field_readiness(fields: list[str] | None) -> dict:
    """Classify mapped fields by whether MT7 can know them before entry."""
    pre_entry = {
        "agent_regime", "atr_pct", "basis", "change_1h_pct", "depth_imbalance",
        "flow_confirmed", "flow_delta_pct", "flow_score", "funding_rate",
        "market_context", "order_flow_vwap", "profile_poc", "trend_score",
        "vol_regime",
    }
    partial = {"btc_beta", "btc_context", "news_sentiment"}
    retrospective = {"journey_mae_pct", "journey_mfe_pct", "journey_stop_pressure", "stop_pressure"}
    out = {"pre_entry": [], "partial": [], "retrospective": [], "missing": []}
    for field in [str(f).strip() for f in (fields or []) if str(f).strip()]:
        if field in pre_entry:
            out["pre_entry"].append(field)
        elif field in partial:
            out["partial"].append(field)
        elif field in retrospective:
            out["retrospective"].append(field)
        else:
            out["missing"].append(field)
    return out


def _research_read_learner_briefs(limit: int = 80) -> list[dict]:
    """Best-effort read of mt-learner researcher briefs for cross-linking."""
    paths = [
        "/opt/mt-learner/research/briefs.json",
        os.path.join(os.getcwd(), "mt-learner", "research", "briefs.json"),
    ]
    for path in paths:
        try:
            if not os.path.exists(path):
                continue
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
            briefs = data.get("briefs") if isinstance(data, dict) else []
            if isinstance(briefs, list):
                return [b for b in briefs if isinstance(b, dict)][:limit]
        except Exception as e:
            print(f"[research_evidence_ledger] learner briefs read error {path}: {e}", file=sys.stderr)
    return []


def _research_related_learner_briefs(item: dict, briefs: list[dict], limit: int = 3) -> list[dict]:
    target = str(item.get("target_strategy") or "").strip()
    tag = str(item.get("research_shadow_tag") or item.get("shadow_tag") or "").lower()
    tag_terms = [t for t in re.split(r"[_\W]+", tag.replace("research_", "")) if len(t) >= 4]
    related = []
    for brief in briefs:
        strategy = str(brief.get("strategy_key") or "")
        text = " ".join(str(brief.get(k) or "") for k in ("title", "thesis", "what_is_novel", "type")).lower()
        score = 0
        if target and strategy == target:
            score += 4
        score += sum(1 for term in tag_terms if term in text)
        if score <= 0:
            continue
        ev = brief.get("evidence") if isinstance(brief.get("evidence"), dict) else {}
        related.append((score, {
            "id": brief.get("id"),
            "title": brief.get("title"),
            "type": brief.get("type"),
            "strategy_key": strategy,
            "status": brief.get("status"),
            "confidence": brief.get("confidence"),
            "cluster_trades": ev.get("cluster_trades"),
            "cluster_avg_pnl": ev.get("cluster_avg_pnl"),
            "cluster_win_rate": ev.get("cluster_win_rate"),
        }))
    related.sort(key=lambda x: (x[0], x[1].get("cluster_trades") or 0), reverse=True)
    return [x[1] for x in related[:limit]]


def _research_evidence_stage(registered: bool, result: dict | None, readiness: dict) -> str:
    if result:
        status = str(result.get("status") or "")
        if status in {"promote_candidate", "reject_candidate", "needs_more_data", "collecting", "evaluator_pending"}:
            return status
    if registered:
        return "registered_shadow"
    if readiness.get("missing"):
        return "needs_mapping"
    if readiness.get("pre_entry") or readiness.get("partial") or readiness.get("retrospective"):
        return "mapped_prior"
    return "source_prior"


def _research_manual_stage(record: dict | None) -> str | None:
    """Return a user override stage stored in the experiment ledger, if any."""
    if not isinstance(record, dict):
        return None
    status = str(record.get("manual_status") or record.get("user_status") or "").strip().lower()
    allowed = {
        "manual_promoted",
        "manual_rejected",
        "manual_shadow",
        "manual_parked",
        "manual_collecting",
    }
    return status if status in allowed else None


def _research_paper_trials_by_tag(ledger: list[dict] | None = None) -> dict[str, dict]:
    """Return the latest paper-only applied trial record for each research tag."""
    ledger = ledger if isinstance(ledger, list) else _read_experiment_ledger()
    trials: dict[str, dict] = {}
    for record in ledger:
        if not isinstance(record, dict) or record.get("type") != "research_paper_trial":
            continue
        tag = str(record.get("research_shadow_tag") or record.get("shadow_tag") or "").strip()
        if not tag:
            continue
        prev = trials.get(tag)
        if not prev or str(record.get("started_at") or record.get("created_at") or "") >= str(prev.get("started_at") or prev.get("created_at") or ""):
            trials[tag] = record
    return trials


RESEARCH_RULE_MODES = {"off", "shadow", "paper_trial", "paper_applied", "live_candidate"}
RESEARCH_RULE_TYPES = {
    "strategy",
    "new_strategy",
    "entry_gate",
    "risk_gate",
    "regime_filter",
    "stop_rule",
    "sizing_rule",
    "exit_rule",
    "scoring_rule",
    "portfolio_rule",
    "execution_rule",
    "annotation",
    "data_collection",
}
RESEARCH_PAPER_RUNTIME_TAGS = {
    "research_funding_crowding_filter",
    "research_order_flow_confirmation",
}


def _research_rule_controls_by_tag(ledger: list[dict] | None = None) -> dict[str, dict]:
    """Return the latest user control record for each research-derived rule."""
    ledger = ledger if isinstance(ledger, list) else _read_experiment_ledger()
    controls: dict[str, dict] = {}
    for record in ledger:
        if not isinstance(record, dict) or record.get("type") != "research_rule_control":
            continue
        tag = str(record.get("research_shadow_tag") or record.get("shadow_tag") or "").strip()
        if not tag:
            continue
        prev = controls.get(tag)
        if not prev or str(record.get("updated_at") or record.get("created_at") or "") >= str(prev.get("updated_at") or prev.get("created_at") or ""):
            controls[tag] = record
    return controls


def _research_rule_type_guess(tag: str, candidate_type: str = "", fields: list[str] | None = None, readiness: dict | None = None) -> str:
    text = " ".join([tag or "", candidate_type or "", " ".join(fields or [])]).lower()
    if "sentiment" in text or "macro" in text or (readiness or {}).get("missing"):
        return "annotation"
    if "stop" in text or "trailing" in text or "breakeven" in text:
        return "stop_rule"
    if "regime" in text:
        return "regime_filter"
    if "volatility" in text or "atr" in text:
        return "risk_gate"
    if "funding" in text or "crowding" in text or "basis" in text:
        return "risk_gate"
    if "size" in text or "leverage" in text:
        return "sizing_rule"
    if "exit" in text or "take_profit" in text:
        return "exit_rule"
    if "score" in text or "conviction" in text or "rank" in text:
        return "scoring_rule"
    if "portfolio" in text or "correlation" in text or "allocation" in text:
        return "portfolio_rule"
    if "execution" in text or "slippage" in text or "fill" in text:
        return "execution_rule"
    if "strategy" in text and "filter" not in text:
        return "new_strategy"
    return "entry_gate"


def _research_rule_executability(tag: str, rule_type: str, item: dict) -> dict:
    readiness = item.get("field_readiness") if isinstance(item.get("field_readiness"), dict) else {}
    missing = readiness.get("missing") or []
    pre_entry = readiness.get("pre_entry") or []
    partial = readiness.get("partial") or []
    retrospective = readiness.get("retrospective") or []
    if rule_type in {"annotation", "data_collection"}:
        return {
            "status": "context_only",
            "label": "Context Only",
            "can_shadow": True,
            "can_paper_apply": False,
            "reason": "This item is useful as context or collection guidance, but is not an executable trade rule yet.",
        }
    if missing:
        return {
            "status": "blocked_missing_fields",
            "label": "Missing Fields",
            "can_shadow": True,
            "can_paper_apply": False,
            "reason": "Required live fields are missing; keep this in shadow or data collection.",
        }
    if retrospective and not pre_entry:
        return {
            "status": "retrospective_only",
            "label": "Retrospective",
            "can_shadow": True,
            "can_paper_apply": False,
            "reason": "The evidence relies on after-the-fact fields, so it cannot safely gate entries yet.",
        }
    if pre_entry or partial:
        wired_tags = RESEARCH_PAPER_RUNTIME_TAGS
        return {
            "status": "wired" if tag in wired_tags else "needs_rule_wiring",
            "label": "Wired" if tag in wired_tags else "Needs Wiring",
            "can_shadow": True,
            "can_paper_apply": tag in wired_tags,
            "reason": (
                "This item has a known paper-applied implementation path."
                if tag in wired_tags
                else "Live-time fields exist, but the specific paper rule still needs an implementation hook."
            ),
        }
    return {
        "status": "needs_mapping",
        "label": "Needs Mapping",
        "can_shadow": True,
        "can_paper_apply": False,
        "reason": "Map the fields and rule shape before applying this to paper trades.",
    }


def _research_rule_control_for_item(item: dict, controls_by_tag: dict[str, dict] | None = None) -> dict:
    tag = str(item.get("research_shadow_tag") or item.get("shadow_tag") or "").strip()
    controls_by_tag = controls_by_tag or {}
    control = controls_by_tag.get(tag) or {}
    rule_type = str(control.get("rule_type") or "").strip().lower()
    if rule_type not in RESEARCH_RULE_TYPES:
        rule_type = _research_rule_type_guess(
            tag,
            str(item.get("candidate_type") or ""),
            item.get("fields") or [],
            item.get("field_readiness") or {},
        )
    default_mode = "paper_trial" if item.get("paper_trial") else "shadow" if item.get("registered") else "off"
    mode = str(control.get("mode") or default_mode).strip().lower()
    if mode not in RESEARCH_RULE_MODES:
        mode = default_mode
    executable = _research_rule_executability(tag, rule_type, item)
    if mode == "paper_applied" and not executable.get("can_paper_apply"):
        mode = "paper_trial" if item.get("paper_trial") else "shadow"
    if mode == "live_candidate" and not executable.get("can_paper_apply"):
        mode = "paper_trial" if item.get("paper_trial") else "shadow"
    changed_paper_behavior = mode == "paper_applied" and tag in RESEARCH_PAPER_RUNTIME_TAGS
    return {
        "mode": mode,
        "rule_type": rule_type,
        "scope": control.get("scope") or item.get("target_strategy") or "portfolio",
        "updated_at": control.get("updated_at"),
        "updated_by": control.get("updated_by"),
        "reason": control.get("reason"),
        "executable": executable,
        "changed_scoring": False,
        "changed_live_behavior": False,
        "changed_paper_behavior": changed_paper_behavior,
        "paper_effect": "active_runtime_hook" if changed_paper_behavior else "none",
    }


def _research_rule_scope_matches(control: dict, sig: dict) -> bool:
    scope = str(control.get("scope") or "portfolio").strip().lower()
    if scope in {"", "all", "all_strategies", "portfolio"}:
        return True
    strategy_key = str(sig.get("_strategy_key") or sig.get("strategy_key") or "").strip().lower()
    return scope == strategy_key


def _research_paper_control_active(
    controls_by_tag: dict[str, dict],
    tag: str,
    sig: dict | None = None,
) -> bool:
    control = controls_by_tag.get(tag) or {}
    if control.get("mode") != "paper_applied":
        return False
    if tag not in RESEARCH_PAPER_RUNTIME_TAGS:
        return False
    if sig is not None and not _research_rule_scope_matches(control, sig):
        return False
    return True


def _apply_research_paper_rules(
    sig: dict,
    cfg: dict,
    flow_result: dict | None = None,
    liquidation: dict | None = None,
    controls_by_tag: dict[str, dict] | None = None,
) -> dict:
    """Apply paper-only research runtime hooks without affecting live trading."""
    result = {
        "allowed": True,
        "blocked_by": [],
        "annotations": [],
        "size_multiplier": 1.0,
        "controls_applied": [],
        "experiment_assignments": [],
    }
    try:
        controls_by_tag = controls_by_tag if isinstance(controls_by_tag, dict) else _research_rule_controls_by_tag()
        strategy_key = str(sig.get("_strategy_key") or sig.get("strategy_key") or "balanced")
        assignments = _research_assignments_for_signal(sig)
        assignment_by_tag = {
            str(item.get("source_id") or ""): item
            for item in assignments
            if item.get("source_id")
        }
        result["experiment_assignments"] = assignments

        def treatment_enabled(tag: str) -> bool:
            assignment = assignment_by_tag.get(tag)
            if assignment:
                result["annotations"].append(
                    f"research_experiment_{assignment['arm']}_{tag}"
                )
                return assignment.get("arm") == "treatment"
            # Backward compatibility for a legacy Paper Applied control. New
            # orchestrated controls always have an assignment.
            result["annotations"].append(f"research_experiment_unattributed_{tag}")
            return True

        if (
            _research_paper_control_active(
                controls_by_tag, "research_order_flow_confirmation", sig
            )
            and treatment_enabled("research_order_flow_confirmation")
        ):
            score = _research_float((flow_result or {}).get("score"), 0.0)
            confirmed = bool((flow_result or {}).get("confirmed"))
            result["controls_applied"].append("research_order_flow_confirmation")
            result["annotations"].append("research_order_flow_confirmation_checked")
            if not confirmed:
                result["allowed"] = False
                result["blocked_by"].append({
                    "tag": "research_order_flow_confirmation",
                    "reason": f"flow not confirmed for paper-applied rule; score={score:.0f}",
                })

        if (
            _research_paper_control_active(
                controls_by_tag, "research_funding_crowding_filter", sig
            )
            and treatment_enabled("research_funding_crowding_filter")
        ):
            row = dict(sig)
            if flow_result is not None:
                row["flow_confirmed"] = bool(flow_result.get("confirmed"))
                row["flow_score"] = flow_result.get("score")
            bucket = _research_funding_bucket(row)
            result["controls_applied"].append("research_funding_crowding_filter")
            result["annotations"].append(f"research_funding_bucket_{bucket}")
            if bucket in {"negative_funding_long_trap", "positive_funding_short_trap"}:
                result["allowed"] = False
                result["blocked_by"].append({
                    "tag": "research_funding_crowding_filter",
                    "reason": f"funding crowding trap bucket: {bucket}",
                })

        if result["blocked_by"]:
            blocked_tags_set = {
                str(item.get("tag") or "") for item in result["blocked_by"]
            }
            for assignment in result["experiment_assignments"]:
                if str(assignment.get("source_id") or "") in blocked_tags_set:
                    assignment["decision"] = "blocked"
                else:
                    assignment["decision"] = "contaminated"
            blocked_tags = [b["tag"] for b in result["blocked_by"]]
            reasons = [b["reason"] for b in result["blocked_by"]]
            log_filtered_candidate({
                **sig,
                "strategy_key": strategy_key,
                "gate_key": "research_paper_runtime",
                "gate_mode": "paper_applied",
                "tags": list(dict.fromkeys(list(sig.get("tags") or []) + blocked_tags)),
                "reason": "; ".join(reasons),
                "research_runtime": result,
                "flow_result": flow_result,
                "liquidation": liquidation,
            })
        else:
            for assignment in result["experiment_assignments"]:
                assignment["decision"] = "accepted"
    except Exception as e:
        print(f"[research_paper_runtime] error: {e}", file=sys.stderr)
        result["allowed"] = True
        result["annotations"].append("research_runtime_error_allowed")
    return result


def _research_evidence_ledger_payload(
    sources: list[dict] | None = None,
    reviews: list[dict] | None = None,
    priority_queue: list[dict] | None = None,
    strategy_candidates: list[dict] | None = None,
    shadow_results: dict | None = None,
) -> dict:
    """Shared Hermes/mt-learner research lifecycle ledger.

    This is the read-only bridge between source priors, registered shadow
    experiments, deterministic outcome tests, and mt-learner's empirical briefs.
    It never mutates scoring, paper config, risk gates, sizing, or execution.
    """
    sources = sources if sources is not None else _research_load_sources()
    reviews = reviews if reviews is not None else _cipher_review_research_hypotheses(sources)
    ledger = _read_experiment_ledger()
    priority_queue = priority_queue if priority_queue is not None else _research_priority_queue(reviews, ledger, sources)
    strategy_candidates = strategy_candidates if strategy_candidates is not None else _research_strategy_candidates(priority_queue)
    shadow_results = shadow_results if shadow_results is not None else _research_shadow_results_payload()
    learner_briefs = _research_read_learner_briefs()
    paper_trials_by_tag = _research_paper_trials_by_tag(ledger)
    rule_controls_by_tag = _research_rule_controls_by_tag(ledger)

    source_by_id = {str(s.get("id") or ""): s for s in sources if isinstance(s, dict)}
    reviews_by_tag: dict[str, list[dict]] = defaultdict(list)
    for review in reviews:
        tag = str(review.get("shadow_tag") or review.get("id") or "")
        if tag:
            reviews_by_tag[tag].append(review)
    priority_by_tag = {
        str(p.get("shadow_tag") or p.get("id") or ""): p
        for p in priority_queue
        if isinstance(p, dict) and (p.get("shadow_tag") or p.get("id"))
    }
    candidate_by_tag = {
        str(c.get("research_shadow_tag") or c.get("shadow_tag") or ""): c
        for c in strategy_candidates
        if isinstance(c, dict) and (c.get("research_shadow_tag") or c.get("shadow_tag"))
    }
    result_by_tag = {
        str(r.get("research_shadow_tag") or ""): r
        for r in (shadow_results.get("results") or [])
        if isinstance(r, dict) and r.get("research_shadow_tag")
    }
    registered_by_tag = {}
    for record in ledger:
        if not isinstance(record, dict) or record.get("source") not in {"hermes_research_pipeline", "hermes_research_strategy_candidate"}:
            continue
        tag = str(record.get("research_shadow_tag") or record.get("shadow_tag") or "")
        if tag and tag not in registered_by_tag:
            registered_by_tag[tag] = record

    tags = sorted(set(reviews_by_tag) | set(priority_by_tag) | set(candidate_by_tag) | set(result_by_tag) | set(registered_by_tag))
    items = []
    stage_counts: dict[str, int] = defaultdict(int)
    for tag in tags:
        priority = priority_by_tag.get(tag) or {}
        candidate = candidate_by_tag.get(tag) or {}
        result = result_by_tag.get(tag)
        registered = registered_by_tag.get(tag)
        paper_trial = paper_trials_by_tag.get(tag)
        matched_reviews = reviews_by_tag.get(tag) or []
        source_ids = []
        for review in matched_reviews:
            sid = str(review.get("source_id") or "")
            if sid and sid not in source_ids:
                source_ids.append(sid)
        for sid in priority.get("source_ids") or []:
            sid = str(sid)
            if sid and sid not in source_ids:
                source_ids.append(sid)

        source_status_counts: dict[str, int] = defaultdict(int)
        quality_scores = []
        relevance_scores = []
        source_titles = []
        for sid in source_ids:
            source = source_by_id.get(sid) or {}
            if source.get("title"):
                source_titles.append(source.get("title"))
            source_status_counts[str(source.get("full_text_status") or "unknown")] += 1
            if source.get("quality_score") is not None:
                quality_scores.append(float(source.get("quality_score") or 0))
            if source.get("relevance_score") is not None:
                relevance_scores.append(float(source.get("relevance_score") or 0))

        fields = []
        for bucket in (
            candidate.get("fields_needed"),
            priority.get("available_fields"),
            priority.get("partial_fields"),
            priority.get("missing_fields"),
            registered.get("mt7_fields_needed") if isinstance(registered, dict) else [],
        ):
            for field in bucket or []:
                field = str(field)
                if field and field not in fields:
                    fields.append(field)
        readiness = _research_field_readiness(fields)
        if candidate.get("missing_fields"):
            for field in candidate.get("missing_fields") or []:
                field = str(field)
                if field and field not in readiness["missing"]:
                    readiness["missing"].append(field)

        manual_stage = _research_manual_stage(registered)
        stage = manual_stage or _research_evidence_stage(bool(registered), result, readiness)
        stage_counts[stage] += 1
        matched = (result or {}).get("matched") or {}
        comparison = (result or {}).get("comparison") or {}
        progress = (result or {}).get("promotion_progress") or {}
        evidence_stats = priority.get("evidence_stats") or {}
        if not evidence_stats and matched_reviews:
            claims = []
            for sid in source_ids:
                source = source_by_id.get(sid)
                if source:
                    claims.extend(_research_claims_from_source(source, limit=3))
            evidence_stats = _research_claim_stats(claims)

        item = {
            "research_shadow_tag": tag,
            "title": candidate.get("title") or priority.get("shadow_tag") or tag,
            "thesis": candidate.get("thesis") or priority.get("thesis") or (registered or {}).get("hypothesis"),
            "expected_edge": candidate.get("expected_edge") or priority.get("expected_edge"),
            "strategy_shape": candidate.get("strategy_shape"),
            "entry_filter_rule": candidate.get("entry_filter_rule"),
            "reject_filter_rule": candidate.get("reject_filter_rule"),
            "cohort_definition": candidate.get("cohort_definition"),
            "expected_failure_mode": candidate.get("expected_failure_mode"),
            "known_caveats": candidate.get("known_caveats") or [],
            "gate_impact": priority.get("gate_impact"),
            "overfitting_risk": priority.get("overfitting_risk"),
            "stage": stage,
            "target_strategy": candidate.get("target_strategy") or priority.get("target_strategy") or (registered or {}).get("target_strategy"),
            "candidate_type": candidate.get("candidate_type") or (registered or {}).get("candidate_type") or "shadow_filter",
            "source_count": len(source_ids),
            "source_ids": source_ids[:12],
            "source_titles": source_titles[:5],
            "source_status_counts": dict(source_status_counts),
            "avg_source_quality": round(sum(quality_scores) / len(quality_scores), 3) if quality_scores else None,
            "avg_source_relevance": round(sum(relevance_scores) / len(relevance_scores), 3) if relevance_scores else None,
            "evidence_stats": evidence_stats,
            "priority_score": priority.get("priority_score"),
            "testability_score": priority.get("testability_score"),
            "registered": bool(registered),
            "registration_id": (registered or {}).get("id"),
            "registered_at": (registered or {}).get("created_at"),
            "manual_status": (registered or {}).get("manual_status"),
            "manual_reason": (registered or {}).get("manual_reason"),
            "manual_updated_at": (registered or {}).get("manual_updated_at"),
            "manual_updated_by": (registered or {}).get("manual_updated_by"),
            "manual_history": (registered or {}).get("manual_history") or [],
            "paper_trial": {
                "id": paper_trial.get("id"),
                "status": paper_trial.get("status") or "active",
                "started_at": paper_trial.get("started_at") or paper_trial.get("created_at"),
                "reason": paper_trial.get("reason"),
                "paper_only": True,
                "changed_scoring": False,
                "changed_live_behavior": False,
                "next_action": paper_trial.get("next_action") or "Collect forward paper outcomes, then decide keep/revert/escalate.",
            } if isinstance(paper_trial, dict) else None,
            "fields": fields[:12],
            "partial_fields": list(priority.get("partial_fields") or [])[:12],
            "missing_fields": list(readiness.get("missing") or [])[:12],
            "field_readiness": readiness,
            "pre_entry_ready": bool(readiness["pre_entry"]) and not readiness["missing"],
            "retrospective_only_risk": bool(readiness["retrospective"]) and not readiness["pre_entry"],
            "matched": matched,
            "comparison": comparison,
            "promotion_progress": progress,
            "outcome_status": (result or {}).get("status"),
            "verdict_reason": (result or {}).get("verdict_reason"),
            "evaluator": (result or {}).get("evaluator"),
            "related_learner_briefs": _research_related_learner_briefs(
                {
                    "target_strategy": candidate.get("target_strategy") or priority.get("target_strategy"),
                    "research_shadow_tag": tag,
                },
                learner_briefs,
            ),
            "next_action": priority.get("next_action") or (
                "Monitor deterministic shadow outcome test." if result else
                "Register as measurement-only shadow experiment." if not registered and not readiness["missing"] else
                "Map missing fields before registration."
            ),
            "promotion_criteria": candidate.get("promotion_criteria") or priority.get("promotion_criteria") or (registered or {}).get("promotion_criteria"),
            "rollback_condition": candidate.get("rollback_criteria") or priority.get("rollback_condition") or (registered or {}).get("rollback_condition"),
            "can_change_live_behavior": False,
            "measurement_only": True,
        }
        item["rule_control"] = _research_rule_control_for_item(item, rule_controls_by_tag)
        items.append(item)

    stage_rank = {
        "promote_candidate": 8,
        "reject_candidate": 7,
        "needs_more_data": 6,
        "collecting": 5,
        "manual_promoted": 5,
        "manual_rejected": 5,
        "manual_shadow": 5,
        "manual_collecting": 5,
        "manual_parked": 4,
        "registered_shadow": 4,
        "mapped_prior": 3,
        "needs_mapping": 2,
        "source_prior": 1,
        "evaluator_pending": 0,
    }
    items.sort(
        key=lambda x: (
            stage_rank.get(str(x.get("stage")), 0),
            int((x.get("promotion_progress") or {}).get("closed") or (x.get("matched") or {}).get("count") or 0),
            int(x.get("priority_score") or 0),
        ),
        reverse=True,
    )
    blindspots = [
        "Corpus indexing is not automatic; new local files need an index run before they enter this ledger.",
        "Retrospective journey fields can validate stop quality, but cannot become pre-entry gates without live-time equivalents.",
        "Promotion samples need symbol, regime, direction, fee/slippage, and false-negative checks; count alone is not proof.",
        "mt-learner briefs are linked heuristically by strategy/topic until every learner suggestion emits a research_shadow_tag.",
    ]
    return {
        "success": True,
        "generated_at": _research_now(),
        "summary": {
            "item_count": len(items),
            "stage_counts": dict(stage_counts),
            "registered_count": sum(1 for x in items if x.get("registered")),
            "pre_entry_ready_count": sum(1 for x in items if x.get("pre_entry_ready")),
            "retrospective_only_count": sum(1 for x in items if x.get("retrospective_only_risk")),
            "paper_trial_count": sum(1 for x in items if x.get("paper_trial")),
            "paper_applied_rule_count": sum(1 for x in items if (x.get("rule_control") or {}).get("mode") == "paper_applied"),
            "live_candidate_rule_count": sum(1 for x in items if (x.get("rule_control") or {}).get("mode") == "live_candidate"),
            "learner_brief_count": len(learner_briefs),
        },
        "items": items,
        "blindspots": blindspots,
        "rules": [
            "Evidence ledger is read-only.",
            "External priors must become shadow experiments before any paper or live impact.",
            "No item in this ledger can change scoring, gates, sizing, paper config, or execution by itself.",
        ],
    }


def _research_find_candidate_for_tag(shadow_tag: str) -> dict:
    tag = str(shadow_tag or "").strip()
    sources = _research_load_sources()
    reviews = _cipher_review_research_hypotheses(sources)
    ledger = _read_experiment_ledger()
    queue = _research_priority_queue(reviews, ledger, sources)
    candidates = _research_strategy_candidates(queue)
    candidate = next(
        (c for c in candidates if str(c.get("research_shadow_tag") or c.get("shadow_tag") or "") == tag),
        {},
    )
    concept = next(
        (q for q in queue if str(q.get("shadow_tag") or q.get("id") or "") == tag),
        {},
    )
    return {"candidate": candidate, "concept": concept}


def _research_ensure_manual_record(shadow_tag: str, action: str) -> tuple[list[dict], dict]:
    tag = str(shadow_tag or "").strip()
    if not re.match(r"^[a-zA-Z0-9_:-]{3,100}$", tag):
        raise ValueError("Invalid research shadow tag")
    ledger = _read_experiment_ledger()
    for record in ledger:
        if (
            isinstance(record, dict)
            and record.get("source") in {"hermes_research_pipeline", "hermes_research_strategy_candidate", "hermes_research_manual_lifecycle"}
            and str(record.get("research_shadow_tag") or record.get("shadow_tag") or "") == tag
        ):
            return ledger, record

    context = _research_find_candidate_for_tag(tag)
    candidate = context.get("candidate") or {}
    concept = context.get("concept") or {}
    record = {
        "id": f"research_manual_{tag}",
        "created_at": _research_now(),
        "source": "hermes_research_manual_lifecycle",
        "status": "shadow_proposed",
        "candidate_title": candidate.get("title") or tag.replace("_", " ").title(),
        "candidate_type": candidate.get("candidate_type") or "shadow_filter",
        "research_shadow_tag": tag,
        "shadow_tag": tag,
        "target_strategy": candidate.get("target_strategy") or concept.get("target_strategy"),
        "hypothesis": candidate.get("thesis") or concept.get("thesis"),
        "mt7_fields_needed": candidate.get("fields_needed") or concept.get("available_fields") or [],
        "promotion_criteria": candidate.get("promotion_criteria") or concept.get("promotion_criteria"),
        "rollback_condition": candidate.get("rollback_criteria") or concept.get("rollback_condition"),
        "can_change_live_behavior": False,
        "measurement_only": True,
        "notes": [
            "Created by manual research lifecycle action.",
            "Does not change scanner scoring, risk gates, paper config, sizing, or execution.",
        ],
    }
    ledger.append(record)
    return ledger, record


def _research_write_experiment_ledger(ledger: list[dict]) -> None:
    os.makedirs("data", exist_ok=True)
    tmp = EXPERIMENT_LEDGER_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(ledger, f, indent=2, sort_keys=True)
    os.replace(tmp, EXPERIMENT_LEDGER_PATH)


def _research_evidence_ledger_action(shadow_tag: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    action = str(payload.get("action") or "").strip().lower()
    if action not in {"shadow", "promote", "reject", "park", "collect"}:
        raise ValueError("action must be shadow, promote, reject, park, or collect")
    reason = str(payload.get("reason") or "").strip()[:700]
    actor = str(payload.get("actor") or "local_user").strip()[:80] or "local_user"

    if action == "shadow":
        registration = _research_register_strategy_candidate(shadow_tag)
        if not registration.get("success"):
            return registration
        ledger, record = _research_ensure_manual_record(shadow_tag, action)
    else:
        ledger, record = _research_ensure_manual_record(shadow_tag, action)

    manual_status = {
        "shadow": "manual_shadow",
        "promote": "manual_promoted",
        "reject": "manual_rejected",
        "park": "manual_parked",
        "collect": "manual_collecting",
    }[action]
    now = _research_now()
    history = record.get("manual_history") if isinstance(record.get("manual_history"), list) else []
    history.append({
        "at": now,
        "action": action,
        "manual_status": manual_status,
        "reason": reason,
        "actor": actor,
    })
    record["manual_status"] = manual_status
    record["manual_action"] = action
    record["manual_reason"] = reason
    record["manual_updated_at"] = now
    record["manual_updated_by"] = actor
    record["manual_history"] = history[-20:]
    record["status"] = "shadow_proposed" if action in {"shadow", "collect"} else manual_status
    record["can_change_live_behavior"] = False
    record["measurement_only"] = True
    _research_write_experiment_ledger(ledger)
    return {
        "success": True,
        "action": action,
        "manual_status": manual_status,
        "record": record,
        "pipeline": _hermes_research_pipeline_summary(),
    }


def _research_start_paper_trial(shadow_tag: str, payload: dict | None = None) -> dict:
    """Start a governed paper-only trial for a promoted research item.

    This is intentionally not an execution hook. It records the handoff from
    research promotion to forward paper monitoring and leaves scoring, sizing,
    live behavior, and paper config unchanged until a concrete executable rule
    is implemented and separately approved.
    """
    payload = payload if isinstance(payload, dict) else {}
    tag = str(shadow_tag or "").strip()
    if not re.match(r"^[a-zA-Z0-9_:-]{3,100}$", tag):
        raise ValueError("Invalid research shadow tag")

    reason = str(payload.get("reason") or "").strip()[:700]
    actor = str(payload.get("actor") or "local_user").strip()[:80] or "local_user"
    ledger, record = _research_ensure_manual_record(tag, "paper_trial")
    result = next(
        (
            r for r in (_research_shadow_results_payload().get("results") or [])
            if isinstance(r, dict) and str(r.get("research_shadow_tag") or "") == tag
        ),
        {},
    )
    manual_status = str(record.get("manual_status") or "").lower()
    status = str(result.get("status") or record.get("status") or "").lower()
    if manual_status != "manual_promoted" and status != "promote_candidate":
        raise ValueError("Research item must be manually promoted or promote-ready before starting a paper trial")

    existing = next(
        (
            r for r in ledger
            if isinstance(r, dict)
            and r.get("type") == "research_paper_trial"
            and str(r.get("research_shadow_tag") or r.get("shadow_tag") or "") == tag
            and str(r.get("status") or "active").lower() in {"active", "collecting", "paper_trial_active"}
        ),
        None,
    )
    if existing:
        return {
            "success": True,
            "created": False,
            "trial": existing,
            "pipeline": _hermes_research_pipeline_summary(),
        }

    now = _research_now()
    trial = {
        "id": f"research_paper_trial_{tag}_{now}",
        "type": "research_paper_trial",
        "source": "hermes_research_pipeline",
        "research_shadow_tag": tag,
        "shadow_tag": tag,
        "target_strategy": record.get("target_strategy"),
        "candidate_title": record.get("candidate_title") or tag.replace("_", " ").title(),
        "candidate_type": record.get("candidate_type") or "shadow_filter",
        "status": "active",
        "started_at": now,
        "created_at": now,
        "reason": reason,
        "actor": actor,
        "paper_only": True,
        "changed_scoring": False,
        "changed_paper_config": False,
        "changed_live_behavior": False,
        "changed_sizing": False,
        "changed_execution": False,
        "baseline_shadow_result": result,
        "promotion_criteria": record.get("promotion_criteria") or (result or {}).get("promotion_criteria"),
        "rollback_condition": record.get("rollback_condition") or (result or {}).get("rollback_condition"),
        "target_closed_paper_outcomes": int(payload.get("target_closed_paper_outcomes") or 20),
        "next_action": "Collect forward paper outcomes under observation; do not escalate until criteria are met.",
        "notes": [
            "Paper-trial marker only; no scanner scoring, gates, sizing, paper config, or execution changed.",
            "Use this to track promoted research through a forward paper validation window.",
        ],
    }
    ledger.append(trial)
    history = record.get("manual_history") if isinstance(record.get("manual_history"), list) else []
    history.append({
        "at": now,
        "action": "start_paper_trial",
        "manual_status": "manual_promoted",
        "reason": reason,
        "actor": actor,
        "trial_id": trial["id"],
    })
    record["manual_history"] = history[-20:]
    record["paper_trial_status"] = "active"
    record["paper_trial_started_at"] = now
    record["paper_trial_id"] = trial["id"]
    record["manual_updated_at"] = now
    record["manual_updated_by"] = actor
    _research_write_experiment_ledger(ledger)
    return {
        "success": True,
        "created": True,
        "trial": trial,
        "pipeline": _hermes_research_pipeline_summary(),
    }


def _research_rulebook_payload() -> dict:
    ledger_payload = _research_evidence_ledger_payload()
    items = []
    for item in ledger_payload.get("items") or []:
        control = item.get("rule_control") or {}
        items.append({
            "research_shadow_tag": item.get("research_shadow_tag"),
            "title": item.get("title"),
            "target_strategy": item.get("target_strategy"),
            "stage": item.get("stage"),
            "manual_status": item.get("manual_status"),
            "outcome_status": item.get("outcome_status"),
            "paper_trial": item.get("paper_trial"),
            "matched": item.get("matched"),
            "comparison": item.get("comparison"),
            "promotion_progress": item.get("promotion_progress"),
            "field_readiness": item.get("field_readiness"),
            "pre_entry_ready": item.get("pre_entry_ready"),
            "retrospective_only_risk": item.get("retrospective_only_risk"),
            "rule_control": control,
            "next_action": (
                "Paper runtime hook is active for paper trades."
                if control.get("mode") == "paper_applied" and control.get("paper_effect") == "active_runtime_hook"
                else (control.get("executable") or {}).get("reason") or item.get("next_action")
            ),
            "safety": {
                "can_change_scoring_now": False,
                "can_change_live_now": False,
                "can_change_paper_now": False,
                "requires_final_live_approval": True,
            },
        })
    summary = {
        "item_count": len(items),
        "off": len([x for x in items if (x.get("rule_control") or {}).get("mode") == "off"]),
        "shadow": len([x for x in items if (x.get("rule_control") or {}).get("mode") == "shadow"]),
        "paper_trial": len([x for x in items if (x.get("rule_control") or {}).get("mode") == "paper_trial"]),
        "paper_applied": len([x for x in items if (x.get("rule_control") or {}).get("mode") == "paper_applied"]),
        "live_candidate": len([x for x in items if (x.get("rule_control") or {}).get("mode") == "live_candidate"]),
        "paper_behavior_active": len([
            x for x in items
            if (x.get("rule_control") or {}).get("paper_effect") == "active_runtime_hook"
        ]),
        "live_behavior_active": 0,
    }
    return {
        "success": True,
        "generated_at": _research_now(),
        "summary": summary,
        "items": items,
        "modes": [
            {"id": "off", "label": "Off", "impact": "stored only"},
            {"id": "shadow", "label": "Shadow", "impact": "measure would-have impact only"},
            {"id": "paper_trial", "label": "Paper Trial", "impact": "forward validation marker"},
            {"id": "paper_applied", "label": "Paper Applied", "impact": "armed for paper runtime hook; no live impact"},
            {"id": "live_candidate", "label": "Live Candidate", "impact": "review queue only; live remains disabled"},
        ],
        "rule_types": sorted(RESEARCH_RULE_TYPES),
        "rules": [
            "Research Rulebook controls research-derived rules, gates, sizing ideas, exit ideas, and annotations.",
            "Mode changes are governance records unless a paper runtime hook exists for the rule.",
            "Live Enabled is intentionally unavailable in this phase.",
        ],
    }


def _research_rule_ev_delta(item: dict) -> float | None:
    matched = item.get("matched") if isinstance(item.get("matched"), dict) else {}
    comparison = item.get("comparison") if isinstance(item.get("comparison"), dict) else {}
    if matched.get("avg_pnl_pct") is None or comparison.get("avg_pnl_pct") is None:
        return None
    try:
        return round(float(matched.get("avg_pnl_pct") or 0.0) - float(comparison.get("avg_pnl_pct") or 0.0), 2)
    except Exception:
        return None


def _research_rule_impact_preview(item: dict) -> dict:
    """Compact impact preview for a research-derived rule before promotion."""
    control = item.get("rule_control") if isinstance(item.get("rule_control"), dict) else {}
    executable = control.get("executable") if isinstance(control.get("executable"), dict) else {}
    matched = item.get("matched") if isinstance(item.get("matched"), dict) else {}
    comparison = item.get("comparison") if isinstance(item.get("comparison"), dict) else {}
    progress = item.get("promotion_progress") if isinstance(item.get("promotion_progress"), dict) else {}
    readiness = item.get("field_readiness") if isinstance(item.get("field_readiness"), dict) else {}
    mode = str(control.get("mode") or "off")
    paper_effect = str(control.get("paper_effect") or "none")
    ev_delta = _research_rule_ev_delta(item)
    matched_count = int(matched.get("count") or matched.get("closed_count") or 0)
    comparison_count = int(comparison.get("count") or comparison.get("closed_count") or 0)
    target = int(progress.get("target") or 50)
    closed = int(progress.get("closed") or matched_count or 0)
    if paper_effect == "active_runtime_hook":
        behavior_read = "Active for paper only; it can block simulated paper candidates and cannot affect live execution."
    elif mode == "paper_applied":
        behavior_read = "Approved as paper-applied governance, but no runtime hook is active for this rule."
    elif mode == "paper_trial":
        behavior_read = "Forward paper validation marker only; no scoring, sizing, gates, or execution change."
    elif mode == "live_candidate":
        behavior_read = "Live review queue only; final live approval and execution gates are still required."
    elif mode == "shadow":
        behavior_read = "Shadow measurement only; no behavior change."
    else:
        behavior_read = "Stored as a research idea; no active measurement or trading behavior."

    return {
        "matched": matched,
        "comparison": comparison,
        "ev_delta_pct": ev_delta,
        "matched_count": matched_count,
        "comparison_count": comparison_count,
        "sample_progress_pct": round(min(1.0, closed / max(1, target)) * 100, 1),
        "target_closed": target,
        "closed": closed,
        "pre_entry_fields": readiness.get("pre_entry") or [],
        "partial_fields": readiness.get("partial") or [],
        "retrospective_fields": readiness.get("retrospective") or [],
        "missing_fields": readiness.get("missing") or [],
        "executable_status": executable.get("status"),
        "executable_label": executable.get("label"),
        "executable_reason": executable.get("reason"),
        "needs_wiring": executable.get("status") == "needs_rule_wiring",
        "can_paper_apply": bool(executable.get("can_paper_apply")),
        "paper_effect": paper_effect,
        "behavior_read": behavior_read,
        "affected_profile_ids": (
            ["paper_active"] if paper_effect == "active_runtime_hook" else
            ["research_shadow", "paper_active"] if mode in {"paper_trial", "paper_applied"} else
            ["live_candidate"] if mode == "live_candidate" else
            ["research_shadow"] if mode == "shadow" else
            []
        ),
    }


def _research_approval_ledger(limit: int = 14, ledger: list[dict] | None = None) -> list[dict]:
    ledger = ledger if isinstance(ledger, list) else _read_experiment_ledger()
    relevant = []
    for record in ledger:
        if not isinstance(record, dict):
            continue
        r_type = str(record.get("type") or "")
        source = str(record.get("source") or "")
        tag = str(record.get("research_shadow_tag") or record.get("shadow_tag") or record.get("strategy") or "").strip()
        if not tag:
            continue
        is_research = (
            source in {"research_rulebook", "hermes_research_pipeline", "hermes_research_manual_lifecycle", "hermes_research_strategy_candidate"}
            or r_type in {"research_rule_control", "research_paper_trial", "disabled_strategy_recovery_action"}
            or bool(record.get("manual_action") or record.get("manual_status"))
        )
        if not is_research:
            continue
        action = (
            record.get("action")
            or record.get("manual_action")
            or record.get("mode")
            or record.get("status")
            or r_type
            or source
        )
        created_at = (
            record.get("updated_at")
            or record.get("manual_updated_at")
            or record.get("started_at")
            or record.get("decided_at")
            or record.get("created_at")
            or ""
        )
        changed_paper = bool(record.get("changed_paper_behavior") or record.get("changed_paper_config"))
        relevant.append({
            "id": record.get("id"),
            "created_at": created_at,
            "type": r_type or source,
            "source": source,
            "shadow_tag": tag,
            "title": record.get("candidate_title") or record.get("title") or tag.replace("_", " ").title(),
            "action": action,
            "mode": record.get("mode"),
            "rule_type": record.get("rule_type"),
            "reason": record.get("reason") or record.get("manual_reason"),
            "actor": record.get("actor") or record.get("updated_by") or record.get("manual_updated_by"),
            "changed_paper_behavior": changed_paper,
            "changed_live_behavior": bool(record.get("changed_live_behavior") or record.get("changed_live_config")),
            "paper_only": bool(record.get("paper_only")),
        })
    relevant.sort(key=lambda r: str(r.get("created_at") or ""), reverse=True)
    return relevant[:limit]


def _strategy_profile_registry_payload(lookback_days: int = 30, alignment: dict | None = None, rulebook: dict | None = None) -> dict:
    """Canonical view of which strategy profile owns Paper, History, Research, and Live-readiness evidence."""
    cfg = _load_paper_config()
    registry = get_strategy_registry(include_disabled=True)
    alignment = alignment if isinstance(alignment, dict) else _execution_policy_alignment_payload(lookback_days=lookback_days)
    rulebook = rulebook if isinstance(rulebook, dict) else _research_rulebook_payload()
    summary = alignment.get("summary") or {}
    rule_summary = rulebook.get("summary") or {}
    disabled = {str(k) for k in (cfg.get("disabled_strategies") or []) if str(k).strip()}
    enabled = sorted([k for k in registry.keys() if k not in disabled])
    active_rules = [
        x for x in (rulebook.get("items") or [])
        if ((x.get("rule_control") or {}).get("paper_effect") == "active_runtime_hook")
    ]
    paper_trial_rules = [
        x for x in (rulebook.get("items") or [])
        if ((x.get("rule_control") or {}).get("mode") == "paper_trial")
    ]
    live_candidates = [
        x for x in (rulebook.get("items") or [])
        if ((x.get("rule_control") or {}).get("mode") == "live_candidate")
    ]
    profiles = [
        {
            "id": "research_shadow",
            "label": "Research Baseline",
            "mode": "advisory_shadow",
            "authority": "Corpus, Hermes, Corpus Scholar, and shadow evaluators can create ideas and measurements only.",
            "can_queue_paper": False,
            "can_change_live": False,
            "enabled_strategy_count": len(enabled),
            "research_item_count": int(rule_summary.get("item_count") or 0),
            "paper_trial_count": int(rule_summary.get("paper_trial") or 0),
            "paper_applied_count": int(rule_summary.get("paper_applied") or 0),
            "live_candidate_count": int(rule_summary.get("live_candidate") or 0),
            "evidence": {
                "registered": int(rule_summary.get("item_count") or 0),
                "active_runtime_hooks": int(rule_summary.get("paper_behavior_active") or 0),
            },
        },
        {
            "id": "paper_active",
            "label": "Paper Active",
            "mode": "simulated_execution_policy",
            "authority": "This is the blueprint for assisted live when the gates clear.",
            "can_queue_paper": bool(cfg.get("enabled")),
            "can_change_live": False,
            "enabled_strategies": enabled,
            "disabled_strategies": sorted(disabled),
            "enabled_strategy_count": len(enabled),
            "disabled_strategy_count": len(disabled),
            "flow_required": bool(cfg.get("flow_required")),
            "min_conviction": cfg.get("min_conviction"),
            "risk_pct_per_trade": cfg.get("risk_pct_per_trade"),
            "max_open_positions": cfg.get("max_open_positions"),
            "current_cohort_label": cfg.get("current_cohort_label"),
            "current_cohort_started_at": cfg.get("current_cohort_started_at"),
            "research_runtime_hooks": [
                {
                    "research_shadow_tag": x.get("research_shadow_tag"),
                    "title": x.get("title"),
                    "rule_type": (x.get("rule_control") or {}).get("rule_type"),
                    "scope": (x.get("rule_control") or {}).get("scope"),
                }
                for x in active_rules
            ],
            "paper_trial_rules": [
                {"research_shadow_tag": x.get("research_shadow_tag"), "title": x.get("title")}
                for x in paper_trial_rules[:8]
            ],
            "evidence": summary.get("paper_ev") or {},
        },
        {
            "id": "history_context",
            "label": "History Context",
            "mode": "evidence_context",
            "authority": "History/live records explain past behavior; they do not define current paper policy.",
            "can_queue_paper": False,
            "can_change_live": False,
            "history_count": int(summary.get("history_count") or 0),
            "inside_policy_count": int(summary.get("history_inside_policy_count") or 0),
            "outside_policy_count": int(summary.get("history_outside_policy_count") or 0),
            "outside_policy_pct": float(summary.get("history_outside_policy_pct") or 0.0),
            "strategy_overlap_pct": float(summary.get("strategy_overlap_pct") or 0.0),
            "evidence": summary.get("history_inside_policy_ev") or summary.get("history_ev") or {},
        },
        {
            "id": "live_candidate",
            "label": "Live Candidate",
            "mode": "review_only",
            "authority": "Must mirror the approved Paper Active profile before assisted live review; silent automation remains unavailable.",
            "can_queue_paper": False,
            "can_change_live": False,
            "can_auto_trade": False,
            "live_trading_enabled": LIVE_TRADING_ENABLED,
            "source_profile_id": "paper_active",
            "live_candidate_rules": [
                {"research_shadow_tag": x.get("research_shadow_tag"), "title": x.get("title")}
                for x in live_candidates[:8]
            ],
            "evidence": {
                "paper_policy_ready": False,
                "live_behavior_active": 0,
            },
        },
    ]
    return {
        "success": True,
        "generated_at": _research_now(),
        "lookback_days": lookback_days,
        "active_profile_id": "paper_active",
        "live_blueprint_profile_id": "paper_active",
        "profiles": profiles,
        "summary": {
            "profile_count": len(profiles),
            "paper_enabled": bool(cfg.get("enabled")),
            "paper_enabled_strategy_count": len(enabled),
            "paper_disabled_strategy_count": len(disabled),
            "active_research_runtime_hooks": len(active_rules),
            "paper_trial_rule_count": len(paper_trial_rules),
            "live_candidate_rule_count": len(live_candidates),
            "history_outside_policy_pct": float(summary.get("history_outside_policy_pct") or 0.0),
            "strategy_overlap_pct": float(summary.get("strategy_overlap_pct") or 0.0),
            "live_behavior_active": 0,
        },
        "alignment": {
            "verdict": alignment.get("verdict") or {},
            "summary": summary,
        },
        "rules": [
            "Paper Active is the execution-policy authority for future assisted live.",
            "History Context is evidence only and may include trades outside the current Paper policy.",
            "Research Baseline can challenge or propose rules, but promotion must pass governance.",
            "Live Candidate mirrors Paper Active only after explicit approval; auto-trading remains disabled.",
        ],
    }


def _research_governance_stage(item: dict) -> str:
    control = item.get("rule_control") if isinstance(item.get("rule_control"), dict) else {}
    executable = control.get("executable") if isinstance(control.get("executable"), dict) else {}
    mode = str(control.get("mode") or "off")
    stage = str(item.get("stage") or "")
    if mode == "live_candidate":
        return "live_candidate_safety_review"
    if mode == "paper_applied":
        return "paper_runtime_review" if control.get("paper_effect") == "active_runtime_hook" else "paper_hook_pending"
    if mode == "paper_trial":
        return "forward_paper_validation"
    if executable.get("status") == "needs_rule_wiring":
        return "implementation_wiring"
    if stage in {"promote_candidate", "manual_promoted"}:
        return "promotion_review"
    if stage in {"reject_candidate", "manual_rejected"}:
        return "rejection_review"
    if mode == "shadow":
        return "shadow_measurement"
    if mode == "off":
        return "stored_prior"
    return stage or "source_review"


def _research_governance_payload(
    *,
    rulebook: dict | None = None,
    evidence_ledger: dict | None = None,
    scheduler: dict | None = None,
    profile_registry: dict | None = None,
) -> dict:
    """Decision workflow joining research evidence, rule controls, approval history, and live safety locks."""
    rulebook = rulebook if isinstance(rulebook, dict) else _research_rulebook_payload()
    evidence_ledger = evidence_ledger if isinstance(evidence_ledger, dict) else _research_evidence_ledger_payload()
    scheduler = scheduler if isinstance(scheduler, dict) else _research_scheduler_payload()
    profile_registry = profile_registry if isinstance(profile_registry, dict) else _strategy_profile_registry_payload(rulebook=rulebook)
    ledger = _read_experiment_ledger()
    evidence_by_tag = {
        str(x.get("research_shadow_tag") or ""): x
        for x in (evidence_ledger.get("items") or [])
        if isinstance(x, dict) and x.get("research_shadow_tag")
    }
    queue = []
    stage_counts: dict[str, int] = defaultdict(int)
    needs_wiring_count = 0
    for rule in rulebook.get("items") or []:
        if not isinstance(rule, dict):
            continue
        tag = str(rule.get("research_shadow_tag") or "")
        merged = {**(evidence_by_tag.get(tag) or {}), **rule}
        control = merged.get("rule_control") if isinstance(merged.get("rule_control"), dict) else {}
        executable = control.get("executable") if isinstance(control.get("executable"), dict) else {}
        impact = _research_rule_impact_preview(merged)
        review_stage = _research_governance_stage(merged)
        stage_counts[review_stage] += 1
        if impact.get("needs_wiring"):
            needs_wiring_count += 1
        queue.append({
            "research_shadow_tag": tag,
            "title": merged.get("title") or merged.get("candidate_title") or tag.replace("_", " ").title(),
            "target_strategy": merged.get("target_strategy"),
            "stage": merged.get("stage"),
            "review_stage": review_stage,
            "manual_status": merged.get("manual_status"),
            "rule_control": control,
            "executable": executable,
            "paper_trial": merged.get("paper_trial"),
            "registered": bool(merged.get("registered")),
            "next_action": merged.get("next_action"),
            "promotion_criteria": merged.get("promotion_criteria"),
            "rollback_condition": merged.get("rollback_condition"),
            "impact_preview": impact,
            "safety": {
                "can_change_scoring_now": False,
                "can_change_live_now": False,
                "requires_user_approval": True,
                "requires_final_live_approval": True,
            },
        })
    rank = {
        "live_candidate_safety_review": 10,
        "paper_runtime_review": 9,
        "paper_hook_pending": 8,
        "forward_paper_validation": 7,
        "promotion_review": 6,
        "implementation_wiring": 5,
        "shadow_measurement": 4,
        "rejection_review": 3,
        "stored_prior": 2,
        "source_review": 1,
    }
    queue.sort(
        key=lambda x: (
            rank.get(str(x.get("review_stage")), 0),
            float((x.get("impact_preview") or {}).get("ev_delta_pct") if (x.get("impact_preview") or {}).get("ev_delta_pct") is not None else -999),
            int(((x.get("impact_preview") or {}).get("closed") or 0)),
        ),
        reverse=True,
    )
    rule_summary = rulebook.get("summary") or {}
    drift_alerts = scheduler.get("drift_alerts") or []
    active_hooks = int(rule_summary.get("paper_behavior_active") or 0)
    live_candidates = int(rule_summary.get("live_candidate") or 0)
    live_behavior_active = int(rule_summary.get("live_behavior_active") or 0)
    live_candidate_safety = [
        _live_readiness_gate(
            "Live behavior",
            "pass" if live_behavior_active == 0 else "fail",
            live_behavior_active,
            "0 active",
            "Research governance can nominate Live Candidate only; no live behavior can be active here.",
            blocking=True,
        ),
        _live_readiness_gate(
            "Master live gate",
            "lock" if not LIVE_TRADING_ENABLED else "warn",
            "disabled" if not LIVE_TRADING_ENABLED else "enabled",
            "disabled until final review",
            "LIVE_TRADING_ENABLED remains the hard environment gate for any assisted-live path.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Paper blueprint",
            "pass" if (profile_registry.get("active_profile_id") == "paper_active") else "warn",
            profile_registry.get("active_profile_id") or "unknown",
            "paper_active",
            "Live Candidate must inherit the exact approved Paper Active profile before assisted-live review.",
            blocking=True,
        ),
        _live_readiness_gate(
            "Drift alerts",
            "warn" if drift_alerts else "pass",
            len(drift_alerts),
            "reviewed",
            "Contradictory or cautionary new evidence should be resolved before promotion.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Final approval path",
            "lock",
            "required",
            "separate approval",
            "No route in this phase enables silent live automation from research governance.",
            blocking=True,
        ),
    ]
    return {
        "success": True,
        "generated_at": _research_now(),
        "summary": {
            "queue_count": len(queue),
            "stage_counts": dict(stage_counts),
            "needs_wiring_count": needs_wiring_count,
            "paper_runtime_hook_count": active_hooks,
            "paper_trial_count": int(rule_summary.get("paper_trial") or 0),
            "paper_applied_count": int(rule_summary.get("paper_applied") or 0),
            "live_candidate_count": live_candidates,
            "live_behavior_active": live_behavior_active,
            "drift_alert_count": len(drift_alerts),
            "approval_record_count": len(_research_approval_ledger(limit=200, ledger=ledger)),
        },
        "promotion_queue": queue,
        "approval_ledger": _research_approval_ledger(limit=14, ledger=ledger),
        "live_candidate_safety": live_candidate_safety,
        "strategy_profiles": profile_registry,
        "rules": [
            "Promotion Review Queue is a decision queue, not an execution queue.",
            "Rule Impact Preview shows evidence and blast radius before behavior changes.",
            "Approval Ledger records who changed mode/status and whether paper behavior changed.",
            "Live Candidate Safety Review blocks direct research-to-live promotion.",
        ],
        "scope": {
            "authority": "Research governance can approve lifecycle status and paper-only rule controls.",
            "paper_behavior": "Only wired Paper Applied rules can affect simulated paper candidates.",
            "live_behavior": "No research governance route enables live trading or silent automation.",
        },
    }


def _research_update_rule_control(shadow_tag: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    tag = str(shadow_tag or "").strip()
    if not re.match(r"^[a-zA-Z0-9_:-]{3,100}$", tag):
        raise ValueError("Invalid research shadow tag")
    mode = str(payload.get("mode") or "").strip().lower()
    rule_type = str(payload.get("rule_type") or "").strip().lower()
    if mode == "live_enabled":
        raise ValueError("Live Enabled is blocked in this phase; use Live Candidate for review only")
    if mode not in RESEARCH_RULE_MODES:
        raise ValueError("mode must be off, shadow, paper_trial, paper_applied, or live_candidate")
    if rule_type and rule_type not in RESEARCH_RULE_TYPES:
        raise ValueError("invalid rule_type")

    ledger_payload = _research_evidence_ledger_payload()
    item = next((x for x in ledger_payload.get("items") or [] if str(x.get("research_shadow_tag") or "") == tag), None)
    if not item:
        raise ValueError("Research item not found")

    if mode == "paper_trial" and not item.get("paper_trial"):
        trial_result = _research_start_paper_trial(tag, {"reason": str(payload.get("reason") or "Rulebook mode set to paper trial")})
        item = next(
            (x for x in (_research_evidence_ledger_payload().get("items") or []) if str(x.get("research_shadow_tag") or "") == tag),
            item,
        )
    control = _research_rule_control_for_item(item, _research_rule_controls_by_tag())
    if not rule_type:
        rule_type = control.get("rule_type") or "entry_gate"
    executable = _research_rule_executability(tag, rule_type, item)
    if mode == "paper_applied":
        if not item.get("paper_trial"):
            raise ValueError("Start a Paper Trial before arming Paper Applied")
        if not executable.get("can_paper_apply"):
            raise ValueError(executable.get("reason") or "This research item is not paper-applicable yet")
    if mode == "live_candidate" and not item.get("paper_trial"):
        raise ValueError("Start and review a Paper Trial before marking Live Candidate")

    now = _research_now()
    reason = str(payload.get("reason") or "").strip()[:700]
    actor = str(payload.get("actor") or "local_user").strip()[:80] or "local_user"
    scope = str(payload.get("scope") or item.get("target_strategy") or "portfolio").strip()[:80] or "portfolio"
    ledger = _read_experiment_ledger()
    record = {
        "id": f"research_rule_control_{tag}_{now}",
        "type": "research_rule_control",
        "source": "research_rulebook",
        "research_shadow_tag": tag,
        "shadow_tag": tag,
        "mode": mode,
        "rule_type": rule_type,
        "scope": scope,
        "reason": reason,
        "actor": actor,
        "created_at": now,
        "updated_at": now,
        "updated_by": actor,
        "executable": executable,
        "changed_scoring": False,
        "changed_live_behavior": False,
        "changed_paper_behavior": mode == "paper_applied" and tag in RESEARCH_PAPER_RUNTIME_TAGS,
        "notes": [
            "Research Rulebook governance control.",
            "No live behavior is changed by this record.",
            "Paper Applied arms a rule for a runtime hook; it does not imply live execution.",
        ],
    }
    ledger.append(record)
    _research_write_experiment_ledger(ledger)
    orchestrator = None
    try:
        if mode in {"paper_trial", "paper_applied"}:
            refreshed = next(
                (
                    x for x in (_research_evidence_ledger_payload().get("items") or [])
                    if str(x.get("research_shadow_tag") or "") == tag
                ),
                item,
            )
            orchestrator = _research_prepare_experiment(
                refreshed,
                actor=actor,
            )
            if mode == "paper_applied":
                experiment_id = str(
                    (orchestrator.get("experiment") or {}).get("experiment_id") or ""
                )
                if not experiment_id:
                    raise ValueError("research experiment preparation did not return an id")
                orchestrator["activation"] = _research_activate_experiment(
                    experiment_id,
                    actor=actor,
                    reason=reason or "User approved Paper Applied challenger",
                )
        elif mode in {"off", "shadow"}:
            stopped = _research_stop_source_experiments(
                tag,
                status="parked" if mode == "off" else "rolled_back",
                actor=actor,
                reason=reason or f"Research Rulebook moved to {mode}",
                automatic=False,
            )
            orchestrator = {"stopped_experiments": stopped}
    except Exception as exc:
        if mode == "paper_applied":
            compensation_time = _research_now()
            compensation = {
                **record,
                "id": f"research_rule_control_{tag}_{compensation_time}_compensating",
                "mode": "paper_trial",
                "reason": (
                    "Paper activation was rejected; automatically restored non-behavioral "
                    f"Paper Trial mode. Cause: {str(exc)[:350]}"
                ),
                "actor": "research_orchestrator",
                "created_at": compensation_time,
                "updated_at": compensation_time,
                "updated_by": "research_orchestrator",
                "changed_paper_behavior": False,
                "notes": [
                    "Compensating governance record after rejected Paper activation.",
                    "The latest rule state is non-behavioral Paper Trial.",
                    "No live behavior was changed.",
                ],
            }
            recovery_ledger = _read_experiment_ledger()
            recovery_ledger.append(compensation)
            _research_write_experiment_ledger(recovery_ledger)
        raise
    return {
        "success": True,
        "control": record,
        "orchestrator": orchestrator,
        "rulebook": _research_rulebook_payload(),
        "pipeline": _hermes_research_pipeline_summary(),
    }


def _research_key_sentences(text: str, tags: list[str], limit: int = 3) -> list[str]:
    clean = re.sub(r"\s+", " ", (text or "")).strip()
    if not clean:
        return []
    sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", clean) if 45 <= len(s.strip()) <= 320]
    scored = []
    for idx, sentence in enumerate(sentences[:80]):
        score = _research_sentence_score(sentence, tags)
        if score > 0:
            scored.append((score, -idx, sentence))
    scored.sort(reverse=True)
    picks = []
    for _, __, sentence in scored:
        normalized = sentence.lower()[:120]
        if any(normalized == p.lower()[:120] for p in picks):
            continue
        picks.append(sentence)
        if len(picks) >= limit:
            break
    return picks or sentences[:limit]


def _research_source_distillations(sources: list[dict], reviews: list[dict], limit: int = 6) -> list[dict]:
    reviews_by_source: dict[str, list[dict]] = defaultdict(list)
    for review in reviews:
        reviews_by_source[str(review.get("source_id") or "")].append(review)
    ranked_sources = sorted(
        [s for s in sources if isinstance(s, dict)],
        key=lambda s: (
            float(s.get("relevance_score") or 0),
            float(s.get("quality_score") or 0),
            int(s.get("full_text_word_count") or 0),
        ),
        reverse=True,
    )
    out: list[dict] = []
    for source in ranked_sources[:limit]:
        sid = str(source.get("id") or "")
        tags = [str(t) for t in (source.get("tags") or []) if str(t)]
        text = _research_source_text(source, max_chars=60000)
        matched_reviews = reviews_by_source.get(sid, [])[:3]
        fields = []
        strategies = []
        shadow_tags = []
        for review in matched_reviews:
            for field in review.get("mt7_fields_needed") or []:
                if field and field not in fields:
                    fields.append(field)
            strategy = review.get("target_strategy")
            if strategy and strategy not in strategies:
                strategies.append(strategy)
            shadow_tag = review.get("shadow_tag")
            if shadow_tag and shadow_tag not in shadow_tags:
                shadow_tags.append(shadow_tag)
        status = source.get("full_text_status") or _research_text_profile(text, str(source.get("source_type") or "")).get("full_text_status")
        word_count = int(source.get("full_text_word_count") or _research_text_profile(text, str(source.get("source_type") or "")).get("full_text_word_count") or 0)
        caveats = []
        if status in {"abstract_only", "metadata_only"}:
            caveats.append("Text coverage is incomplete; treat this as a discovery lead until a full source is indexed.")
        elif status == "partial_text":
            caveats.append("Only partial text is indexed; use the source as a weak prior until the complete document is available.")
        elif status == "low_quality_extract":
            caveats.append("Text extraction quality is low; important tables, equations, or sections may be missing.")
        elif status == "scanned_needs_ocr":
            caveats.append("The document appears scanned or image-based; OCR is needed before MT7 should reason from it.")
        elif status == "full_text_unverified":
            caveats.append("Long web text is indexed, but scraped pages can include navigation or omit sections.")
        if not fields:
            caveats.append("No direct MT7 field map yet; keep as background prior.")
        if source.get("source_type") == "uploaded_pdf" and (source.get("extraction") or {}).get("error"):
            caveats.append(str((source.get("extraction") or {}).get("error")))
        application = "Use as external context only until mapped into a shadow cohort."
        if fields and shadow_tags:
            application = (
                f"Apply as shadow evidence for {', '.join(shadow_tags[:2])}; monitor "
                f"{', '.join(fields[:5])} before any scoring or gate change."
            )
        elif fields:
            application = f"Map into MT7 telemetry via {', '.join(fields[:5])}; do not promote until forward-tested."
        verified_claims = _research_claims_from_source(source, text=text, limit=4)
        claim_stats = _research_claim_stats(verified_claims)
        best_claim_confidence = int(claim_stats.get("best_confidence") or 0)
        out.append({
            "source_id": sid,
            "title": source.get("title"),
            "source_type": source.get("source_type"),
            "tags": tags,
            "full_text_status": status,
            "word_count": word_count,
            "quality_score": source.get("quality_score"),
            "relevance_score": source.get("relevance_score"),
            "key_takeaways": _research_key_sentences(text, tags, limit=3),
            "verified_claims": verified_claims,
            "claim_confidence": best_claim_confidence,
            "claim_stats": claim_stats,
            "mt7_application": application,
            "mapped_fields": fields[:8],
            "target_strategies": strategies[:4],
            "shadow_tags": shadow_tags[:4],
            "caveats": caveats or ["Shadow-only prior; requires out-of-sample validation before impact."],
        })
    return out


def _research_status_check(name: str, status: str, detail: str, value=None, action: str = "") -> dict:
    color = {"pass": "green", "warn": "amber", "fail": "red", "info": "blue"}.get(status, "blue")
    return {"name": name, "status": status, "color": color, "detail": detail, "value": value, "action": action}


def _research_workflow_health(
    sources: list[dict] | None = None,
    memo: dict | None = None,
    reviews: list[dict] | None = None,
    shadow_results: dict | None = None,
) -> dict:
    """Research/learner operating-state audit for the whole knowledge workflow."""
    sources = sources if sources is not None else _research_load_sources()
    reviews = reviews if reviews is not None else _cipher_review_research_hypotheses(sources)
    memo = memo if memo is not None else (_hermes_read_json(HERMES_RESEARCH_MEMO_PATH, None) or {})
    shadow_results = shadow_results if shadow_results is not None else _research_shadow_results_payload()

    status_counts: dict[str, int] = defaultdict(int)
    full_text_count = 0
    weak_text_count = 0
    hard_weak_text_count = 0
    partial_text_count = 0
    total_words = 0
    approved_count = 0
    sync_candidate_count = 0
    quality_scores = []
    relevance_scores = []
    for source in sources:
        text = str(source.get("raw_excerpt") or source.get("summary") or "")
        profile = _research_text_profile(text, str(source.get("source_type") or ""), source.get("full_text_status"))
        status = str(source.get("full_text_status") or profile.get("full_text_status") or "unknown")
        word_count = int(source.get("full_text_word_count") or profile.get("full_text_word_count") or 0)
        status_counts[status] += 1
        total_words += max(0, word_count)
        if status in {"full_text", "full_text_unverified"}:
            full_text_count += 1
        if status in {"metadata_only", "abstract_only", "partial_text", "low_quality_extract", "scanned_needs_ocr"}:
            weak_text_count += 1
        if status == "partial_text":
            partial_text_count += 1
        if status in {"metadata_only", "abstract_only", "low_quality_extract", "scanned_needs_ocr"}:
            hard_weak_text_count += 1
        if source.get("online_sync_approved"):
            approved_count += 1
        if _research_source_is_online_sync_candidate(source):
            sync_candidate_count += 1
        if source.get("quality_score") is not None:
            quality_scores.append(float(source.get("quality_score") or 0))
        if source.get("relevance_score") is not None:
            relevance_scores.append(float(source.get("relevance_score") or 0))

    source_count = len(sources)
    full_text_ratio = (full_text_count / source_count) if source_count else 0
    tag_counts: dict[str, int] = defaultdict(int)
    source_support_by_tag: dict[str, set[str]] = defaultdict(set)
    direct_crypto_claims = 0
    missing_field_tags = set()
    for review in reviews:
        tag = str(review.get("shadow_tag") or review.get("id") or "")
        if not tag:
            continue
        tag_counts[tag] += 1
        if review.get("source_id"):
            source_support_by_tag[tag].add(str(review.get("source_id")))
        for field in review.get("mt7_fields_needed") or []:
            if field in {"news_sentiment", "btc_beta", "order_flow_vwap", "profile_poc", "basis"}:
                missing_field_tags.add(tag)
        if str(review.get("market_scope") or "").lower() in {"crypto_perp", "crypto_derivatives"}:
            direct_crypto_claims += 1
        evidence_stats = review.get("evidence_stats") or {}
        direct_crypto_claims += int(evidence_stats.get("direct_crypto_perp_count") or 0)
    duplicate_review_count = sum(max(0, n - 1) for n in tag_counts.values())
    unique_shadow_tags = len(tag_counts)
    memo_age = _file_age_seconds(HERMES_RESEARCH_MEMO_PATH)
    indexed_paths = {
        os.path.abspath(os.path.expanduser(str(s.get("path"))))
        for s in sources
        if s.get("path")
    }
    indexed_rel_roots = {
        (
            os.path.abspath(os.path.expanduser(str(s.get("corpus_root")))),
            _research_norm_identity(str(s.get("relative_path") or "")),
        )
        for s in sources
        if s.get("corpus_root") and s.get("relative_path")
    }
    indexed_relative_paths = {
        _research_norm_identity(str(s.get("relative_path") or ""))
        for s in sources
        if s.get("relative_path")
    }
    indexed_titles = {
        _research_norm_identity(str(s.get("title") or ""))
        for s in sources
        if s.get("title")
    }
    visible_local_candidates = _research_local_corpus_candidates(limit=500, extract_text=False)
    local_candidates = [
        c for c in visible_local_candidates
        if (
            os.path.abspath(os.path.expanduser(str(c.get("path")))) not in indexed_paths
            and (
                os.path.abspath(os.path.expanduser(str(c.get("corpus_root") or ""))),
                _research_norm_identity(str(c.get("relative_path") or "")),
            ) not in indexed_rel_roots
            and _research_norm_identity(str(c.get("relative_path") or "")) not in indexed_relative_paths
            and _research_norm_identity(str(c.get("title") or "")) not in indexed_titles
        )
    ]
    shadow_summary = shadow_results.get("summary") if isinstance(shadow_results, dict) else {}
    registered = int((shadow_summary or {}).get("registered") or 0)
    evaluated = int((shadow_summary or {}).get("evaluated") or 0)
    pending_evaluators = int((shadow_summary or {}).get("evaluator_pending") or 0)
    learner_age = _file_age_seconds(LEARNER_HEARTBEAT_PATH)

    checks = []
    checks.append(_research_status_check(
        "Corpus Indexed",
        "pass" if source_count >= 10 else "warn" if source_count else "fail",
        "Research sources are indexed into Hermes' local library.",
        source_count,
        "Run Index Local Corpus or upload PDFs." if source_count < 10 else "",
    ))
    checks.append(_research_status_check(
        "Local Backlog",
        "warn" if local_candidates else "pass",
        "Unindexed files still visible in configured corpus roots.",
        len(local_candidates),
        "Run Index Local Corpus with force=false to ingest new files." if local_candidates else "",
    ))
    checks.append(_research_status_check(
        "Full-Text Coverage",
        "pass" if full_text_ratio >= 0.70 else "warn" if full_text_ratio >= 0.40 else "fail",
        "High-quality learning needs full paper/article bodies, not abstracts or metadata.",
        f"{full_text_count}/{source_count}",
        "Replace abstract-only leads with PDFs/full text or run OCR for scanned files." if full_text_ratio < 0.70 else "",
    ))
    checks.append(_research_status_check(
        "Weak Text Risk",
        "fail" if source_count and hard_weak_text_count > max(2, source_count * 0.20) else "warn" if hard_weak_text_count > 2 else "pass",
        "Partial extracts are usable with caution; metadata-only, abstract-only, scanned, or low-quality extracts should not drive strategy changes.",
        f"{weak_text_count} weak / {hard_weak_text_count} hard",
        "Open Full Text Audit and reprocess hard-weak sources." if hard_weak_text_count > 2 else "",
    ))
    checks.append(_research_status_check(
        "Research Memo Freshness",
        "fail" if memo_age is None else "warn" if memo_age > 7 * 86400 else "pass",
        "The memo should reflect the currently indexed corpus and candidate queue.",
        "missing" if memo_age is None else f"{round(memo_age / 3600, 1)}h old",
        "Generate Research Memo after new sources are indexed." if memo_age is None or memo_age > 7 * 86400 else "",
    ))
    checks.append(_research_status_check(
        "Hypothesis Collapse",
        "pass" if unique_shadow_tags and duplicate_review_count >= 0 else "warn",
        "Many source-level reviews should collapse into a small set of reusable MT7 concepts.",
        f"{unique_shadow_tags} concepts / {len(reviews)} reviews",
        "Use Priority Queue, not raw Cipher Review cards, for decisions.",
    ))
    checks.append(_research_status_check(
        "Evaluator Coverage",
        "pass" if registered and evaluated == registered and pending_evaluators == 0 else "warn" if registered else "info",
        "Every registered research candidate should have deterministic measurement logic.",
        f"{evaluated}/{registered}",
        "Add evaluator logic before trusting registered candidates." if pending_evaluators else "",
    ))
    checks.append(_research_status_check(
        "Online Knowledge Sync",
        "pass" if sync_candidate_count and approved_count >= sync_candidate_count else "warn" if sync_candidate_count else "info",
        "Approved sources can be exported without local paths for the online MT7 instance.",
        f"{approved_count}/{sync_candidate_count}",
        "Bulk approve safe sources and export the online sync package." if sync_candidate_count and approved_count < sync_candidate_count else "",
    ))
    checks.append(_research_status_check(
        "Learner Heartbeat",
        "pass" if learner_age is not None and learner_age < 600 else "warn" if learner_age is not None and learner_age < 1800 else "fail",
        "The autonomous learner loop must be alive to turn validated evidence into proposals.",
        "missing" if learner_age is None else f"{round(learner_age / 60, 1)}m old",
        "Restart mt-learner or verify LEARNER_HEARTBEAT_PATH." if learner_age is None or learner_age >= 600 else "",
    ))

    fail_count = len([c for c in checks if c["status"] == "fail"])
    warn_count = len([c for c in checks if c["status"] == "warn"])
    posture = "blocked" if fail_count else "needs_attention" if warn_count else "healthy"
    next_actions = [c.get("action") for c in checks if c.get("action")][:5]
    if not next_actions:
        next_actions = ["Keep shadow-first validation active; review promotion candidates only after forward samples are complete."]
    return {
        "generated_at": _research_now(),
        "posture": posture,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "checks": checks,
        "metrics": {
            "source_count": source_count,
            "full_text_count": full_text_count,
            "full_text_ratio": round(full_text_ratio, 3),
            "weak_text_count": weak_text_count,
            "hard_weak_text_count": hard_weak_text_count,
            "partial_text_count": partial_text_count,
            "total_words": total_words,
            "status_counts": dict(status_counts),
            "avg_quality_score": round(sum(quality_scores) / len(quality_scores), 3) if quality_scores else None,
            "avg_relevance_score": round(sum(relevance_scores) / len(relevance_scores), 3) if relevance_scores else None,
            "local_backlog_count": len(local_candidates),
            "review_count": len(reviews),
            "unique_shadow_tags": unique_shadow_tags,
            "duplicate_review_count": duplicate_review_count,
            "source_support_by_tag": {k: len(v) for k, v in source_support_by_tag.items()},
            "direct_crypto_claims": direct_crypto_claims,
            "missing_field_tag_count": len(missing_field_tags),
            "registered_research_tests": registered,
            "evaluated_research_tests": evaluated,
            "pending_evaluators": pending_evaluators,
            "online_sync_approved_count": approved_count,
            "online_sync_candidate_count": sync_candidate_count,
            "memo_age_seconds": memo_age,
            "learner_heartbeat_age_seconds": learner_age,
        },
        "next_actions": next_actions,
    }


def _research_generate_memo(register_experiments: bool = True) -> dict:
    sources = _research_load_sources()
    reviews = _cipher_review_research_hypotheses(sources)
    priority_queue = _research_priority_queue(reviews, _read_experiment_ledger(), sources)
    source_distillations = _research_source_distillations(sources, reviews)
    strategy_candidates = _research_strategy_candidates(priority_queue)
    verified_claim_count = sum(len(s.get("verified_claims") or []) for s in source_distillations)
    top = reviews[:8]
    tag_counts: dict[str, int] = {}
    for s in sources:
        for tag in s.get("tags") or []:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    registered = 0
    if register_experiments:
        for hyp in top:
            record = {
                "id": hyp.get("id"),
                "created_at": _research_now(),
                "source": "hermes_research_pipeline",
                "status": "shadow_proposed",
                "hypothesis": hyp.get("thesis"),
                "target_strategy": hyp.get("target_strategy"),
                "shadow_tag": hyp.get("shadow_tag"),
                "mt7_fields_needed": hyp.get("mt7_fields_needed"),
                "expected_edge": hyp.get("expected_edge"),
                "gate_impact": hyp.get("gate_impact"),
                "overfitting_risk": hyp.get("overfitting_risk"),
                "promotion_criteria": hyp.get("promotion_criteria"),
                "rollback_condition": hyp.get("rollback_condition"),
                "source_title": hyp.get("source_title"),
            }
            if record["id"] and _append_experiment_record_once(record):
                registered += 1
    memo = {
        "generated_at": _research_now(),
        "title": "Hermes Research Memo",
        "mode": "research_to_shadow_experiments",
        "artifact_type": "research_memo",
        "source_count": len(sources),
        "tag_counts": tag_counts,
        "sections": {
            "executive_summary": (
                f"Hermes distilled {len(source_distillations)} research sources and verified {verified_claim_count} source claims into shadow-only MT7 applications. "
                "Each source is mapped to concrete fields, evidence type, market scope, candidate strategy gates, and validation caveats before it can influence scoring."
            ),
            "source_distillations": source_distillations,
            "strategy_candidates": strategy_candidates,
            "research_radar": top,
            "cipher_review": [
                {
                    "id": h.get("id"),
                    "verdict": h.get("cipher_verdict"),
                    "score": h.get("cipher_score"),
                    "target_strategy": h.get("target_strategy"),
                    "shadow_tag": h.get("shadow_tag"),
                    "overfitting_risk": h.get("overfitting_risk"),
                    "gate_impact": h.get("gate_impact"),
                } for h in top
            ],
            "priority_queue": priority_queue[:8],
            "anti_overfit_rules": [
                "Do not promote from a single source or a single week of market behavior.",
                "Require at least 50 closed forward-tested tagged signals before live effect.",
                "Reject symbol-specific hacks unless they are explicitly liquidity/execution safety rules.",
                "Measure trade-count reduction, EV, drawdown, and false-negative opportunity cost.",
            ],
        },
        "registered_shadow_experiments": registered,
    }
    _research_write_json(HERMES_RESEARCH_MEMO_PATH, memo)
    archive_dir = os.path.join(HERMES_RESEARCH_DIR, "archive")
    os.makedirs(archive_dir, exist_ok=True)
    stamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    _research_write_json(os.path.join(archive_dir, f"research_memo_{stamp}.json"), memo)
    return memo


def _research_generate_weekly_memo(register_experiments: bool = True) -> dict:
    """Compatibility alias for older UI/API callers."""
    return _research_generate_memo(register_experiments=register_experiments)


def _hermes_research_pipeline_summary() -> dict:
    sources = _research_load_sources()
    memo = _hermes_read_json(HERMES_RESEARCH_MEMO_PATH, None) or _hermes_read_json(HERMES_RESEARCH_LEGACY_MEMO_PATH, None)
    reviews = _cipher_review_research_hypotheses(sources)
    ledger = _read_experiment_ledger()
    research_experiments = [
        x for x in ledger
        if isinstance(x, dict) and x.get("source") in {"hermes_research_pipeline", "hermes_research_strategy_candidate"}
    ]
    priority_queue = _research_priority_queue(reviews, ledger, sources)
    strategy_candidates = _research_strategy_candidates(priority_queue)
    display_sources = []
    online_sync_approved_count = sum(1 for s in sources if isinstance(s, dict) and s.get("online_sync_approved"))
    online_sync_candidate_count = sum(1 for s in sources if isinstance(s, dict) and _research_source_is_online_sync_candidate(s))
    ranked_display_sources = sorted(
        sources,
        key=lambda s: (
            float(s.get("relevance_score") or 0),
            float(s.get("quality_score") or 0),
            int(s.get("full_text_word_count") or 0),
        ),
        reverse=True,
    )
    for source in ranked_display_sources[:8]:
        item = dict(source)
        text = str(item.get("raw_excerpt") or item.get("summary") or "")
        profile = _research_text_profile(text, str(item.get("source_type") or ""), item.get("full_text_status"))
        item.setdefault("full_text_status", profile["full_text_status"])
        item.setdefault("full_text_word_count", profile["full_text_word_count"])
        item.setdefault("full_text_confidence", profile["full_text_confidence"])
        display_sources.append(item)
    shadow_results = _research_shadow_results_payload()
    evidence_ledger = _research_evidence_ledger_payload(
        sources=sources,
        reviews=reviews,
        priority_queue=priority_queue,
        strategy_candidates=strategy_candidates,
        shadow_results=shadow_results,
    )
    workflow_health = _research_workflow_health(
        sources=sources,
        memo=memo if isinstance(memo, dict) else {},
        reviews=reviews,
        shadow_results=shadow_results,
    )
    return {
        "library": {
            "source_count": len(sources),
            "full_text_count": workflow_health.get("metrics", {}).get("full_text_count", 0),
            "full_text_ratio": workflow_health.get("metrics", {}).get("full_text_ratio", 0),
            "weak_text_count": workflow_health.get("metrics", {}).get("weak_text_count", 0),
            "status_counts": workflow_health.get("metrics", {}).get("status_counts", {}),
            "online_sync_approved_count": online_sync_approved_count,
            "online_sync_candidate_count": online_sync_candidate_count,
            "online_sync_package_path": HERMES_RESEARCH_ONLINE_SYNC_PATH,
            "sources": display_sources,
            "local_candidates": _research_local_corpus_candidates(limit=8, extract_text=False),
        },
        "research_memo": memo,
        "weekly_memo": memo,
        "cipher_reviews": reviews[:10],
        "priority_queue": priority_queue[:12],
        "strategy_candidates": strategy_candidates[:8],
        "shadow_results": shadow_results,
        "evidence_ledger": evidence_ledger,
        "workflow_health": workflow_health,
        "shadow_experiment_count": len(research_experiments),
        "source_path": HERMES_RESEARCH_SOURCES_PATH,
        "memo_path": HERMES_RESEARCH_MEMO_PATH,
        "legacy_memo_path": HERMES_RESEARCH_LEGACY_MEMO_PATH,
    }


def _research_priority_audit_payload(shadow_tag: str) -> dict:
    """Build a source-level audit packet for one research priority concept."""
    tag = str(shadow_tag or "").strip()
    sources = _research_load_sources()
    source_by_id = {str(s.get("id") or ""): s for s in sources if isinstance(s, dict)}
    reviews = _cipher_review_research_hypotheses(sources)
    ledger = _read_experiment_ledger()
    queue = _research_priority_queue(reviews, ledger, sources)
    concept = next((q for q in queue if str(q.get("shadow_tag") or q.get("id") or "") == tag), None)
    if not concept:
        return {"success": False, "error": "Research priority not found"}

    matched_reviews = [
        r for r in reviews
        if str(r.get("shadow_tag") or r.get("id") or "") == str(concept.get("shadow_tag") or concept.get("id") or "")
    ]
    seen_source_ids: list[str] = []
    for sid in concept.get("source_ids") or []:
        if sid and sid not in seen_source_ids:
            seen_source_ids.append(str(sid))
    for review in matched_reviews:
        sid = str(review.get("source_id") or "")
        if sid and sid not in seen_source_ids:
            seen_source_ids.append(sid)

    source_packets = []
    all_claims = []
    for sid in seen_source_ids:
        source = source_by_id.get(sid)
        if not source:
            continue
        text = str(source.get("raw_excerpt") or source.get("summary") or "")[:60000]
        profile = _research_text_profile(text, str(source.get("source_type") or ""), source.get("full_text_status"))
        claims = _research_claims_from_source(source, text=text, limit=5)
        all_claims.extend(claims)
        source_reviews = [r for r in matched_reviews if str(r.get("source_id") or "") == sid]
        source_packets.append({
            "source_id": sid,
            "title": source.get("title"),
            "url": source.get("url"),
            "full_text_url": source.get("full_text_url"),
            "source_type": source.get("source_type"),
            "author": source.get("author"),
            "published_at": source.get("published_at"),
            "tags": source.get("tags") or [],
            "full_text_status": source.get("full_text_status") or profile.get("full_text_status"),
            "full_text_word_count": source.get("full_text_word_count") or profile.get("full_text_word_count"),
            "quality_score": source.get("quality_score"),
            "relevance_score": source.get("relevance_score"),
            "summary": str(source.get("summary") or "").strip() or _research_summarize_text(text),
            "key_takeaways": _research_key_sentences(text, [str(t) for t in (source.get("tags") or [])], limit=3),
            "verified_claims": claims,
            "claim_stats": _research_claim_stats(claims),
            "matched_reviews": source_reviews,
            "caveats": [
                c for c in [
                    "Incomplete text; treat as discovery lead." if (source.get("full_text_status") in {"abstract_only", "metadata_only", "partial_text"}) else "",
                    "Web scrape is long but unverified; inspect source before promotion." if source.get("full_text_status") == "full_text_unverified" else "",
                    "Low-quality extraction may omit tables, equations, or sections." if source.get("full_text_status") == "low_quality_extract" else "",
                ] if c
            ],
        })

    all_claims_sorted = sorted(all_claims, key=lambda c: int(c.get("confidence") or 0), reverse=True)
    support_claims = [c for c in all_claims_sorted if c.get("stance") == "support"][:6]
    caution_claims = [c for c in all_claims_sorted if c.get("stance") == "caution"][:6]
    contradiction_claims = [c for c in all_claims_sorted if c.get("stance") == "contradiction"][:6]
    audit_stats = _research_claim_stats(all_claims)
    experiment = next(
        (
            x for x in ledger
            if isinstance(x, dict)
            and x.get("source") in {"hermes_research_pipeline", "hermes_research_strategy_candidate"}
            and str(x.get("shadow_tag") or x.get("id") or "") == str(concept.get("shadow_tag") or concept.get("id") or "")
        ),
        None,
    )
    return {
        "success": True,
        "generated_at": _research_now(),
        "concept": concept,
        "strategy_candidate": _research_strategy_candidate_blueprint(concept),
        "audit_stats": audit_stats,
        "source_count": len(source_packets),
        "sources": source_packets,
        "support_claims": support_claims,
        "caution_claims": caution_claims,
        "contradiction_claims": contradiction_claims,
        "matched_reviews": matched_reviews,
        "registered_experiment": experiment,
        "shadow_test": {
            "shadow_tag": concept.get("shadow_tag"),
            "target_strategy": concept.get("target_strategy"),
            "thesis": concept.get("thesis"),
            "fields": concept.get("available_fields") or [],
            "partial_fields": concept.get("partial_fields") or [],
            "missing_fields": concept.get("missing_fields") or [],
            "promotion_criteria": concept.get("promotion_criteria"),
            "rollback_condition": concept.get("rollback_condition"),
            "next_action": concept.get("next_action"),
            "gate_impact": concept.get("gate_impact"),
            "blockers": concept.get("blockers") or [],
        },
    }


def _profit_factor_from_pnls(pnls: list[float]) -> float | None:
    gains = [p for p in pnls if p > 0]
    losses = [abs(p) for p in pnls if p < 0]
    if losses:
        return round(sum(gains) / sum(losses), 2)
    if gains:
        return 999.0
    return None


