def _hermes_symbol_risk_audit(con: sqlite3.Connection) -> dict:
    raw = _load_risk_gates_raw()
    overrides = raw.get("symbol_overrides", {})
    if not isinstance(overrides, dict):
        overrides = {}
    liq_cfg = _liquidity_gate_config(raw)
    loss_cfg = _symbol_loss_gate_config(raw)
    blocked = [
        {"symbol": sym, **entry}
        for sym, entry in overrides.items()
        if isinstance(entry, dict) and entry.get("action") == "blocked"
    ]
    recent_liquidity_rows: list[dict] = []
    try:
        signal_cols = _hermes_table_cols(con, "signals")
        live_filter = (
            "AND COALESCE(source, 'live') = 'live'"
            if "source" in signal_cols else ""
        )
        rows = con.execute("""
            SELECT symbol, result, pnl_pct, signal_json
            FROM signals
            WHERE result IN ('WIN','LOSS','PARTIAL')
              AND pnl_pct IS NOT NULL
              AND datetime(COALESCE(result_at, logged_at)) >= datetime('now', '-30 days')
              {live_filter}
            ORDER BY COALESCE(result_at, logged_at) DESC
            LIMIT 400
        """.format(live_filter=live_filter)).fetchall()
        buckets: dict[str, list[float]] = defaultdict(list)
        for row in rows:
            try:
                sj = json.loads(row["signal_json"] or "{}")
            except Exception:
                sj = {}
            tier = sj.get("liquidity_tier")
            if not tier:
                tags = sj.get("tags") or []
                if "liq_micro" in tags:
                    tier = "micro"
                elif "liq_thin" in tags:
                    tier = "thin"
            if tier:
                buckets[str(tier)].append(float(row["pnl_pct"] or 0.0))
        for tier, pnls in buckets.items():
            recent_liquidity_rows.append({
                "tier": tier,
                "count": len(pnls),
                "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
                "profit_factor_pct": _profit_factor_from_pnls(pnls),
            })
    except Exception as e:
        recent_liquidity_rows.append({"error": str(e)})

    return {
        "liquidity_gate": liq_cfg,
        "symbol_loss_gate": loss_cfg,
        "blocked_symbol_count": len(blocked),
        "blocked_symbols": sorted(blocked, key=lambda x: str(x.get("blocked_at") or ""), reverse=True)[:20],
        "recent_liquidity_tiers": sorted(recent_liquidity_rows, key=lambda x: -int(x.get("count") or 0)),
        "dataset": {
            "source_lane": "live",
            "window": "recent_30d_by_outcome_time",
            "value_unit": "pnl_pct",
            "execution_semantics": "signal evaluator outcomes; not verified executed fills",
        },
        "recommendation": (
            "Treat blocked symbols and micro/thin liquidity cohorts as manual-review names. "
            "Do not re-enable a blocked symbol without a documented cooldown or improved forward evidence."
        ),
    }


def _hermes_signal_audit(con: sqlite3.Connection) -> dict:
    cols = _hermes_table_cols(con, "signals")
    if not cols:
        return {"count": 0, "closed": 0, "sample_warning": "signals table unavailable"}

    live_source_filter = (
        "AND COALESCE(source, 'live') = 'live'"
        if "source" in cols else ""
    )
    shadow_source_filter = (
        "AND source = 'disabled_shadow'"
        if "source" in cols else "AND 1=0"
    )
    if "result_at" in cols and "logged_at" in cols:
        date_expr = "COALESCE(result_at, logged_at)"
    elif "result_at" in cols:
        date_expr = "result_at"
    elif "logged_at" in cols:
        date_expr = "logged_at"
    elif "created_at" in cols:
        date_expr = "created_at"
    elif "ts" in cols:
        date_expr = "ts"
    else:
        date_expr = None
    recent_filter = (
        f"AND datetime({date_expr}) >= datetime('now', '-30 days')"
        if date_expr else ""
    )

    def _summary(rows) -> dict:
        pnls = [float(r["pnl_pct"] or 0) for r in rows]
        wins = sum(1 for r in rows if r["result"] == "WIN")
        partials = sum(1 for r in rows if r["result"] == "PARTIAL")
        losses = sum(1 for r in rows if r["result"] == "LOSS")
        return {
            "closed": len(rows),
            "wins": wins,
            "partials": partials,
            "losses": losses,
            "win_partial_rate": round((wins + partials) / len(rows), 3) if rows else None,
            "ev_per_trade_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
            "total_pnl_pct": round(sum(pnls), 2) if pnls else 0,
            "profit_factor_pct": _profit_factor_from_pnls(pnls),
            "metric_note": "EV is a simple mean of pnl_pct; profit factor is gross positive pnl_pct divided by gross negative pnl_pct.",
        }

    def _lane(source_filter: str, source_lane: str) -> dict:
        closed_rows = con.execute(f"""
            SELECT result, pnl_pct, strategy_key, symbol
            FROM signals
            WHERE result IS NOT NULL
              AND pnl_pct IS NOT NULL
              {source_filter}
        """).fetchall()
        recent_rows = con.execute(f"""
            SELECT result, pnl_pct, strategy_key, symbol
            FROM signals
            WHERE result IS NOT NULL
              AND pnl_pct IS NOT NULL
              {source_filter}
              {recent_filter}
        """).fetchall() if date_expr else closed_rows[-200:]
        strategy_rows = con.execute(f"""
            SELECT strategy_key,
                   COUNT(*) AS n,
                   ROUND(AVG(pnl_pct), 2) AS ev_per_trade_pct,
                   ROUND(SUM(pnl_pct), 2) AS total_pnl_pct,
                   SUM(CASE WHEN result IN ('WIN','PARTIAL','TP3') THEN 1 ELSE 0 END) AS good,
                   '{source_lane}' AS source_lane,
                   'recent_30d' AS window,
                   'percentage_points' AS total_unit
            FROM signals
            WHERE result IS NOT NULL
              AND pnl_pct IS NOT NULL
              {source_filter}
              {recent_filter}
            GROUP BY strategy_key
            HAVING COUNT(*) >= 3
            ORDER BY total_pnl_pct DESC
            LIMIT 12
        """).fetchall()
        symbol_rows = con.execute(f"""
            SELECT symbol,
                   COUNT(*) AS n,
                   ROUND(AVG(pnl_pct), 2) AS ev_per_trade_pct,
                   ROUND(SUM(pnl_pct), 2) AS total_pnl_pct,
                   '{source_lane}' AS source_lane,
                   'recent_30d' AS window,
                   'percentage_points' AS total_unit
            FROM signals
            WHERE result IS NOT NULL
              AND pnl_pct IS NOT NULL
              {source_filter}
              {recent_filter}
            GROUP BY symbol
            HAVING COUNT(*) >= 2
            ORDER BY total_pnl_pct ASC
            LIMIT 8
        """).fetchall()
        return {
            "dataset": {
                "source_lane": source_lane,
                "window": "recent_30d_by_outcome_time",
                "value_unit": "pnl_pct",
                "cumulative_unit": "percentage_points",
                "execution_semantics": (
                    "signal evaluator outcomes; not verified executed fills"
                    if source_lane == "live"
                    else "counterfactual disabled-strategy outcomes; no execution authority"
                ),
            },
            "all_time": _summary(closed_rows),
            "recent_30d": _summary(recent_rows),
            "strategies": _hermes_rows_to_dicts(strategy_rows),
            "worst_symbols": _hermes_rows_to_dicts(symbol_rows),
        }

    live_lane = _lane(live_source_filter, "live")
    shadow_lane = _lane(shadow_source_filter, "disabled_shadow")
    source_filter = live_source_filter

    # ── Coach intelligence: structured contract + recent evidence ──
    coach_summary = {
        "contract_version": COACH_REVIEW_VERSION,
        "total_reviews": 0,
        "structured_reviews": 0,
        "legacy_reviews": 0,
        "by_result": {},
        "loss_themes": [],
        "recurring_patterns": [],
        "strategy_patterns": [],
        "quality": {},
        "note": "Use /api/intelligence/hermes/coach-reviews for the paginated evidence corpus.",
    }
    recent_reviews = []
    try:
        all_review_rows = con.execute(f"""
            SELECT id, symbol, direction, strategy_key, result, pnl_pct,
                   logged_at, signal_json
            FROM signals
            WHERE result IS NOT NULL
              AND result NOT IN ('EXPIRED', 'SKIPPED')
              AND json_extract(signal_json, '$.coach_review') IS NOT NULL
              {source_filter}
            ORDER BY logged_at DESC
        """).fetchall()

        issue_counts: dict[str, dict] = {}
        strategy_counts: dict[tuple[str, str], dict] = {}
        by_result: dict = {}
        structured_reviews = 0
        reasoning_removed = 0
        path_available = 0
        actionable = 0
        sentence_counts: dict[str, int] = {}
        sentence_total = 0

        for i, row in enumerate(all_review_rows):
            try:
                sj = json.loads(row["signal_json"] or "{}")
                raw_review = sj.get("coach_review") or ""
                review_text, sanitation = _sanitize_coach_review_text(raw_review)
                if not review_text:
                    continue
                result = row["result"]
                by_result[result] = by_result.get(result, 0) + 1
                packet = sj.get("coach_review_packet")
                if not isinstance(packet, dict) or packet.get("version") != COACH_REVIEW_VERSION:
                    packet = _build_coach_review_packet(
                        dict(row),
                        sj,
                        _coach_journey_from_signal_json(sj),
                        review_text,
                        None,
                    )
                else:
                    structured_reviews += 1
                quality = packet.get("quality") or {}
                reasoning_removed += int(bool(
                    sanitation.get("reasoning_removed")
                    or quality.get("reasoning_removed")
                ))
                path_available += int(bool((packet.get("path") or {}).get("available")))
                actionable += int(bool((packet.get("lesson") or {}).get("next_trade_rule")))
                for sentence in re.split(r"(?<=[.!?])\s+", review_text.replace("\n", " ")):
                    normalized = re.sub(
                        r"[^a-z0-9% ]+",
                        " ",
                        sentence.lower(),
                    )
                    normalized = re.sub(r"\s+", " ", normalized).strip()
                    if len(normalized.split()) < 7:
                        continue
                    sentence_counts[normalized] = sentence_counts.get(normalized, 0) + 1
                    sentence_total += 1
                issue = str(
                    (packet.get("verdict") or {}).get("primary_issue")
                    or "unclassified"
                )
                issue_bucket = issue_counts.setdefault(
                    issue,
                    {"total": 0, "LOSS": 0, "WIN": 0, "PARTIAL": 0, "pnl_sum": 0.0},
                )
                issue_bucket["total"] += 1
                if result in issue_bucket:
                    issue_bucket[result] += 1
                issue_bucket["pnl_sum"] += _report_float(row["pnl_pct"])
                strategy_key = str(row["strategy_key"] or "unknown")
                strategy_bucket = strategy_counts.setdefault(
                    (strategy_key, issue),
                    {"count": 0, "losses": 0, "wins_partials": 0, "pnl_sum": 0.0},
                )
                strategy_bucket["count"] += 1
                strategy_bucket["losses"] += int(result == "LOSS")
                strategy_bucket["wins_partials"] += int(result in {"WIN", "PARTIAL"})
                strategy_bucket["pnl_sum"] += _report_float(row["pnl_pct"])
                if i < 20:
                    recent_reviews.append({
                        "signal_id": row["id"],
                        "symbol":    row["symbol"],
                        "direction": row["direction"],
                        "strategy":  row["strategy_key"],
                        "result":    result,
                        "pnl_pct":   row["pnl_pct"],
                        "review":    review_text,
                        "packet":    packet,
                    })
            except Exception:
                pass

        loss_themes = sorted(
            [
                {
                    "theme": issue,
                    "loss_count": counts["LOSS"],
                    "win_count": counts["WIN"],
                    "partial_count": counts["PARTIAL"],
                    "total_count": counts["total"],
                }
                for issue, counts in issue_counts.items()
                if counts["total"] > 0
            ],
            key=lambda x: x["loss_count"], reverse=True,
        )
        recurring_patterns = sorted(
            [
                {
                    "issue": issue,
                    "label": issue.replace("_", " ").title(),
                    "sample": counts["total"],
                    "losses": counts["LOSS"],
                    "wins_partials": counts["WIN"] + counts["PARTIAL"],
                    "avg_pnl_pct": round(counts["pnl_sum"] / counts["total"], 2),
                    "descriptive_only": True,
                }
                for issue, counts in issue_counts.items()
            ],
            key=lambda item: (item["sample"], item["losses"]),
            reverse=True,
        )
        strategy_patterns = sorted(
            [
                {
                    "strategy": strategy,
                    "issue": issue,
                    "sample": counts["count"],
                    "losses": counts["losses"],
                    "wins_partials": counts["wins_partials"],
                    "avg_pnl_pct": round(counts["pnl_sum"] / counts["count"], 2),
                }
                for (strategy, issue), counts in strategy_counts.items()
                if counts["count"] >= 5
            ],
            key=lambda item: (item["losses"], item["sample"]),
            reverse=True,
        )[:12]
        total_reviews = len(all_review_rows)
        repeated_counts = [
            count for count in sentence_counts.values()
            if count >= 5
        ]
        repeated_occurrences = sum(repeated_counts)
        repeated_occurrence_pct = (
            round(repeated_occurrences / sentence_total * 100, 1)
            if sentence_total else 0.0
        )
        coach_summary = {
            "contract_version": COACH_REVIEW_VERSION,
            "total_reviews": total_reviews,
            "structured_reviews": structured_reviews,
            "legacy_reviews": max(0, total_reviews - structured_reviews),
            "by_result": by_result,
            "loss_themes": loss_themes,
            "recurring_patterns": recurring_patterns,
            "strategy_patterns": strategy_patterns,
            "quality": {
                "structured_coverage_pct": round(
                    structured_reviews / total_reviews * 100, 1
                ) if total_reviews else 0.0,
                "path_evidence_coverage_pct": round(
                    path_available / total_reviews * 100, 1
                ) if total_reviews else 0.0,
                "actionable_rule_coverage_pct": round(
                    actionable / total_reviews * 100, 1
                ) if total_reviews else 0.0,
                "reasoning_contamination_hidden": reasoning_removed,
                "exact_sentences_repeated_5plus": len(repeated_counts),
                "repeated_sentence_occurrence_pct": repeated_occurrence_pct,
                "narrative_repetition_status": (
                    "needs_review" if repeated_occurrence_pct >= 15 else "acceptable"
                ),
            },
            "authority": "descriptive_only",
            "note": "Use /api/intelligence/hermes/coach-reviews for the paginated evidence corpus.",
        }
    except Exception:
        pass

    all_summary = live_lane["all_time"]
    recent_summary = live_lane["recent_30d"]
    return {
        "dataset": live_lane["dataset"],
        "all_time": all_summary,
        "recent_30d": recent_summary,
        "strategies": live_lane["strategies"],
        "worst_symbols": live_lane["worst_symbols"],
        "disabled_shadow": shadow_lane,
        "sample_warning": "low sample" if recent_summary["closed"] < 30 else None,
        "coach_reviews": coach_summary,
        "coach_reviews_recent_20": recent_reviews,
    }


def _hermes_paper_stats(rows) -> dict:
    items = [dict(row) for row in rows]
    pnls = [
        float(row.get("pnl_pct") or 0.0)
        for row in items
        if row.get("pnl_pct") is not None
    ]
    pnl_usd = [
        _paper_trade_pnl_usd(row)
        for row in items if row.get("pnl_pct") is not None
    ]
    gross_pnls = [
        float(
            row.get("gross_pnl_pct")
            if row.get("gross_pnl_pct") is not None
            else row.get("pnl_pct") or 0.0
        )
        for row in items
        if row.get("pnl_pct") is not None
    ]
    costs_usd = [
        _paper_notional_pnl_usd(
            row.get("size_usd"),
            float(row.get("fee_cost_pct") or 0.0)
            + float(row.get("slippage_cost_pct") or 0.0),
            row.get("leverage"),
        )
        for row in items
        if row.get("pnl_pct") is not None
    ]
    funding_usd = [
        float(row.get("funding_pnl_usd") or 0.0)
        for row in items
        if row.get("funding_pnl_usd") is not None
    ]
    funding_complete = len([
        row for row in items if int(row.get("funding_complete") or 0) == 1
    ])
    execution_complete = len([
        row for row in items
        if int(row.get("execution_cost_complete") or 0) == 1
    ])
    wins = sum(
        1 for row in items
        if str(row.get("result") or "").upper() in {"WIN", "TP3"}
    )
    partials = sum(
        1 for row in items
        if str(row.get("result") or "").upper() == "PARTIAL"
    )
    losses = sum(
        1 for row in items
        if str(row.get("result") or "").upper() == "LOSS"
    )
    worst = sorted(
        [
            {
                "symbol": row.get("symbol"),
                "strategy_key": row.get("strategy_key"),
                "pnl_pct": row.get("pnl_pct"),
                "pnl_usd": round(
                    float(row.get("size_usd") or 0.0)
                    * float(row.get("pnl_pct") or 0.0)
                    / 100.0,
                    2,
                ),
                "size_usd": row.get("size_usd"),
                "atr_pct": row.get("atr_pct"),
                "trend_score": row.get("trend_score"),
                "closed_at": row.get("closed_at"),
            }
            for row in items
            if row.get("pnl_pct") is not None
        ],
        key=lambda row: float(row.get("pnl_usd") or 0.0),
    )[:8]
    return {
        "closed": len(items),
        "wins": wins,
        "partials": partials,
        "losses": losses,
        "win_partial_rate": (
            round((wins + partials) / len(items), 3) if items else None
        ),
        "win_partial_rate_pct": (
            round((wins + partials) / len(items) * 100.0, 1)
            if items else None
        ),
        "ev_per_trade_pct": (
            round(sum(pnls) / len(pnls), 2) if pnls else None
        ),
        "total_pnl_pct": round(sum(pnls), 2) if pnls else 0,
        "avg_pnl_usd": (
            round(sum(pnl_usd) / len(pnl_usd), 2) if pnl_usd else None
        ),
        "total_pnl_usd": round(sum(pnl_usd), 2) if pnl_usd else 0,
        "gross_ev_per_trade_pct": (
            round(sum(gross_pnls) / len(gross_pnls), 2)
            if gross_pnls else None
        ),
        "total_cost_usd": round(sum(costs_usd), 2) if costs_usd else 0,
        "funding_pnl_usd": round(sum(funding_usd), 4),
        "funding_coverage_pct": (
            round(funding_complete / len(items) * 100.0, 1) if items else None
        ),
        "execution_cost_coverage_pct": (
            round(execution_complete / len(items) * 100.0, 1) if items else None
        ),
        "profit_factor": _profit_factor_from_pnls(pnls),
        "profit_factor_usd": _profit_factor_from_pnls(pnl_usd),
        "worst_trades": worst,
        "sample_warning": "low sample" if len(items) < 50 else None,
        "metric_note": (
            "Paper is simulated execution. USD fields convert leveraged return "
            "back to notional dollars with size_usd * pnl_pct / leverage; "
            "percentage totals must not be added to simulated account equity."
        ),
    }


def _hermes_paper_audit(con: sqlite3.Connection) -> dict:
    cols = _hermes_table_cols(con, "paper_trades")
    if not cols:
        return {"open": 0, "closed": 0, "sample_warning": "paper_trades table unavailable"}

    def _expr(name: str, fallback: str = "NULL") -> str:
        return name if name in cols else f"{fallback} AS {name}"

    rows = con.execute(f"""
        SELECT symbol,
               strategy_key,
               result,
               pnl_pct,
               {_expr('gross_pnl_pct', 'pnl_pct')},
               {_expr('fee_cost_pct', '0')},
               {_expr('slippage_cost_pct', '0')},
               {_expr('funding_pnl_usd', '0')},
               {_expr('funding_complete', '0')},
               {_expr('execution_cost_complete', '0')},
               {_expr('atr_pct')},
               {_expr('trend_score')},
               status,
               size_usd,
               {_expr('leverage', '1')},
               {_expr('closed_at')},
               {_expr('queued_at')},
               {_expr('filled_at')},
               {_expr('opened_at')},
               {_expr('learning_policy_fingerprint')}
        FROM paper_trades
        WHERE status='closed'
          AND pnl_pct IS NOT NULL
        ORDER BY {_expr('closed_at', "''").split(' AS ')[0]} ASC
    """).fetchall()
    all_stats = _hermes_paper_stats(rows)
    cfg = _load_paper_config()
    cohort_scope = _paper_cohort_scope(cfg)
    cohort_rows = [
        row for row in rows
        if _paper_trade_in_cohort(dict(row), cohort_scope)
    ]
    cohort_stats = _hermes_paper_stats(cohort_rows)

    status_rows = con.execute("""
        SELECT status, COUNT(*) AS n
        FROM paper_trades
        GROUP BY status
    """).fetchall()
    lifecycle = {
        str(row["status"] or "unknown"): int(row["n"] or 0)
        for row in status_rows
    }
    leverage_divisor = (
        "COALESCE(NULLIF(leverage, 0), 1)"
        if "leverage" in cols else "1"
    )
    symbol_rows = con.execute(f"""
        SELECT symbol,
               COUNT(*) AS n,
               ROUND(AVG(pnl_pct), 2) AS ev_per_trade_pct,
               ROUND(SUM(size_usd * pnl_pct / 100.0 /
                   {leverage_divisor}), 2) AS total_pnl_usd,
               'paper_simulated' AS source_lane,
               'USD' AS total_unit
        FROM paper_trades
        WHERE status='closed'
          AND pnl_pct IS NOT NULL
        GROUP BY symbol
        ORDER BY total_pnl_usd ASC
        LIMIT 8
    """).fetchall()
    return {
        **all_stats,
        "open": int(lifecycle.get("open") or 0),
        "pending": int(lifecycle.get("pending") or 0),
        "dataset": {
            "source_lane": "paper_trades",
            "execution_semantics": "simulated fills only; not brokerage account P&L",
            "percent_unit": "leveraged pnl_pct",
            "dollar_method": "notional size_usd * leveraged pnl_pct / 100 / leverage",
        },
        "current_policy_cohort": {
            **cohort_scope,
            **cohort_stats,
        },
        "lifecycle": lifecycle,
        "worst_symbols_by_usd": _hermes_rows_to_dicts(symbol_rows),
    }


def _hermes_paper_policy_context(goals: dict, actuals: dict) -> dict:
    cfg = _load_paper_config()
    registry = get_strategy_registry(include_disabled=True)
    overrides = _load_strategy_overrides()
    disabled = {
        str(key).strip()
        for key in (cfg.get("disabled_strategies") or [])
        if str(key).strip()
    }
    user_floor = int(cfg.get("min_conviction", 55) or 55)
    effective_thresholds = {}
    for key, strategy in registry.items():
        override = overrides.get(key) or {}
        runtime_floor = int(
            override.get("min_conviction", strategy.get("min_conviction", 0))
            or 0
        )
        effective_thresholds[key] = {
            "paper_user_floor": user_floor,
            "runtime_strategy_floor": runtime_floor,
            "effective_floor": max(user_floor, runtime_floor),
            "runtime_floor_authority": (
                "strategy_override"
                if "min_conviction" in override else "strategy_default"
            ),
        }

    sizing_policy = _paper_sizing_policy(cfg)
    sizing_balance = float(
        sizing_policy.get("effective_sizing_base_usd") or 0.0
    )
    current_simulated_equity = actuals.get("current_value_usd")
    return {
        "execution_mode": "paper_simulation",
        "policy_authority": "paper_config.json",
        "enabled": bool(cfg.get("enabled")),
        "current_cohort_label": cfg.get("current_cohort_label"),
        "current_cohort_started_at": cfg.get("current_cohort_started_at"),
        "active_strategies": sorted(
            key for key in registry
            if key not in disabled and bool(registry[key].get("enabled", True))
        ),
        "disabled_strategies": sorted(disabled),
        "strategy_cooldowns": cfg.get("_strategy_cooldowns") or {},
        "risk_pct_per_trade": float(cfg.get("risk_pct_per_trade", 5.0) or 5.0),
        "max_open_positions": int(cfg.get("max_open_positions", 5) or 5),
        "flow_required": bool(cfg.get("flow_required", True)),
        "min_flow_score": float(cfg.get("min_flow_score", 50.0) or 50.0),
        "sizing_mode": sizing_policy.get("mode"),
        "fixed_sizing_base_usd": sizing_policy.get("fixed_base_usd"),
        "sizing_balance_usd": sizing_balance,
        "current_simulated_equity_usd": current_simulated_equity,
        "sizing_compounds_simulated_equity": (
            sizing_policy.get("mode") == "compound_realized"
        ),
        "sizing_policy": sizing_policy,
        "sizing_note": sizing_policy.get("reason"),
        "hard_notional_caps_usd": {
            tier: round(sizing_balance * fraction, 2)
            for tier, fraction in HARD_NOTIONAL_CAPS_BY_LIQUIDITY_TIER.items()
        },
        "effective_conviction_thresholds": effective_thresholds,
    }


def _hermes_readiness_context(actuals: dict) -> dict:
    target = int(
        actuals.get("paper_cohort_readiness_target")
        or PAPER_READINESS_MIN_TRADES
    )
    return {
        "authority": "MT7 hard promotion gates",
        "hermes_can_override": False,
        "paper_policy_ready": bool(actuals.get("scale_up_ready")),
        "live_trading_default": "disabled",
        "current_cohort_sample_n": int(
            actuals.get("paper_cohort_sample_n") or 0
        ),
        "current_cohort_target_n": target,
        "current_cohort_win_partial_rate_pct": actuals.get(
            "paper_cohort_win_partial_rate"
        ),
        "current_cohort_ev_per_trade_pct": actuals.get(
            "paper_cohort_avg_pnl"
        ),
        "current_cohort_avg_pnl_usd": actuals.get(
            "paper_cohort_avg_pnl_usd"
        ),
        "current_cohort_profit_factor_usd": actuals.get(
            "paper_cohort_profit_factor"
        ),
        "current_cohort_leave_best_out_total_pnl_usd": actuals.get(
            "paper_cohort_leave_best_out_total_pnl_usd"
        ),
        "current_cohort_max_drawdown_pct": actuals.get(
            "paper_cohort_max_drawdown_pct"
        ),
        "rolling_windows": actuals.get("paper_cohort_rolling_windows") or {},
        "blockers": list(actuals.get("scale_up_blockers") or []),
        "decision_rule": (
            "Do not recommend scaling, assisted live, or higher risk until "
            "paper_policy_ready is true. A smaller Hermes sample target does "
            "not supersede MT7's 50-trade minimum."
        ),
    }


def _hermes_suggestion_audit() -> dict:
    suggestions = _annotate_suggestion_authority(_load_suggestions())
    counts: dict[str, int] = {}
    for s in suggestions:
        status = s.get("status") or "unknown"
        counts[status] = counts.get(status, 0) + 1
    active = [s for s in suggestions if s.get("status") in {"pending", "pending_review", "evaluating", "shadow_evaluating"}]
    applied_evaluating = [s for s in active if s.get("status") == "evaluating"]
    parallel_shadow = [
        s for s in active
        if s.get("status") in {"pending", "pending_review", "shadow_evaluating"}
        and not s.get("state_conflict")
    ]
    authority_conflicts = [s for s in suggestions if s.get("state_conflict")]
    baseline_conflicts = [
        s for s in suggestions
        if s.get("baseline_conflict")
        and s.get("status") in {
            "pending", "pending_review", "shadow_evaluating", "evaluating"
        }
    ]
    warnings = []
    if len(applied_evaluating) > 1:
        warnings.append("More than one applied config evaluation is active; attribution is compromised.")
    if len(parallel_shadow) > 2:
        warnings.append("More than two shadow/pending learner ideas are active; resolve the oldest before adding new hypotheses.")
    if authority_conflicts:
        warnings.append("Suggestion labels disagree with active strategy overrides; reconcile authority before trusting learner attribution.")
    if baseline_conflicts:
        warnings.append(
            "One or more learner proposals were optimized from a stale "
            "current-value baseline. Recompute them from runtime_actual before "
            "starting or applying an evaluation."
        )
    return {
        "learner_running": _learner_running(),
        "counts": counts,
        "active": active[:5],
        "applied_evaluating_count": len(applied_evaluating),
        "parallel_shadow_count": len(parallel_shadow),
        "authority_conflict_count": len(authority_conflicts),
        "authority_conflict_ids": [s.get("id") for s in authority_conflicts],
        "baseline_conflict_count": len(baseline_conflicts),
        "baseline_conflict_ids": [s.get("id") for s in baseline_conflicts],
        "warnings": warnings,
        "total": len(suggestions),
    }


def _hermes_recommendation(packet: dict) -> dict:
    paper = packet.get("paper") or {}
    live = (packet.get("signals") or {}).get("recent_30d") or {}
    suggestions = packet.get("suggestions") or {}
    readiness = packet.get("readiness") or {}

    cohort_n = int(readiness.get("current_cohort_sample_n") or 0)
    cohort_target = int(
        readiness.get("current_cohort_target_n")
        or PAPER_READINESS_MIN_TRADES
    )
    if cohort_n < cohort_target:
        return {
            "title": "Extend the isolated Paper policy cohort",
            "hypothesis": "The current execution policy cannot be judged from a partial cohort, regardless of older aggregate Paper results.",
            "experiment": f"Keep the current Paper policy unchanged until it reaches {cohort_target} closed trades and clears every MT7 readiness gate.",
            "success_metric": (
                f"{cohort_target} closed current-policy trades, W+P >= "
                f"{PAPER_READINESS_WP_FLOOR_PCT:.0f}%, dollar PF >= "
                f"{PAPER_READINESS_PF_FLOOR:.2f}, positive trimmed EV, "
                "positive P&L after removing the best winner, and stable 20/50 windows."
            ),
            "do_not_change": "Do not activate assisted live, raise risk, or substitute all-time Paper history for the isolated current-policy cohort.",
        }

    if int(suggestions.get("baseline_conflict_count") or 0) > 0:
        return {
            "title": "Recompute stale learner proposal baselines",
            "hypothesis": "A threshold proposal cannot be attributed correctly when its claimed current value differs from the runtime strategy value.",
            "experiment": "Regenerate each conflicting proposal from runtime_actual, then evaluate the new threshold as a read-only counterfactual before any config mutation.",
            "success_metric": "The learner proposal current value equals runtime_actual and the evaluation has a frozen source, strategy, regime, and outcome window.",
            "do_not_change": "Do not apply or start the stale proposal as written.",
        }

    if int(suggestions.get("parallel_shadow_count") or 0) > 2 or int(suggestions.get("applied_evaluating_count") or 0) > 0:
        return {
            "title": "Resolve the learner queue before adding hypotheses",
            "hypothesis": "Attribution quality improves when applied experiments are serial and shadow experiments are capped.",
            "experiment": "Promote, reject, park, or finish the two oldest active learner items before registering any new Hermes idea.",
            "success_metric": "At most two read-only shadows and zero stuck applied evaluations remain active.",
            "do_not_change": "Do not let Hermes or Cipher register another config experiment while learner attribution is already crowded.",
        }
    paper_pf = paper.get("profit_factor_usd")
    if (
        (paper.get("ev_per_trade_pct") is not None and paper.get("ev_per_trade_pct") < 0)
        or (paper_pf is not None and float(paper_pf or 0) < 1.0)
    ):
        return {
            "title": "Run a volatility/liquidity filter experiment on paper only",
            "hypothesis": "Paper bot losses may be coming from tradeability gaps rather than the broad signal engine.",
            "experiment": "Use the liquidity gate in shadow mode or paper-only mode for micro/thin symbols, then compare EV, profit factor, and trade count.",
            "success_metric": "Paper EV improves by at least 3 percentage points and profit factor clears 1.0 without cutting trade count by more than 40%.",
            "do_not_change": "Do not blend paper outcomes into live signal EV when judging this experiment.",
        }
    if suggestions.get("active"):
        return {
            "title": "Resolve the active learner queue before adding new hypotheses",
            "hypothesis": "A clean one-change-at-a-time loop is more valuable than adding research complexity.",
            "experiment": "Apply, reject, or finish evaluation of the active learner suggestion, then capture before/after EV.",
            "success_metric": "Every applied change has a baseline, evaluation window, and explicit keep/revert decision.",
            "do_not_change": "Do not let Hermes propose a second config experiment while mt-learner has one active.",
        }
    return {
        "title": "Create one shadow experiment from external research",
        "hypothesis": "Hermes Research can improve MT7 if every outside idea is converted into a measurable shadow tag first.",
        "experiment": "Add one research-queue item with data requirements, a shadow tag, and a 50-signal evaluation plan.",
        "success_metric": "The hypothesis is testable with MT7/MEXC/Hyperliquid data and does not require live execution changes.",
        "do_not_change": "Do not modify thresholds or sizing from academic/industry research until the shadow dataset validates it.",
    }


def _build_hermes_audit() -> dict:
    goals = _load_goals()
    actuals = _compute_goal_actuals(goals)
    packet: dict = {
        "generated_at": datetime.utcnow().isoformat(),
        "mode": "mt7_context_packet",
        "data_contract_version": "hermes_metrics_v3_coach_intelligence",
        "consultancy": _hermes_consultancy_profile(),
        "latest_memo": _hermes_latest_memo(),
        "memo_archive": _hermes_memo_archive(),
        "goals": goals,
        "goal_actuals": actuals,
        "metric_provenance": _hermes_metric_provenance(),
        "edge_lab": _hermes_edge_lab_meta(),
        "cipher_reports": _hermes_latest_report_meta(),
        "suggestions": _hermes_suggestion_audit(),
        "research": _hermes_research_queue(),
        "blindspots": [
            "Paper trades and live-tagged signals are different data streams and must not be blended.",
            "Small samples can be dominated by a few outlier meme-token wins or losses.",
            "Cipher narratives can sound useful without proving they improved EV.",
            "Edge Lab findings are research priors, not permission to change live scoring.",
            "With a small account, sizing and drawdown control matter as much as signal accuracy.",
        ],
    }
    packet["paper_policy"] = _hermes_paper_policy_context(goals, actuals)
    packet["readiness"] = _hermes_readiness_context(actuals)
    packet["decision_authority"] = {
        "hermes_role": "outside_read_only_advisor",
        "trading_authority": "none",
        "paper_readiness_authority": "MT7 hard promotion gates",
        "source_live_semantics": (
            "History/live signal-evaluator outcomes. These are not proof of "
            "executed brokerage fills or realized account P&L."
        ),
        "paper_semantics": (
            "Simulated execution using paper_trades. Only explicitly named "
            "USD fields may be compared with simulated Paper equity."
        ),
        "prohibited_inferences": [
            "Never format total_pnl_pct as USD.",
            "Never blend disabled_shadow with source live.",
            "Never label an all-time query as a 30-day cohort.",
            "Never infer position risk from current simulated equity when Paper sizing uses a fixed configured balance.",
            "Never override the MT7 current-policy 50-trade readiness minimum.",
        ],
    }
    packet["capability_contract"] = {
        "flow_confirmation": {
            "implemented": True,
            "fields": ["flow_score", "flow_confirmed"],
            "paper_required": bool(
                packet.get("paper_policy", {}).get("flow_required")
            ),
            "instruction": "Evaluate existing flow cohorts; do not recommend implementing flow tags as if they are missing.",
        },
        "disabled_strategy_shadow": {
            "implemented": True,
            "source_lane": "disabled_shadow",
            "execution_impact": "none",
            "momentum_breakout_disabled_in_paper": (
                "momentum_breakout"
                in set(packet.get("paper_policy", {}).get("disabled_strategies") or [])
            ),
        },
        "symbol_loss_gate": {
            "implemented": True,
            "window": "30 days",
            "unit": "cumulative pnl_pct on source live",
            "instruction": "Any proposed dollar risk budget is an extension, not a missing-control fix.",
        },
        "paper_cooldowns": {
            "implemented": True,
            "behavior": "automatic Paper safety control",
            "instruction": "Do not invent an ADL, venue-stress, or manual trigger reason unless the packet supplies one.",
        },
        "live_execution": {
            "master_gate_enabled": bool(LIVE_TRADING_ENABLED),
            "silent_automation": False,
        },
        "paper_risk_semantics": {
            "risk_pct_is_sizing_input": True,
            "guaranteed_realized_loss_cap": False,
            "instruction": (
                "Do not call account_balance_usd * risk_pct_per_trade a hard "
                "maximum loss. Leverage, gaps, modeled exits, and slippage can "
                "produce a different realized Paper loss; use worst_trades "
                "and explicit pnl_usd fields for observed loss claims."
            ),
        },
    }
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        packet["signals"] = _hermes_signal_audit(con)
        packet["paper"] = _hermes_paper_audit(con)
        packet["symbol_risk"] = _hermes_symbol_risk_audit(con)
        packet["sizing_integrity"] = _paper_sizing_integrity_payload(lookback_days=60, con=con)
        con.close()
    except Exception as e:
        print(f"[hermes] db audit: {e}", file=sys.stderr)
        packet["signals"] = {"error": str(e)}
        packet["paper"] = {"error": str(e)}
        packet["symbol_risk"] = {"error": str(e)}
        packet["sizing_integrity"] = {"error": str(e)}

    live_ev = (packet.get("signals") or {}).get("recent_30d", {}).get("ev_per_trade_pct")
    paper_ev = (packet.get("paper") or {}).get("ev_per_trade_pct")
    score = 50
    if live_ev is not None:
        score += 15 if live_ev > 0 else -15
    if paper_ev is not None:
        score += 15 if paper_ev > 0 else -15
    if actuals.get("kill_switch_breached"):
        score -= 25
    if packet["suggestions"].get("active"):
        score -= 5
    packet["health_score"] = max(0, min(100, score))
    packet["health_score_contract"] = {
        "type": "coarse_directional_heuristic",
        "promotion_authority": False,
        "method": (
            "Starts at 50, adds or subtracts directional live/Paper EV points, "
            "then applies kill-switch and active-suggestion adjustments."
        ),
        "note": (
            "Do not interpret this score as a probability of profitability or "
            "as permission to scale. Use readiness.paper_policy_ready."
        ),
    }
    packet["recommendation"] = _hermes_recommendation(packet)
    packet["risk_warning"] = (
        "Do not fund or scale live automation from this MT7 context packet alone. The Hermes agent must remain an outside consultant, not an execution authority."
    )
    return packet


_hermes_audit_cache_lock = threading.Lock()
_hermes_audit_cache: dict = {"built_at": 0.0, "packet": None}
# Hermes reads several thousand resolved reviews and multiple advisory feeds.
# Data-changing routes explicitly invalidate this cache, while the UI exposes a
# forced refresh. Keep routine navigation cheap without hiding fresh mutations.
HERMES_AUDIT_CACHE_SECONDS = 300


def _invalidate_hermes_audit_cache() -> None:
    with _hermes_audit_cache_lock:
        _hermes_audit_cache.update({"built_at": 0.0, "packet": None})


def _load_hermes_audit_cached(force: bool = False) -> dict:
    now = time.time()
    with _hermes_audit_cache_lock:
        packet = _hermes_audit_cache.get("packet")
        age = max(0.0, now - float(_hermes_audit_cache.get("built_at") or 0.0))
        if not force and packet is not None and age < HERMES_AUDIT_CACHE_SECONDS:
            cached = copy.deepcopy(packet)
            cached["cache"] = {
                "status": "hit",
                "age_seconds": round(age, 1),
                "ttl_seconds": HERMES_AUDIT_CACHE_SECONDS,
            }
            return cached
        packet = _build_hermes_audit()
        _hermes_audit_cache.update({"built_at": time.time(), "packet": packet})
        built = copy.deepcopy(packet)
        built["cache"] = {
            "status": "rebuilt",
            "age_seconds": 0.0,
            "ttl_seconds": HERMES_AUDIT_CACHE_SECONDS,
        }
        return built


