def _hypothesis_stats(rows: list[dict]) -> dict:
    closed = [
        r for r in rows
        if str(r.get("result") or "").upper() in ("WIN", "LOSS", "PARTIAL", "TP3")
        and r.get("pnl_pct") is not None
    ]
    wins = [r for r in closed if str(r.get("result") or "").upper() in ("WIN", "TP3")]
    partials = [r for r in closed if str(r.get("result") or "").upper() == "PARTIAL"]
    pnls = [float(r.get("pnl_pct") or 0.0) for r in closed]
    pnl_usd = []
    for r in closed:
        if r.get("pnl_usd") is not None:
            try:
                pnl_usd.append(float(r.get("pnl_usd") or 0.0))
                continue
            except Exception:
                pass
        if r.get("size_usd") is not None:
            pnl_usd.append(_paper_trade_pnl_usd(r))
    pf_basis = pnl_usd if pnl_usd else pnls
    gains = [x for x in pf_basis if x > 0]
    losses = [abs(x) for x in pf_basis if x < 0]
    return {
        "count": len(closed),
        "wins": len(wins),
        "partials": len(partials),
        "losses": len([r for r in closed if str(r.get("result") or "").upper() == "LOSS"]),
        "win_partial_rate": round((len(wins) + len(partials)) / len(closed) * 100, 1) if closed else 0,
        "avg_pnl": round(sum(pnls) / len(pnls), 2) if pnls else 0,
        "total_pnl": round(sum(pnls), 2) if pnls else 0,
        "total_pnl_usd": round(sum(pnl_usd), 2) if pnl_usd else None,
        "profit_factor": round(sum(gains) / sum(losses), 2) if losses else (round(sum(gains), 2) if gains else 0),
    }


def _row_matches_hypothesis(row: dict, hypothesis: dict) -> bool:
    strategy = hypothesis.get("strategy")
    if strategy and str(row.get("strategy_key") or "") != strategy:
        return False
    regime = hypothesis.get("agent_regime")
    if regime and str(row.get("agent_regime") or "") != regime:
        return False
    if "requires_flow_confirmed" in hypothesis:
        return bool(row.get("flow_confirmed")) is bool(hypothesis.get("requires_flow_confirmed"))
    return True


def _hypothesis_verdict(affected: dict, unaffected: dict, target: int) -> dict:
    n = int(affected.get("count") or 0)
    avg = float(affected.get("avg_pnl") or 0.0)
    wp = float(affected.get("win_partial_rate") or 0.0)
    base_avg = float(unaffected.get("avg_pnl") or 0.0)
    if n < target:
        status = "collecting"
        label = "Collecting"
        color = "blue"
        detail = f"{n}/{target} affected closed samples."
    elif avg < 0 and avg < base_avg:
        status = "promote_candidate"
        label = "Promote Candidate"
        color = "green"
        detail = "Affected slice is negative EV and worse than the comparison slice."
    elif avg < base_avg or wp < 50:
        status = "review"
        label = "Review"
        color = "amber"
        detail = "Affected slice is weaker, but not clean enough to promote automatically."
    else:
        status = "do_not_promote"
        label = "Do Not Promote"
        color = "red"
        detail = "Affected slice is not underperforming enough to justify a block."
    return {"status": status, "label": label, "color": color, "detail": detail}


def _suggestion_shadow_rows(con: sqlite3.Connection, since: str | None = None) -> dict[str, list[dict]]:
    signal_cols = {r[1] for r in con.execute("PRAGMA table_info(signals)").fetchall()}
    paper_cols = {r[1] for r in con.execute("PRAGMA table_info(paper_trades)").fetchall()}
    live_flow_expr = "flow_confirmed" if "flow_confirmed" in signal_cols else "NULL"
    paper_flow_expr = "pt.flow_confirmed" if "flow_confirmed" in paper_cols else "NULL"
    paper_pnl_usd_expr = "pt.pnl_usd" if "pnl_usd" in paper_cols else "NULL"
    paper_size_expr = "pt.size_usd" if "size_usd" in paper_cols else "NULL"
    live_where = """
        result IN ('WIN','LOSS','PARTIAL','TP3')
        AND pnl_pct IS NOT NULL
        AND (source IS NULL OR source != 'paper')
    """
    live_params = []
    if since:
        live_where += " AND COALESCE(result_at, entry_at, logged_at, '') >= ?"
        live_params.append(str(since))
    live_rows = [dict(r) for r in con.execute(f"""
        SELECT id, symbol, strategy_key, direction, result, pnl_pct, tags,
               conviction, COALESCE(result_at, entry_at, logged_at) as ts,
               json_extract(signal_json, '$.agent_regime') as agent_regime,
               json_extract(signal_json, '$.volatility_regime') as volatility_regime,
               COALESCE({live_flow_expr}, CASE
                   WHEN (',' || COALESCE(tags,'') || ',') LIKE '%,flow_confirmed,%' THEN 1
                   ELSE 0
               END) as flow_confirmed
        FROM signals
        WHERE {live_where}
        ORDER BY ts DESC
        LIMIT 5000
    """, live_params).fetchall()]

    paper_where = "pt.status='closed' AND pt.pnl_pct IS NOT NULL"
    paper_params = []
    if since:
        paper_where += " AND COALESCE(pt.closed_at, pt.opened_at, pt.queued_at, '') >= ?"
        paper_params.append(str(since))
    paper_rows = [dict(r) for r in con.execute(f"""
        SELECT pt.id, pt.symbol, pt.strategy_key, pt.direction, pt.result,
               pt.pnl_pct, {paper_pnl_usd_expr} as pnl_usd,
               {paper_size_expr} as size_usd, COALESCE(pt.leverage, 1) as leverage,
               pt.conviction, {paper_flow_expr} as flow_confirmed,
               COALESCE(pt.closed_at, pt.opened_at, pt.queued_at) as ts,
               json_extract(s.signal_json, '$.agent_regime') as agent_regime,
               json_extract(s.signal_json, '$.volatility_regime') as volatility_regime
        FROM paper_trades pt
        LEFT JOIN signals s ON s.id = pt.signal_id
        WHERE {paper_where}
        ORDER BY ts DESC
        LIMIT 5000
    """, paper_params).fetchall()]
    return {"live": live_rows, "paper": paper_rows}


def _row_matches_suggestion_shadow(row: dict, suggestion: dict) -> bool:
    strategy = suggestion.get("strategy")
    if strategy and str(row.get("strategy_key") or "") != str(strategy):
        return False
    stype = suggestion.get("type")
    payload = suggestion.get("api_payload") or {}
    if stype == "threshold":
        try:
            threshold = float(suggestion.get("suggested_value") or payload.get("min_conviction"))
            conviction = float(row.get("conviction") or 0)
            return conviction < threshold
        except Exception:
            return False
    if stype == "regime_suppress":
        blocked = _normalize_agent_regime_list(payload.get("blocked_agent_regimes"))
        regime = str(suggestion.get("regime") or "").strip().lower()
        if regime and regime not in blocked:
            blocked.append(regime)
        allowed = payload.get("allowed_volatility")
        if blocked:
            return str(row.get("agent_regime") or "").strip().lower() in blocked
        if isinstance(allowed, list) and allowed:
            return str(row.get("volatility_regime") or "").strip().lower() not in {
                str(v).strip().lower() for v in allowed
            }
    return False


def _suggestion_shadow_title(suggestion: dict) -> str:
    stype = suggestion.get("type")
    strategy = suggestion.get("strategy") or "strategy"
    if stype == "threshold":
        return f"{strategy}: threshold >= {suggestion.get('suggested_value') or (suggestion.get('api_payload') or {}).get('min_conviction')}"
    if stype == "regime_suppress":
        regime = suggestion.get("regime") or ", ".join((suggestion.get("api_payload") or {}).get("blocked_agent_regimes") or [])
        return f"{strategy}: suppress {regime or 'weak regime'}"
    return suggestion.get("evidence_summary") or suggestion.get("id") or "Learner suggestion"


def _suggestion_shadow_verdict(affected: dict, comparison: dict, target: int, suggestion: dict) -> dict:
    n = int(affected.get("count") or 0)
    avg = float(affected.get("avg_pnl") or 0.0)
    wp = float(affected.get("win_partial_rate") or 0.0)
    base_avg = float(comparison.get("avg_pnl") or 0.0)
    if n < target:
        return {
            "status": "collecting",
            "label": "Collecting",
            "color": "blue",
            "evidence_ready": False,
            "recommendation": "keep_collecting",
            "detail": f"{n}/{target} affected closed samples.",
        }
    if avg < 0 and avg < base_avg:
        return {
            "status": "ready_to_promote",
            "label": "Ready To Promote",
            "color": "green",
            "evidence_ready": True,
            "recommendation": "promote",
            "detail": "Would-have affected slice is negative EV and worse than the comparison slice.",
        }
    if avg < base_avg or wp < 50:
        return {
            "status": "review",
            "label": "Review",
            "color": "amber",
            "evidence_ready": True,
            "recommendation": "manual_review",
            "detail": "Affected slice is weaker, but the edge is not clean enough to promote automatically.",
        }
    return {
        "status": "do_not_promote",
        "label": "Do Not Promote",
        "color": "red",
        "evidence_ready": True,
        "recommendation": "reject",
        "detail": "Affected slice is not underperforming enough to justify applying this suggestion.",
    }


def _evaluate_suggestions_shadow(suggestions: list[dict], target: int, since: str | None = None) -> dict:
    candidates = [
        s for s in suggestions
        if s.get("status") in {"pending", "pending_review", "shadow_evaluating"}
        and s.get("type") in {"threshold", "regime_suppress"}
        and not s.get("state_conflict")
    ]
    if not candidates:
        return {
            "target": target,
            "items": [],
            "summary": {
                "suggestion_count": 0,
                "parallel_shadow_count": 0,
                "ready_to_promote_count": 0,
                "review_count": 0,
                "collecting_count": 0,
                "reject_recommended_count": 0,
                "paper_closed": 0,
                "live_closed": 0,
                "status_counts": {},
            },
        }
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        rows_by_source = _suggestion_shadow_rows(con, since=since)
    finally:
        con.close()
    items = []
    for suggestion in candidates:
        source_payload = {}
        for source_name, rows in rows_by_source.items():
            strategy = str(suggestion.get("strategy") or "")
            affected = [r for r in rows if _row_matches_suggestion_shadow(r, suggestion)]
            comparison = [
                r for r in rows
                if (not strategy or str(r.get("strategy_key") or "") == strategy)
                and not _row_matches_suggestion_shadow(r, suggestion)
            ]
            affected_stats = _hypothesis_stats(affected)
            comparison_stats = _hypothesis_stats(comparison)
            source_payload[source_name] = {
                "affected": affected_stats,
                "comparison": comparison_stats,
                "delta": {
                    "avg_pnl": round(affected_stats["avg_pnl"] - comparison_stats["avg_pnl"], 2),
                    "win_partial_rate": round(affected_stats["win_partial_rate"] - comparison_stats["win_partial_rate"], 1),
                },
                "recent_affected": affected[:8],
                "verdict": _suggestion_shadow_verdict(affected_stats, comparison_stats, target, suggestion),
            }
        primary = source_payload["paper"] if source_payload["paper"]["affected"]["count"] else source_payload["live"]
        items.append({
            "suggestion_id": suggestion.get("id"),
            "title": _suggestion_shadow_title(suggestion),
            "status": suggestion.get("status"),
            "lane": "shadow",
            "type": suggestion.get("type"),
            "strategy": suggestion.get("strategy"),
            "target": target,
            "expected": suggestion.get("expected_ev_label") or suggestion.get("expected_net_ev_delta") or suggestion.get("expected_trade_count_delta"),
            "sources": source_payload,
            "primary_verdict": primary["verdict"],
        })
    status_counts = defaultdict(int)
    for item in items:
        status_counts[str((item.get("primary_verdict") or {}).get("status") or "unknown")] += 1
    items.sort(key=lambda item: {
        "ready_to_promote": 0,
        "review": 1,
        "collecting": 2,
        "do_not_promote": 3,
    }.get(str((item.get("primary_verdict") or {}).get("status") or ""), 4))
    return {
        "target": target,
        "items": items,
        "summary": {
            "suggestion_count": len(items),
            "parallel_shadow_count": len(items),
            "ready_to_promote_count": int(status_counts.get("ready_to_promote", 0)),
            "review_count": int(status_counts.get("review", 0)),
            "collecting_count": int(status_counts.get("collecting", 0)),
            "reject_recommended_count": int(status_counts.get("do_not_promote", 0)),
            "paper_closed": len(rows_by_source.get("paper") or []),
            "live_closed": len(rows_by_source.get("live") or []),
            "status_counts": dict(status_counts),
        },
    }


@app.route("/api/intelligence/hypotheses")
def api_intelligence_hypotheses():
    """Evaluate multiple shadow hypotheses in parallel without mutating config."""
    try:
        target = int(request.args.get("target") or 50)
        since = request.args.get("since")
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        live_where = """
            result IN ('WIN','LOSS','PARTIAL','TP3')
            AND pnl_pct IS NOT NULL
            AND (source IS NULL OR source != 'paper')
        """
        live_params = []
        if since:
            live_where += " AND COALESCE(result_at, entry_at, logged_at, '') >= ?"
            live_params.append(str(since))
        signal_cols = {r[1] for r in con.execute("PRAGMA table_info(signals)").fetchall()}
        paper_cols = {r[1] for r in con.execute("PRAGMA table_info(paper_trades)").fetchall()}
        live_flow_expr = "flow_confirmed" if "flow_confirmed" in signal_cols else "NULL"
        paper_flow_expr = "pt.flow_confirmed" if "flow_confirmed" in paper_cols else "NULL"
        paper_pnl_usd_expr = "pt.pnl_usd" if "pnl_usd" in paper_cols else "NULL"
        paper_size_expr = "pt.size_usd" if "size_usd" in paper_cols else "NULL"
        live_rows = [dict(r) for r in con.execute(f"""
            SELECT id, symbol, strategy_key, direction, result, pnl_pct, tags,
                   COALESCE(result_at, entry_at, logged_at) as ts,
                   json_extract(signal_json, '$.agent_regime') as agent_regime,
                   COALESCE({live_flow_expr}, CASE
                       WHEN (',' || COALESCE(tags,'') || ',') LIKE '%,flow_confirmed,%' THEN 1
                       ELSE 0
                   END) as flow_confirmed
            FROM signals
            WHERE {live_where}
            ORDER BY ts DESC
            LIMIT 5000
        """, live_params).fetchall()]

        paper_where = "pt.status='closed' AND pt.pnl_pct IS NOT NULL"
        paper_params = []
        if since:
            paper_where += " AND COALESCE(pt.closed_at, pt.opened_at, pt.queued_at, '') >= ?"
            paper_params.append(str(since))
        paper_rows = [dict(r) for r in con.execute(f"""
            SELECT pt.id, pt.symbol, pt.strategy_key, pt.direction, pt.result,
                   pt.pnl_pct, {paper_pnl_usd_expr} as pnl_usd,
                   {paper_size_expr} as size_usd, COALESCE(pt.leverage, 1) as leverage,
                   {paper_flow_expr} as flow_confirmed,
                   COALESCE(pt.closed_at, pt.opened_at, pt.queued_at) as ts,
                   json_extract(s.signal_json, '$.agent_regime') as agent_regime
            FROM paper_trades pt
            LEFT JOIN signals s ON s.id = pt.signal_id
            WHERE {paper_where}
            ORDER BY ts DESC
            LIMIT 5000
        """, paper_params).fetchall()]
        con.close()

        rows_by_source = {"live": live_rows, "paper": paper_rows}
        evaluated = []
        for hypothesis in PARALLEL_HYPOTHESES:
            source_payload = {}
            for source_name, rows in rows_by_source.items():
                affected = [r for r in rows if _row_matches_hypothesis(r, hypothesis)]
                comparison = [
                    r for r in rows
                    if str(r.get("strategy_key") or "") == str(hypothesis.get("strategy") or "")
                    and not _row_matches_hypothesis(r, hypothesis)
                ]
                affected_stats = _hypothesis_stats(affected)
                comparison_stats = _hypothesis_stats(comparison)
                source_payload[source_name] = {
                    "affected": affected_stats,
                    "comparison": comparison_stats,
                    "delta": {
                        "avg_pnl": round(affected_stats["avg_pnl"] - comparison_stats["avg_pnl"], 2),
                        "win_partial_rate": round(affected_stats["win_partial_rate"] - comparison_stats["win_partial_rate"], 1),
                    },
                    "recent_affected": affected[:8],
                    "verdict": _hypothesis_verdict(affected_stats, comparison_stats, target),
                }
            primary = source_payload["paper"] if source_payload["paper"]["affected"]["count"] else source_payload["live"]
            evaluated.append({
                **hypothesis,
                "target": target,
                "sources": source_payload,
                "primary_verdict": primary["verdict"],
            })

        return jsonify({
            "success": True,
            "target": target,
            "since": since,
            "mode": "parallel_shadow",
            "summary": {
                "hypothesis_count": len(evaluated),
                "live_closed": len(live_rows),
                "paper_closed": len(paper_rows),
            },
            "hypotheses": evaluated,
        })
    except Exception as e:
        print(f"[api/intelligence/hypotheses] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


def _apply_suggestion_config(suggestion: dict) -> tuple[bool, str | None]:
    stype = suggestion.get("type")
    payload = suggestion.get("api_payload") or {}
    strategy_key = suggestion.get("strategy")

    try:
        existing_control = _suggestion_effective_control(suggestion)
        if existing_control.get("managed") and existing_control.get("active"):
            return False, (
                "the exact control is already active; reconcile its current owner "
                "instead of starting a duplicate applied trial"
            )
        if stype == "new_strategy":
            with app.test_client() as c:
                r = c.post(
                    "/api/strategies/custom",
                    data=json.dumps(payload),
                    content_type="application/json",
                )
            if r.status_code not in (200, 201):
                return False, "failed to create strategy"
            return True, None

        if stype == "threshold":
            if not strategy_key:
                return False, "strategy missing"
            min_conviction = payload.get("min_conviction")
            if min_conviction is None:
                return False, "min_conviction missing from payload"
            if strategy_key in STRATEGIES:
                _save_strategy_override(strategy_key, "min_conviction", int(min_conviction))
            else:
                with app.test_client() as c:
                    r = c.patch(
                        f"/api/strategies/custom/{strategy_key}",
                        data=json.dumps({"min_conviction": int(min_conviction)}),
                        content_type="application/json",
                    )
                if r.status_code not in (200, 201):
                    return False, "failed to update custom strategy threshold"
            return True, None

        if stype == "regime_suppress":
            if not strategy_key:
                return False, "strategy missing"
            valid = {"low", "medium", "high", "extreme"}
            blocked = _normalize_agent_regime_list(payload.get("blocked_agent_regimes"))
            regime = str(suggestion.get("regime") or "").strip().lower()
            if not blocked and regime and regime not in valid:
                blocked = _normalize_agent_regime_list([regime])

            if blocked:
                if strategy_key in STRATEGIES:
                    current_override = _load_strategy_overrides().get(strategy_key, {})
                    existing_blocked = _normalize_agent_regime_list(current_override.get("blocked_agent_regimes"))
                else:
                    current_cfg = get_strategy_config(strategy_key, include_disabled=True)
                    existing_blocked = _normalize_agent_regime_list(current_cfg.get("blocked_agent_regimes"))
                merged_blocked = existing_blocked + [r for r in blocked if r not in existing_blocked]
                if strategy_key in STRATEGIES:
                    _save_strategy_override(strategy_key, "blocked_agent_regimes", merged_blocked)
                else:
                    with app.test_client() as c:
                        r = c.patch(
                            f"/api/strategies/custom/{strategy_key}",
                            data=json.dumps({"blocked_agent_regimes": merged_blocked}),
                            content_type="application/json",
                        )
                    if r.status_code not in (200, 201):
                        return False, "failed to update custom strategy agent-regime filter"
                _append_experiment_record({
                    "id": suggestion.get("id"),
                    "type": "regime_suppress",
                    "strategy": strategy_key,
                    "field": "blocked_agent_regimes",
                    "value": merged_blocked,
                    "added": blocked,
                    "evidence_summary": suggestion.get("evidence_summary"),
                    "sample_size": suggestion.get("sample_size"),
                    "baseline": _suggestion_baseline_snapshot(),
                    "applied_at": datetime.utcnow().isoformat(),
                })
                return True, None

            allowed = payload.get("allowed_volatility")
            if not isinstance(allowed, list) or not allowed or any(v not in valid for v in allowed):
                return False, "regime_suppress payload needs blocked_agent_regimes or valid allowed_volatility"
            if strategy_key in STRATEGIES:
                _save_strategy_override(strategy_key, "allowed_volatility", allowed)
            else:
                with app.test_client() as c:
                    r = c.patch(
                        f"/api/strategies/custom/{strategy_key}",
                        data=json.dumps({"allowed_volatility": allowed}),
                        content_type="application/json",
                    )
                if r.status_code not in (200, 201):
                    return False, "failed to update custom strategy volatility filter"
            _append_experiment_record({
                "id": suggestion.get("id"),
                "type": "regime_suppress",
                "strategy": strategy_key,
                "field": "allowed_volatility",
                "value": allowed,
                "evidence_summary": suggestion.get("evidence_summary"),
                "sample_size": suggestion.get("sample_size"),
                "baseline": _suggestion_baseline_snapshot(),
                "applied_at": datetime.utcnow().isoformat(),
            })
            return True, None

        return False, f"unsupported suggestion type: {stype}"
    except Exception as e:
        return False, str(e)


def _activate_suggestion_learning_trial(
    suggestion: dict,
    contract: dict,
    activated_at: str,
    baseline: dict,
    status_extra: dict | None = None,
) -> tuple[bool, str | None, dict | None]:
    """Bind an applied suggestion to an immutable forward experiment."""
    try:
        experiment = _learning_register_suggestion_experiment(
            suggestion,
            contract,
            baseline,
            activated_at,
        )
    except Exception as e:
        rollback_ok, rollback_error, _ = _revert_suggestion_config(suggestion)
        detail = f"learning experiment registration failed: {e}"
        if not rollback_ok:
            detail += f"; config rollback also failed: {rollback_error}"
        return False, detail, None

    extra = {
        "baseline": baseline,
        "applied_at": activated_at,
        "learning_experiment_id": experiment["experiment_id"],
        "learning_policy_fingerprint": experiment["policy_fingerprint"],
        "learning_contract_version": LEARNING_CONTRACT_VERSION,
        **(status_extra or {}),
    }
    if _update_suggestion_status(suggestion.get("id"), "evaluating", extra):
        return True, None, experiment

    rollback_ok, rollback_error, _ = _revert_suggestion_config(suggestion)
    con = sqlite3.connect(DB_PATH)
    try:
        now = datetime.now(timezone.utc).isoformat()
        con.execute(
            """UPDATE learning_experiments
               SET status='cancelled', updated_at=?, result_json=?
               WHERE experiment_id=?""",
            (
                now,
                json.dumps({
                    "reason": "suggestion status update failed",
                    "config_rollback_ok": rollback_ok,
                    "config_rollback_error": rollback_error,
                }),
                experiment["experiment_id"],
            ),
        )
        _learning_append_event(
            con,
            experiment["experiment_id"],
            "cancelled",
            {
                "reason": "suggestion status update failed",
                "config_rollback_ok": rollback_ok,
                "config_rollback_error": rollback_error,
            },
            now,
        )
        con.commit()
    finally:
        con.close()
    return False, "failed to update suggestion after experiment registration", experiment


def _learning_close_suggestion_experiments(
    suggestion_id: str,
    status: str,
    payload: dict | None = None,
) -> list[str]:
    """Close registered experiments without changing strategy authority."""
    if status not in {"rolled_back", "cancelled", "completed"}:
        raise ValueError("invalid terminal learning experiment status")
    con = sqlite3.connect(DB_PATH)
    closed: list[str] = []
    try:
        rows = con.execute(
            """SELECT experiment_id
               FROM learning_experiments
               WHERE source_type='learner_suggestion' AND source_id=?
                 AND status IN ('active','collecting','review','falsified',
                                'promotion_candidate')""",
            (suggestion_id,),
        ).fetchall()
        now = datetime.now(timezone.utc).isoformat()
        for (experiment_id,) in rows:
            con.execute(
                """UPDATE learning_experiments
                   SET status=?, updated_at=?, rollback_required=0
                   WHERE experiment_id=?""",
                (status, now, experiment_id),
            )
            _learning_append_event(
                con,
                experiment_id,
                status,
                {
                    **(payload or {}),
                    "automatic_config_change": False,
                },
                now,
            )
            closed.append(experiment_id)
        con.commit()
    except sqlite3.OperationalError:
        con.rollback()
    finally:
        con.close()
    return closed


