@app.route('/api/intelligence/suggestions')
def api_intelligence_suggestions():
    """Read learner suggestions and annotate with current performance baseline."""
    try:
        suggestions = _load_suggestions()
        evaluating = [s for s in suggestions if s.get('status') == 'evaluating']
        if evaluating:
            try:
                conn = sqlite3.connect(DB_PATH)
                for sug in evaluating:
                    applied_at = (sug.get('baseline') or {}).get('applied_at')
                    strategy = sug.get('strategy')
                    if applied_at and strategy:
                        row = conn.execute(
                            "SELECT COUNT(*) FROM signals WHERE result IN ('WIN','LOSS','PARTIAL')"
                            " AND strategy_key=? AND entry_at>=?",
                            (strategy, applied_at),
                        ).fetchone()
                        sug['trades_since_baseline'] = row[0] if row else 0
                conn.close()
            except Exception:
                pass
        suggestions = _annotate_suggestion_authority(suggestions)
        goals = _load_goals()
        evaluation_window = int(goals.get('evaluation_window_trades') or 20)
        shadow_target = int(request.args.get("shadow_target") or 50)
        shadow_lab = _evaluate_suggestions_shadow(suggestions, shadow_target)
        applied_evaluating = [s for s in suggestions if s.get("status") == "evaluating"]
        applied_busy_strategies = sorted({
            str(s.get("strategy") or "unknown") for s in applied_evaluating
        })
        parallel_shadow = [
            s for s in suggestions
            if s.get("status") in {"pending", "pending_review", "shadow_evaluating"}
            and not s.get("state_conflict")
        ]
        state_conflicts = [s for s in suggestions if s.get("state_conflict")]
        return jsonify({
            'success': True,
            'suggestions': suggestions,
            'baseline': _suggestion_baseline_snapshot(),
            'learner_running': _learner_running(),
            'evaluation_window_trades': evaluation_window,
            'shadow_lab': shadow_lab,
            'workflow': {
                'shadow_mode': 'parallel_read_only',
                'applied_mode': 'serial_per_strategy_parallel_across_strategies',
                'parallel_shadow_count': len(parallel_shadow),
                'applied_evaluating_count': len(applied_evaluating),
                'applied_lane_open': True,
                'applied_busy_strategy_keys': applied_busy_strategies,
                'applied_evaluating_ids': [s.get("id") for s in applied_evaluating],
                'state_conflict_count': len(state_conflicts),
                'state_conflict_ids': [s.get("id") for s in state_conflicts],
                'authority_contract': {
                    'proposed': 'read_only',
                    'shadow_evaluating': 'read_only',
                    'evaluating': 'applied_config_trial',
                    'applied': 'applied_config',
                    'parked': 'read_only',
                    'superseded': 'no_authority',
                    'rejected': 'no_authority',
                },
                'suggestion_contract': {
                    'version': SUGGESTION_CONTRACT_VERSION,
                    'applies_to': 'all_suggestion_types',
                    'auto_apply_allowed': False,
                    'acknowledgement_required': True,
                    'restricted_capital_fields': sorted(_SUGGESTION_CAPITAL_FIELDS),
                    'restricted_execution_fields': sorted(_SUGGESTION_EXECUTION_FIELDS),
                    'restricted_confirmation': 'exact_phrase_required',
                },
            },
        })
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e),
            'suggestions': [],
            'learner_running': _learner_running(),
        }), 500


@app.route('/api/intelligence/suggestions/<suggestion_id>', methods=['PATCH'])
def api_intelligence_suggestion_action(suggestion_id):
    """Backward-compatible apply/dismiss endpoint for older frontend code."""
    data = request.get_json() or {}
    action = data.get('action')
    if action not in ('apply', 'dismiss'):
        return jsonify({'success': False, 'error': 'action must be apply or dismiss'}), 400

    suggestions = _load_suggestions()
    suggestion = next((s for s in suggestions if s.get('id') == suggestion_id), None)
    if not suggestion:
        return jsonify({'success': False, 'error': 'suggestion not found'}), 404

    if action == 'dismiss':
        reason = data.get("reason", "dismissed via legacy PATCH")
        _write_rejected({
            "id": suggestion_id,
            "strategy": suggestion.get("strategy"),
            "type": suggestion.get("type"),
            "suggested_value": suggestion.get("suggested_value") or suggestion.get("regime"),
            "reason": reason,
            "rejected_at": datetime.utcnow().isoformat(),
        })
        if not _update_suggestion_status(suggestion_id, "rejected", {
            "rejected_at": datetime.utcnow().isoformat(),
            "reject_reason": reason,
        }):
            return jsonify({'success': False, 'error': 'failed to update suggestion'}), 500
        return jsonify({'success': True, 'applied': False, 'suggestion_id': suggestion_id})

    allowed, gate_error, contract = _suggestion_application_gate(suggestion, data)
    if not allowed:
        return jsonify({
            "success": False,
            "error": gate_error,
            "explainability": contract,
        }), 409

    evaluating = _suggestion_evaluation_conflicts(suggestions, suggestion)
    if evaluating:
        return jsonify({
            "success": False,
            "error": (
                f"Cannot apply — '{evaluating[0].get('id')}' is already "
                f"evaluating {suggestion.get('strategy') or 'this strategy'}"
            ),
        }), 409

    ok, err = _apply_suggestion_config(suggestion)
    if not ok:
        return jsonify({'success': False, 'error': err}), 400
    applied_at = datetime.utcnow().isoformat()
    baseline = _suggestion_baseline_snapshot()
    baseline["applied_at"] = applied_at
    activated, activation_error, experiment = _activate_suggestion_learning_trial(
        suggestion,
        contract,
        applied_at,
        baseline,
    )
    if not activated:
        return jsonify({'success': False, 'error': activation_error}), 500

    return jsonify({
        'success': True,
        'applied': True,
        'suggestion_id': suggestion_id,
        'baseline': baseline,
        'learning_experiment': experiment,
    })


@app.route("/api/intelligence/suggestions/<suggestion_id>/apply", methods=["POST"])
def api_suggestion_apply(suggestion_id):
    try:
        body = request.get_json(silent=True) or {}
        suggestions = _load_suggestions()
        suggestion = next((s for s in suggestions if s.get("id") == suggestion_id), None)
        if not suggestion:
            return jsonify({"success": False, "error": "Suggestion not found"}), 404
        evaluating = _suggestion_evaluation_conflicts(suggestions, suggestion)
        if evaluating:
            return jsonify({
                "success": False,
                "error": (
                    f"Cannot apply — '{evaluating[0].get('id')}' is already "
                    f"evaluating {suggestion.get('strategy') or 'this strategy'}"
                ),
            }), 409
        if suggestion.get("status") not in {"pending_review", "pending"}:
            return jsonify({
                "success": False,
                "error": f"Status is {suggestion.get('status')}, not pending_review",
            }), 409

        allowed, gate_error, contract = _suggestion_application_gate(suggestion, body)
        if not allowed:
            return jsonify({
                "success": False,
                "error": gate_error,
                "explainability": contract,
            }), 409

        ok, err = _apply_suggestion_config(suggestion)
        if not ok:
            return jsonify({"success": False, "error": err}), 400

        applied_at = datetime.utcnow().isoformat()
        baseline = _suggestion_baseline_snapshot()
        baseline["applied_at"] = applied_at
        activated, activation_error, experiment = _activate_suggestion_learning_trial(
            suggestion,
            contract,
            applied_at,
            baseline,
        )
        if not activated:
            return jsonify({"success": False, "error": activation_error}), 500
        return jsonify({
            "success": True,
            "applied": suggestion_id,
            "baseline": baseline,
            "learning_experiment": experiment,
        })
    except Exception as e:
        print(f"[api/suggestion/apply] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/intelligence/suggestions/<suggestion_id>/promote", methods=["POST"])
def api_suggestion_promote(suggestion_id):
    """Promote a pending or shadow-evaluating learner suggestion into applied evaluation.

    This uses the same config mutation path as Apply, but accepts shadow_evaluating
    suggestions so ready shadow evidence does not bottleneck behind old queue state.
    """
    try:
        body = request.get_json(silent=True) or {}
        reason = str(body.get("reason") or "manual shadow promotion").strip()[:700]
        suggestions = _load_suggestions()
        suggestion = next((s for s in suggestions if s.get("id") == suggestion_id), None)
        if not suggestion:
            return jsonify({"success": False, "error": "Suggestion not found"}), 404
        evaluating = _suggestion_evaluation_conflicts(suggestions, suggestion)
        if evaluating:
            return jsonify({
                "success": False,
                "error": (
                    f"Cannot promote — '{evaluating[0].get('id')}' is already "
                    f"evaluating {suggestion.get('strategy') or 'this strategy'}"
                ),
            }), 409
        if suggestion.get("status") not in {"pending_review", "pending", "shadow_evaluating", "parked"}:
            return jsonify({
                "success": False,
                "error": f"Status is {suggestion.get('status')}, not promotable",
            }), 409

        allowed, gate_error, contract = _suggestion_application_gate(suggestion, body)
        if not allowed:
            return jsonify({
                "success": False,
                "error": gate_error,
                "explainability": contract,
            }), 409

        ok, err = _apply_suggestion_config(suggestion)
        if not ok:
            return jsonify({"success": False, "error": err}), 400

        promoted_at = datetime.utcnow().isoformat()
        baseline = _suggestion_baseline_snapshot()
        baseline["applied_at"] = promoted_at
        baseline["promoted_from_status"] = suggestion.get("status")
        activated, activation_error, experiment = _activate_suggestion_learning_trial(
            suggestion,
            contract,
            promoted_at,
            baseline,
            {
                "promoted_at": promoted_at,
                "promote_reason": reason,
                "previous_status": suggestion.get("status"),
            },
        )
        if not activated:
            return jsonify({"success": False, "error": activation_error}), 500
        _append_experiment_record({
            "id": suggestion_id,
            "type": "suggestion_promoted",
            "strategy": suggestion.get("strategy"),
            "suggestion_type": suggestion.get("type"),
            "promoted_at": promoted_at,
            "previous_status": suggestion.get("status"),
            "reason": reason,
            "baseline": baseline,
        })
        return jsonify({
            "success": True,
            "promoted": suggestion_id,
            "baseline": baseline,
            "learning_experiment": experiment,
        })
    except Exception as e:
        print(f"[api/suggestion/promote] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/intelligence/suggestions/<suggestion_id>/reject", methods=["POST"])
def api_suggestion_reject(suggestion_id):
    try:
        body = request.get_json(silent=True) or {}
        reason = body.get("reason", "")
        suggestions = _load_suggestions()
        suggestion = next((s for s in suggestions if s.get("id") == suggestion_id), None)
        if not suggestion:
            return jsonify({"success": False, "error": "Suggestion not found"}), 404
        control = _suggestion_effective_control(suggestion)
        if control.get("active") and suggestion.get("status") != "superseded":
            return jsonify({
                "success": False,
                "error": (
                    "This suggestion still has active scan authority. "
                    "Park it to roll back its exact control before rejecting it."
                ),
                "control_authority": control,
            }), 409

        rejected_at = datetime.utcnow().isoformat()
        _write_rejected({
            "id": suggestion_id,
            "strategy": suggestion.get("strategy"),
            "type": suggestion.get("type"),
            "suggested_value": suggestion.get("suggested_value") or suggestion.get("regime"),
            "reason": reason,
            "rejected_at": rejected_at,
        })
        if not _update_suggestion_status(suggestion_id, "rejected", {
            "rejected_at": rejected_at,
            "reject_reason": reason,
        }):
            return jsonify({"success": False, "error": "Failed to update suggestion"}), 500
        return jsonify({"success": True, "rejected": suggestion_id})
    except Exception as e:
        print(f"[api/suggestion/reject] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/intelligence/suggestions/<suggestion_id>/park", methods=["POST"])
def api_suggestion_park(suggestion_id):
    """Park or defer a suggestion without applying or rejecting it.

    Parking is authority-neutral: if the suggestion owns an active built-in
    override, that exact field/value is rolled back before the status changes.
    """
    try:
        body = request.get_json(silent=True) or {}
        reason = body.get("reason") or "evaluation parked manually"
        suggestions = _load_suggestions()
        suggestion = next((s for s in suggestions if s.get("id") == suggestion_id), None)
        if not suggestion:
            return jsonify({"success": False, "error": "Suggestion not found"}), 404
        current_status = suggestion.get("status")
        if current_status not in {"pending", "pending_review", "evaluating", "shadow_evaluating"}:
            return jsonify({
                "success": False,
                "error": f"Status is {current_status}, not parkable",
            }), 409

        control = _suggestion_effective_control(suggestion)
        rollback = {"changed": False}
        if control.get("active"):
            ok, err, rollback = _revert_suggestion_config(suggestion)
            if not ok:
                return jsonify({
                    "success": False,
                    "error": f"Cannot park while control is active: {err}",
                    "control_authority": control,
                }), 409

        parked_at = datetime.utcnow().isoformat()
        extra = {
            "parked_at": parked_at,
            "park_reason": reason,
            "previous_status": current_status,
            "control_rolled_back": bool(rollback.get("changed")),
            "control_rolled_back_at": parked_at if rollback.get("changed") else None,
        }
        if not _update_suggestion_status(suggestion_id, "parked", extra):
            return jsonify({"success": False, "error": "Failed to update suggestion"}), 500
        learning_closed = _learning_close_suggestion_experiments(
            suggestion_id,
            "rolled_back" if rollback.get("changed") else "cancelled",
            {
                "reason": reason,
                "control_rollback": rollback,
            },
        )
        _append_experiment_record({
            "id": suggestion_id,
            "type": "suggestion_parked",
            "strategy": suggestion.get("strategy"),
            "suggestion_type": suggestion.get("type"),
            "reason": reason,
            "parked_at": parked_at,
            "baseline": suggestion.get("baseline"),
            "trades_since_baseline": suggestion.get("trades_since_baseline"),
            "control_rollback": rollback,
            "learning_experiments_closed": learning_closed,
        })
        return jsonify({
            "success": True,
            "parked": suggestion_id,
            "parked_at": parked_at,
            "control_rollback": rollback,
            "learning_experiments_closed": learning_closed,
        })
    except Exception as e:
        print(f"[api/suggestion/park] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/intelligence/suggestions/<suggestion_id>/resume", methods=["POST"])
def api_suggestion_resume(suggestion_id):
    """Resume a parked suggestion into the concurrent shadow-evaluation lane."""
    try:
        suggestions = _load_suggestions()
        suggestion = next((s for s in suggestions if s.get("id") == suggestion_id), None)
        if not suggestion:
            return jsonify({"success": False, "error": "Suggestion not found"}), 404
        if suggestion.get("status") != "parked":
            return jsonify({
                "success": False,
                "error": f"Status is {suggestion.get('status')}, not parked",
            }), 409

        control = _suggestion_effective_control(suggestion)
        if control.get("active"):
            return jsonify({
                "success": False,
                "error": (
                    "Cannot resume as shadow while this suggestion's control is active. "
                    "Remove or reconcile the active override first."
                ),
                "control_authority": control,
            }), 409

        resumed_at = datetime.utcnow().isoformat()
        baseline = _suggestion_baseline_snapshot()
        baseline["shadow_started_at"] = resumed_at
        extra = {
            "shadow_baseline": baseline,
            "shadow_started_at": resumed_at,
            "resumed_at": resumed_at,
            "previous_status": "parked",
            "shadow_mode": True,
        }
        if not _update_suggestion_status(suggestion_id, "shadow_evaluating", extra):
            return jsonify({"success": False, "error": "Failed to update suggestion"}), 500
        _append_experiment_record({
            "id": suggestion_id,
            "type": "suggestion_shadow_resumed",
            "strategy": suggestion.get("strategy"),
            "suggestion_type": suggestion.get("type"),
            "resumed_at": resumed_at,
            "shadow_baseline": baseline,
            "parked_at": suggestion.get("parked_at"),
            "park_reason": suggestion.get("park_reason"),
        })
        return jsonify({"success": True, "resumed": suggestion_id, "status": "shadow_evaluating", "shadow_baseline": baseline})
    except Exception as e:
        print(f"[api/suggestion/resume] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


