@app.route(
    "/api/intelligence/research/orchestrator/experiments/<path:experiment_id>/stop",
    methods=["POST"],
)
def api_research_orchestrator_stop(experiment_id: str):
    """Explicitly stop or roll back a Paper challenger."""
    try:
        body = request.get_json(silent=True) or {}
        reason = str(body.get("reason") or "").strip()
        actor = str(body.get("actor") or "local_user").strip() or "local_user"
        if len(reason) < 8:
            return jsonify({
                "success": False,
                "error": "A clear stop reason of at least 8 characters is required.",
            }), 400
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        row = con.execute(
            """SELECT source_id FROM learning_experiments
               WHERE experiment_id=? AND source_type='research_candidate'""",
            (experiment_id,),
        ).fetchone()
        con.close()
        if not row:
            return jsonify({"success": False, "error": "experiment not found"}), 404
        stopped = _research_stop_source_experiments(
            str(row["source_id"]),
            status="rolled_back",
            actor=actor,
            reason=reason,
            automatic=False,
        )
        return jsonify({
            "success": True,
            "stopped_experiments": stopped,
            "live_behavior_changed": False,
            "orchestrator": _research_experiment_orchestrator_payload(),
        })
    except Exception as e:
        print(f"[api/research/orchestrator/stop] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route(
    "/api/intelligence/learning/experiments/<path:experiment_id>/rollback",
    methods=["POST"],
)
def api_learning_experiment_rollback(experiment_id: str):
    """Explicitly roll back a falsified suggestion experiment."""
    try:
        body = request.get_json(silent=True) or {}
        reason = str(body.get("reason") or "").strip()
        if len(reason) < 8:
            return jsonify({
                "success": False,
                "error": "A clear rollback reason of at least 8 characters is required.",
            }), 400
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        row = con.execute(
            "SELECT * FROM learning_experiments WHERE experiment_id=?",
            (experiment_id,),
        ).fetchone()
        con.close()
        if not row:
            return jsonify({"success": False, "error": "experiment not found"}), 404
        experiment = dict(row)
        if experiment["status"] != "falsified":
            return jsonify({
                "success": False,
                "error": "Only a falsified experiment can use this rollback path.",
            }), 409
        suggestion = next(
            (
                item for item in _load_suggestions()
                if str(item.get("id")) == str(experiment.get("source_id"))
            ),
            None,
        )
        if not suggestion:
            return jsonify({
                "success": False,
                "error": "source suggestion is unavailable; no config was changed",
            }), 409
        ok, error, rollback = _revert_suggestion_config(suggestion)
        if not ok:
            return jsonify({
                "success": False,
                "error": error,
                "config_changed": False,
            }), 409
        rolled_back_at = datetime.now(timezone.utc).isoformat()
        _learning_close_suggestion_experiments(
            str(experiment.get("source_id")),
            "rolled_back",
            {
                "reason": reason,
                "control_rollback": rollback,
                "explicit_user_action": True,
            },
        )
        _update_suggestion_status(
            str(experiment.get("source_id")),
            "parked",
            {
                "parked_at": rolled_back_at,
                "park_reason": reason,
                "previous_status": suggestion.get("status"),
                "control_rolled_back": bool(rollback.get("changed")),
                "learning_experiment_id": experiment_id,
            },
        )
        return jsonify({
            "success": True,
            "experiment_id": experiment_id,
            "status": "rolled_back",
            "control_rollback": rollback,
            "automatic": False,
        })
    except Exception as e:
        print(f"[api/learning/rollback] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


