@app.route('/api/intelligence/research/sources')
def api_research_sources():
    """List all indexed Hermes research sources with readable metadata."""
    try:
        sources = _research_load_sources()
        items = []
        for source in sources:
            if not isinstance(source, dict):
                continue
            excerpt = str(source.get("raw_excerpt") or "")
            profile = _research_text_profile(
                excerpt or str(source.get("summary") or ""),
                str(source.get("source_type") or ""),
                source.get("full_text_status"),
            )
            display_summary = str(source.get("summary") or "").strip() or _research_summarize_text(excerpt)
            items.append({
                "id": source.get("id"),
                "title": source.get("title"),
                "url": source.get("url"),
                "full_text_url": source.get("full_text_url"),
                "path": source.get("path"),
                "relative_path": source.get("relative_path"),
                "corpus_root": source.get("corpus_root"),
                "original_filename": source.get("original_filename"),
                "file_ext": source.get("file_ext"),
                "file_size_bytes": source.get("file_size_bytes"),
                "source_type": source.get("source_type"),
                "author": source.get("author"),
                "published_at": source.get("published_at"),
                "added_at": source.get("added_at"),
                "tags": source.get("tags") or [],
                "summary": display_summary,
                "stored_summary": source.get("summary") or "",
                "quality_score": source.get("quality_score"),
                "relevance_score": source.get("relevance_score"),
                "full_text_status": source.get("full_text_status") or profile["full_text_status"],
                "full_text_word_count": source.get("full_text_word_count") or profile["full_text_word_count"],
                "full_text_confidence": source.get("full_text_confidence") or profile["full_text_confidence"],
                "hypothesis_count": len(source.get("hypotheses") or []),
                "has_text": bool(excerpt or source.get("summary")),
                "text_preview": (excerpt or display_summary)[:420],
                "extraction": source.get("extraction"),
                "online_sync_approved": bool(source.get("online_sync_approved")),
                "online_sync_candidate": _research_source_is_online_sync_candidate(source),
                "online_sync_approved_at": source.get("online_sync_approved_at"),
            })
        return jsonify({"success": True, "source_count": len(items), "sources": items})
    except Exception as e:
        print(f"[api/research/sources:get] error: {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route('/api/intelligence/research/full-text-audit')
def api_research_full_text_audit():
    """Summarize how much indexed research has true/full text available."""
    try:
        sources = _research_load_sources()
        counts: dict[str, int] = defaultdict(int)
        rows = []
        for source in sources:
            text = str(source.get("raw_excerpt") or source.get("summary") or "")
            profile = _research_text_profile(text, str(source.get("source_type") or ""), source.get("full_text_status"))
            status = source.get("full_text_status") or profile["full_text_status"]
            counts[status] += 1
            rows.append({
                "id": source.get("id"),
                "title": source.get("title"),
                "source_type": source.get("source_type"),
                "status": status,
                "word_count": source.get("full_text_word_count") or profile["full_text_word_count"],
                "url": source.get("url"),
                "full_text_url": source.get("full_text_url"),
            })
        complete = counts.get("full_text", 0) + counts.get("full_text_unverified", 0)
        return jsonify({
            "success": True,
            "source_count": len(sources),
            "counts": dict(counts),
            "complete_or_unverified_count": complete,
            "full_text_ratio": round(complete / len(sources), 3) if sources else 0,
            "sources": rows,
            "note": "abstract_only and metadata_only sources are useful discovery leads, but should not be treated as fully read research.",
        })
    except Exception as e:
        print(f"[api/research/full-text-audit] error: {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


