REPORTS_DIR = "data/reports"
REPORT_SCHEMA_VERSION = "cipher-v11-measured-market-regime"


def _report_classify_session(utc_iso: str) -> str:
    """Classify a UTC timestamp into the crypto desk session buckets."""
    try:
        dt = datetime.fromisoformat(str(utc_iso).replace("Z", "").split(".")[0])
        h = dt.hour
        if 0 <= h < 8:
            return "ASIA"
        if 8 <= h < 13:
            return "LONDON"
        if 13 <= h < 21:
            return "NY"
        return "ASIA"
    except Exception:
        return "UNKNOWN"


def _report_db_rows(table: str, date_col: str | None = None, date_value: str | None = None,
                    days_back: int | None = None, limit: int = 500) -> list[dict]:
    """Best-effort SQLite reader for report sections; returns [] on schema drift."""
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        exists = con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name=?",
            (table,),
        ).fetchone()
        if not exists:
            con.close()
            return []
        cols = {r[1] for r in con.execute(f"PRAGMA table_info({table})").fetchall()}
        where = ""
        params: list = []
        if date_col and date_col in cols and date_value:
            target_start, target_end = _report_date_bounds(date_value)
            query_start = (
                target_start - timedelta(days=max(0, int(days_back or 0)))
                if days_back else target_start
            )
            # ISO timestamps sort chronologically in SQLite and preserve use
            # of the logged/opened-at indexes; wrapping the column in date()
            # forced full scans as the history tables grew.
            where = f"WHERE {date_col}>=? AND {date_col}<?"
            params = [query_start.isoformat(), target_end.isoformat()]
        order = f"ORDER BY {date_col} DESC" if date_col and date_col in cols else ""
        rows = con.execute(
            f"SELECT * FROM {table} {where} {order} LIMIT ?",
            (*params, limit),
        ).fetchall()
        con.close()
        return [dict(r) for r in rows]
    except Exception as e:
        print(f"[report_db_rows] {table}: {e}", file=sys.stderr)
        return []


def _report_signal_json(row: dict) -> dict:
    try:
        raw = row.get("signal_json") or "{}"
        return json.loads(raw) if isinstance(raw, str) else (raw or {})
    except Exception:
        return {}


def _report_fetch_ticker_snapshot() -> list[dict]:
    """Fetch MEXC tickers for market pulse, funding heatmap, movers, and coiling."""
    try:
        resp = requests.get(f"{MEXC_BASE}/contract/ticker", timeout=10)
        payload = resp.json()
        if payload.get("success") and isinstance(payload.get("data"), list):
            return payload["data"]
    except Exception as e:
        print(f"[report_ticker] {e}", file=sys.stderr)
    return []


def _report_date_bounds(date_str: str, days: int = 1) -> tuple[datetime, datetime]:
    """Return UTC-naive ISO-compatible bounds for indexed report queries."""
    try:
        start = datetime.fromisoformat(str(date_str)[:10])
    except Exception:
        start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
    return start, start + timedelta(days=max(1, int(days or 1)))


def _report_persisted_ticker_snapshot(date_str: str) -> tuple[list[dict], str | None]:
    """Load the final persisted all-market snapshot for a UTC day."""
    start, end = _report_date_bounds(date_str)
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        exists = con.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='ticker_snapshots'"
        ).fetchone()
        if not exists:
            con.close()
            return [], None
        latest = con.execute(
            "SELECT MAX(ts) FROM ticker_snapshots WHERE ts>=? AND ts<?",
            (start.isoformat(), end.isoformat()),
        ).fetchone()[0]
        if not latest and date_str[:10] == datetime.utcnow().strftime("%Y-%m-%d"):
            latest = con.execute(
                "SELECT MAX(ts) FROM ticker_snapshots WHERE ts>=? AND ts<?",
                ((start - timedelta(hours=6)).isoformat(), end.isoformat()),
            ).fetchone()[0]
        if not latest:
            daily_exists = con.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='ticker_daily_snapshots'"
            ).fetchone()
            if daily_exists:
                daily_rows = con.execute(
                    """
                    SELECT symbol, exchange, price, volume_24h, funding_rate,
                           change_24h_pct, open_interest, ts
                    FROM ticker_daily_snapshots
                    WHERE day=?
                    """,
                    (date_str[:10],),
                ).fetchall()
                if daily_rows:
                    daily_ts = str(daily_rows[0]["ts"])
                    rows = [
                        {k: row[k] for k in row.keys() if k != "ts"}
                        for row in daily_rows
                    ]
                    con.close()
                    return rows, daily_ts
            con.close()
            return [], None
        rows = con.execute(
            """
            SELECT symbol, exchange, price, volume_24h, funding_rate,
                   change_24h_pct, open_interest
            FROM ticker_snapshots
            WHERE ts=?
            """,
            (latest,),
        ).fetchall()
        con.close()
        return [dict(r) for r in rows], str(latest)
    except Exception as e:
        print(f"[report_persisted_tickers] {e}", file=sys.stderr)
        return [], None


def _report_ticker_snapshot_for_date(date_str: str) -> tuple[list[dict], dict]:
    """Serve reports from persisted evidence without blocking on an exchange call."""
    persisted, snapshot_at = _report_persisted_ticker_snapshot(date_str)
    today = datetime.utcnow().strftime("%Y-%m-%d")
    freshness_minutes = None
    if snapshot_at:
        try:
            snap_dt = datetime.fromisoformat(snapshot_at.replace("Z", "+00:00")).replace(tzinfo=None)
            freshness_minutes = max(0, (datetime.utcnow() - snap_dt).total_seconds() / 60)
        except Exception:
            pass
    if date_str != today or persisted:
        source = "persisted_hourly"
        if date_str == today and freshness_minutes is not None and freshness_minutes > 90:
            source = "persisted_stale"
        return persisted, {
            "source": source if persisted else "unavailable",
            "snapshot_at": snapshot_at,
            "freshness_minutes": round(freshness_minutes, 1) if freshness_minutes is not None else None,
        }
    return [], {
        "source": "unavailable",
        "snapshot_at": None,
        "freshness_minutes": None,
    }


def _report_cross_venue_evidence(
    con: sqlite3.Connection,
    start_iso: str,
    end_iso: str,
    focus_symbols: list[str] | None = None,
) -> dict:
    """Summarize cached synchronized venue batches without report-time API calls."""
    packet = {
        "available": False,
        "captured_at": None,
        "first_captured_at": None,
        "freshness_minutes": None,
        "venue_count": 0,
        "matched_two_venue": 0,
        "matched_three_venue": 0,
        "collection_latency_ms": None,
        "collection_errors": {},
        "price_dislocations": [],
        "funding_divergences": [],
        "focus_assets": [],
        "symbol_mismatches": [],
        "retention_days": CROSS_VENUE_RETENTION_DAYS,
        "method": (
            "Three public ticker universes collected in one batch; funding normalized "
            "to an 8h equivalent. Price gaps retain raw values and an 8 bps USDC quote buffer; "
            "exact-base matches wider than 500 bps are quarantined as identity/staleness conflicts."
        ),
        "limits": [
            "Ticker batches are near-synchronized, not atomic exchange timestamps.",
            "Base-symbol matching cannot prove token identity; implausible matches are quarantined.",
            "Hyperliquid public asset context does not include top-of-book spread.",
            "MEXC ticker open interest remains in native contract units and is not compared as USD.",
            "Cross-venue observations are context only and cannot create or execute a trade.",
        ],
    }
    latest = con.execute(
        """
        SELECT MAX(captured_at)
        FROM cross_venue_snapshots
        WHERE captured_at>=? AND captured_at<?
        """,
        (start_iso, end_iso),
    ).fetchone()[0]
    if not latest:
        return packet
    first = con.execute(
        """
        SELECT MIN(captured_at)
        FROM cross_venue_snapshots
        WHERE captured_at>=? AND captured_at<=?
        """,
        (start_iso, latest),
    ).fetchone()[0]
    latest_rows = [
        dict(row) for row in con.execute(
            """
            SELECT base_asset,exchange,native_symbol,quote_asset,price,mark_price,
                   index_price,bid_price,ask_price,spread_bps,volume_24h_usd,
                   open_interest_native,open_interest_usd,funding_rate,
                   funding_interval_hours,funding_interval_assumed,funding_8h_equiv,
                   change_24h_pct,data_quality
            FROM cross_venue_snapshots
            WHERE captured_at=?
            ORDER BY base_asset,exchange
            """,
            (latest,),
        ).fetchall()
    ]
    first_rows = {
        (str(row["base_asset"]), str(row["exchange"])): dict(row)
        for row in con.execute(
            """
            SELECT base_asset,exchange,price,open_interest_usd
            FROM cross_venue_snapshots
            WHERE captured_at=?
            """,
            (first,),
        ).fetchall()
    } if first else {}
    run = con.execute(
        """
        SELECT latency_ms,matched_two_venue,matched_three_venue,errors_json
        FROM cross_venue_collection_runs
        WHERE captured_at=?
        """,
        (latest,),
    ).fetchone()
    grouped = defaultdict(list)
    for row in latest_rows:
        grouped[str(row.get("base_asset") or "")].append(row)
    focus_bases = {
        str(symbol or "").upper().replace("_USDT", "").replace("_USDC", "")
        for symbol in (focus_symbols or [])
        if str(symbol or "").strip()
    }
    dislocations = []
    symbol_mismatches = []
    for base, venues in grouped.items():
        valid_prices = [
            (str(row.get("exchange")), _report_float(row.get("price")))
            for row in venues
            if _report_float(row.get("price")) > 0
        ]
        if len(valid_prices) < 2:
            continue
        prices = sorted(value for _, value in valid_prices)
        midpoint = prices[len(prices) // 2] if len(prices) % 2 else sum(prices[-2:]) / 2
        high_venue, high_price = max(valid_prices, key=lambda item: item[1])
        low_venue, low_price = min(valid_prices, key=lambda item: item[1])
        raw_gap_bps = ((high_price - low_price) / midpoint) * 10000 if midpoint else 0
        has_usdc = any(str(row.get("quote_asset")) == "USDC" for row in venues)
        adjusted_gap_bps = max(0, raw_gap_bps - (8 if has_usdc else 0))
        funding_values = [
            (str(row.get("exchange")), _report_float(row.get("funding_8h_equiv")))
            for row in venues
            if row.get("funding_8h_equiv") is not None
        ]
        funding_gap_bps = (
            (max(value for _, value in funding_values) - min(value for _, value in funding_values)) * 10000
            if len(funding_values) >= 2 else None
        )
        venue_volumes = {
            str(row.get("exchange")): round(_report_float(row.get("volume_24h_usd")), 2)
            for row in venues
            if row.get("volume_24h_usd") is not None
        }
        minimum_volume = min(venue_volumes.values()) if venue_volumes else 0
        venue_moves = []
        oi_moves = []
        if first and first != latest:
            for row in venues:
                key = (base, str(row.get("exchange")))
                prior = first_rows.get(key)
                first_price = _report_float((prior or {}).get("price"))
                last_price = _report_float(row.get("price"))
                if first_price and last_price:
                    venue_moves.append({
                        "exchange": key[1],
                        "return_pct": round(((last_price / first_price) - 1) * 100, 3),
                    })
                first_oi = _report_float((prior or {}).get("open_interest_usd"))
                last_oi = _report_float(row.get("open_interest_usd"))
                if first_oi and last_oi:
                    oi_moves.append({
                        "exchange": key[1],
                        "oi_change_pct": round(((last_oi / first_oi) - 1) * 100, 2),
                    })
        venue_leader = None
        leader_margin_bps = None
        direction_aligned = None
        if len(venue_moves) >= 2:
            returns = [item["return_pct"] for item in venue_moves]
            average_return = sum(returns) / len(returns)
            ordered = sorted(
                venue_moves,
                key=lambda item: item["return_pct"],
                reverse=average_return >= 0,
            )
            venue_leader = ordered[0]["exchange"]
            leader_margin_bps = round(
                abs(ordered[0]["return_pct"] - ordered[1]["return_pct"]) * 100,
                1,
            )
            signs = {
                1 if value > 0.05 else -1 if value < -0.05 else 0
                for value in returns
            }
            direction_aligned = len(signs - {0}) <= 1 and 0 not in signs
        row_packet = {
            "base_asset": base,
            "symbol": f"{base}_USDT",
            "venues": [str(row.get("exchange")) for row in venues],
            "venue_count": len(venues),
            "raw_price_gap_bps": round(raw_gap_bps, 2),
            "adjusted_price_gap_bps": round(adjusted_gap_bps, 2),
            "premium_venue": high_venue,
            "discount_venue": low_venue,
            "funding_gap_8h_bps": round(funding_gap_bps, 3) if funding_gap_bps is not None else None,
            "funding_8h": {
                venue: round(value, 7) for venue, value in funding_values
            },
            "venue_moves": venue_moves,
            "venue_leader": venue_leader,
            "leader_margin_bps": leader_margin_bps,
            "direction_aligned": direction_aligned,
            "oi_usd_moves": oi_moves,
            "max_observed_spread_bps": round(
                max(
                    [
                        _report_float(row.get("spread_bps"))
                        for row in venues if row.get("spread_bps") is not None
                    ] or [0]
                ),
                2,
            ),
            "venue_volume_24h_usd": venue_volumes,
            "minimum_venue_volume_24h_usd": round(minimum_volume, 2),
            "liquidity_quality": (
                "thin" if minimum_volume and minimum_volume < 1_000_000 else
                "measured" if minimum_volume else "unknown"
            ),
            "focus": base in focus_bases,
        }
        if raw_gap_bps > 500:
            row_packet["identity_status"] = "quarantined_price_mismatch"
            symbol_mismatches.append(row_packet)
            continue
        row_packet["identity_status"] = "price_consistent"
        dislocations.append(row_packet)
    dislocations.sort(
        key=lambda item: (
            bool(item.get("focus")),
            _report_float(item.get("adjusted_price_gap_bps")),
        ),
        reverse=True,
    )
    funding_divergences = sorted(
        [
            item for item in dislocations
            if item.get("funding_gap_8h_bps") is not None
        ],
        key=lambda item: abs(_report_float(item.get("funding_gap_8h_bps"))),
        reverse=True,
    )[:8]
    try:
        latest_dt = datetime.fromisoformat(str(latest).replace("Z", "+00:00")).replace(tzinfo=None)
        freshness = max(0, (datetime.utcnow() - latest_dt).total_seconds() / 60)
    except Exception:
        freshness = None
    errors = {}
    if run:
        try:
            errors = json.loads(run["errors_json"] or "{}")
        except Exception:
            errors = {"parse": "invalid collection health metadata"}
    packet.update({
        "available": bool(dislocations),
        "captured_at": str(latest),
        "first_captured_at": str(first) if first else None,
        "freshness_minutes": round(freshness, 1) if freshness is not None else None,
        "venue_count": len({row.get("exchange") for row in latest_rows}),
        "matched_two_venue": int(run["matched_two_venue"] or 0) if run else len(dislocations),
        "matched_three_venue": int(run["matched_three_venue"] or 0) if run else sum(
            1 for item in dislocations if item.get("venue_count") == 3
        ),
        "collection_latency_ms": int(run["latency_ms"] or 0) if run else None,
        "collection_errors": errors,
        "price_dislocations": dislocations[:12],
        "funding_divergences": funding_divergences,
        "focus_assets": [item for item in dislocations if item.get("focus")][:8],
        "symbol_mismatches": sorted(
            symbol_mismatches,
            key=lambda item: _report_float(item.get("raw_price_gap_bps")),
            reverse=True,
        )[:12],
    })
    return packet


def _report_catalyst_evidence(
    con: sqlite3.Connection,
    start_iso: str,
    end_iso: str,
    focus_symbols: list[str] | None = None,
    *,
    lookahead_days: int = 7,
) -> dict:
    """Summarize cached official-source events without a report-time network request."""
    packet = {
        "available": False,
        "last_collected_at": None,
        "freshness_minutes": None,
        "collection_latency_ms": None,
        "source_counts": {},
        "source_errors": {},
        "primary_source_count": 0,
        "events_in_window": [],
        "upcoming_events": [],
        "active_incidents": [],
        "focus_events": [],
        "event_type_counts": {},
        "method": (
            "Official MEXC and Bybit announcements, Hyperliquid Statuspage incidents/"
            "maintenance, Federal Reserve monetary-policy RSS, and the official FOMC "
            "calendar are combined with reviewed protocol status/governance feeds and "
            "crypto-filtered SEC/CFTC releases. All are collected asynchronously and "
            "cached before report generation."
        ),
        "limits": [
            "The feed set is bounded and does not represent every exchange, jurisdiction, protocol, governance forum, or token issuer.",
            "Event classification is deterministic and does not infer bullish or bearish direction.",
            "Publication time and effective/event time are shown separately when the source provides both.",
            "Governance-forum publication proves discussion, not passage, implementation, or economic effect.",
            "Catalyst evidence is advisory and cannot create, score, size, or execute a trade.",
        ],
    }
    run = con.execute(
        """
        SELECT collected_at,latency_ms,stored_events,source_counts_json,source_errors_json
        FROM catalyst_collection_runs ORDER BY collected_at DESC LIMIT 1
        """
    ).fetchone()
    if run:
        try:
            source_counts = json.loads(run["source_counts_json"] or "{}")
        except Exception:
            source_counts = {}
        try:
            source_errors = json.loads(run["source_errors_json"] or "{}")
        except Exception:
            source_errors = {"parse": "invalid source-health metadata"}
        try:
            collected_dt = datetime.fromisoformat(str(run["collected_at"]).replace("Z", "+00:00")).replace(tzinfo=None)
            freshness = max(0, (datetime.utcnow() - collected_dt).total_seconds() / 60)
        except Exception:
            freshness = None
        packet.update({
            "last_collected_at": str(run["collected_at"]),
            "freshness_minutes": round(freshness, 1) if freshness is not None else None,
            "collection_latency_ms": int(run["latency_ms"] or 0),
            "source_counts": source_counts,
            "source_errors": source_errors,
        })
    try:
        start = datetime.fromisoformat(start_iso)
        end = datetime.fromisoformat(end_iso)
    except Exception:
        start = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        end = start + timedelta(days=1)
    query_start = (start - timedelta(days=1)).isoformat()
    query_end = (end + timedelta(days=max(1, lookahead_days))).isoformat()
    rows = [
        dict(row) for row in con.execute(
            """
            SELECT source_key,source_name,source_kind,source_url,external_id,title,
                   summary,published_at,event_at,observed_at,status,severity,event_type,
                   affected_assets_json,affected_venues_json,horizon,scheduled,
                   primary_source,source_time_quality,raw_meta_json
            FROM catalyst_events
            WHERE (
                    COALESCE(published_at,event_at,observed_at)>=?
                AND COALESCE(published_at,event_at,observed_at)<?
            ) OR (
                    event_at>=?
                AND event_at<?
            ) OR status IN ('investigating','identified','monitoring')
            ORDER BY COALESCE(event_at,published_at,observed_at) ASC
            LIMIT 400
            """,
            (query_start, end_iso, end_iso, query_end),
        ).fetchall()
    ]
    focus = {
        str(symbol or "").upper()
        for symbol in (focus_symbols or [])
        if str(symbol or "").strip()
    }
    severity_rank = {"critical": 4, "high": 3, "medium": 2, "low": 1}

    def serialize(row: dict) -> dict:
        try:
            assets = json.loads(row.get("affected_assets_json") or "[]")
        except Exception:
            assets = []
        try:
            venues = json.loads(row.get("affected_venues_json") or "[]")
        except Exception:
            venues = []
        try:
            raw_meta = json.loads(row.get("raw_meta_json") or "{}")
        except Exception:
            raw_meta = {}
        return {
            "source_key": row.get("source_key"),
            "source_name": row.get("source_name"),
            "source_kind": row.get("source_kind"),
            "source_url": row.get("source_url"),
            "title": row.get("title"),
            "summary": row.get("summary"),
            "published_at": row.get("published_at"),
            "event_at": row.get("event_at"),
            "observed_at": row.get("observed_at"),
            "status": row.get("status"),
            "severity": row.get("severity"),
            "event_type": row.get("event_type"),
            "affected_assets": assets,
            "affected_venues": venues,
            "horizon": row.get("horizon"),
            "scheduled": bool(row.get("scheduled")),
            "primary_source": bool(row.get("primary_source")),
            "source_time_quality": row.get("source_time_quality"),
            "authority_scope": raw_meta.get("authority_scope") or (
                "official_source" if row.get("primary_source") else "attributed_source"
            ),
            "symbol_resolution": raw_meta.get("symbol_resolution") or (
                "source_named_or_market_wide"
            ),
            "focus_match": bool(focus.intersection(set(assets))),
        }

    serialized = [serialize(row) for row in rows]

    def in_range(value, lower: datetime, upper: datetime) -> bool:
        try:
            parsed = datetime.fromisoformat(str(value or "").replace("Z", "+00:00")).replace(tzinfo=None)
            return lower <= parsed < upper
        except Exception:
            return False

    current = [
        row for row in serialized
        if in_range(row.get("published_at"), start, end)
        or in_range(row.get("event_at"), start, end)
    ]
    upcoming = [
        row for row in serialized
        if in_range(row.get("event_at"), end, end + timedelta(days=max(1, lookahead_days)))
    ]
    active = [
        row for row in serialized
        if str(row.get("status") or "").lower() in {"investigating", "identified", "monitoring"}
    ]
    priority = lambda row: (
        severity_rank.get(str(row.get("severity") or "").lower(), 0),
        bool(row.get("focus_match")),
        str(row.get("event_at") or row.get("published_at") or ""),
    )
    current.sort(key=priority, reverse=True)
    active.sort(key=priority, reverse=True)
    upcoming.sort(
        key=lambda row: str(row.get("event_at") or "9999"),
    )
    event_type_counts = defaultdict(int)
    for row in current:
        event_type_counts[str(row.get("event_type") or "announcement")] += 1
    focus_events = [
        row for row in [*active, *current, *upcoming]
        if row.get("focus_match")
    ]
    focus_events = list({
        (
            row.get("source_key"),
            row.get("title"),
            row.get("event_at"),
        ): row
        for row in focus_events
    }.values())
    packet.update({
        "available": bool(serialized),
        "primary_source_count": len({
            str(row.get("source_key"))
            for row in serialized if row.get("primary_source")
        }),
        "events_in_window": current[:16],
        "upcoming_events": upcoming[:12],
        "active_incidents": active[:8],
        "focus_events": sorted(focus_events, key=priority, reverse=True)[:10],
        "event_type_counts": dict(event_type_counts),
    })
    return packet


def _report_tokenomics_evidence(
    con: sqlite3.Connection,
    start_iso: str,
    end_iso: str,
    focus_symbols: list[str] | None = None,
    *,
    lookahead_days: int = 90,
) -> dict:
    """Build an honest cached supply/unlock/treasury packet for Priya."""
    focus = {
        f"{base}_USDT"
        for base in (
            _tokenomics_base_symbol(symbol)
            for symbol in (focus_symbols or [])
        )
        if base
    }
    packet = {
        "available": False,
        "last_collected_at": None,
        "freshness_minutes": None,
        "collection_latency_ms": None,
        "source_counts": {},
        "source_errors": {},
        "asset_snapshots": [],
        "focus_assets": [],
        "float_risk_assets": [],
        "upcoming_unlocks": [],
        "focus_unlocks": [],
        "treasury_snapshots": [],
        "focus_treasuries": [],
        "coverage": {
            "supply_fdv": False,
            "unlock_schedule": False,
            "treasury_composition": False,
            "holder_concentration": False,
            "wallet_exchange_flows": False,
        },
        "onchain_capability_boundary": {
            "status": "not_configured_identity_safe",
            "decision": "deferred_until_chain_specific_contracts_are_reviewed",
            "holder_concentration": {
                "available": False,
                "requirements": [
                    "reviewed token contract per chain",
                    "chain-specific holder/indexer source",
                    "vesting, treasury, bridge, burn, and exchange-address exclusions",
                    "timestamped historical snapshots",
                ],
            },
            "labeled_wallet_flows": {
                "available": False,
                "requirements": [
                    "licensed or user-configured address labels",
                    "chain-specific transfer indexing",
                    "bridge and internal-transfer de-duplication",
                    "classification confidence and provenance",
                ],
            },
            "reason": (
                "A same-symbol or top-wallet query is not identity-safe across chains, "
                "and unlabeled transfers cannot be described as whale or exchange intent."
            ),
        },
        "method": (
            "CoinGecko market snapshots provide circulating/total/max supply and FDV. "
            "DefiLlama public pages provide third-party aggregated next-unlock and "
            "treasury observations. All sources are collected asynchronously."
        ),
        "limits": [
            "CoinGecko and DefiLlama are third-party aggregators, not issuer filings or audited on-chain attestations.",
            "Unlock rows show the next disclosed group; a linear row is a rate change and is not presented as a one-time dollar unlock.",
            "MT7 does not yet have scalable direct holder-concentration, wallet-label, treasury-transfer, or exchange-flow coverage.",
            "Supply, unlock, and treasury evidence can qualify risk; it does not predict price direction or create a trade.",
        ],
    }
    run = con.execute(
        """
        SELECT collected_at,latency_ms,asset_snapshots,unlock_events,
               treasury_snapshots,mapped_symbols,source_counts_json,source_errors_json
        FROM tokenomics_collection_runs
        WHERE collected_at<?
        ORDER BY collected_at DESC LIMIT 1
        """,
        (end_iso,),
    ).fetchone()
    if run:
        try:
            source_counts = json.loads(run["source_counts_json"] or "{}")
        except Exception:
            source_counts = {}
        try:
            source_errors = json.loads(run["source_errors_json"] or "{}")
        except Exception:
            source_errors = {"parse": "invalid tokenomics source-health metadata"}
        try:
            collected_dt = datetime.fromisoformat(
                str(run["collected_at"]).replace("Z", "+00:00")
            ).replace(tzinfo=None)
            freshness = max(
                0,
                (datetime.utcnow() - collected_dt).total_seconds() / 60,
            )
        except Exception:
            freshness = None
        packet.update({
            "last_collected_at": str(run["collected_at"]),
            "freshness_minutes": round(freshness, 1) if freshness is not None else None,
            "collection_latency_ms": int(run["latency_ms"] or 0),
            "source_counts": source_counts,
            "source_errors": source_errors,
        })

    latest_asset_at = con.execute(
        """
        SELECT MAX(captured_at) FROM tokenomics_asset_snapshots
        WHERE captured_at<?
        """,
        (end_iso,),
    ).fetchone()[0]
    assets = []
    if latest_asset_at:
        assets = [
            dict(row) for row in con.execute(
                """
                SELECT captured_at,symbol,coin_id,name,source_name,source_url,
                       mapping_quality,current_price,market_cap,fully_diluted_value,
                       circulating_supply,total_supply,max_supply,float_pct,
                       fdv_market_cap_ratio,volume_24h,source_updated_at,data_quality
                FROM tokenomics_asset_snapshots
                WHERE captured_at=?
                ORDER BY market_cap DESC
                LIMIT 80
                """,
                (latest_asset_at,),
            ).fetchall()
        ]
    for row in assets:
        float_pct = _report_float(row.get("float_pct"), None)
        ratio = _report_float(row.get("fdv_market_cap_ratio"), None)
        reasons = []
        if float_pct is not None and float_pct < 35:
            reasons.append(f"only {float_pct:.1f}% of reported max/total supply circulates")
        if ratio is not None and ratio >= 2:
            reasons.append(f"FDV is {ratio:.2f}× market cap")
        row["risk_level"] = (
            "high" if len(reasons) >= 2 or (ratio is not None and ratio >= 4)
            else "watch" if reasons else "normal"
        )
        row["risk_reasons"] = reasons

    try:
        lower = datetime.fromisoformat(start_iso)
        upper = datetime.fromisoformat(end_iso) + timedelta(days=max(1, lookahead_days))
    except Exception:
        lower = datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        upper = lower + timedelta(days=max(1, lookahead_days))
    unlock_rows = [
        dict(row) for row in con.execute(
            """
            SELECT source_name,source_url,project_name,symbol,coin_id,unlock_at,
                   observed_at,unlock_type,category,token_amount,unlock_value_usd,
                   unlock_pct_float,circulating_supply,max_supply,unlocked_pct,
                   mapping_quality,data_quality,raw_meta_json
            FROM token_unlock_events
            WHERE observed_at<?
              AND unlock_at>=?
              AND unlock_at<?
            ORDER BY unlock_at ASC
            LIMIT 1200
            """,
            (end_iso, lower.isoformat(), upper.isoformat()),
        ).fetchall()
    ]
    unlock_groups: dict[tuple, dict] = {}
    for row in unlock_rows:
        key = (
            row.get("project_name"),
            row.get("symbol"),
            row.get("unlock_at"),
            row.get("unlock_type"),
        )
        grouped = unlock_groups.setdefault(key, {
            "source_name": row.get("source_name"),
            "source_url": row.get("source_url"),
            "project_name": row.get("project_name"),
            "symbol": f"{row.get('symbol')}_USDT" if row.get("symbol") else None,
            "coin_id": row.get("coin_id"),
            "unlock_at": row.get("unlock_at"),
            "observed_at": row.get("observed_at"),
            "unlock_type": row.get("unlock_type"),
            "categories": [],
            "token_amount": 0.0,
            "unlock_value_usd": 0.0,
            "unlock_pct_float": 0.0,
            "unlocked_pct": row.get("unlocked_pct"),
            "mapping_quality": row.get("mapping_quality"),
            "data_quality": row.get("data_quality"),
            "linear_rate_change": str(row.get("unlock_type") or "") == "linear",
        })
        if row.get("category") and row.get("category") not in grouped["categories"]:
            grouped["categories"].append(row.get("category"))
        for field in ("token_amount", "unlock_value_usd", "unlock_pct_float"):
            value = _report_float(row.get(field), None)
            if value is not None:
                grouped[field] += value
    unlocks = list(unlock_groups.values())
    for row in unlocks:
        if row.get("linear_rate_change"):
            row["token_amount"] = None
            row["unlock_value_usd"] = None
            row["unlock_pct_float"] = None
            row["risk_level"] = "schedule"
        else:
            pct_float = _report_float(row.get("unlock_pct_float"), 0)
            row["risk_level"] = (
                "high" if pct_float >= 3
                else "watch" if pct_float >= 1
                else "low"
            )

    latest_treasury_day = con.execute(
        """
        SELECT MAX(snapshot_day) FROM token_treasury_snapshots
        WHERE captured_at<?
        """,
        (end_iso,),
    ).fetchone()[0]
    treasuries = []
    if latest_treasury_day:
        treasuries = [
            dict(row) for row in con.execute(
                """
                SELECT snapshot_day,captured_at,source_name,source_url,project_name,
                       symbol,coin_id,treasury_value_usd,stablecoins_usd,majors_usd,
                       own_tokens_usd,other_tokens_usd,liquid_ex_own_usd,
                       own_token_share_pct,market_cap,mapping_quality,data_quality
                FROM token_treasury_snapshots
                WHERE snapshot_day=?
                ORDER BY treasury_value_usd DESC
                LIMIT 600
                """,
                (latest_treasury_day,),
            ).fetchall()
        ]
        for row in treasuries:
            if row.get("symbol"):
                row["symbol"] = f"{row['symbol']}_USDT"
            own_share = _report_float(row.get("own_token_share_pct"), 0)
            row["composition_risk"] = (
                "high" if own_share >= 75
                else "watch" if own_share >= 50
                else "diversified"
            )

    focus_assets = [row for row in assets if row.get("symbol") in focus]
    float_risk = sorted(
        [row for row in assets if row.get("risk_level") != "normal"],
        key=lambda row: (
            {"high": 2, "watch": 1}.get(row.get("risk_level"), 0),
            _report_float(row.get("fdv_market_cap_ratio")),
        ),
        reverse=True,
    )
    verified_unlocks = [
        row for row in unlocks if row.get("mapping_quality") == "curated_exact"
    ]
    focus_unlocks = [
        row for row in unlocks
        if row.get("symbol") in focus
        and row.get("mapping_quality") == "curated_exact"
    ]
    focus_treasuries = [
        row for row in treasuries
        if row.get("symbol") in focus
        and row.get("mapping_quality") == "curated_exact"
    ]
    packet.update({
        "available": bool(assets or unlocks or treasuries),
        "asset_snapshots": assets[:30],
        "focus_assets": focus_assets[:12],
        "float_risk_assets": float_risk[:12],
        "upcoming_unlocks": verified_unlocks[:20],
        "focus_unlocks": focus_unlocks[:12],
        "treasury_snapshots": treasuries[:20],
        "focus_treasuries": focus_treasuries[:12],
        "coverage": {
            "supply_fdv": bool(assets),
            "unlock_schedule": bool(verified_unlocks),
            "treasury_composition": bool(treasuries),
            "holder_concentration": False,
            "wallet_exchange_flows": False,
        },
    })
    return packet


def _report_social_evidence(
    con: sqlite3.Connection,
    start_iso: str,
    end_iso: str,
    focus_symbols: list[str] | None = None,
) -> dict:
    """Return cached activity-quality evidence without report-time social calls."""
    focus = {
        str(symbol or "").upper()
        for symbol in (focus_symbols or [])
        if str(symbol or "").strip()
    }
    packet = {
        "available": False,
        "last_collected_at": None,
        "freshness_minutes": None,
        "collection_latency_ms": None,
        "source_counts": {},
        "source_errors": {},
        "topic_snapshots": [],
        "focus_topics": [],
        "quality_status": "unavailable",
        "method": (
            "MT7 samples recent public Bluesky search results asynchronously, then "
            "measures activity, author diversity, duplicate language, concentration, "
            "and change versus its own trailing snapshots."
        ),
        "limits": [
            "Coverage is currently Bluesky-only; it is not a cross-platform measure of total crypto attention.",
            "Search results are a bounded sample shaped by Bluesky indexing and ranking, not a complete firehose.",
            "Engagement and post volume do not establish truth, price direction, or account credibility.",
            "Social evidence is advisory and cannot create, score, size, or execute a trade.",
        ],
    }
    run = con.execute(
        """
        SELECT collected_at,latency_ms,stored_topics,total_posts,unique_authors,
               source_counts_json,source_errors_json
        FROM social_collection_runs
        WHERE collected_at<?
        ORDER BY collected_at DESC LIMIT 1
        """,
        (end_iso,),
    ).fetchone()
    if not run:
        return packet
    try:
        source_counts = json.loads(run["source_counts_json"] or "{}")
    except Exception:
        source_counts = {}
    try:
        source_errors = json.loads(run["source_errors_json"] or "{}")
    except Exception:
        source_errors = {"parse": "invalid social source-health metadata"}
    latest = str(run["collected_at"])
    try:
        latest_dt = datetime.fromisoformat(latest.replace("Z", "+00:00")).replace(tzinfo=None)
        freshness = max(0, (datetime.utcnow() - latest_dt).total_seconds() / 60)
    except Exception:
        freshness = None
    rows = [
        dict(row) for row in con.execute(
            """
            SELECT captured_at,source_key,source_name,source_url,topic_key,query_text,
                   symbol,post_count,unique_authors,total_likes,total_reposts,
                   total_replies,top_author_share_pct,duplicate_text_share_pct,
                   posts_per_hour,engagement_per_post,activity_vs_baseline_pct,
                   baseline_observations,evidence_quality,quality_flags_json,
                   examples_json,source_time_quality
            FROM social_activity_snapshots
            WHERE captured_at=?
            ORDER BY post_count DESC
            LIMIT 20
            """,
            (latest,),
        ).fetchall()
    ]
    for row in rows:
        try:
            row["quality_flags"] = json.loads(row.pop("quality_flags_json") or "[]")
        except Exception:
            row["quality_flags"] = ["invalid_quality_metadata"]
        try:
            row["examples"] = json.loads(row.pop("examples_json") or "[]")
        except Exception:
            row["examples"] = []
        row["focus_match"] = bool(row.get("symbol") in focus)
    focus_rows = [row for row in rows if row.get("focus_match")]
    quality_rank = {"usable_single_source": 3, "thin": 2, "concentrated": 1}
    lead_quality = max(
        (str(row.get("evidence_quality") or "unavailable") for row in rows),
        key=lambda value: quality_rank.get(value, 0),
        default="unavailable",
    )
    packet.update({
        "available": bool(rows),
        "last_collected_at": latest,
        "freshness_minutes": round(freshness, 1) if freshness is not None else None,
        "collection_latency_ms": int(run["latency_ms"] or 0),
        "source_counts": source_counts,
        "source_errors": source_errors,
        "total_posts": int(run["total_posts"] or 0),
        "sampled_unique_authors": int(run["unique_authors"] or 0),
        "topic_snapshots": rows,
        "focus_topics": focus_rows[:10],
        "quality_status": lead_quality,
        "source_family_count": len({
            str(row.get("source_key") or "") for row in rows if row.get("source_key")
        }),
    })
    return packet


def _evidence_cohort_metrics(rows: list[dict]) -> dict:
    pnl = [
        _report_float(row.get("pnl_pct"), None)
        for row in rows if row.get("pnl_pct") is not None
    ]
    good = sum(
        1 for row in rows
        if str(row.get("result") or "").upper() in {
            "WIN", "PARTIAL", "TP1", "TP2", "TP3",
        }
    )
    return {
        "sample": len(rows),
        "resolved": sum(1 for row in rows if str(row.get("result") or "").strip()),
        "win_partial_rate_pct": round(good / len(rows) * 100, 1) if rows else None,
        "avg_pnl_pct": round(sum(pnl) / len(pnl), 3) if pnl else None,
    }


def _report_evidence_outcome_audit(
    con: sqlite3.Connection,
    end_iso: str,
    *,
    days: int = 30,
) -> dict:
    """Measure report evidence against later outcomes; never modify scoring."""
    cutoff = (
        datetime.fromisoformat(end_iso) - timedelta(days=max(7, min(days, 90)))
    ).isoformat()
    packet = {
        "available": False,
        "status": "collecting_baseline",
        "window_days": max(7, min(days, 90)),
        "minimum_resolved_sample": 30,
        "scoring_eligible": False,
        "signal_cohorts": {},
        "large_mover_audit": {
            "threshold_abs_move_pct": 8,
            "observations": 0,
            "with_prior_evidence": 0,
            "with_mt7_signal": 0,
            "missed_without_signal": 0,
        },
        "method": (
            "A signal is tagged only when the evidence snapshot/publication existed "
            "before the signal timestamp. Cohorts compare resolved outcomes with and "
            "without each evidence family. Large-mover coverage uses retained daily "
            "ticker snapshots and an 8% absolute-move review threshold."
        ),
        "limits": [
            "This is an observational forward audit, not a causal backtest.",
            "New evidence feeds need enough post-deployment outcomes before comparison is meaningful.",
            "No cohort can change conviction, leverage, size, or execution without a separately approved experiment.",
        ],
    }
    tables = {
        str(row[0]) for row in con.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()
    }
    if "signals" not in tables:
        return packet
    signal_columns = {
        str(row[1]) for row in con.execute("PRAGMA table_info(signals)").fetchall()
    }
    if not {"symbol", "logged_at", "result"} <= signal_columns:
        return packet
    pnl_expr = "pnl_pct" if "pnl_pct" in signal_columns else "NULL"
    signals = [
        dict(row) for row in con.execute(
            f"""
            SELECT symbol,logged_at,result,{pnl_expr} AS pnl_pct
            FROM signals
            WHERE logged_at>=? AND logged_at<?
              AND UPPER(COALESCE(result,'')) IN
                  ('WIN','LOSS','PARTIAL','TP1','TP2','TP3')
            ORDER BY logged_at
            LIMIT 3000
            """,
            (cutoff, end_iso),
        ).fetchall()
    ]
    social_rows = []
    if "social_activity_snapshots" in tables:
        social_rows = [
            dict(row) for row in con.execute(
                """
                SELECT captured_at,symbol,evidence_quality
                FROM social_activity_snapshots
                WHERE captured_at>=? AND captured_at<?
                ORDER BY captured_at
                """,
                ((datetime.fromisoformat(cutoff) - timedelta(hours=6)).isoformat(), end_iso),
            ).fetchall()
        ]
    catalyst_rows = []
    if "catalyst_events" in tables:
        catalyst_rows = [
            dict(row) for row in con.execute(
                """
                SELECT published_at,event_at,affected_assets_json
                FROM catalyst_events
                WHERE COALESCE(published_at,observed_at)>=?
                  AND COALESCE(published_at,observed_at)<?
                LIMIT 3000
                """,
                ((datetime.fromisoformat(cutoff) - timedelta(days=2)).isoformat(), end_iso),
            ).fetchall()
        ]
        for row in catalyst_rows:
            try:
                row["assets"] = json.loads(row.get("affected_assets_json") or "[]")
            except Exception:
                row["assets"] = []
    token_rows = []
    if "tokenomics_asset_snapshots" in tables:
        token_rows = [
            dict(row) for row in con.execute(
                """
                SELECT captured_at,symbol,float_pct,fdv_market_cap_ratio
                FROM tokenomics_asset_snapshots
                WHERE captured_at>=? AND captured_at<?
                ORDER BY captured_at
                LIMIT 3000
                """,
                ((datetime.fromisoformat(cutoff) - timedelta(days=1)).isoformat(), end_iso),
            ).fetchall()
        ]

    cohorts = {
        "social_activity": {"with": [], "without": []},
        "official_catalyst": {"with": [], "without": []},
        "tokenomics_risk": {"with": [], "without": []},
    }
    for signal in signals:
        symbol = str(signal.get("symbol") or "")
        try:
            logged = datetime.fromisoformat(str(signal.get("logged_at") or "").replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            continue
        has_social = any(
            row.get("symbol") in {None, "", symbol}
            and row.get("evidence_quality") in {"usable_single_source", "thin", "concentrated"}
            and timedelta(0) <= logged - datetime.fromisoformat(str(row["captured_at"])) <= timedelta(hours=6)
            for row in social_rows
        )
        has_catalyst = False
        for row in catalyst_rows:
            published = _catalyst_iso(row.get("published_at"))
            if not published:
                continue
            try:
                age = logged - datetime.fromisoformat(published)
            except Exception:
                continue
            if timedelta(0) <= age <= timedelta(hours=24) and (
                symbol in row.get("assets", []) or "MARKET" in row.get("assets", [])
            ):
                has_catalyst = True
                break
        has_tokenomics = any(
            row.get("symbol") == symbol
            and datetime.fromisoformat(str(row["captured_at"])) <= logged
            and (
                (_report_float(row.get("float_pct"), 100) < 35)
                or (_report_float(row.get("fdv_market_cap_ratio"), 0) >= 2)
            )
            for row in token_rows
        )
        for key, present in (
            ("social_activity", has_social),
            ("official_catalyst", has_catalyst),
            ("tokenomics_risk", has_tokenomics),
        ):
            cohorts[key]["with" if present else "without"].append(signal)
    packet["signal_cohorts"] = {
        key: {
            "with_evidence": _evidence_cohort_metrics(value["with"]),
            "without_evidence": _evidence_cohort_metrics(value["without"]),
        }
        for key, value in cohorts.items()
    }

    if "ticker_daily_snapshots" in tables:
        movers = [
            dict(row) for row in con.execute(
                """
                SELECT day,symbol,change_24h_pct
                FROM ticker_daily_snapshots
                WHERE day>=? AND day<?
                  AND ABS(COALESCE(change_24h_pct,0))>=8
                ORDER BY day DESC,ABS(change_24h_pct) DESC
                LIMIT 1000
                """,
                (cutoff[:10], end_iso[:10]),
            ).fetchall()
        ]
        signal_keys = {
            (str(row.get("logged_at") or "")[:10], str(row.get("symbol") or ""))
            for row in signals
        }
        with_evidence = 0
        with_signal = 0
        for mover in movers:
            day, symbol = str(mover.get("day") or ""), str(mover.get("symbol") or "")
            if (day, symbol) in signal_keys:
                with_signal += 1
            try:
                day_end = datetime.fromisoformat(day) + timedelta(days=1)
            except Exception:
                continue
            prior_social = any(
                row.get("symbol") == symbol
                and datetime.fromisoformat(str(row["captured_at"])) < day_end
                and datetime.fromisoformat(str(row["captured_at"])) >= day_end - timedelta(hours=24)
                for row in social_rows
            )
            prior_token = any(
                row.get("symbol") == symbol
                and datetime.fromisoformat(str(row["captured_at"])) < day_end
                for row in token_rows
            )
            prior_catalyst = False
            for row in catalyst_rows:
                published = _catalyst_iso(row.get("published_at"))
                if not published:
                    continue
                if (
                    day_end - timedelta(days=2)
                    <= datetime.fromisoformat(published)
                    < day_end
                    and symbol in row.get("assets", [])
                ):
                    prior_catalyst = True
                    break
            if prior_social or prior_token or prior_catalyst:
                with_evidence += 1
        packet["large_mover_audit"].update({
            "observations": len(movers),
            "with_prior_evidence": with_evidence,
            "with_mt7_signal": with_signal,
            "missed_without_signal": max(0, len(movers) - with_signal),
        })
    resolved = len(signals)
    packet.update({
        "available": bool(signals or packet["large_mover_audit"]["observations"]),
        "status": "descriptive_only" if resolved >= 30 else "collecting_baseline",
        "resolved_signal_sample": resolved,
        "scoring_eligible": False,
    })
    return packet


def _cached_report_evidence_outcome_audit(
    con: sqlite3.Connection,
    end_iso: str,
    *,
    days: int = 30,
) -> dict:
    """Read the latest background audit snapshot without running cohort joins."""
    row = con.execute(
        """
        SELECT generated_at,audit_json,latency_ms
        FROM report_evidence_audit_snapshots
        WHERE window_days=? AND generated_at<=?
        ORDER BY generated_at DESC LIMIT 1
        """,
        (max(7, min(days, 90)), end_iso),
    ).fetchone()
    if not row:
        return {
            "available": False,
            "status": "awaiting_background_audit",
            "scoring_eligible": False,
            "signal_cohorts": {},
            "large_mover_audit": {},
            "limits": [
                "The background outcome audit has not completed yet.",
                "No evidence family has scoring authority.",
            ],
        }
    try:
        packet = json.loads(row["audit_json"] or "{}")
    except Exception:
        packet = {
            "available": False,
            "status": "invalid_cached_audit",
            "scoring_eligible": False,
        }
    packet["generated_at"] = str(row["generated_at"])
    packet["evaluation_latency_ms"] = int(row["latency_ms"] or 0)
    packet["cache_mode"] = "background_snapshot"
    packet["scoring_eligible"] = False
    return packet


def _refresh_report_evidence_outcome_audit(days: int = 30) -> dict:
    """Compute and persist the audit off the report request path."""
    started = time.perf_counter()
    generated_at = datetime.utcnow().replace(microsecond=0).isoformat()
    con = sqlite3.connect(DB_PATH, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        audit = _report_evidence_outcome_audit(
            con,
            generated_at,
            days=max(7, min(days, 90)),
        )
        latency_ms = round((time.perf_counter() - started) * 1000)
        con.execute(
            """
            INSERT OR REPLACE INTO report_evidence_audit_snapshots
                (generated_at,window_days,audit_json,latency_ms)
            VALUES (?,?,?,?)
            """,
            (
                generated_at,
                max(7, min(days, 90)),
                json.dumps(audit, sort_keys=True, default=str),
                latency_ms,
            ),
        )
        con.execute(
            "DELETE FROM report_evidence_audit_snapshots WHERE generated_at<?",
            ((datetime.utcnow() - timedelta(days=30)).isoformat(),),
        )
        con.commit()
    finally:
        con.close()
    return {
        "generated_at": generated_at,
        "window_days": max(7, min(days, 90)),
        "latency_ms": latency_ms,
        "status": audit.get("status"),
        "resolved_signal_sample": audit.get("resolved_signal_sample", 0),
        "scoring_eligible": False,
    }


def _report_market_history_evidence(
    date_str: str,
    *,
    days: int = 1,
    focus_symbols: list[str] | None = None,
) -> dict:
    """Build bounded specialist evidence from persisted market and order-flow tables.

    This intentionally uses indexed ranges and aggregate queries. Reports receive
    compact facts rather than raw tape, keeping cache files and request latency small.
    """
    start, end = _report_date_bounds(date_str, days=days)
    start_iso, end_iso = start.isoformat(), end.isoformat()
    start_ts = int(start.replace(tzinfo=timezone.utc).timestamp())
    end_ts = int(end.replace(tzinfo=timezone.utc).timestamp())
    focus = list(dict.fromkeys(
        str(s or "").upper() for s in (focus_symbols or []) if str(s or "").strip()
    ))[:8]
    evidence = {
        "window": {
            "start": start_iso,
            "end": end_iso,
            "days": days,
        },
        "market_history": {
            "available": False,
            "snapshot_count": 0,
            "symbol_count": 0,
            "venue_count": 0,
            "first_snapshot": None,
            "last_snapshot": None,
            "breadth_path": [],
            "price_rotations": [],
            "oi_rotations": [],
        },
        "market_context": {
            "available": False,
            "observations": 0,
        },
        "structural_history": {
            "available": False,
            "window_days": 30,
            "daily_observations": 0,
            "symbol_count": 0,
            "breadth_path": [],
            "price_rotations": [],
            "oi_rotations": [],
        },
        "order_flow": {
            "available": False,
            "venue": "MEXC",
            "symbol_count": 0,
            "symbols": [],
            "retention": "72 hours",
        },
        "cross_venue": {
            "available": False,
            "matched_two_venue": 0,
            "matched_three_venue": 0,
            "price_dislocations": [],
            "funding_divergences": [],
            "focus_assets": [],
            "symbol_mismatches": [],
        },
        "catalysts": {
            "available": False,
            "events_in_window": [],
            "upcoming_events": [],
            "active_incidents": [],
            "focus_events": [],
            "source_errors": {},
        },
        "tokenomics": {
            "available": False,
            "asset_snapshots": [],
            "focus_assets": [],
            "float_risk_assets": [],
            "upcoming_unlocks": [],
            "focus_unlocks": [],
            "treasury_snapshots": [],
            "focus_treasuries": [],
            "source_errors": {},
        },
        "social": {
            "available": False,
            "topic_snapshots": [],
            "focus_topics": [],
            "source_errors": {},
            "quality_status": "unavailable",
        },
        "evidence_outcomes": {
            "available": False,
            "status": "collecting_baseline",
            "scoring_eligible": False,
            "signal_cohorts": {},
        },
    }
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        tables = {
            str(r[0]) for r in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        }
        if "ticker_snapshots" in tables:
            coverage = con.execute(
                """
                SELECT MIN(ts), MAX(ts), COUNT(*), COUNT(DISTINCT symbol),
                       COUNT(DISTINCT exchange)
                FROM ticker_snapshots
                WHERE ts>=? AND ts<?
                """,
                (start_iso, end_iso),
            ).fetchone()
            first_ts, last_ts = coverage[0], coverage[1]
            history = evidence["market_history"]
            history.update({
                "available": bool(coverage[2]),
                "first_snapshot": first_ts,
                "last_snapshot": last_ts,
                "snapshot_count": int(coverage[2] or 0),
                "symbol_count": int(coverage[3] or 0),
                "venue_count": int(coverage[4] or 0),
            })
            timeline = [
                dict(r) for r in con.execute(
                    """
                    SELECT ts,
                           COUNT(*) AS symbols,
                           SUM(CASE WHEN change_24h_pct>0.25 THEN 1 ELSE 0 END) AS advancers,
                           SUM(CASE WHEN change_24h_pct<-0.25 THEN 1 ELSE 0 END) AS decliners,
                           AVG(change_24h_pct) AS average_move_pct,
                           SUM(CASE WHEN funding_rate<-0.001 THEN 1 ELSE 0 END) AS extreme_negative_funding,
                           SUM(CASE WHEN funding_rate>0.001 THEN 1 ELSE 0 END) AS extreme_positive_funding,
                           SUM(open_interest) AS aggregate_open_interest
                    FROM ticker_snapshots
                    WHERE ts>=? AND ts<?
                    GROUP BY ts
                    ORDER BY ts
                    """,
                    (start_iso, end_iso),
                ).fetchall()
            ]
            if len(timeline) > 32:
                stride = max(1, len(timeline) // 31)
                timeline = timeline[::stride]
                if timeline[-1].get("ts") != last_ts:
                    last_row = con.execute(
                        """
                        SELECT ts, COUNT(*) AS symbols,
                               SUM(CASE WHEN change_24h_pct>0.25 THEN 1 ELSE 0 END) AS advancers,
                               SUM(CASE WHEN change_24h_pct<-0.25 THEN 1 ELSE 0 END) AS decliners,
                               AVG(change_24h_pct) AS average_move_pct,
                               SUM(CASE WHEN funding_rate<-0.001 THEN 1 ELSE 0 END) AS extreme_negative_funding,
                               SUM(CASE WHEN funding_rate>0.001 THEN 1 ELSE 0 END) AS extreme_positive_funding,
                               SUM(open_interest) AS aggregate_open_interest
                        FROM ticker_snapshots WHERE ts=? GROUP BY ts
                        """,
                        (last_ts,),
                    ).fetchone()
                    if last_row:
                        timeline.append(dict(last_row))
            for row in timeline:
                row["average_move_pct"] = round(_report_float(row.get("average_move_pct")), 3)
                row["aggregate_open_interest"] = round(_report_float(row.get("aggregate_open_interest")), 2)
            history["breadth_path"] = timeline
            if first_ts and last_ts and first_ts != last_ts:
                first_rows = {
                    str(r["symbol"]): dict(r) for r in con.execute(
                        """
                        SELECT symbol, price, funding_rate, open_interest
                        FROM ticker_snapshots WHERE ts=?
                        """,
                        (first_ts,),
                    ).fetchall()
                }
                last_rows = {
                    str(r["symbol"]): dict(r) for r in con.execute(
                        """
                        SELECT symbol, price, funding_rate, open_interest
                        FROM ticker_snapshots WHERE ts=?
                        """,
                        (last_ts,),
                    ).fetchall()
                }
                rotations = []
                for symbol, latest in last_rows.items():
                    prior = first_rows.get(symbol)
                    if not prior:
                        continue
                    first_price = _report_float(prior.get("price"))
                    last_price = _report_float(latest.get("price"))
                    first_oi = _report_float(prior.get("open_interest"))
                    last_oi = _report_float(latest.get("open_interest"))
                    price_return = ((last_price / first_price) - 1) * 100 if first_price else 0
                    oi_change = ((last_oi / first_oi) - 1) * 100 if first_oi else None
                    rotations.append({
                        "symbol": symbol,
                        "price_return_pct": round(price_return, 2),
                        "oi_change_pct": round(oi_change, 2) if oi_change is not None else None,
                        "funding_start": _report_float(prior.get("funding_rate")),
                        "funding_end": _report_float(latest.get("funding_rate")),
                    })
                history["price_rotations"] = sorted(
                    rotations,
                    key=lambda x: abs(_report_float(x.get("price_return_pct"))),
                    reverse=True,
                )[:8]
                history["oi_rotations"] = sorted(
                    [x for x in rotations if x.get("oi_change_pct") is not None],
                    key=lambda x: abs(_report_float(x.get("oi_change_pct"))),
                    reverse=True,
                )[:8]

        if "ticker_daily_snapshots" in tables:
            structural_start = (end - timedelta(days=30)).strftime("%Y-%m-%d")
            structural_end = end.strftime("%Y-%m-%d")
            daily_path = [
                dict(r) for r in con.execute(
                    """
                    SELECT day, COUNT(*) AS symbols,
                           SUM(CASE WHEN change_24h_pct>0.25 THEN 1 ELSE 0 END) AS advancers,
                           SUM(CASE WHEN change_24h_pct<-0.25 THEN 1 ELSE 0 END) AS decliners,
                           AVG(change_24h_pct) AS average_move_pct,
                           SUM(CASE WHEN funding_rate<-0.001 THEN 1 ELSE 0 END) AS extreme_negative_funding,
                           SUM(CASE WHEN funding_rate>0.001 THEN 1 ELSE 0 END) AS extreme_positive_funding
                    FROM ticker_daily_snapshots
                    WHERE day>=? AND day<?
                    GROUP BY day
                    ORDER BY day
                    """,
                    (structural_start, structural_end),
                ).fetchall()
            ]
            if daily_path:
                for row in daily_path:
                    row["average_move_pct"] = round(_report_float(row.get("average_move_pct")), 3)
                first_day = str(daily_path[0]["day"])
                last_day = str(daily_path[-1]["day"])
                first_rows = {
                    str(r["symbol"]): dict(r) for r in con.execute(
                        """
                        SELECT symbol, price, funding_rate, open_interest
                        FROM ticker_daily_snapshots WHERE day=?
                        """,
                        (first_day,),
                    ).fetchall()
                }
                last_rows = {
                    str(r["symbol"]): dict(r) for r in con.execute(
                        """
                        SELECT symbol, price, funding_rate, open_interest
                        FROM ticker_daily_snapshots WHERE day=?
                        """,
                        (last_day,),
                    ).fetchall()
                }
                rotations = []
                if first_day != last_day:
                    for symbol, latest in last_rows.items():
                        prior = first_rows.get(symbol)
                        if not prior:
                            continue
                        first_price = _report_float(prior.get("price"))
                        last_price = _report_float(latest.get("price"))
                        first_oi = _report_float(prior.get("open_interest"))
                        last_oi = _report_float(latest.get("open_interest"))
                        rotations.append({
                            "symbol": symbol,
                            "price_return_pct": round(
                                ((last_price / first_price) - 1) * 100 if first_price else 0,
                                2,
                            ),
                            "oi_change_pct": round(
                                ((last_oi / first_oi) - 1) * 100,
                                2,
                            ) if first_oi else None,
                            "funding_start": _report_float(prior.get("funding_rate")),
                            "funding_end": _report_float(latest.get("funding_rate")),
                        })
                evidence["structural_history"] = {
                    "available": True,
                    "window_days": 30,
                    "first_day": first_day,
                    "last_day": last_day,
                    "daily_observations": len(daily_path),
                    "symbol_count": int(daily_path[-1].get("symbols") or 0),
                    "breadth_path": daily_path,
                    "price_rotations": sorted(
                        rotations,
                        key=lambda x: abs(_report_float(x.get("price_return_pct"))),
                        reverse=True,
                    )[:8],
                    "oi_rotations": sorted(
                        [x for x in rotations if x.get("oi_change_pct") is not None],
                        key=lambda x: abs(_report_float(x.get("oi_change_pct"))),
                        reverse=True,
                    )[:8],
                }

        if "market_context_snapshots" in tables:
            rows = [
                dict(r) for r in con.execute(
                    """
                    SELECT ts, btc_price, btc_rsi_1h, btc_trend, btc_change_24h,
                           eth_price, eth_rsi_1h, eth_trend, btc_ls_ratio
                    FROM market_context_snapshots
                    WHERE ts>=? AND ts<?
                    ORDER BY ts
                    LIMIT 240
                    """,
                    (start_iso, end_iso),
                ).fetchall()
            ]
            if rows:
                trend_flips = sum(
                    1 for prev, cur in zip(rows, rows[1:])
                    if prev.get("btc_trend") and cur.get("btc_trend")
                    and prev.get("btc_trend") != cur.get("btc_trend")
                )
                first, latest = rows[0], rows[-1]
                first_btc = _report_float(first.get("btc_price"))
                last_btc = _report_float(latest.get("btc_price"))
                evidence["market_context"] = {
                    "available": True,
                    "observations": len(rows),
                    "first_snapshot": first,
                    "latest_snapshot": latest,
                    "btc_window_return_pct": round(
                        ((last_btc / first_btc) - 1) * 100 if first_btc else 0,
                        2,
                    ),
                    "btc_trend_flips": trend_flips,
                    "btc_rsi_change": round(
                        _report_float(latest.get("btc_rsi_1h"))
                        - _report_float(first.get("btc_rsi_1h")),
                        2,
                    ),
                }

        if {
            "cross_venue_snapshots",
            "cross_venue_collection_runs",
        } <= tables:
            evidence["cross_venue"] = _report_cross_venue_evidence(
                con,
                start_iso,
                end_iso,
                focus_symbols=focus,
            )

        if {
            "catalyst_events",
            "catalyst_collection_runs",
        } <= tables:
            evidence["catalysts"] = _report_catalyst_evidence(
                con,
                start_iso,
                end_iso,
                focus_symbols=focus,
                lookahead_days=14 if days >= 7 else 7,
            )

        if {
            "tokenomics_asset_snapshots",
            "token_unlock_events",
            "token_treasury_snapshots",
            "tokenomics_collection_runs",
        } <= tables:
            evidence["tokenomics"] = _report_tokenomics_evidence(
                con,
                start_iso,
                end_iso,
                focus_symbols=focus,
                lookahead_days=120 if days >= 7 else 90,
            )

        if {
            "social_activity_snapshots",
            "social_collection_runs",
        } <= tables:
            evidence["social"] = _report_social_evidence(
                con,
                start_iso,
                end_iso,
                focus_symbols=focus,
            )

        if "report_evidence_audit_snapshots" in tables:
            evidence["evidence_outcomes"] = _cached_report_evidence_outcome_audit(
                con,
                end_iso,
                days=30,
            )

        if focus and {"order_flow_trades", "order_flow_depth_snapshots"} <= tables:
            marks = ",".join("?" for _ in focus)
            params = [*focus, start_ts, end_ts]
            trade_rows = [
                dict(r) for r in con.execute(
                    f"""
                    SELECT symbol, COUNT(*) AS trade_count,
                           SUM(volume) AS total_volume,
                           SUM(CASE WHEN LOWER(side)='buy' THEN volume ELSE 0 END) AS buy_volume,
                           SUM(CASE WHEN LOWER(side)='sell' THEN volume ELSE 0 END) AS sell_volume
                    FROM order_flow_trades
                    WHERE exchange='MEXC' AND symbol IN ({marks}) AND ts>=? AND ts<?
                    GROUP BY symbol
                    """,
                    params,
                ).fetchall()
            ]
            depth_rows = {
                str(r["symbol"]): dict(r) for r in con.execute(
                    f"""
                    SELECT symbol, COUNT(*) AS depth_samples,
                           AVG(imbalance) AS average_imbalance,
                           AVG(CASE WHEN best_bid>0 AND best_ask>0
                               THEN ((best_ask-best_bid)/((best_ask+best_bid)/2))*10000
                               ELSE NULL END) AS average_spread_bps,
                           AVG(bid_total) AS average_bid_depth,
                           AVG(ask_total) AS average_ask_depth
                    FROM order_flow_depth_snapshots
                    WHERE exchange='MEXC' AND symbol IN ({marks}) AND ts>=? AND ts<?
                    GROUP BY symbol
                    """,
                    params,
                ).fetchall()
            }
            packets = []
            for row in trade_rows:
                symbol = str(row.get("symbol") or "")
                total = _report_float(row.get("total_volume"))
                buy = _report_float(row.get("buy_volume"))
                sell = _report_float(row.get("sell_volume"))
                depth = depth_rows.get(symbol, {})
                packets.append({
                    "symbol": symbol,
                    "trade_count": int(row.get("trade_count") or 0),
                    "total_volume": round(total, 4),
                    "aggressive_buy_pct": round(buy / total * 100, 1) if total else None,
                    "flow_delta_pct": round((buy - sell) / total * 100, 1) if total else None,
                    "depth_samples": int(depth.get("depth_samples") or 0),
                    "average_imbalance": round(_report_float(depth.get("average_imbalance")), 3),
                    "average_spread_bps": round(_report_float(depth.get("average_spread_bps")), 2),
                    "average_bid_depth": round(_report_float(depth.get("average_bid_depth")), 4),
                    "average_ask_depth": round(_report_float(depth.get("average_ask_depth")), 4),
                })
            evidence["order_flow"].update({
                "available": bool(packets),
                "symbol_count": len(packets),
                "symbols": sorted(packets, key=lambda x: x.get("trade_count", 0), reverse=True),
            })
        con.close()
    except Exception as e:
        print(f"[report_market_history] {e}", file=sys.stderr)
    return evidence


def _missed_mover_context(symbol: str, date_str: str) -> dict:
    """Explain whether an explosive mover was signaled, blocked, or truly missed."""
    ctx = _report_explosive_signal_context(symbol, date_str)
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        recent = con.execute("""
            SELECT logged_at, direction, strategy_key, conviction, result, pnl_pct, source
            FROM signals
            WHERE symbol=?
            ORDER BY logged_at DESC
            LIMIT 1
        """, (symbol,)).fetchone()
        if recent:
            ctx["last_signal"] = dict(recent)
        blocked_recent = con.execute("""
            SELECT logged_at, gate_key, gate_mode, strategy_key, direction, conviction, reason
            FROM filtered_candidates
            WHERE symbol=?
            ORDER BY logged_at DESC
            LIMIT 1
        """, (symbol,)).fetchone()
        if blocked_recent:
            ctx["last_block"] = dict(blocked_recent)
        con.close()
    except Exception as e:
        print(f"[missed_mover_context] {symbol}: {e}", file=sys.stderr)
    return ctx


def _build_missed_mover_autopsy(date_str: str | None = None, limit: int = 12) -> dict:
    """Rank large movers and classify whether MT7 caught, blocked, or missed them."""
    date_str = date_str or datetime.utcnow().strftime("%Y-%m-%d")
    limit = max(3, min(int(limit or 12), 30))
    tickers = _report_fetch_ticker_snapshot()
    movers = []
    for ticker in tickers:
        symbol = _report_symbol(ticker)
        if not symbol:
            continue
        change = _report_percent_change(ticker)
        volume = _report_volume(ticker)
        funding = _report_funding(ticker)
        if abs(change) < 8:
            continue
        context = _missed_mover_context(symbol, date_str)
        had_signal = bool(context.get("had_signal"))
        was_blocked = bool(context.get("was_blocked"))
        if had_signal:
            classification = "caught"
            verdict = "MT7 generated a signal today; audit entry timing and result."
        elif was_blocked:
            classification = "blocked"
            verdict = f"Risk gate blocked it before recommendation: {context.get('block_gate') or 'unknown gate'}."
        else:
            classification = "missed"
            verdict = "No signal or block record today. This is an edge-discovery candidate."
        abs_change = abs(change)
        crowding = "short_squeeze_risk" if funding < -0.001 else "long_flush_risk" if funding > 0.001 else "neutral_funding"
        mover_score = abs_change
        if abs(funding) > 0.001:
            mover_score += min(20, abs(funding) * 5000)
        if volume >= 1_000_000:
            mover_score += 5
        movers.append({
            "symbol": symbol,
            "exchange": ticker.get("exchange") or "MEXC",
            "change_24h_pct": round(change, 2),
            "volume_24h": round(volume, 0),
            "funding_rate": funding,
            "funding_crowding": crowding,
            "classification": classification,
            "verdict": verdict,
            "context": context,
            "mover_score": round(mover_score, 2),
            "next_step": (
                "Compare scan cadence, kline depth, funding threshold, and flow confirmation at move start."
                if classification == "missed"
                else "Review whether the existing decision was correct before changing scanner logic."
            ),
        })
    movers.sort(key=lambda x: (x["classification"] == "missed", x["mover_score"]), reverse=True)
    counts = {
        "missed": sum(1 for m in movers if m["classification"] == "missed"),
        "caught": sum(1 for m in movers if m["classification"] == "caught"),
        "blocked": sum(1 for m in movers if m["classification"] == "blocked"),
    }
    # The screen and research queue consume only the ranked display set.
    # Enriching every 8% mover sequentially made first paint exceed 50 seconds
    # on broad volatile days without adding visible decision value.
    shadow_summary = _record_explosive_shadow_events(date_str, movers[:limit])
    return {
        "date": date_str,
        "generated_at": datetime.utcnow().isoformat(),
        "total_candidates": len(movers),
        "counts": counts,
        "shadow_summary": shadow_summary,
        "movers": movers[:limit],
        "rules": [
            "A missed mover is not an entry signal.",
            "Only fresh MT7 signals with risk gates passed can become trade candidates.",
            "Use repeated missed patterns to add shadow features, not one-off symbol hacks.",
        ],
    }


def _pct_change(new: float, old: float) -> float | None:
    try:
        if old == 0:
            return None
        return (float(new) - float(old)) / float(old) * 100
    except Exception:
        return None


def _ensure_explosive_shadow_table() -> None:
    con = sqlite3.connect(DB_PATH)
    con.execute("""
        CREATE TABLE IF NOT EXISTS explosive_move_shadow (
            id                 INTEGER PRIMARY KEY AUTOINCREMENT,
            date               TEXT NOT NULL,
            recorded_at        TEXT NOT NULL,
            symbol             TEXT NOT NULL,
            exchange           TEXT NOT NULL DEFAULT 'MEXC',
            direction          TEXT NOT NULL,
            change_24h_pct     REAL,
            funding_rate       REAL,
            volume_24h         REAL,
            classification     TEXT,
            had_signal         INTEGER DEFAULT 0,
            was_blocked        INTEGER DEFAULT 0,
            prior_3h_return    REAL,
            prior_6h_return    REAL,
            impulse_1h_return  REAL,
            volume_expansion   REAL,
            range_expansion    REAL,
            wick_pressure      REAL,
            shadow_score       REAL,
            clue_label         TEXT,
            context_json       TEXT,
            UNIQUE(date, symbol)
        )
    """)
    con.execute("CREATE INDEX IF NOT EXISTS idx_explosive_shadow_date ON explosive_move_shadow (date, shadow_score)")
    con.commit()
    con.close()


def _ensure_research_radar_alerts_table() -> None:
    con = sqlite3.connect(DB_PATH)
    con.execute("""
        CREATE TABLE IF NOT EXISTS research_radar_alerts (
            id                    INTEGER PRIMARY KEY AUTOINCREMENT,
            template_key          TEXT NOT NULL,
            shadow_id             INTEGER,
            date                  TEXT NOT NULL,
            recorded_at           TEXT NOT NULL,
            symbol                TEXT NOT NULL,
            exchange              TEXT NOT NULL DEFAULT 'MEXC',
            direction             TEXT,
            classification        TEXT,
            change_24h_pct        REAL,
            funding_rate          REAL,
            volume_24h            REAL,
            shadow_score          REAL,
            clue_label            TEXT,
            context_json          TEXT,
            status                TEXT DEFAULT 'pending',
            scored_at             TEXT,
            forward_window_days   INTEGER DEFAULT 7,
            next_signal_id        INTEGER,
            next_signal_at        TEXT,
            next_signal_direction TEXT,
            next_signal_strategy  TEXT,
            next_signal_result    TEXT,
            next_signal_pnl_pct   REAL,
            next_signal_net_est_pct REAL,
            UNIQUE(template_key, shadow_id)
        )
    """)
    con.execute("CREATE INDEX IF NOT EXISTS idx_research_radar_alerts_template ON research_radar_alerts (template_key, recorded_at)")
    con.execute("CREATE INDEX IF NOT EXISTS idx_research_radar_alerts_symbol ON research_radar_alerts (symbol, recorded_at)")
    con.execute("CREATE INDEX IF NOT EXISTS idx_research_radar_alerts_status ON research_radar_alerts (status, recorded_at)")
    con.commit()
    con.close()


def _explosive_shadow_features(symbol: str, change_24h_pct: float, funding_rate: float, volume_24h: float) -> dict:
    """Build non-execution research features for a current explosive mover."""
    features = {
        "prior_3h_return": None,
        "prior_6h_return": None,
        "impulse_1h_return": None,
        "volume_expansion": None,
        "range_expansion": None,
        "wick_pressure": None,
        "shadow_score": 0,
        "clues": [],
        "clue_label": "insufficient_kline_context",
    }
    try:
        raw = fetch_mexc(f"/contract/kline/{symbol}", params={"interval": "Min60", "limit": 36})
        if not raw or not isinstance(raw, dict):
            return features
        opens = [float(x) for x in (raw.get("open") or [])]
        highs = [float(x) for x in (raw.get("high") or [])]
        lows = [float(x) for x in (raw.get("low") or [])]
        closes = [float(x) for x in (raw.get("close") or [])]
        vols = [float(x) for x in (raw.get("vol") or [])]
        n = min(len(opens), len(highs), len(lows), len(closes), len(vols))
        if n < 10:
            return features
        opens, highs, lows, closes, vols = opens[-n:], highs[-n:], lows[-n:], closes[-n:], vols[-n:]

        prior_3h = _pct_change(closes[-2], closes[-5]) if n >= 5 else None
        prior_6h = _pct_change(closes[-2], closes[-8]) if n >= 8 else None
        impulse_1h = _pct_change(closes[-1], closes[-2])
        recent_vol = sum(vols[-3:]) / 3
        base_vols = vols[-15:-3] if n >= 15 else vols[:-3]
        base_vol = (sum(base_vols) / len(base_vols)) if base_vols else None
        volume_expansion = (recent_vol / base_vol) if base_vol and base_vol > 0 else None
        recent_ranges = [(highs[i] - lows[i]) / closes[i] * 100 for i in range(max(0, n - 3), n) if closes[i] > 0]
        base_ranges = [(highs[i] - lows[i]) / closes[i] * 100 for i in range(max(0, n - 15), max(0, n - 3)) if closes[i] > 0]
        recent_range = sum(recent_ranges) / len(recent_ranges) if recent_ranges else None
        base_range = sum(base_ranges) / len(base_ranges) if base_ranges else None
        range_expansion = (recent_range / base_range) if base_range and base_range > 0 else None
        last_range = max(highs[-1] - lows[-1], 0)
        wick_pressure = None
        if last_range > 0:
            if change_24h_pct >= 0:
                wick_pressure = (highs[-1] - closes[-1]) / last_range
            else:
                wick_pressure = (closes[-1] - lows[-1]) / last_range

        direction = 1 if change_24h_pct >= 0 else -1
        score = min(40, abs(change_24h_pct) * 1.4)
        clues = []
        if prior_3h is not None and prior_3h * direction > 1.5:
            score += min(15, abs(prior_3h) * 2)
            clues.append("pre_move_drift")
        if prior_6h is not None and prior_6h * direction > 3:
            score += min(15, abs(prior_6h))
            clues.append("six_hour_alignment")
        if impulse_1h is not None and impulse_1h * direction > 2:
            score += min(15, abs(impulse_1h) * 1.5)
            clues.append("fresh_impulse")
        if volume_expansion is not None and volume_expansion >= 1.8:
            score += min(15, volume_expansion * 3)
            clues.append("volume_expansion")
        if range_expansion is not None and range_expansion >= 1.5:
            score += min(10, range_expansion * 2)
            clues.append("range_expansion")
        if abs(funding_rate or 0) >= 0.001:
            score += min(12, abs(funding_rate) * 5000)
            clues.append("crowded_funding")
        if volume_24h >= 1_000_000:
            score += 5
            clues.append("liquid_enough")
        if wick_pressure is not None and wick_pressure > 0.45:
            score -= 8
            clues.append("late_wick_risk")

        features.update({
            "prior_3h_return": round(prior_3h, 3) if prior_3h is not None else None,
            "prior_6h_return": round(prior_6h, 3) if prior_6h is not None else None,
            "impulse_1h_return": round(impulse_1h, 3) if impulse_1h is not None else None,
            "volume_expansion": round(volume_expansion, 3) if volume_expansion is not None else None,
            "range_expansion": round(range_expansion, 3) if range_expansion is not None else None,
            "wick_pressure": round(wick_pressure, 3) if wick_pressure is not None else None,
            "shadow_score": round(max(0, min(100, score)), 2),
            "clues": clues,
            "clue_label": ", ".join(clues[:4]) if clues else "move_only",
        })
    except Exception as e:
        print(f"[explosive_shadow_features] {symbol}: {e}", file=sys.stderr)
    return features


def _record_explosive_shadow_events(date_str: str, movers: list[dict]) -> dict:
    """Persist current explosive movers as shadow research events."""
    if not movers:
        return {"recorded": 0, "top_score": None}
    selected = [m for m in movers if m.get("symbol")]
    if not selected:
        return {"recorded": 0, "top_score": None}
    feature_rows = {}
    with ThreadPoolExecutor(max_workers=min(8, len(selected))) as executor:
        future_map = {
            executor.submit(
                _explosive_shadow_features,
                str(m.get("symbol")),
                _report_float(m.get("change_24h_pct")),
                _report_float(m.get("funding_rate")),
                _report_float(m.get("volume_24h")),
            ): str(m.get("symbol"))
            for m in selected
        }
        for future in as_completed(future_map):
            symbol = future_map[future]
            try:
                feature_rows[symbol] = future.result()
            except Exception as exc:
                print(f"[explosive_shadow_features] {symbol}: {exc}", file=sys.stderr)
                feature_rows[symbol] = {
                    "shadow_score": 0,
                    "clues": [],
                    "clue_label": "feature_fetch_failed",
                }
    rows = []
    for m in selected:
        symbol = m.get("symbol")
        change = _report_float(m.get("change_24h_pct"))
        funding = _report_float(m.get("funding_rate"))
        volume = _report_float(m.get("volume_24h"))
        feats = feature_rows.get(str(symbol)) or {}
        m["shadow"] = feats
        ctx = m.get("context") or {}
        rows.append((
            date_str,
            datetime.utcnow().isoformat(),
            symbol,
            m.get("exchange") or "MEXC",
            "UP" if change >= 0 else "DOWN",
            change,
            funding,
            volume,
            m.get("classification"),
            1 if ctx.get("had_signal") else 0,
            1 if ctx.get("was_blocked") else 0,
            feats.get("prior_3h_return"),
            feats.get("prior_6h_return"),
            feats.get("impulse_1h_return"),
            feats.get("volume_expansion"),
            feats.get("range_expansion"),
            feats.get("wick_pressure"),
            feats.get("shadow_score"),
            feats.get("clue_label"),
            json.dumps({"context": ctx, "clues": feats.get("clues", [])}, default=str),
        ))
    try:
        _ensure_explosive_shadow_table()
        con = sqlite3.connect(DB_PATH)
        con.executemany("""
            INSERT INTO explosive_move_shadow
            (date, recorded_at, symbol, exchange, direction, change_24h_pct, funding_rate, volume_24h,
             classification, had_signal, was_blocked, prior_3h_return, prior_6h_return, impulse_1h_return,
             volume_expansion, range_expansion, wick_pressure, shadow_score, clue_label, context_json)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(date, symbol) DO UPDATE SET
                recorded_at=excluded.recorded_at,
                direction=excluded.direction,
                change_24h_pct=excluded.change_24h_pct,
                funding_rate=excluded.funding_rate,
                volume_24h=excluded.volume_24h,
                classification=excluded.classification,
                had_signal=excluded.had_signal,
                was_blocked=excluded.was_blocked,
                prior_3h_return=excluded.prior_3h_return,
                prior_6h_return=excluded.prior_6h_return,
                impulse_1h_return=excluded.impulse_1h_return,
                volume_expansion=excluded.volume_expansion,
                range_expansion=excluded.range_expansion,
                wick_pressure=excluded.wick_pressure,
                shadow_score=excluded.shadow_score,
                clue_label=excluded.clue_label,
                context_json=excluded.context_json
        """, rows)
        con.commit()
        con.close()
    except Exception as e:
        print(f"[record_explosive_shadow] {e}", file=sys.stderr)
    top = max((float(r[17] or 0) for r in rows), default=None)
    return {"recorded": len(rows), "top_score": round(top, 2) if top is not None else None}


def _load_explosive_shadow(date_str: str | None = None, limit: int = 30) -> dict:
    date_str = date_str or datetime.utcnow().strftime("%Y-%m-%d")
    try:
        _ensure_explosive_shadow_table()
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        rows = [dict(r) for r in con.execute("""
            SELECT *
            FROM explosive_move_shadow
            WHERE date=?
            ORDER BY shadow_score DESC, ABS(change_24h_pct) DESC
            LIMIT ?
        """, (date_str, max(5, min(int(limit or 30), 100)))).fetchall()]
        con.close()
    except Exception as e:
        print(f"[load_explosive_shadow] {e}", file=sys.stderr)
        rows = []
    for r in rows:
        try:
            ctx = json.loads(r.get("context_json") or "{}")
        except Exception:
            ctx = {}
        r["context"] = ctx.get("context", {})
        r["clues"] = ctx.get("clues", [])
    return {
        "date": date_str,
        "count": len(rows),
        "rows": rows,
        "rules": [
            "Shadow scores do not change conviction.",
            "Repeated clue clusters become candidates for forward-tested features.",
            "No missed mover is tradable unless MT7 emits a fresh risk-gated signal.",
        ],
    }


def _evaluate_explosive_shadow_clusters(days_back: int = 14, forward_days: int = 7, min_count: int = 1) -> dict:
    """Evaluate shadow clue clusters against the next resolved signal for the same symbol."""
    days_back = max(1, min(int(days_back or 14), 90))
    forward_days = max(1, min(int(forward_days or 7), 30))
    min_count = max(1, min(int(min_count or 1), 20))
    since = (datetime.utcnow() - timedelta(days=days_back)).strftime("%Y-%m-%d")
    _ensure_explosive_shadow_table()
    rows: list[dict] = []
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        shadows = [dict(r) for r in con.execute("""
            SELECT *
            FROM explosive_move_shadow
            WHERE date >= ?
            ORDER BY recorded_at DESC
        """, (since,)).fetchall()]
        for sh in shadows:
            recorded = _parse_iso_datetime(sh.get("recorded_at")) or datetime.utcnow()
            until = (recorded + timedelta(days=forward_days)).isoformat()
            sig = con.execute("""
                SELECT logged_at, result_at, direction, strategy_key, conviction, result, pnl_pct, source
                FROM signals
                WHERE symbol=?
                  AND logged_at >= ?
                  AND logged_at <= ?
                  AND result IN ('WIN','LOSS','PARTIAL')
                  AND pnl_pct IS NOT NULL
                ORDER BY logged_at ASC
                LIMIT 1
            """, (sh.get("symbol"), sh.get("recorded_at"), until)).fetchone()
            item = dict(sh)
            item["next_signal"] = dict(sig) if sig else None
            rows.append(item)
        con.close()
    except Exception as e:
        print(f"[evaluate_explosive_shadow] {e}", file=sys.stderr)

    clusters: dict[str, dict] = {}
    for row in rows:
        key = row.get("clue_label") or "unknown"
        bucket = clusters.setdefault(key, {
            "cluster": key,
            "count": 0,
            "symbols": [],
            "shadow_scores": [],
            "move_abs": [],
            "caught": 0,
            "blocked": 0,
            "missed": 0,
            "next_signal_count": 0,
            "next_signal_pnls": [],
            "next_signal_wins": 0,
            "pending": 0,
        })
        bucket["count"] += 1
        if row.get("symbol") and row.get("symbol") not in bucket["symbols"]:
            bucket["symbols"].append(row.get("symbol"))
        bucket["shadow_scores"].append(_report_float(row.get("shadow_score")))
        bucket["move_abs"].append(abs(_report_float(row.get("change_24h_pct"))))
        if row.get("had_signal"):
            bucket["caught"] += 1
        elif row.get("was_blocked"):
            bucket["blocked"] += 1
        else:
            bucket["missed"] += 1
        sig = row.get("next_signal")
        if sig:
            pnl = _report_float(sig.get("pnl_pct"))
            bucket["next_signal_count"] += 1
            bucket["next_signal_pnls"].append(pnl)
            if str(sig.get("result") or "").upper() in ("WIN", "PARTIAL"):
                bucket["next_signal_wins"] += 1
        else:
            bucket["pending"] += 1

    evaluated = []
    for bucket in clusters.values():
        n = bucket["count"]
        if n < min_count:
            continue
        signal_n = bucket["next_signal_count"]
        pnls = bucket["next_signal_pnls"]
        avg_pnl = round(sum(pnls) / len(pnls), 2) if pnls else None
        win_rate = round(bucket["next_signal_wins"] / signal_n, 4) if signal_n else None
        caught_rate = round(bucket["caught"] / n, 4) if n else 0
        blocked_rate = round(bucket["blocked"] / n, 4) if n else 0
        missed_rate = round(bucket["missed"] / n, 4) if n else 0
        if signal_n < 3:
            verdict = "collect_data"
        elif avg_pnl is not None and avg_pnl > 5 and win_rate is not None and win_rate >= 0.5:
            verdict = "promising"
        elif avg_pnl is not None and avg_pnl < -5:
            verdict = "avoid"
        else:
            verdict = "mixed"
        evaluated.append({
            "cluster": bucket["cluster"],
            "count": n,
            "symbols": bucket["symbols"][:8],
            "avg_shadow_score": round(sum(bucket["shadow_scores"]) / len(bucket["shadow_scores"]), 2) if bucket["shadow_scores"] else 0,
            "avg_abs_move_pct": round(sum(bucket["move_abs"]) / len(bucket["move_abs"]), 2) if bucket["move_abs"] else 0,
            "caught_rate": caught_rate,
            "blocked_rate": blocked_rate,
            "missed_rate": missed_rate,
            "next_signal_count": signal_n,
            "pending_count": bucket["pending"],
            "avg_next_signal_pnl": avg_pnl,
            "next_signal_win_partial_rate": win_rate,
            "verdict": verdict,
        })
    evaluated.sort(key=lambda x: (
        x["verdict"] == "promising",
        x["next_signal_count"],
        x["avg_next_signal_pnl"] if x["avg_next_signal_pnl"] is not None else -999,
        x["avg_shadow_score"],
    ), reverse=True)
    return {
        "generated_at": datetime.utcnow().isoformat(),
        "days_back": days_back,
        "forward_days": forward_days,
        "min_count": min_count,
        "shadow_rows": len(rows),
        "clusters": evaluated,
        "summary": {
            "clusters": len(evaluated),
            "promising": sum(1 for c in evaluated if c["verdict"] == "promising"),
            "avoid": sum(1 for c in evaluated if c["verdict"] == "avoid"),
            "collect_data": sum(1 for c in evaluated if c["verdict"] == "collect_data"),
        },
        "rules": [
            "Evaluation is read-only and does not affect live scoring.",
            "Clusters need repeated examples before promotion to a shadow strategy.",
            "Next-signal P&L means the next resolved MT7 signal on the same symbol inside the forward window.",
        ],
    }


def _shadow_row_clues(row: dict) -> list[str]:
    try:
        raw = row.get("context_json") or "{}"
        ctx = json.loads(raw) if isinstance(raw, str) else (raw or {})
        clues = ctx.get("clues") or []
        if isinstance(clues, list):
            return [str(c) for c in clues if c]
    except Exception:
        pass
    label = row.get("clue_label") or ""
    return [p.strip() for p in label.split(",") if p.strip()]


def _research_radar_templates_for_row(row: dict) -> list[str]:
    clues = set(_shadow_row_clues(row))
    score = _report_float(row.get("shadow_score"))
    move = _report_float(row.get("change_24h_pct"))
    funding = _report_float(row.get("funding_rate"))
    volume = _report_float(row.get("volume_24h"))
    wick = _report_float(row.get("wick_pressure"), None)
    volume_expansion = _report_float(row.get("volume_expansion"), None)
    templates: list[str] = []

    has_alignment = "pre_move_drift" in clues and ("six_hour_alignment" in clues or "fresh_impulse" in clues)
    has_expansion = "volume_expansion" in clues or "range_expansion" in clues
    if score >= 62 and has_alignment and has_expansion and volume >= 1_000_000:
        templates.append("explosive_continuation_watch")

    if move > 8 and ("crowded_funding" in clues or funding <= -0.001) and (wick is None or wick <= 0.55):
        templates.append("squeeze_continuation_research")

    if move > 10 and ("late_wick_risk" in clues or (wick is not None and wick > 0.45)):
        templates.append("post_spike_exhaustion_short_watch")

    if move < -8 and ("crowded_funding" in clues or funding >= 0.001) and has_expansion:
        templates.append("flush_continuation_research")

    if volume_expansion is not None and volume_expansion >= 3 and score >= 55:
        templates.append("volume_shock_scanner_gap")

    return templates


