def _report_cross_desk_synthesis(data: dict) -> dict:
    pulse = data.get("market_pulse") or {}
    coverage = data.get("specialty_coverage") or {}
    specialist = data.get("specialist_evidence") or {}
    cross_venue = specialist.get("cross_venue") or {}
    catalysts = specialist.get("catalysts") or {}
    tokenomics = specialist.get("tokenomics") or {}
    social = specialist.get("social") or {}
    neg, pos = _report_count_funding_extremes(data)
    disagreements = data.get("disagreements") or []
    return {
        "consensus": [
            f"Current measured regime: {str(pulse.get('dominant_regime') or 'unknown').replace('_', ' ')}.",
            f"Funding crowding is active in {neg + pos} extreme buckets.",
            "Only fresh MT7 signals—not report observations—can become trade candidates.",
        ],
        "tensions": [
            f"{len(disagreements)} signals show material narrative/structural disagreement.",
            (
                f"{len(catalysts.get('events_in_window') or [])} primary-source events are cached in-window, "
                "but an event timestamp alone does not prove it caused price leadership."
                if catalysts.get("available") else
                "Price leadership may be real while its catalyst, sentiment, or supply explanation remains unverified."
            ),
            (
                f"{len(tokenomics.get('focus_unlocks') or [])} focus-asset unlock schedules "
                "and treasury observations are third-party aggregated, not issuer-confirmed."
                if tokenomics.get("available") else
                "No cached supply/unlock/treasury evidence covers this report window."
            ),
            (
                f"Direct activity is sampled across {len(social.get('topic_snapshots') or [])} "
                f"topics, but source diversity is {social.get('source_family_count', 0)} platform."
                if social.get("available") else
                "Funding crowding is not a substitute for direct social activity."
            ),
        ],
        "blind_spots": [
            "No direct holder-concentration, labeled wallet-transfer, or exchange-flow feed in the Cipher report.",
            (
                "Direct social coverage is Bluesky-only; MT7 measures activity quality but does not infer directional sentiment or author truthfulness."
                if social.get("available") else
                "No cached direct social-activity feed exists in this report window."
            ),
            (
                "Primary catalyst coverage is bounded to reviewed exchange, protocol/governance, U.S. regulator, and Federal Reserve sources."
                if catalysts.get("available") else
                "No cached primary-source catalyst batch exists in this report window."
            ),
            (
                "Cross-venue tickers are cached together, but synchronized depth is not collected across all venues."
                if cross_venue.get("available")
                else "No synchronized cross-venue ticker batch exists in this report window."
            ),
        ],
        "coverage": coverage,
    }


def _report_desk_debate(data: dict) -> dict:
    """Opposing measured cases with an explicit resolution and no trade authority."""
    pulse = data.get("market_pulse") or {}
    breadth = data.get("market_breadth") or {}
    paper = data.get("paper_desk") or {}
    specialist = data.get("specialist_evidence") or {}
    cross = specialist.get("cross_venue") or {}
    catalysts = specialist.get("catalysts") or {}
    tokenomics = specialist.get("tokenomics") or {}
    advancers = int(breadth.get("advancers") or 0)
    decliners = int(breadth.get("decliners") or 0)
    total = int(breadth.get("total") or 0)
    neg, pos = _report_count_funding_extremes(data)
    disagreements = len(data.get("disagreements") or [])
    upside = []
    downside = []

    if total:
        if advancers > decliners:
            upside.append(
                f"Breadth favors upside: {advancers} advancers versus {decliners} decliners."
            )
        elif decliners > advancers:
            downside.append(
                f"Breadth favors downside: {decliners} decliners versus {advancers} advancers."
            )
        else:
            upside.append(f"Breadth is balanced at {advancers}/{decliners}; no directional edge.")
            downside.append(f"Breadth is balanced at {advancers}/{decliners}; no directional edge.")
    if neg:
        upside.append(
            f"{neg} extreme-negative funding names create conditional short-squeeze fuel."
        )
    if pos:
        downside.append(
            f"{pos} extreme-positive funding names create conditional long-unwind risk."
        )
    paper_ev = paper.get("avg_pnl_pct")
    if paper_ev is not None:
        target = upside if _report_float(paper_ev) > 0 else downside
        target.append(
            f"Recent Paper expectancy is {_report_float(paper_ev):+.2f}% across "
            f"{int(paper.get('closed') or 0)} closed trades."
        )
    if cross.get("available"):
        aligned = sum(
            1 for row in (cross.get("price_dislocations") or [])
            if row.get("direction_aligned") is True
        )
        if aligned:
            upside.append(
                f"{aligned} cached cross-venue dislocations show aligned direction; current books still require recheck."
            )
        else:
            downside.append("Cached venue evidence does not show a clearly aligned leadership set.")
    else:
        downside.append("Cross-venue confirmation is unavailable in this report window.")
    if disagreements:
        downside.append(f"{disagreements} material desk disagreements reduce directional confidence.")
    if not catalysts.get("available"):
        downside.append("No time-matched primary-source catalyst explains the current leadership.")
    if not tokenomics.get("available"):
        downside.append("Supply and unlock coverage is unavailable for the focus assets.")

    directional_up = int(advancers > decliners) + int(neg > pos)
    directional_down = int(decliners > advancers) + int(pos > neg) + int(disagreements > 0)
    if not total or str(pulse.get("dominant_regime") or "unknown") == "unknown":
        resolution = "Evidence is incomplete; the desk abstains from a directional resolution."
        lean = "abstain"
        confidence = "low"
    elif abs(directional_up - directional_down) < 2:
        resolution = (
            "The measured cases remain mixed. Review only fresh MT7 signals with independent "
            "structure, flow, and risk confirmation."
        )
        lean = "mixed"
        confidence = "low"
    elif directional_up > directional_down:
        resolution = (
            "The balance of evidence conditionally favors upside follow-through, but only a fresh "
            "MT7 signal with aligned structure and flow can become a candidate."
        )
        lean = "conditional_upside"
        confidence = "medium"
    else:
        resolution = (
            "The balance of evidence conditionally favors defensive/downside posture; avoid treating "
            "crowded funding or a large move as a standalone short."
        )
        lean = "conditional_downside"
        confidence = "medium"
    return {
        "upside_case": upside[:6],
        "downside_case": downside[:6],
        "resolution": resolution,
        "lean": lean,
        "confidence": confidence,
        "confirmation": (
            "Consecutive fresh scans retain the regime while breadth and cross-venue direction agree."
        ),
        "invalidation": (
            "Breadth leadership reverses, the regime changes, or fresh flow disagrees with the resolved lean."
        ),
        "authority": "advisory_only",
    }


def _report_agent_spotlight(data: dict) -> dict:
    key = str(data.get("spotlight_key") or "funding")
    briefs = data.get("analyst_briefs") or {}
    brief = briefs.get(key) or {}
    try:
        from lib.agents import AGENT_ROSTER
        persona = AGENT_ROSTER.get(key) or {}
    except Exception:
        persona = {}
    return {
        "agent_key": key,
        "name": persona.get("name") or key.replace("_", " ").title(),
        "title": persona.get("title") or "Cipher analyst",
        "specialty": persona.get("specialty") or "",
        "selection_reason": "The spotlight rotates weekly to audit each specialty and prevent one desk from dominating the firm's interpretation.",
        "current_contribution": brief.get("read") or "No specialty brief available.",
        "evidence": brief.get("evidence") or [],
        "trader_use": brief.get("trader_use") or "",
        "invalidation": brief.get("invalidation") or "",
        "confidence": brief.get("confidence") or "low",
        "coverage": brief.get("coverage") or "unknown",
        "limits": brief.get("limits") or [],
    }


def _enrich_report_intelligence(data: dict, weekly: bool = False) -> dict:
    data["specialty_coverage"] = _report_research_coverage()
    data["analyst_focus"] = _report_role_focus(data)
    data["horizon_outlook"] = _report_horizon_outlook(data)
    data["scenario_matrix"] = _report_scenario_matrix(data)
    data["cross_desk_synthesis"] = _report_cross_desk_synthesis(data)
    data["desk_debate"] = _report_desk_debate(data)
    data["analyst_briefs"] = _report_analyst_briefs(data, weekly=weekly)
    data["desk_verdict"] = _report_desk_verdict(data, weekly=weekly)
    if weekly:
        data["agent_spotlight"] = _report_agent_spotlight(data)
    return data


def _build_report_action_matrix(data: dict) -> dict:
    """Convert report observations into trader-facing actions without inventing entries."""
    pulse = data.get("market_pulse") or {}
    paper = data.get("paper_desk") or {}
    explosive = data.get("explosive_move") or {}
    explosive_ctx = data.get("explosive_signal_context") or {}
    coiling = data.get("whats_coiling") or []
    disagreements = data.get("disagreements") or []
    blocked = data.get("blocked") or []
    strategy_perf = data.get("strategy_regime_perf") or []
    tokenomics = (data.get("specialist_evidence") or {}).get("tokenomics") or {}
    neg_funding, pos_funding = _report_count_funding_extremes(data)

    actions: list[dict] = []
    watchlist: list[dict] = []
    avoid: list[dict] = []
    investigations: list[dict] = []

    posture = "selective"
    if not int(pulse.get("signals") or 0):
        posture = "wait"
    if int(pulse.get("blocked") or 0) or disagreements:
        posture = "defensive"
    if explosive and not explosive_ctx.get("had_signal") and not explosive_ctx.get("was_blocked"):
        posture = "investigate"

    if explosive:
        sym = explosive.get("symbol")
        move = _report_float(explosive.get("change_24h_pct"))
        fr = _report_float(explosive.get("funding_rate"))
        if explosive_ctx.get("had_signal"):
            actions.append({
                "label": "Review MT7 Signal",
                "symbol": sym,
                "priority": "high",
                "reason": (
                    f"Explosive mover was on the signal list as {explosive_ctx.get('signal_direction')} "
                    f"at conviction {explosive_ctx.get('signal_conviction')}."
                ),
                "next_step": "Open the signal/trade detail and compare entry timing, funding, volume, and stop distance before considering any manual action.",
            })
        elif explosive_ctx.get("was_blocked"):
            avoid.append({
                "label": "Respect Risk Gate",
                "symbol": sym,
                "reason": f"Explosive mover was blocked by {explosive_ctx.get('block_gate')}.",
                "next_step": "Do not override the gate from the report. Review only after the gate condition clears on a fresh scan.",
            })
        else:
            investigations.append({
                "label": "Missed Mover Review",
                "symbol": sym,
                "reason": f"{sym} moved {move:+.2f}% with funding {fr:.5f} but had no MT7 signal or block record.",
                "next_step": "Check whether the move lacked structure at scan time, happened between scans, or exposed a missing feature.",
            })

    for item in coiling[:4]:
        sym = item.get("symbol")
        watch = item.get("watch") or "funding unwind"
        rate = _report_float(item.get("funding_rate"))
        watchlist.append({
            "label": watch,
            "symbol": sym,
            "reason": f"Funding is extreme at {rate:.5f} while price has not fully resolved.",
            "next_step": "Wait for a fresh MT7 signal or visible volume expansion; do not trade the funding read alone.",
        })

    if neg_funding or pos_funding:
        actions.append({
            "label": "Funding Crowding Scan",
            "symbol": "market",
            "priority": "medium",
            "reason": f"{neg_funding} extreme negative and {pos_funding} extreme positive funding buckets are active.",
            "next_step": "Favor setups where funding crowding aligns with price structure and order-flow confirmation.",
        })

    weak_perf = []
    for r in strategy_perf:
        good = int(r.get("win") or 0) + int(r.get("partial") or 0)
        total = good + int(r.get("loss") or 0)
        if total >= 5 and good / total < 0.45:
            weak_perf.append({
                "strategy": r.get("strategy"),
                "regime": r.get("regime"),
                "good": good,
                "total": total,
            })
    for r in weak_perf[:3]:
        avoid.append({
            "label": "Weak Strategy/Regime Bucket",
            "symbol": str(r.get("strategy") or "strategy"),
            "reason": f"{r.get('strategy')} in {r.get('regime')} is {r.get('good')}/{r.get('total')} W+P in the recent report window.",
            "next_step": "Treat matching signals as review-only unless the current setup has stronger independent confirmation.",
        })

    token_risk_rows = [
        row for row in (tokenomics.get("focus_assets") or [])
        if row.get("risk_level") in {"high", "watch"}
    ]
    token_unlock_rows = [
        row for row in (tokenomics.get("focus_unlocks") or [])
        if row.get("risk_level") in {"high", "watch"}
    ]
    if token_risk_rows:
        row = token_risk_rows[0]
        avoid.append({
            "label": "Float / Valuation Supply Risk",
            "symbol": row.get("symbol"),
            "reason": (
                f"Reported float is {float(row.get('float_pct') or 0):.1f}% and "
                f"FDV/market cap is {float(row.get('fdv_market_cap_ratio') or 0):.2f}×."
            ),
            "next_step": (
                "Require stronger independent confirmation and explicitly disclose any "
                "risk reduction. This evidence cannot justify more leverage or a larger position."
            ),
        })
    if token_unlock_rows:
        row = token_unlock_rows[0]
        avoid.append({
            "label": "Near-Term Unlock Risk",
            "symbol": row.get("symbol") or row.get("project_name"),
            "reason": (
                f"Aggregated schedule shows a {float(row.get('unlock_pct_float') or 0):.2f}% "
                f"of-float cliff at {row.get('unlock_at')}."
            ),
            "next_step": (
                "Verify the issuer schedule and define the event-risk window; keep the "
                "setup review-only if the schedule cannot be confirmed."
            ),
        })

    closed = int(paper.get("closed") or 0)
    avg_pnl = _report_float(paper.get("avg_pnl_pct"))
    if closed:
        investigations.append({
            "label": "Paper Cohort Check",
            "symbol": "paper",
            "reason": f"Recent paper desk has {closed} closed trades at {avg_pnl:+.2f}% average P&L.",
            "next_step": "Use the Paper tab cohort gates, not this daily report alone, to decide promotion.",
        })

    return {
        "posture": posture,
        "actions": actions[:5],
        "watchlist": watchlist[:6],
        "avoid": avoid[:5],
        "investigations": investigations[:5],
        "rules": [
            "Reports are advisory; only fresh MT7 signals can become trade candidates.",
            "No report note may create a trade if the signal engine did not produce one.",
            "Use paper cohort gates for promotion decisions.",
        ],
    }


def _sanitize_report_narrative(narrative: dict, data: dict) -> dict:
    """Strip action-inventing language from AI-polished report notes."""
    clean = dict(narrative or {})
    explosive = data.get("explosive_move") or {}
    explosive_ctx = data.get("explosive_signal_context") or {}
    no_signal = bool(explosive) and not explosive_ctx.get("had_signal")
    banned = [
        "i'm opening", "i am opening", "open a long", "open a short",
        "i'd open", "i would open", "enter long", "enter short",
        "go long", "go short", "shorting ", "longing ",
    ]
    for key, value in list(clean.items()):
        if not isinstance(value, str):
            continue
        low = value.lower()
        if any(term in low for term in banned):
            if no_signal:
                sym = explosive.get("symbol") or "the explosive mover"
                clean[key] = (
                    f"{sym} moved sharply, but MT7 did not produce a trade signal for it in this report window. "
                    "Treat it as a missed-mover review, not an entry. Wait for a fresh signal, risk-gate context, and order-flow confirmation."
                )
            else:
                clean[key] = re.sub(
                    r"\b(?:I[' ]?m|I am|I'd|I would)?\s*(?:opening|open|enter|go)\s+(?:a\s+)?(?:long|short)\b",
                    "reviewing the setup",
                    value,
                    flags=re.IGNORECASE,
                )
    return clean


def _build_weekly_report_narrative(data: dict) -> dict:
    """Weekly synthesis contract: progression, persistence, attribution, and next-week tests."""
    narrative = _report_empty_narrative()
    pulse = data.get("market_pulse") or {}
    weekly = data.get("weekly_summary") or {}
    days = data.get("daily_rollup") or []
    paper = data.get("paper_desk") or {}
    specialist = data.get("specialist_evidence") or {}
    history = specialist.get("market_history") or {}
    context = specialist.get("market_context") or {}
    flow = specialist.get("order_flow") or {}
    cross = specialist.get("cross_venue") or {}
    catalysts = specialist.get("catalysts") or {}
    tokenomics = specialist.get("tokenomics") or {}
    social = specialist.get("social") or {}
    focus = data.get("analyst_focus") or {}
    briefs = data.get("analyst_briefs") or {}
    regime = str(weekly.get("dominant_regime") or pulse.get("dominant_regime") or "unknown").replace("_", " ")
    signals = int(weekly.get("signals") or 0)
    blocked = int(weekly.get("blocked") or 0)
    active_days = int(weekly.get("active_signal_days") or sum(
        1 for day in days if int((day.get("market_pulse") or {}).get("signals") or 0)
    ))
    first_pulse = (days[0].get("market_pulse") if days else {}) or {}
    last_pulse = (days[-1].get("market_pulse") if days else {}) or {}
    neg, pos = _report_count_funding_extremes(data)
    regime_counts = weekly.get("regime_counts") or {}
    regime_mix = ", ".join(
        f"{str(label).replace('_', ' ')} {count}"
        for label, count in sorted(regime_counts.items(), key=lambda item: item[1], reverse=True)[:4]
    ) or "no classified observations"
    regime_lead_clause = (
        f"{regime} led the aggregate"
        if regime != "unknown" else
        "no regime earned a dominant weekly label"
    )
    breadth_path = history.get("breadth_path") or []
    breadth_first = breadth_path[0] if breadth_path else {}
    breadth_last = breadth_path[-1] if breadth_path else {}
    paper_closed = int(paper.get("closed") or 0)
    paper_note = (
        f"The retained paper cohort closed {paper_closed} trades at "
        f"{float(paper.get('win_rate_pct') or 0):.1f}% W+P and "
        f"{float(paper.get('avg_pnl_pct') or 0):+.2f}% average P&L, with "
        f"${float(paper.get('max_drawdown_usd') or 0):.2f} measured maximum drawdown."
        if paper_closed else
        "No closed paper cohort is available for this report window, so execution quality cannot support a weekly conclusion."
    )
    narrative["trader_open"] = (
        f"This week produced {signals} recorded signals across {active_days}/7 calendar days and "
        f"{blocked} pre-desk rejections. The classified mix was {regime_mix}; {regime_lead_clause}, "
        f"while {int(weekly.get('mixed_desk_days') or 0)} sessions ended with mixed desk agreement. "
        f"Daily signal count moved from {int(first_pulse.get('signals') or 0)} at the start of the window "
        f"to {int(last_pulse.get('signals') or 0)} at the latest checkpoint. {paper_note} "
        "My next-week posture is conditional: retain only strategy/regime combinations with measured net evidence, "
        "and reclassify before acting if the weekly leader is not also present on fresh scans."
    )
    if regime == "unknown":
        regime_read = (
            "The weekly regime remains unclassified because the recorded signals did not produce a stable dominant label. "
            "That is an abstention, not a neutral-market call."
        )
    else:
        regime_read = (
            f"{regime.title()} accumulated the most classified observations, but leadership is durable only if it "
            "persists across multiple daily checkpoints rather than being concentrated in one scan."
        )
    weekly_btc_note = (
        f"BTC changed {float(context.get('btc_window_return_pct') or 0):+.2f}% through "
        f"{int(context.get('observations') or 0)} checkpoints and registered "
        f"{int(context.get('btc_trend_flips') or 0)} trend flips."
        if int(context.get("observations") or 0) >= 2 else
        f"BTC persistence is unmeasured because only {int(context.get('observations') or 0)} context checkpoint is retained."
    )
    narrative["regime_forecast"] = (
        f"{regime_read} {weekly_btc_note} "
        f"Measured breadth moved from {int(breadth_first.get('advancers') or 0)}/"
        f"{int(breadth_first.get('decliners') or 0)} to {int(breadth_last.get('advancers') or 0)}/"
        f"{int(breadth_last.get('decliners') or 0)} advancers/decliners. "
        "Continuation requires the same regime, breadth direction, and positive strategy evidence on at least two fresh sessions; "
        "a different daily leader or renewed breadth reversal is the transition trigger."
    )
    narrative["risk_close"] = (
        f"Weekly gating rejected {blocked} candidates, and mixed desk agreement appeared on "
        f"{int(weekly.get('mixed_desk_days') or 0)} days. {paper_note} "
        "For next week, a quieter gate or a profitable short sample does not justify greater exposure. "
        "Any suggestion to raise position size or leverage must state current and proposed exposure, liquidation distance, "
        "fee/slippage impact, and drawdown effect, then wait for explicit approval. "
        "If those quantities are missing, the correct risk action is to abstain."
    )

    funding_item = (focus.get("funding") or {}).get("item") or {}
    if funding_item:
        symbol = _report_symbol(funding_item)
        rate = _report_funding(funding_item)
        move = _report_percent_change(funding_item)
        narrative["funding_autopsy"] = (
            f"My weekly funding focus is {symbol}, selected for the largest unresolved absolute carry imbalance: "
            f"{rate:.5f} with a {move:+.2f}% 24-hour move at the latest snapshot. "
            f"Across the current board, {neg} contracts sit in extreme negative funding and {pos} in extreme positive funding. "
            "The test for next week is normalization versus price follow-through: if absolute funding falls while structure holds, "
            "crowding is unwinding without directional confirmation; if price breaks against the paying side with expanding flow, "
            "the unwind thesis strengthens. Carry alone remains insufficient for entry."
        )
    else:
        narrative["funding_autopsy"] = (
            "No contract met the report's measured funding-focus requirements this week. "
            "Without a non-zero, attributable funding imbalance, I cannot produce a crowding or normalization claim. "
            "The funding desk therefore abstains until the background snapshots retain a qualifying contract."
        )

    flow_item = (focus.get("microstructure") or {}).get("item") or {}
    if flow_item:
        narrative["microstructure_autopsy"] = (
            f"The strongest retained microstructure packet belongs to {flow_item.get('symbol')}: "
            f"{int(flow_item.get('trade_count') or 0)} trades, "
            f"{float(flow_item.get('flow_delta_pct') or 0):+.1f}% aggressive-flow delta, "
            f"{float(flow_item.get('average_imbalance') or 0):+.3f} average book imbalance, and "
            f"{float(flow_item.get('average_spread_bps') or 0):.2f} bps average spread. "
            f"Coverage reached {int(flow.get('symbol_count') or 0)} focus symbols, so this is a bounded MEXC execution read, "
            "not a market-wide weekly order-flow history. Retests are credible only while flow, depth, and spread remain aligned."
        )
    else:
        narrative["microstructure_autopsy"] = (
            "The weekly focus set has no retained MEXC tape/depth packet strong enough for an execution-quality conclusion. "
            "Ticker volume cannot fill that gap. Niobe abstains from calling continuation or absorption until a fresh focus symbol "
            "has trade delta, order-book imbalance, and spread evidence."
        )

    cross_item = (focus.get("cross_venue") or {}).get("item") or {}
    if cross_item:
        narrative["cross_venue_autopsy"] = (
            f"The widest identity-safe cached venue dislocation is {cross_item.get('symbol')} at "
            f"{float(cross_item.get('adjusted_price_gap_bps') or 0):.1f} adjusted bps, with "
            f"{cross_item.get('premium_venue') or 'an unavailable venue'} rich to "
            f"{cross_item.get('discount_venue') or 'an unavailable venue'}. "
            f"The latest synchronized batch matched {int(cross.get('matched_three_venue') or 0)} assets across all three venues "
            f"and quarantined {len(cross.get('symbol_mismatches') or [])} identity conflicts. "
            "Next week's confirmation test is persistence after fees, quote normalization, and live-depth checks; "
            "the report neither assumes executability nor recommends an arbitrage."
        )
    else:
        narrative["cross_venue_autopsy"] = (
            "No identity-safe synchronized multi-venue row survived the weekly evidence gates. "
            "Ghost abstains from venue leadership and dispersion claims until a fresh cached batch has matching contracts, "
            "usable liquidity, and a non-stale timestamp."
        )

    news_brief = briefs.get("news") or {}
    token_brief = briefs.get("tokenomics") or {}
    social_brief = briefs.get("sentiment") or {}
    narrative["catalyst_watch"] = (
        f"Weekly catalyst review: {news_brief.get('read') or 'No time-matched primary-source event was retained.'} "
        f"The window contains {len(catalysts.get('events_in_window') or [])} in-window, "
        f"{len(catalysts.get('upcoming_events') or [])} upcoming, and "
        f"{len(catalysts.get('active_incidents') or [])} active official-source items. "
        "For the coming week, separate publication time from effective time and judge direction only from the measured reaction."
    )
    narrative["tokenomics_watch"] = (
        f"Weekly supply-risk review: {token_brief.get('read') or 'No mapped supply, unlock, or treasury evidence covers the focus set.'} "
        f"The cache contains {len(tokenomics.get('focus_unlocks') or [])} relevant unlock schedules and "
        f"{len(tokenomics.get('focus_treasuries') or [])} mapped treasury observations. "
        "These are slow-horizon risk qualifiers: verify issuer schedules and mapping freshness before changing admission, "
        "and never use a low-float or treasury observation to increase leverage or size."
    )
    narrative["social_watch"] = (
        f"Weekly attention review: {social_brief.get('read') or 'No direct social sample was retained.'} "
        f"The report covers {len(social.get('topic_snapshots') or [])} sampled topics from "
        f"{int(social.get('source_family_count') or 0)} direct platform family. "
        "Next week's useful test is persistence with diverse authors and low duplication alongside price/volume confirmation; "
        "a one-platform burst is a verification priority, not sentiment truth."
    )

    upcoming = catalysts.get("upcoming_events") or []
    upcoming_note = (
        f"The nearest cached scheduled item is “{upcoming[0].get('title')}” at {upcoming[0].get('event_at')}."
        if upcoming else
        "No scheduled official item is cached; source health must be checked before treating the calendar as clear."
    )
    tactical_test = (
        f"Tactical: confirm that {regime} remains the regime leader on consecutive sessions rather than inheriting this week's aggregate."
        if regime != "unknown" else
        "Tactical: withhold regime-specific preference until one classified regime leads on consecutive sessions."
    )
    narrative["week_ahead"] = (
        f"Next week's operating test has three layers. Immediate: require a fresh classified MT7 signal and current execution data. "
        f"{tactical_test} "
        "Structural: keep strategy promotion tied to forward net outcomes across regime rotations, not report confidence. "
        f"{upcoming_note} Funding crowding is {neg} negative versus {pos} positive extreme buckets at the handoff snapshot. "
        "If evidence families disagree, preserve capital and investigate the missing link."
    )
    spotlight = data.get("agent_spotlight") or _report_agent_spotlight(data)
    narrative["spotlight"] = (
        f"{spotlight.get('name') or 'The selected analyst'} is highlighted because the rotation requires an auditable specialty review. "
        f"Current contribution: {spotlight.get('current_contribution') or 'no qualified contribution'}. "
        f"Evidence quality is {spotlight.get('coverage') or 'unknown'} at {spotlight.get('confidence') or 'low'} confidence. "
        f"Trader use: {spotlight.get('trader_use') or 'keep the observation advisory'}. "
        f"The contribution fails if {spotlight.get('invalidation') or 'new measured evidence contradicts it'}."
    )
    return narrative


def _build_deterministic_report_narrative(data: dict, weekly: bool = False) -> dict:
    """
    No-cost Cipher desk notes built directly from report data.

    This is the baseline narrative layer. Paid/free hosted LLMs can polish it,
    but reports should never go blank because a provider key is missing or a
    free-tier quota is exhausted.

    All notes are written in first-person analyst voice. No 3rd-person framing.
    Every note ends with a forward call — what to watch or do next.
    """
    if weekly:
        return _build_weekly_report_narrative(data)
    narrative = _report_empty_narrative()
    pulse = data.get("market_pulse") or {}
    paper = data.get("paper_desk") or {}
    top_gainers = data.get("top_gainers") or []
    top_losers = data.get("top_losers") or []
    coiling = data.get("whats_coiling") or []
    disagreements = data.get("disagreements") or []
    explosive = data.get("explosive_move") or {}
    explosive_ctx = data.get("explosive_signal_context") or {}
    coiling_rates = data.get("coiling_base_rates") or {}
    strategy_perf = data.get("strategy_regime_perf") or []
    specialist = data.get("specialist_evidence") or {}
    market_history = specialist.get("market_history") or {}
    market_context = specialist.get("market_context") or {}
    order_flow = specialist.get("order_flow") or {}
    cross_venue = specialist.get("cross_venue") or {}
    catalysts = specialist.get("catalysts") or {}
    tokenomics = specialist.get("tokenomics") or {}
    social = specialist.get("social") or {}
    role_focus = data.get("analyst_focus") or _report_role_focus(data)
    breadth_path = market_history.get("breadth_path") or []
    breadth_first = breadth_path[0] if breadth_path else {}
    breadth_last = breadth_path[-1] if breadth_path else {}
    price_rotations = market_history.get("price_rotations") or []
    oi_rotations = market_history.get("oi_rotations") or []
    lead_rotation = price_rotations[0] if price_rotations else {}
    lead_oi = oi_rotations[0] if oi_rotations else {}
    flow_rows = order_flow.get("symbols") or []
    lead_flow = (role_focus.get("microstructure") or {}).get("item") or (
        flow_rows[0] if flow_rows else {}
    )
    funding_subject = (role_focus.get("funding") or {}).get("item") or explosive
    neg_funding, pos_funding = _report_count_funding_extremes(data)

    top_gain = top_gainers[0] if top_gainers else None
    top_loss = top_losers[0] if top_losers else None
    xsym = _report_fmt_symbol(explosive)
    xmove = _report_fmt_move(explosive)
    signals = int(pulse.get("signals") or 0)
    blocked = int(pulse.get("blocked") or 0)
    regime = str(pulse.get("dominant_regime") or "unknown").replace("_", " ")

    # --- Thomas: trader_open — signal count, regime, best strategy, funding crowding ---
    best_strat_note = ""
    if strategy_perf:
        regime_key = str(pulse.get("dominant_regime") or "")
        regime_rows = [r for r in strategy_perf if r.get("regime", "") == regime_key]
        if not regime_rows:
            regime_rows = strategy_perf
        def _win_rate(r: dict) -> float:
            w = int(r.get("win", 0)) + int(r.get("partial", 0))
            total = w + int(r.get("loss", 0))
            return w / total if total >= 3 else 0.0
        best = max(regime_rows, key=_win_rate, default=None)
        if best:
            bw = int(best.get("win", 0)) + int(best.get("partial", 0))
            btotal = bw + int(best.get("loss", 0))
            if btotal >= 3:
                best_strat_note = (
                    f" {best.get('strategy', 'unknown').replace('_', ' ').title()} "
                    f"is leading in this regime — {bw}/{btotal} closed trades on the right side."
                )

    funding_crowd = ""
    if neg_funding and pos_funding:
        funding_crowd = f" Funding pressure is split: {neg_funding} names carry negative rate (short squeeze risk), {pos_funding} carry positive (long flush risk)."
    elif neg_funding:
        funding_crowd = f" {neg_funding} names are running extreme negative funding — shorts are paying heavily to stay on."
    elif pos_funding:
        funding_crowd = f" {pos_funding} names are running extreme positive funding — longs are carrying a crowded bet."

    top_gain_str = _report_fmt_symbol(top_gain)
    top_loss_str = _report_fmt_symbol(top_loss)
    leadership_note = ""
    if top_gain and top_loss:
        leadership_note = (
            f" Measured strength was led by {top_gain_str} ({_report_fmt_move(top_gain)}), "
            f"while {top_loss_str} ({_report_fmt_move(top_loss)}) led weakness."
        )
    elif top_gain:
        leadership_note = f" Measured strength was led by {top_gain_str} ({_report_fmt_move(top_gain)})."
    elif top_loss:
        leadership_note = f" Measured weakness was led by {top_loss_str} ({_report_fmt_move(top_loss)})."
    else:
        leadership_note = " No complete mover snapshot was retained, so the desk abstains from naming leadership."
    history_note = ""
    if breadth_path:
        history_note = (
            f" Across {len(breadth_path)} measured market checkpoints, breadth moved from "
            f"{breadth_first.get('advancers', 0)}/{breadth_first.get('decliners', 0)} "
            f"to {breadth_last.get('advancers', 0)}/{breadth_last.get('decliners', 0)} advancers/decliners. "
            f"BTC returned {float(market_context.get('btc_window_return_pct') or 0):+.2f}% "
            f"with {int(market_context.get('btc_trend_flips') or 0)} recorded trend flips."
        )
    paper_note = ""
    if int(paper.get("closed") or 0):
        pf = paper.get("profit_factor")
        paper_note = (
            f" The recent paper cohort is {float(paper.get('win_rate_pct') or 0):.1f}% W+P at "
            f"{float(paper.get('avg_pnl_pct') or 0):+.2f}% expectancy"
            f"{f', profit factor {float(pf):.2f}' if pf is not None else ''}, with "
            f"${float(paper.get('max_drawdown_usd') or 0):.2f} measured drawdown."
        )
    regime_sentence = (
        f"The classified tape is {regime}."
        if regime != "unknown" else
        "The regime is unclassified because the current signal evidence does not support a stable label."
    )
    narrative["trader_open"] = (
        f"I logged {signals} signals today with {blocked} candidates blocked before they reached the desk. "
        f"{regime_sentence}{best_strat_note}{funding_crowd}{history_note}{paper_note}{leadership_note} "
        f"Base case: keep the current filters while breadth and BTC structure agree. "
        f"Rotation case: if breadth reverses and BTC trend flips again, pause regime-specific setups until MT7 reclassifies the tape."
    )

    # --- Nadia: regime_forecast — coiling setups + historical base rates ---
    if coiling:
        lead = coiling[0]
        lead_sym = lead.get("symbol", "")
        lead_fr = _report_float(lead.get("funding_rate"))
        lead_fr_ann = abs(lead_fr) * 3 * 365 * 100
        watch = lead.get("watch", "SHORT SQUEEZE")
        base_note = ""
        if lead_sym in coiling_rates:
            br = coiling_rates[lead_sym]
            n = br.get("n", 0)
            wr = br.get("win_rate")
            if wr is not None and n >= 5:
                base_note = f" History: {n} prior setups with this funding profile resolved in favor of {br.get('direction', watch)} {wr}% of the time."
            elif n < 5:
                base_note = f" We have fewer than 5 historical comps for this setup — treat it as unvalidated edge."
        if breadth_path:
            btc_context_note = (
                f"BTC moved {float(market_context.get('btc_window_return_pct') or 0):+.2f}% "
                f"across {int(market_context.get('observations') or 0)} context checkpoints"
                if int(market_context.get("observations") or 0) >= 2 else
                f"BTC persistence is unmeasured from only {int(market_context.get('observations') or 0)} context checkpoint"
            )
            context_note = (
                f" {btc_context_note}, while breadth finished at {breadth_last.get('advancers', 0)}/"
                f"{breadth_last.get('decliners', 0)} advancers/decliners."
            )
        elif int((data.get("market_breadth") or {}).get("total") or 0):
            current_breadth = data.get("market_breadth") or {}
            context_note = (
                f" Historical breadth checkpoints are unavailable; the current all-market snapshot is "
                f"{int(current_breadth.get('advancers') or 0)}/"
                f"{int(current_breadth.get('decliners') or 0)} advancers/decliners."
            )
        else:
            context_note = " No complete breadth history or current market breadth is available, so the macro confirmation leg is unresolved."
        narrative["regime_forecast"] = (
            f"I'm reading pressure build, not trend. {lead_sym} has barely moved ({_report_fmt_move(lead)}) "
            f"but funding is at {lead_fr:.5f} — that's {lead_fr_ann:.0f}% annualized carry. "
            f"Something has to give: either price breaks in the direction of the carry, or funding normalizes as positions unwind.{base_note} "
            f"{context_note} "
            f"Watch {lead_sym} for a volume surge that resolves the coil. Until then, any exposure reduction should be explicit; do not raise leverage or position size from this report."
        )
    else:
        if regime == "unknown":
            narrative["regime_forecast"] = (
                "I cannot classify the current regime from the retained signal mix, and no qualified coiling setup provides "
                "a transition marker. That is an abstention rather than a balanced-market forecast. "
                "Wait for a fresh scan with classified signals, stable breadth, and sufficient funding/structure evidence; "
                "do not increase leverage or position size while the regime remains unresolved."
            )
            regime_note = ""
        else:
            regime_note = f"The {regime} regime is the dominant read today."
        if regime != "unknown" and strategy_perf:
            regime_key = str(pulse.get("dominant_regime") or "")
            regime_rows = [r for r in strategy_perf if r.get("regime", "") == regime_key]
            if regime_rows:
                def _wr(r: dict) -> float:
                    w = int(r.get("win", 0)) + int(r.get("partial", 0))
                    t = w + int(r.get("loss", 0))
                    return w / t if t >= 3 else 0.0
                best = max(regime_rows, key=_wr, default=None)
                if best and _wr(best) > 0:
                    bw = int(best.get("win", 0)) + int(best.get("partial", 0))
                    bt = bw + int(best.get("loss", 0))
                    regime_note = (
                        f"In {regime} regimes, our {best.get('strategy', '').replace('_', ' ').title()} filter "
                        f"has {bw}/{bt} on the right side of closed trades."
                    )
        pressure_summary = ""
        if neg_funding or pos_funding:
            pressure_summary = f" Funding extremes are present ({neg_funding} negative, {pos_funding} positive) but no coiling setup meets the threshold today."
        if regime != "unknown":
            narrative["regime_forecast"] = (
                f"{regime_note}{pressure_summary} "
                f"No coiling setups on the board means the market isn't telegraphing a squeeze or flush. "
                f"My posture here is selective: require clean structure, elevated volume, and funded direction before taking any position."
            )

    # --- Harper: risk_close — gate names, blocked counts, forward posture ---
    blocked_gates: list[str] = []
    for b in (data.get("blocked") or [])[:20]:
        gk = b.get("gate_key") or ""
        if gk and gk not in blocked_gates:
            blocked_gates.append(gk)

    if blocked or disagreements:
        gate_detail = ""
        if blocked_gates:
            gate_detail = f" The active gates were: {', '.join(blocked_gates[:4])}."
        dis_note = ""
        if disagreements:
            dis_note = f" {len(disagreements)} signals came through with material analyst disagreement — those are lower-confidence entries."
        narrative["risk_close"] = (
            f"I blocked {blocked} candidates before they reached your list.{gate_detail}{dis_note} "
            f"The recent paper cohort shows ${float(paper.get('max_drawdown_usd') or 0):.2f} maximum drawdown, "
            f"{float(paper.get('avg_pnl_pct') or 0):+.2f}% expectancy, and "
            f"{float(paper.get('avg_fee_cost_pct') or 0) + float(paper.get('avg_slippage_cost_pct') or 0):.4f}% average execution drag. "
            f"Blocked candidates don't disappear; they reappear when conditions improve. "
            f"Watch the blocked list for symbols that clear gate criteria on the next scan. "
            f"No leverage or position-size increase is supported by a report alone; any such change must show the old and proposed exposure, liquidation distance, and drawdown impact for explicit user approval."
        )
    else:
        narrative["risk_close"] = (
            f"I blocked nothing today and saw no major disagreement across analysts. "
            f"The recent paper cohort is {float(paper.get('win_rate_pct') or 0):.1f}% W+P with "
            f"${float(paper.get('max_drawdown_usd') or 0):.2f} maximum drawdown and "
            f"{float(paper.get('avg_pnl_pct') or 0):+.2f}% expectancy. "
            f"A quiet gate is not evidence for more risk. Keep stops mechanical; any proposed leverage or size increase must state the capital and liquidation impact and require explicit approval."
        )

    # --- Kenny: funding_autopsy — alignment, annualized carry, signal cross-reference ---
    if funding_subject:
        exp_sym = _report_symbol(funding_subject)
        exp_change = _report_percent_change(funding_subject)
        exp_fr = _report_funding(funding_subject)
        exp_fr_ann = abs(exp_fr) * 3 * 365 * 100 if exp_fr else 0

        # Classify funding alignment
        if exp_change > 0 and exp_fr < -0.0003:
            alignment = "short squeeze"
            alignment_note = (
                f"Funding was deeply negative ({exp_fr:.5f}, {exp_fr_ann:.0f}% annualized) while price ripped {exp_change:.1f}%. "
                f"That's a classic squeeze — shorts got carried out. Late entries from here carry the wrong side of funding."
            )
        elif exp_change < 0 and exp_fr > 0.0003:
            alignment = "long flush"
            alignment_note = (
                f"Funding was elevated ({exp_fr:.5f}, {exp_fr_ann:.0f}% annualized) while price dropped {abs(exp_change):.1f}%. "
                f"That's a long flush — crowded longs unwinding. Catching this knife requires a funding reset first."
            )
        elif exp_fr and abs(exp_fr) > 0.0003 and exp_change * (1 if exp_fr > 0 else -1) > 0:
            alignment = "aligned carry"
            alignment_note = (
                f"Funding at {exp_fr:.5f} ({exp_fr_ann:.0f}% annualized) moved in the same direction as price. "
                f"That's not a squeeze — it's a carry trade. Momentum chasers are paying to be right. "
                f"Watch for the unwind when funding flips."
            )
        else:
            alignment = "neutral"
            alignment_note = (
                f"Funding was neutral ({exp_fr:.5f}) during the {exp_change:.1f}% move on {exp_sym}. "
                f"Funding does not explain the move, and this snapshot cannot identify the cause. "
                f"Check timestamped spot flow, news, token supply, and order-flow evidence before assigning a driver. "
                f"No funding edge is established in either direction."
            )

        # Signal cross-reference
        sig_note = ""
        same_as_explosive = exp_sym and exp_sym == explosive.get("symbol")
        if same_as_explosive and explosive_ctx.get("had_signal"):
            sig_dir = explosive_ctx.get("signal_direction", "")
            sig_conv = explosive_ctx.get("signal_conviction", "")
            sig_result = explosive_ctx.get("signal_result") or "open"
            sig_note = (
                f" {exp_sym} was on our list today — {sig_dir} at {sig_conv} conviction, currently {sig_result}. "
                f"The system caught this name."
            )
        elif same_as_explosive and explosive_ctx.get("was_blocked"):
            gate = explosive_ctx.get("block_gate", "a risk gate")
            sig_note = f" {exp_sym} was blocked by {gate} before reaching the signal list — it was on our radar but gated out."
        else:
            sig_note = (
                f" {exp_sym} is the funding desk's specialty-selected focus, not an inferred trade. "
                "Its next useful observation is whether carry normalizes with or without structural price follow-through."
            )

        narrative["funding_autopsy"] = (
            f"The big move today was {exp_sym} at {exp_change:+.1f}%. {alignment_note}{sig_note} "
            f"Across persisted snapshots, the largest OI rotation was {lead_oi.get('symbol') or 'unavailable'} "
            f"at {float(lead_oi.get('oi_change_pct') or 0):+.2f}%, with funding moving from "
            f"{float(lead_oi.get('funding_start') or 0):.5f} to {float(lead_oi.get('funding_end') or 0):.5f}. "
            f"Forward call: if this is a {alignment}, watch for funding to normalize over the next 8–24 hours. "
            f"That normalization window is when the next tradeable setup typically appears."
        )
    else:
        if neg_funding or pos_funding:
            narrative["funding_autopsy"] = (
                f"No single explosive move to dissect today, but funding pressure is real. "
                f"{neg_funding} names run extreme negative funding (short squeeze risk) and "
                f"{pos_funding} run extreme positive (long flush risk). "
                f"Crowded carry without price resolution is a pending event, not a stable condition. "
                f"Watch for a catalyst that forces the unwind — that's where the next explosive move comes from."
            )
        else:
            narrative["funding_autopsy"] = (
                f"No explosive move and no extreme funding today. "
                f"Funding-neutral environments reduce one edge signal but don't eliminate others. "
                f"Structure and volume still apply. My read: stay selective, let setup quality drive entries."
            )

    # --- Niobe: microstructure_autopsy — volume classification, continuation vs trap ---
    if lead_flow:
        exp_sym = lead_flow.get("symbol", "")
        market_match = next(
            (
                row for row in [*top_gainers, *top_losers, explosive]
                if row and _report_symbol(row) == exp_sym
            ),
            {},
        )
        exp_change = _report_percent_change(market_match)
        exp_vol = _report_volume(market_match)
        narrative["microstructure_autopsy"] = (
            f"{exp_sym} was selected for the strongest retained focus-name tape"
            f"{f' alongside a {exp_change:+.1f}% move on {exp_vol / 1e6:.0f}M USD reported volume' if market_match else ''}. "
            f"The packet contains "
            f"{int(lead_flow.get('trade_count') or 0)} trades, "
            f"{float(lead_flow.get('flow_delta_pct') or 0):+.1f}% aggressive-flow delta, "
            f"{float(lead_flow.get('average_imbalance') or 0):+.3f} average book imbalance, and "
            f"{float(lead_flow.get('average_spread_bps') or 0):.2f} bps average spread. "
            f"Continuation requires flow and book pressure to remain aligned on a retest; divergence or a widening spread converts the move into a trap review."
        )
    else:
        narrative["microstructure_autopsy"] = (
            f"No report focus name had enough retained MEXC tape and depth to support a measured flow call. "
            f"Ticker volume cannot distinguish aggressive buying from passive absorption. "
            f"Use the current order-flow overlay before manual execution; if spread, depth, and trade delta are unavailable, keep the setup in review rather than inferring liquidity from the candle."
        )

    # --- Ghost: cross_venue_autopsy — venue leader, arb gap implications ---
    if explosive:
        exp_sym = explosive.get("symbol", "")
        exp_change = _report_float(explosive.get("change_24h_pct"))
        exp_cross = next(
            (
                row for row in (cross_venue.get("price_dislocations") or [])
                if str(row.get("symbol") or "") == str(exp_sym)
            ),
            None,
        )
        if exp_cross:
            move_note = ""
            if exp_cross.get("venue_leader"):
                move_note = (
                    f" Across the retained window, {exp_cross.get('venue_leader')} led the move by "
                    f"{float(exp_cross.get('leader_margin_bps') or 0):.1f} bps; "
                    f"direction agreement was {str(exp_cross.get('direction_aligned')).lower()}."
                )
            else:
                move_note = " This is the first retained batch in the window, so move leadership is not yet measurable."
            narrative["cross_venue_autopsy"] = (
                f"{exp_sym} moved {exp_change:+.1f}%. Its cached venue range is "
                f"{float(exp_cross.get('raw_price_gap_bps') or 0):.1f} raw bps and "
                f"{float(exp_cross.get('adjusted_price_gap_bps') or 0):.1f} bps after the USDC quote buffer, "
                f"with {exp_cross.get('premium_venue')} at the premium and "
                f"{exp_cross.get('discount_venue')} at the discount.{move_note} "
                f"The normalized funding spread is "
                f"{float(exp_cross.get('funding_gap_8h_bps') or 0):.3f} bps per 8h. "
                f"Use this to judge market-wide confirmation—not as an arbitrage or entry signal—and inspect live depth before acting."
            )
        else:
            narrative["cross_venue_autopsy"] = (
                f"{exp_sym} moved {exp_change:+.1f}%, but no matched cached MEXC/Hyperliquid/Bybit row covers it in this report window. "
                f"Venue leadership, price dispersion, and normalized funding divergence are therefore unresolved. "
                f"Keep the move in review until a fresh MT7 signal and current multi-venue evidence agree."
            )
    else:
        lead_cross = (cross_venue.get("price_dislocations") or [{}])[0]
        if cross_venue.get("available") and lead_cross:
            narrative["cross_venue_autopsy"] = (
                f"No single explosive mover dominates the report. The widest cached adjusted venue range is "
                f"{lead_cross.get('symbol')} at {float(lead_cross.get('adjusted_price_gap_bps') or 0):.1f} bps, "
                f"with {lead_cross.get('premium_venue')} at the premium and {lead_cross.get('discount_venue')} at the discount. "
                f"That is a dislocation to monitor, not proof of direction or executable arbitrage. "
                f"Require persistence, current depth, fees, transfer constraints, and a fresh MT7 setup before using it."
            )
        else:
            narrative["cross_venue_autopsy"] = (
                f"No synchronized cached venue evidence exists in this report window. "
                f"I cannot infer leadership, confirmation, or arbitrage conditions from a single exchange snapshot. "
                f"Wait for the background collector and a fresh MT7 signal before making a venue-based call."
            )

    # --- Priya: tokenomics_watch — supply, schedule, treasury, and explicit gaps ---
    token_assets = (
        tokenomics.get("focus_assets")
        or tokenomics.get("float_risk_assets")
        or []
    )
    token_unlocks = tokenomics.get("focus_unlocks") or []
    token_treasuries = tokenomics.get("focus_treasuries") or []
    lead_token = token_assets[0] if token_assets else {}
    lead_unlock = token_unlocks[0] if token_unlocks else {}
    lead_treasury = token_treasuries[0] if token_treasuries else {}
    if lead_token:
        token_note = (
            f"My clearest measured supply qualifier is {lead_token.get('symbol')}: "
            f"{float(lead_token.get('float_pct') or 0):.1f}% of reported max/total supply "
            f"is circulating, FDV is {float(lead_token.get('fdv_market_cap_ratio') or 0):.2f}× "
            f"market cap, and the cached float-risk label is {lead_token.get('risk_level') or 'normal'}. "
        )
    else:
        token_note = (
            "No report focus name has an unambiguous cached CoinGecko supply mapping, "
            "so I will not infer float quality from price or volume. "
        )
    if lead_unlock:
        if lead_unlock.get("linear_rate_change"):
            unlock_note = (
                f"The next aggregated schedule is a linear rate change for "
                f"{lead_unlock.get('project_name')} at {lead_unlock.get('unlock_at')}; "
                "it is not a one-time cliff and has no fabricated dollar value. "
            )
        else:
            unlock_note = (
                f"The next aggregated cliff is {lead_unlock.get('project_name')} at "
                f"{lead_unlock.get('unlock_at')}, about "
                f"{float(lead_unlock.get('unlock_pct_float') or 0):.2f}% of circulating "
                f"supply and ${float(lead_unlock.get('unlock_value_usd') or 0):,.0f} "
                "at the cached price. "
            )
    else:
        unlock_note = "No next-unlock observation is mapped to the report focus set. "
    treasury_note = (
        (
            f"{lead_treasury.get('project_name')} has ${float(lead_treasury.get('treasury_value_usd') or 0):,.0f} "
            f"of aggregated treasury value with {float(lead_treasury.get('own_token_share_pct') or 0):.1f}% "
            "in its own token; that measures composition risk, not sale intent. "
        )
        if lead_treasury else
        "No mapped treasury-composition observation covers the focus set. "
    )
    narrative["tokenomics_watch"] = (
        f"{token_note}{unlock_note}{treasury_note}"
        "Use these observations to qualify admission and downside risk. Do not use them "
        "to increase leverage or position size, and do not call a whale or exchange-flow "
        "event: direct holder concentration and labeled wallet flows remain unavailable."
    )

    # --- Hari: social_watch — direct activity, evidence quality, and manipulation risk ---
    social_rows = social.get("focus_topics") or social.get("topic_snapshots") or []
    lead_social = (
        next(
            (row for row in social_rows if row.get("topic_key") == "market"),
            social_rows[0] if social_rows else {},
        )
    )
    if lead_social:
        baseline_note = (
            f"Activity is {float(lead_social.get('activity_vs_baseline_pct')):+.1f}% "
            f"versus the trailing median built from {int(lead_social.get('baseline_observations') or 0)} snapshots."
            if lead_social.get("activity_vs_baseline_pct") is not None else
            f"Only {int(lead_social.get('baseline_observations') or 0)} prior snapshots exist, "
            "so acceleration is not yet measurable."
        )
        narrative["social_watch"] = (
            f"My direct sample for {lead_social.get('symbol') or lead_social.get('topic_key')} "
            f"contains {int(lead_social.get('post_count') or 0)} public posts from "
            f"{int(lead_social.get('unique_authors') or 0)} authors over the six-hour window, "
            f"or {float(lead_social.get('posts_per_hour') or 0):.2f} posts per hour. {baseline_note} "
            f"Top-author concentration is {float(lead_social.get('top_author_share_pct') or 0):.1f}% "
            f"and duplicate-language share is {float(lead_social.get('duplicate_text_share_pct') or 0):.1f}%, "
            f"producing a {lead_social.get('evidence_quality')} quality label. This is Bluesky-only attention, "
            "not cross-platform sentiment and not proof that popular claims are true. Use it to prioritize "
            "verification; require price, volume, structure, and a fresh MT7 signal before taking any action."
        )
    else:
        narrative["social_watch"] = (
            f"No cached direct social sample exists in this report window. Funding still shows "
            f"{neg_funding} short-crowded and {pos_funding} long-crowded buckets, but derivatives "
            "positioning is not social sentiment. Keep the attention thesis unclassified until a source-labeled "
            "sample includes enough unique authors, a usable baseline, and low duplication; do not infer crowd "
            "direction from price, funding, or a few posts."
        )

    # --- Yasmin: catalyst_watch — official event, timing, reaction test, invalidation ---
    catalyst_rows = [
        *(catalysts.get("active_incidents") or []),
        *(catalysts.get("focus_events") or []),
        *(catalysts.get("events_in_window") or []),
        *(catalysts.get("upcoming_events") or []),
    ]
    catalyst_rows = list({
        (
            row.get("source_key"),
            row.get("title"),
            row.get("event_at"),
        ): row
        for row in catalyst_rows
    }.values())
    if catalyst_rows:
        lead_event = catalyst_rows[0]
        event_assets = ", ".join(lead_event.get("affected_assets") or ["market-wide"])
        timing = lead_event.get("event_at") or lead_event.get("published_at") or "time unavailable"
        narrative["catalyst_watch"] = (
            f"My highest-priority official-source item is “{lead_event.get('title')}” from "
            f"{lead_event.get('source_name')}. It is classified {lead_event.get('event_type')} / "
            f"{lead_event.get('severity')}, timed for {timing}, and mapped to {event_assets}. "
            f"The source proves that the event exists; it does not prove bullish or bearish direction. "
            f"Before the timestamp, treat volatility expectations as risk context. After it, measure breadth, "
            f"volume, funding, MEXC order flow, and venue agreement. If those reactions do not align—or the "
            f"asset mapping is unrelated—discard the catalyst attribution and keep any setup review-only until a fresh MT7 signal appears."
        )
    else:
        mover_note = (
            f"I therefore cannot attribute {xsym}'s {xmove} move to news. "
            if explosive else
            "There is also no qualified mover to test against a catalyst timeline. "
        )
        narrative["catalyst_watch"] = (
            f"No cached official MEXC, Bybit, Hyperliquid Statuspage, or Federal Reserve event is "
            f"time-matched to this report window. {mover_note}"
            f"Keep the catalyst desk unclassified, check source health, and wait for a "
            f"fresh MT7 signal; missing catalyst coverage is not evidence that no event occurred."
        )

    # --- Weekly additions ---
    if weekly:
        wins = int(paper.get("wins") or 0)
        closed = int(paper.get("closed") or 0)
        avg_pnl = _report_float(paper.get("avg_pnl_pct"))
        total_pnl = _report_float(paper.get("total_pnl_pct"))

        perf_note = ""
        if closed >= 5:
            win_rate = round(wins / closed * 100) if closed else 0
            if win_rate >= 60 and avg_pnl > 0:
                perf_note = f" The paper numbers are encouraging — {win_rate}% win rate and {avg_pnl:.2f}% average P&L. If these hold another two weeks, the filters are earning promotion to live."
            elif win_rate < 40 or avg_pnl < 0:
                perf_note = f" The paper numbers are telling me something is wrong — {win_rate}% win rate and {avg_pnl:.2f}% average P&L. Before going live, I need to understand whether this is a filter problem or a regime problem."
            else:
                perf_note = f" Paper is running at {win_rate}% and {avg_pnl:.2f}% average — acceptable but not yet compelling. Give it more reps before reading too much into it."
        elif closed > 0:
            perf_note = f" Only {closed} paper trades closed this week — too thin for statistical reads. Keep running."
        else:
            perf_note = " No paper trades closed this week. Check that the paper bot is scanning and that minimum conviction thresholds are reachable."

        upcoming = catalysts.get("upcoming_events") or []
        lead_upcoming = upcoming[0] if upcoming else {}
        catalyst_note = (
            f" The next official scheduled item is “{lead_upcoming.get('title')}” at "
            f"{lead_upcoming.get('event_at')}; define the pre-event risk window and judge direction only from the post-event response."
            if lead_upcoming else
            " No official scheduled item is cached for the look-ahead window, so verify the source-health panel before treating the calendar as clear."
        )
        narrative["week_ahead"] = (
            f"I closed {closed} paper trades this week with {wins} winners, {avg_pnl:.2f}% average, and {total_pnl:.2f}% total P&L.{perf_note} "
            f"The base case is conditional continuation of the {regime} regime; the rotation case activates only if another regime leads across consecutive sessions. "
            f"Funding extremes ({neg_funding} negative, {pos_funding} positive) define the crowding risk, not a guaranteed squeeze or flush. "
            f"Next week, compare every setup with the 0–24h, 2–7d, and 2–6w horizon board before changing strategy posture."
            f"{catalyst_note}"
        )

        spotlight_key = data.get("spotlight_key") or "funding"
        spotlight = data.get("agent_spotlight") or _report_agent_spotlight(data)
        spotlight_name = spotlight.get("name") or spotlight_key.replace("_", " ").title()
        evidence = spotlight.get("evidence") or []
        evidence_note = f" Evidence: {'; '.join(evidence[:2])}." if evidence else ""
        narrative["spotlight"] = (
            f"This week's spotlight is {spotlight_name}: {spotlight.get('current_contribution') or 'specialty review pending'}."
            f"{evidence_note} Trader use: {spotlight.get('trader_use') or 'keep the contribution advisory'}. "
            f"Invalidation: {spotlight.get('invalidation') or 'new contradictory evidence'}. "
            f"Coverage is {spotlight.get('coverage') or 'unknown'}, so the spotlight audits both the call and the data the analyst did not have."
        )

    return narrative


def _merge_report_narrative(base: dict, override: dict) -> dict:
    merged = dict(base)
    for key, value in (override or {}).items():
        if key in merged and isinstance(value, str) and value.strip():
            candidate = value.strip()
            baseline = str(base.get(key) or "")
            # AI polish may improve readability, but it may not collapse a
            # measured desk note back into the short generic copy this report
            # layer was built to replace.
            min_words = max(55, int(len(baseline.split()) * 0.7))
            if len(candidate.split()) >= min_words:
                merged[key] = candidate
    return merged


def _call_report_ai(data: dict, weekly: bool = False) -> tuple[dict, bool, str]:
    """Generate concise cached report notes. Deterministic notes are the free fallback."""
    narrative = _build_deterministic_report_narrative(data, weekly=weekly)
    mode = REPORT_NARRATIVE_MODE
    if mode in {"deterministic", "off", "none"}:
        return narrative, False, "deterministic"
    allowed_providers = None
    if mode in {"free", "free_only", "free-only"}:
        allowed_providers = REPORT_FREE_AI_PROVIDERS
    elif mode in {"auto", "any"}:
        allowed_providers = None
    elif mode:
        # Future-friendly: REPORT_NARRATIVE_MODE=ollama or =gemini restricts
        # report polishing to that provider while keeping deterministic fallback.
        allowed_providers = {mode}
    try:
        from lib.agents import AGENT_ROSTER, FIRM_META
        compact = {
            "date": data.get("date"),
            "week": data.get("week"),
            "market_pulse": data.get("market_pulse"),
            "top_gainers": data.get("top_gainers", [])[:3],
            "top_losers": data.get("top_losers", [])[:3],
            "explosive_move": data.get("explosive_move"),
            "disagreements": data.get("disagreements", [])[:4],
            "strategy_regime_perf": data.get("strategy_regime_perf", [])[:8],
            "paper_desk": data.get("paper_desk", {}),
            "action_matrix": data.get("action_matrix", {}),
            "snapshot_meta": data.get("snapshot_meta", {}),
            "specialist_evidence": data.get("specialist_evidence", {}),
        }
        system = (
            f"You are the editorial desk for {FIRM_META['name']}. Return only JSON. "
            "Write concise institutional crypto research notes for retail traders. "
            "Do not imitate copyrighted dialogue; use the broad voice traits provided. "
            "Never claim you are opening, entering, longing, shorting, buying, or selling. "
            "Use only advisory verbs: review, watch, wait, avoid, investigate. "
            "If the explosive mover has no MT7 signal, call it a missed-mover review, not an entry."
        )
        requested = [
            ("trader_open", AGENT_ROSTER["trader"]),
            ("regime_forecast", AGENT_ROSTER["regime"]),
            ("risk_close", AGENT_ROSTER["risk_manager"]),
            ("funding_autopsy", AGENT_ROSTER["funding"]),
            ("microstructure_autopsy", AGENT_ROSTER["microstructure"]),
            ("cross_venue_autopsy", AGENT_ROSTER["cross_venue"]),
            ("catalyst_watch", AGENT_ROSTER["news"]),
            ("tokenomics_watch", AGENT_ROSTER["tokenomics"]),
            ("social_watch", AGENT_ROSTER["sentiment"]),
        ]
        if weekly:
            requested.extend([
                ("week_ahead", AGENT_ROSTER["trader"]),
                ("spotlight", AGENT_ROSTER.get(data.get("spotlight_key", "funding"), AGENT_ROSTER["funding"])),
            ])
        analyst_guide = "\n".join(
            f"- {k}: {v['name']}, {v.get('domain', v.get('role', 'analyst'))}"
            for k, v in requested
        )
        output_template = json.dumps({k: "" for k, _ in requested}, indent=2)
        user = (
            "Market data:\n"
            f"{json.dumps(compact, default=str)}\n\n"
            "Write one 80-140 word first-person institutional desk note for each analyst using the data above. "
            "State the measured read, cite specific numbers, explain the trading implication, and end with "
            "a confirmation/invalidation or forward-monitoring call. Preserve evidence density; do not replace "
            "measured details with descriptions of the analyst's job. "
            "Do not create trade instructions; reports cannot authorize entries.\n\n"
            "Analyst voices:\n"
            f"{analyst_guide}\n\n"
            "Return only this JSON with your notes as the values (no extra text):\n"
            f"{output_template}"
        )
        raw = call_ai(
            system=system,
            user=user,
            max_tokens=1800,
            allowed_providers=allowed_providers,
            feature="report_polish",
        )
        if not raw:
            return narrative, False, "deterministic"
        clean = raw.strip()
        if clean.startswith("```"):
            clean = clean.removeprefix("```json").removeprefix("```").removesuffix("```").strip()
        parsed = json.loads(clean)
        if isinstance(parsed, dict):
            merged = _merge_report_narrative(narrative, parsed)
            return _sanitize_report_narrative(merged, data), True, "ai"
    except Exception as e:
        print(f"[report_ai] {e}", file=sys.stderr)
    return narrative, False, "deterministic"


def _report_explosive_signal_context(symbol: str, date_str: str) -> dict:
    """Check if the explosive move pair appeared in today's signals or blocked list."""
    ctx: dict = {"had_signal": False, "was_blocked": False}
    if not symbol:
        return ctx
    try:
        con = sqlite3.connect(DB_PATH)
        row = con.execute(
            "SELECT direction, conviction, result, strategy_key FROM signals "
            "WHERE symbol=? AND date(logged_at)=? ORDER BY conviction DESC LIMIT 1",
            (symbol, date_str),
        ).fetchone()
        if row:
            ctx.update({"had_signal": True, "signal_direction": row[0],
                         "signal_conviction": row[1], "signal_result": row[2],
                         "signal_strategy": row[3]})
        blk = con.execute(
            "SELECT gate_key FROM filtered_candidates WHERE symbol=? AND date(logged_at)=? LIMIT 1",
            (symbol, date_str),
        ).fetchone()
        if blk:
            ctx.update({"was_blocked": True, "block_gate": blk[0]})
        con.close()
    except Exception as e:
        print(f"[explosive_ctx] {e}", file=sys.stderr)
    return ctx


def _report_coiling_base_rates(coiling: list, date_str: str) -> dict:
    """Historical win rate for extreme-funding setups in the signals DB."""
    result: dict = {}
    if not coiling:
        return result
    try:
        con = sqlite3.connect(DB_PATH)
        for entry in coiling[:4]:
            fr = _report_float(entry.get("funding_rate"))
            sym = entry.get("symbol", "")
            if fr == 0 or not sym:
                continue
            direction = "LONG" if fr < 0 else "SHORT"
            threshold = max(abs(fr) * 0.5, 0.0003)
            sign = -1 if fr < 0 else 1
            rows = con.execute(
                "SELECT result FROM signals WHERE direction=? "
                "AND funding_rate IS NOT NULL AND ABS(funding_rate)>=? "
                "AND (CASE WHEN funding_rate<0 THEN -1 ELSE 1 END)=? "
                "AND result IN ('WIN','LOSS','PARTIAL') AND date(logged_at)<date(?) LIMIT 100",
                (direction, threshold, sign, date_str),
            ).fetchall()
            n = len(rows)
            wins = sum(1 for r in rows if r[0] in ("WIN", "PARTIAL"))
            result[sym] = {
                "n": n,
                "win_rate": round(wins / n * 100) if n >= 5 else None,
                "direction": direction,
            }
        con.close()
    except Exception as e:
        print(f"[coiling_base_rates] {e}", file=sys.stderr)
    return result


def _report_classify_market_regime(
    ticker_items: list[dict],
    signal_regime_counts: dict[str, int] | None = None,
) -> dict:
    """Classify the desk-wide regime from broad, measured market evidence.

    Per-signal agent coverage is intentionally sparse, so missing agent fields
    must not outvote the observed 1,000+ contract market snapshot. This
    classifier uses breadth, median movement, dispersion, large-move density,
    and funding crowding. It abstains when the snapshot is too small.
    """
    usable = [
        item for item in ticker_items
        if item.get("change_24h_pct") is not None
    ]
    total = len(usable)
    valid_signal_counts = {
        str(key): int(value or 0)
        for key, value in (signal_regime_counts or {}).items()
        if str(key) != "unknown" and int(value or 0) > 0
    }
    if total < 50:
        classified_signals = sum(valid_signal_counts.values())
        if classified_signals >= 5:
            label = max(valid_signal_counts, key=valid_signal_counts.get)
            return {
                "label": label,
                "confidence": "low",
                "source": "classified_signal_subset",
                "sample": classified_signals,
                "coverage_pct": round(
                    classified_signals / max(1, sum((signal_regime_counts or {}).values())) * 100,
                    1,
                ),
                "directional_bias": "mixed",
                "evidence": [
                    f"Broad ticker snapshot insufficient ({total} contracts).",
                    f"Fallback uses {classified_signals} classified signals.",
                ],
            }
        return {
            "label": "unknown",
            "confidence": "insufficient",
            "source": "abstention",
            "sample": total,
            "coverage_pct": 0.0,
            "directional_bias": "unknown",
            "evidence": [f"Only {total} usable contracts; at least 50 are required."],
        }

    moves = sorted(_report_float(item.get("change_24h_pct")) for item in usable)
    absolute_moves = sorted(abs(value) for value in moves)
    mid = total // 2
    median_move = moves[mid] if total % 2 else (moves[mid - 1] + moves[mid]) / 2
    p75_abs = absolute_moves[min(total - 1, int((total - 1) * 0.75))]
    advancers = len([value for value in moves if value > 0.25])
    decliners = len([value for value in moves if value < -0.25])
    advancer_ratio = advancers / total
    decliner_ratio = decliners / total
    large_move_ratio = len([value for value in absolute_moves if value >= 8]) / total
    funding_values = [
        abs(_report_float(item.get("funding_rate")))
        for item in usable if item.get("funding_rate") is not None
    ]
    extreme_funding_ratio = (
        len([value for value in funding_values if value >= 0.001]) / len(funding_values)
        if funding_values else 0.0
    )
    directional_bias = (
        "bullish" if advancer_ratio >= 0.60
        else "bearish" if decliner_ratio >= 0.60
        else "mixed"
    )

    label = "choppy"
    confidence = "medium"
    reason = "Breadth is mixed and neither compression nor market-wide expansion dominates."
    if decliner_ratio >= 0.65 and median_move <= -1.0:
        label = "risk_off_beta"
        confidence = "high" if decliner_ratio >= 0.72 else "medium"
        reason = "Declining breadth and the median contract move show broad downside beta pressure."
    elif large_move_ratio >= 0.12 and p75_abs >= 5.0:
        label = "liquidation_cascade"
        confidence = "medium"
        reason = "A large share of contracts are making outsized moves with elevated cross-market dispersion."
    elif extreme_funding_ratio >= 0.10 and p75_abs >= 3.0:
        label = "volatile_squeeze"
        confidence = "medium"
        reason = "Extreme perp carry is widespread while price dispersion is elevated."
    elif extreme_funding_ratio >= 0.12:
        label = "funding_crowded"
        confidence = "medium"
        reason = "Extreme funding is broad enough to make crowded positioning the dominant structural condition."
    elif (
        (advancer_ratio >= 0.65 or decliner_ratio >= 0.65)
        and abs(median_move) >= 1.0
    ):
        label = "trending"
        confidence = "high" if max(advancer_ratio, decliner_ratio) >= 0.72 else "medium"
        reason = "Directional breadth and the median contract move agree."
    elif p75_abs <= 1.5 and abs(median_move) <= 0.4:
        label = "compression"
        confidence = "medium"
        reason = "Three quarters of contracts remain inside a narrow 24-hour movement band."

    classified_signals = sum(valid_signal_counts.values())
    all_signals = sum((signal_regime_counts or {}).values())
    return {
        "label": label,
        "confidence": confidence,
        "source": "broad_ticker_snapshot",
        "sample": total,
        "coverage_pct": 100.0,
        "directional_bias": directional_bias,
        "evidence": [
            reason,
            (
                f"Breadth: {advancers} advancing / {decliners} declining; "
                f"median move {median_move:+.2f}%."
            ),
            (
                f"75th-percentile absolute move {p75_abs:.2f}%; "
                f"{large_move_ratio * 100:.1f}% moved at least 8%."
            ),
            (
                f"Extreme-funding share {extreme_funding_ratio * 100:.1f}% "
                f"across {len(funding_values)} funded contracts."
            ),
            (
                f"Signal-agent regime coverage {classified_signals}/{all_signals}."
                if all_signals
                else "No signal-agent regime rows were available."
            ),
        ],
        "metrics": {
            "advancer_ratio": round(advancer_ratio, 4),
            "decliner_ratio": round(decliner_ratio, 4),
            "median_move_pct": round(median_move, 2),
            "p75_abs_move_pct": round(p75_abs, 2),
            "large_move_ratio": round(large_move_ratio, 4),
            "extreme_funding_ratio": round(extreme_funding_ratio, 4),
        },
    }


def _build_daily_data(
    date_str: str,
    ticker_snapshot: list[dict] | None = None,
    *,
    include_specialist_evidence: bool = True,
) -> dict:
    """Build template-driven daily report data from Matrix Trader state."""
    signals = _report_db_rows("signals", "logged_at", date_str, limit=1000)
    blocked = _report_db_rows("filtered_candidates", "logged_at", date_str, limit=500)
    paper = _report_db_rows("paper_trades", "opened_at", date_str, days_back=7, limit=500)
    if ticker_snapshot is not None:
        tickers = ticker_snapshot
        snapshot_meta = {
            "source": "provided",
            "snapshot_at": None,
            "freshness_minutes": None,
        }
    else:
        tickers, snapshot_meta = _report_ticker_snapshot_for_date(date_str)

    exchange_breakdown: dict[str, int] = {}
    regime_counts: dict[str, int] = {}
    sessions = {k: {"count": 0, "symbols": []} for k in ("ASIA", "LONDON", "NY", "UNKNOWN")}
    disagreements = []

    for sig in signals:
        exchange = sig.get("exchange") or "MEXC"
        symbol = _report_symbol(sig)
        exchange_breakdown[exchange] = exchange_breakdown.get(exchange, 0) + 1
        session = _report_classify_session(sig.get("logged_at", ""))
        sessions.setdefault(session, {"count": 0, "symbols": []})
        sessions[session]["count"] += 1
        if symbol:
            sessions[session]["symbols"].append(symbol)

        sj = _report_signal_json(sig)
        regime = sj.get("agent_regime") or sj.get("regime") or "unknown"
        regime_counts[regime] = regime_counts.get(regime, 0) + 1
        score = _report_float(sj.get("agent_shadow_disagreement", sj.get("agent_disagreement")), 0)
        if score > 0.4:
            disagreements.append({
                "symbol": symbol,
                "exchange": exchange,
                "direction": sig.get("direction"),
                "conviction": sig.get("conviction"),
                "disagreement_score": round(score, 3),
                "narrative_bull": sj.get("agent_narrative_bull"),
                "structural_bull": sj.get("agent_structural_bull"),
            })

    def ticker_item(t: dict) -> dict:
        return {
            "symbol": _report_symbol(t),
            "exchange": t.get("exchange") or "MEXC",
            "change_24h_pct": round(_report_percent_change(t), 2),
            "volume_24h": round(_report_volume(t), 0),
            "funding_rate": _report_funding(t),
        }

    ticker_items = [ticker_item(t) for t in tickers if _report_symbol(t)]
    ticker_items.sort(key=lambda x: x["change_24h_pct"], reverse=True)
    top_gainers = ticker_items[:5]
    top_losers = sorted(ticker_items, key=lambda x: x["change_24h_pct"])[:5]
    moves = sorted(_report_float(t.get("change_24h_pct")) for t in ticker_items)
    if moves:
        mid = len(moves) // 2
        median_move = moves[mid] if len(moves) % 2 else (moves[mid - 1] + moves[mid]) / 2
    else:
        median_move = 0.0
    market_breadth = {
        "total": len(ticker_items),
        "advancers": len([m for m in moves if m > 0.25]),
        "decliners": len([m for m in moves if m < -0.25]),
        "unchanged": len([m for m in moves if -0.25 <= m <= 0.25]),
        "median_move_pct": round(median_move, 2),
        "volume_leaders": sorted(
            ticker_items,
            key=lambda x: _report_float(x.get("volume_24h")),
            reverse=True,
        )[:5],
    }

    heatmap = sorted(
        [{"symbol": t["symbol"], "exchange": t["exchange"], "funding_rate": t["funding_rate"]}
         for t in ticker_items if t["funding_rate"] is not None],
        key=lambda x: x["funding_rate"],
    )
    funding_heatmap = {
        "extreme_negative": [h for h in heatmap if h["funding_rate"] < -0.001][:10],
        "mild_negative": [h for h in heatmap if -0.001 <= h["funding_rate"] < -0.00025][:10],
        "neutral": [h for h in heatmap if abs(h["funding_rate"]) <= 0.00025][:8],
        "mild_positive": [h for h in heatmap if 0.00025 < h["funding_rate"] <= 0.001][:10],
        "extreme_positive": [h for h in heatmap if h["funding_rate"] > 0.001][:10],
    }
    coiling = [
        {
            "symbol": t["symbol"],
            "exchange": t["exchange"],
            "funding_rate": t["funding_rate"],
            "change_24h_pct": t["change_24h_pct"],
            "watch": "SHORT SQUEEZE" if t["funding_rate"] < 0 else "LONG FLUSH",
        }
        for t in ticker_items
        if abs(t["funding_rate"]) > 0.0008 and abs(t["change_24h_pct"]) < 3
    ][:8]

    explosive_move = None
    if ticker_items:
        explosive_move = max(ticker_items, key=lambda x: abs(x["change_24h_pct"]))

    perf_rows = _report_db_rows("signals", "logged_at", date_str, days_back=7, limit=2000)
    perf: dict[tuple[str, str], dict] = {}
    for row in perf_rows:
        result = str(row.get("result") or "").lower()
        if result not in ("win", "loss", "partial"):
            continue
        regime = _report_signal_json(row).get("agent_regime") or "unknown"
        strategy = row.get("strategy_key") or row.get("strategy") or "unknown"
        bucket = perf.setdefault(
            (strategy, regime),
            {"win": 0, "loss": 0, "partial": 0, "pnl_values": []},
        )
        bucket[result] += 1
        if row.get("pnl_pct") is not None:
            bucket["pnl_values"].append(_report_float(row.get("pnl_pct")))

    closed_paper = [p for p in paper if str(p.get("status") or "").lower() == "closed"]
    pnl_values = [_report_float(p.get("pnl_pct")) for p in closed_paper if p.get("pnl_pct") is not None]
    paper_wins = [
        p for p in closed_paper
        if str(p.get("result") or "").upper() in ("WIN", "TP3", "PARTIAL", "TP1", "TP2")
    ]
    positive_pnl = sum(x for x in pnl_values if x > 0)
    negative_pnl = abs(sum(x for x in pnl_values if x < 0))
    gross_values = [
        _report_float(p.get("gross_pnl_pct"))
        for p in closed_paper if p.get("gross_pnl_pct") is not None
    ]
    fee_values = [
        _report_float(p.get("fee_cost_pct"))
        for p in closed_paper if p.get("fee_cost_pct") is not None
    ]
    slippage_values = [
        _report_float(p.get("slippage_cost_pct"))
        for p in closed_paper if p.get("slippage_cost_pct") is not None
    ]
    realized_pnl_usd = sum(
        _paper_trade_pnl_usd(p)
        for p in closed_paper if p.get("pnl_pct") is not None
    )
    curve = 0.0
    peak = 0.0
    max_drawdown_usd = 0.0
    for p in sorted(closed_paper, key=lambda x: str(x.get("closed_at") or x.get("opened_at") or "")):
        curve += _paper_trade_pnl_usd(p)
        peak = max(peak, curve)
        max_drawdown_usd = max(max_drawdown_usd, peak - curve)
    paper_desk = {
        "open": len([p for p in paper if str(p.get("status") or "").lower() == "open"]),
        "closed": len(closed_paper),
        "wins": len(paper_wins),
        "win_rate_pct": round(len(paper_wins) / len(closed_paper) * 100, 1) if closed_paper else 0,
        "avg_pnl_pct": round(sum(pnl_values) / len(pnl_values), 2) if pnl_values else 0,
        "total_pnl_pct": round(sum(pnl_values), 2) if pnl_values else 0,
        "profit_factor": round(positive_pnl / negative_pnl, 2) if negative_pnl else None,
        "realized_pnl_usd": round(realized_pnl_usd, 2),
        "max_drawdown_usd": round(max_drawdown_usd, 2),
        "avg_gross_pnl_pct": round(sum(gross_values) / len(gross_values), 2) if gross_values else None,
        "avg_fee_cost_pct": round(sum(fee_values) / len(fee_values), 4) if fee_values else None,
        "avg_slippage_cost_pct": round(sum(slippage_values) / len(slippage_values), 4) if slippage_values else None,
        "compounded_trades": len([
            p for p in closed_paper
            if str(p.get("sizing_mode") or "").lower() in ("equity_compound", "compound")
        ]),
    }

    regime_assessment = _report_classify_market_regime(ticker_items, regime_counts)
    dominant_regime = str(regime_assessment.get("label") or "unknown")
    history_rows = _report_db_rows("signals", "logged_at", date_str, days_back=30, limit=5000)
    regime_windows = {"7d": defaultdict(int), "30d": defaultdict(int)}
    cutoff_7d = (datetime.fromisoformat(date_str) - timedelta(days=7)).date()
    for row in history_rows:
        row_regime = _report_signal_json(row).get("agent_regime") or _report_signal_json(row).get("regime") or "unknown"
        regime_windows["30d"][row_regime] += 1
        try:
            logged_date = datetime.fromisoformat(str(row.get("logged_at") or "").replace("Z", "+00:00")).date()
        except Exception:
            logged_date = cutoff_7d
        if logged_date >= cutoff_7d:
            regime_windows["7d"][row_regime] += 1
    regime_history = {}
    for window, counts in regime_windows.items():
        clean_counts = dict(counts)
        regime_history[window] = {
            "counts": clean_counts,
            "observations": sum(clean_counts.values()),
            "dominant": max(clean_counts, key=clean_counts.get) if clean_counts else "unknown",
        }
    explosive_sym = (explosive_move or {}).get("symbol", "")
    explosive_signal_context = _report_explosive_signal_context(explosive_sym, date_str)
    coiling_base_rates = _report_coiling_base_rates(coiling, date_str)
    focus_symbols = [
        x.get("symbol") for x in
        [explosive_move, *top_gainers[:2], *top_losers[:2], *coiling[:2]]
        if x and x.get("symbol")
    ]
    specialist_evidence = (
        _report_market_history_evidence(
            date_str,
            days=1,
            focus_symbols=focus_symbols,
        )
        if include_specialist_evidence else {}
    )
    strategy_regime_perf = []
    for key, values in sorted(perf.items()):
        pnl = values.pop("pnl_values", [])
        total = int(values.get("win") or 0) + int(values.get("loss") or 0) + int(values.get("partial") or 0)
        good = int(values.get("win") or 0) + int(values.get("partial") or 0)
        strategy_regime_perf.append({
            "strategy": key[0],
            "regime": key[1],
            **values,
            "sample": total,
            "win_partial_rate_pct": round(good / total * 100, 1) if total else 0,
            "avg_pnl_pct": round(sum(pnl) / len(pnl), 2) if pnl else None,
        })
    report_data = {
        "date": date_str,
        "snapshot_meta": snapshot_meta,
        "market_pulse": {
            "signals": len(signals),
            "blocked": len(blocked),
            "dominant_regime": dominant_regime,
            "regime_confidence": regime_assessment.get("confidence"),
            "regime_source": regime_assessment.get("source"),
            "regime_directional_bias": regime_assessment.get("directional_bias"),
            "regime_evidence": regime_assessment.get("evidence") or [],
            "desk_agreement": "high" if not disagreements else "mixed",
            "exchange_breakdown": exchange_breakdown,
        },
        "signals_today": signals[:100],
        "blocked": blocked[:100],
        "sessions": sessions,
        "regime_counts": regime_counts,
        "regime_assessment": regime_assessment,
        "regime_history": regime_history,
        "market_breadth": market_breadth,
        "funding_heatmap": funding_heatmap,
        "top_gainers": top_gainers,
        "top_losers": top_losers,
        "explosive_move": explosive_move,
        "explosive_signal_context": explosive_signal_context,
        "whats_coiling": coiling,
        "coiling_base_rates": coiling_base_rates,
        "liquidation_clusters": [],
        "disagreements": disagreements[:10],
        "strategy_regime_perf": strategy_regime_perf,
        "specialist_evidence": specialist_evidence,
        "desk_wrong": [],
        "paper_desk": paper_desk,
        "learner": _report_read_learner_files(),
    }
    report_data["action_matrix"] = _build_report_action_matrix(report_data)
    return report_data


def _report_read_learner_files() -> dict:
    data = {"briefs": [], "suggestions": []}
    for key, path in (
        ("briefs", "/opt/mt-learner/research/briefs.json"),
        ("suggestions", "/opt/mt-learner/suggestions/pending.json"),
    ):
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    payload = json.load(f)
                data[key] = payload.get(key, payload.get("briefs", payload if isinstance(payload, list) else []))
        except Exception:
            pass
    return data


def _report_weekly_rollups(start: datetime) -> list[dict]:
    """Build seven lightweight daily rollups with one bounded DB pass."""
    end = start + timedelta(days=7)
    day_map = {
        (start + timedelta(days=offset)).strftime("%Y-%m-%d"): {
            "date": (start + timedelta(days=offset)).strftime("%Y-%m-%d"),
            "market_pulse": {
                "signals": 0,
                "blocked": 0,
                "dominant_regime": "unknown",
                "desk_agreement": "high",
                "exchange_breakdown": {},
            },
            "regime_counts": {},
            "market_snapshot_available": False,
            "market_snapshot_batches": 0,
            "market_snapshot_symbols": 0,
        }
        for offset in range(7)
    }
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        tables = {
            str(r[0]) for r in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        }
        if "signals" in tables:
            rows = con.execute(
                """
                SELECT logged_at, exchange, signal_json
                FROM signals
                WHERE logged_at>=? AND logged_at<?
                ORDER BY logged_at
                LIMIT 10000
                """,
                (start.isoformat(), end.isoformat()),
            ).fetchall()
            for row in rows:
                day = str(row["logged_at"] or "")[:10]
                bucket = day_map.get(day)
                if not bucket:
                    continue
                pulse = bucket["market_pulse"]
                pulse["signals"] += 1
                exchange = str(row["exchange"] or "MEXC")
                pulse["exchange_breakdown"][exchange] = (
                    pulse["exchange_breakdown"].get(exchange, 0) + 1
                )
                sj = _report_signal_json({"signal_json": row["signal_json"]})
                regime = str(sj.get("agent_regime") or sj.get("regime") or "unknown")
                bucket["regime_counts"][regime] = bucket["regime_counts"].get(regime, 0) + 1
                disagreement = _report_float(
                    sj.get("agent_shadow_disagreement", sj.get("agent_disagreement")),
                    0,
                )
                if disagreement > 0.4:
                    pulse["desk_agreement"] = "mixed"
        if "filtered_candidates" in tables:
            rows = con.execute(
                """
                SELECT logged_at, COUNT(*)
                FROM filtered_candidates
                WHERE logged_at>=? AND logged_at<?
                GROUP BY substr(logged_at, 1, 10)
                """,
                (start.isoformat(), end.isoformat()),
            ).fetchall()
            for logged_at, count in rows:
                day = str(logged_at or "")[:10]
                if day in day_map:
                    day_map[day]["market_pulse"]["blocked"] = int(count or 0)
        if "ticker_snapshots" in tables:
            rows = con.execute(
                """
                SELECT substr(ts, 1, 10) AS day,
                       COUNT(DISTINCT ts) AS batches,
                       COUNT(DISTINCT symbol) AS symbols
                FROM ticker_snapshots
                WHERE ts>=? AND ts<?
                GROUP BY substr(ts, 1, 10)
                """,
                (start.isoformat(), end.isoformat()),
            ).fetchall()
            for row in rows:
                day = str(row["day"] or "")
                if day in day_map:
                    day_map[day]["market_snapshot_available"] = bool(row["batches"])
                    day_map[day]["market_snapshot_batches"] = int(row["batches"] or 0)
                    day_map[day]["market_snapshot_symbols"] = int(row["symbols"] or 0)
        con.close()
    except Exception as e:
        print(f"[report_weekly_rollups] {e}", file=sys.stderr)
    for bucket in day_map.values():
        counts = bucket["regime_counts"]
        bucket["market_pulse"]["dominant_regime"] = (
            max(counts, key=counts.get) if counts else "unknown"
        )
    return list(day_map.values())


def _build_weekly_data(week_key: str) -> dict:
    try:
        year, week_num = week_key.split("-W", 1)
        start = datetime.fromisocalendar(int(year), int(week_num), 1)
    except Exception:
        start = datetime.utcnow() - timedelta(days=6)
        year, week_num, _ = start.isocalendar()
        week_key = f"{year}-W{week_num:02d}"
    today_str = datetime.utcnow().strftime("%Y-%m-%d")
    days = _report_weekly_rollups(start)
    report_date = min(today_str, (start + timedelta(days=6)).strftime("%Y-%m-%d"))
    latest = _build_daily_data(report_date, include_specialist_evidence=False)
    weekly_regimes: dict[str, int] = defaultdict(int)
    weekly_signals = 0
    weekly_blocked = 0
    weekly_disagreement_days = 0
    for day in days:
        day_pulse = day.get("market_pulse") or {}
        weekly_signals += int(day_pulse.get("signals") or 0)
        weekly_blocked += int(day_pulse.get("blocked") or 0)
        if day_pulse.get("desk_agreement") == "mixed":
            weekly_disagreement_days += 1
        for label, count in (day.get("regime_counts") or {}).items():
            weekly_regimes[str(label)] += int(count or 0)
    weekly_dominant = max(weekly_regimes, key=weekly_regimes.get) if weekly_regimes else "unknown"
    active_signal_days = len([
        day for day in days if int((day.get("market_pulse") or {}).get("signals") or 0) > 0
    ])
    daily_signal_counts = [
        int((day.get("market_pulse") or {}).get("signals") or 0) for day in days
    ]
    daily_blocked_counts = [
        int((day.get("market_pulse") or {}).get("blocked") or 0) for day in days
    ]
    latest["current_market_pulse"] = latest.get("market_pulse") or {}
    latest["market_pulse"] = {
        **(latest.get("market_pulse") or {}),
        "signals": weekly_signals,
        "blocked": weekly_blocked,
        "dominant_regime": weekly_dominant,
        "desk_agreement": "mixed" if weekly_disagreement_days else "high",
        "scope": "weekly",
    }
    focus_symbols = [
        x.get("symbol") for x in
        [
            latest.get("explosive_move"),
            *(latest.get("top_gainers") or [])[:2],
            *(latest.get("top_losers") or [])[:2],
        ]
        if x and x.get("symbol")
    ]
    latest["specialist_evidence"] = _report_market_history_evidence(
        start.strftime("%Y-%m-%d"),
        days=7,
        focus_symbols=focus_symbols,
    )
    spotlight_order = ["funding", "microstructure", "cross_venue", "regime", "technical",
                       "sentiment", "news", "tokenomics", "narrative_debate",
                       "structural_debate", "risk_manager", "trader"]
    spotlight_key = spotlight_order[int(week_num) % len(spotlight_order)]
    latest.update({
        "week": week_key,
        "daily_rollup": days,
        "spotlight_key": spotlight_key,
        "weekly_summary": {
            "signals": weekly_signals,
            "blocked": weekly_blocked,
            "dominant_regime": weekly_dominant,
            "regime_counts": dict(weekly_regimes),
            "mixed_desk_days": weekly_disagreement_days,
            "active_signal_days": active_signal_days,
            "daily_signal_counts": daily_signal_counts,
            "daily_blocked_counts": daily_blocked_counts,
            "signal_change_first_to_last": (
                daily_signal_counts[-1] - daily_signal_counts[0]
                if daily_signal_counts else 0
            ),
            "blocked_change_first_to_last": (
                daily_blocked_counts[-1] - daily_blocked_counts[0]
                if daily_blocked_counts else 0
            ),
            "market_snapshot_days": len([
                d for d in days if d.get("market_snapshot_available")
            ]),
            "market_snapshot_note": (
                f"Persisted MEXC all-market snapshots were available for "
                f"{len([d for d in days if d.get('market_snapshot_available')])}/7 days in this "
                "report window. Historical breadth and rotation use only those measured snapshots."
            ),
        },
        "upcoming_events": (
            (latest.get("specialist_evidence") or {})
            .get("catalysts", {})
            .get("upcoming_events", [])
        )[:8],
    })
    return latest


def _report_cache_path(report_type: str, key: str) -> str:
    safe_key = re.sub(r"[^0-9A-Za-z_-]", "-", key)
    return os.path.join(REPORTS_DIR, f"{report_type}_{safe_key}.json")


def _report_sentences(narrative: dict) -> set[str]:
    sentences: set[str] = set()
    for value in (narrative or {}).values():
        if not isinstance(value, str):
            continue
        for sentence in re.split(r"(?<=[.!?])\s+", value):
            normalized = re.sub(r"\s+", " ", sentence.strip().lower())
            if len(normalized) >= 35:
                sentences.add(normalized)
    return sentences


def _report_repetition_audit(report_type: str, key: str, narrative: dict) -> dict:
    """Bounded exact-sentence baseline against prior reports and the paired daily."""
    current = _report_sentences(narrative)
    comparisons: list[dict] = []
    try:
        candidates = sorted(
            (
                name for name in os.listdir(REPORTS_DIR)
                if name.startswith(f"{report_type}_") and name.endswith(".json")
            ),
            reverse=True,
        )[:15]
        for filename in candidates:
            path = os.path.join(REPORTS_DIR, filename)
            try:
                with open(path, "r", encoding="utf-8") as handle:
                    prior = json.load(handle)
                if str(prior.get("key")) == str(key):
                    continue
                prior_sentences = _report_sentences(prior.get("narrative") or {})
                shared = current & prior_sentences
                comparisons.append({
                    "report": prior.get("key") or filename,
                    "shared_sentences": len(shared),
                    "overlap_pct": round(len(shared) / max(1, len(current)) * 100, 1),
                })
            except Exception:
                continue
        if report_type == "weekly":
            daily_key = str((key and datetime.utcnow().strftime("%Y-%m-%d")) or "")
            daily_path = _report_cache_path("daily", daily_key)
            if os.path.exists(daily_path):
                with open(daily_path, "r", encoding="utf-8") as handle:
                    daily = json.load(handle)
                daily_sentences = _report_sentences(daily.get("narrative") or {})
                shared = current & daily_sentences
                comparisons.append({
                    "report": f"paired daily {daily_key}",
                    "shared_sentences": len(shared),
                    "overlap_pct": round(len(shared) / max(1, len(current)) * 100, 1),
                    "comparison_type": "daily_weekly",
                })
    except Exception as exc:
        return {
            "status": "unavailable",
            "sentence_count": len(current),
            "max_overlap_pct": None,
            "comparisons": [],
            "note": f"Repetition baseline unavailable: {exc}",
        }
    maximum = max((row["overlap_pct"] for row in comparisons), default=0.0)
    return {
        "status": "pass" if maximum < 30 else "review",
        "sentence_count": len(current),
        "max_overlap_pct": maximum,
        "threshold_pct": 30,
        "comparisons": sorted(comparisons, key=lambda row: row["overlap_pct"], reverse=True)[:5],
        "method": "exact normalized sentences of 35+ characters; bounded to 15 prior reports",
    }


def _report_parse_iso(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).replace(tzinfo=None)
    except Exception:
        return None


def _register_report_claims(report_type: str, key: str, generated_at: str, data: dict) -> int:
    """Register only current, future-observable claims. Historical rebuilds never backfill."""
    now = datetime.utcnow().replace(microsecond=0)
    current_key = now.strftime("%Y-%m-%d") if report_type == "daily" else now.strftime("%G-W%V")
    if str(key) != current_key:
        return 0
    duration = timedelta(days=1 if report_type == "daily" else 7)
    window_start = now
    window_end = now + duration
    pulse = data.get("market_pulse") or {}
    breadth = data.get("market_breadth") or {}
    regime = str(pulse.get("dominant_regime") or "unknown")
    total = int(breadth.get("total") or 0)
    advancers = int(breadth.get("advancers") or 0)
    decliners = int(breadth.get("decliners") or 0)
    funding_item = ((data.get("analyst_focus") or {}).get("funding") or {}).get("item") or {}
    claims: list[dict] = []
    if regime != "unknown" and int(pulse.get("signals") or 0) >= 5:
        claims.append({
            "analyst_key": "regime",
            "claim_type": "regime_persistence",
            "symbol": "",
            "metric": "dominant_regime",
            "comparator": "equals",
            "threshold": None,
            "expected_value": regime,
            "baseline_value": None,
            "source_section": "regime_forecast",
            "evidence": {
                "signals": int(pulse.get("signals") or 0),
                "desk_agreement": pulse.get("desk_agreement"),
            },
        })
    if total >= 20:
        bias = "positive" if advancers / total >= 0.58 else "negative" if decliners / total >= 0.58 else "mixed"
        claims.append({
            "analyst_key": "trader",
            "claim_type": "breadth_persistence",
            "symbol": "",
            "metric": "breadth_bias",
            "comparator": "equals",
            "threshold": 0.58,
            "expected_value": bias,
            "baseline_value": round((advancers - decliners) / max(1, total), 6),
            "source_section": "trader_open",
            "evidence": {"advancers": advancers, "decliners": decliners, "total": total},
        })
    funding_rate = _report_funding(funding_item)
    funding_symbol = _report_symbol(funding_item)
    if funding_symbol and abs(funding_rate) >= 0.0003:
        claims.append({
            "analyst_key": "funding",
            "claim_type": "funding_normalization",
            "symbol": funding_symbol,
            "metric": "absolute_funding_rate",
            "comparator": "decreases_by_pct",
            "threshold": 0.20,
            "expected_value": "normalize",
            "baseline_value": funding_rate,
            "source_section": "funding_autopsy",
            "evidence": {
                "selection_reason": ((data.get("analyst_focus") or {}).get("funding") or {}).get("selection_reason"),
                "change_24h_pct": _report_percent_change(funding_item),
            },
        })
    if not claims:
        return 0
    inserted = 0
    try:
        con = sqlite3.connect(DB_PATH, timeout=5)
        for claim in claims:
            # The first forward claim is the accountable claim. Regenerating a
            # report may change the focus packet, but it must never rewrite or
            # multiply a prediction after its observation window has begun.
            existing = con.execute(
                """
                SELECT id FROM report_claims
                WHERE report_type=? AND report_key=? AND analyst_key=? AND claim_type=?
                LIMIT 1
                """,
                (report_type, key, claim["analyst_key"], claim["claim_type"]),
            ).fetchone()
            if existing:
                continue
            cur = con.execute(
                """
                INSERT OR IGNORE INTO report_claims
                    (report_type,report_key,generated_at,analyst_key,claim_type,symbol,
                     window_start,window_end,metric,comparator,threshold,expected_value,
                     baseline_value,evidence_json,source_section,status)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending')
                """,
                (
                    report_type, key, generated_at, claim["analyst_key"], claim["claim_type"],
                    claim["symbol"], window_start.isoformat(), window_end.isoformat(),
                    claim["metric"], claim["comparator"], claim["threshold"],
                    claim["expected_value"], claim["baseline_value"],
                    json.dumps(claim["evidence"], default=str), claim["source_section"],
                ),
            )
            inserted += max(0, int(cur.rowcount or 0))
        con.commit()
        con.close()
    except Exception as exc:
        print(f"[report_claims_register] {exc}", file=sys.stderr)
    return inserted


def _resolve_report_claim_observation(con, claim: dict) -> tuple[str, str]:
    metric = claim["metric"]
    start = claim["window_start"]
    end = claim["window_end"]
    if metric == "dominant_regime":
        rows = con.execute(
            """
            SELECT signal_json FROM signals
            WHERE logged_at>=? AND logged_at<=?
            """,
            (start, end),
        ).fetchall()
        counts: dict[str, int] = defaultdict(int)
        for row in rows:
            try:
                payload = json.loads(row[0] or "{}")
                label = str(payload.get("agent_regime") or payload.get("regime") or "unknown")
                if label != "unknown":
                    counts[label] += 1
            except Exception:
                continue
        if not counts:
            return "", "No classified signals were recorded in the claim window."
        return max(counts, key=counts.get), f"Observed regime counts: {dict(counts)}"
    if metric == "breadth_bias":
        latest = con.execute(
            "SELECT MAX(ts) FROM ticker_snapshots WHERE ts>=? AND ts<=?",
            (start, end),
        ).fetchone()[0]
        if not latest:
            return "", "No ticker snapshot was recorded in the claim window."
        rows = con.execute(
            "SELECT change_24h_pct FROM ticker_snapshots WHERE ts=?",
            (latest,),
        ).fetchall()
        if not rows:
            return "", "The latest ticker batch had no usable rows."
        adv = sum(1 for row in rows if _report_float(row[0]) > 0)
        dec = sum(1 for row in rows if _report_float(row[0]) < 0)
        total = len(rows)
        threshold = float(claim["threshold"] or 0.58)
        label = "positive" if adv / total >= threshold else "negative" if dec / total >= threshold else "mixed"
        return label, f"Latest breadth {adv}/{dec} advancing/declining across {total} rows."
    if metric == "absolute_funding_rate":
        row = con.execute(
            """
            SELECT funding_rate FROM ticker_snapshots
            WHERE symbol=? AND ts>=? AND ts<=?
            ORDER BY ts DESC LIMIT 1
            """,
            (claim["symbol"], start, end),
        ).fetchone()
        if not row or row[0] is None:
            return "", "No ending funding snapshot was recorded for the focus symbol."
        return str(float(row[0])), f"Ending funding rate: {float(row[0]):.8f}"
    return "", "Unsupported metric."


def _score_mature_report_claims(limit: int = 100) -> dict:
    """Resolve mature claims descriptively; this function has no scoring authority."""
    now = datetime.utcnow().isoformat()
    summary = {"resolved": 0, "correct": 0, "incorrect": 0, "unscorable": 0}
    try:
        con = sqlite3.connect(DB_PATH, timeout=5)
        con.row_factory = sqlite3.Row
        rows = con.execute(
            """
            SELECT * FROM report_claims
            WHERE status='pending' AND window_end<=?
            ORDER BY window_end LIMIT ?
            """,
            (now, max(1, min(int(limit or 100), 500))),
        ).fetchall()
        for raw in rows:
            claim = dict(raw)
            observed, note = _resolve_report_claim_observation(con, claim)
            if observed == "":
                status = "unscorable"
            elif claim["comparator"] == "equals":
                status = "resolved_correct" if str(observed) == str(claim["expected_value"]) else "resolved_incorrect"
            elif claim["comparator"] == "decreases_by_pct":
                baseline = abs(float(claim["baseline_value"] or 0))
                ending = abs(float(observed))
                threshold = float(claim["threshold"] or 0)
                status = "resolved_correct" if baseline and ending <= baseline * (1 - threshold) else "resolved_incorrect"
                note += f" Baseline absolute rate: {baseline:.8f}; required decrease: {threshold * 100:.0f}%."
            else:
                status = "unscorable"
                note = "Unsupported comparator."
            con.execute(
                """
                UPDATE report_claims
                SET status=?, resolved_at=?, observed_value=?, resolution_note=?
                WHERE id=?
                """,
                (status, now, observed or None, note, claim["id"]),
            )
            summary["resolved"] += 1
            if status == "resolved_correct":
                summary["correct"] += 1
            elif status == "resolved_incorrect":
                summary["incorrect"] += 1
            else:
                summary["unscorable"] += 1
        con.commit()
        con.close()
    except Exception as exc:
        summary["error"] = str(exc)
    return summary


def _report_claims_packet(limit: int = 20) -> dict:
    """Small read-only accountability packet for the report UI."""
    try:
        con = sqlite3.connect(DB_PATH, timeout=3)
        con.row_factory = sqlite3.Row
        totals = {
            str(row["status"]): int(row["n"] or 0)
            for row in con.execute(
                "SELECT status, COUNT(*) AS n FROM report_claims GROUP BY status"
            ).fetchall()
        }
        analyst_rows = con.execute(
            """
            SELECT analyst_key,
                   SUM(CASE WHEN status='resolved_correct' THEN 1 ELSE 0 END) AS correct,
                   SUM(CASE WHEN status='resolved_incorrect' THEN 1 ELSE 0 END) AS incorrect,
                   SUM(CASE WHEN status='unscorable' THEN 1 ELSE 0 END) AS unscorable,
                   SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending
            FROM report_claims GROUP BY analyst_key ORDER BY analyst_key
            """
        ).fetchall()
        claim_rows = con.execute(
            """
            SELECT report_type,report_key,analyst_key,claim_type,symbol,window_end,metric,comparator,threshold,
                   expected_value,baseline_value,status,observed_value,resolution_note,source_section
            FROM report_claims ORDER BY generated_at DESC, id DESC LIMIT ?
            """,
            (max(1, min(int(limit or 20), 100)),),
        ).fetchall()
        con.close()
        analysts = []
        for row in analyst_rows:
            resolved = int(row["correct"] or 0) + int(row["incorrect"] or 0)
            analysts.append({
                **dict(row),
                "resolved": resolved,
                "accuracy_pct": round(int(row["correct"] or 0) / resolved * 100, 1) if resolved else None,
            })
        return {
            "available": True,
            "authority": "descriptive_only",
            "totals": totals,
            "analysts": analysts,
            "claims": [dict(row) for row in claim_rows],
            "rules": [
                "Only claims written before their observation window can be scored.",
                "Unscorable claims remain visible and do not count as correct.",
                "Claim accuracy cannot alter signals, strategies, risk, sizing, or execution.",
            ],
        }
    except Exception as exc:
        return {
            "available": False,
            "authority": "descriptive_only",
            "totals": {},
            "analysts": [],
            "claims": [],
            "error": str(exc),
        }


def _load_or_build_report(report_type: str, key: str, force: bool = False) -> dict:
    os.makedirs(REPORTS_DIR, exist_ok=True)
    path = _report_cache_path(report_type, key)
    if not force and os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                cached = json.load(f)
            if cached.get("schema_version") == REPORT_SCHEMA_VERSION:
                today = datetime.utcnow().strftime("%Y-%m-%d")
                current_week = datetime.utcnow().strftime("%G-W%V")
                is_current = (
                    (report_type == "daily" and key == today)
                    or (report_type == "weekly" and key == current_week)
                )
                # Historical reports are immutable. Current reports refresh
                # deterministically so new cached evidence does not remain
                # invisible until the user explicitly asks for AI regeneration.
                max_age_seconds = 900 if report_type == "daily" else 3600
                cache_age = max(0, time.time() - os.path.getmtime(path))
                if not is_current or cache_age < max_age_seconds:
                    return cached
            # Rebuild old schemas once so new evidence fields come from the
            # persisted stores. Relabeling an old payload would look upgraded
            # while silently retaining its original data gaps.
        except Exception:
            pass
    data = _build_weekly_data(key) if report_type == "weekly" else _build_daily_data(key)
    _enrich_report_intelligence(data, weekly=(report_type == "weekly"))
    if force:
        narrative, ai_available, narrative_source = _call_report_ai(
            data,
            weekly=(report_type == "weekly"),
        )
    else:
        # First paint is deterministic and cacheable. The explicit Regenerate
        # action may spend AI latency on editorial polish without making report
        # navigation wait on a hosted/free provider.
        narrative = _build_deterministic_report_narrative(
            data,
            weekly=(report_type == "weekly"),
        )
        ai_available = False
        narrative_source = "deterministic_fast"
    generated_at = datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    data["narrative_trust"] = _report_narrative_trust(narrative_source)
    data["narrative_quality"] = _report_repetition_audit(
        report_type,
        key,
        narrative,
    )
    _register_report_claims(report_type, key, generated_at, data)
    data["claim_accountability"] = _report_claims_packet()
    report = {
        "success": True,
        "schema_version": REPORT_SCHEMA_VERSION,
        "type": report_type,
        "key": key,
        "date": data.get("date"),
        "week": data.get("week"),
        "data": data,
        "narrative": narrative,
        "ai_available": ai_available,
        "narrative_source": narrative_source,
        "generated_at": generated_at,
    }
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(report, f, indent=2, default=str)
    except Exception as e:
        print(f"[report_cache] {e}", file=sys.stderr)
    return report


