@app.route("/api/ai/benchmarks", methods=["POST"])
def api_ai_benchmarks_start():
    """Start an explicit shadow benchmark in a background thread."""
    try:
        from lib.ai_benchmark import (
            BENCHMARK_CASES,
            MAX_CANDIDATES,
            create_benchmark_run,
            execute_benchmark_run,
        )
        from lib.ai_client import is_valid_model, load_ai_settings, provider_status

        body = request.get_json(silent=True) or {}
        feature = str(body.get("feature") or "").strip()
        raw_models = body.get("models")
        if feature not in BENCHMARK_CASES:
            return jsonify({"success": False, "error": "unknown benchmark feature"}), 400
        if not isinstance(raw_models, list) or not raw_models:
            return jsonify({"success": False, "error": "select at least one candidate model"}), 400
        if len(raw_models) > MAX_CANDIDATES:
            return jsonify({"success": False, "error": f"select no more than {MAX_CANDIDATES} models"}), 400

        settings = load_ai_settings()
        provider_health = {
            item["provider"]: item
            for item in provider_status(settings)
        }
        candidates = []
        seen = set()
        for item in raw_models:
            if not isinstance(item, dict):
                return jsonify({"success": False, "error": "candidate models must be objects"}), 400
            provider = str(item.get("provider") or "").strip()
            model = str(item.get("model") or "").strip()
            key = (provider, model)
            if key in seen:
                continue
            if not is_valid_model(provider, model, settings):
                return jsonify({"success": False, "error": f"unknown model: {provider}/{model}"}), 400
            provider_state = provider_health.get(provider) or {}
            if not provider_state.get("available"):
                return jsonify({"success": False, "error": f"provider is not configured: {provider}"}), 400
            circuit_state = (provider_state.get("circuit") or {}).get("state") or "closed"
            if circuit_state not in {"closed", "probe_ready"}:
                return jsonify({
                    "success": False,
                    "error": f"provider circuit is {circuit_state}: {provider}",
                }), 409
            seen.add(key)
            candidates.append({"provider": provider, "model": model})
        if not candidates:
            return jsonify({"success": False, "error": "no valid candidate models selected"}), 400

        run_id = create_benchmark_run(DB_PATH, feature, candidates)
        thread = threading.Thread(
            target=execute_benchmark_run,
            args=(DB_PATH, run_id, feature, candidates),
            daemon=True,
            name=f"ai-benchmark-{run_id}",
        )
        thread.start()
        return jsonify({
            "success": True,
            "run_id": run_id,
            "feature": feature,
            "candidate_count": len(candidates),
            "case_count": len(BENCHMARK_CASES[feature]),
            "status": "running",
        }), 202
    except RuntimeError as e:
        return jsonify({"success": False, "error": str(e)}), 409
    except ValueError as e:
        return jsonify({"success": False, "error": str(e)}), 400
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/ai/benchmarks/<int:run_id>/promote", methods=["POST"])
def api_ai_benchmark_promote(run_id):
    """Explicitly promote an eligible benchmark model to one feature route."""
    try:
        from lib.ai_benchmark import benchmark_overview, record_promotion
        from lib.ai_client import AI_FEATURES, load_ai_settings, save_ai_settings

        body = request.get_json(silent=True) or {}
        provider = str(body.get("provider") or "").strip()
        model = str(body.get("model") or "").strip()
        feature = str(body.get("feature") or "").strip()
        valid_features = {item["key"] for item in AI_FEATURES}
        if feature not in valid_features:
            return jsonify({"success": False, "error": "unknown AI feature"}), 400

        overview = benchmark_overview(DB_PATH, run_limit=50)
        run = next((item for item in overview["runs"] if item["id"] == run_id), None)
        if not run or run["status"] != "completed" or run["feature"] != feature:
            return jsonify({"success": False, "error": "completed matching benchmark run not found"}), 404
        result = next(
            (
                item for item in run["models"]
                if item["provider"] == provider and item["model"] == model
            ),
            None,
        )
        if not result or not result.get("eligible"):
            return jsonify({"success": False, "error": "model did not meet promotion gates"}), 409

        settings = load_ai_settings()
        routes = dict(settings.get("feature_routes") or {})
        old_route = dict(routes.get(feature) or {
            "provider": settings.get("provider"),
            "model": settings.get("model"),
        })
        new_route = {"provider": provider, "model": model}
        routes[feature] = new_route
        settings["feature_routes"] = routes
        save_ai_settings(settings)
        try:
            record_promotion(DB_PATH, run_id, feature, old_route, new_route)
        except Exception as audit_error:
            print(f"[ai_benchmark] promotion audit failed: {audit_error}", file=sys.stderr)
        return jsonify({
            "success": True,
            "run_id": run_id,
            "feature": feature,
            "old_route": old_route,
            "new_route": new_route,
            "note": "Model routing changed only; trading authority and risk gates are unchanged.",
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


_SHADOW_FORECAST_CYCLE_LOCK = threading.Lock()


def _shadow_forecast_price_resolver(row: dict, target_ts: int):
    """Resolve the first completed Min1 candle at a forecast horizon."""
    try:
        now_ts = int(time.time())
        if now_ts < target_ts + 60:
            return None
        sig = {
            "exchange": row.get("exchange") or "MEXC",
            "symbol": row.get("symbol") or "",
        }
        frame = _fetch_klines_for_signal(
            sig,
            interval="Min1",
            limit=500,
            start_ts=max(0, target_ts - 180),
            end_ts=min(now_ts, target_ts + 900),
        )
        if frame.empty:
            return None
        candidates = []
        for _, candle in frame.iterrows():
            try:
                opened_ts = int(candle["timestamp"])
                closed_ts = opened_ts + 60
                if closed_ts >= target_ts and closed_ts <= target_ts + 900:
                    candidates.append((closed_ts, float(candle["close"])))
            except (TypeError, ValueError):
                continue
        if not candidates:
            return None
        closed_ts, price = min(candidates, key=lambda item: item[0])
        if price <= 0:
            return None
        return (
            price,
            datetime.fromtimestamp(closed_ts, tz=timezone.utc).isoformat(),
        )
    except Exception as e:
        print(f"[shadow_forecast] price resolver error: {e}", file=sys.stderr)
        return None


def _run_shadow_forecast_cycle(action: str = "all") -> dict:
    """Run one bounded collector/evaluator cycle without overlapping itself."""
    if not _SHADOW_FORECAST_CYCLE_LOCK.acquire(blocking=False):
        return {"success": False, "busy": True}
    try:
        from lib.ai_client import load_ai_settings
        from lib.ai_forecasting import collect_forecasts_once, evaluate_due_forecasts

        result = {"success": True}
        if action in {"all", "collect"}:
            result["collection"] = collect_forecasts_once(
                DB_PATH,
                load_ai_settings(),
                max_signals_per_cycle=1,
            )
        if action in {"all", "evaluate"}:
            result["evaluation"] = evaluate_due_forecasts(
                DB_PATH,
                _shadow_forecast_price_resolver,
            )
        return result
    except Exception as e:
        print(f"[shadow_forecast] cycle error: {e}", file=sys.stderr)
        return {"success": False, "error": str(e)}
    finally:
        _SHADOW_FORECAST_CYCLE_LOCK.release()


