@app.route("/api/ai/forecasting/run", methods=["POST"])
def api_ai_forecasting_run():
    """Start one bounded shadow collection/evaluation cycle."""
    try:
        body = request.get_json(silent=True) or {}
        action = str(body.get("action") or "all").strip().lower()
        if action not in {"all", "collect", "evaluate"}:
            return jsonify({"success": False, "error": "unknown forecast action"}), 400
        if _SHADOW_FORECAST_CYCLE_LOCK.locked():
            return jsonify({"success": False, "error": "forecast cycle already running"}), 409
        thread = threading.Thread(
            target=_run_shadow_forecast_cycle,
            args=(action,),
            daemon=True,
            name=f"shadow-forecast-{action}",
        )
        thread.start()
        return jsonify({
            "success": True,
            "status": "running",
            "action": action,
        }), 202
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


