# ---------------------------------------------------------------------------

def _load_paper_config() -> dict:
    try:
        if os.path.exists(PAPER_CONFIG_PATH):
            with open(PAPER_CONFIG_PATH, encoding="utf-8") as f:
                cfg = json.load(f)
                merged = {**_PAPER_CONFIG_DEFAULT, **cfg}
                merged.pop("size_usd", None)
                return merged
    except Exception:
        pass
    return dict(_PAPER_CONFIG_DEFAULT)


def _save_paper_config(cfg: dict) -> None:
    os.makedirs("data", exist_ok=True)
    cfg = dict(cfg)
    cfg.pop("size_usd", None)
    with open(PAPER_CONFIG_PATH, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2)


def _paper_entry_touched(pt: dict, start_iso: str, limit: int = 1440) -> tuple[bool, str | None]:
    """Return whether a pending paper trade's entry price was touched on Min1 candles."""
    start_dt = _parse_utc_iso(start_iso)
    if not start_dt:
        return False, None
    fake_sig = {
        "symbol":    pt["symbol"],
        "direction": pt["direction"],
        "logged_at": start_iso,
        "entry1":    pt["entry_px"],
        "stop_loss": pt["stop_loss"],
        "exchange":  "MEXC",
    }
    klines = _fetch_klines_for_signal(fake_sig, interval="Min1", limit=limit, start_ts=int(start_dt.timestamp()))
    if klines.empty:
        return False, None
    for _, c in klines.iterrows():
        try:
            ts = int(c["timestamp"])
            low = float(c["low"])
            high = float(c["high"])
            if pt["direction"] == "LONG" and low <= float(pt["entry_px"]):
                return True, datetime.utcfromtimestamp(ts).isoformat()
            if pt["direction"] == "SHORT" and high >= float(pt["entry_px"]):
                return True, datetime.utcfromtimestamp(ts).isoformat()
        except Exception:
            continue
    return False, None


def _paper_ticker_spread(ticker: dict | None) -> dict:
    ticker = ticker or {}
    bid = next(
        (ticker.get(key) for key in ("bid1", "bidPrice", "bid_price") if ticker.get(key) is not None),
        None,
    )
    ask = next(
        (ticker.get(key) for key in ("ask1", "askPrice", "ask_price") if ticker.get(key) is not None),
        None,
    )
    try:
        bid = float(bid)
        ask = float(ask)
        mid = (bid + ask) / 2.0
        if bid <= 0 or ask <= 0 or ask < bid or mid <= 0:
            raise ValueError("invalid book")
        return {
            "bid": bid,
            "ask": ask,
            "spread_bps": round((ask - bid) / mid * 10_000.0, 4),
        }
    except (TypeError, ValueError):
        return {"bid": None, "ask": None, "spread_bps": None}


def _paper_check_entries(cfg: dict) -> dict:
    """
    Promote pending paper trades to open only when entry1 is touched.
    Expire pending entries after entry_timeout_hours without counting them as losses.
    """
    filled = 0
    expired = 0
    timeout_hours = float(cfg.get("entry_timeout_hours", 24) or 24)
    now = datetime.utcnow()
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT * FROM paper_trades WHERE status='pending' ORDER BY opened_at ASC"
        ).fetchall()
        con.close()
        tickers = fetch_mexc("/contract/ticker") if rows else []
        ticker_by_symbol = {
            str(ticker.get("symbol") or ""): ticker
            for ticker in (tickers or [])
            if isinstance(ticker, dict) and ticker.get("symbol")
        }

        for row in rows:
            pt = dict(row)
            queued_at = pt.get("queued_at") or pt.get("opened_at")
            queued_parsed = _parse_utc_iso(queued_at)
            queued_dt = queued_parsed.replace(tzinfo=None) if queued_parsed else now

            if (now - queued_dt).total_seconds() > timeout_hours * 3600:
                note = f"Entry not filled within {timeout_hours:g}h"
                closed_at = now.isoformat()
                con = sqlite3.connect(DB_PATH)
                con.execute(
                    """UPDATE paper_trades
                       SET status='entry_expired', closed_at=?, result='EXPIRED', note=?
                       WHERE id=? AND status='pending'""",
                    (closed_at, note, pt["id"]),
                )
                if pt.get("signal_id"):
                    con.execute(
                        """UPDATE signals
                           SET result='EXPIRED', result_note=?, result_at=?
                           WHERE id=? AND result IS NULL AND source='paper'""",
                        (note, closed_at, pt["signal_id"]),
                    )
                con.commit()
                con.close()
                expired += 1
                continue

            touched, entry_at = _paper_entry_touched(pt, queued_at)
            if not touched or not entry_at:
                continue

            observed_at = datetime.utcnow().isoformat()
            spread = _paper_ticker_spread(ticker_by_symbol.get(pt["symbol"]))
            entry_dt = _parse_utc_iso(entry_at)
            observed_dt = _parse_utc_iso(observed_at)
            lag_seconds = (
                max(0.0, (observed_dt - entry_dt).total_seconds())
                if entry_dt and observed_dt else None
            )
            con = sqlite3.connect(DB_PATH)
            con.execute(
                """UPDATE paper_trades
                   SET status='open', opened_at=?, filled_at=?, note=NULL,
                       fill_bid=?, fill_ask=?, fill_spread_bps=?,
                       fill_liquidity_observed_at=?, fill_liquidity_lag_seconds=?
                   WHERE id=? AND status='pending'""",
                (
                    entry_at,
                    entry_at,
                    spread.get("bid"),
                    spread.get("ask"),
                    spread.get("spread_bps"),
                    observed_at,
                    lag_seconds,
                    pt["id"],
                ),
            )
            if pt.get("signal_id"):
                con.execute(
                    "UPDATE signals SET entry_at=? WHERE id=? AND entry_at IS NULL AND source='paper'",
                    (entry_at, pt["signal_id"]),
                )
            con.commit()
            con.close()
            if pt.get("signal_id"):
                log_position_event(
                    {"id": pt["signal_id"], "direction": pt["direction"], "entry1": pt["entry_px"], "leverage": pt.get("leverage")},
                    "ENTRY_FILLED",
                    entry_at,
                    pt["entry_px"],
                    0.0,
                    100.0,
                    f"Paper entry touched at {pt['entry_px']}",
                )
            filled += 1
            print(f"[paper_bot] FILLED {pt['symbol']} {pt['direction']} @ {pt['entry_px']}", file=sys.stderr)
    except Exception as e:
        print(f"[paper_bot] _paper_check_entries error: {e}", file=sys.stderr)
    return {"filled": filled, "expired": expired}


def _paper_cost_adjustment(
    cfg: dict,
    result: str,
    leverage: float,
) -> tuple[float, float, float]:
    """
    Return fee, slippage, and total costs as leveraged P&L percentage points.
    Paper entries are modeled as maker limit fills. Stops are taker exits;
    TP wins are maker exits with a small adverse-fill buffer.
    """
    maker_bps = max(0.0, float(cfg.get("paper_maker_fee_bps", 0.0) or 0.0))
    taker_bps = max(0.0, float(cfg.get("paper_taker_fee_bps", 2.0) or 2.0))
    slip_bps = max(0.0, float(cfg.get("paper_slippage_bps", 3.0) or 3.0))
    lev = max(1.0, float(leverage or 1.0))

    entry_fee_bps = maker_bps
    if result == "WIN":
        exit_fee_bps = maker_bps
        slippage_bps = slip_bps * 0.25
    elif result == "PARTIAL":
        exit_fee_bps = (maker_bps / 3.0) + (taker_bps * 2.0 / 3.0)
        slippage_bps = slip_bps * 0.75
    else:
        exit_fee_bps = taker_bps
        slippage_bps = slip_bps

    fee_cost_pct = round(((entry_fee_bps + exit_fee_bps) / 100.0) * lev, 2)
    slippage_cost_pct = round((slippage_bps / 100.0) * lev, 2)
    return fee_cost_pct, slippage_cost_pct, round(fee_cost_pct + slippage_cost_pct, 2)


def _paper_funding_adjustment(
    pt: dict,
    closed_at: str,
    fetcher=None,
) -> dict:
    """Calculate settled funding while a MEXC Paper position was held.

    Funding intervals are read from settlement history instead of assuming an
    eight-hour cycle. An unavailable response is explicitly incomplete and
    contributes zero to net P&L rather than fabricating a value.
    """
    if str(pt.get("exchange") or "MEXC").upper() != "MEXC":
        return {
            "pnl_pct": 0.0,
            "pnl_usd": 0.0,
            "settlement_count": 0,
            "complete": False,
            "source": "unsupported_exchange",
            "error": "Funding settlement history is implemented for MEXC Paper trades only.",
        }
    opened = _parse_utc_iso(pt.get("filled_at") or pt.get("opened_at"))
    closed = _parse_utc_iso(closed_at)
    if not opened or not closed or closed < opened:
        return {
            "pnl_pct": 0.0,
            "pnl_usd": 0.0,
            "settlement_count": 0,
            "complete": False,
            "source": "mexc_funding_history",
            "error": "Invalid Paper hold interval.",
        }
    fetcher = fetcher or fetch_mexc
    try:
        history_rows = []
        reached_open = False
        for page_num in range(1, 11):
            payload = fetcher(
                "/contract/funding_rate/history",
                {
                    "symbol": pt["symbol"],
                    "page_num": page_num,
                    "page_size": 1000,
                },
            )
            if not isinstance(payload, dict) or not isinstance(payload.get("resultList"), list):
                raise ValueError("MEXC funding history unavailable")
            page_rows = payload.get("resultList") or []
            if not page_rows:
                break
            history_rows.extend(page_rows)
            settle_values = [
                float(item.get("settleTime"))
                for item in page_rows
                if item.get("settleTime") is not None
            ]
            if settle_values and min(settle_values) / 1000.0 <= opened.timestamp():
                reached_open = True
                break
            total_count = int(payload.get("totalCount") or len(history_rows))
            if len(history_rows) >= total_count:
                reached_open = True
                break
        if not history_rows:
            raise ValueError("MEXC funding history returned no settlements")
        if not reached_open:
            raise ValueError("Funding history pagination did not reach the position open time")
        rates = []
        for item in history_rows:
            try:
                settle = datetime.fromtimestamp(
                    float(item.get("settleTime")) / 1000.0,
                    tz=timezone.utc,
                )
                if opened < settle <= closed:
                    rates.append(float(item.get("fundingRate") or 0.0))
            except (TypeError, ValueError, OSError):
                continue
        leverage = max(1.0, float(pt.get("leverage") or 1.0))
        direction_sign = -1.0 if str(pt.get("direction") or "").upper() == "LONG" else 1.0
        pnl_pct = round(direction_sign * sum(rates) * leverage * 100.0, 6)
        size_usd = float(pt.get("size_usd") or 0.0)
        return {
            "pnl_pct": pnl_pct,
            "pnl_usd": round(
                _paper_notional_pnl_usd(size_usd, pnl_pct, leverage),
                6,
            ),
            "settlement_count": len(rates),
            "complete": True,
            "source": "mexc_funding_history",
            "error": None,
        }
    except Exception as e:
        return {
            "pnl_pct": 0.0,
            "pnl_usd": 0.0,
            "settlement_count": 0,
            "complete": False,
            "source": "mexc_funding_history",
            "error": str(e)[:500],
        }


def _paper_backfill_funding(limit: int = 500) -> dict:
    """Backfill closed Paper rows without funding, preserving an audit count."""
    limit = max(1, min(int(limit or 500), 2000))
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    rows = [dict(row) for row in con.execute(
        """SELECT * FROM paper_trades
           WHERE status='closed' AND pnl_pct IS NOT NULL
             AND COALESCE(funding_complete, 0)=0
           ORDER BY closed_at DESC, id DESC
           LIMIT ?""",
        (limit,),
    ).fetchall()]
    con.close()
    cache: dict[tuple, object] = {}

    def cached_fetch(path: str, params: dict | None = None):
        params = params or {}
        key = (path, tuple(sorted(params.items())))
        if key not in cache:
            cache[key] = fetch_mexc(path, params)
        return cache[key]

    updated = 0
    incomplete = 0
    unit_repairs = 0
    errors: list[dict] = []
    for pt in rows:
        funding = _paper_funding_adjustment(
            pt,
            pt.get("closed_at"),
            fetcher=cached_fetch,
        )
        if not funding.get("complete"):
            incomplete += 1
            errors.append({
                "trade_id": pt.get("id"),
                "symbol": pt.get("symbol"),
                "error": funding.get("error"),
            })
            continue
        gross = pt.get("gross_pnl_pct")
        if gross is None:
            gross = (
                float(pt.get("pnl_pct") or 0.0)
                + float(pt.get("fee_cost_pct") or 0.0)
                + float(pt.get("slippage_cost_pct") or 0.0)
            )
        net = round(
            float(gross or 0.0)
            - float(pt.get("fee_cost_pct") or 0.0)
            - float(pt.get("slippage_cost_pct") or 0.0)
            + float(funding.get("pnl_pct") or 0.0),
            2,
        )
        con = sqlite3.connect(DB_PATH)
        con.execute(
            """UPDATE paper_trades
               SET funding_pnl_pct=?, funding_pnl_usd=?,
                   funding_settlement_count=?, funding_complete=1,
                   funding_error=NULL, funding_source=?,
                   cost_model_version=?, pnl_pct=?
               WHERE id=? AND COALESCE(funding_complete, 0)=0""",
            (
                funding.get("pnl_pct"),
                funding.get("pnl_usd"),
                funding.get("settlement_count"),
                funding.get("source"),
                "paper_cost_v2_historical_funding_backfill",
                net,
                pt["id"],
            ),
        )
        if pt.get("signal_id"):
            signal_row = con.execute(
                "SELECT signal_json FROM signals WHERE id=? AND source='paper'",
                (pt["signal_id"],),
            ).fetchone()
            signal_json = _learning_json(signal_row[0], {}) if signal_row else {}
            signal_json.update({
                "pnl_pct": net,
                "funding_pnl_pct": funding.get("pnl_pct"),
                "funding_pnl_usd": funding.get("pnl_usd"),
                "funding_settlement_count": funding.get("settlement_count"),
                "funding_complete": True,
                "cost_model_version": "paper_cost_v2_historical_funding_backfill",
            })
            con.execute(
                """UPDATE signals SET pnl_pct=?, evaluation_version=?, signal_json=?
                   WHERE id=? AND source='paper'""",
                (
                    net,
                    "paper_min1_funding_v2_backfill",
                    json.dumps(signal_json, default=str),
                    pt["signal_id"],
                ),
            )
        con.commit()
        con.close()
        updated += 1
    # Repair rows written by the earlier ambiguous unit convention. This is
    # idempotent and does not change leveraged pnl_pct.
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    funding_rows = [dict(row) for row in con.execute("""
        SELECT id, signal_id, size_usd, leverage, funding_pnl_pct,
               funding_pnl_usd
        FROM paper_trades
        WHERE funding_complete=1 AND funding_pnl_pct IS NOT NULL
    """).fetchall()]
    for row in funding_rows:
        expected = round(
            _paper_notional_pnl_usd(
                row.get("size_usd"),
                row.get("funding_pnl_pct"),
                row.get("leverage"),
            ),
            6,
        )
        if abs(expected - float(row.get("funding_pnl_usd") or 0.0)) < 0.000001:
            continue
        con.execute(
            "UPDATE paper_trades SET funding_pnl_usd=? WHERE id=?",
            (expected, row["id"]),
        )
        if row.get("signal_id"):
            signal_row = con.execute(
                "SELECT signal_json FROM signals WHERE id=? AND source='paper'",
                (row["signal_id"],),
            ).fetchone()
            if signal_row:
                signal_json = _learning_json(signal_row[0], {})
                signal_json["funding_pnl_usd"] = expected
                con.execute(
                    "UPDATE signals SET signal_json=? WHERE id=? AND source='paper'",
                    (json.dumps(signal_json, default=str), row["signal_id"]),
                )
        unit_repairs += 1
    con.commit()
    con.close()
    return {
        "success": True,
        "examined": len(rows),
        "updated": updated,
        "incomplete": incomplete,
        "funding_usd_unit_repairs": unit_repairs,
        "errors": errors[:25],
        "remaining": max(0, len(rows) - updated),
        "behavior_changed": False,
        "live_changed": False,
    }


def _paper_stop_policy(cfg: dict, pt: dict) -> dict:
    """Build the paper-only dynamic stop policy for evaluate_outcome()."""
    valid_modes = {"static", "breakeven_after_tp1", "tp_ladder_lock", "atr_trailing"}
    mode = str(cfg.get("paper_stop_mode") or "static").strip().lower()
    if mode not in valid_modes:
        mode = "static"
    atr_value = 0.0
    try:
        atr_pct = float(pt.get("atr_pct") or 0.0)
        entry = float(pt.get("entry_px") or 0.0)
        if atr_pct > 0 and entry > 0:
            atr_value = entry * atr_pct / 100.0
    except Exception:
        atr_value = 0.0
    return {
        "mode": mode,
        "breakeven_buffer_bps": float(cfg.get("paper_breakeven_buffer_bps", 5.0) or 0.0),
        "trail_atr_value": atr_value * float(cfg.get("paper_trailing_atr_mult", 1.0) or 1.0),
    }


def _liquidation_summary_for_position(
    *,
    exchange: str,
    symbol: str,
    direction: str,
    entry_px: float,
    leverage: float,
    size_usd: float,
    margin_mode: str = "isolated",
) -> dict:
    try:
        return estimate_liquidation_price(
            exchange=exchange,
            symbol=symbol,
            direction=direction,
            entry_price=float(entry_px),
            leverage=float(leverage or 1.0),
            notional_usd=float(size_usd or 0.0),
            margin_mode=margin_mode or "isolated",
        )
    except Exception as e:
        return {"success": False, "error": str(e)}


def _apply_liquidation_to_signal(sig: dict, notional_usd: float | None = None) -> dict:
    """Attach exchange-aware liquidation fields to a signal-like dict."""
    try:
        entry = sig.get("entry1")
        if entry is None and sig.get("entries"):
            entry = (sig.get("entries") or [None])[0]
        if entry is None:
            entry = sig.get("price")
        leverage = sig.get("leverage") or sig.get("leverage_cap") or sig.get("max_leverage") or 1
        notional = float(notional_usd or sig.get("size_usd") or 100.0)
        liq = _liquidation_summary_for_position(
            exchange=sig.get("exchange") or "MEXC",
            symbol=sig.get("symbol"),
            direction=sig.get("direction"),
            entry_px=float(entry),
            leverage=float(leverage),
            size_usd=notional,
            margin_mode=sig.get("margin_mode") or "isolated",
        )
        sig["liquidation"] = liq
        if liq.get("success"):
            sig["liquidation_price"] = liq.get("liquidation_price")
            sig["liquidation_distance_pct"] = liq.get("distance_pct")
            sig["liquidation_mmr"] = liq.get("maintenance_margin_rate")
            sig["liquidation_formula"] = liq.get("formula")
            tags = sig.get("tags")
            if isinstance(tags, str):
                tags = [t.strip() for t in tags.split(",") if t.strip()]
            elif not isinstance(tags, list):
                tags = []
            dist = liq.get("distance_pct")
            if dist is not None:
                if float(dist) < 2.0 and "liq_tight" not in tags:
                    tags.append("liq_tight")
                elif float(dist) >= 5.0 and "liq_safe" not in tags:
                    tags.append("liq_safe")
            sig["tags"] = tags
    except Exception as e:
        sig["liquidation"] = {"success": False, "error": str(e)}
    return sig


def _paper_check_exits(cfg: dict | None = None) -> int:
    """
    Check filled/open paper trades against Min1 klines and close those that
    have hit a TP or stop level. Returns number of trades closed.
    Reuses evaluate_outcome() by mapping paper trade columns to the expected dict shape.
    """
    closed = 0
    cfg = cfg or _load_paper_config()
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT * FROM paper_trades WHERE status='open' ORDER BY opened_at ASC"
        ).fetchall()
        con.close()

        for row in rows:
            pt = dict(row)
            entry_at = pt.get("filled_at") or pt.get("opened_at")
            if not pt.get("liquidation_px"):
                liq = _liquidation_summary_for_position(
                    exchange=pt.get("exchange") or "MEXC",
                    symbol=pt["symbol"],
                    direction=pt["direction"],
                    entry_px=pt["entry_px"],
                    leverage=pt.get("leverage") or 1,
                    size_usd=pt.get("size_usd") or 100,
                    margin_mode=pt.get("margin_mode") or "isolated",
                )
                if liq.get("success"):
                    pt["liquidation_px"] = liq.get("liquidation_price")
                    con = sqlite3.connect(DB_PATH)
                    con.execute(
                        """UPDATE paper_trades
                           SET liquidation_px=?, liquidation_distance_pct=?,
                               liquidation_mmr=?, liquidation_fee_rate=?,
                               liquidation_formula=?, liquidation_tier=?
                           WHERE id=?""",
                        (
                            liq.get("liquidation_price"),
                            liq.get("distance_pct"),
                            liq.get("maintenance_margin_rate"),
                            liq.get("liquidation_fee_rate"),
                            liq.get("formula"),
                            json.dumps(liq.get("risk_tier"), default=str),
                            pt["id"],
                        ),
                    )
                    con.commit()
                    con.close()
            # Build a signals-compatible dict for evaluate_outcome
            fake_sig = {
                "symbol":    pt["symbol"],
                "direction": pt["direction"],
                "logged_at": entry_at,
                "entry_at":  entry_at,   # already entered
                "entry1":    pt["entry_px"],
                "entry2":    pt["entry_px"],
                "entry3":    pt["entry_px"],
                "tp1":       pt["tp1"],
                "tp2":       pt["tp2"],
                "tp3":       pt["tp3"],
                "stop_loss": pt["stop_loss"],
                "leverage":  pt.get("leverage"),
                "exchange":  pt.get("exchange") or "MEXC",
                "liquidation_price": pt.get("liquidation_px"),
            }
            # Min1 klines: catch 1-minute wicks hitting stop/TP, matching live
            # trading behaviour where stop orders execute on any price touch.
            # Long holds are chunked inside _fetch_klines_for_signal, so the
            # full configured holding window is evaluated instead of only 24h.
            outcome = evaluate_outcome(
                fake_sig,
                interval="Min1",
                kline_limit=1440,
                stop_policy=_paper_stop_policy(cfg, pt),
            )
            if outcome is None:
                continue  # no level hit yet — position stays open

            result, note, exit_px, result_at, _ = outcome
            # Paper trades only close WIN/LOSS/PARTIAL — never EXPIRED or SKIPPED
            if result not in {"WIN", "LOSS", "PARTIAL"}:
                continue
            closed_at = result_at or datetime.utcnow().isoformat()
            funding = _paper_funding_adjustment(pt, closed_at)
            leverage = pt.get("leverage") or 1.0
            if exit_px and pt["entry_px"] and pt["entry_px"] != 0:
                raw_pnl = (
                    (exit_px - pt["entry_px"]) / pt["entry_px"] * 100
                    if pt["direction"] == "LONG"
                    else (pt["entry_px"] - exit_px) / pt["entry_px"] * 100
                )
                gross_pnl_pct = round(raw_pnl * leverage, 2)
                fee_cost_pct, slippage_cost_pct, total_cost_pct = _paper_cost_adjustment(
                    cfg, result, leverage
                )
                pnl_pct = round(
                    gross_pnl_pct
                    - total_cost_pct
                    + float(funding.get("pnl_pct") or 0.0),
                    2,
                )
            else:
                gross_pnl_pct = None
                fee_cost_pct = None
                slippage_cost_pct = None
                pnl_pct = None

            execution_cost_complete = bool(
                funding.get("complete")
                and pt.get("fill_spread_bps") is not None
                and float(pt.get("fill_liquidity_lag_seconds") or 999999) <= 300
            )
            con = sqlite3.connect(DB_PATH)
            con.execute(
                """UPDATE paper_trades
                   SET status='closed', closed_at=?, exit_px=?, result=?,
                       gross_pnl_pct=?, fee_cost_pct=?, slippage_cost_pct=?,
                       funding_pnl_pct=?, funding_pnl_usd=?,
                       funding_settlement_count=?, funding_complete=?,
                       funding_error=?, funding_source=?,
                       execution_cost_complete=?, cost_model_version=?,
                       pnl_pct=?, note=?
                   WHERE id=?""",
                (
                    closed_at, exit_px, result, gross_pnl_pct, fee_cost_pct,
                    slippage_cost_pct,
                    funding.get("pnl_pct"),
                    funding.get("pnl_usd"),
                    funding.get("settlement_count"),
                    1 if funding.get("complete") else 0,
                    funding.get("error"),
                    funding.get("source"),
                    1 if execution_cost_complete else 0,
                    "paper_cost_v2_settled_funding",
                    pnl_pct, note, pt["id"],
                ),
            )
            if pt.get("signal_id"):
                con.execute(
                    """UPDATE signals
                       SET result=?, exit_price=?, result_at=?, pnl_pct=?,
                           evaluation_version=?, entry_at=COALESCE(entry_at, ?),
                           entry1=?, entry2=?, entry3=?, tp1=?, tp2=?, tp3=?,
                           stop_loss=?, leverage=COALESCE(leverage, ?)
                       WHERE id=? AND result IS NULL AND source='paper'""",
                    (
                        result, exit_px, closed_at, pnl_pct, "paper_min1_funding_v2",
                        entry_at, pt["entry_px"], pt["entry_px"], pt["entry_px"],
                        pt["tp1"], pt["tp2"], pt["tp3"], pt["stop_loss"],
                        pt.get("leverage"), pt["signal_id"],
                    ),
                )
            con.commit()
            con.close()
            if pt.get("signal_id"):
                journey_sig = dict(fake_sig)
                journey_sig.update({
                    "result": result,
                    "result_at": closed_at,
                    "exit_price": exit_px,
                })
                _persist_journey_to_signal_json(pt["signal_id"], journey_sig, pnl_pct)
            closed += 1
            print(
                f"[paper_bot] closed {pt['symbol']} {pt['direction']} → {result} "
                f"gross={gross_pnl_pct}% funding={funding.get('pnl_pct')}% "
                f"net={pnl_pct}% exit={exit_px}",
                file=sys.stderr,
            )
    except Exception as e:
        print(f"[paper_bot] _paper_check_exits error: {e}", file=sys.stderr)
    if closed:
        try:
            _learning_evaluate_active_experiments()
        except Exception as e:
            print(f"[learning] post-close evaluation error: {e}", file=sys.stderr)
    return closed


def _paper_expire_stale_open_trades(cfg: dict) -> int:
    """
    Free paper slots that stayed open past the configured holding window.
    These are marked EXPIRED, not LOSS, because neither TP nor stop was touched.
    """
    expired = 0
    max_hours = float(cfg.get("max_holding_hours", 80) or 80)
    now = datetime.utcnow()
    try:
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT * FROM paper_trades WHERE status='open' ORDER BY opened_at ASC"
        ).fetchall()
        con.close()

        for row in rows:
            pt = dict(row)
            opened = _parse_utc_iso(pt.get("filled_at") or pt.get("opened_at"))
            opened_dt = opened.replace(tzinfo=None) if opened else now
            if (now - opened_dt).total_seconds() <= max_hours * 3600:
                continue

            note = f"Open paper trade expired after {max_hours:g}h without TP/SL"
            closed_at = now.isoformat()
            con = sqlite3.connect(DB_PATH)
            con.execute(
                """UPDATE paper_trades
                   SET status='expired', closed_at=?, result='EXPIRED', note=?
                   WHERE id=? AND status='open'""",
                (closed_at, note, pt["id"]),
            )
            if pt.get("signal_id"):
                con.execute(
                    """UPDATE signals
                       SET result='EXPIRED', result_note=?, result_at=?
                       WHERE id=? AND result IS NULL AND source='paper'""",
                    (note, closed_at, pt["signal_id"]),
                )
            con.commit()
            con.close()
            expired += 1
            print(
                f"[paper_bot] EXPIRED {pt['symbol']} {pt['direction']} "
                f"after {max_hours:g}h hold",
                file=sys.stderr,
            )
    except Exception as e:
        print(f"[paper_bot] _paper_expire_stale_open_trades error: {e}", file=sys.stderr)
    return expired


def _paper_safety_controls(cfg: dict) -> dict:
    """
    Evaluate recent paper bot performance and return protective parameter overrides.
    Never mutates cfg — returns a plain dict of overrides.

    Controls:
      1. Per-strategy consecutive loss pause: N losses in a row → cooldown (persisted in cfg)
      2. Drawdown risk reduction: account down >X% → scale risk_pct down
      3. Cold streak flow boost: last N closed trades all losses → raise min_flow_score
      4. New strategy auto-block: strategy in registry not previously seen → auto-disable
      5. Global loss alert: consecutive losses >= goals alert → halve risk and raise gates

    Returns:
      extra_disabled   — set of strategy keys currently in cooldown
      risk_multiplier  — float (1.0 = no change, 0.5 = halved)
      flow_score_boost — float to add to min_flow_score
      min_conviction_boost — int to add to paper min_conviction
      cooldowns        — updated cooldown dict to persist
      reasons          — list of human-readable active control strings
    """
    streak_n          = int(cfg.get("loss_streak_pause_n", 4))
    cooldown_h        = float(cfg.get("loss_streak_cooldown_hours", 12.0))
    drawdown_thresh   = float(cfg.get("drawdown_reduce_pct", 20.0))
    cold_n            = int(cfg.get("cold_streak_flow_boost_n", 3))
    account_balance   = float(cfg.get("account_balance_usd", 200.0))

    extra_disabled    = set()
    risk_multiplier   = 1.0
    flow_score_boost  = 0.0
    min_conviction_boost = 0
    reasons           = []
    stored_cooldowns  = dict(cfg.get("_strategy_cooldowns") or {})
    now               = datetime.utcnow()
    now_iso           = now.isoformat()
    new_cooldowns     = {}

    try:
        con = sqlite3.connect(DB_PATH)

        # 1. Per-strategy loss streak → cooldown
        rows = con.execute(
            "SELECT strategy_key, result FROM paper_trades "
            "WHERE result IN ('WIN','LOSS','PARTIAL') "
            "ORDER BY closed_at DESC LIMIT 120"
        ).fetchall()
        by_strat: dict[str, list] = defaultdict(list)
        for strat_key, result in rows:
            by_strat[strat_key].append(result)

        for strat, results in by_strat.items():
            streak = 0
            for r in results:  # newest-first
                if r == "LOSS":
                    streak += 1
                else:
                    break
            existing_resume = stored_cooldowns.get(strat)
            if existing_resume and existing_resume > now_iso:
                extra_disabled.add(strat)
                new_cooldowns[strat] = existing_resume
                reasons.append(f"{strat} paused (cooldown until {existing_resume[:16]}Z)")
            elif streak >= streak_n:
                resume_at = (now + timedelta(hours=cooldown_h)).isoformat()
                extra_disabled.add(strat)
                new_cooldowns[strat] = resume_at
                reasons.append(f"{strat} paused ({streak} losses → resume {resume_at[:16]}Z)")
                print(f"[paper_safety] {strat}: {streak} consecutive losses → cooldown until {resume_at}", file=sys.stderr)

        # 2. Drawdown risk reduction
        pnl_rows = con.execute(
            "SELECT size_usd, pnl_pct, closed_at, leverage FROM paper_trades "
            "WHERE status='closed' AND pnl_pct IS NOT NULL "
            "ORDER BY closed_at ASC, id ASC"
        ).fetchall()
        drawdown_pct = float(_paper_equity_metrics(pnl_rows, account_balance).get("max_drawdown_pct") or 0.0)
        if drawdown_pct >= drawdown_thresh:
            overage = drawdown_pct - drawdown_thresh
            risk_multiplier = max(0.4, 1.0 - overage / 100.0)
            reasons.append(f"drawdown {drawdown_pct:.1f}% → risk ×{risk_multiplier:.2f}")

        # 3. Cold streak → elevated flow score
        recent_results = con.execute(
            "SELECT result FROM paper_trades "
            "WHERE result IN ('WIN','LOSS','PARTIAL') "
            "ORDER BY closed_at DESC LIMIT ?",
            (cold_n,)
        ).fetchall()
        if len(recent_results) >= cold_n and all(r[0] == "LOSS" for r in recent_results):
            flow_score_boost = 20.0
            reasons.append(f"cold streak (last {cold_n} all losses) → flow_score +{flow_score_boost:.0f}")

        # 4. Global consecutive-loss alert → automatic paper tightening.
        goals = _load_goals()
        alert_n = int(goals.get("consecutive_loss_alert") or DEFAULT_GOALS.get("consecutive_loss_alert") or 5)
        streak_rows = con.execute(
            "SELECT result FROM paper_trades "
            "WHERE result IN ('WIN','LOSS','PARTIAL') "
            "ORDER BY closed_at DESC LIMIT ?",
            (max(alert_n + 3, 12),),
        ).fetchall()
        global_streak = 0
        for r in streak_rows:
            if r[0] == "LOSS":
                global_streak += 1
            else:
                break
        if alert_n > 0 and global_streak >= alert_n:
            risk_multiplier = min(risk_multiplier, 0.5)
            flow_score_boost = max(flow_score_boost, 25.0)
            min_conviction_boost = max(min_conviction_boost, 8)
            reasons.append(
                f"global loss streak {global_streak}/{alert_n} → risk ×0.50, conviction +8, flow_score +25"
            )

        con.close()
    except Exception as e:
        print(f"[paper_safety] error computing controls: {e}", file=sys.stderr)

    return {
        "extra_disabled":   extra_disabled,
        "risk_multiplier":  risk_multiplier,
        "flow_score_boost": flow_score_boost,
        "min_conviction_boost": min_conviction_boost,
        "cooldowns":        new_cooldowns,
        "reasons":          reasons,
    }


def _paper_candidate_routing_plan(
    candidates_by_symbol: dict[str, list[dict]],
) -> tuple[dict[str, dict], list[dict]]:
    """Choose the existing highest-conviction winner and expose every loser."""
    winners: dict[str, dict] = {}
    ledger_rows: list[dict] = []
    for symbol, candidates in candidates_by_symbol.items():
        if not candidates:
            continue
        ordered = sorted(
            candidates,
            key=lambda item: -float(
                item.get("conviction", item.get("conviction_base", 0)) or 0
            ),
        )
        winner = ordered[0]
        winners[symbol] = winner
        selected_key = str(winner.get("_strategy_key") or "balanced")
        for candidate in ordered:
            selected = candidate is winner
            ledger_rows.append({
                "symbol": symbol,
                "strategy_key": str(candidate.get("_strategy_key") or "balanced"),
                "direction": candidate.get("direction"),
                "conviction": float(
                    candidate.get("conviction", candidate.get("conviction_base", 0)) or 0
                ),
                "selected": selected,
                "selected_strategy_key": selected_key,
                "decision": (
                    "only_candidate"
                    if len(ordered) == 1
                    else "selected"
                    if selected
                    else "lost_to_higher_conviction"
                ),
                "candidate_count": len(ordered),
            })
    return winners, ledger_rows


def _paper_record_candidate_routing(
    scan_id: str,
    observed_at: str,
    rows: list[dict],
    cfg: dict,
) -> None:
    """Persist pre-dedup routing evidence without changing the routing policy."""
    if not rows:
        return
    try:
        con = sqlite3.connect(DB_PATH)
        for row in rows:
            policy = _learning_policy_snapshot(row["strategy_key"], cfg)
            con.execute(
                """INSERT INTO paper_candidate_routing
                   (scan_id, observed_at, symbol, strategy_key, direction,
                    conviction, selected, selected_strategy_key, decision,
                    candidate_count, policy_fingerprint)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    scan_id,
                    observed_at,
                    row["symbol"],
                    row["strategy_key"],
                    row.get("direction"),
                    row.get("conviction"),
                    1 if row.get("selected") else 0,
                    row.get("selected_strategy_key"),
                    row.get("decision"),
                    row.get("candidate_count"),
                    _learning_fingerprint(policy),
                ),
            )
        cutoff = (datetime.utcnow() - timedelta(days=30)).isoformat()
        con.execute(
            "DELETE FROM paper_candidate_routing WHERE observed_at < ?",
            (cutoff,),
        )
        con.commit()
        con.close()
    except Exception as e:
        print(f"[paper_routing] record error: {e}", file=sys.stderr)


def _paper_update_selected_routing(
    scan_id: str,
    symbol: str,
    *,
    flow_confirmed: bool,
    flow_score: float,
    paper_trade_id: int,
) -> None:
    try:
        con = sqlite3.connect(DB_PATH)
        con.execute(
            """UPDATE paper_candidate_routing
               SET flow_confirmed=?, flow_score=?, paper_trade_id=?
               WHERE scan_id=? AND symbol=? AND selected=1""",
            (
                1 if flow_confirmed else 0,
                float(flow_score or 0.0),
                int(paper_trade_id),
                scan_id,
                symbol,
            ),
        )
        con.commit()
        con.close()
    except Exception as e:
        print(f"[paper_routing] update error: {e}", file=sys.stderr)


def _paper_bot_scan(cfg: dict) -> dict:
    """
    Run one scan cycle for the paper bot across all enabled strategies.
    Fetches tickers once, runs each enabled strategy, deduplicates by symbol
    (highest conviction wins), then checks flow and enters paper positions.
    Returns a summary dict.
    """
    entered = 0
    rejected = 0
    skipped = 0

    try:
        disabled_strategies  = {str(k).strip() for k in (cfg.get("disabled_strategies") or []) if str(k).strip()}
        min_conviction       = int(cfg.get("min_conviction", 55))
        sizing_policy        = _paper_sizing_policy(cfg)
        account_balance      = float(
            sizing_policy.get("effective_sizing_base_usd") or 0.0
        )
        risk_pct             = float(cfg.get("risk_pct_per_trade", 5.0))
        flow_required        = cfg.get("flow_required", True)
        min_flow_score       = float(cfg.get("min_flow_score", 50.0))
        max_open             = int(cfg.get("max_open_positions", 5))
        max_atr_pct          = float(cfg.get("max_atr_pct", 4.0))
        max_trend_score_abs  = int(cfg.get("max_trend_score_abs", 25))

        if not sizing_policy.get("entry_allowed"):
            reason = sizing_policy.get("reason") or "Paper sizing policy blocked new entries."
            print(f"[paper_sizing] BLOCK {reason}", file=sys.stderr)
            return {
                "entered": 0,
                "rejected": 0,
                "skipped": 0,
                "reason": "sizing_policy_block",
                "sizing_policy": sizing_policy,
            }

        # Safety controls: streak pauses, drawdown reduction, cold streak flow boost
        safety = _paper_safety_controls(cfg)
        if safety["cooldowns"] != dict(cfg.get("_strategy_cooldowns") or {}):
            cfg["_strategy_cooldowns"] = safety["cooldowns"]
            _save_paper_config(cfg)
        disabled_strategies |= safety["extra_disabled"]
        risk_pct             = risk_pct * safety["risk_multiplier"]
        min_flow_score       = min_flow_score + safety["flow_score_boost"]
        min_conviction       = min(100, min_conviction + int(safety.get("min_conviction_boost") or 0))
        if safety["reasons"]:
            print(f"[paper_safety] active: {safety['reasons']}", file=sys.stderr)

        # Auto-block new strategies that haven't been seen before
        registry_keys = set(get_strategy_registry().keys())
        known = set(cfg.get("_known_strategies") or [])
        brand_new = registry_keys - known - disabled_strategies - set(cfg.get("disabled_strategies") or [])
        if brand_new:
            for k in sorted(brand_new):
                print(f"[paper_safety] new strategy '{k}' auto-disabled (not previously seen)", file=sys.stderr)
            cfg["disabled_strategies"] = list(set(cfg.get("disabled_strategies") or []) | brand_new)
            cfg["_known_strategies"] = list(known | registry_keys)
            disabled_strategies |= brand_new
            _save_paper_config(cfg)
        elif known != registry_keys:
            cfg["_known_strategies"] = list(known | registry_keys)
            _save_paper_config(cfg)

        # Count current active paper positions. Pending entries reserve a slot
        # because a live system would already have a working limit order.
        con = sqlite3.connect(DB_PATH)
        active_count = con.execute(
            "SELECT COUNT(*) FROM paper_trades WHERE status IN ('pending','open')"
        ).fetchone()[0]
        open_symbols = {
            r[0] for r in con.execute(
                "SELECT symbol FROM paper_trades WHERE status IN ('pending','open')"
            ).fetchall()
        }
        con.close()

        tickers = fetch_mexc("/contract/ticker")
        if not tickers:
            return {"entered": 0, "rejected": 0, "skipped": 0, "reason": "no_tickers"}

        symbol_history_counts = _paper_symbol_history_counts()

        shadow_result = _disabled_strategy_shadow_scan(
            cfg,
            tickers=tickers,
            disabled_strategies=disabled_strategies,
        )

        if active_count >= max_open:
            print(f"[paper_bot] at max open positions ({max_open}), skipping entries", file=sys.stderr)
            return {
                "entered": 0,
                "rejected": 0,
                "skipped": 0,
                "reason": "max_positions",
                "disabled_shadow": shadow_result,
            }

        # Run all active strategies, dedup by symbol keeping highest conviction.
        # Active/inactive state is controlled by paper_config.disabled_strategies.
        registry = get_strategy_registry()
        candidates_by_symbol: dict[str, list[dict]] = defaultdict(list)
        for key in registry:
            if key in disabled_strategies:
                continue
            sigs, _ = run_scan(threshold=min_conviction, strategy_key=key, tickers=tickers)
            for sig in sigs:
                sig["_strategy_key"] = key
                candidates_by_symbol[sig["symbol"]].append(sig)

        best, routing_rows = _paper_candidate_routing_plan(candidates_by_symbol)
        now = datetime.utcnow().isoformat()
        scan_id = hashlib.sha256(
            f"{now}|{len(routing_rows)}|{socket.gethostname()}".encode()
        ).hexdigest()[:20]
        _paper_record_candidate_routing(scan_id, now, routing_rows, cfg)
        # Sort by conviction descending
        signals = sorted(best.values(), key=lambda s: s.get("conviction", s.get("conviction_base", 0)), reverse=True)
        research_paper_controls = _research_rule_controls_by_tag()

        for sig in signals:
            if active_count >= max_open:
                break
            if sig.get("conviction", sig.get("conviction_base", 0)) < min_conviction:
                skipped += 1
                continue
            if sig["symbol"] in open_symbols:
                skipped += 1
                continue
            # Data-driven gates: atr_pct and trend_score outpredict conviction
            # (analyze.py: winners 3.2% / 9.3 vs losers 5.5% / 14.1)
            if sig.get("atr_pct", 0) > max_atr_pct:
                print(f"[paper_bot] SKIP {sig['symbol']} atr_pct={sig.get('atr_pct'):.2f} > {max_atr_pct}", file=sys.stderr)
                skipped += 1
                continue
            if abs(sig.get("trend_score", 0)) > max_trend_score_abs:
                print(f"[paper_bot] SKIP {sig['symbol']} trend_score={sig.get('trend_score')} abs>{max_trend_score_abs}", file=sys.stderr)
                skipped += 1
                continue
            sig["logged_at"] = sig.get("logged_at") or now
            sig["_research_assignments"] = _research_assignments_for_signal(
                sig,
                assigned_at=now,
            )

            flow_result = None
            confirmed   = True
            flow_score  = 0.0
            flow_reasons = []

            flow_assignment = next(
                (
                    item for item in sig["_research_assignments"]
                    if item.get("source_id") == "research_order_flow_confirmation"
                ),
                None,
            )
            flow_challenger = (
                _research_paper_control_active(
                    research_paper_controls,
                    "research_order_flow_confirmation",
                    sig,
                )
                and (
                    not flow_assignment
                    or flow_assignment.get("arm") == "treatment"
                )
            )
            flow_needed = flow_required or flow_challenger
            if flow_needed:
                # Pass min_flow_score through — prior code loaded it from cfg
                # (line ~5938) into a local then never used it, so the value
                # in paper_config.json silently had no effect and every
                # dead-tape altcoin passed the gate at the hardcoded default
                # of 50. Audit §03 finding paper_flow_dead_001.
                flow_result   = _flow_confirm(
                    sig["symbol"],
                    sig["direction"],
                    sig.get("price", 0),
                    min_score=min_flow_score,
                )
                confirmed     = flow_result["confirmed"]
                flow_score    = flow_result["score"]
                flow_reasons  = list(flow_result.get("reasons") or [])

            entries = sig.get("entries") or []
            entry_px  = entries[0] if entries else sig.get("entry1") or sig.get("price", 0)
            leverage  = float(sig.get("leverage_cap") or sig.get("leverage") or 1)
            conviction = sig.get("conviction", sig.get("conviction_base", 0))
            raw_size_usd = compute_paper_position_size(
                account_balance=account_balance,
                risk_pct=risk_pct,
                entry_px=entry_px,
                stop_loss=sig.get("stop_loss"),
                atr_pct=sig.get("atr_pct"),
                conviction=conviction,
            )
            notional_cap = _hard_notional_cap_for_signal(
                account_balance,
                sig,
                symbol_history_count=symbol_history_counts.get(sig["symbol"], 0),
            )
            sizing = _apply_hard_notional_cap(raw_size_usd, notional_cap)
            size_usd = sizing["size_usd"]
            if sizing["notional_cap_applied"]:
                sig["tags"] = list(dict.fromkeys(list(sig.get("tags") or []) + ["paper_notional_capped"]))
                print(
                    f"[paper_sizing] CAP {sig['symbol']} raw=${raw_size_usd:.2f} "
                    f"cap=${sizing['notional_cap_usd']:.2f} tier={sizing['liquidity_tier']} "
                    f"history={sizing['symbol_history_count']} reason={sizing['notional_cap_reason']}",
                    file=sys.stderr,
                )

            # Ladder levels: signals store as exits[] array, not flat tp1/tp2/tp3 keys
            exits = sig.get("exits") or []
            tp1 = exits[0] if len(exits) > 0 else sig.get("tp1")
            tp2 = exits[1] if len(exits) > 1 else sig.get("tp2")
            tp3 = exits[2] if len(exits) > 2 else sig.get("tp3")

            exchange = sig.get("exchange") or "MEXC"
            margin_mode = str(cfg.get("paper_margin_mode") or "isolated").lower()
            liq = _liquidation_summary_for_position(
                exchange=exchange,
                symbol=sig["symbol"],
                direction=sig["direction"],
                entry_px=entry_px,
                leverage=leverage,
                size_usd=size_usd,
                margin_mode=margin_mode,
            )
            if liq.get("success"):
                sig["liquidation"] = liq
                sig["liquidation_price"] = liq.get("liquidation_price")
                sig["liquidation_distance_pct"] = liq.get("distance_pct")

            research_runtime = _apply_research_paper_rules(
                sig,
                cfg,
                flow_result=flow_result,
                liquidation=liq,
                controls_by_tag=research_paper_controls,
            )
            if research_runtime.get("annotations"):
                sig["tags"] = list(dict.fromkeys(list(sig.get("tags") or []) + research_runtime["annotations"]))
            if not research_runtime.get("allowed", True):
                confirmed = False
                for block in research_runtime.get("blocked_by") or []:
                    flow_reasons.append(block.get("reason") or block.get("tag") or "research paper rule blocked")

            status = "pending" if confirmed else "flow_rejected"
            flow_reasons_str = json.dumps(flow_reasons)
            strategy_key = sig.get("_strategy_key", "balanced")
            learning_attribution = _learning_attribution_for_trade(
                strategy_key,
                cfg,
            )
            sig["learning_experiment_id"] = learning_attribution["experiment_id"]
            sig["learning_policy_fingerprint"] = learning_attribution["policy_fingerprint"]
            sig["learning_contract_version"] = LEARNING_CONTRACT_VERSION

            # Log confirmed entries to signals table so they appear in History tab
            signal_id = sig.get("signal_id")
            counterfactual_signal_id = None
            if confirmed:
                sig["strategy_key"]   = strategy_key
                sig["flow_score"]     = flow_score
                sig["flow_confirmed"] = True
                inserted_ids = log_signals([sig], source="paper", allow_duplicate_open=True)
                if inserted_ids and inserted_ids[0]:
                    signal_id = inserted_ids[0]
            elif research_runtime.get("blocked_by"):
                # A research gate must continue following every blocked
                # opportunity.  This preserves the winner-cost counterfactual
                # without opening a Paper position.
                shadow_sig = dict(sig)
                shadow_sig["strategy_key"] = strategy_key
                shadow_sig["flow_score"] = flow_score
                shadow_sig["flow_confirmed"] = bool(
                    (flow_result or {}).get("confirmed")
                )
                shadow_sig["research_counterfactual"] = True
                shadow_sig["research_runtime"] = research_runtime
                shadow_sig["tags"] = list(dict.fromkeys(
                    list(shadow_sig.get("tags") or [])
                    + ["research_counterfactual"]
                    + [
                        str(block.get("tag"))
                        for block in research_runtime.get("blocked_by") or []
                        if block.get("tag")
                    ]
                ))
                inserted_ids = log_signals(
                    [shadow_sig],
                    source="research_counterfactual",
                    allow_duplicate_open=True,
                )
                if inserted_ids and inserted_ids[0]:
                    counterfactual_signal_id = inserted_ids[0]
            elif flow_needed and not confirmed:
                # Preserve the opportunity cost of the global flow gate. These
                # signals remain zero-authority and are outcome-scored exactly
                # like disabled/research shadow candidates.
                shadow_sig = dict(sig)
                shadow_sig["strategy_key"] = strategy_key
                shadow_sig["flow_score"] = flow_score
                shadow_sig["flow_confirmed"] = False
                shadow_sig["flow_counterfactual"] = True
                shadow_sig["tags"] = list(dict.fromkeys(
                    list(shadow_sig.get("tags") or []) + ["flow_counterfactual"]
                ))
                inserted_ids = log_signals(
                    [shadow_sig],
                    source="flow_counterfactual",
                    allow_duplicate_open=False,
                )
                if inserted_ids and inserted_ids[0]:
                    counterfactual_signal_id = inserted_ids[0]

            con = sqlite3.connect(DB_PATH)
            cursor = con.execute(
                """INSERT INTO paper_trades
                   (opened_at, symbol, strategy_key, direction, entry_px, size_usd,
                    tp1, tp2, tp3, stop_loss, leverage, conviction,
                    flow_confirmed, flow_score, flow_reasons, status, signal_id,
                    atr_pct, trend_score, queued_at, filled_at, exchange, margin_mode,
                    liquidation_px, liquidation_distance_pct, liquidation_mmr,
                    liquidation_fee_rate, liquidation_formula, liquidation_tier,
                    raw_size_usd, notional_cap_usd, notional_cap_reason,
                    liquidity_tier, liquidity_risk_score, symbol_history_count,
                    sizing_mode, sizing_base_usd, realized_equity_usd,
                    sizing_risk_pct, sizing_policy_json, learning_experiment_id,
                    learning_policy_fingerprint, learning_policy_json)
                   VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    now,
                    sig["symbol"],
                    sig.get("_strategy_key", "balanced"),
                    sig["direction"],
                    entry_px,
                    size_usd,
                    tp1,
                    tp2,
                    tp3,
                    sig.get("stop_loss"),
                    leverage,
                    conviction,
                    1 if confirmed else 0,
                    flow_score,
                    flow_reasons_str,
                    status,
                    signal_id,
                    sig.get("atr_pct"),
                    sig.get("trend_score"),
                    now,
                    None,
                    exchange,
                    margin_mode,
                    liq.get("liquidation_price") if liq.get("success") else None,
                    liq.get("distance_pct") if liq.get("success") else None,
                    liq.get("maintenance_margin_rate") if liq.get("success") else None,
                    liq.get("liquidation_fee_rate") if liq.get("success") else None,
                    liq.get("formula") if liq.get("success") else None,
                    json.dumps(liq.get("risk_tier"), default=str) if liq.get("success") else None,
                    sizing["raw_size_usd"],
                    sizing["notional_cap_usd"],
                    sizing["notional_cap_reason"],
                    sizing["liquidity_tier"],
                    sig.get("liquidity_risk_score"),
                    sizing["symbol_history_count"],
                    sizing_policy["mode"],
                    sizing_policy["effective_sizing_base_usd"],
                    sizing_policy["realized_equity_usd"],
                    risk_pct,
                    json.dumps(sizing_policy, default=str),
                    learning_attribution["experiment_id"],
                    learning_attribution["policy_fingerprint"],
                    json.dumps(learning_attribution["policy"], sort_keys=True, default=str),
                ),
            )
            paper_trade_id = int(cursor.lastrowid)
            con.commit()
            con.close()
            _paper_update_selected_routing(
                scan_id,
                sig["symbol"],
                flow_confirmed=confirmed,
                flow_score=flow_score,
                paper_trade_id=paper_trade_id,
            )
            assignments = research_runtime.get("experiment_assignments") or []
            decision = "blocked" if research_runtime.get("blocked_by") else "accepted"
            _research_record_assignments(
                assignments,
                paper_trade_id=paper_trade_id,
                signal_id=counterfactual_signal_id or signal_id,
                decision=decision,
                metadata={
                    "blocked_by": research_runtime.get("blocked_by") or [],
                    "flow_required_by_champion": bool(flow_required),
                    "paper_status": status,
                },
            )

            if confirmed:
                entered += 1
                active_count += 1
                open_symbols.add(sig["symbol"])
                print(
                    f"[paper_bot] QUEUED {sig['symbol']} {sig['direction']} "
                    f"entry={entry_px} flow_score={flow_score:.0f}",
                    file=sys.stderr,
                )
            else:
                rejected += 1
                print(
                    f"[paper_bot] REJECTED {sig['symbol']} {sig['direction']} "
                    f"flow_score={flow_score:.0f}",
                    file=sys.stderr,
                )

    except Exception as e:
        print(f"[paper_bot] _paper_bot_scan error: {e}", file=sys.stderr)

    return {
        "entered": entered,
        "rejected": rejected,
        "skipped": skipped,
        "disabled_shadow": locals().get("shadow_result"),
        "routing": {
            "scan_id": locals().get("scan_id"),
            "candidates": len(locals().get("routing_rows") or []),
            "symbols": len(locals().get("best") or {}),
            "overlap_symbols": sum(
                1 for items in (locals().get("candidates_by_symbol") or {}).values()
                if len(items) > 1
            ),
        },
    }


def _disabled_strategy_shadow_scan(
    cfg: dict,
    tickers: list | None = None,
    disabled_strategies: set[str] | None = None,
) -> dict:
    """Collect read-only recovery evidence for paper-disabled strategies."""
    try:
        disabled = set(disabled_strategies or {
            str(k).strip()
            for k in (cfg.get("disabled_strategies") or [])
            if str(k).strip()
        })
        if not disabled:
            return {"shadow_logged": 0, "strategies": 0, "reason": "none_disabled"}
        registry = get_strategy_registry(include_disabled=True)
        disabled = {k for k in disabled if k in registry}
        if not disabled:
            return {"shadow_logged": 0, "strategies": 0, "reason": "no_registry_match"}
        if tickers is None:
            tickers = fetch_mexc("/contract/ticker")
        if not tickers:
            return {"shadow_logged": 0, "strategies": len(disabled), "reason": "no_tickers"}
        min_conviction = int(cfg.get("min_conviction", 55))
        max_per_strategy = int(cfg.get("disabled_shadow_max_per_strategy") or 8)
        total_logged = 0
        per_strategy: dict[str, int] = {}
        for key in sorted(disabled):
            sigs, _ = run_scan(
                threshold=min_conviction,
                strategy_key=key,
                tickers=tickers,
                include_disabled=True,
                enable_agents=False,
            )
            shadow_sigs = []
            for sig in sigs[:max_per_strategy]:
                sig = dict(sig)
                sig["strategy_key"] = key
                sig["shadow_only"] = True
                sig["paper_disabled_shadow"] = True
                sig["source"] = "disabled_shadow"
                tags = list(sig.get("tags") or [])
                for tag in ("disabled_strategy_shadow", f"strategy_shadow_{key}"):
                    if tag not in tags:
                        tags.append(tag)
                sig["tags"] = tags
                shadow_sigs.append(sig)
            inserted = log_signals(shadow_sigs, source="disabled_shadow") if shadow_sigs else []
            logged = len([x for x in inserted if x])
            total_logged += logged
            per_strategy[key] = logged
        if total_logged:
            print(f"[disabled_shadow] logged={total_logged} per_strategy={per_strategy}", file=sys.stderr)
        return {
            "shadow_logged": total_logged,
            "strategies": len(disabled),
            "per_strategy": per_strategy,
        }
    except Exception as e:
        print(f"[disabled_shadow] scan error: {e}", file=sys.stderr)
        return {"shadow_logged": 0, "strategies": 0, "error": str(e)}


def _paper_bot_loop():
    """Background daemon: exits checked every 60s; new entries on configured interval."""
    import time as _time
    _time.sleep(120)  # 2-minute startup delay
    last_scan = 0.0
    while True:
        try:
            cfg = _load_paper_config()
            if cfg.get("enabled"):
                # First promote working limit orders whose entry was actually touched.
                entry_result = _paper_check_entries(cfg)
                if entry_result.get("filled") or entry_result.get("expired"):
                    print(
                        f"[paper_bot] entries — filled={entry_result['filled']} "
                        f"expired={entry_result['expired']}",
                        file=sys.stderr,
                    )

                # Always check exits — positions must close the moment a level is hit
                closed = _paper_check_exits(cfg)
                if closed:
                    print(f"[paper_bot] closed {closed} position(s)", file=sys.stderr)
                expired_open = _paper_expire_stale_open_trades(cfg)
                if expired_open:
                    print(f"[paper_bot] expired {expired_open} stale open position(s)", file=sys.stderr)

                # Only scan for new entries on the configured interval
                scan_interval = int(cfg.get("scan_interval_minutes", 5)) * 60
                if _time.time() - last_scan >= scan_interval:
                    orchestration = _research_reconcile_experiments()
                    scan_result = _paper_bot_scan(cfg)
                    shadow_eval = _evaluate_open_signal_outcomes(
                        source_allow={
                            "disabled_shadow",
                            "research_counterfactual",
                            "flow_counterfactual",
                        },
                        limit=120,
                    )
                    last_scan = _time.time()
                    print(
                        f"[paper_bot] scan done — entered={scan_result['entered']} "
                        f"rejected={scan_result['rejected']} "
                        f"disabled_shadow={((scan_result.get('disabled_shadow') or {}).get('shadow_logged') or 0)} "
                        f"research_prepared={len(orchestration.get('prepared') or [])} "
                        f"research_blocked={len(orchestration.get('errors') or [])} "
                        f"shadow_tagged={shadow_eval.get('tagged') if shadow_eval.get('success') else 'err'}",
                        file=sys.stderr,
                    )
        except Exception as e:
            print(f"[paper_bot] loop error: {e}", file=sys.stderr)
        _time.sleep(60)  # check exits every 60s; new entries gated by scan_interval


