@app.route("/api/paper/trades")
def api_paper_trades():
    """Return all paper trades, optionally filtered by status."""
    try:
        status = request.args.get("status", "")
        con = sqlite3.connect(DB_PATH)
        con.row_factory = sqlite3.Row
        if status:
            rows = con.execute(
                "SELECT * FROM paper_trades WHERE status=? ORDER BY opened_at DESC",
                (status,),
            ).fetchall()
        else:
            rows = con.execute(
                "SELECT * FROM paper_trades ORDER BY opened_at DESC LIMIT 200"
            ).fetchall()
        con.close()
        trades = []
        live_symbols = {
            str(r["symbol"]).upper()
            for r in rows
            if r["status"] in ("open", "pending") and r["symbol"]
        }
        live_prices = {}
        if live_symbols:
            try:
                tickers = fetch_mexc("/contract/ticker") or []
                for ticker in tickers:
                    sym = str(ticker.get("symbol") or "").upper()
                    if sym in live_symbols:
                        px = float(ticker.get("lastPrice") or ticker.get("fairPrice") or 0)
                        if px > 0:
                            live_prices[sym] = px
            except Exception as e:
                print(f"[paper_trades] live price seed failed: {e}", file=sys.stderr)
        for r in rows:
            t = dict(r)
            live_px = live_prices.get(str(t.get("symbol") or "").upper())
            if live_px:
                t["current_px"] = live_px
            pnl = t.get("pnl_pct")
            gross = t.get("gross_pnl_pct")
            fee = float(t.get("fee_cost_pct") or 0.0)
            slip = float(t.get("slippage_cost_pct") or 0.0)
            t["pnl_usd"] = (
                round(_paper_trade_pnl_usd(t), 2)
                if pnl is not None else None
            )
            t["gross_pnl_usd"] = (
                round(_paper_trade_pnl_usd(t, "gross_pnl_pct"), 2)
                if gross is not None else None
            )
            t["cost_usd"] = (
                round(
                    _paper_notional_pnl_usd(
                        t.get("size_usd"),
                        fee + slip,
                        t.get("leverage"),
                    ),
                    2,
                )
                if pnl is not None else None
            )
            if not t.get("liquidation_px") and t.get("entry_px"):
                liq = _liquidation_summary_for_position(
                    exchange=t.get("exchange") or "MEXC",
                    symbol=t.get("symbol"),
                    direction=t.get("direction"),
                    entry_px=t.get("entry_px"),
                    leverage=t.get("leverage") or 1,
                    size_usd=t.get("size_usd") or 100,
                    margin_mode=t.get("margin_mode") or "isolated",
                )
                if liq.get("success"):
                    t["liquidation_px"] = liq.get("liquidation_price")
                    t["liquidation_distance_pct"] = liq.get("distance_pct")
                    t["liquidation_mmr"] = liq.get("maintenance_margin_rate")
                    t["liquidation_formula"] = liq.get("formula")
                    t["liquidation"] = liq
            trades.append(t)
        return jsonify({"success": True, "trades": trades})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/paper/filter-stats")
def api_paper_filter_stats():
    """
    Live winner/loser averages for ATR% and trend_score from closed signals.
    Used to annotate the paper trader config panel with real DB-derived hints.
    Requires at least 10 winners and 10 losers to return meaningful data.
    """
    try:
        con = sqlite3.connect(DB_PATH)
        rows = con.execute(
            "SELECT atr_pct, trend_score, result FROM signals "
            "WHERE result IN ('WIN','LOSS','PARTIAL') "
            "AND atr_pct IS NOT NULL AND trend_score IS NOT NULL"
        ).fetchall()
        con.close()

        winners = [(r[0], abs(r[1])) for r in rows if r[2] in ("WIN", "PARTIAL")]
        losers  = [(r[0], abs(r[1])) for r in rows if r[2] == "LOSS"]

        def _avg(vals):
            return round(sum(vals) / len(vals), 2) if vals else None

        w_atr   = _avg([r[0] for r in winners])
        l_atr   = _avg([r[0] for r in losers])
        w_trend = _avg([r[1] for r in winners])
        l_trend = _avg([r[1] for r in losers])

        return jsonify({
            "success": True,
            "sample": {"winners": len(winners), "losers": len(losers)},
            "atr_pct":     {"winners_avg": w_atr,   "losers_avg": l_atr},
            "trend_score": {"winners_avg": w_trend, "losers_avg": l_trend},
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500


def _disabled_strategy_shadow_payload() -> dict:
    cfg = _load_paper_config()
    disabled = {
        str(k).strip()
        for k in (cfg.get("disabled_strategies") or [])
        if str(k).strip()
    }
    registry = get_strategy_registry(include_disabled=True)
    rows: list[dict] = []
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        cohort_since = str(cfg.get("current_cohort_started_at") or "")
        active_keys = sorted(set(get_strategy_registry().keys()) - disabled)
        active_symbol_rows = [dict(r) for r in con.execute(
            """
            SELECT DISTINCT symbol
            FROM paper_trades
            WHERE strategy_key IN ({})
              AND symbol IS NOT NULL
              AND (?='' OR COALESCE(closed_at, filled_at, opened_at, queued_at, '') >= ?)
            """.format(",".join(["?"] * len(active_keys)) if active_keys else "''"),
            (*active_keys, cohort_since, cohort_since) if active_keys else (cohort_since, cohort_since),
        ).fetchall()]
        active_symbols = {str(r.get("symbol") or "").upper() for r in active_symbol_rows if r.get("symbol")}
        active_closed = [dict(r) for r in con.execute(
            """
            SELECT strategy_key, symbol, result, pnl_pct, closed_at
            FROM paper_trades
            WHERE status='closed'
              AND pnl_pct IS NOT NULL
              AND (?='' OR COALESCE(closed_at, opened_at, queued_at, '') >= ?)
            """,
            (cohort_since, cohort_since),
        ).fetchall()]
        active_pnls = [
            float(r.get("pnl_pct") or 0.0)
            for r in active_closed
            if str(r.get("strategy_key") or "") in set(active_keys)
        ]
        active_avg_pnl = round(sum(active_pnls) / len(active_pnls), 2) if active_pnls else None
        active_wp_rate = None
        if active_pnls:
            wp = len([r for r in active_closed if str(r.get("strategy_key") or "") in set(active_keys) and r.get("result") in {"WIN", "TP3", "PARTIAL"}])
            active_wp_rate = round(wp / len(active_pnls) * 100, 1)

        for key in sorted(disabled):
            strat = registry.get(key) or {"name": key}
            all_rows = [dict(r) for r in con.execute(
                """
                SELECT id, logged_at, entry_at, result_at, symbol, direction,
                       conviction, result, pnl_pct, source, signal_json
                FROM signals
                WHERE strategy_key=?
                  AND source='disabled_shadow'
                ORDER BY logged_at DESC
                LIMIT 500
                """,
                (key,),
            ).fetchall()]
            closed = [r for r in all_rows if r.get("pnl_pct") is not None and r.get("result") in {"WIN", "LOSS", "PARTIAL", "TP3"}]
            open_count = len([r for r in all_rows if not r.get("result")])
            pnls = [float(r.get("pnl_pct") or 0.0) for r in closed]
            wins = len([r for r in closed if r.get("result") in {"WIN", "TP3"}])
            partials = len([r for r in closed if r.get("result") == "PARTIAL"])
            losses = len([r for r in closed if r.get("result") == "LOSS"])
            count = len(closed)
            avg_pnl = round(sum(pnls) / count, 2) if count else None
            total_pnl = round(sum(pnls), 2) if count else 0.0
            wp_rate = round((wins + partials) / count * 100, 1) if count else None
            shadow_symbols = {str(r.get("symbol") or "").upper() for r in all_rows if r.get("symbol")}
            overlap_symbols = sorted(shadow_symbols & active_symbols)
            overlap_pct = round(len(overlap_symbols) / len(shadow_symbols) * 100, 1) if shadow_symbols else 0.0
            portfolio_delta = round(avg_pnl - active_avg_pnl, 2) if avg_pnl is not None and active_avg_pnl is not None else None
            needed = max(0, 20 - count)
            memo_reasons = []
            if count < 20:
                verdict = "collect"
                label = "Collect"
                color = "blue"
                action = "Keep disabled while shadow collects at least 20 closed outcomes."
                memo_reasons.append(f"only {count}/20 closed shadow outcomes")
            elif avg_pnl is not None and avg_pnl > 0 and (wp_rate or 0) >= 50 and total_pnl > 0:
                verdict = "reenable_candidate"
                label = "Re-enable Candidate"
                color = "green"
                action = "Review for a small paper re-enable trial with current filters."
                memo_reasons.append(f"{count} closed shadow outcomes with positive avg P&L")
            elif avg_pnl is not None and (avg_pnl <= 0 or (wp_rate or 0) < 45):
                verdict = "keep_disabled"
                label = "Keep Disabled"
                color = "red"
                action = "Do not re-enable; current filtered shadow outcomes are not profitable."
                if avg_pnl is not None and avg_pnl <= 0:
                    memo_reasons.append(f"avg P&L is {avg_pnl:+.2f}%")
                if wp_rate is not None and wp_rate < 45:
                    memo_reasons.append(f"W+P is {wp_rate:.1f}%")
            else:
                verdict = "review"
                label = "Review"
                color = "amber"
                action = "Evidence is mixed; inspect recent examples before changing config."
                memo_reasons.append("evidence is mixed after sample threshold")
            if portfolio_delta is not None:
                if portfolio_delta > 0:
                    memo_reasons.append(f"shadow EV is {portfolio_delta:+.2f} pts vs active paper cohort")
                else:
                    memo_reasons.append(f"shadow EV trails active paper by {abs(portfolio_delta):.2f} pts")
            if overlap_pct >= 60:
                memo_reasons.append(f"{overlap_pct:.1f}% symbol overlap with active paper strategies")
            elif shadow_symbols:
                memo_reasons.append(f"{overlap_pct:.1f}% symbol overlap with active paper strategies")
            decision_memo = {
                "decision": label,
                "reason": "; ".join(memo_reasons) if memo_reasons else "waiting for disabled-shadow evidence",
                "needed": f"{needed} more closed shadow outcomes" if needed else "sample target reached",
                "risk": (
                    "Do not re-enable until avg P&L > 0, W+P >= 50%, and portfolio overlap is acceptable."
                    if verdict == "collect"
                    else "Paper-only recovery trial still needs monitoring; live trading remains disabled."
                    if verdict == "reenable_candidate"
                    else "Avoid re-enabling until shadow outcomes improve materially."
                    if verdict == "keep_disabled"
                    else "Manual review needed before changing paper config."
                ),
            }
            rows.append({
                "strategy_key": key,
                "strategy_name": strat.get("name") or key,
                "disabled": True,
                "shadow_signals": len(all_rows),
                "open_shadow": open_count,
                "closed_shadow": count,
                "target_closed": 20,
                "wins": wins,
                "partials": partials,
                "losses": losses,
                "avg_pnl_pct": avg_pnl,
                "total_pnl_pct": total_pnl,
                "win_partial_rate": wp_rate,
                "portfolio_delta_pct": portfolio_delta,
                "active_baseline": {
                    "closed": len(active_pnls),
                    "avg_pnl_pct": active_avg_pnl,
                    "win_partial_rate": active_wp_rate,
                    "active_strategies": active_keys,
                },
                "overlap": {
                    "shadow_symbol_count": len(shadow_symbols),
                    "active_symbol_count": len(active_symbols),
                    "overlap_count": len(overlap_symbols),
                    "overlap_pct": overlap_pct,
                    "symbols": overlap_symbols[:12],
                    "portfolio_read": (
                        "high_overlap" if overlap_pct >= 60 else
                        "moderate_overlap" if overlap_pct >= 25 else
                        "diversifying" if shadow_symbols else
                        "insufficient"
                    ),
                },
                "decision_memo": decision_memo,
                "verdict": verdict,
                "label": label,
                "color": color,
                "action": action,
                "last_seen": all_rows[0].get("logged_at") if all_rows else None,
                "recent": all_rows[:6],
            })
        recovery_actions = [
            r for r in _read_experiment_ledger()
            if isinstance(r, dict)
            and r.get("type") == "disabled_strategy_recovery_action"
            and r.get("action") == "reenable_paper_trial"
        ]
        trials = []
        for rec in recovery_actions[-20:]:
            key = str(rec.get("strategy") or "")
            started = str(rec.get("decided_at") or "")
            if not key or not started:
                continue
            trades = [dict(r) for r in con.execute(
                """
                SELECT id, opened_at, closed_at, symbol, direction, status, result, pnl_pct, size_usd
                FROM paper_trades
                WHERE strategy_key=?
                  AND COALESCE(opened_at, queued_at, closed_at, '') >= ?
                ORDER BY COALESCE(closed_at, opened_at, queued_at, '') DESC
                LIMIT 200
                """,
                (key, started),
            ).fetchall()]
            closed_trades = [t for t in trades if t.get("status") == "closed" and t.get("pnl_pct") is not None]
            trial_pnls = [float(t.get("pnl_pct") or 0.0) for t in closed_trades]
            trial_wp = len([t for t in closed_trades if t.get("result") in {"WIN", "TP3", "PARTIAL"}])
            trial_avg = round(sum(trial_pnls) / len(trial_pnls), 2) if trial_pnls else None
            trial_wp_rate = round(trial_wp / len(trial_pnls) * 100, 1) if trial_pnls else None
            if len(trial_pnls) < 10:
                trial_status = "trial_collecting"
                trial_label = "Trial Collecting"
                trial_action = f"Collect {10 - len(trial_pnls)} more closed paper outcomes before judging."
            elif trial_avg is not None and trial_avg > 0 and (trial_wp_rate or 0) >= 50:
                trial_status = "trial_working"
                trial_label = "Trial Working"
                trial_action = "Keep paper trial active; evidence is currently positive."
            else:
                trial_status = "trial_failing"
                trial_label = "Trial Failing"
                trial_action = "Consider disabling again unless recent examples justify continuation."
            trials.append({
                "strategy_key": key,
                "strategy_name": (registry.get(key) or {}).get("name") or key,
                "started_at": started,
                "closed": len(trial_pnls),
                "open_or_pending": len([t for t in trades if t.get("status") in {"open", "pending"}]),
                "target_closed": 10,
                "avg_pnl_pct": trial_avg,
                "total_pnl_pct": round(sum(trial_pnls), 2) if trial_pnls else 0,
                "win_partial_rate": trial_wp_rate,
                "status": trial_status,
                "label": trial_label,
                "action": trial_action,
                "recent": trades[:6],
            })
    finally:
        con.close()
    rows.sort(key=lambda r: (
        {"reenable_candidate": 0, "review": 1, "collect": 2, "keep_disabled": 3}.get(r["verdict"], 4),
        -(r.get("closed_shadow") or 0),
    ))
    summary = {
        "disabled_count": len(disabled),
        "tracked_count": len(rows),
        "reenable_candidate_count": len([r for r in rows if r["verdict"] == "reenable_candidate"]),
        "review_count": len([r for r in rows if r["verdict"] == "review"]),
        "collect_count": len([r for r in rows if r["verdict"] == "collect"]),
        "keep_disabled_count": len([r for r in rows if r["verdict"] == "keep_disabled"]),
        "active_trial_count": len([t for t in trials if t["status"] in {"trial_collecting", "trial_working"}]),
    }
    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "summary": summary,
        "rows": rows,
        "trials": trials,
        "scope": {
            "source": "disabled_shadow",
            "execution_impact": "none",
            "paper_trade_impact": "none",
            "description": "Disabled strategies are scanned and outcome-scored in shadow only; no paper trades are queued.",
        },
    }


@app.route("/api/paper/disabled-strategy-shadow")
def api_paper_disabled_strategy_shadow():
    try:
        return jsonify(_disabled_strategy_shadow_payload())
    except Exception as e:
        print(f"[api/paper/disabled-strategy-shadow] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/paper/disabled-strategy-shadow/<strategy_key>/action", methods=["POST"])
def api_paper_disabled_strategy_shadow_action(strategy_key: str):
    """Manual governance actions for disabled strategy recovery evidence."""
    try:
        key = str(strategy_key or "").strip()
        registry = get_strategy_registry(include_disabled=True)
        if key not in registry:
            return jsonify({"success": False, "error": "strategy not found"}), 404
        body = request.get_json(silent=True) or {}
        action = str(body.get("action") or "").strip().lower()
        reason = str(body.get("reason") or "").strip()[:700]
        if action not in {"collect", "keep_disabled", "reenable_paper_trial"}:
            return jsonify({
                "success": False,
                "error": "action must be collect, keep_disabled, or reenable_paper_trial",
            }), 400

        payload = _disabled_strategy_shadow_payload()
        row = next((r for r in payload.get("rows", []) if r.get("strategy_key") == key), None)
        decided_at = datetime.utcnow().isoformat()
        cfg = _load_paper_config()
        changed_config = False
        if action == "reenable_paper_trial":
            disabled = [str(k).strip() for k in (cfg.get("disabled_strategies") or []) if str(k).strip()]
            cfg["disabled_strategies"] = [k for k in disabled if k != key]
            cfg["current_cohort_started_at"] = decided_at
            cfg["current_cohort_label"] = f"recovery_trial_{key}_{decided_at[:10]}"
            cfg["current_cohort_strategy_keys"] = [key]
            cfg["current_cohort_policy_fingerprints"] = [
                _learning_fingerprint(_learning_policy_snapshot(key, cfg))
            ]
            cfg["current_cohort_assignment_basis"] = "filled_at"
            _save_paper_config(cfg)
            changed_config = True

        _append_experiment_record({
            "id": f"disabled_strategy_recovery_{key}_{decided_at}",
            "type": "disabled_strategy_recovery_action",
            "strategy": key,
            "action": action,
            "reason": reason,
            "decided_at": decided_at,
            "changed_paper_config": changed_config,
            "changed_live_config": False,
            "shadow_summary": row,
        })
        return jsonify({
            "success": True,
            "strategy_key": key,
            "action": action,
            "changed_paper_config": changed_config,
            "config": cfg if changed_config else None,
            "recovery": _disabled_strategy_shadow_payload(),
        })
    except Exception as e:
        print(f"[api/paper/disabled-strategy-shadow/action] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


def _paper_research_runtime_impact_payload(limit: int = 12) -> dict:
    """Summarize paper candidates blocked by active research runtime hooks."""
    rulebook = _research_rulebook_payload()
    active_rules = []
    for item in rulebook.get("items") or []:
        control = item.get("rule_control") or {}
        if control.get("paper_effect") != "active_runtime_hook":
            continue
        active_rules.append({
            "research_shadow_tag": item.get("research_shadow_tag"),
            "title": item.get("title"),
            "mode": control.get("mode"),
            "rule_type": control.get("rule_type"),
            "scope": control.get("scope"),
            "paper_effect": control.get("paper_effect"),
        })

    by_tag: dict[str, dict] = {
        str(rule.get("research_shadow_tag") or ""): {
            **rule,
            "blocked_count": 0,
            "recent": [],
        }
        for rule in active_rules
        if rule.get("research_shadow_tag")
    }

    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        rows = [dict(r) for r in con.execute(
            """
            SELECT logged_at, symbol, exchange, direction, strategy_key, conviction,
                   price, atr_pct, volatility, funding_rate, reason, signal_json
            FROM filtered_candidates
            WHERE gate_key='research_paper_runtime'
            ORDER BY logged_at DESC
            LIMIT 250
            """
        ).fetchall()]
    finally:
        con.close()

    recent_all = []
    for row in rows:
        payload = {}
        try:
            payload = json.loads(row.get("signal_json") or "{}")
        except Exception:
            payload = {}
        runtime = payload.get("research_runtime") if isinstance(payload.get("research_runtime"), dict) else {}
        flow = payload.get("flow_result") if isinstance(payload.get("flow_result"), dict) else {}
        blocked_by = runtime.get("blocked_by") or []
        if not blocked_by:
            blocked_by = [{"tag": "research_paper_runtime", "reason": row.get("reason") or "research runtime blocked"}]
        for block in blocked_by:
            tag = str((block or {}).get("tag") or "research_paper_runtime")
            if tag not in by_tag:
                by_tag[tag] = {
                    "research_shadow_tag": tag,
                    "title": tag.replace("_", " ").title(),
                    "mode": "paper_applied",
                    "rule_type": "entry_gate",
                    "scope": "unknown",
                    "paper_effect": "active_runtime_hook",
                    "blocked_count": 0,
                    "recent": [],
                }
            item = {
                "logged_at": row.get("logged_at"),
                "symbol": row.get("symbol"),
                "exchange": row.get("exchange"),
                "direction": row.get("direction"),
                "strategy_key": row.get("strategy_key"),
                "conviction": row.get("conviction"),
                "price": row.get("price"),
                "atr_pct": row.get("atr_pct"),
                "volatility": row.get("volatility"),
                "funding_rate": row.get("funding_rate"),
                "flow_score": flow.get("score"),
                "flow_confirmed": flow.get("confirmed"),
                "reason": (block or {}).get("reason") or row.get("reason"),
                "tag": tag,
            }
            by_tag[tag]["blocked_count"] += 1
            if len(by_tag[tag]["recent"]) < limit:
                by_tag[tag]["recent"].append(item)
            if len(recent_all) < limit:
                recent_all.append(item)

    rows_out = sorted(
        by_tag.values(),
        key=lambda x: (-int(x.get("blocked_count") or 0), str(x.get("research_shadow_tag") or "")),
    )
    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "summary": {
            "active_runtime_hooks": len(active_rules),
            "blocked_total": sum(int(x.get("blocked_count") or 0) for x in rows_out),
            "tracked_rules": len(rows_out),
        },
        "rules": rows_out,
        "recent": recent_all,
        "scope": {
            "source": "filtered_candidates",
            "gate_key": "research_paper_runtime",
            "paper_trade_impact": "blocks candidates before pending paper entry",
            "live_trade_impact": "none",
        },
    }


@app.route("/api/paper/research-runtime-impact")
def api_paper_research_runtime_impact():
    try:
        return jsonify(_paper_research_runtime_impact_payload())
    except Exception as e:
        print(f"[api/paper/research-runtime-impact] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


def _trade_time(row: dict, keys: tuple[str, ...]) -> datetime | None:
    for key in keys:
        dt = _parse_iso_datetime(row.get(key))
        if dt:
            return dt
    return None


def _trade_pnl_stats(rows: list[dict]) -> dict:
    values = [float(r.get("pnl_pct")) for r in rows if r.get("pnl_pct") is not None]
    wins = [r for r in rows if str(r.get("result") or "").upper() in ("WIN", "TP3")]
    partials = [r for r in rows if str(r.get("result") or "").upper() == "PARTIAL"]
    losses = [r for r in rows if str(r.get("result") or "").upper() == "LOSS"]
    return {
        "count": len(rows),
        "closed_count": len(values),
        "avg_pnl_pct": round(sum(values) / len(values), 2) if values else None,
        "total_pnl_pct": round(sum(values), 2) if values else 0,
        "win_partial_rate": round((len(wins) + len(partials)) / len(rows) * 100, 1) if rows else None,
        "wins": len(wins),
        "partials": len(partials),
        "losses": len(losses),
    }


def _paper_live_divergence_payload(limit: int = 40, window_hours: int = 24) -> dict:
    """Compare History/live-source outcomes against nearby paper-engine trades."""
    window_hours = max(1, min(int(window_hours or 24), 168))
    limit = max(10, min(int(limit or 40), 160))
    since = (datetime.utcnow() - timedelta(days=30)).isoformat()

    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        live_rows = [dict(r) for r in con.execute("""
            SELECT id, logged_at, entry_at, result_at, symbol, exchange, direction,
                   strategy, strategy_key, price, entry1, result, pnl_pct,
                   conviction, flow_confirmed, flow_score
            FROM signals
            WHERE COALESCE(source, 'live')='live'
              AND result IN ('WIN','LOSS','PARTIAL')
              AND pnl_pct IS NOT NULL
              AND COALESCE(result_at, entry_at, logged_at, '') >= ?
            ORDER BY COALESCE(result_at, entry_at, logged_at) DESC
            LIMIT ?
        """, (since, limit)).fetchall()]
        paper_rows = [dict(r) for r in con.execute("""
            SELECT id, opened_at, queued_at, filled_at, closed_at, symbol, exchange,
                   strategy_key, direction, entry_px, status, result, pnl_pct,
                   conviction, flow_confirmed, flow_score, signal_id
            FROM paper_trades
            WHERE status IN ('closed','open','pending')
              AND COALESCE(filled_at, opened_at, queued_at, closed_at, '') >= ?
            ORDER BY COALESCE(closed_at, filled_at, opened_at, queued_at) DESC
            LIMIT 500
        """, (since,)).fetchall()]
    finally:
        con.close()

    for row in live_rows:
        row["_match_time"] = _trade_time(row, ("entry_at", "logged_at", "result_at"))
        row["_strategy_key"] = row.get("strategy_key") or strategy_name_to_key(row.get("strategy") or "")
    for row in paper_rows:
        row["_match_time"] = _trade_time(row, ("filled_at", "opened_at", "queued_at", "closed_at"))

    def _entry_distance(live: dict, paper: dict) -> float | None:
        live_px = live.get("entry1") if live.get("entry1") is not None else live.get("price")
        paper_px = paper.get("entry_px")
        try:
            live_px = float(live_px)
            paper_px = float(paper_px)
            if live_px <= 0 or paper_px <= 0:
                return None
            return abs(live_px - paper_px) / live_px * 100
        except Exception:
            return None

    def _score_candidate(live: dict, paper: dict) -> tuple[float, float | None]:
        lt = live.get("_match_time")
        pt = paper.get("_match_time")
        diff_hours = abs((lt - pt).total_seconds()) / 3600 if lt and pt else None
        score = 0.0
        if live.get("symbol") == paper.get("symbol"):
            score += 100
        if live.get("direction") == paper.get("direction"):
            score += 35
        if live.get("_strategy_key") == paper.get("strategy_key"):
            score += 35
        if diff_hours is not None:
            score += max(0, 24 - min(diff_hours, 24))
        dist = _entry_distance(live, paper)
        if dist is not None:
            score += max(0, 10 - min(dist, 10))
        return score, diff_hours

    def _label_match(live: dict, paper: dict | None, diff_hours: float | None) -> tuple[str, str]:
        if not paper:
            return "manual_extra_trade", "No nearby paper-engine trade found for this History/live outcome."
        if live.get("symbol") != paper.get("symbol"):
            return "manual_extra_trade", "Closest paper trade was a different symbol."
        if live.get("direction") != paper.get("direction"):
            return "direction_mismatch", "Paper engine had the same symbol but opposite direction."
        if live.get("_strategy_key") != paper.get("strategy_key"):
            return "different_strategy", "Same symbol and direction, but History/live used a different strategy."
        if diff_hours is not None and diff_hours > 2:
            return "late_or_offset_entry", "Same engine idea, but History/live timing was more than 2 hours away."
        dist = _entry_distance(live, paper)
        if dist is not None and dist > 1.5:
            return "different_entry", "Same engine idea, but entry prices differed by more than 1.5%."
        live_result = str(live.get("result") or "").upper()
        paper_result = str(paper.get("result") or "").upper()
        if paper.get("status") == "closed" and paper_result and live_result and paper_result != live_result:
            return "different_exit_or_outcome", "Same engine idea, but History/live and paper closed differently."
        return "matched_engine_trade", "History/live outcome matches a nearby paper-engine trade."

    audits = []
    used_paper_ids: set[int] = set()
    window = float(window_hours)
    for live in live_rows:
        candidates = []
        for paper in paper_rows:
            if live.get("symbol") != paper.get("symbol"):
                continue
            score, diff_hours = _score_candidate(live, paper)
            if diff_hours is not None and diff_hours > window:
                continue
            candidates.append((score, diff_hours, paper))
        candidates.sort(key=lambda x: (-x[0], x[1] if x[1] is not None else 9999))
        paper = candidates[0][2] if candidates else None
        diff_hours = candidates[0][1] if candidates else None
        label, reason = _label_match(live, paper, diff_hours)
        if paper:
            used_paper_ids.add(int(paper.get("id") or 0))
        audits.append({
            "label": label,
            "reason": reason,
            "time_delta_hours": round(diff_hours, 2) if diff_hours is not None else None,
            "entry_delta_pct": round(_entry_distance(live, paper), 2) if paper and _entry_distance(live, paper) is not None else None,
            "live": {
                "id": live.get("id"),
                "logged_at": live.get("logged_at"),
                "entry_at": live.get("entry_at"),
                "result_at": live.get("result_at"),
                "symbol": live.get("symbol"),
                "exchange": live.get("exchange"),
                "direction": live.get("direction"),
                "strategy_key": live.get("_strategy_key"),
                "strategy": live.get("strategy"),
                "entry_px": live.get("entry1") if live.get("entry1") is not None else live.get("price"),
                "result": live.get("result"),
                "pnl_pct": live.get("pnl_pct"),
                "conviction": live.get("conviction"),
                "flow_confirmed": live.get("flow_confirmed"),
                "flow_score": live.get("flow_score"),
            },
            "paper": {
                "id": paper.get("id"),
                "opened_at": paper.get("opened_at"),
                "filled_at": paper.get("filled_at"),
                "closed_at": paper.get("closed_at"),
                "symbol": paper.get("symbol"),
                "exchange": paper.get("exchange"),
                "direction": paper.get("direction"),
                "strategy_key": paper.get("strategy_key"),
                "entry_px": paper.get("entry_px"),
                "status": paper.get("status"),
                "result": paper.get("result"),
                "pnl_pct": paper.get("pnl_pct"),
                "conviction": paper.get("conviction"),
                "flow_confirmed": paper.get("flow_confirmed"),
                "flow_score": paper.get("flow_score"),
            } if paper else None,
        })

    skipped = []
    for paper in paper_rows:
        if paper.get("status") != "closed":
            continue
        paper_id = int(paper.get("id") or 0)
        if paper_id in used_paper_ids:
            continue
        skipped.append({
            "id": paper.get("id"),
            "opened_at": paper.get("opened_at"),
            "filled_at": paper.get("filled_at"),
            "closed_at": paper.get("closed_at"),
            "symbol": paper.get("symbol"),
            "exchange": paper.get("exchange"),
            "direction": paper.get("direction"),
            "strategy_key": paper.get("strategy_key"),
            "entry_px": paper.get("entry_px"),
            "result": paper.get("result"),
            "pnl_pct": paper.get("pnl_pct"),
            "conviction": paper.get("conviction"),
            "flow_confirmed": paper.get("flow_confirmed"),
            "flow_score": paper.get("flow_score"),
        })

    by_label: dict[str, list[dict]] = defaultdict(list)
    for audit in audits:
        by_label[audit["label"]].append(audit)

    matched = [a for a in audits if a.get("paper")]
    exact = [a for a in audits if a.get("label") == "matched_engine_trade"]
    manual_extra = [a for a in audits if a.get("label") == "manual_extra_trade"]
    matched_live_rows = [a["live"] for a in matched if a.get("live")]
    matched_paper_rows = [a["paper"] for a in matched if a.get("paper") and a["paper"].get("pnl_pct") is not None]
    label_stats = {
        label: {
            **_trade_pnl_stats([a["live"] for a in rows if a.get("live")]),
            "label": label,
        }
        for label, rows in sorted(by_label.items())
    }
    summary = {
        "live_sample": len(live_rows),
        "paper_sample": len(paper_rows),
        "matched_any": len(matched),
        "matched_engine": len(exact),
        "manual_extra": len(manual_extra),
        "engine_skipped": len(skipped),
        "match_rate_pct": round(len(matched) / len(live_rows) * 100, 1) if live_rows else 0,
        "exact_match_rate_pct": round(len(exact) / len(live_rows) * 100, 1) if live_rows else 0,
        "live_ev": _trade_pnl_stats(live_rows),
        "matched_live_ev": _trade_pnl_stats(matched_live_rows),
        "matched_paper_ev": _trade_pnl_stats(matched_paper_rows),
        "manual_extra_ev": _trade_pnl_stats([a["live"] for a in manual_extra if a.get("live")]),
        "skipped_paper_ev": _trade_pnl_stats(skipped),
        "by_label": label_stats,
    }
    live_ev = summary["matched_live_ev"].get("avg_pnl_pct")
    paper_ev = summary["matched_paper_ev"].get("avg_pnl_pct")
    if live_ev is not None and paper_ev is not None:
        summary["matched_ev_delta_pct"] = round(float(live_ev) - float(paper_ev), 2)
    else:
        summary["matched_ev_delta_pct"] = None

    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "window_hours": window_hours,
        "lookback_days": 30,
        "summary": summary,
        "audits": audits,
        "engine_skipped_recent": skipped[:20],
        "scope": {
            "live_source": "signals where source=live; these are History/live records and may be MT7-generated",
            "paper_source": "paper_trades from the paper strategy engine",
            "behavior": "read-only audit; no scoring, paper, or live trading behavior changes",
        },
    }


def _paper_sizing_integrity_payload(lookback_days: int = 60, con: sqlite3.Connection | None = None) -> dict:
    """Audit whether dollar-weighted outcomes diverge from percent EV because of sizing."""
    lookback_days = max(1, min(int(lookback_days or 60), 365))
    since = (datetime.utcnow() - timedelta(days=lookback_days)).isoformat()
    own_con = con is None
    db = con or sqlite3.connect(DB_PATH)
    db.row_factory = sqlite3.Row
    try:
        cols = {r[1] for r in db.execute("PRAGMA table_info(paper_trades)").fetchall()}
        raw_expr = "raw_size_usd" if "raw_size_usd" in cols else "size_usd"
        cap_expr = "notional_cap_usd" if "notional_cap_usd" in cols else "NULL"
        cap_reason_expr = "notional_cap_reason" if "notional_cap_reason" in cols else "NULL"
        liq_expr = "liquidity_tier" if "liquidity_tier" in cols else "NULL"
        hist_expr = "symbol_history_count" if "symbol_history_count" in cols else "NULL"
        rows = [dict(r) for r in db.execute(f"""
            SELECT id, symbol, strategy_key, direction, result, pnl_pct, size_usd,
                   COALESCE(leverage, 1) AS leverage,
                   {raw_expr} AS raw_size_usd,
                   {cap_expr} AS notional_cap_usd,
                   {cap_reason_expr} AS notional_cap_reason,
                   {liq_expr} AS liquidity_tier,
                   {hist_expr} AS symbol_history_count,
                   COALESCE(closed_at, filled_at, opened_at, queued_at) AS ts
            FROM paper_trades
            WHERE status='closed'
              AND result IN ('WIN','LOSS','PARTIAL','TP3')
              AND pnl_pct IS NOT NULL
              AND COALESCE(closed_at, filled_at, opened_at, queued_at, '') >= ?
            ORDER BY COALESCE(closed_at, filled_at, opened_at, queued_at) DESC
        """, (since,)).fetchall()]
    finally:
        if own_con:
            db.close()

    def _stats(items: list[dict]) -> dict:
        pnls = [float(x.get("pnl_pct") or 0.0) for x in items]
        pnl_usd = [_paper_trade_pnl_usd(x) for x in items]
        wins = [x for x in items if str(x.get("result") or "").upper() in {"WIN", "PARTIAL", "TP3"} and float(x.get("pnl_pct") or 0.0) > 0]
        losses = [x for x in items if str(x.get("result") or "").upper() == "LOSS" or float(x.get("pnl_pct") or 0.0) < 0]
        win_sizes = [float(x.get("size_usd") or 0.0) for x in wins]
        loss_sizes = [float(x.get("size_usd") or 0.0) for x in losses]
        raw_sizes = [float(x.get("raw_size_usd") or x.get("size_usd") or 0.0) for x in items]
        final_sizes = [float(x.get("size_usd") or 0.0) for x in items]
        cap_applied = [
            x for x in items
            if float(x.get("raw_size_usd") or x.get("size_usd") or 0.0) > float(x.get("size_usd") or 0.0) + 0.001
        ]
        avg_win_size = sum(win_sizes) / len(win_sizes) if win_sizes else None
        avg_loss_size = sum(loss_sizes) / len(loss_sizes) if loss_sizes else None
        return {
            "count": len(items),
            "avg_pnl_pct": round(sum(pnls) / len(pnls), 2) if pnls else None,
            "total_pnl_pct": round(sum(pnls), 2) if pnls else 0,
            "avg_pnl_usd": round(sum(pnl_usd) / len(pnl_usd), 2) if pnl_usd else None,
            "total_pnl_usd": round(sum(pnl_usd), 2) if pnl_usd else 0,
            "profit_factor_pct": _profit_factor_from_pnls(pnls),
            "profit_factor_usd": _profit_factor_from_pnls(pnl_usd),
            "avg_size_usd": round(sum(final_sizes) / len(final_sizes), 2) if final_sizes else None,
            "avg_raw_size_usd": round(sum(raw_sizes) / len(raw_sizes), 2) if raw_sizes else None,
            "avg_win_size_usd": round(avg_win_size, 2) if avg_win_size is not None else None,
            "avg_loss_size_usd": round(avg_loss_size, 2) if avg_loss_size is not None else None,
            "loss_to_win_size_ratio": round(avg_loss_size / avg_win_size, 2) if avg_loss_size and avg_win_size else None,
            "cap_applied_count": len(cap_applied),
            "cap_applied_pct": round(len(cap_applied) / len(items) * 100, 1) if items else 0,
        }

    def _breakdown(key: str, limit: int = 10) -> list[dict]:
        buckets: dict[str, list[dict]] = defaultdict(list)
        for row in rows:
            buckets[str(row.get(key) or "unknown")].append(row)
        out = [{"key": k, **_stats(v)} for k, v in buckets.items()]
        return sorted(out, key=lambda x: (-int(x.get("count") or 0), float(x.get("profit_factor_usd") or 0)))[:limit]

    summary = _stats(rows)
    warnings = []
    pct_pf = summary.get("profit_factor_pct")
    usd_pf = summary.get("profit_factor_usd")
    ratio = summary.get("loss_to_win_size_ratio")
    if pct_pf is not None and usd_pf is not None and pct_pf >= 1.0 and usd_pf < 1.0:
        warnings.append("Percent-weighted PF clears 1.0 while dollar-weighted PF fails; losses are likely larger notional than wins.")
    if ratio is not None and ratio > 1.25:
        warnings.append(f"Average losing notional is {ratio:.2f}x average winning notional.")
    if summary.get("cap_applied_count"):
        warnings.append(f"Hard notional caps applied to {summary.get('cap_applied_count')} closed trades in this window.")
    if not warnings:
        warnings.append("No sizing/PF contradiction detected in the selected paper window.")

    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "lookback_days": lookback_days,
        "summary": summary,
        "warnings": warnings,
        "hard_notional_caps": {
            "tier_fractions": HARD_NOTIONAL_CAPS_BY_LIQUIDITY_TIER,
            "low_history_count": HARD_NOTIONAL_CAP_LOW_HISTORY_COUNT,
            "low_history_fraction": HARD_NOTIONAL_CAP_LOW_HISTORY_FRACTION,
            "low_history_deep_fraction": HARD_NOTIONAL_CAP_LOW_HISTORY_DEEP_FRACTION,
            "deep_volume_usd": HARD_NOTIONAL_CAP_DEEP_VOLUME_USD,
            "hardwired": True,
        },
        "by_liquidity_tier": _breakdown("liquidity_tier", limit=8),
        "by_strategy": _breakdown("strategy_key", limit=12),
        "worst_symbols_by_usd": sorted(
            _breakdown("symbol", limit=30),
            key=lambda x: float(x.get("total_pnl_usd") or 0.0),
        )[:10],
        "recent_capped": [
            r for r in rows
            if float(r.get("raw_size_usd") or r.get("size_usd") or 0.0) > float(r.get("size_usd") or 0.0) + 0.001
        ][:20],
        "scope": {
            "source": "paper_trades",
            "behavior": "read-only audit; notional caps are enforced only when new paper trades are queued",
        },
    }


