def _execution_policy_alignment_payload(lookback_days: int = 30) -> dict:
    """Compare broad History/live records to the current paper execution policy."""
    lookback_days = max(1, min(int(lookback_days or 30), 365))
    since = (datetime.utcnow() - timedelta(days=lookback_days)).isoformat()
    cfg = _load_paper_config()
    registry = get_strategy_registry(include_disabled=True)
    disabled = {str(k) for k in (cfg.get("disabled_strategies") or []) if str(k).strip()}
    paper_enabled = sorted([k for k in registry.keys() if k not in disabled])
    paper_enabled_set = set(paper_enabled)

    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        history_rows = [dict(r) for r in con.execute("""
            SELECT id, logged_at, entry_at, result_at, symbol, direction,
                   strategy, strategy_key, result, pnl_pct, conviction,
                   flow_confirmed, flow_score
            FROM signals
            WHERE COALESCE(source, 'live')='live'
              AND result IN ('WIN','LOSS','PARTIAL')
              AND pnl_pct IS NOT NULL
              AND COALESCE(result_at, entry_at, logged_at, '') >= ?
        """, (since,)).fetchall()]
        paper_rows = [dict(r) for r in con.execute("""
            SELECT id, opened_at, filled_at, closed_at, symbol, direction,
                   strategy_key, status, result, pnl_pct, conviction,
                   flow_confirmed, flow_score
            FROM paper_trades
            WHERE status='closed'
              AND result IN ('WIN','LOSS','PARTIAL')
              AND pnl_pct IS NOT NULL
              AND COALESCE(closed_at, filled_at, opened_at, '') >= ?
        """, (since,)).fetchall()]
    finally:
        con.close()

    for row in history_rows:
        row["strategy_key"] = row.get("strategy_key") or strategy_name_to_key(row.get("strategy") or "")

    history_by_strategy: dict[str, list[dict]] = defaultdict(list)
    paper_by_strategy: dict[str, list[dict]] = defaultdict(list)
    for row in history_rows:
        history_by_strategy[row.get("strategy_key") or "unknown"].append(row)
    for row in paper_rows:
        paper_by_strategy[row.get("strategy_key") or "unknown"].append(row)

    history_strategy_set = set(history_by_strategy.keys())
    paper_seen_set = set(paper_by_strategy.keys())
    history_inside_policy = [r for r in history_rows if r.get("strategy_key") in paper_enabled_set]
    history_outside_policy = [r for r in history_rows if r.get("strategy_key") not in paper_enabled_set]
    disabled_seen = sorted(history_strategy_set & disabled)
    history_only = sorted(history_strategy_set - paper_seen_set)
    paper_only = sorted(paper_seen_set - history_strategy_set)
    shared_seen = sorted(history_strategy_set & paper_seen_set)

    strategy_rows = []
    all_keys = sorted(history_strategy_set | paper_seen_set | set(registry.keys()))
    for key in all_keys:
        h_rows = history_by_strategy.get(key, [])
        p_rows = paper_by_strategy.get(key, [])
        in_policy = key in paper_enabled_set
        strategy_rows.append({
            "strategy_key": key,
            "strategy_name": (registry.get(key) or {}).get("name") or key.replace("_", " ").title(),
            "paper_enabled": in_policy,
            "paper_disabled": key in disabled,
            "history": _trade_pnl_stats(h_rows),
            "paper": _trade_pnl_stats(p_rows),
            "present_in_history": bool(h_rows),
            "present_in_paper": bool(p_rows),
            "alignment": (
                "shared_active" if in_policy and h_rows and p_rows else
                "history_outside_policy" if (not in_policy and h_rows) else
                "paper_active_no_history" if (in_policy and p_rows and not h_rows) else
                "history_no_paper_sample" if (in_policy and h_rows and not p_rows) else
                "paper_disabled" if key in disabled else
                "configured_no_recent_sample"
            ),
        })

    history_total = len(history_rows)
    outside_count = len(history_outside_policy)
    outside_pct = round(outside_count / history_total * 100, 1) if history_total else 0
    shared_active_count = len([
        row for row in strategy_rows
        if row.get("alignment") == "shared_active"
    ])
    active_with_history = len([k for k in paper_enabled if history_by_strategy.get(k)])
    active_with_paper = len([k for k in paper_enabled if paper_by_strategy.get(k)])
    overlap_den = len(set(k for k in paper_enabled if history_by_strategy.get(k) or paper_by_strategy.get(k)))
    overlap_pct = round(shared_active_count / overlap_den * 100, 1) if overlap_den else 0

    if history_total == 0 or not paper_rows:
        status = "insufficient_sample"
        color = "blue"
        label = "Collect Sample"
        verdict = "Need both History/live outcomes and closed paper trades before judging comparability."
    elif outside_pct <= 5 and overlap_pct >= 80:
        status = "aligned"
        color = "green"
        label = "Comparable"
        verdict = "History/live and paper are mostly measuring the same active strategy policy."
    elif outside_pct <= 25 and overlap_pct >= 50:
        status = "partial"
        color = "amber"
        label = "Partially Comparable"
        verdict = "There is enough overlap to compare directionally, but strategy policy differences still matter."
    else:
        status = "not_comparable"
        color = "red"
        label = "Not Comparable"
        verdict = "History/live and paper are measuring different strategy populations; use paper as its own policy test."

    notes = []
    if disabled_seen:
        notes.append(f"{len(disabled_seen)} disabled paper strateg{'y' if len(disabled_seen) == 1 else 'ies'} still appear in History/live.")
    if history_only:
        notes.append(f"{len(history_only)} History/live strateg{'y' if len(history_only) == 1 else 'ies'} have no recent closed paper sample.")
    if paper_only:
        notes.append(f"{len(paper_only)} paper strateg{'y' if len(paper_only) == 1 else 'ies'} have no recent History/live sample.")
    if cfg.get("flow_required"):
        notes.append("Paper policy requires flow confirmation; History/live may include records outside that gate.")
    if not notes:
        notes.append("Strategy sets are currently close enough for high-level comparison.")

    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "lookback_days": lookback_days,
        "verdict": {
            "status": status,
            "label": label,
            "color": color,
            "summary": verdict,
            "notes": notes,
        },
        "policy": {
            "paper_enabled": paper_enabled,
            "paper_disabled": sorted(disabled),
            "flow_required": bool(cfg.get("flow_required")),
            "min_conviction": cfg.get("min_conviction"),
            "max_open_positions": cfg.get("max_open_positions"),
            "max_atr_pct": cfg.get("max_atr_pct"),
            "max_trend_score_abs": cfg.get("max_trend_score_abs"),
            "current_cohort_label": cfg.get("current_cohort_label"),
            "current_cohort_started_at": cfg.get("current_cohort_started_at"),
        },
        "summary": {
            "history_count": history_total,
            "paper_count": len(paper_rows),
            "history_inside_policy_count": len(history_inside_policy),
            "history_outside_policy_count": outside_count,
            "history_outside_policy_pct": outside_pct,
            "paper_enabled_count": len(paper_enabled),
            "paper_disabled_count": len(disabled),
            "history_strategy_count": len(history_strategy_set),
            "paper_strategy_count": len(paper_seen_set),
            "shared_strategy_count": len(shared_seen),
            "shared_active_strategy_count": shared_active_count,
            "active_with_history_count": active_with_history,
            "active_with_paper_count": active_with_paper,
            "strategy_overlap_pct": overlap_pct,
            "history_ev": _trade_pnl_stats(history_rows),
            "history_inside_policy_ev": _trade_pnl_stats(history_inside_policy),
            "history_outside_policy_ev": _trade_pnl_stats(history_outside_policy),
            "paper_ev": _trade_pnl_stats(paper_rows),
        },
        "sets": {
            "history_strategies": sorted(history_strategy_set),
            "paper_seen_strategies": sorted(paper_seen_set),
            "shared_seen": shared_seen,
            "history_only": history_only,
            "paper_only": paper_only,
            "disabled_seen_in_history": disabled_seen,
        },
        "strategies": sorted(
            strategy_rows,
            key=lambda r: (
                0 if r.get("alignment") == "history_outside_policy" else 1,
                -int((r.get("history") or {}).get("count") or 0),
                -int((r.get("paper") or {}).get("count") or 0),
                str(r.get("strategy_key") or ""),
            ),
        ),
        "scope": {
            "history_source": "signals where source=live; broad History/live records",
            "paper_source": "paper_trades; current configurable paper execution policy",
            "behavior": "read-only alignment audit; no scoring, paper, or live trading behavior changes",
        },
    }


