def _live_readiness_gate(
    name: str,
    status: str,
    value,
    target: str,
    detail: str,
    blocking: bool = True,
) -> dict:
    color = {
        "pass": "green",
        "wait": "blue",
        "warn": "amber",
        "fail": "red",
        "lock": "blue",
        "info": "gray",
    }.get(status, "gray")
    return {
        "name": name,
        "status": status,
        "color": color,
        "value": value,
        "target": target,
        "detail": detail,
        "blocking": blocking,
    }


def _live_readiness_payload() -> dict:
    """Aggregate the evidence and locks that govern assisted/live progression."""
    goals = _load_goals()
    actuals = _compute_goal_actuals(goals)
    cfg = _load_paper_config()
    alignment = _execution_policy_alignment_payload(lookback_days=30)
    profile_registry = _strategy_profile_registry_payload(lookback_days=30, alignment=alignment)

    scale_trigger = goals.get("scale_up_trigger", {}) or {}
    cohort_target = max(
        PAPER_READINESS_MIN_TRADES,
        int(goals.get("evaluation_window_trades") or 20),
    )
    cohort_wp_floor = PAPER_READINESS_WP_FLOOR_PCT
    cohort_pf_floor = PAPER_READINESS_PF_FLOOR
    max_drawdown_pct = abs(float(goals.get("max_drawdown_pct", 40.0) or 40.0))
    live_ev_threshold = float(scale_trigger.get("ev_threshold_pct", 8.0) or 8.0)
    live_ev_min_trades = int(scale_trigger.get("min_trades", 50) or 50)

    paper_enabled = bool(cfg.get("enabled"))
    cohort_n = int(actuals.get("paper_cohort_sample_n") or 0)
    cohort_wp = actuals.get("paper_cohort_win_partial_rate")
    cohort_pf = actuals.get("paper_cohort_profit_factor")
    cohort_avg = actuals.get("paper_cohort_avg_pnl")
    cohort_avg_usd = actuals.get("paper_cohort_avg_pnl_usd")
    cohort_trimmed = actuals.get("paper_cohort_trimmed_avg_pnl")
    cohort_ex_best_usd = actuals.get(
        "paper_cohort_leave_best_out_total_pnl_usd"
    )
    cohort_drawdown = float(
        actuals.get("paper_cohort_max_drawdown_pct") or 0.0
    )
    cohort_drawdown_limit = float(
        actuals.get("paper_cohort_drawdown_limit_pct")
        or min(max_drawdown_pct, PAPER_READINESS_MAX_COHORT_DRAWDOWN_PCT)
    )
    cohort_rolling = actuals.get("paper_cohort_rolling_windows") or {}
    cohort_rolling_stable = all(
        int((cohort_rolling.get(str(window)) or {}).get("count") or 0)
        >= window
        and float(
            (cohort_rolling.get(str(window)) or {}).get("avg_pnl") or 0
        ) > 0
        and float(
            (cohort_rolling.get(str(window)) or {}).get("avg_pnl_usd") or 0
        ) > 0
        and float(
            (cohort_rolling.get(str(window)) or {}).get("profit_factor") or 0
        ) >= PAPER_READINESS_RECENT_PF_FLOOR
        and float(
            (cohort_rolling.get(str(window)) or {}).get(
                "win_partial_rate"
            ) or 0
        ) >= PAPER_READINESS_RECENT_WP_FLOOR_PCT
        for window in PAPER_READINESS_RECENT_WINDOWS
    )
    drawdown_pct = float(actuals.get("drawdown_pct") or 0.0)
    safety_controls = list(actuals.get("active_safety_controls") or [])
    live_ev = actuals.get("ev_per_trade_pct")
    live_ev_n = int(actuals.get("ev_sample_n") or 0)
    keys_configured = bool(HL_WALLET_ADDRESS.strip() and HL_PRIVATE_KEY.strip())
    cooldown_remaining = 0
    if _KILL_SWITCH_LAST_FIRED_TS:
        cooldown_remaining = max(0, int(_KILL_SWITCH_COOLDOWN_S - (time.time() - _KILL_SWITCH_LAST_FIRED_TS)))

    paper_gates = [
        _live_readiness_gate(
            "Paper bot",
            "pass" if paper_enabled else "wait",
            "running" if paper_enabled else "paused",
            "running",
            "Paper must keep collecting policy evidence before any assisted-live review.",
        ),
        _live_readiness_gate(
            "Current Paper trial sample",
            "pass" if cohort_n >= cohort_target else "wait",
            f"{cohort_n}/{cohort_target}",
            f">= {cohort_target} closed",
            "Closed trades recorded since the current Paper policy trial began.",
        ),
        _live_readiness_gate(
            "Profitable or partial rate",
            "wait" if cohort_n < cohort_target else ("pass" if cohort_wp is not None and float(cohort_wp) >= cohort_wp_floor else "fail"),
            "—" if cohort_wp is None else f"{float(cohort_wp):.1f}%",
            f">= {cohort_wp_floor:.0f}%",
            "Share of current-trial trades that finished as a full or partial profit.",
        ),
        _live_readiness_gate(
            "Average result after costs",
            "wait" if cohort_n < cohort_target else (
                "pass"
                if cohort_avg is not None
                and float(cohort_avg) > 0
                and cohort_avg_usd is not None
                and float(cohort_avg_usd) > 0
                else "fail"
            ),
            (
                "—" if cohort_avg is None
                else f"{float(cohort_avg):+.2f}% / ${float(cohort_avg_usd or 0):+.2f}"
            ),
            "> 0% and > $0",
            "The average result must be positive after simulated fees and slippage in both percentage and dollar terms.",
        ),
        _live_readiness_gate(
            "Paper profit factor",
            "wait" if cohort_n < cohort_target else ("pass" if cohort_pf is not None and float(cohort_pf) >= cohort_pf_floor else "fail"),
            "—" if cohort_pf is None else f"{float(cohort_pf):.2f}",
            f">= {cohort_pf_floor:.2f}",
            "Gross dollars won divided by gross dollars lost in the paper cohort.",
        ),
        _live_readiness_gate(
            "Recent-window consistency",
            "wait" if cohort_n < cohort_target else (
                "pass" if cohort_rolling_stable else "fail"
            ),
            "recent 20 and 50 are stable" if cohort_rolling_stable else "not yet stable",
            "both averages > 0; profit factor >= 1.0; profitable/partial >= 50%",
            "The most recent 20- and 50-trade windows must both remain net-positive instead of relying on older wins.",
        ),
        _live_readiness_gate(
            "Profit without outlier dependence",
            "wait" if cohort_n < cohort_target else (
                "pass"
                if cohort_trimmed is not None
                and float(cohort_trimmed) > 0
                and float(cohort_ex_best_usd or 0) > 0
                else "fail"
            ),
            (
                "—" if cohort_trimmed is None
                else f"trimmed avg {float(cohort_trimmed):+.2f}% / without best ${float(cohort_ex_best_usd or 0):+.2f}"
            ),
            "both > 0",
            "The average after trimming extreme results and total P&L after removing the best winner must both stay positive.",
        ),
        _live_readiness_gate(
            "Current-trial drawdown",
            "wait" if cohort_n < cohort_target else (
                "pass" if cohort_drawdown <= cohort_drawdown_limit else "fail"
            ),
            f"{cohort_drawdown:.1f}%",
            f"<= {cohort_drawdown_limit:.1f}%",
            "Peak-to-trough drawdown measured only within the current Paper trial.",
        ),
        _live_readiness_gate(
            "Whole Paper account drawdown",
            "pass" if drawdown_pct < max_drawdown_pct else "fail",
            f"{drawdown_pct:.1f}%",
            f"< {max_drawdown_pct:.1f}%",
            "Paper equity drawdown must stay inside the configured risk limit.",
        ),
        _live_readiness_gate(
            "Paper risk controls",
            "pass" if not safety_controls else "fail",
            "clear" if not safety_controls else f"{len(safety_controls)} active",
            "clear",
            "; ".join(safety_controls[:3]) if safety_controls else "No active cooldown, drawdown, or cold-streak paper controls.",
        ),
    ]

    daily_loss_status = "pass" if MAX_DAILY_LOSS_USDT > 0 else "warn"
    execution_locks = [
        _live_readiness_gate(
            "Live master gate",
            "lock" if not LIVE_TRADING_ENABLED else "warn",
            "disabled" if not LIVE_TRADING_ENABLED else "enabled",
            "disabled until review",
            "LIVE_TRADING_ENABLED is the hard environment gate. Keep it disabled until assisted-live review is approved.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Hyperliquid keys",
            "pass" if keys_configured else "warn",
            "configured" if keys_configured else "missing",
            "configured for assisted live",
            "Keys are only needed when deliberately testing assisted Hyperliquid execution.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Signal age gate",
            "pass",
            "<= 5m",
            "backend enforced",
            "Order placement refuses stale signals older than 5 minutes.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Kill switch",
            "warn" if cooldown_remaining else "pass",
            f"cooldown {cooldown_remaining}s" if cooldown_remaining else "armed",
            "armed",
            "Kill switch exists and new orders are refused briefly after it fires.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Daily loss gate",
            daily_loss_status,
            f"${MAX_DAILY_LOSS_USDT:.2f}" if MAX_DAILY_LOSS_USDT > 0 else "not set",
            "MAX_DAILY_LOSS_USDT > 0",
            "Execution route fails closed when the configured daily loss limit is reached.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Assisted confirmation",
            "info",
            "manual confirm",
            "required",
            "Current execution UI stages orders for explicit confirmation; no silent live bot is enabled.",
            blocking=False,
        ),
    ]

    alignment_verdict = alignment.get("verdict") or {}
    alignment_summary = alignment.get("summary") or {}
    history_ev_status = (
        "wait" if live_ev_n < live_ev_min_trades else
        "pass" if live_ev is not None and float(live_ev) >= live_ev_threshold else
        "warn"
    )
    context_gates = [
        _live_readiness_gate(
            "Policy comparability",
            "pass" if alignment_verdict.get("status") == "aligned" else "warn" if alignment_verdict.get("status") == "partial" else "info",
            alignment_verdict.get("label") or "Review",
            "context only",
            "History/live is context. The proven Paper policy remains the live blueprint.",
            blocking=False,
        ),
        _live_readiness_gate(
            "History/live EV",
            history_ev_status,
            "—" if live_ev is None else f"{float(live_ev):+.2f}%",
            f">= {live_ev_threshold:.1f}% over {live_ev_min_trades}",
            "Legacy broad History/live signal sample. Useful context, not policy authority.",
            blocking=False,
        ),
        _live_readiness_gate(
            "Outside-paper history",
            "warn" if float(alignment_summary.get("history_outside_policy_pct") or 0.0) > 5 else "pass",
            f"{float(alignment_summary.get('history_outside_policy_pct') or 0.0):.1f}%",
            "<= 5% ideal",
            "How much recent History/live came from strategies not enabled in Paper.",
            blocking=False,
        ),
    ]

    paper_blockers = [
        f"{g['name']}: {g['value']} vs {g['target']}"
        for g in paper_gates
        if g.get("blocking") and g.get("status") in {"wait", "warn", "fail", "lock"}
    ]
    paper_policy_ready = not paper_blockers
    if paper_policy_ready:
        label = "Assisted Review Candidate"
        status = "review_candidate"
        color = "green"
        summary = "Paper policy evidence clears the current gates. The next step is an assisted-live design review, not silent automation."
        next_actions = [
            "Review exact assisted-live rules: exchange, symbols, risk cap, confirmation path, and kill-switch drill.",
            "Keep LIVE_TRADING_ENABLED disabled until the assisted-live checklist is explicitly approved.",
            "Use Paper policy settings as the live blueprint; keep broad History/live as context only.",
        ]
    else:
        label = "Live Locked"
        status = "locked_collect_sample"
        color = "blue"
        summary = "Live automation stays locked while Paper policy evidence is incomplete or blocked."
        next_actions = [
            "Keep the Paper bot running on the current policy until the evidence gates clear.",
            "Resolve any active safety controls before changing risk or enabling live execution.",
            "Use the Paper tab for cohort detail and this Live tab for promotion readiness.",
        ]

    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "verdict": {
            "status": status,
            "label": label,
            "color": color,
            "summary": summary,
            "paper_policy_ready": paper_policy_ready,
            "can_assisted_review": paper_policy_ready,
            "can_auto_trade": False,
            "live_trading_enabled": LIVE_TRADING_ENABLED,
            "paper_blockers": paper_blockers,
        },
        "gates": {
            "paper_policy": paper_gates,
            "execution_locks": execution_locks,
            "context": context_gates,
        },
        "actuals": actuals,
        "policy": {
            "strategy_profile_id": "paper_active",
            "live_blueprint_profile_id": "paper_active",
            "paper_enabled": paper_enabled,
            "current_cohort_label": cfg.get("current_cohort_label"),
            "current_cohort_started_at": cfg.get("current_cohort_started_at"),
            "disabled_strategies": cfg.get("disabled_strategies") or [],
            "min_conviction": cfg.get("min_conviction"),
            "flow_required": bool(cfg.get("flow_required")),
            "risk_pct_per_trade": cfg.get("risk_pct_per_trade"),
            "max_open_positions": cfg.get("max_open_positions"),
            "sizing_policy": _paper_sizing_policy(cfg),
        },
        "execution": {
            "live_trading_enabled": LIVE_TRADING_ENABLED,
            "hyperliquid_keys_configured": keys_configured,
            "max_daily_loss_usdt": MAX_DAILY_LOSS_USDT,
            "kill_switch_cooldown_remaining_seconds": cooldown_remaining,
        },
        "policy_context": {
            "comparability": alignment.get("verdict") or {},
            "summary": alignment.get("summary") or {},
        },
        "strategy_profiles": profile_registry,
        "next_actions": next_actions,
        "scope": {
            "paper_authority": "The current Paper execution policy is the blueprint for assisted live.",
            "history_role": "History/live records are evidence and context, not policy authority.",
            "automation": "No silent live automation is enabled by this route or UI.",
        },
    }


