def _parse_iso_to_epoch(value: str | None) -> int | None:
    if not value:
        return None
    try:
        text = str(value).strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        dt = datetime.fromisoformat(text)
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return int(dt.replace(tzinfo=timezone.utc).timestamp())
    except Exception:
        return None


def _load_edge_factor_report() -> dict:
    try:
        with open(EDGE_LAB_REPORT_PATH, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _edge_template_tp_sl(template: str | None) -> tuple[float | None, float | None]:
    text = str(template or "")
    m = re.search(r"TP(\d+(?:_\d+)?)_SL(\d+(?:_\d+)?)", text)
    if not m:
        return None, None
    try:
        return float(m.group(1).replace("_", ".")), float(m.group(2).replace("_", "."))
    except Exception:
        return None, None


def _edge_cost_assumption_pct() -> float:
    cfg = _load_paper_config()
    taker_bps = max(0.0, float(cfg.get("paper_taker_fee_bps", 2.0) or 2.0))
    slippage_bps = max(0.0, float(cfg.get("paper_slippage_bps", 3.0) or 3.0))
    # Conservative: assume taker both ways plus one slippage allowance.
    return round(((taker_bps * 2.0) + slippage_bps) / 100.0, 4)


def _edge_net_expectancy(row: dict) -> dict:
    if row.get("net_expectancy_pct") is not None:
        return {
            "tp_pct": _edge_template_tp_sl(row.get("template"))[0],
            "sl_pct": _edge_template_tp_sl(row.get("template"))[1],
            "cost_pct": row.get("round_trip_cost_pct"),
            "breakeven_tp_rate": None,
            "net_expectancy_pct": row.get("net_expectancy_pct"),
            "confirmation_net_expectancy_pct": row.get(
                "confirmation_net_expectancy_pct"
            ),
            "post_cost_profitable": float(row.get("net_expectancy_pct") or 0) > 0,
            "note": (
                "Outcome-aware Edge Lab v2 expectancy; ambiguous paths are "
                "separate and horizon exits are marked to market when available."
            ),
        }
    tp_pct, sl_pct = _edge_template_tp_sl(row.get("template"))
    try:
        tp_rate = float(row.get("tp_rate") or 0.0) / 100.0
    except Exception:
        tp_rate = 0.0
    cost_pct = _edge_cost_assumption_pct()
    if tp_pct is None or sl_pct is None or tp_pct <= 0 or sl_pct <= 0:
        return {
            "tp_pct": tp_pct,
            "sl_pct": sl_pct,
            "cost_pct": cost_pct,
            "breakeven_tp_rate": None,
            "net_expectancy_pct": None,
            "post_cost_profitable": None,
            "note": "Template TP/SL could not be parsed; do not use relative edge alone.",
        }
    breakeven = (sl_pct + cost_pct) / (tp_pct + sl_pct)
    expectancy = (tp_rate * tp_pct) - ((1.0 - tp_rate) * sl_pct) - cost_pct
    return {
        "tp_pct": tp_pct,
        "sl_pct": sl_pct,
        "cost_pct": cost_pct,
        "breakeven_tp_rate": round(breakeven * 100.0, 2),
        "net_expectancy_pct": round(expectancy, 4),
        "post_cost_profitable": expectancy > 0,
        "note": "Fee/slippage-adjusted; positive edge_delta is not enough unless net_expectancy_pct > 0.",
    }


def _edge_factor_matches(feature: dict, direction: str, report: dict) -> list[dict]:
    side = "long" if str(direction).upper() == "LONG" else "short"
    groups = report.get("groups") if isinstance(report.get("groups"), dict) else {}
    specs = [
        ("volatility_regime", feature.get("volatility_regime")),
        ("trend_state", feature.get("trend_state")),
        ("compression_state", feature.get("compression_state")),
        ("rsi_decile", feature.get("rsi_decile")),
        ("volume_decile", feature.get("volume_decile")),
        ("atr_decile", feature.get("atr_decile")),
    ]
    if feature.get("volatility_regime") and feature.get("trend_state"):
        specs.append(("regime_x_trend", f"{feature.get('volatility_regime')}_{feature.get('trend_state')}"))

    tag_map = {
        "tag_compressed": "compressed",
        "tag_expanded": "expanded",
        "tag_bullish_trend": "bullish_trend",
        "tag_bearish_trend": "bearish_trend",
        "tag_extreme_vol": "extreme_vol",
        "tag_low_vol": "low_vol",
    }
    for col, label in tag_map.items():
        if feature.get(col):
            specs.append(("tag_presence", label))

    matches = []
    seen = set()
    for group, raw_key in specs:
        if raw_key is None:
            continue
        key = str(raw_key)
        group_payload = groups.get(group) or {}
        if not isinstance(group_payload, dict):
            continue
        for side_key, rows in group_payload.items():
            if not str(side_key).endswith("." + side):
                continue
            if not isinstance(rows, list):
                continue
            for row in rows:
                if str(row.get("group_key")) != key:
                    continue
                stable = (group, side_key, key)
                if stable in seen:
                    continue
                seen.add(stable)
                item = {
                    "group": group,
                    "template": row.get("template"),
                    "side": row.get("side"),
                    "group_key": key,
                    "tp_rate": row.get("tp_rate"),
                    "baseline_rate": row.get("baseline_rate"),
                    "edge_delta": row.get("edge_delta"),
                    "n": row.get("n"),
                    "sample_quality": row.get("sample_quality"),
                    "effective_n": row.get("effective_n"),
                    "ambiguous_pct": row.get("ambiguous_pct"),
                    "net_expectancy_pct": row.get("net_expectancy_pct"),
                    "confirmation_net_expectancy_pct": row.get(
                        "confirmation_net_expectancy_pct"
                    ),
                    "round_trip_cost_pct": row.get("round_trip_cost_pct"),
                    "evidence_tier": row.get("evidence_tier"),
                    "q_value": row.get("q_value"),
                }
                item.update(_edge_net_expectancy(item))
                matches.append(item)
    return sorted(matches, key=lambda r: float(r.get("edge_delta") or -999), reverse=True)


def _edge_alignment_from_matches(matches: list[dict]) -> dict:
    if not matches:
        return {"label": "unmatched", "score": None, "best_edge_delta": None, "best_net_expectancy_pct": None}
    # Tag presence restates regime/trend/compression and is explanatory only;
    # do not count it as an independent confirmation.
    independent = [
        match for match in matches
        if not str(match.get("group") or "").startswith("tag_presence")
    ] or matches
    deltas = [float(m.get("edge_delta") or 0.0) for m in independent]
    best = max(deltas)
    net_values = [
        float(m.get("net_expectancy_pct"))
        for m in independent
        if m.get("net_expectancy_pct") is not None
    ]
    best_net = max(net_values) if net_values else None
    score = round(sum(deltas[: min(4, len(deltas))]) / max(1, min(4, len(deltas))), 2)
    any_post_cost_profitable = any(
        m.get("post_cost_profitable") is True for m in independent
    )
    validated = [
        m for m in independent
        if m.get("evidence_tier") == "validated_candidate"
        and (
            m.get("q_value") is None
            or float(m.get("q_value") or 1.0) <= 0.10
        )
        and float(m.get("confirmation_net_expectancy_pct") or -999) > 0
    ]
    candidates = [
        m for m in independent
        if m.get("evidence_tier") in {
            "validated_candidate", "confirmation_candidate"
        }
    ]
    if validated and any_post_cost_profitable:
        label = "favorable"
    elif candidates and any_post_cost_profitable:
        label = "mild"
    elif best > -1.0:
        label = "neutral"
    else:
        label = "unfavorable"
    return {
        "label": label,
        "score": score,
        "best_edge_delta": round(best, 2),
        "best_net_expectancy_pct": round(best_net, 4) if best_net is not None else None,
        "post_cost_profitable": any_post_cost_profitable,
    }


def _ensure_edge_lab_indexes(con: sqlite3.Connection) -> None:
    """Create the indexes needed by paper cohort attribution, lazily."""
    global _EDGE_LAB_INDEX_READY
    if _EDGE_LAB_INDEX_READY:
        return
    if _edge_table_exists(con, "candle_features"):
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_cf_symbol_timeframe_ts
            ON candle_features (symbol, timeframe, timestamp)
        """)
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_cf_timestamp
            ON candle_features (timestamp)
        """)
    if _edge_table_exists(con, "candle_feature_snapshots"):
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_cfs_symbol_timeframe_ts
            ON candle_feature_snapshots (symbol, exchange, timeframe, timestamp)
        """)
        con.execute("""
            CREATE INDEX IF NOT EXISTS idx_cfs_timestamp
            ON candle_feature_snapshots (timestamp)
        """)
    con.commit()
    _EDGE_LAB_INDEX_READY = True


def _edge_table_exists(con: sqlite3.Connection, table: str) -> bool:
    row = con.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1",
        (table,),
    ).fetchone()
    return bool(row)


def _edge_snapshot_feature(row: sqlite3.Row | dict) -> dict:
    candidate = dict(row)
    try:
        payload = json.loads(candidate.pop("features_json", "") or "{}")
    except Exception:
        payload = {}
    tags = set(payload.get("tags") or []) if isinstance(payload.get("tags"), list) else set()
    candidate.update({
        "volatility_regime": payload.get("volatility_regime"),
        "trend_state": payload.get("trend_state"),
        "compression_state": payload.get("compression_state"),
        "rsi_decile": payload.get("rsi_15m_decile"),
        "volume_decile": payload.get("volume_decile"),
        "atr_decile": payload.get("atr_pct_15m_decile"),
        "stddev_decile": payload.get("stddev_decile"),
        "tag_compressed": int("compressed" in tags),
        "tag_expanded": int("expanded" in tags),
        "tag_bullish_trend": int("bullish_trend" in tags),
        "tag_bearish_trend": int("bearish_trend" in tags),
        "tag_extreme_vol": int("extreme_vol" in tags),
        "tag_low_vol": int("low_vol" in tags),
    })
    return candidate


def _edge_feature_candidate(
    con: sqlite3.Connection,
    symbol: str,
    trade_ts: int,
) -> tuple[dict | None, str | None, bool]:
    """Return the latest leakage-safe feature state known before a trade."""
    symbol = str(symbol or "").upper()
    # Min15 timestamps identify the candle start. Only use candles that had
    # fully closed before entry; otherwise a later backfill would leak the
    # remainder of the entry candle into its attribution.
    completed_before_ts = trade_ts - (15 * 60)
    symbol_seen = False
    if _edge_table_exists(con, "candle_feature_snapshots"):
        row = con.execute("""
            SELECT symbol, timeframe, timestamp, features_json
            FROM candle_feature_snapshots
            WHERE symbol=? AND exchange='MEXC' AND timeframe='Min15' AND timestamp <= ?
            ORDER BY timestamp DESC
            LIMIT 1
        """, (symbol, completed_before_ts)).fetchone()
        if row:
            return _edge_snapshot_feature(row), "candle_feature_snapshots", True
        symbol_seen = bool(con.execute("""
            SELECT 1 FROM candle_feature_snapshots
            WHERE symbol=? AND exchange='MEXC' AND timeframe='Min15'
            LIMIT 1
        """, (symbol,)).fetchone())

    # Backward-compatible fallback while an existing Edge Lab database is
    # being upgraded and snapshot coverage is still being backfilled.
    if _edge_table_exists(con, "candle_features"):
        row = con.execute("""
            SELECT symbol, timeframe, timestamp, volatility_regime, trend_state,
                   compression_state, rsi_decile, volume_decile, atr_decile,
                   stddev_decile, tag_compressed, tag_expanded, tag_bullish_trend,
                   tag_bearish_trend, tag_extreme_vol, tag_low_vol
            FROM candle_features
            WHERE symbol=? AND timeframe='Min15' AND timestamp <= ?
            ORDER BY timestamp DESC
            LIMIT 1
        """, (symbol, completed_before_ts)).fetchone()
        if row:
            return dict(row), "candle_features", True
        if not symbol_seen:
            symbol_seen = bool(con.execute("""
                SELECT 1 FROM candle_features
                WHERE symbol=? AND timeframe='Min15'
                LIMIT 1
            """, (symbol,)).fetchone())
    return None, None, symbol_seen


def _edge_feature_match(
    con: sqlite3.Connection,
    symbol: str,
    trade_ts: int | None,
    max_age_seconds: int,
) -> dict:
    if trade_ts is None:
        return {
            "matched": False,
            "coverage_reason": "invalid_trade_timestamp",
            "feature": None,
            "feature_source": None,
            "age_seconds": None,
        }
    candidate, source, symbol_seen = _edge_feature_candidate(con, symbol, trade_ts)
    if not candidate:
        return {
            "matched": False,
            "coverage_reason": "no_feature_before_trade" if symbol_seen else "symbol_not_ingested",
            "feature": None,
            "feature_source": None,
            "age_seconds": None,
        }
    candle_close_ts = int(candidate.get("timestamp") or 0) + (15 * 60)
    age_seconds = int(trade_ts - candle_close_ts)
    matched = 0 <= age_seconds <= max_age_seconds
    return {
        "matched": matched,
        "coverage_reason": (
            "matched_snapshot" if matched and source == "candle_feature_snapshots"
            else "matched_labeled_feature" if matched
            else "feature_after_trade" if age_seconds < 0
            else "stale_feature"
        ),
        "feature": candidate if matched else None,
        "feature_source": source,
        "age_seconds": age_seconds,
    }


@app.route("/api/paper/cohort-edge")
def api_paper_cohort_edge():
    """Attribute paper cohort trades to Edge Lab factor states.

    This is research-only. It never changes paper config or scoring.
    """
    try:
        cfg = _load_paper_config()
        cohort_scope = _paper_cohort_scope(cfg)
        since = request.args.get("since") or cohort_scope.get("started_at")
        if request.args.get("since"):
            cohort_scope = {**cohort_scope, "started_at": str(since)}
        if not since:
            return jsonify({"success": False, "error": "No cohort start configured"}), 400

        since_ts = _parse_iso_to_epoch(since)
        if since_ts is None:
            return jsonify({"success": False, "error": "Invalid since timestamp"}), 400

        if not os.path.exists(EDGE_LAB_DB_PATH):
            return jsonify({"success": False, "error": "edge_lab.db not found"}), 404

        report = _load_edge_factor_report()
        report_meta = report.get("meta") if isinstance(report.get("meta"), dict) else {}

        sig_con = sqlite3.connect(DB_PATH)
        sig_con.row_factory = sqlite3.Row
        candidates = [dict(r) for r in sig_con.execute("""
            SELECT id, symbol, strategy_key, direction, status, result, pnl_pct,
                   size_usd, leverage, queued_at, filled_at, opened_at, closed_at,
                   learning_policy_fingerprint
            FROM paper_trades
            WHERE status IN ('closed', 'open', 'pending')
            ORDER BY COALESCE(closed_at, opened_at, queued_at) DESC
            LIMIT 1000
        """).fetchall()]
        rows = [
            row for row in candidates
            if _paper_trade_in_cohort(row, cohort_scope)
        ][:200]
        sig_con.close()

        edge_con = sqlite3.connect(EDGE_LAB_DB_PATH)
        edge_con.row_factory = sqlite3.Row
        _ensure_edge_lab_indexes(edge_con)
        label_max_ts = None
        snapshot_max_ts = None
        if _edge_table_exists(edge_con, "candle_features"):
            max_ts_row = edge_con.execute("SELECT MAX(timestamp) FROM candle_features").fetchone()
            label_max_ts = int(max_ts_row[0]) if max_ts_row and max_ts_row[0] is not None else None
        if _edge_table_exists(edge_con, "candle_feature_snapshots"):
            max_ts_row = edge_con.execute("SELECT MAX(timestamp) FROM candle_feature_snapshots").fetchone()
            snapshot_max_ts = int(max_ts_row[0]) if max_ts_row and max_ts_row[0] is not None else None
        edge_max_ts = snapshot_max_ts or label_max_ts

        attributed = []
        max_age_seconds = int(request.args.get("max_age_minutes") or 30) * 60
        for trade in rows:
            trade_ts = _parse_iso_to_epoch(
                trade.get("filled_at") or trade.get("opened_at") or trade.get("queued_at") or trade.get("closed_at")
            )
            edge_match = _edge_feature_match(
                edge_con,
                str(trade.get("symbol") or "").upper(),
                trade_ts,
                max_age_seconds,
            )
            feature = edge_match["feature"]
            age_seconds = edge_match["age_seconds"]

            matches = _edge_factor_matches(feature or {}, trade.get("direction"), report) if feature else []
            alignment = _edge_alignment_from_matches(matches)
            pnl = trade.get("pnl_pct")
            attributed.append({
                **trade,
                "edge_lab": {
                    "matched": edge_match["matched"],
                    "coverage_reason": edge_match["coverage_reason"],
                    "feature_source": edge_match["feature_source"],
                    "age_minutes": round(age_seconds / 60, 1) if age_seconds is not None else None,
                    "feature": feature,
                    "alignment": alignment,
                    "top_matches": matches[:5],
                },
                "pnl_usd": round(_paper_trade_pnl_usd(trade), 2)
                if pnl is not None else None,
            })
        edge_con.close()

        closed = [t for t in attributed if t.get("status") == "closed"]

        def _bucket_stats(items: list[dict]) -> dict:
            pnls = [float(t.get("pnl_pct") or 0.0) for t in items if t.get("pnl_pct") is not None]
            wins = [t for t in items if t.get("result") == "WIN"]
            partials = [t for t in items if t.get("result") == "PARTIAL"]
            losses = [t for t in items if t.get("result") == "LOSS"]
            return {
                "count": len(items),
                "closed": len([t for t in items if t.get("status") == "closed"]),
                "win_partial_rate": round((len(wins) + len(partials)) / len(items) * 100, 1) if items else 0,
                "avg_pnl": round(sum(pnls) / len(pnls), 2) if pnls else 0,
                "total_pnl": round(sum(pnls), 2) if pnls else 0,
                "wins": len(wins),
                "partials": len(partials),
                "losses": len(losses),
            }

        by_alignment = defaultdict(list)
        by_strategy = defaultdict(list)
        by_factor = defaultdict(list)
        for t in closed:
            edge = t.get("edge_lab") or {}
            label = ((edge.get("alignment") or {}).get("label")) or "unmatched"
            by_alignment[label].append(t)
            by_strategy[t.get("strategy_key") or "unknown"].append(t)
            for match in (edge.get("top_matches") or [])[:3]:
                if match.get("edge_delta") is not None and float(match.get("edge_delta") or 0) > 0:
                    by_factor[f"{match.get('group')}:{match.get('group_key')}"].append(t)

        matched_closed = [
            t for t in closed if (t.get("edge_lab") or {}).get("matched")
        ]
        matched_all = [
            t for t in attributed if (t.get("edge_lab") or {}).get("matched")
        ]
        coverage_reasons = defaultdict(int)
        unmatched_symbols = defaultdict(lambda: {"count": 0, "reasons": defaultdict(int)})
        for trade in closed:
            edge = trade.get("edge_lab") or {}
            reason = edge.get("coverage_reason") or "unknown"
            coverage_reasons[reason] += 1
            if not edge.get("matched"):
                symbol = str(trade.get("symbol") or "unknown").upper()
                unmatched_symbols[symbol]["count"] += 1
                unmatched_symbols[symbol]["reasons"][reason] += 1
        summary = {
            "total_trades": len(attributed),
            "closed_trades": len(closed),
            "open_or_pending_trades": len(attributed) - len(closed),
            "matched_all_trades": len(matched_all),
            "matched_trades": len(matched_closed),
            "coverage_pct": (
                round(len(matched_closed) / len(closed) * 100, 1)
                if closed
                else None
            ),
            "coverage_basis": "closed_current_trial_trades",
            "coverage_reasons": dict(sorted(coverage_reasons.items())),
            "unmatched_symbols": [
                {
                    "symbol": symbol,
                    "count": payload["count"],
                    "reasons": dict(sorted(payload["reasons"].items())),
                }
                for symbol, payload in sorted(
                    unmatched_symbols.items(),
                    key=lambda item: (-item[1]["count"], item[0]),
                )
            ],
            "by_alignment": {k: _bucket_stats(v) for k, v in sorted(by_alignment.items())},
            "by_strategy": {k: _bucket_stats(v) for k, v in sorted(by_strategy.items())},
            "top_positive_factors": [
                {"factor": k, **_bucket_stats(v)}
                for k, v in sorted(by_factor.items(), key=lambda kv: len(kv[1]), reverse=True)[:8]
            ],
        }

        return jsonify({
            "success": True,
            "cohort": {
                "label": cfg.get("current_cohort_label") or "Current cohort",
                "started_at": since,
                "scope": cohort_scope,
                "active_strategies": sorted(set(get_strategy_registry().keys()) - set(cfg.get("disabled_strategies") or [])),
            },
            "edge_lab": {
                "db_path": EDGE_LAB_DB_PATH,
                "report_path": EDGE_LAB_REPORT_PATH,
                "max_timestamp": edge_max_ts,
                "max_timestamp_iso": datetime.utcfromtimestamp(edge_max_ts).isoformat() if edge_max_ts else None,
                "feature_snapshot_max_timestamp": snapshot_max_ts,
                "feature_snapshot_max_timestamp_iso": datetime.utcfromtimestamp(snapshot_max_ts).isoformat() if snapshot_max_ts else None,
                "labeled_outcome_max_timestamp": label_max_ts,
                "labeled_outcome_max_timestamp_iso": datetime.utcfromtimestamp(label_max_ts).isoformat() if label_max_ts else None,
                "feature_source": "candle_feature_snapshots" if snapshot_max_ts else "candle_features",
                "feature_outcome_separation": bool(snapshot_max_ts),
                "report_meta": report_meta,
                "max_match_age_minutes": max_age_seconds // 60,
            },
            "summary": summary,
            "trades": attributed[:80],
        })
    except Exception as e:
        print(f"[api/paper/cohort-edge] {e}", file=sys.stderr)
        return jsonify({"success": False, "error": str(e)}), 500


def _paper_review_stats(
    trades: list[dict],
    starting_balance: float = 200.0,
) -> dict:
    return _paper_evidence_stats(trades, starting_balance)


def _paper_review_breakdown(
    trades: list[dict],
    key: str,
    limit: int = 8,
    starting_balance: float = 200.0,
) -> list[dict]:
    buckets = defaultdict(list)
    for trade in trades:
        buckets[trade.get(key) or "unknown"].append(trade)
    rows = []
    for bucket_key, items in buckets.items():
        rows.append({
            "key": bucket_key,
            **_paper_review_stats(items, starting_balance),
        })
    return sorted(rows, key=lambda r: (r.get("count", 0), r.get("total_pnl_usd", 0)), reverse=True)[:limit]


def _paper_cohort_gate(
    name: str,
    status: str,
    value,
    target: str,
    detail: str,
    blocking: bool = True,
) -> dict:
    return {
        "name": name,
        "status": status,
        "value": value,
        "target": target,
        "detail": detail,
        "blocking": blocking,
    }


def _build_paper_cohort_review() -> dict:
    cfg = _load_paper_config()
    goals = _load_goals()
    cohort_scope = _paper_cohort_scope(cfg)
    since = cohort_scope.get("started_at")
    configured_target = int(cfg.get("current_cohort_target_count") or 20)
    target = max(
        PAPER_READINESS_MIN_TRADES,
        configured_target,
        int(goals.get("evaluation_window_trades") or 20),
    )
    starting_balance = float(
        cfg.get("account_balance_usd")
        or goals.get("account_balance_usd")
        or 200.0
    )
    drawdown_limit = min(
        abs(float(goals.get("max_drawdown_pct") or 40.0)),
        PAPER_READINESS_MAX_COHORT_DRAWDOWN_PCT,
    )
    active_strategies = sorted(set(get_strategy_registry().keys()) - set(cfg.get("disabled_strategies") or []))
    research = _hermes_research_pipeline_summary()

    if not since:
        return {
            "label": cfg.get("current_cohort_label") or "Current cohort",
            "started_at": None,
            "target_count": target,
            "configured_target_count": configured_target,
            "active_strategies": active_strategies,
            "decision": "configure_cohort",
            "decision_label": "Configure Cohort",
            "decision_color": "amber",
            "summary": "No current paper cohort start is configured, so MT7 cannot isolate this test from older paper trades.",
            "recommendation": "Set a cohort start timestamp before judging paper changes.",
            "gates": [_paper_cohort_gate("Closed trades collected", "watch", f"0/{target}", f"{target} closed", "Set a current-trial start time before collecting this sample.")],
            "cohort": _paper_review_stats([], starting_balance),
            "baseline": _paper_review_stats([], starting_balance),
            "strategy_breakdown": [],
            "direction_breakdown": [],
            "hermes": {
                "source_count": ((research.get("library") or {}).get("source_count") or 0),
                "shadow_experiment_count": research.get("shadow_experiment_count") or 0,
                "latest_research_memo_at": ((research.get("research_memo") or {}).get("generated_at")),
            },
        }

    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    try:
        rows = [dict(r) for r in con.execute("""
            SELECT id, symbol, strategy_key, direction, status, result, pnl_pct,
                   size_usd, leverage, queued_at, filled_at, opened_at, closed_at,
                   fee_cost_pct, slippage_cost_pct, flow_confirmed, flow_score,
                   learning_policy_fingerprint
            FROM paper_trades
            WHERE status='closed'
            ORDER BY closed_at ASC
        """).fetchall()]
        active_rows = [dict(r) for r in con.execute("""
            SELECT strategy_key, queued_at, filled_at, opened_at,
                   learning_policy_fingerprint
            FROM paper_trades
            WHERE status IN ('pending','open')
        """).fetchall()]
        open_count = sum(
            1 for trade in active_rows
            if _paper_trade_in_cohort(trade, cohort_scope)
        )
    finally:
        con.close()

    cohort = [t for t in rows if _paper_trade_in_cohort(t, cohort_scope)]
    baseline = [
        t for t in rows
        if (
            not cohort_scope.get("strategy_keys")
            or t.get("strategy_key") in set(cohort_scope.get("strategy_keys") or [])
        )
        and not _paper_trade_in_cohort(t, cohort_scope)
    ]
    cohort_stats = _paper_review_stats(cohort, starting_balance)
    baseline_stats = _paper_review_stats(baseline, starting_balance)

    count = int(cohort_stats.get("count") or 0)
    wp = float(cohort_stats.get("win_partial_rate") or 0.0)
    avg = float(cohort_stats.get("avg_pnl") or 0.0)
    pf = float(cohort_stats.get("profit_factor") or 0.0)
    avg_usd = float(cohort_stats.get("avg_pnl_usd") or 0.0)
    baseline_avg = float(baseline_stats.get("avg_pnl") or 0.0)
    baseline_wp = float(baseline_stats.get("win_partial_rate") or 0.0)
    trimmed_avg = float(cohort_stats.get("trimmed_avg_pnl") or 0.0)
    leave_best_usd = float(
        cohort_stats.get("leave_best_out_total_pnl_usd") or 0.0
    )
    cohort_drawdown = float(cohort_stats.get("max_drawdown_pct") or 0.0)
    rolling = cohort_stats.get("rolling_windows") or {}
    rolling_stable = all(
        int((rolling.get(str(window)) or {}).get("count") or 0) >= window
        and float((rolling.get(str(window)) or {}).get("avg_pnl") or 0) > 0
        and float((rolling.get(str(window)) or {}).get("avg_pnl_usd") or 0) > 0
        and float((rolling.get(str(window)) or {}).get("profit_factor") or 0)
        >= PAPER_READINESS_RECENT_PF_FLOOR
        and float(
            (rolling.get(str(window)) or {}).get("win_partial_rate") or 0
        ) >= PAPER_READINESS_RECENT_WP_FLOOR_PCT
        for window in PAPER_READINESS_RECENT_WINDOWS
    )
    sample_ready = count >= target

    gates = [
        _paper_cohort_gate(
            "Closed trades collected",
            "pass" if sample_ready else ("watch" if count >= max(10, target // 2) else "wait"),
            f"{count}/{target}",
            f"{target} closed",
            "Assisted-live review requires at least 50 isolated closed trades, even if the configured experiment target is smaller.",
        ),
        _paper_cohort_gate(
            "Profitable or partial rate",
            "wait" if not sample_ready else (
                "pass" if wp >= PAPER_READINESS_WP_FLOOR_PCT else "fail"
            ),
            f"{wp:.1f}%",
            f">= {PAPER_READINESS_WP_FLOOR_PCT:.0f}%",
            "Wins plus partial wins must clear the reliability floor on the full isolated cohort.",
        ),
        _paper_cohort_gate(
            "Average result after costs",
            "wait" if not sample_ready else (
                "pass" if avg > 0 and avg_usd > 0 else "fail"
            ),
            f"{avg:+.2f}% / ${avg_usd:+.2f}",
            "> 0% and > $0",
            "Average Paper result must be positive in both percentage and actual position-size dollars after fees and slippage.",
        ),
        _paper_cohort_gate(
            "Profit Factor",
            "wait" if not sample_ready else (
                "pass" if pf >= PAPER_READINESS_PF_FLOOR else "fail"
            ),
            f"{pf:.2f}",
            f">= {PAPER_READINESS_PF_FLOOR:.2f}",
            "Gross dollars won divided by gross dollars lost.",
        ),
        _paper_cohort_gate(
            "Recent-window consistency",
            "wait" if not sample_ready else (
                "pass" if rolling_stable else "fail"
            ),
            " / ".join(
                f"{window}: {float((rolling.get(str(window)) or {}).get('avg_pnl') or 0):+.2f}%"
                for window in PAPER_READINESS_RECENT_WINDOWS
            ),
            "both averages > 0; profit factor >= 1.0; profitable/partial >= 50%",
            "Both recent windows must remain net-positive so an older winning regime cannot hide current decay.",
        ),
        _paper_cohort_gate(
            "Profit without outlier dependence",
            "wait" if not sample_ready else (
                "pass" if trimmed_avg > 0 and leave_best_usd > 0 else "fail"
            ),
            f"trimmed avg {trimmed_avg:+.2f}% / without best ${leave_best_usd:+.2f}",
            "both > 0",
            "The 10% trimmed mean and total P&L after removing the single best dollar winner must both remain positive.",
        ),
        _paper_cohort_gate(
            "Current-trial drawdown",
            "wait" if not sample_ready else (
                "pass" if cohort_drawdown <= drawdown_limit else "fail"
            ),
            f"{cohort_drawdown:.1f}%",
            f"<= {drawdown_limit:.1f}%",
            "Peak-to-trough drawdown is calculated only inside the isolated cohort using actual paper position sizes.",
        ),
        _paper_cohort_gate(
            "Change from earlier trades",
            "pass" if avg > baseline_avg and wp >= baseline_wp else "watch",
            f"{avg - baseline_avg:+.2f}% average / {wp - baseline_wp:+.1f} points profitable-or-partial",
            "informational",
            "The older mixed-policy sample is useful context but cannot authorize or block the current policy.",
            blocking=False,
        ),
    ]
    blocking_failures = [
        gate for gate in gates
        if gate.get("blocking") and gate.get("status") != "pass"
    ]
    evidence_ready = sample_ready and not blocking_failures

    if not sample_ready:
        decision = "hold_collect_sample"
        label = "Hold: Collect Sample"
        color = "blue"
        summary = f"{count}/{target} closed trades are in the current cohort. MT7 should keep observing before changing paper settings."
        recommendation = "Keep the paper bot unchanged until the cohort reaches the sample gate."
    elif evidence_ready:
        decision = "ready_next_test"
        label = "Ready For Next Test"
        color = "green"
        summary = "The cohort clears sample, net EV, reliability, rolling stability, outlier-resilience, and cohort-drawdown gates."
        recommendation = "This is eligible for an assisted-live design review only; live trading remains disabled until the separate execution checklist is explicitly approved."
    elif (
        avg <= 0
        or pf < 1.0
        or not rolling_stable
        or cohort_drawdown > drawdown_limit
    ):
        decision = "tighten_or_pause"
        label = "Tighten Or Pause"
        color = "red"
        summary = "The cohort has enough sample but paper EV or profit factor is not holding up."
        recommendation = "Inspect the worst strategy/symbol buckets before allowing another configuration change."
    else:
        decision = "hold_review"
        label = "Hold: Review"
        color = "amber"
        summary = "The cohort is mixed: enough sample to study, but not enough evidence to promote automation."
        recommendation = "Use strategy split, Edge Lab attribution, and Hermes research before applying a paper config change."

    edge_available = os.path.exists(EDGE_LAB_DB_PATH) and bool(_load_edge_factor_report())
    return {
        "label": cfg.get("current_cohort_label") or "Current cohort",
        "started_at": since,
        "scope": cohort_scope,
        "target_count": target,
        "configured_target_count": configured_target,
        "active_strategies": active_strategies,
        "open_or_pending_count": open_count,
        "decision": decision,
        "decision_label": label,
        "decision_color": color,
        "evidence_ready": evidence_ready,
        "blocking_failures": [
            gate.get("name") for gate in blocking_failures
        ],
        "summary": summary,
        "recommendation": recommendation,
        "gates": gates,
        "cohort": cohort_stats,
        "baseline": baseline_stats,
        "baseline_delta": {
            "avg_pnl": round(avg - baseline_avg, 2),
            "win_partial_rate": round(wp - baseline_wp, 1),
        },
        "strategy_breakdown": _paper_review_breakdown(
            cohort, "strategy_key", starting_balance=starting_balance
        ),
        "direction_breakdown": _paper_review_breakdown(
            cohort, "direction", starting_balance=starting_balance
        ),
        "recent_trades": list(reversed(cohort[-8:])),
        "edge_lab": {
            "available": edge_available,
            "note": "Use the Edge Lab Cohort Attribution card below this review to confirm whether cohort trades are occurring in historically favorable states.",
        },
        "hermes": {
            "source_count": ((research.get("library") or {}).get("source_count") or 0),
            "shadow_experiment_count": research.get("shadow_experiment_count") or 0,
            "latest_research_memo_at": ((research.get("research_memo") or {}).get("generated_at")),
        },
    }


