def _order_flow_recorder_loop():
    """Record recent MEXC tape/depth for active paper-trade symbols only."""
    import time as _time
    _time.sleep(90)
    while True:
        try:
            symbols = _order_flow_active_symbols()
            if not symbols:
                _time.sleep(15)
                continue
            totals = {"trades": 0, "depth": 0}
            for symbol in symbols:
                result = _record_order_flow_symbol(symbol)
                totals["trades"] += int(result.get("trades") or 0)
                totals["depth"] += int(result.get("depth") or 0)
                _time.sleep(0.35)
            print(
                f"[order_flow_recorder] symbols={len(symbols)} trades={totals['trades']} depth={totals['depth']}",
                file=sys.stderr,
            )
        except Exception as e:
            print(f"[order_flow_recorder] loop error: {e}", file=sys.stderr)
        _time.sleep(10)


_order_flow_recorder_thread = threading.Thread(target=_order_flow_recorder_loop, daemon=True)


def _research_scheduler_loop():
    """Passive research due-checker. It only mutates research artifacts when enabled."""
    import time as _time
    _time.sleep(600)
    while True:
        try:
            cfg = _research_scheduler_config()
            if not cfg.get("enabled"):
                _time.sleep(900)
                continue
            if _research_scheduler_due(cfg):
                result = _research_scheduler_run_once(reason="scheduled")
                if result.get("success"):
                    print(
                        f"[research_scheduler] cycle ok sources={result.get('added_sources')} drift={result.get('new_drift_alert_count')}",
                        file=sys.stderr,
                    )
                else:
                    print(f"[research_scheduler] cycle failed: {result.get('error')}", file=sys.stderr)
            _time.sleep(900)
        except Exception as e:
            print(f"[research_scheduler] loop error: {e}", file=sys.stderr)
            _time.sleep(900)


_research_scheduler_thread = threading.Thread(target=_research_scheduler_loop, daemon=True)


# Background threads (_outcome, _snapshot, _cross_venue, _catalysts, _tokenomics, _social,
# _coach_review, _paper_bot, _shadow_forecast, _order_flow_recorder, _research_scheduler)
# are constructed at module level so they're attribute-accessible, but their
# .start() calls now live inside the __main__ guard. Previously they fired at
# import time, which meant any offline script (backtest.py, the reconstruct
# harness, ad-hoc REPL exploration) would silently spawn four background
# workers that hit MEXC and the SQLite DB. CLAUDE.md flags this as a hard rule
# ("Do not import from app.py in a way that triggers Flask server startup");
# the audit (§05) flagged backtest.py's `from app import score_ticker` as a
# concrete violation. Moving .start() under __main__ closes that loophole
# without extracting score_ticker into a separate module.
if __name__ == "__main__":
    _outcome_thread.start()
    _snapshot_thread.start()
    _cross_venue_snapshot_thread.start()
    _catalyst_collection_thread.start()
    _tokenomics_collection_thread.start()
    _social_collection_thread.start()
    _coach_review_thread.start()
    _paper_bot_thread.start()
    _shadow_forecast_thread.start()
    _order_flow_recorder_thread.start()
    _research_scheduler_thread.start()

    try:
        # SOCK_DGRAM connect trick: doesn't send packets, just resolves the
        # outbound interface so we get the real LAN IP rather than 127.0.0.1.
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        lan_ip = s.getsockname()[0]
        s.close()
    except Exception:
        lan_ip = "127.0.0.1"

    print("=" * 50)
    print("  Matrix Trader 7.0")
    print(f"  Local  → http://localhost:{PORT}")
    print(f"  iPhone → http://{lan_ip}:{PORT}")
    print("=" * 50)

    init_db()
    app.run(host="0.0.0.0", port=PORT, debug=False)
